let themePreference = 'dark';
let resolvedTheme = 'dark';
let themeMediaQuery = null;
let appearanceViewModeMediaQuery = null;

// ——— Shared utilities ———
// Canonical helpers shared by every feature area. The per-feature aliases
// (chToday, finRound, paMoney, rtNum, …) delegate here.

function todayLocalDate() {
    return typeof getLocalDateString === 'function' ? getLocalDateString() : new Date().toISOString().slice(0, 10);
}

function toFiniteNumber(value, fallback = 0) {
    const n = typeof value === 'number' ? value : parseFloat(value);
    return Number.isFinite(n) ? n : fallback;
}

function trimToString(value) {
    return String(value ?? '').trim();
}

function lowerKey(value) {
    return trimToString(value).toLowerCase();
}

function roundTo(value, decimals = 2) {
    const factor = Math.pow(10, decimals);
    return Math.round((toFiniteNumber(value, 0) + Number.EPSILON) * factor) / factor;
}

function roundToOrNull(value, decimals = 2) {
    const n = toFiniteNumber(value, NaN);
    if (!Number.isFinite(n)) return null;
    const factor = 10 ** decimals;
    return Math.round(n * factor) / factor;
}

function allSubstancesId() {
    return typeof DASHBOARD_ALL !== 'undefined' ? DASHBOARD_ALL : 'all';
}

function escapeHtmlSafe(value) {
    return typeof escapeHtml === 'function' ? escapeHtml(String(value ?? '')) : String(value ?? '');
}

function meanOrNull(values) {
    const nums = (values || []).map(v => toFiniteNumber(v, NaN)).filter(Number.isFinite);
    if (!nums.length) return null;
    return nums.reduce((sum, n) => sum + n, 0) / nums.length;
}

function medianOfNumbers(numbers) {
    if (!numbers || !numbers.length) return null;
    const sorted = [...numbers].sort((a, b) => a - b);
    const mid = Math.floor(sorted.length / 2);
    return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

function daysBetweenDates(startDate, endDate) {
    const start = typeof parseLocalDate === 'function' ? parseLocalDate(startDate) : null;
    const end = typeof parseLocalDate === 'function' ? parseLocalDate(endDate) : null;
    if (!start || !end) return null;
    return Math.round((end.getTime() - start.getTime()) / 86400000);
}

function formatLongDateLabel(dateStr) {
    const d = typeof parseLocalDate === 'function' ? parseLocalDate(dateStr) : null;
    if (!d) return dateStr || '—';
    return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}

function formatNumberOrDash(value, decimals = 2) {
    if (value == null || !Number.isFinite(toFiniteNumber(value, NaN))) return '—';
    return formatAmount(value, decimals);
}

function formatMoneyOrDash(value, decimals = 2) {
    if (value == null || !Number.isFinite(toFiniteNumber(value, NaN))) return '—';
    const symbol = typeof getCurrencySymbol === 'function' ? getCurrencySymbol() : '$';
    return `${symbol}${formatAmount(toFiniteNumber(value, 0), decimals)}`;
}

function toneClass(prefix, tone) {
    if (tone === 'good') return `${prefix}-tone-good`;
    if (tone === 'warn') return `${prefix}-tone-warn`;
    if (tone === 'bad') return `${prefix}-tone-bad`;
    return `${prefix}-tone-neutral`;
}

function describeElapsedMs(ms) {
    if (ms == null || !Number.isFinite(ms) || ms < 0) return null;
    const minutes = Math.floor(ms / 60000);
    return { minutes, hours: minutes / 60, text: formatBreakText(minutes) };
}

function getSystemTheme() {
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

function resolveTheme(preference = themePreference) {
    if (preference === 'light') return 'light';
    if (preference === 'system') return getSystemTheme();
    return 'dark';
}

function applyResolvedTheme(theme) {
    resolvedTheme = theme;
    document.documentElement.dataset.theme = theme;
    updateThemePreviewUI();
}

function loadThemePreference() {
    try {
        const saved = localStorage.getItem(THEME_PREFERENCE_KEY);
        if (saved === 'dark' || saved === 'light' || saved === 'system') {
            themePreference = saved;
        }
    } catch (_) { /* ignore */ }
    applyResolvedTheme(resolveTheme(themePreference));
}

function onSystemThemeChange() {
    if (themePreference === 'system') {
        applyResolvedTheme(resolveTheme('system'));
    }
}

function setupThemeSystemListener() {
    if (themeMediaQuery) {
        themeMediaQuery.removeEventListener('change', onSystemThemeChange);
        themeMediaQuery = null;
    }
    if (themePreference === 'system') {
        themeMediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
        themeMediaQuery.addEventListener('change', onSystemThemeChange);
    }
}

function updateThemePreviewUI() {
    const select = document.getElementById('theme-preference');
    if (select && select.value !== themePreference) {
        select.value = themePreference;
    }
    const preview = document.getElementById('theme-preview-text');
    const systemNote = document.getElementById('theme-system-note');
    if (!preview) return;

    const resolvedLabel = resolvedTheme.charAt(0).toUpperCase() + resolvedTheme.slice(1);
    if (themePreference === 'system') {
        const prefLabel = 'System';
        preview.textContent = `Current theme: ${prefLabel} → ${resolvedLabel}`;
        if (systemNote) {
            systemNote.textContent = `Using system setting: ${resolvedLabel}`;
            systemNote.classList.remove('hidden');
        }
    } else {
        const prefLabel = themePreference.charAt(0).toUpperCase() + themePreference.slice(1);
        preview.textContent = `Current theme: ${prefLabel}`;
        systemNote?.classList.add('hidden');
    }
}

function setThemePreference(preference) {
    if (preference !== 'dark' && preference !== 'light' && preference !== 'system') return;
    themePreference = preference;
    try {
        localStorage.setItem(THEME_PREFERENCE_KEY, preference);
    } catch (_) { /* ignore */ }
    applyResolvedTheme(resolveTheme(preference));
    setupThemeSystemListener();
}

function initTheme() {
    loadThemePreference();
    setupThemeSystemListener();
    updateThemePreviewUI();
}

function normalizeAppearanceViewMode(value) {
    return APPEARANCE_VIEW_MODES.includes(value) ? value : 'auto';
}

function getAppearanceViewMode(data = appData) {
    return normalizeAppearanceViewMode(data?.settings?.appearanceViewMode);
}

function resolveAppearanceViewLayout(mode = getAppearanceViewMode()) {
    const preference = normalizeAppearanceViewMode(mode);
    if (preference === 'phone') return 'phone';
    if (preference === 'laptop') return 'laptop';
    try {
        if (typeof window !== 'undefined' && window.matchMedia?.(APPEARANCE_VIEW_MODE_LAPTOP_MQ)?.matches) {
            return 'laptop';
        }
    } catch (_) { /* ignore */ }
    return 'phone';
}

function isAppearancePhoneLayout() {
    return document.documentElement?.dataset?.viewLayout !== 'laptop';
}

function isAppearanceLaptopLayout() {
    return document.documentElement?.dataset?.viewLayout === 'laptop';
}

function syncAppearanceViewModeUI(mode = getAppearanceViewMode()) {
    const preference = normalizeAppearanceViewMode(mode);
    const select = document.getElementById('appearance-view-mode');
    if (select && select.value !== preference) select.value = preference;
    document.querySelectorAll('[data-appearance-view-mode]').forEach((btn) => {
        const active = btn.getAttribute('data-appearance-view-mode') === preference;
        btn.classList.toggle('active', active);
        btn.setAttribute('aria-pressed', active ? 'true' : 'false');
    });
}

function applyAppearanceViewMode(mode = getAppearanceViewMode()) {
    const preference = normalizeAppearanceViewMode(mode);
    const layout = resolveAppearanceViewLayout(preference);
    const root = document.documentElement;
    if (root) {
        root.dataset.viewMode = preference;
        root.dataset.viewLayout = layout;
    }
    syncAppearanceViewModeUI(preference);
    return layout;
}

function setupAppearanceViewModeListener() {
    if (appearanceViewModeMediaQuery) {
        appearanceViewModeMediaQuery.removeEventListener('change', onAppearanceViewModeViewportChange);
        appearanceViewModeMediaQuery = null;
    }
    if (getAppearanceViewMode() !== 'auto') return;
    if (typeof window === 'undefined' || !window.matchMedia) return;
    appearanceViewModeMediaQuery = window.matchMedia(APPEARANCE_VIEW_MODE_LAPTOP_MQ);
    appearanceViewModeMediaQuery.addEventListener('change', onAppearanceViewModeViewportChange);
}

function onAppearanceViewModeViewportChange() {
    if (getAppearanceViewMode() !== 'auto') return;
    applyAppearanceViewMode('auto');
}

function setAppearanceViewMode(mode) {
    const preference = normalizeAppearanceViewMode(mode);
    if (!appData.settings) appData.settings = {};
    appData.settings.appearanceViewMode = preference;
    saveData(appData);
    applyAppearanceViewMode(preference);
    setupAppearanceViewModeListener();
    applyAppearanceZoom(getActiveAppearanceZoom());
    if (typeof updateStatsCalendarLayoutForViewMode === 'function') {
        updateStatsCalendarLayoutForViewMode();
    }
}

function initAppearanceViewMode() {
    if (!appData.settings) appData.settings = {};
    appData.settings.appearanceViewMode = getAppearanceViewMode();
    applyAppearanceViewMode(appData.settings.appearanceViewMode);
    setupAppearanceViewModeListener();
}

const APPEARANCE_ZOOM_PRESETS = Object.freeze([90, 100, 110, 125, 150]);
const APPEARANCE_ZOOM_MIN = 75;
const APPEARANCE_ZOOM_MAX = 200;
const APPEARANCE_ZOOM_STEP = 5;
const APPEARANCE_ZOOM_DEFAULT = 100;

function normalizeAppearanceZoom(value) {
    const n = typeof value === 'string' && value.endsWith('%')
        ? parseFloat(value)
        : parseFloat(value);
    if (!Number.isFinite(n)) return APPEARANCE_ZOOM_DEFAULT;
    const rounded = Math.round(n);
    return Math.min(APPEARANCE_ZOOM_MAX, Math.max(APPEARANCE_ZOOM_MIN, rounded));
}

function snapAppearanceZoom(value, step = APPEARANCE_ZOOM_STEP) {
    const n = normalizeAppearanceZoom(value);
    const snapped = Math.round(n / step) * step;
    return normalizeAppearanceZoom(snapped);
}

function getAppearanceZoom(data = appData) {
    return normalizeAppearanceZoom(data?.settings?.appearanceZoom);
}

function getPhoneViewZoom(data = appData) {
    const raw = data?.settings?.phoneViewZoom;
    return raw == null || raw === '' ? getAppearanceZoom(data) : normalizeAppearanceZoom(raw);
}

function getLaptopViewZoom(data = appData) {
    const raw = data?.settings?.laptopViewZoom;
    return raw == null || raw === '' ? getAppearanceZoom(data) : normalizeAppearanceZoom(raw);
}

function getActiveAppearanceZoom(data = appData) {
    const layout = resolveAppearanceViewLayout(getAppearanceViewMode(data));
    if (layout === 'laptop') return getLaptopViewZoom(data);
    return getPhoneViewZoom(data);
}

function isAppearanceZoomPreset(percent) {
    return APPEARANCE_ZOOM_PRESETS.includes(normalizeAppearanceZoom(percent));
}

function applyAppearanceZoom(percent = getActiveAppearanceZoom()) {
    const zoom = normalizeAppearanceZoom(percent);
    const scale = zoom / 100;
    const root = document.documentElement;
    if (root) {
        if (root.style?.setProperty) {
            root.style.setProperty('--app-zoom', String(scale));
            root.style.setProperty('--app-zoom-percent', `${zoom}`);
        }
        if (root.dataset) root.dataset.appZoom = String(zoom);
    }
    syncAppearanceZoomUI(zoom);
    updateAppearanceZoomLayoutMetrics();
    return zoom;
}

function updateAppearanceZoomLayoutMetrics() {
    const root = document.documentElement;
    const nav = document.querySelector('.bottom-nav');
    if (!root?.style?.setProperty) return;
    const zoom = normalizeAppearanceZoom(root.dataset?.appZoom || getActiveAppearanceZoom());
    const scale = zoom / 100;
    let navHeight = 110;
    if (nav) {
        const layoutHeight = nav.offsetHeight || 0;
        const visualHeight = nav.getBoundingClientRect?.().height || 0;
        if (layoutHeight > 0) navHeight = layoutHeight;
        else if (visualHeight > 0 && scale > 0) navHeight = visualHeight / scale;
    }
    root.style.setProperty(
        '--bottom-nav-clearance',
        `calc(${Math.ceil(navHeight)}px + env(safe-area-inset-bottom, 0px))`
    );
    root.style.setProperty('--tap-target-min', `calc(44px / var(--app-zoom))`);
}

function syncAppearanceZoomUI(percent = getActiveAppearanceZoom()) {
    const zoom = normalizeAppearanceZoom(percent);
    const isPreset = isAppearanceZoomPreset(zoom);
    const select = document.getElementById('appearance-zoom-preset');
    if (select) {
        select.value = isPreset ? String(zoom) : 'custom';
    }
    document.querySelectorAll('[data-appearance-zoom]').forEach((btn) => {
        const value = btn.getAttribute('data-appearance-zoom');
        const active = value === 'custom' ? !isPreset : String(zoom) === value;
        btn.classList.toggle('active', active);
        btn.setAttribute('aria-pressed', active ? 'true' : 'false');
    });
    const label = document.getElementById('appearance-zoom-value');
    if (label) label.textContent = `${zoom}%`;
    const slider = document.getElementById('appearance-zoom-slider');
    if (slider) {
        if (String(slider.value) !== String(zoom)) slider.value = String(zoom);
        slider.setAttribute('aria-valuenow', String(zoom));
    }
    const customInput = document.getElementById('appearance-zoom-custom');
    const customRow = document.getElementById('appearance-zoom-custom-row');
    if (customRow) customRow.classList.toggle('hidden', isPreset && select?.value !== 'custom');
    if (customInput && document.activeElement !== customInput) {
        customInput.value = String(zoom);
    }
    const live = document.getElementById('appearance-zoom-live');
    if (live) live.textContent = `App zoom ${zoom} percent`;
}

function persistAppearanceZoomSettings(zoom, data = appData) {
    if (!data.settings) data.settings = {};
    const z = normalizeAppearanceZoom(zoom);
    data.settings.appearanceZoom = z;
    const layout = resolveAppearanceViewLayout(getAppearanceViewMode(data));
    if (layout === 'laptop') data.settings.laptopViewZoom = z;
    else data.settings.phoneViewZoom = z;
    return z;
}

function setAppearanceZoom(percent, options = {}) {
    const zoom = normalizeAppearanceZoom(percent);
    persistAppearanceZoomSettings(zoom);
    if (options.persist !== false) saveData(appData);
    applyAppearanceZoom(zoom);
    return zoom;
}

function adjustAppearanceZoom(delta) {
    const current = getActiveAppearanceZoom();
    const next = snapAppearanceZoom(current + (parseFloat(delta) || 0));
    return setAppearanceZoom(next);
}

function stepAppearanceZoom(direction) {
    const dir = direction < 0 ? -1 : 1;
    return adjustAppearanceZoom(dir * APPEARANCE_ZOOM_STEP);
}

function onAppearanceZoomPresetChange(value) {
    if (value === 'custom') {
        document.getElementById('appearance-zoom-custom-row')?.classList.remove('hidden');
        document.getElementById('appearance-zoom-custom')?.focus();
        syncAppearanceZoomUI(getActiveAppearanceZoom());
        return;
    }
    setAppearanceZoom(value);
}

function onAppearanceZoomCustomInput(value) {
    const zoom = normalizeAppearanceZoom(value);
    setAppearanceZoom(zoom);
}

function resetAppearanceZoom() {
    return setAppearanceZoom(APPEARANCE_ZOOM_DEFAULT);
}

function normalizeAppearanceSpacing(value) {
    return value === 'compact' || value === 'comfortable' ? value : 'default';
}

function getAppearanceSpacing(data = appData) {
    return normalizeAppearanceSpacing(data?.settings?.appearanceSpacing);
}

function applyAppearanceSpacing(spacing = getAppearanceSpacing()) {
    const value = normalizeAppearanceSpacing(spacing);
    const scale = value === 'compact' ? 0.92 : (value === 'comfortable' ? 1.08 : 1);
    const root = document.documentElement;
    if (root) {
        if (root.style?.setProperty) root.style.setProperty('--app-spacing-scale', String(scale));
        if (root.dataset) root.dataset.appearanceSpacing = value;
    }
    const select = document.getElementById('appearance-spacing');
    if (select && select.value !== value) select.value = value;
    return value;
}

function setAppearanceSpacing(spacing) {
    if (!appData.settings) appData.settings = {};
    appData.settings.appearanceSpacing = normalizeAppearanceSpacing(spacing);
    saveData(appData);
    applyAppearanceSpacing(appData.settings.appearanceSpacing);
}

// ——— In-cell / card metric progress bars ———
// Shared progress presentation for tables and dashboard cards. Uses normalized
// current/target values from callers — never recalculates metric math here.

function normalizeMetricProgress({ current, target, percent } = {}) {
    const cur = current == null || current === '' ? null : Number(current);
    const tgt = target == null || target === '' ? null : Number(target);
    let pct = percent == null || percent === '' ? null : Number(percent);

    const validCurrent = cur != null && Number.isFinite(cur);
    const validTargetPositive = tgt != null && Number.isFinite(tgt) && tgt > 0;
    const validTargetFinite = tgt != null && Number.isFinite(tgt);
    const validPercent = pct != null && Number.isFinite(pct);

    if (!validPercent && validCurrent && validTargetPositive) {
        pct = (cur / tgt) * 100;
    }
    // Never invent a percentage when the target is zero or missing.
    if (validTargetFinite && !(tgt > 0)) {
        pct = null;
    }

    const scaleMax = (validCurrent && validTargetPositive)
        ? Math.max(Math.abs(cur), Math.abs(tgt), 0)
        : (validTargetPositive ? Math.abs(tgt) : (validCurrent ? Math.abs(cur) : 0));

    let targetMarkerPercent = null;
    if (validTargetPositive && scaleMax > 0) {
        targetMarkerPercent = Math.max(0, Math.min(100, (Math.abs(tgt) / scaleMax) * 100));
    }

    if (pct == null || !Number.isFinite(pct)) {
        return {
            current: validCurrent ? cur : null,
            target: validTargetFinite ? tgt : null,
            percent: null,
            visualPercent: 0,
            fillPercent: 0,
            targetMarkerPercent,
            scaleMax: scaleMax || null,
            ratio: null,
            valid: false,
            exceedsTarget: false
        };
    }

    const exceedsTarget = pct > 100;
    // When over target, expand the track to current so the target marker sits inside the range.
    let fillPercent;
    if (validCurrent && validTargetPositive && exceedsTarget && scaleMax > 0) {
        fillPercent = Math.max(0, Math.min(100, (Math.abs(cur) / scaleMax) * 100));
    } else {
        fillPercent = Math.max(0, Math.min(100, pct));
    }
    const visualPercent = Math.max(0, Math.min(100, pct));

    return {
        current: validCurrent ? cur : null,
        target: validTargetFinite ? tgt : null,
        percent: pct,
        visualPercent,
        fillPercent,
        targetMarkerPercent,
        scaleMax: scaleMax || null,
        ratio: pct / 100,
        valid: true,
        exceedsTarget
    };
}

const TARGET_LINE_COLOR_SCOPES = Object.freeze([
    { id: 'entire', label: 'Entire card or row' },
    { id: 'current', label: 'Current value' },
    { id: 'difference', label: 'Difference only' },
    { id: 'percentage', label: 'Percentage only' },
    { id: 'targetMarker', label: 'Target marker only' }
]);

const TARGET_LINE_METRIC_DIRECTIONS = Object.freeze({
    use: 'lowerIsBetter',
    taper: 'lowerIsBetter',
    spend: 'lowerIsBetter',
    purchaseCount: 'lowerIsBetter',
    nicotineStrength: 'lowerIsBetter',
    streak: 'higherIsBetter',
    noUseDays: 'higherIsBetter',
    vapeLifespan: 'higherIsBetter',
    nicotineFreeHours: 'higherIsBetter',
    daysBetweenPurchases: 'higherIsBetter',
    inventory: 'neutral',
    gift: 'neutral',
    adjustment: 'neutral'
});

const TARGET_LINE_DEFAULT_COLORS = Object.freeze({
    favorable: { background: 'rgba(76, 175, 80, 0.18)', text: '#2e7d32', border: '#4caf50', fill: '#4caf50' },
    near: { background: 'rgba(255, 183, 77, 0.18)', text: '#ef6c00', border: '#ffb74d', fill: '#ffb74d' },
    unfavorable: { background: 'rgba(239, 83, 80, 0.16)', text: '#c62828', border: '#ef5350', fill: '#ef5350' },
    neutral: { background: '', text: '', border: '', fill: '' }
});

function getDefaultTargetLinePrefs() {
    return {
        enabled: true,
        colorScope: 'difference'
    };
}

function normalizeTargetLineColorScope(scope) {
    const id = String(scope || '').trim();
    return TARGET_LINE_COLOR_SCOPES.some(s => s.id === id) ? id : 'difference';
}

function normalizeTargetLineDirection(directionOrMetricKind) {
    if (directionOrMetricKind === 'lowerIsBetter'
        || directionOrMetricKind === 'higherIsBetter'
        || directionOrMetricKind === 'neutral') {
        return directionOrMetricKind;
    }
    return TARGET_LINE_METRIC_DIRECTIONS[directionOrMetricKind] || 'lowerIsBetter';
}

function ensureTargetLinePrefs(data = appData) {
    if (!data.settings) data.settings = {};
    const defaults = getDefaultTargetLinePrefs();
    const raw = data.settings.targetLinePrefs && typeof data.settings.targetLinePrefs === 'object'
        ? data.settings.targetLinePrefs
        : {};
    data.settings.targetLinePrefs = {
        enabled: raw.enabled === undefined
            ? (data.settings.showTargetLines === undefined ? defaults.enabled : !!data.settings.showTargetLines)
            : !!raw.enabled,
        colorScope: normalizeTargetLineColorScope(raw.colorScope ?? data.settings.targetLineColorScope)
    };
    data.settings.showTargetLines = data.settings.targetLinePrefs.enabled;
    data.settings.targetLineColorScope = data.settings.targetLinePrefs.colorScope;
    return data.settings.targetLinePrefs;
}

function getTargetLinePrefs(data = appData) {
    return ensureTargetLinePrefs(data);
}

function isTargetLinesEnabled(data = appData) {
    return getTargetLinePrefs(data).enabled !== false;
}

function getTargetLineColorScope(data = appData) {
    return getTargetLinePrefs(data).colorScope;
}

function setTargetLinesEnabled(enabled, data = appData) {
    const prefs = ensureTargetLinePrefs(data);
    prefs.enabled = !!enabled;
    data.settings.showTargetLines = prefs.enabled;
    if (typeof saveData === 'function') saveData(data);
    syncTargetLineSettingsUI(data);
    refreshMetricProgressDisplays();
    return prefs.enabled;
}

function setTargetLineColorScope(scope, data = appData) {
    const prefs = ensureTargetLinePrefs(data);
    prefs.colorScope = normalizeTargetLineColorScope(scope);
    data.settings.targetLineColorScope = prefs.colorScope;
    if (typeof saveData === 'function') saveData(data);
    syncTargetLineSettingsUI(data);
    refreshMetricProgressDisplays();
    return prefs.colorScope;
}

function syncTargetLineSettingsUI(data = appData) {
    const prefs = getTargetLinePrefs(data);
    const toggle = document.getElementById('appearance-show-target-lines');
    if (toggle) toggle.checked = prefs.enabled !== false;
    const scope = document.getElementById('appearance-target-line-color-scope');
    if (scope) scope.value = prefs.colorScope;
}

function refreshMetricProgressDisplays() {
    try {
        if (typeof renderPurchaseHistory === 'function') renderPurchaseHistory();
        if (typeof renderTaperWeeklyTable === 'function' && typeof currentSubstanceId !== 'undefined') {
            renderTaperWeeklyTable(currentSubstanceId);
        }
        if (typeof renderRecoveryDashboard === 'function') renderRecoveryDashboard();
        if (typeof updateDashboard === 'function') updateDashboard();
        if (typeof renderFinancialAnalyticsView === 'function') renderFinancialAnalyticsView();
    } catch (_) { /* ignore refresh errors */ }
}

function formatMetricTargetLineValue(value, unit = '') {
    if (value == null || value === '' || !Number.isFinite(Number(value))) return '—';
    const n = Number(value);
    const amt = typeof formatAmount === 'function' ? formatAmount(n) : String(n);
    const u = unit == null ? '' : String(unit).trim();
    return u ? `${amt} ${u}` : amt;
}

function formatMetricTargetLineDifference(diff, unit = '') {
    if (diff == null || !Number.isFinite(Number(diff))) return '—';
    const n = Number(diff);
    const u = unit == null ? '' : String(unit).trim();
    const absAmt = typeof formatAmount === 'function' ? formatAmount(Math.abs(n)) : String(Math.abs(n));
    const withUnit = u ? `${absAmt} ${u}` : absAmt;
    if (Math.abs(n) < 1e-9) return withUnit;
    return `${n > 0 ? '+' : '−'}${withUnit}`;
}

/**
 * Shared target-line model from already-normalized current/target values.
 * Callers must not recalculate metric math inside table/card renderers.
 */
function buildMetricTargetLine({
    current,
    target,
    percent,
    direction,
    metricKind,
    unit = '',
    currentLabel = null,
    targetLabel = null,
    nearBandPct = 10
} = {}) {
    const dir = normalizeTargetLineDirection(direction || metricKind || 'lowerIsBetter');
    const progress = normalizeMetricProgress({ current, target, percent });
    const cur = progress.current;
    const tgt = progress.target;
    const hasCurrent = cur != null && Number.isFinite(cur);
    const hasTarget = tgt != null && Number.isFinite(tgt);
    const difference = (hasCurrent && hasTarget) ? (cur - tgt) : null;
    const pct = (hasTarget && tgt > 0 && progress.percent != null && Number.isFinite(progress.percent))
        ? progress.percent
        : null;

    let tone = 'neutral';
    if (!hasCurrent || !hasTarget) {
        tone = 'missing';
    } else if (dir === 'neutral') {
        tone = 'neutral';
    } else if (!(tgt > 0) && pct == null) {
        tone = 'neutral';
    } else {
        const band = Number.isFinite(Number(nearBandPct)) ? Math.max(0, Number(nearBandPct)) : 10;
        const absPctDelta = pct != null ? Math.abs(pct - 100) : null;
        const onTarget = difference != null && Math.abs(difference) < 1e-9;
        if (onTarget) {
            tone = 'favorable';
        } else if (dir === 'lowerIsBetter') {
            if (cur < tgt) tone = 'favorable';
            else if (absPctDelta != null && absPctDelta <= band) tone = 'near';
            else tone = 'unfavorable';
        } else {
            // higherIsBetter
            if (cur > tgt) tone = 'favorable';
            else if (absPctDelta != null && absPctDelta <= band) tone = 'near';
            else tone = 'unfavorable';
        }
    }

    const curDisplay = currentLabel != null && currentLabel !== ''
        ? String(currentLabel)
        : formatMetricTargetLineValue(cur, unit);
    const tgtDisplay = targetLabel != null && targetLabel !== ''
        ? String(targetLabel)
        : formatMetricTargetLineValue(tgt, unit);

    return {
        current: hasCurrent ? cur : null,
        target: hasTarget ? tgt : null,
        difference,
        percent: pct,
        direction: dir,
        tone,
        unit: unit || '',
        currentDisplay: hasCurrent ? curDisplay : '—',
        targetDisplay: hasTarget ? tgtDisplay : '—',
        differenceDisplay: formatMetricTargetLineDifference(difference, unit),
        percentDisplay: pct == null ? '—' : `${Math.round(pct * 10) / 10}% of target`,
        progress,
        valid: hasCurrent || hasTarget
    };
}

function getTargetLineDefaultColorSet(tone) {
    return TARGET_LINE_DEFAULT_COLORS[tone] || TARGET_LINE_DEFAULT_COLORS.neutral;
}

/**
 * Resolve colors for a target line. Custom CCR styles always override defaults.
 */
function resolveMetricTargetLineColors(targetLine, ccrResult = null, colorScope = null, data = appData) {
    const scope = normalizeTargetLineColorScope(colorScope || getTargetLineColorScope(data));
    const defaults = getTargetLineDefaultColorSet(targetLine?.tone);
    const hasCcr = !!(ccrResult?.matched?.length && ccrResult.style);
    const ccr = hasCcr ? {
        background: ccrResult.style.background || '',
        text: ccrResult.style.text || '',
        border: ccrResult.style.border || '',
        fill: ccrResult.style.background || ccrResult.style.border || ccrResult.style.text || ''
    } : null;
    const active = ccr || defaults;
    return {
        scope,
        hasCustomRule: hasCcr,
        tone: targetLine?.tone || 'neutral',
        entire: scope === 'entire' ? active : null,
        current: scope === 'current' ? active : null,
        difference: scope === 'difference' ? active : null,
        percentage: scope === 'percentage' ? active : null,
        targetMarker: scope === 'targetMarker' ? active : null,
        fill: (scope === 'entire' || scope === 'targetMarker') ? (active.fill || active.border || '') : '',
        active
    };
}

function buildTargetLinePartStyle(colorSet) {
    if (!colorSet) return '';
    return [
        colorSet.background ? `background:${colorSet.background}` : '',
        colorSet.text ? `color:${colorSet.text}` : '',
        colorSet.border ? `border-color:${colorSet.border}` : ''
    ].filter(Boolean).join(';');
}

function renderMetricTargetLine(targetLine, {
    ccrResult = null,
    colorScope = null,
    data = appData,
    showBar = true,
    compact = false
} = {}) {
    if (!targetLine || !isTargetLinesEnabled(data)) return '';
    const colors = resolveMetricTargetLineColors(targetLine, ccrResult, colorScope, data);
    const wrapStyle = buildTargetLinePartStyle(colors.entire);
    const currentStyle = buildTargetLinePartStyle(colors.current);
    const diffStyle = buildTargetLinePartStyle(colors.difference);
    const pctStyle = buildTargetLinePartStyle(colors.percentage);
    const progress = targetLine.progress || normalizeMetricProgress(targetLine);
    const barHtml = showBar && isInCellProgressBarsEnabled(data) && progress?.valid
        ? renderMetricProgressBar(progress, {
            ccrResult,
            showPercent: false,
            targetLineColors: colors,
            data
        })
        : '';
    const compactClass = compact ? ' metric-target-line--compact' : '';
    return `<div class="metric-target-line${compactClass} metric-tl-tone-${escapeAttr(targetLine.tone || 'neutral')}${colors.hasCustomRule ? ' ccr-applied' : ''}" data-color-scope="${escapeAttr(colors.scope)}"${wrapStyle ? ` style="${escapeAttr(wrapStyle)}"` : ''}>
        <div class="metric-tl-row metric-tl-current"${currentStyle ? ` style="${escapeAttr(currentStyle)}"` : ''}><span class="metric-tl-label">Current:</span> <span class="metric-tl-value">${escapeHtml(targetLine.currentDisplay)}</span></div>
        <div class="metric-tl-row metric-tl-target"><span class="metric-tl-label">Target:</span> <span class="metric-tl-value">${escapeHtml(targetLine.targetDisplay)}</span></div>
        <div class="metric-tl-row metric-tl-diff"${diffStyle ? ` style="${escapeAttr(diffStyle)}"` : ''}><span class="metric-tl-label">Difference:</span> <span class="metric-tl-value">${escapeHtml(targetLine.differenceDisplay)}</span></div>
        <div class="metric-tl-row metric-tl-pct"${pctStyle ? ` style="${escapeAttr(pctStyle)}"` : ''}><span class="metric-tl-value">${escapeHtml(targetLine.percentDisplay)}</span></div>
        ${barHtml}
    </div>`;
}

function isInCellProgressBarsEnabled(data = appData) {
    return data?.settings?.showInCellProgressBars !== false;
}

function setInCellProgressBarsEnabled(enabled, data = appData) {
    if (!data.settings) data.settings = {};
    data.settings.showInCellProgressBars = !!enabled;
    if (typeof saveData === 'function') saveData(data);
    const el = document.getElementById('appearance-show-progress-bars');
    if (el) el.checked = !!enabled;
    refreshMetricProgressDisplays();
    return !!enabled;
}

function syncInCellProgressBarsToggle() {
    const el = document.getElementById('appearance-show-progress-bars');
    if (el) el.checked = isInCellProgressBarsEnabled();
    syncTargetLineSettingsUI();
}

function getMetricProgressFillStyle(ccrResult, targetLineColors = null) {
    if (ccrResult?.matched?.length && ccrResult.style) {
        const fill = ccrResult.style.background || ccrResult.style.border || ccrResult.style.text;
        if (fill) return `background:${fill}`;
    }
    if (targetLineColors?.fill) return `background:${targetLineColors.fill}`;
    if (targetLineColors?.active?.fill) return `background:${targetLineColors.active.fill}`;
    return '';
}

function renderMetricProgressBar(progress, {
    ccrResult = null,
    showPercent = true,
    targetLineColors = null,
    data = appData
} = {}) {
    if (!progress?.valid) return '';
    const colors = targetLineColors || null;
    const fillStyle = getMetricProgressFillStyle(ccrResult, colors);
    const fillWidth = Math.round((progress.fillPercent ?? progress.visualPercent) * 10) / 10;
    const visual = Math.round(progress.visualPercent * 10) / 10;
    const truePct = Math.round(progress.percent * 10) / 10;
    const marker = progress.targetMarkerPercent;
    const showMarker = marker != null && Number.isFinite(marker) && marker >= 0 && marker <= 100;
    const markerStyleParts = [`left:${Math.round(marker * 10) / 10}%`];
    if (colors?.targetMarker?.fill || colors?.targetMarker?.border || colors?.targetMarker?.text) {
        const mFill = colors.targetMarker.fill || colors.targetMarker.border || colors.targetMarker.text;
        markerStyleParts.push(`background:${mFill}`);
    } else if (colors?.scope === 'targetMarker' && colors?.active?.fill) {
        markerStyleParts.push(`background:${colors.active.fill}`);
    }
    const pctLabel = showPercent
        ? `<span class="metric-progress-pct">${escapeHtml(String(truePct))}%</span>`
        : '';
    const markerHtml = showMarker
        ? `<span class="metric-progress-target-marker" title="Target" aria-hidden="true" style="${escapeAttr(markerStyleParts.join(';'))}"></span>`
        : '';
    return `<div class="metric-progress-track-row">
        <div class="metric-progress-track rd-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${escapeAttr(String(visual))}"${progress.exceedsTarget ? ' data-exceeds-target="true"' : ''}${showMarker ? ` data-has-target-marker="true"` : ''}>
            <div class="metric-progress-fill rd-progress-fill"${fillStyle ? ` style="${escapeAttr(fillStyle)};width:${fillWidth}%"` : ` style="width:${fillWidth}%"`}></div>
            ${markerHtml}
        </div>
        ${pctLabel}
    </div>`;
}

/**
 * Shared cell/card renderer: keeps value visible, optional target line + progress bar.
 * Callers pass already-normalized current/target/percent — no per-table math here.
 */
function renderMetricProgressCell(valueHtml, options = {}) {
    const data = options.data || appData;
    const progress = normalizeMetricProgress(options);
    const targetLinesOn = isTargetLinesEnabled(data);
    const barsOn = isInCellProgressBarsEnabled(data);

    if (targetLinesOn && (options.current != null || options.target != null || options.currentLabel || options.targetLabel)) {
        const tl = buildMetricTargetLine({
            current: options.current,
            target: options.target,
            percent: options.percent,
            direction: options.direction,
            metricKind: options.metricKind,
            unit: options.unit || '',
            currentLabel: options.currentLabel,
            targetLabel: options.targetLabel,
            nearBandPct: options.nearBandPct
        });
        if (tl.valid) {
            return renderMetricTargetLine(tl, {
                ccrResult: options.ccrResult || null,
                colorScope: options.colorScope,
                data,
                showBar: barsOn && options.showBar !== false,
                compact: options.compact === true
            });
        }
    }

    if (!barsOn) return valueHtml;
    if (!progress.valid) return valueHtml;
    const defaultColors = (!options.ccrResult?.matched?.length && options.metricKind)
        ? resolveMetricTargetLineColors(
            buildMetricTargetLine({
                current: options.current,
                target: options.target,
                percent: options.percent,
                direction: options.direction,
                metricKind: options.metricKind
            }),
            null,
            options.colorScope,
            data
        )
        : null;
    const bar = renderMetricProgressBar(progress, {
        ccrResult: options.ccrResult || null,
        showPercent: options.showPercent !== false,
        targetLineColors: defaultColors,
        data
    });
    if (!bar) return valueHtml;
    const ccrClass = options.ccrResult?.matched?.length ? ' ccr-applied' : '';
    const wrapStyle = options.ccrResult?.matched?.length
        ? buildConditionalColorInlineStyle(options.ccrResult)
        : '';
    return `<div class="metric-progress-cell${ccrClass}"${wrapStyle ? ` style="${escapeAttr(wrapStyle)}"` : ''}>
        <div class="metric-progress-value">${valueHtml}</div>
        ${bar}
    </div>`;
}

function formatMetricProgressPair(currentLabel, targetLabel) {
    const cur = currentLabel == null || currentLabel === '' ? '—' : String(currentLabel);
    const tgt = targetLabel == null || targetLabel === '' ? '—' : String(targetLabel);
    return `${cur} / ${tgt}`;
}

function resetAppearanceSettings() {
    if (!appData.settings) appData.settings = {};
    appData.settings.appearanceViewMode = 'auto';
    appData.settings.appearanceZoom = APPEARANCE_ZOOM_DEFAULT;
    appData.settings.phoneViewZoom = APPEARANCE_ZOOM_DEFAULT;
    appData.settings.laptopViewZoom = APPEARANCE_ZOOM_DEFAULT;
    appData.settings.appearanceSpacing = 'default';
    // Keep progress-bar / target-line preferences; only reset layout/spacing/zoom/view.
    saveData(appData);
    applyAppearanceViewMode('auto');
    setupAppearanceViewModeListener();
    applyAppearanceZoom(APPEARANCE_ZOOM_DEFAULT);
    applyAppearanceSpacing('default');
    syncInCellProgressBarsToggle();
    syncTargetLineSettingsUI();
    if (typeof syncPreviousPeriodCompareSettingsUI === 'function') syncPreviousPeriodCompareSettingsUI();
    if (typeof updateStatsCalendarLayoutForViewMode === 'function') {
        updateStatsCalendarLayoutForViewMode();
    }
}

// ——— Previous-period comparisons ———
// Shared current-vs-previous presentation for dashboard, Insights, spending, and taper.
// Uses normalized metric values from callers — no per-surface recalculation of amounts.

const PREVIOUS_PERIOD_COMPARE_MODES = Object.freeze([
    { id: 'previous-day', label: 'Previous day' },
    { id: 'previous-week', label: 'Previous week' },
    { id: 'previous-month', label: 'Previous month' },
    { id: 'previous-selected-range', label: 'Previous selected date range' },
    { id: 'same-period-last-month', label: 'Same period last month' },
    { id: 'same-period-last-year', label: 'Same period last year' }
]);

const PREVIOUS_PERIOD_COLOR_SCOPES = Object.freeze([
    { id: 'previous', label: 'Previous value' },
    { id: 'numericChange', label: 'Numeric change' },
    { id: 'percentageChange', label: 'Percentage change' },
    { id: 'direction', label: 'Increase/decrease direction' }
]);

const PERIOD_COMPARE_DEFAULT_COLORS = Object.freeze({
    favorable: { background: 'rgba(76, 175, 80, 0.18)', text: '#2e7d32', border: '#4caf50', fill: '#4caf50' },
    unfavorable: { background: 'rgba(239, 83, 80, 0.16)', text: '#c62828', border: '#ef5350', fill: '#ef5350' },
    neutral: { background: '', text: '', border: '', fill: '' },
    missing: { background: '', text: '', border: '', fill: '' }
});

function getDefaultPreviousPeriodComparePrefs() {
    return {
        enabled: true,
        mode: 'previous-week',
        colorScope: 'numericChange'
    };
}

function normalizePreviousPeriodCompareMode(mode) {
    const id = String(mode || '').trim();
    return PREVIOUS_PERIOD_COMPARE_MODES.some(m => m.id === id) ? id : 'previous-week';
}

function normalizePreviousPeriodColorScope(scope) {
    const id = String(scope || '').trim();
    return PREVIOUS_PERIOD_COLOR_SCOPES.some(s => s.id === id) ? id : 'numericChange';
}

function ensurePreviousPeriodComparePrefs(data = appData) {
    if (!data.settings) data.settings = {};
    const defaults = getDefaultPreviousPeriodComparePrefs();
    const raw = data.settings.previousPeriodComparePrefs
        && typeof data.settings.previousPeriodComparePrefs === 'object'
        ? data.settings.previousPeriodComparePrefs
        : {};
    data.settings.previousPeriodComparePrefs = {
        enabled: raw.enabled === undefined
            ? (data.settings.showPreviousPeriodCompare === undefined
                ? defaults.enabled
                : !!data.settings.showPreviousPeriodCompare)
            : !!raw.enabled,
        mode: normalizePreviousPeriodCompareMode(
            raw.mode ?? data.settings.previousPeriodCompareMode ?? defaults.mode
        ),
        colorScope: normalizePreviousPeriodColorScope(
            raw.colorScope ?? data.settings.previousPeriodCompareColorScope ?? defaults.colorScope
        )
    };
    data.settings.showPreviousPeriodCompare = data.settings.previousPeriodComparePrefs.enabled;
    data.settings.previousPeriodCompareMode = data.settings.previousPeriodComparePrefs.mode;
    data.settings.previousPeriodCompareColorScope = data.settings.previousPeriodComparePrefs.colorScope;
    return data.settings.previousPeriodComparePrefs;
}

function getPreviousPeriodComparePrefs(data = appData) {
    return ensurePreviousPeriodComparePrefs(data);
}

function isPreviousPeriodCompareEnabled(data = appData) {
    return getPreviousPeriodComparePrefs(data).enabled !== false;
}

function getPreviousPeriodCompareMode(data = appData) {
    return getPreviousPeriodComparePrefs(data).mode;
}

function getPreviousPeriodCompareColorScope(data = appData) {
    return getPreviousPeriodComparePrefs(data).colorScope;
}

function setPreviousPeriodCompareEnabled(enabled, data = appData) {
    const prefs = ensurePreviousPeriodComparePrefs(data);
    prefs.enabled = !!enabled;
    data.settings.showPreviousPeriodCompare = prefs.enabled;
    if (typeof saveData === 'function') saveData(data);
    syncPreviousPeriodCompareSettingsUI(data);
    refreshPreviousPeriodCompareDisplays();
    return prefs.enabled;
}

function setPreviousPeriodCompareMode(mode, data = appData) {
    const prefs = ensurePreviousPeriodComparePrefs(data);
    prefs.mode = normalizePreviousPeriodCompareMode(mode);
    data.settings.previousPeriodCompareMode = prefs.mode;
    if (typeof saveData === 'function') saveData(data);
    syncPreviousPeriodCompareSettingsUI(data);
    refreshPreviousPeriodCompareDisplays();
    return prefs.mode;
}

function setPreviousPeriodCompareColorScope(scope, data = appData) {
    const prefs = ensurePreviousPeriodComparePrefs(data);
    prefs.colorScope = normalizePreviousPeriodColorScope(scope);
    data.settings.previousPeriodCompareColorScope = prefs.colorScope;
    if (typeof saveData === 'function') saveData(data);
    syncPreviousPeriodCompareSettingsUI(data);
    refreshPreviousPeriodCompareDisplays();
    return prefs.colorScope;
}

function syncPreviousPeriodCompareSettingsUI(data = appData) {
    const prefs = getPreviousPeriodComparePrefs(data);
    const toggle = document.getElementById('appearance-show-previous-period-compare');
    if (toggle) toggle.checked = prefs.enabled !== false;
    const mode = document.getElementById('appearance-previous-period-mode');
    if (mode) mode.value = prefs.mode;
    const scope = document.getElementById('appearance-previous-period-color-scope');
    if (scope) scope.value = prefs.colorScope;
}

function refreshPreviousPeriodCompareDisplays() {
    try {
        if (typeof renderRecoveryDashboard === 'function') renderRecoveryDashboard();
        if (typeof updateDashboard === 'function') updateDashboard();
        if (typeof renderStats === 'function') renderStats();
        else if (typeof refreshInsightsView === 'function') refreshInsightsView();
        if (typeof renderTaperCurrentWeekSummary === 'function' && typeof currentSubstanceId !== 'undefined') {
            renderTaperCurrentWeekSummary(currentSubstanceId);
        }
        if (typeof renderFinancialAnalyticsView === 'function') renderFinancialAnalyticsView();
    } catch (_) { /* ignore */ }
}

/**
 * Resolve previous bounds from a current range + comparison mode.
 * Custom / selected-range modes use an equal-length immediately preceding window.
 */
function resolvePreviousPeriodBounds(currentBounds, mode = 'previous-selected-range') {
    const startDate = currentBounds?.startDate;
    const endDate = currentBounds?.endDate;
    if (!startDate || !endDate) {
        return { startDate: null, endDate: null, label: 'Previous period', valid: false };
    }
    const key = normalizePreviousPeriodCompareMode(mode);
    const days = typeof countDaysInRange === 'function'
        ? countDaysInRange(startDate, endDate)
        : 1;

    if (key === 'previous-day') {
        return {
            startDate: addDaysYYYYMMDD(startDate, -1),
            endDate: addDaysYYYYMMDD(endDate, -1),
            label: 'Previous day',
            valid: true,
            mode: key
        };
    }
    if (key === 'previous-week') {
        return {
            startDate: addDaysYYYYMMDD(startDate, -7),
            endDate: addDaysYYYYMMDD(endDate, -7),
            label: 'Previous week',
            valid: true,
            mode: key
        };
    }
    if (key === 'previous-month') {
        const anchor = addDaysYYYYMMDD(getMonthStartDateStr(endDate), -1);
        return {
            startDate: getMonthStartDateStr(anchor),
            endDate: getMonthEndDateStr(anchor),
            label: 'Previous month',
            valid: true,
            mode: key
        };
    }
    if (key === 'same-period-last-month') {
        const prevStart = typeof shiftLocalDateByMonths === 'function'
            ? shiftLocalDateByMonths(startDate, -1)
            : addDaysYYYYMMDD(startDate, -30);
        return {
            startDate: prevStart,
            endDate: addDaysYYYYMMDD(prevStart, days - 1),
            label: 'Same period last month',
            valid: true,
            mode: key
        };
    }
    if (key === 'same-period-last-year') {
        const prevStart = typeof shiftLocalDateByMonths === 'function'
            ? shiftLocalDateByMonths(startDate, -12)
            : addDaysYYYYMMDD(startDate, -365);
        return {
            startDate: prevStart,
            endDate: addDaysYYYYMMDD(prevStart, days - 1),
            label: 'Same period last year',
            valid: true,
            mode: key
        };
    }
    // previous-selected-range (default): equal-length window immediately before
    const prev = typeof getEqualLengthPreviousBounds === 'function'
        ? getEqualLengthPreviousBounds(startDate, endDate)
        : {
            startDate: addDaysYYYYMMDD(startDate, -days),
            endDate: addDaysYYYYMMDD(startDate, -1),
            daysInRange: days
        };
    return {
        startDate: prev.startDate,
        endDate: prev.endDate,
        label: 'Previous selected range',
        valid: true,
        mode: 'previous-selected-range'
    };
}

function getCanonicalSpendInRange(substanceId, startDate, endDate, data = appData) {
    if (!substanceId || !startDate || !endDate) return 0;
    return (data.purchases || []).reduce((sum, p) => {
        if (typeof purchaseCountsTowardSpend === 'function' && !purchaseCountsTowardSpend(p)) return sum;
        if (typeof purchaseMatchesSubstance === 'function') {
            if (!purchaseMatchesSubstance(p, substanceId, data)) return sum;
        } else if (getPurchaseSubstanceId(p) !== substanceId) {
            return sum;
        }
        const d = getPurchaseDateStr(p);
        if (!d || d < startDate || d > endDate) return sum;
        return sum + (getPurchaseSpendAmount(p) || 0);
    }, 0);
}

function getPeriodCompareMetricValue(substanceId, metricKind, bounds, data = appData) {
    if (!bounds?.startDate || !bounds?.endDate) return null;
    const kind = metricKind || 'use';
    if (kind === 'use' || kind === 'taper' || kind === 'nicotineStrength') {
        return typeof getCanonicalUsageInRange === 'function'
            ? getCanonicalUsageInRange(substanceId, bounds.startDate, bounds.endDate, data)
            : null;
    }
    if (kind === 'spend') {
        return getCanonicalSpendInRange(substanceId, bounds.startDate, bounds.endDate, data);
    }
    if (kind === 'purchaseCount') {
        return typeof getPurchaseCountInDateRange === 'function'
            ? getPurchaseCountInDateRange(substanceId, bounds.startDate, bounds.endDate, null, data)
            : null;
    }
    if (kind === 'inventory' || kind === 'gift' || kind === 'adjustment') {
        return null; // neutral / snapshot metrics — callers pass explicit previous when available
    }
    return typeof getCanonicalUsageInRange === 'function'
        ? getCanonicalUsageInRange(substanceId, bounds.startDate, bounds.endDate, data)
        : null;
}

/**
 * Build a previous-period comparison model from already-normalized current/previous values.
 */
function buildMetricPeriodComparison({
    current,
    previous,
    metricKind = 'use',
    direction,
    unit = '',
    currentLabel = null,
    previousLabel = null,
    currentPeriodLabel = 'Current',
    previousPeriodLabel = 'Previous',
    currentBounds = null,
    previousBounds = null
} = {}) {
    const dir = normalizeTargetLineDirection(direction || metricKind || 'use');
    const cur = current == null || current === '' ? null : Number(current);
    const prev = previous == null || previous === '' ? null : Number(previous);
    const hasCurrent = cur != null && Number.isFinite(cur);
    const hasPrevious = prev != null && Number.isFinite(prev);
    const difference = (hasCurrent && hasPrevious) ? (cur - prev) : null;

    // Never invent a percentage when previous is zero (or missing).
    let percent = null;
    if (hasCurrent && hasPrevious && Math.abs(prev) > (typeof INVENTORY_EPS === 'number' ? INVENTORY_EPS : 1e-9)) {
        percent = (difference / Math.abs(prev)) * 100;
    }

    let tone = 'neutral';
    let directionKey = 'unchanged';
    let directionValue = 0;
    if (!hasPrevious) {
        tone = 'missing';
    } else if (!hasCurrent) {
        tone = 'missing';
    } else if (dir === 'neutral') {
        tone = 'neutral';
        if (difference != null && Math.abs(difference) > 1e-9) {
            directionKey = difference > 0 ? 'increase' : 'decrease';
            directionValue = difference > 0 ? 1 : -1;
        }
    } else if (difference != null) {
        if (Math.abs(difference) <= 1e-9) {
            tone = 'neutral';
            directionKey = 'unchanged';
        } else {
            directionKey = difference > 0 ? 'increase' : 'decrease';
            directionValue = difference > 0 ? 1 : -1;
            const improved = dir === 'higherIsBetter' ? difference > 0 : difference < 0;
            tone = improved ? 'favorable' : 'unfavorable';
        }
    }

    const arrow = directionKey === 'decrease' ? '▼' : directionKey === 'increase' ? '▲' : '►';
    const absDiffLabel = difference == null
        ? null
        : formatMetricTargetLineDifference(Math.abs(difference), unit).replace(/^[+−-]/, '');
    let changeDisplay;
    if (!hasPrevious) {
        changeDisplay = 'No previous value';
    } else if (difference == null) {
        changeDisplay = 'No previous value';
    } else if (percent == null) {
        // Previous was zero (or non-finite pct) — still show numeric difference.
        const signed = difference > 0 ? `+${absDiffLabel}` : difference < 0 ? `−${absDiffLabel}` : absDiffLabel;
        changeDisplay = `${arrow} ${signed}`;
    } else {
        const pctAbs = Math.round(Math.abs(percent) * 10) / 10;
        const lowerHigher = difference < 0 ? 'lower' : difference > 0 ? 'higher' : 'unchanged';
        changeDisplay = `${arrow} ${absDiffLabel} · ${pctAbs}% ${lowerHigher}`;
    }

    const curDisplay = currentLabel != null && currentLabel !== ''
        ? String(currentLabel)
        : formatMetricTargetLineValue(cur, unit);
    const prevDisplay = !hasPrevious
        ? 'No previous value'
        : (previousLabel != null && previousLabel !== ''
            ? String(previousLabel)
            : formatMetricTargetLineValue(prev, unit));

    return {
        current: hasCurrent ? cur : null,
        previous: hasPrevious ? prev : null,
        difference,
        percent,
        direction: dir,
        directionKey,
        directionValue,
        tone,
        unit: unit || '',
        arrow,
        currentDisplay: hasCurrent ? curDisplay : '—',
        previousDisplay: prevDisplay,
        differenceDisplay: difference == null
            ? '—'
            : formatMetricTargetLineDifference(difference, unit),
        percentDisplay: percent == null ? '—' : `${Math.round(percent * 10) / 10}%`,
        changeDisplay,
        currentPeriodLabel: currentPeriodLabel || 'Current',
        previousPeriodLabel: previousPeriodLabel || 'Previous',
        currentBounds: currentBounds || null,
        previousBounds: previousBounds || null,
        missingPrevious: !hasPrevious,
        valid: hasCurrent || hasPrevious
    };
}

function resolvePeriodCompareColors(comparison, ccrResult = null, colorScope = null, data = appData) {
    const scope = normalizePreviousPeriodColorScope(colorScope || getPreviousPeriodCompareColorScope(data));
    const defaults = PERIOD_COMPARE_DEFAULT_COLORS[comparison?.tone] || PERIOD_COMPARE_DEFAULT_COLORS.neutral;
    const hasCcr = !!(ccrResult?.matched?.length && ccrResult.style);
    const ccr = hasCcr ? {
        background: ccrResult.style.background || '',
        text: ccrResult.style.text || '',
        border: ccrResult.style.border || '',
        fill: ccrResult.style.background || ccrResult.style.border || ccrResult.style.text || ''
    } : null;
    const active = ccr || defaults;
    return {
        scope,
        hasCustomRule: hasCcr,
        tone: comparison?.tone || 'neutral',
        previous: scope === 'previous' ? active : null,
        numericChange: scope === 'numericChange' ? active : null,
        percentageChange: scope === 'percentageChange' ? active : null,
        direction: scope === 'direction' ? active : null,
        active
    };
}

function evaluatePeriodCompareColors(comparison, options = {}, data = appData) {
    if (typeof evaluateConditionalColorRules !== 'function' || !comparison) {
        return { matched: [], style: null, labels: [] };
    }
    const scope = normalizePreviousPeriodColorScope(
        options.colorScope || getPreviousPeriodCompareColorScope(data)
    );
    let metric = 'periodNumericChange';
    let value = comparison.difference;
    let textValue = undefined;
    if (scope === 'previous') {
        metric = 'periodPreviousValue';
        value = comparison.previous;
    } else if (scope === 'percentageChange') {
        metric = 'periodPercentageChange';
        value = comparison.percent;
    } else if (scope === 'direction') {
        metric = 'periodChangeDirection';
        value = comparison.directionValue;
        textValue = comparison.directionKey;
    }
    if (value == null && textValue == null) {
        return { matched: [], style: null, labels: [] };
    }
    return evaluateConditionalColorRules({
        substanceId: options.substanceId,
        section: options.section || 'dashboard',
        metric,
        value,
        textValue
    }, data);
}

function buildPeriodComparePartStyle(colorSet) {
    if (!colorSet) return '';
    return [
        colorSet.background ? `background:${colorSet.background}` : '',
        colorSet.text ? `color:${colorSet.text}` : '',
        colorSet.border ? `border-color:${colorSet.border}` : ''
    ].filter(Boolean).join(';');
}

function renderMetricPeriodComparison(comparison, {
    ccrResult = null,
    colorScope = null,
    data = appData,
    compact = false
} = {}) {
    if (!comparison || !isPreviousPeriodCompareEnabled(data)) return '';
    const colors = resolvePeriodCompareColors(comparison, ccrResult, colorScope, data);
    const prevStyle = buildPeriodComparePartStyle(colors.previous);
    const changeStyle = buildPeriodComparePartStyle(colors.numericChange);
    const pctStyle = buildPeriodComparePartStyle(colors.percentageChange);
    const dirStyle = buildPeriodComparePartStyle(colors.direction);
    const compactClass = compact ? ' metric-period-compare--compact' : '';
    const changeRowStyle = changeStyle || pctStyle || dirStyle;

    return `<div class="metric-period-compare${compactClass} metric-pc-tone-${escapeAttr(comparison.tone || 'neutral')}${colors.hasCustomRule ? ' ccr-applied' : ''}" data-color-scope="${escapeAttr(colors.scope)}">
        <div class="metric-pc-row metric-pc-current"><span class="metric-pc-label">${escapeHtml(comparison.currentPeriodLabel)}:</span> <span class="metric-pc-value">${escapeHtml(comparison.currentDisplay)}</span></div>
        <div class="metric-pc-row metric-pc-previous"${prevStyle ? ` style="${escapeAttr(prevStyle)}"` : ''}><span class="metric-pc-label">${escapeHtml(comparison.previousPeriodLabel)}:</span> <span class="metric-pc-value">${escapeHtml(comparison.previousDisplay)}</span></div>
        <div class="metric-pc-row metric-pc-change"${changeRowStyle ? ` style="${escapeAttr(changeRowStyle)}"` : ''}><span class="metric-pc-value">${escapeHtml(comparison.changeDisplay)}</span></div>
    </div>`;
}

/**
 * High-level helper: fetch previous metric for bounds+mode and render comparison HTML.
 * Callers pass the already-normalized current value (and optional labels).
 */
function renderPreviousPeriodCompareForMetric({
    substanceId,
    currentValue,
    currentBounds,
    metricKind = 'use',
    unit = '',
    currentLabel = null,
    currentPeriodLabel = 'Current',
    previousPeriodLabel = null,
    mode = null,
    section = 'dashboard',
    data = appData,
    compact = false
} = {}) {
    if (!isPreviousPeriodCompareEnabled(data)) return '';
    if (!currentBounds?.startDate || !currentBounds?.endDate) return '';
    const compareMode = mode || getPreviousPeriodCompareMode(data);
    const prevBounds = resolvePreviousPeriodBounds(currentBounds, compareMode);
    if (!prevBounds.valid) {
        const missing = buildMetricPeriodComparison({
            current: currentValue,
            previous: null,
            metricKind,
            unit,
            currentLabel,
            currentPeriodLabel,
            previousPeriodLabel: previousPeriodLabel || 'Previous'
        });
        return renderMetricPeriodComparison(missing, { data, compact });
    }
    const previousValue = getPeriodCompareMetricValue(substanceId, metricKind, prevBounds, data);
    const modeLabel = PREVIOUS_PERIOD_COMPARE_MODES.find(m => m.id === compareMode)?.label
        || prevBounds.label
        || 'Previous';
    const cmp = buildMetricPeriodComparison({
        current: currentValue,
        previous: previousValue,
        metricKind,
        unit,
        currentLabel,
        previousLabel: null,
        currentPeriodLabel,
        previousPeriodLabel: previousPeriodLabel || modeLabel,
        currentBounds,
        previousBounds: prevBounds
    });
    const ccr = evaluatePeriodCompareColors(cmp, { substanceId, section }, data);
    return renderMetricPeriodComparison(cmp, {
        ccrResult: ccr,
        data,
        compact
    });
}

