function getDefaultConditionalColorRulesState(theme = 'dark') {
    return {
        enabled: true,
        version: 1,
        rules: [],
        metricSettings: {}
    };
}

function normalizeHexColor(input, fallback = '#000000') {
    if (input == null) return fallback;
    let s = String(input).trim();
    if (!s) return fallback;
    if (s.startsWith('rgba') || s.startsWith('rgb') || s.startsWith('hsl')) return s;
    if (s[0] !== '#') s = `#${s}`;
    if (/^#[0-9a-fA-F]{3}$/.test(s)) {
        s = `#${s[1]}${s[1]}${s[2]}${s[2]}${s[3]}${s[3]}`;
    }
    if (/^#[0-9a-fA-F]{6}$/.test(s) || /^#[0-9a-fA-F]{8}$/.test(s)) return s.toLowerCase();
    return fallback;
}

function clampCssByte(n) {
    return Math.max(0, Math.min(255, Math.round(Number(n) || 0)));
}

function rgbToHexColor(r, g, b) {
    return `#${[r, g, b].map(v => clampCssByte(v).toString(16).padStart(2, '0')).join('')}`;
}

/** Parse #RGB / #RRGGBB / #RRGGBBAA / rgb() / rgba() into { r, g, b, a } (a in 0–1). */
function parseCssColor(color) {
    if (color == null || typeof color !== 'string') return null;
    const c = color.trim();
    if (!c) return null;

    let m = c.match(/^#([0-9a-fA-F]{3})$/);
    if (m) {
        const h = m[1];
        return {
            r: parseInt(h[0] + h[0], 16),
            g: parseInt(h[1] + h[1], 16),
            b: parseInt(h[2] + h[2], 16),
            a: 1
        };
    }
    m = c.match(/^#([0-9a-fA-F]{6})([0-9a-fA-F]{2})?$/);
    if (m) {
        return {
            r: parseInt(m[1].slice(0, 2), 16),
            g: parseInt(m[1].slice(2, 4), 16),
            b: parseInt(m[1].slice(4, 6), 16),
            a: m[2] != null ? parseInt(m[2], 16) / 255 : 1
        };
    }
    m = c.match(/^rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)(?:\s*,\s*([\d.]+%?))?\s*\)$/i);
    if (m) {
        let a = 1;
        if (m[4] != null) {
            a = String(m[4]).endsWith('%') ? parseFloat(m[4]) / 100 : parseFloat(m[4]);
        }
        if (!Number.isFinite(a)) a = 1;
        return {
            r: Number(m[1]),
            g: Number(m[2]),
            b: Number(m[3]),
            a: Math.max(0, Math.min(1, a))
        };
    }
    return null;
}

function formatCssColorFromParts(parts) {
    if (!parts) return '';
    const r = clampCssByte(parts.r);
    const g = clampCssByte(parts.g);
    const b = clampCssByte(parts.b);
    let a = parts.a;
    if (a == null || !Number.isFinite(Number(a))) a = 1;
    a = Math.max(0, Math.min(1, Number(a)));
    if (a >= 0.999) return rgbToHexColor(r, g, b);
    const aStr = String(Math.round(a * 1000) / 1000);
    return `rgba(${r}, ${g}, ${b}, ${aStr})`;
}

function composeCcrBackgroundFromPicker(pickerHex, opacityPercent) {
    const rgb = parseCssColor(pickerHex) || { r: 76, g: 175, b: 80, a: 1 };
    const pct = Math.max(0, Math.min(100, Number(opacityPercent)));
    const a = Number.isFinite(pct) ? pct / 100 : 1;
    return formatCssColorFromParts({ r: rgb.r, g: rgb.g, b: rgb.b, a });
}

function validateCcrBackgroundColor(value) {
    const trimmed = String(value ?? '').trim();
    if (!trimmed) {
        return { ok: true, value: '', message: '', parsed: null };
    }
    const parsed = parseCssColor(trimmed);
    if (!parsed) {
        return {
            ok: false,
            value: trimmed,
            message: 'Invalid background color. Use #RGB, #RRGGBB, #RRGGBBAA, rgb(), or rgba().',
            parsed: null
        };
    }
    return { ok: true, value: trimmed, message: '', parsed };
}

function parseCssColorToRgb(color) {
    const parsed = parseCssColor(color);
    if (!parsed) return null;
    return { r: parsed.r, g: parsed.g, b: parsed.b };
}

function relativeLuminance(rgb) {
    if (!rgb) return null;
    const channel = (v) => {
        const s = Math.max(0, Math.min(255, Number(v))) / 255;
        return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
    };
    const r = channel(rgb.r);
    const g = channel(rgb.g);
    const b = channel(rgb.b);
    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

function getContrastRatio(fg, bg) {
    const a = relativeLuminance(parseCssColorToRgb(fg));
    const b = relativeLuminance(parseCssColorToRgb(bg));
    if (a == null || b == null) return null;
    const lighter = Math.max(a, b);
    const darker = Math.min(a, b);
    return (lighter + 0.05) / (darker + 0.05);
}

function getContrastWarning(fg, bg) {
    const ratio = getContrastRatio(fg, bg);
    if (ratio == null) return { ok: true, ratio: null, message: '' };
    if (ratio >= 4.5) return { ok: true, ratio, message: `Contrast ${ratio.toFixed(2)}:1 — good` };
    if (ratio >= 3) return { ok: false, ratio, message: `Contrast ${ratio.toFixed(2)}:1 — low for small text` };
    return { ok: false, ratio, message: `Contrast ${ratio.toFixed(2)}:1 — poor; adjust colors` };
}

function normalizeConditionalColorRule(raw, index = 0) {
    if (!raw || typeof raw !== 'object') return null;
    const rawMetricKey = String(raw.metric || '').trim();
    const migratedMetricKey = migrateCcrMetricKey(rawMetricKey);
    const removedCurrentGapMetric = migratedMetricKey === 'useGapCurrent';
    const opIds = new Set(CCR_OPERATORS.map(o => o.id));
    const metricDef = getCcrMetricDef(raw.metric);
    const metric = metricDef ? metricDef.key : 'useAmount';
    const removedDropdownMetric = !!metricDef && !isCcrDropdownMetricKey(metric);
    let operator = opIds.has(raw.operator) ? raw.operator : 'gt';
    if (operator === 'betweenInclusive') operator = 'between';
    let sectionScope = raw.sectionScope;
    if (sectionScope === 'all' || sectionScope == null) sectionScope = ['all'];
    if (!Array.isArray(sectionScope)) sectionScope = [String(sectionScope)];
    sectionScope = sectionScope.map(String).filter(Boolean);
    if (!sectionScope.length) sectionScope = ['all'];

    let substanceScope = raw.substanceScope;
    if (substanceScope == null || substanceScope === '' || substanceScope === 'all') {
        substanceScope = 'all';
    } else if (Array.isArray(substanceScope)) {
        substanceScope = substanceScope.map(String).filter(Boolean);
        if (!substanceScope.length) substanceScope = 'all';
    } else {
        substanceScope = String(substanceScope);
    }

    const colors = raw.colors && typeof raw.colors === 'object' ? raw.colors : {};
    const border = normalizeHexColor(colors.border, '#4caf50');
    const lastModified = raw.lastModified
        ? String(raw.lastModified)
        : (raw.updatedAt ? String(raw.updatedAt) : '');
    let valueUnit = raw.valueUnit == null || raw.valueUnit === '' ? null : String(raw.valueUnit);
    let durationValueVersion = raw.durationValueVersion == null
        ? null
        : Number(raw.durationValueVersion);
    let value = raw.value === undefined ? null : raw.value;
    let valueTo = raw.valueTo === undefined ? null : raw.valueTo;
    let targetValue = raw.targetValue === undefined ? null : raw.targetValue;
    if (rawMetricKey === 'daysSinceUse' || rawMetricKey === 'timeSinceLastUse') {
        const convertDaysToHours = (v) => {
            const n = ccrCoerceNumber(v);
            return n == null ? v : n * 24;
        };
        value = convertDaysToHours(value);
        valueTo = convertDaysToHours(valueTo);
        targetValue = convertDaysToHours(targetValue);
        valueUnit = 'hours';
    }
    if (metric === 'sessionDuration') {
        if (valueUnit !== 'hours' && valueUnit !== 'minutes') {
            if (durationValueVersion === 2 || raw.valueInputUnit === 'hours') valueUnit = 'hours';
            else valueUnit = 'minutes'; // legacy saved Duration rules stored minutes
        }
        if (valueUnit === 'hours') durationValueVersion = 2;
        else if (durationValueVersion == null) durationValueVersion = 1;
    } else if (isCcrTimeGapMetric(metric)) {
        if (!CCR_TIME_INPUT_UNITS.includes(valueUnit)) valueUnit = 'hours';
        value = ccrTimeGapUnitToHours(value, valueUnit);
        valueTo = ccrTimeGapUnitToHours(valueTo, valueUnit);
        targetValue = ccrTimeGapUnitToHours(targetValue, valueUnit);
        valueUnit = 'hours';
        durationValueVersion = null;
    } else {
        valueUnit = null;
        durationValueVersion = null;
    }
    const metricDefaults = getDefaultCcrMetricSettings(metric);
    if (!opIds.has(operator)) {
        operator = metricDefaults?.defaultOperator || metricDefaults?.allowedOperators?.[0] || 'gt';
    }
    const normalizedBoundary = raw.rangeBoundary == null && operator === 'between'
        ? 'inclusive'
        : normalizeCcrRangeBoundary(raw.rangeBoundary, operator);
    let visualTarget = normalizeCcrVisualTarget(raw.visualTarget || raw.targetArea || raw.target);
    const createdByUser = raw.createdByUser === true || (!raw.isPreset && raw.createdByUser !== false);
    const createdAt = raw.createdAt
        ? String(raw.createdAt)
        : (raw.lastModified ? String(raw.lastModified) : new Date().toISOString());
    const normalized = {
        id: String(raw.id || ccrNewId()),
        name: String(raw.name || `Rule ${index + 1}`).slice(0, 80),
        enabled: removedCurrentGapMetric ? false : raw.enabled !== false,
        isPreset: !!raw.isPreset,
        presetId: raw.presetId ? String(raw.presetId) : null,
        substanceScope,
        sectionScope,
        metric,
        operator,
        rangeBoundary: normalizedBoundary,
        value,
        valueTo,
        targetValue,
        valueUnit,
        durationValueVersion,
        colors: {
            // Empty string = no background override. Missing key keeps legacy default.
            background: Object.prototype.hasOwnProperty.call(colors, 'background')
                ? String(colors.background ?? '').trim()
                : '',
            text: Object.prototype.hasOwnProperty.call(colors, 'text') && String(colors.text ?? '').trim() === ''
                ? ''
                : (Object.prototype.hasOwnProperty.call(colors, 'text') ? normalizeHexColor(colors.text, '') : ''),
            border: Object.prototype.hasOwnProperty.call(colors, 'border') && String(colors.border ?? '').trim() === ''
                ? ''
                : (Object.prototype.hasOwnProperty.call(colors, 'border') ? border : ''),
            accent: Object.prototype.hasOwnProperty.call(colors, 'accent')
                ? normalizeHexColor(colors.accent, '')
                : ''
        },
        visualTarget,
        createdByUser,
        createdAt,
        priority: Number.isFinite(Number(raw.priority)) ? Number(raw.priority) : (100 - index),
        stopProcessing: !!raw.stopProcessing,
        statusLabel: raw.statusLabel != null ? String(raw.statusLabel).slice(0, 40) : '',
        customGroupId: raw.customGroupId ? String(raw.customGroupId) : '',
        lastModified
    };
    if (removedCurrentGapMetric) {
        normalized.needsReview = true;
        normalized.reviewReason = 'Current gap rules were disabled because the metric was removed. Recreate as Break Between Uses only if that preserves the intended meaning.';
    } else if (removedDropdownMetric) {
        normalized.needsReview = true;
        normalized.reviewReason = raw.reviewReason
            ? String(raw.reviewReason).slice(0, 240)
            : CCR_REMOVED_METRIC_REVIEW_REASON;
    } else {
        normalized.needsReview = !!raw.needsReview;
        if (raw.reviewReason) normalized.reviewReason = String(raw.reviewReason).slice(0, 240);
    }
    return normalized;
}

function normalizeCcrCustomGroup(raw, index = 0) {
    if (!raw || typeof raw !== 'object') return null;
    const id = String(raw.id || ccrNewId('group'));
    return {
        id,
        name: String(raw.name || `Group ${index + 1}`).slice(0, 80),
        enabled: raw.enabled !== false,
        createdAt: raw.createdAt ? String(raw.createdAt) : new Date().toISOString(),
        lastModified: raw.lastModified ? String(raw.lastModified) : ''
    };
}

function normalizeCcrManagerPersistedUi(raw = {}) {
    const allowedGroupBy = new Set(['substance', 'metric', 'section', 'enabled', 'custom']);
    const groupBy = allowedGroupBy.has(raw.groupBy) ? raw.groupBy : 'metric';
    const collapsedGroups = raw.collapsedGroups && typeof raw.collapsedGroups === 'object'
        ? { ...raw.collapsedGroups }
        : {};
    const expandedRuleIds = Array.isArray(raw.expandedRuleIds) ? raw.expandedRuleIds.map(String) : [];
    return { groupBy, collapsedGroups, expandedRuleIds };
}

function ensureConditionalColorRules(data = appData, options = {}) {
    if (!data.settings) data.settings = {};
    const theme = options.theme
        || (typeof resolvedTheme !== 'undefined' ? resolvedTheme : 'dark')
        || 'dark';
    const existing = data.settings[ccrStorageKey()];
    if (!existing || typeof existing !== 'object') {
        data.settings[ccrStorageKey()] = getDefaultConditionalColorRulesState(theme);
        return data.settings[ccrStorageKey()];
    }
    const state = data.settings[ccrStorageKey()];
    state.enabled = state.enabled !== false;
    state.version = Number(state.version) || 1;
    state.customGroups = Array.isArray(state.customGroups)
        ? state.customGroups.map((g, i) => normalizeCcrCustomGroup(g, i)).filter(Boolean)
        : [];
    state.ui = normalizeCcrManagerPersistedUi(state.ui);
    state.metricSettings = normalizeCcrMetricSettingsMap(state.metricSettings);
    if (!Array.isArray(state.rules)) {
        state.rules = [];
    } else {
        state.rules = state.rules
            .map((r, i) => normalizeConditionalColorRule(r, i))
            .filter(Boolean);
    }
    return state;
}

function getConditionalColorRulesState(data = appData) {
    return ensureConditionalColorRules(data);
}

function getConditionalColorRules(data = appData) {
    return getConditionalColorRulesState(data).rules.slice();
}

function persistConditionalColorRulesState(patch = {}, data = appData) {
    const state = ensureConditionalColorRules(data);
    if (patch.enabled != null) state.enabled = !!patch.enabled;
    if (Array.isArray(patch.rules)) {
        state.rules = patch.rules.map((r, i) => normalizeConditionalColorRule(r, i)).filter(Boolean);
    }
    if (Array.isArray(patch.customGroups)) {
        state.customGroups = patch.customGroups.map((g, i) => normalizeCcrCustomGroup(g, i)).filter(Boolean);
    }
    if (patch.ui && typeof patch.ui === 'object') {
        state.ui = normalizeCcrManagerPersistedUi({ ...(state.ui || {}), ...patch.ui });
    }
    if (patch.metricSettings && typeof patch.metricSettings === 'object') {
        state.metricSettings = normalizeCcrMetricSettingsMap(patch.metricSettings);
    }
    data.settings[ccrStorageKey()] = state;
    if (typeof saveData === 'function') saveData(data);
    return state;
}

function ccrCoerceNumber(value) {
    if (value == null || value === '') return null;
    if (typeof value === 'number') return Number.isFinite(value) ? value : null;
    const n = parseFloat(String(value).replace(/[^0-9eE.+-]/g, ''));
    return Number.isFinite(n) ? n : null;
}

function ccrMetricLegacyKeys(metricKey) {
    const canonical = migrateCcrMetricKey(metricKey);
    return Object.entries(CCR_METRIC_ALIASES)
        .filter(([, target]) => target === canonical)
        .map(([key]) => key);
}

function ccrMetricRecordFromContext(context = {}) {
    return context.record || context.log || context.purchase || context.taperRow
        || context.periodComparison || context.comparison || null;
}

function ccrMetricNumber(value) {
    return ccrCoerceNumber(value);
}

function ccrMetricText(value) {
    return value == null ? '' : String(value);
}

function ccrMetricDateDiffDays(dateValue, asOf = new Date()) {
    if (!dateValue) return null;
    const then = typeof parseLocalDate === 'function' ? parseLocalDate(String(dateValue)) : new Date(dateValue);
    const now = asOf instanceof Date ? asOf : new Date(asOf);
    if (!then?.getTime || !Number.isFinite(then.getTime()) || !Number.isFinite(now.getTime())) return null;
    return Math.max(0, (now.getTime() - then.getTime()) / 86400000);
}

function ccrMetricMatchesFamily(record, family, data = appData) {
    if (!record || !family || family === 'all') return true;
    const sid = record.substanceId || record.substance || record.item || record.substanceScope;
    if (!sid) return true;
    return resolveCcrMetricSubstanceFamily(sid, data) === family;
}

function ccrMetricPurchaseList(context = {}, data = appData) {
    const family = resolveCcrMetricSubstanceFamily(context.substanceId || context.substanceScope || 'all', data);
    const direct = Array.isArray(context.purchases) ? context.purchases : (data.purchases || []);
    return direct
        .filter(p => ccrMetricMatchesFamily(p, family, data))
        .filter(p => !p.archivedAt && !p.inventoryHidden);
}

function ccrMetricPurchaseGapsDays(purchases = []) {
    const sorted = purchases
        .filter(p => p?.date)
        .slice()
        .sort((a, b) => getPurchaseDatetimeMs(a) - getPurchaseDatetimeMs(b));
    const gaps = [];
    for (let i = 1; i < sorted.length; i++) {
        const prev = getPurchaseDatetimeMs(sorted[i - 1]);
        const cur = getPurchaseDatetimeMs(sorted[i]);
        if (Number.isFinite(prev) && Number.isFinite(cur) && cur >= prev) {
            gaps.push((cur - prev) / 86400000);
        }
    }
    return gaps;
}

function ccrMetricPurchaseWindowDays(purchases = []) {
    const times = purchases
        .map(p => getPurchaseDatetimeMs(p))
        .filter(Number.isFinite)
        .sort((a, b) => a - b);
    if (!times.length) return null;
    if (times.length === 1) return 7;
    return Math.max(1, (times[times.length - 1] - times[0]) / 86400000);
}

function ccrMetricPurchaseUnitCost(purchase, explicitKey = null) {
    if (!purchase) return null;
    const explicit = explicitKey ? ccrMetricNumber(purchase[explicitKey]) : null;
    if (explicit != null) return explicit;
    const spend = getPurchaseSpendAmount(purchase);
    const qty = getPurchaseQuantityBought(purchase);
    return qty > 0 ? spend / qty : null;
}

function ccrMetricLogAmount(log) {
    if (!log) return null;
    if (typeof getLogPersonalAmount === 'function') {
        const personal = getLogPersonalAmount(log);
        if (Number.isFinite(personal) && personal > 0) return personal;
    }
    return ccrMetricNumber(log.amount);
}

function ccrMetricResolveField(context, keys, fallback = null) {
    const record = ccrMetricRecordFromContext(context);
    for (const key of keys) {
        if (record && record[key] != null && record[key] !== '') return record[key];
        if (context[key] != null && context[key] !== '') return context[key];
    }
    return fallback;
}

function ccrMetricResolveNumericField(context, keys, fallback = null) {
    const value = ccrMetricResolveField(context, keys, fallback);
    return ccrMetricNumber(value);
}

function ccrMetricResolveTextField(context, keys, fallback = '') {
    return ccrMetricText(ccrMetricResolveField(context, keys, fallback));
}

function ccrMetricResolveUseVsTarget(context = {}) {
    const used = ccrMetricResolveNumericField(context, ['used', 'actual', 'current', 'value']);
    const target = ccrMetricResolveNumericField(context, ['target', 'goal', 'limit', 'planned', 'targetValue']);
    if (used == null || target == null || target <= 0) return null;
    return { value: used / target, target };
}

function ccrMetricResolveTaperRatio(context = {}) {
    const actual = ccrMetricResolveNumericField(context, ['actual', 'actualAmount', 'actualGrams', 'actualPuffs', 'actualDrinks', 'used']);
    const planned = ccrMetricResolveNumericField(context, ['planned', 'plannedAmount', 'plannedGrams', 'puffTarget', 'weeklyMax', 'plannedDrinks', 'target']);
    if (actual == null || planned == null || planned <= 0) return null;
    return { value: actual / planned, target: planned };
}

function ccrMetricResolvePercentageOfTarget(context = {}) {
    const direct = ccrMetricResolveNumericField(context, ['percentageOfTarget']);
    if (direct != null) return direct;
    const ratio = ccrMetricResolveTaperRatio(context);
    return ratio?.value != null ? ratio.value * 100 : null;
}

function ccrMetricResolvePurchaseBreakHours(context = {}, data = appData) {
    const purchase = context.purchase || context.record;
    if (!purchase?.date) return ccrMetricResolveNumericField(context, ['breakBetweenPurchases', 'breakHours']);
    const family = resolveCcrMetricSubstanceFamily(context.substanceId || getPurchaseSubstanceId(purchase) || 'all', data);
    const sorted = (data.purchases || [])
        .filter(p => p !== purchase && ccrMetricMatchesFamily(p, family, data))
        .filter(p => p.date && !p.archivedAt && !p.inventoryHidden)
        .sort((a, b) => getPurchaseDatetimeMs(b) - getPurchaseDatetimeMs(a));
    const cur = getPurchaseDatetimeMs(purchase);
    const prev = sorted.find(p => getPurchaseDatetimeMs(p) < cur);
    if (!prev) return null;
    return (cur - getPurchaseDatetimeMs(prev)) / 3600000;
}

function ccrMetricResolveMonthlySpend(context = {}, data = appData) {
    const direct = ccrMetricResolveNumericField(context, ['monthlySpending', 'monthSpend']);
    if (direct != null) return direct;
    const purchase = context.purchase || context.record;
    const month = purchase?.date ? String(purchase.date).slice(0, 7) : getLocalDateString().slice(0, 7);
    return ccrMetricPurchaseList(context, data)
        .filter(p => String(p.date || '').slice(0, 7) === month)
        .reduce((sum, p) => sum + getPurchaseSpendAmount(p), 0);
}

function ccrMetricResolvePeriod(context = {}, key) {
    const comparison = context.periodComparison || context.comparison || context.record || {};
    if (key === 'periodPreviousValue') return ccrMetricNumber(comparison.previous);
    if (key === 'periodNumericChange') return ccrMetricNumber(comparison.difference);
    if (key === 'periodPercentageChange') return ccrMetricNumber(comparison.percent);
    if (key === 'periodChangeDirection') {
        const text = comparison.directionKey || comparison.direction || comparison.directionValue;
        return { value: comparison.directionValue ?? text, textValue: ccrMetricText(text) };
    }
    return null;
}

const CCR_METRIC_FORMATTERS = Object.freeze({
    number: value => value == null ? '—' : formatAmount(value),
    currency: value => value == null ? '—' : fmtSheetMoney(value, appData?.settings?.currency || '$'),
    percent: value => value == null ? '—' : `${formatAmount(value)}%`,
    ratio: value => value == null ? '—' : `${formatAmount(value * 100)}%`,
    hours: value => value == null ? '—' : formatBreakSincePreviousUse(value),
    days: value => value == null ? '—' : `${formatAmount(value)}d`,
    text: value => value == null || value === '' ? '—' : String(value),
    boolean: value => value ? 'True' : 'False'
});

const CCR_METRIC_RESOLVERS = Object.freeze({
    useAmount: (context) => ccrMetricLogAmount(context.log || context.record),
    sessionDuration: (context) => getNormalizedSessionDurationMinutes(context.log || context.record),
    useVsTarget: ccrMetricResolveUseVsTarget,
    useGapPrevious: (context, data) => computeBreakSincePreviousUseHours(context.log || context.record, data),
    inventoryRemaining: (context) => getPurchaseRemainingAmount(context.purchase || context.record),
    inventoryPercent: (context) => getPurchasePercentRemaining(context.purchase || context.record),
    daysSincePurchase: (context) => ccrMetricDateDiffDays((context.purchase || context.record)?.date, context.asOf),
    inventoryStatus: (context) => {
        const purchase = context.purchase || context.record;
        const status = purchase?.inventoryStatus || getPurchaseSupplyStatus(purchase)?.key || '';
        return { value: status, textValue: status };
    },
    spend: (context) => getPurchaseSpendAmount(context.purchase || context.record),
    purchaseCount: (context, data) => context.purchase || context.record?.date ? 1 : ccrMetricPurchaseList(context, data).length,
    purchaseAmount: (context) => getPurchaseQuantityBought(context.purchase || context.record),
    breakBetweenPurchases: ccrMetricResolvePurchaseBreakHours,
    averageGapBetweenPurchases: (context, data) => {
        const direct = ccrMetricResolveNumericField(context, ['averageGapBetweenPurchases', 'averagePurchaseGapDays', 'purchaseFrequencyDays']);
        if (direct != null) return direct;
        const gaps = ccrMetricPurchaseGapsDays(ccrMetricPurchaseList(context, data));
        return gaps.length ? gaps.reduce((sum, gap) => sum + gap, 0) / gaps.length : null;
    },
    purchasesPerWeek: (context, data) => {
        const direct = ccrMetricResolveNumericField(context, ['purchasesPerWeek']);
        if (direct != null) return direct;
        const purchases = ccrMetricPurchaseList(context, data);
        const days = ccrMetricPurchaseWindowDays(purchases);
        return days ? purchases.length / (days / 7) : null;
    },
    purchasesPerMonth: (context, data) => {
        const direct = ccrMetricResolveNumericField(context, ['purchasesPerMonth', 'purchaseFrequency']);
        if (direct != null) return direct;
        const purchases = ccrMetricPurchaseList(context, data);
        const days = ccrMetricPurchaseWindowDays(purchases);
        return days ? purchases.length / (days / 30.4375) : null;
    },
    store: (context) => {
        const store = ccrMetricResolveTextField(context, ['store', 'location', 'supplier']);
        return { value: store, textValue: store };
    },
    taperPlannedVsActual: ccrMetricResolveTaperRatio,
    taperStatus: (context) => {
        const status = ccrMetricResolveTextField(context, ['status', 'statusLabel', 'taperStatus']);
        return { value: status, textValue: status };
    },
    plannedAmount: (context) => ccrMetricResolveNumericField(context, [
        'plannedAmount', 'plannedGrams', 'puffTarget', 'plannedTabs', 'plannedUg',
        'plannedPills', 'plannedMg', 'plannedDrinks', 'planned', 'target'
    ]),
    actualAmount: (context) => ccrMetricResolveNumericField(context, [
        'actualAmount', 'actualGrams', 'actualPuffs', 'actualTabs', 'actualUg',
        'actualPills', 'actualMg', 'actualDrinks', 'actual', 'used'
    ]),
    difference: (context) => ccrMetricResolveNumericField(context, ['difference', 'diff']),
    percentageOfTarget: ccrMetricResolvePercentageOfTarget,
    transactionType: (context) => {
        const tx = getLogTransactionType(context.log || context.record || {});
        return { value: tx, textValue: tx };
    },
    productType: (context) => {
        const record = ccrMetricRecordFromContext(context) || {};
        const productType = record.productType || record.type || '';
        return { value: productType, textValue: productType };
    },
    statusLabel: (context) => {
        const label = ccrMetricResolveTextField(context, ['statusLabel', 'status']);
        return { value: label, textValue: label };
    },
    periodPreviousValue: (context) => ccrMetricResolvePeriod(context, 'periodPreviousValue'),
    periodNumericChange: (context) => ccrMetricResolvePeriod(context, 'periodNumericChange'),
    periodPercentageChange: (context) => ccrMetricResolvePeriod(context, 'periodPercentageChange'),
    periodChangeDirection: (context) => ccrMetricResolvePeriod(context, 'periodChangeDirection'),
    gramsPerHour: (context) => getNormalizedGramsPerHour(context.log || context.record),
    supplyDuration: (context) => ccrMetricResolveNumericField(context, ['supplyDuration', 'supplyDurationDays']),
    costPerGram: (context) => ccrMetricPurchaseUnitCost(context.purchase || context.record, 'costPerGram'),
    plannedGrams: (context) => ccrMetricResolveNumericField(context, ['plannedGrams', 'plannedAmount', 'planned']),
    actualGrams: (context) => ccrMetricResolveNumericField(context, ['actualGrams', 'actualAmount', 'actual']),
    useDifference: (context) => ccrMetricResolveNumericField(context, [
        'useDifference', 'puffDifference', 'difference', 'diff'
    ]),
    plannedSpending: (context) => ccrMetricResolveNumericField(context, ['plannedSpending', 'spendPlanned']),
    actualSpending: (context) => ccrMetricResolveNumericField(context, ['actualSpending', 'spent']),
    spendingDifference: (context) => ccrMetricResolveNumericField(context, ['spendingDifference', 'spendDiff']),
    puffs: (context) => ccrMetricResolveNumericField(context, ['puffs', 'amount']),
    percentLeftCheckpoint: (context) => ccrMetricResolveNumericField(context, ['percentAfter', 'percentLeft', 'percentLeftCheckpoint']),
    personalUseAmount: (context) => getLogPersonalAmount(context.log || context.record || {}),
    nicotineFreeHours: (context) => ccrMetricResolveNumericField(context, ['nicotineFreeHours']),
    percentLeft: (context) => ccrMetricResolveNumericField(context, ['percentLeft', 'remainingPercent']),
    puffsRemaining: (context) => ccrMetricResolveNumericField(context, ['puffsRemaining', 'remainingPuffs', 'remainingAmount']),
    currentVapeAge: (context) => ccrMetricResolveNumericField(context, ['currentVapeAge', 'vapeAgeDays']),
    vapeLifespan: (context) => ccrMetricResolveNumericField(context, ['vapeLifespan', 'vapeLifespanDays']),
    nicotineStrength: (context) => ccrMetricResolveNumericField(context, ['nicotineStrength', 'nicotineMgPerMl', 'nicotinePercent']),
    vapesPurchased: (context, data) => context.purchase || context.record?.date ? 1 : ccrMetricPurchaseList(context, data).length,
    costPerVape: (context) => ccrMetricPurchaseUnitCost(context.purchase || context.record, 'costPerVape'),
    monthlySpending: ccrMetricResolveMonthlySpend,
    breakBetweenVapePurchases: ccrMetricResolvePurchaseBreakHours,
    puffTarget: (context) => ccrMetricResolveNumericField(context, ['puffTarget', 'weeklyMax']),
    actualPuffs: (context) => ccrMetricResolveNumericField(context, ['actualPuffs', 'used']),
    puffDifference: (context) => ccrMetricResolveNumericField(context, ['puffDifference', 'difference']),
    puffsVsTargetRatio: (context) => {
        const actual = ccrMetricResolveNumericField(context, ['actualPuffs', 'used']);
        const target = ccrMetricResolveNumericField(context, ['puffTarget', 'weeklyMax', 'target']);
        return actual != null && target > 0 ? { value: actual / target, target } : null;
    },
    vapeLifespanGoal: (context) => ccrMetricResolveNumericField(context, ['vapeLifespanGoal', 'lifespanGoal']),
    daysBetweenPurchasesGoal: (context) => ccrMetricResolveNumericField(context, ['daysBetweenPurchasesGoal', 'buyInterval']),
    monthlyVapeCap: (context) => ccrMetricResolveNumericField(context, ['monthlyVapeCap', 'targetMonthlyVapeCap']),
    spendingGoal: (context) => ccrMetricResolveNumericField(context, ['spendingGoal', 'goalMonthlySpend']),
    tabs: (context) => ccrMetricResolveNumericField(context, ['tabs', 'quantityTabs', 'amount']),
    ug: (context) => ccrMetricResolveNumericField(context, ['ug', 'totalUg']),
    tabsRemaining: (context) => ccrMetricResolveNumericField(context, ['tabsRemaining', 'remainingTabs', 'remainingAmount']),
    ugRemaining: (context) => ccrMetricResolveNumericField(context, ['ugRemaining', 'remainingUg']),
    costPerTab: (context) => ccrMetricPurchaseUnitCost(context.purchase || context.record, 'costPerTab'),
    costPerUg: (context) => ccrMetricPurchaseUnitCost(context.purchase || context.record, 'costPerUg'),
    plannedTabs: (context) => ccrMetricResolveNumericField(context, ['plannedTabs', 'plannedAmount', 'planned']),
    actualTabs: (context) => ccrMetricResolveNumericField(context, ['actualTabs', 'actualAmount', 'actual']),
    plannedUg: (context) => ccrMetricResolveNumericField(context, ['plannedUg', 'plannedAmount', 'planned']),
    actualUg: (context) => ccrMetricResolveNumericField(context, ['actualUg', 'actualAmount', 'actual']),
    pills: (context) => ccrMetricResolveNumericField(context, ['pills', 'pillQuantity', 'amount']),
    mg: (context) => ccrMetricResolveNumericField(context, ['mg', 'totalMg']),
    strengthPerPill: (context) => ccrMetricResolveNumericField(context, ['strengthPerPill', 'mgPerPill']),
    pillsRemaining: (context) => ccrMetricResolveNumericField(context, ['pillsRemaining', 'remainingPills', 'remainingAmount']),
    mgRemaining: (context) => ccrMetricResolveNumericField(context, ['mgRemaining', 'remainingMg']),
    missingStrengthFlag: (context) => !!(context.record || context.purchase || {}).needsStrengthReview,
    costPerPill: (context) => ccrMetricPurchaseUnitCost(context.purchase || context.record, 'costPerPill'),
    costPerMg: (context) => ccrMetricPurchaseUnitCost(context.purchase || context.record, 'costPerMg'),
    plannedPills: (context) => ccrMetricResolveNumericField(context, ['plannedPills', 'plannedAmount', 'planned']),
    actualPills: (context) => ccrMetricResolveNumericField(context, ['actualPills', 'actualAmount', 'actual']),
    plannedMg: (context) => ccrMetricResolveNumericField(context, ['plannedMg', 'plannedAmount', 'planned']),
    actualMg: (context) => ccrMetricResolveNumericField(context, ['actualMg', 'actualAmount', 'actual']),
    drinks: (context) => ccrMetricResolveNumericField(context, ['drinks', 'amount']),
    multiDayDuration: (context) => ccrMetricResolveNumericField(context, ['multiDayDuration', 'durationDays']),
    costPerDrink: (context) => ccrMetricPurchaseUnitCost(context.purchase || context.record, 'costPerDrink'),
    plannedDrinks: (context) => ccrMetricResolveNumericField(context, ['plannedDrinks', 'plannedAmount', 'planned']),
    actualDrinks: (context) => ccrMetricResolveNumericField(context, ['actualDrinks', 'actualAmount', 'actual'])
});

const ccrMissingResolverWarnings = new Set();

function getCcrMetricResolver(metricKey) {
    const def = getCcrMetricDef(metricKey);
    if (!def) return null;
    return CCR_METRIC_RESOLVERS[def.resolver || def.key] || CCR_METRIC_RESOLVERS[def.key] || null;
}

function warnCcrMissingMetricResolver(metricKey) {
    const key = migrateCcrMetricKey(metricKey);
    if (ccrMissingResolverWarnings.has(key)) return;
    ccrMissingResolverWarnings.add(key);
    if (typeof console !== 'undefined' && typeof console.warn === 'function') {
        console.warn(`[CCR] Metric "${key}" is visible but has no registered resolver.`);
    }
}

function getCcrMetricFormatter(metricKey) {
    const def = getCcrMetricDef(metricKey);
    if (!def) return CCR_METRIC_FORMATTERS.number;
    if (def.formatter && CCR_METRIC_FORMATTERS[def.formatter]) return CCR_METRIC_FORMATTERS[def.formatter];
    if (def.valueType === 'string') return CCR_METRIC_FORMATTERS.text;
    if (def.valueType === 'boolean') return CCR_METRIC_FORMATTERS.boolean;
    if (def.unitType && CCR_METRIC_FORMATTERS[def.unitType]) return CCR_METRIC_FORMATTERS[def.unitType];
    return CCR_METRIC_FORMATTERS.number;
}

function normalizeCcrMetricResolvedValue(result) {
    if (result && typeof result === 'object' && !Array.isArray(result)
        && (Object.prototype.hasOwnProperty.call(result, 'value')
            || Object.prototype.hasOwnProperty.call(result, 'textValue')
            || Object.prototype.hasOwnProperty.call(result, 'target'))) {
        return {
            value: result.value,
            textValue: result.textValue,
            target: result.target
        };
    }
    return { value: result };
}

function resolveCcrRegisteredMetric(metricKey, context = {}, data = appData) {
    const def = getCcrMetricDef(metricKey);
    const resolver = getCcrMetricResolver(metricKey);
    if (!def || !resolver) return null;
    try {
        return normalizeCcrMetricResolvedValue(resolver(context, data, def));
    } catch (err) {
        if (typeof console !== 'undefined' && typeof console.warn === 'function') {
            console.warn(`[CCR] Metric resolver failed for "${def.key}".`, err);
        }
        return null;
    }
}

function getCcrMetricRegistryEntry(metricKey) {
    const def = getCcrMetricDef(metricKey);
    if (!def) return null;
    return {
        key: def.key,
        label: def.label,
        group: def.group,
        valueType: def.valueType,
        internalUnit: def.internalUnit,
        displayUnit: def.displayUnit,
        supportedSubstances: [...def.substances],
        supportedSections: [...def.sections],
        allowedOperators: [...(getDefaultCcrMetricSettings(def.key)?.allowedOperators || [])],
        calculationFunction: getCcrMetricResolver(def.key),
        formatter: getCcrMetricFormatter(def.key),
        favorableDirection: def.favorableDirection,
        legacyKeys: ccrMetricLegacyKeys(def.key),
        deleted: def.deleted
    };
}

function getCcrMetricRegistry() {
    return CCR_METRICS.map(m => getCcrMetricRegistryEntry(m.key)).filter(Boolean);
}

function hasCcrValidTargetData(data = appData, family = 'all') {
    const logs = data.logs || [];
    if (logs.some(l => ccrMetricMatchesFamily(l, family, data)
        && (l.target != null || l.goal != null || l.limit != null || l.planned != null))) return true;
    const plans = [
        ...Object.values(data.taperPlans || {}),
        ...(data.taperPlansV2 || [])
    ];
    return plans.some(plan => {
        if (!ccrMetricMatchesFamily(plan, family, data)) return false;
        return plan.target != null || plan.dailyLimit != null || plan.weeklyLimit != null
            || plan.goalAmount != null || (plan.weeklyTargets || []).some(w => (
                w.plannedAmount != null || w.plannedGrams != null || w.weeklyMax != null || w.puffTarget != null
            ));
    });
}

function ccrMetricHasAvailableData(metric, data = appData, family = 'all') {
    if (!metric) return false;
    if (metric.requiresTarget) return hasCcrValidTargetData(data, family);
    const key = metric.key;
    if (['spend', 'purchaseCount', 'purchaseAmount', 'breakBetweenPurchases', 'averageGapBetweenPurchases',
        'purchasesPerWeek', 'purchasesPerMonth', 'store', 'inventoryRemaining', 'inventoryPercent',
        'daysSincePurchase', 'inventoryStatus', 'costPerGram', 'costPerVape', 'costPerTab', 'costPerUg',
        'costPerPill', 'costPerMg', 'breakBetweenVapePurchases', 'vapesPurchased', 'monthlySpending'].includes(key)) {
        return (data.purchases || []).some(p => ccrMetricMatchesFamily(p, family, data));
    }
    if (['taperPlannedVsActual', 'taperStatus', 'plannedAmount', 'actualAmount', 'difference', 'percentageOfTarget',
        'plannedGrams', 'actualGrams', 'useDifference', 'plannedSpending', 'actualSpending', 'spendingDifference',
        'puffTarget', 'actualPuffs', 'puffDifference', 'puffsVsTargetRatio', 'vapeLifespanGoal',
        'daysBetweenPurchasesGoal', 'monthlyVapeCap', 'spendingGoal', 'plannedTabs', 'actualTabs',
        'plannedUg', 'actualUg', 'plannedPills', 'actualPills', 'plannedMg', 'actualMg',
        'plannedDrinks', 'actualDrinks'].includes(key)) {
        return !!((data.taperPlansV2 || []).length || Object.keys(data.taperPlans || {}).length);
    }
    if (key.startsWith('period')) return (data.logs || []).length > 0 || (data.purchases || []).length > 0;
    return (data.logs || []).some(l => ccrMetricMatchesFamily(l, family, data));
}

function ccrMetricSupportsSection(metric, section = 'all', data = appData) {
    if (!metric) return false;
    return ccrMetricSupportsSectionScope(metric, section, data);
}

function ccrMetricSupportsFamily(metric, family = 'all') {
    if (!metric) return false;
    if (!family || family === 'all') return metric.substances.includes('all');
    return metric.substances.includes(family);
}

function buildCcrMetricAuditReport(data = appData, options = {}) {
    const family = resolveCcrMetricSubstanceFamily(options.substanceScope || options.substance || 'all', data);
    const section = options.section || 'all';
    return CCR_METRICS.map(metric => {
        const resolver = getCcrMetricResolver(metric.key);
        const unsupportedSection = !ccrMetricSupportsSection(metric, section, data);
        const unsupportedSubstance = !ccrMetricSupportsFamily(metric, family);
        const noAvailableData = !ccrMetricHasAvailableData(metric, data, family);
        const statuses = [];
        if (resolver) statuses.push('implemented');
        else statuses.push('missing resolver');
        if (unsupportedSection) statuses.push('unsupported section');
        if (unsupportedSubstance) statuses.push('unsupported substance');
        if (noAvailableData) statuses.push('no available data');
        return {
            key: metric.key,
            label: metric.label,
            group: metric.group,
            valueType: metric.valueType,
            internalUnit: metric.internalUnit,
            displayUnit: metric.displayUnit,
            supportedSubstances: [...metric.substances],
            supportedSections: [...metric.sections],
            allowedOperators: [...(getDefaultCcrMetricSettings(metric.key)?.allowedOperators || [])],
            favorableDirection: metric.favorableDirection,
            legacyKeys: ccrMetricLegacyKeys(metric.key),
            visible: !metric.deleted
                && isCcrDropdownMetricKey(metric.key)
                && !!resolver
                && !unsupportedSubstance
                && !unsupportedSection
                && !(metric.hideWhenUnavailable && noAvailableData),
            deleted: metric.deleted,
            implemented: !!resolver,
            missingResolver: !resolver,
            unsupportedSection,
            unsupportedSubstance,
            noAvailableData,
            statuses
        };
    });
}

function renderCcrMetricAuditReport(data = appData, options = {}) {
    const rows = buildCcrMetricAuditReport(data, options);
    const visibleRows = rows.filter(r => !r.deleted);
    const counts = {
        implemented: visibleRows.filter(r => r.implemented).length,
        missing: visibleRows.filter(r => r.missingResolver).length,
        unsupportedSection: visibleRows.filter(r => r.unsupportedSection).length,
        unsupportedSubstance: visibleRows.filter(r => r.unsupportedSubstance).length,
        noData: visibleRows.filter(r => r.noAvailableData).length
    };
    const body = visibleRows.map(row => `
        <tr>
            <td><code>${escapeHtml(row.key)}</code></td>
            <td>${escapeHtml(row.label)}</td>
            <td>${escapeHtml(row.group)}</td>
            <td>${escapeHtml(row.valueType)}</td>
            <td>${escapeHtml(row.internalUnit || '—')}</td>
            <td>${escapeHtml(row.displayUnit || '—')}</td>
            <td>${escapeHtml(row.supportedSubstances.join(', ') || '—')}</td>
            <td>${escapeHtml(row.supportedSections.join(', ') || '—')}</td>
            <td>${escapeHtml(row.allowedOperators.join(', ') || '—')}</td>
            <td>${escapeHtml(row.statuses.join(', '))}</td>
        </tr>
    `).join('');
    return `<div class="ccr-metric-audit-summary">
        <span>Implemented: ${counts.implemented}</span>
        <span>Missing resolver: ${counts.missing}</span>
        <span>Unsupported section: ${counts.unsupportedSection}</span>
        <span>Unsupported substance: ${counts.unsupportedSubstance}</span>
        <span>No available data: ${counts.noData}</span>
    </div>
    <div class="table-scroll">
        <table class="ccr-metric-audit-table">
            <thead><tr><th>Key</th><th>Label</th><th>Group</th><th>Type</th><th>Internal</th><th>Display</th><th>Substances</th><th>Sections</th><th>Operators</th><th>Status</th></tr></thead>
            <tbody>${body}</tbody>
        </table>
    </div>`;
}

function toggleCcrMetricAuditReport() {
    const el = document.getElementById('ccr-metric-audit-report');
    if (!el) return;
    const show = el.classList.contains('hidden');
    el.classList.toggle('hidden', !show);
    if (show) {
        const substance = document.getElementById('ccr-manager-filter-substance')?.value || 'all';
        const section = document.getElementById('ccr-manager-filter-section')?.value || 'all';
        el.innerHTML = renderCcrMetricAuditReport(appData, { substanceScope: substance, section });
    }
}

function isCcrDurationMetric(metric) {
    return migrateCcrMetricKey(metric) === 'sessionDuration';
}

function isCcrTimeGapMetric(metric) {
    const key = migrateCcrMetricKey(metric);
    return key === 'useGapCurrent' || key === 'useGapPrevious';
}

/** Duration rules: new rules use hours; legacy rules without a unit are minutes. */
function getCcrDurationValueUnit(rule) {
    if (!isCcrDurationMetric(rule?.metric)) return null;
    if (rule.valueUnit === 'hours' || rule.valueUnit === 'minutes') return rule.valueUnit;
    if (rule.durationValueVersion === 2 || rule.valueInputUnit === 'hours') return 'hours';
    return 'minutes';
}

function ccrDurationHoursToMinutes(hours) {
    const n = ccrCoerceNumber(hours);
    if (n == null) return null;
    return n * 60;
}

function ccrDurationMinutesToHours(minutes) {
    const n = ccrCoerceNumber(minutes);
    if (n == null) return null;
    return Math.round((n / 60) * 1000) / 1000;
}

/** Comparison thresholds for Duration rules, always in minutes. */
function getCcrRuleCompareMinutes(rule, field = 'value') {
    const raw = field === 'valueTo' ? rule?.valueTo : rule?.value;
    const n = ccrCoerceNumber(raw);
    if (n == null) return null;
    if (!isCcrDurationMetric(rule?.metric)) return n;
    return getCcrDurationValueUnit(rule) === 'hours' ? n * 60 : n;
}

function ccrTimeGapUnitToHours(value, unit = 'hours') {
    const n = ccrCoerceNumber(value);
    if (n == null) return null;
    if (unit === 'minutes') return n / 60;
    if (unit === 'days') return n * 24;
    return n;
}

function ccrTimeGapHoursToUnit(hours, unit = 'hours') {
    const n = ccrCoerceNumber(hours);
    if (n == null) return '';
    if (unit === 'minutes') return String(Math.round(n * 60 * 1000) / 1000);
    if (unit === 'days') return String(Math.round((n / 24) * 1000) / 1000);
    return String(Math.round(n * 1000) / 1000);
}

function getCcrRuleCompareHours(rule, field = 'value') {
    const raw = field === 'valueTo' ? rule?.valueTo : rule?.value;
    const n = ccrCoerceNumber(raw);
    if (n == null) return null;
    return n;
}

function getCcrRuleCompareNumber(rule, field = 'value') {
    if (isCcrDurationMetric(rule?.metric)) return getCcrRuleCompareMinutes(rule, field);
    if (isCcrTimeGapMetric(rule?.metric)) return getCcrRuleCompareHours(rule, field);
    const raw = field === 'valueTo' ? rule?.valueTo : rule?.value;
    return ccrCoerceNumber(raw);
}

function getCcrDurationEditorValues(rule) {
    if (!isCcrDurationMetric(rule?.metric)) {
        return {
            value: rule?.value == null ? '' : String(rule.value),
            valueTo: rule?.valueTo == null ? '' : String(rule.valueTo)
        };
    }
    const unit = getCcrDurationValueUnit(rule);
    const toEditor = (raw) => {
        const n = ccrCoerceNumber(raw);
        if (n == null) return '';
        const hours = unit === 'hours' ? n : ccrDurationMinutesToHours(n);
        return hours == null ? '' : String(hours);
    };
    return { value: toEditor(rule.value), valueTo: toEditor(rule.valueTo) };
}

function getCcrTimeGapEditorValues(rule, data = appData) {
    if (!isCcrTimeGapMetric(rule?.metric)) {
        return {
            value: rule?.value == null ? '' : String(rule.value),
            valueTo: rule?.valueTo == null ? '' : String(rule.valueTo)
        };
    }
    const unit = getCcrMetricSettings(rule.metric, data)?.inputUnit || 'hours';
    return {
        value: ccrTimeGapHoursToUnit(rule.value, unit),
        valueTo: ccrTimeGapHoursToUnit(rule.valueTo, unit)
    };
}

function formatCcrDurationThresholdLabel(minutes) {
    const n = ccrCoerceNumber(minutes);
    if (n == null || !Number.isFinite(n) || n < 0) return '—';
    if (n === 0) return '0m';
    if (typeof formatDurationHours === 'function') return formatDurationHours(n / 60);
    const hours = n / 60;
    const h = Math.floor(hours);
    const m = Math.round((hours - h) * 60);
    if (h > 0) return m > 0 ? `${h}h ${m}m` : `${h}h`;
    return `${m}m`;
}

function formatCcrUseGapThresholdLabel(hours) {
    const n = ccrCoerceNumber(hours);
    if (n == null || !Number.isFinite(n) || n < 0) return '—';
    if (n === 0) return '0m';
    if (typeof formatBreakFromHours === 'function') return formatBreakFromHours(n);
    const totalMinutes = Math.round(n * 60);
    const days = Math.floor(totalMinutes / 1440);
    const h = Math.floor((totalMinutes % 1440) / 60);
    const m = totalMinutes % 60;
    if (days > 0) return h > 0 ? `${days}d ${h}h` : `${days}d`;
    if (h > 0) return m > 0 ? `${h}h ${m}m` : `${h}h`;
    return `${m}m`;
}

function ccrIsEmpty(value) {
    if (value == null) return true;
    if (typeof value === 'string') return value.trim() === '';
    if (Array.isArray(value)) return value.length === 0;
    return false;
}

function normalizeCcrTransactionTypeToken(value) {
    const raw = String(value ?? '').trim().toLowerCase();
    if (!raw) return '';
    const compact = raw.replace(/[\s-]+/g, '_');
    if (compact === 'gift_given' || compact === 'giftgiven') return 'gift_given';
    if (compact === 'gift_received' || compact === 'giftreceived') return 'gift_received';
    if (compact === 'inventory_adjustment' || compact === 'inventory_adj' || compact === 'adjustment') {
        return 'inventory_adjustment';
    }
    if (compact === 'shared_use' || compact === 'legacy_shared_use') return 'shared_use';
    if (compact === 'use' || compact === 'personal_use') return 'use';
    return compact;
}

function compareConditionalColorRule(rule, context = {}) {
    if (!rule || !rule.enabled) return false;
    const operator = rule.operator;
    let rawValue = context.value;
    let textValue = context.textValue != null ? String(context.textValue) : (rawValue == null ? '' : String(rawValue));
    let ruleValue = rule.value;
    if (rule.metric === 'transactionType') {
        rawValue = normalizeCcrTransactionTypeToken(rawValue);
        ruleValue = normalizeCcrTransactionTypeToken(rule.value);
        textValue = normalizeCcrTransactionTypeToken(textValue || rawValue);
    }
    const numValue = ccrCoerceNumber(rawValue);
    const compare = getCcrRuleCompareNumber(rule, 'value');
    const compareTo = getCcrRuleCompareNumber(rule, 'valueTo');
    const target = ccrCoerceNumber(context.target != null ? context.target : rule.targetValue);

    try {
        switch (operator) {
            case 'empty':
                return ccrIsEmpty(rawValue) && ccrIsEmpty(textValue);
            case 'notEmpty':
                return !ccrIsEmpty(rawValue) || !ccrIsEmpty(textValue);
            case 'true':
                return rawValue === true || rawValue === 1 || String(rawValue).toLowerCase() === 'true';
            case 'false':
                return rawValue === false || rawValue === 0 || String(rawValue).toLowerCase() === 'false';
            case 'contains':
                return textValue.toLowerCase().includes(String(ruleValue ?? '').toLowerCase());
            case 'notContains':
                return !textValue.toLowerCase().includes(String(ruleValue ?? '').toLowerCase());
            case 'eq':
                if (numValue != null && compare != null && rule.metric !== 'transactionType') {
                    return Math.abs(numValue - compare) < 1e-9;
                }
                return String(rawValue ?? '').toLowerCase() === String(ruleValue ?? '').toLowerCase();
            case 'neq':
                if (numValue != null && compare != null && rule.metric !== 'transactionType') {
                    return Math.abs(numValue - compare) >= 1e-9;
                }
                return String(rawValue ?? '').toLowerCase() !== String(ruleValue ?? '').toLowerCase();
            case 'gt':
                return numValue != null && compare != null && numValue > compare;
            case 'gte':
                return numValue != null && compare != null && numValue >= compare;
            case 'lt':
                return numValue != null && compare != null && numValue < compare;
            case 'lte':
                return numValue != null && compare != null && numValue <= compare;
            case 'between':
            case 'betweenInclusive': {
                if (numValue == null || compare == null || compareTo == null) return false;
                const lo = Math.min(compare, compareTo);
                const hi = Math.max(compare, compareTo);
                const boundary = rule.operator === 'betweenInclusive'
                    ? 'inclusive'
                    : getCcrRuleRangeBoundary(rule);
                const lowerOk = boundary === 'exclusive' || boundary === 'exclusiveInclusive'
                    ? numValue > lo
                    : numValue >= lo;
                const upperOk = boundary === 'inclusive' || boundary === 'exclusiveInclusive'
                    ? numValue <= hi
                    : numValue < hi;
                return lowerOk && upperOk;
            }
            case 'betweenExclusive': {
                if (numValue == null || compare == null || compareTo == null) return false;
                const lo = Math.min(compare, compareTo);
                const hi = Math.max(compare, compareTo);
                return numValue > lo && numValue < hi;
            }
            case 'pctAboveTarget': {
                if (numValue == null || target == null || target === 0 || compare == null) return false;
                const pctAbove = ((numValue - target) / Math.abs(target)) * 100;
                return pctAbove >= compare;
            }
            case 'pctBelowTarget': {
                if (numValue == null || target == null || target === 0 || compare == null) return false;
                const pctBelow = ((target - numValue) / Math.abs(target)) * 100;
                return pctBelow >= compare;
            }
            case 'daysSince': {
                // context.value should already be days since; rule.value is the threshold
                if (numValue == null || compare == null) return false;
                return numValue >= compare;
            }
            default:
                return false;
        }
    } catch (_) {
        return false;
    }
}

function ruleMatchesSubstanceScope(rule, substanceId) {
    const scope = rule.substanceScope;
    if (scope == null || scope === 'all') return true;
    if (!substanceId || substanceId === 'all' || substanceId === DASHBOARD_ALL) return true;
    if (Array.isArray(scope)) {
        return scope.some(id => String(id) === String(substanceId));
    }
    return String(scope) === String(substanceId);
}

function ruleMatchesSectionScope(rule, section) {
    const scope = rule.sectionScope || ['all'];
    if (!scope.length || scope.includes('all')) return true;
    if (!section) return true;
    return scope.includes(section);
}

function ruleMatchesMetric(rule, metric) {
    if (!metric) return true;
    return migrateCcrMetricKey(rule.metric) === migrateCcrMetricKey(metric);
}

function getCcrRuleSpecificityScore(rule) {
    if (!rule) return 0;
    let score = 0;
    const substanceScope = rule.substanceScope;
    const sectionScope = rule.sectionScope || [];
    if (substanceScope && substanceScope !== 'all') {
        score += Array.isArray(substanceScope) ? Math.min(3, substanceScope.length) : 3;
    }
    if (sectionScope.length && !sectionScope.includes('all')) score += Math.min(3, sectionScope.length);
    if (rule.metric && rule.metric !== 'all') score += 2;
    if (normalizeCcrVisualTarget(rule.visualTarget) !== 'value') score += 1;
    if (rule.operator === 'between' || rule.operator === 'eq') score += 1;
    return score;
}

function compareCcrRulePrecedence(a, b) {
    const pa = Number(a?.priority) || 0;
    const pb = Number(b?.priority) || 0;
    if (pa !== pb) return pb - pa;
    const sa = getCcrRuleSpecificityScore(a);
    const sb = getCcrRuleSpecificityScore(b);
    if (sa !== sb) return sb - sa;
    const ca = Date.parse(a?.createdAt || '') || 0;
    const cb = Date.parse(b?.createdAt || '') || 0;
    if (ca !== cb) return ca - cb;
    return String(a?.id || '').localeCompare(String(b?.id || ''));
}

function formatCcrPrecedenceLabel(rule) {
    return `Priority ${Number(rule?.priority) || 0} · Specificity ${getCcrRuleSpecificityScore(rule)} · Created ${formatCcrLastModifiedLabel(rule?.createdAt)}`;
}

/**
 * Shared evaluation engine.
 * context: { substanceId, section, metric, value, textValue, target, dateValue }
 * Returns presentation styles only — never mutates underlying data.
 */
function evaluateConditionalColorRules(context = {}, data = appData) {
    const state = ensureConditionalColorRules(data);
    const empty = {
        matched: [],
        style: null,
        className: '',
        labels: [],
        cssText: '',
        attrs: ''
    };
    if (!state.enabled) return empty;

    const rules = (state.rules || [])
        .filter(r => r && r.enabled)
        .slice()
        .sort(compareCcrRulePrecedence);

    const matched = [];
    let style = null;
    const contextTarget = normalizeCcrVisualTarget(context.visualTarget || 'value');

    for (const rule of rules) {
        if (rule.createdByUser !== true) continue;
        if (normalizeCcrVisualTarget(rule.visualTarget) !== contextTarget) continue;
        if (!ruleMatchesSubstanceScope(rule, context.substanceId)) continue;
        if (!ruleMatchesSectionScope(rule, context.section)) continue;
        if (!ruleMatchesMetric(rule, context.metric)) continue;
        if (context.value === undefined && !['empty', 'notEmpty', 'true', 'false'].includes(rule.operator)) {
            // Missing metric values are ignored unless emptiness operators are used.
            continue;
        }
        if (!compareConditionalColorRule(rule, context)) continue;

        matched.push(rule);
        if (!style) {
            style = {
                background: normalizeCcrVisualTarget(rule.visualTarget) === 'border' ? '' : rule.colors.background,
                text: normalizeCcrVisualTarget(rule.visualTarget) === 'border' ? '' : rule.colors.text,
                border: rule.colors.border || rule.colors.accent,
                accent: rule.colors.accent || rule.colors.border
            };
        } else {
            // Higher priority already applied; lower-priority rules may fill missing slots only.
            if (normalizeCcrVisualTarget(rule.visualTarget) !== 'border') {
                style.background = style.background || rule.colors.background;
                style.text = style.text || rule.colors.text;
            }
            style.border = style.border || rule.colors.border || rule.colors.accent;
            style.accent = style.accent || rule.colors.accent || rule.colors.border;
        }
        if (rule.stopProcessing) break;
    }

    if (!matched.length) return empty;

    const labels = matched
        .map(r => (r.statusLabel || '').trim())
        .filter(Boolean)
        .filter((v, i, arr) => arr.indexOf(v) === i);

    const cssText = style
        ? [
            style.background ? `background:${style.background}` : '',
            style.text ? `color:${style.text}` : '',
            style.border ? `border-color:${style.border}` : ''
        ].filter(Boolean).join(';')
        : '';

    const attrs = cssText
        ? ` class="ccr-applied" style="${escapeAttr(cssText)}" data-ccr-labels="${escapeAttr(labels.join(', '))}"`
        : ' class="ccr-applied"';

    return {
        matched,
        style,
        className: 'ccr-applied',
        labels,
        cssText,
        attrs
    };
}

function buildConditionalColorInlineStyle(result) {
    if (!result?.style) return '';
    const s = result.style;
    return [
        s.background ? `background:${s.background}` : '',
        s.text ? `color:${s.text}` : '',
        s.border ? `border:1px solid ${s.border}` : ''
    ].filter(Boolean).join(';');
}

/** Row-level CCR for Use History (Gift Given / Gift Received presets + custom overrides). */
function evaluateUseHistoryRowConditionalColor(entry, substanceId = null, data = appData) {
    if (!entry || typeof evaluateConditionalColorRules !== 'function') return null;
    const tx = typeof getLogTransactionType === 'function'
        ? getLogTransactionType(entry)
        : (entry.transactionType || 'use');
    const sid = substanceId || (typeof getUseSubstanceId === 'function'
        ? getUseSubstanceId(entry, data)
        : entry.substanceId);
    const contexts = [{
        substanceId: sid,
        section: 'useHistory',
        visualTarget: 'row',
        metric: 'transactionType',
        value: tx,
        textValue: tx,
        log: entry
    }];
    const amount = typeof getLogStatsAmount === 'function' ? getLogStatsAmount(entry) : ccrCoerceNumber(entry.amount);
    if (amount != null) contexts.push({ substanceId: sid, section: 'useHistory', visualTarget: 'row', metric: 'useAmount', value: amount, log: entry });
    const duration = typeof getNormalizedSessionDurationMinutes === 'function' ? getNormalizedSessionDurationMinutes(entry) : null;
    if (duration != null) contexts.push({ substanceId: sid, section: 'useHistory', visualTarget: 'row', metric: 'sessionDuration', value: duration, log: entry });
    const gph = typeof getNormalizedGramsPerHour === 'function' ? getNormalizedGramsPerHour(entry) : null;
    if (gph != null && Number.isFinite(gph)) contexts.push({ substanceId: sid, section: 'useHistory', visualTarget: 'row', metric: 'gramsPerHour', value: gph, log: entry });
    const breakHours = typeof computeBreakSincePreviousUseHours === 'function' ? computeBreakSincePreviousUseHours(entry, data) : null;
    if (breakHours != null && Number.isFinite(breakHours)) contexts.push({ substanceId: sid, section: 'useHistory', visualTarget: 'row', metric: 'useGapPrevious', value: breakHours, log: entry });

    const results = contexts.map(ctx => evaluateConditionalColorRules(ctx, data)).filter(r => r?.matched?.length);
    if (!results.length) return { matched: [], style: null, className: '', labels: [], cssText: '', attrs: '' };
    const matched = results.flatMap(r => r.matched || []);
    const style = results.reduce((acc, result) => {
        if (!result.style) return acc;
        if (!acc) return { ...result.style };
        acc.background = acc.background || result.style.background;
        acc.text = acc.text || result.style.text;
        acc.border = acc.border || result.style.border;
        acc.accent = acc.accent || result.style.accent;
        return acc;
    }, null);
    const labels = matched
        .map(r => (r.statusLabel || '').trim())
        .filter(Boolean)
        .filter((v, i, arr) => arr.indexOf(v) === i);
    return { matched, style, className: style ? 'ccr-row-colored' : '', labels, cssText: '', attrs: '' };
}

function buildUseHistoryRowInlineStyle(ccrResult) {
    if (!ccrResult?.matched?.length || !ccrResult.style) return '';
    const s = ccrResult.style;
    const parts = [];
    if (s.background) {
        parts.push(`--ccr-row-bg:${s.background}`);
    }
    if (s.border) {
        parts.push(`--ccr-row-border:${s.border}`);
    }
    if (s.accent && !s.border) {
        parts.push(`--ccr-row-border:${s.accent}`);
    }
    if (s.text) {
        parts.push(`--ccr-row-text:${s.text}`);
    }
    return parts.join(';');
}

function getUseHistoryRowColorClassNames(entry, ccrResult) {
    const classes = [];
    if (ccrResult?.matched?.length && buildUseHistoryRowInlineStyle(ccrResult)) classes.push('ccr-row-colored');
    return classes;
}

function renderConditionalColorLabels(result, { fallbackLabel = '' } = {}) {
    const labels = (result?.labels || []).filter(Boolean);
    // Only explicit rule status labels — never invent text from rule names or fallbacks.
    if (!labels.length) return '';
    return labels.map(label => {
        const style = buildConditionalColorInlineStyle(result);
        return `<span class="ccr-status-label status-badge"${style ? ` style="${escapeAttr(style)}"` : ''}>${escapeHtml(label)}</span>`;
    }).join(' ');
}

function wrapWithConditionalColor(innerHtml, result, { keepLabel = true, fallbackLabel = '' } = {}) {
    if (!result?.matched?.length) return innerHtml;
    const style = buildConditionalColorInlineStyle(result);
    const labelsHtml = keepLabel ? renderConditionalColorLabels(result) : '';
    return `<span class="ccr-wrap"${style ? ` style="${escapeAttr(style)}"` : ''}>${innerHtml}${labelsHtml ? ` ${labelsHtml}` : ''}</span>`;
}

function applyConditionalColorToElement(el, result) {
    if (!el || !result?.matched?.length || !result.style) return;
    if (result.style.background) el.style.background = result.style.background;
    if (result.style.text) el.style.color = result.style.text;
    if (result.style.border) el.style.borderColor = result.style.border;
    el.classList.add('ccr-applied');
    if (result.labels?.length) el.setAttribute('data-ccr-labels', result.labels.join(', '));
}

function evaluateUsageVsTargetColors(used, target, options = {}, data = appData) {
    if (target == null || !(target > 0) || used == null) {
        return evaluateConditionalColorRules({
            ...options,
            metric: options.metric || 'useVsTarget',
            value: undefined
        }, data);
    }
    const ratio = used / target;
    return evaluateConditionalColorRules({
        substanceId: options.substanceId,
        section: options.section || 'status',
        metric: options.metric || 'useVsTarget',
        value: ratio,
        target
    }, data);
}

function evaluateInventoryColors(percentRemaining, options = {}, data = appData) {
    if (percentRemaining == null || Number.isNaN(Number(percentRemaining))) {
        return evaluateConditionalColorRules({
            ...options,
            metric: 'inventoryPercent',
            value: undefined
        }, data);
    }
    return evaluateConditionalColorRules({
        substanceId: options.substanceId,
        section: options.section || 'inventory',
        metric: 'inventoryPercent',
        value: Number(percentRemaining)
    }, data);
}

function evaluateTaperColors(planned, actual, status, options = {}, data = appData) {
    const results = [];
    if (planned != null && planned > 0 && actual != null) {
        results.push(evaluateConditionalColorRules({
            substanceId: options.substanceId,
            section: options.section || 'taper',
            metric: 'taperPlannedVsActual',
            value: actual / planned,
            target: planned
        }, data));
    }
    if (status != null && status !== '') {
        results.push(evaluateConditionalColorRules({
            substanceId: options.substanceId,
            section: options.section || 'taper',
            metric: 'taperStatus',
            value: status,
            textValue: status
        }, data));
    }
    const matched = results.flatMap(r => r.matched || []);
    if (!matched.length) {
        return {
            matched: [],
            style: null,
            className: '',
            labels: [],
            cssText: '',
            attrs: ''
        };
    }
    const style = results.find(r => r.style)?.style || null;
    const labels = matched
        .map(r => (r.statusLabel || '').trim())
        .filter(Boolean)
        .filter((v, i, a) => a.indexOf(v) === i);
    const cssText = style
        ? [
            style.background ? `background:${style.background}` : '',
            style.text ? `color:${style.text}` : '',
            style.border ? `border-color:${style.border}` : ''
        ].filter(Boolean).join(';')
        : '';
    return { matched, style, className: 'ccr-applied', labels, cssText, attrs: '' };
}

function evaluateSpendColors(amount, options = {}, data = appData) {
    return evaluateConditionalColorRules({
        substanceId: options.substanceId,
        section: options.section || 'spending',
        metric: 'spend',
        value: amount
    }, data);
}

function saveConditionalColorRule(rule, data = appData) {
    const state = ensureConditionalColorRules(data);
    const existing = state.rules.find(r => r.id === rule?.id);
    const normalized = normalizeConditionalColorRule({
        ...(existing ? { createdAt: existing.createdAt } : {}),
        ...rule,
        lastModified: new Date().toISOString()
    }, state.rules.length);
    if (!normalized) return null;
    const idx = state.rules.findIndex(r => r.id === normalized.id);
    if (idx >= 0) state.rules[idx] = normalized;
    else state.rules.push(normalized);
    persistConditionalColorRulesState({ rules: state.rules }, data);
    invalidateConditionalColorRuleMatchCache();
    return normalized;
}

function deleteConditionalColorRule(ruleId, data = appData) {
    const state = ensureConditionalColorRules(data);
    state.rules = state.rules.filter(r => r.id !== ruleId);
    persistConditionalColorRulesState({ rules: state.rules }, data);
    invalidateConditionalColorRuleMatchCache();
    return state.rules;
}

function duplicateConditionalColorRule(ruleId, data = appData) {
    const state = ensureConditionalColorRules(data);
    const src = state.rules.find(r => r.id === ruleId);
    if (!src) return null;
    const copy = normalizeConditionalColorRule({
        ...src,
        id: ccrNewId(),
        name: `${src.name} (copy)`,
        isPreset: false,
        presetId: null,
        createdAt: new Date().toISOString(),
        priority: (Number(src.priority) || 0) + 1,
        lastModified: new Date().toISOString()
    });
    state.rules.push(copy);
    persistConditionalColorRulesState({ rules: state.rules }, data);
    invalidateConditionalColorRuleMatchCache();
    return copy;
}

function setConditionalColorRuleEnabled(ruleId, enabled, data = appData) {
    const state = ensureConditionalColorRules(data);
    const rule = state.rules.find(r => r.id === ruleId);
    if (!rule) return null;
    rule.enabled = !!enabled;
    rule.lastModified = new Date().toISOString();
    persistConditionalColorRulesState({ rules: state.rules }, data);
    invalidateConditionalColorRuleMatchCache();
    return rule;
}

function reorderConditionalColorRule(ruleId, direction, data = appData) {
    const state = ensureConditionalColorRules(data);
    const sorted = state.rules.slice().sort((a, b) => (Number(b.priority) || 0) - (Number(a.priority) || 0));
    const idx = sorted.findIndex(r => r.id === ruleId);
    if (idx < 0) return state.rules;
    const swapWith = direction < 0 ? idx - 1 : idx + 1;
    if (swapWith < 0 || swapWith >= sorted.length) return state.rules;
    const a = sorted[idx];
    const b = sorted[swapWith];
    const tmp = a.priority;
    a.priority = b.priority;
    b.priority = tmp;
    if (a.priority === b.priority) {
        a.priority = (Number(a.priority) || 0) + (direction < 0 ? 1 : -1);
    }
    a.lastModified = new Date().toISOString();
    b.lastModified = a.lastModified;
    persistConditionalColorRulesState({ rules: sorted }, data);
    invalidateConditionalColorRuleMatchCache();
    return sorted;
}

function resetConditionalColorRulesToPresets(data = appData) {
    const theme = (typeof resolvedTheme !== 'undefined' ? resolvedTheme : 'dark') || 'dark';
    const state = getDefaultConditionalColorRulesState(theme);
    state.rules = state.rules.map((r, i) => normalizeConditionalColorRule({
        ...r,
        lastModified: new Date().toISOString()
    }, i));
    data.settings[ccrStorageKey()] = state;
    if (typeof saveData === 'function') saveData(data);
    invalidateConditionalColorRuleMatchCache();
    return state;
}

function exportConditionalColorRulesJson(data = appData) {
    const state = ensureConditionalColorRules(data);
    return JSON.stringify({
        app: 'recovery-tracker-conditional-color-rules',
        version: state.version || 1,
        exportedAt: new Date().toISOString(),
        enabled: state.enabled,
        metricSettings: state.metricSettings || {},
        customGroups: state.customGroups || [],
        ui: state.ui || {},
        rules: state.rules
    }, null, 2);
}

function importConditionalColorRulesJson(jsonText, data = appData, { replace = false } = {}) {
    let parsed;
    try {
        parsed = typeof jsonText === 'string' ? JSON.parse(jsonText) : jsonText;
    } catch (_) {
        throw new Error('Invalid JSON for conditional color rules.');
    }
    const incoming = Array.isArray(parsed)
        ? parsed
        : (Array.isArray(parsed?.rules) ? parsed.rules : null);
    if (!incoming) throw new Error('No rules array found in import file.');
    const normalized = incoming.map((r, i) => normalizeConditionalColorRule(r, i)).filter(Boolean);
    if (!normalized.length) throw new Error('No valid rules in import file.');
    const state = ensureConditionalColorRules(data);
    const metricSettings = normalizeCcrMetricSettingsMap(parsed?.metricSettings || {});
    if (replace) {
        state.rules = normalized;
        state.metricSettings = metricSettings;
    } else {
        const existingIds = new Set(state.rules.map(r => r.id));
        normalized.forEach(rule => {
            if (existingIds.has(rule.id)) rule.id = ccrNewId();
            state.rules.push(rule);
        });
        state.metricSettings = { ...(state.metricSettings || {}), ...metricSettings };
    }
    if (parsed && typeof parsed === 'object' && parsed.enabled != null) {
        state.enabled = !!parsed.enabled;
    }
    persistConditionalColorRulesState({ rules: state.rules, enabled: state.enabled, metricSettings: state.metricSettings }, data);
    invalidateConditionalColorRuleMatchCache();
    return state;
}

function setConditionalColorRulesEnabled(enabled, data = appData) {
    return persistConditionalColorRulesState({ enabled: !!enabled }, data);
}

// ——— Color Rule Manager (central CCR management) ———

const CCR_MANAGER_SORT_OPTIONS = Object.freeze([
    { id: 'priority', label: 'Priority' },
    { id: 'name', label: 'Name' },
    { id: 'metric', label: 'Metric' },
    { id: 'substance', label: 'Substance' },
    { id: 'rangeLower', label: 'Range (lower bound)' },
    { id: 'lastModified', label: 'Last Modified' }
]);

const CCR_SECTION_USAGE_LABELS = Object.freeze({
    dashboard: 'Dashboard',
    status: 'Status badges',
    useHistory: 'Use History',
    inventory: 'Inventory',
    purchaseHistory: 'Purchase History',
    insights: 'Insights',
    spending: 'Spending Summary',
    taper: 'Weekly Taper',
    calendar: 'Calendar',
    all: 'All sections'
});

let ccrManagerUiState = {
    search: '',
    substance: 'all',
    section: 'all',
    metric: 'all',
    enabled: 'all',
    groupBy: 'metric',
    sort: 'priority',
    sortDir: 'desc',
    selectedIds: []
};

let ccrMatchCountCache = { key: '', counts: Object.create(null) };
let ccrDragRuleId = null;

function invalidateConditionalColorRuleMatchCache() {
    ccrMatchCountCache = { key: '', counts: Object.create(null) };
}

function getCcrManagerUiState() {
    if (!ccrManagerUiState.selectedIds) ccrManagerUiState.selectedIds = [];
    return ccrManagerUiState;
}

function setCcrManagerFilters(patch = {}) {
    const state = getCcrManagerUiState();
    Object.assign(state, patch);
    if (patch.selectedIds) state.selectedIds = [...patch.selectedIds];
    return state;
}

function formatCcrConditionSummary(rule) {
    if (!rule) return '—';
    const metricDef = getCcrMetricUiDef(rule.metric) || getCcrMetricDef(rule.metric);
    const metricName = metricDef?.label || rule.metric;
    const op = CCR_OPERATORS.find(o => o.id === rule.operator);
    const opLabel = op?.label || rule.operator;
    if (isCcrDurationMetric(rule.metric)) {
        const lo = formatCcrDurationThresholdLabel(getCcrRuleCompareMinutes(rule, 'value'));
        const hi = formatCcrDurationThresholdLabel(getCcrRuleCompareMinutes(rule, 'valueTo'));
        switch (rule.operator) {
            case 'lt':
                return `Duration less than ${lo}`;
            case 'lte':
                return `Duration at most ${lo}`;
            case 'gt':
                return `Duration greater than ${lo}`;
            case 'gte':
                return `Duration at least ${lo}`;
            case 'eq':
                return `Duration equals ${lo}`;
            case 'neq':
                return `Duration not ${lo}`;
            case 'between':
            case 'betweenInclusive':
                return `Duration between ${lo} and ${hi}`;
            case 'betweenExclusive':
                return `Duration between ${lo} and ${hi} (exclusive)`;
            case 'empty':
                return 'Duration empty';
            case 'notEmpty':
                return 'Duration not empty';
            default:
                break;
        }
    }
    if (isCcrTimeGapMetric(rule.metric)) {
        const lo = formatCcrUseGapThresholdLabel(getCcrRuleCompareHours(rule, 'value'));
        const hi = formatCcrUseGapThresholdLabel(getCcrRuleCompareHours(rule, 'valueTo'));
        const prefix = String(metricName).replace(/^Use Gap\s*→\s*/i, 'Use Gap: ');
        switch (rule.operator) {
            case 'lt':
                return `${prefix} · Less than ${lo}`;
            case 'lte':
                return `${prefix} · At most ${lo}`;
            case 'gt':
                return `${prefix} · Greater than ${lo}`;
            case 'gte':
                return `${prefix} · At least ${lo}`;
            case 'eq':
                return `${prefix} · Equals ${lo}`;
            case 'neq':
                return `${prefix} · Not ${lo}`;
            case 'between':
            case 'betweenInclusive':
                return `${prefix} · Between ${lo} and ${hi}`;
            case 'betweenExclusive':
                return `${prefix} · Between ${lo} and ${hi} (exclusive)`;
            case 'empty':
                return `${prefix} · Empty`;
            case 'notEmpty':
                return `${prefix} · Not empty`;
            default:
                break;
        }
    }
    if (rule.operator === 'between' || rule.operator === 'betweenInclusive' || rule.operator === 'betweenExclusive') {
        const boundary = getCcrRuleRangeBoundary(rule);
        const lower = boundary === 'exclusive' || boundary === 'exclusiveInclusive' ? '<' : '<=';
        const upper = boundary === 'inclusive' || boundary === 'exclusiveInclusive' ? '<=' : '<';
        return `${rule.value ?? '—'} ${lower} value ${upper} ${rule.valueTo ?? '—'}`;
    }
    if (rule.operator === 'empty' || rule.operator === 'notEmpty'
        || rule.operator === 'true' || rule.operator === 'false') {
        return opLabel;
    }
    if (rule.operator === 'pctAboveTarget' || rule.operator === 'pctBelowTarget') {
        return `${opLabel} ${rule.value ?? '—'}% (target ${rule.targetValue ?? '—'})`;
    }
    return `${opLabel} ${rule.value ?? ''}`.trim();
}

function formatCcrSubstanceScopeLabel(rule, data = appData) {
    const scope = rule?.substanceScope;
    if (scope == null || scope === 'all') return 'All substances';
    const ids = Array.isArray(scope) ? scope : [scope];
    return ids.map(id => {
        const sub = (data.substances || []).find(s => s.id === id);
        return sub?.name || id;
    }).join(', ') || 'All substances';
}

function formatCcrSectionScopeLabel(rule) {
    const scope = rule?.sectionScope || ['all'];
    if (!scope.length || scope.includes('all')) return 'All sections';
    return scope.map(id => CCR_SECTION_USAGE_LABELS[id] || id).join(', ');
}

function getConditionalColorRuleUsage(rule) {
    const scope = rule?.sectionScope || ['all'];
    if (!scope.length || scope.includes('all')) {
        return Object.keys(CCR_SECTION_USAGE_LABELS)
            .filter(id => id !== 'all')
            .map(id => ({ id, label: CCR_SECTION_USAGE_LABELS[id], used: true }));
    }
    return Object.keys(CCR_SECTION_USAGE_LABELS)
        .filter(id => id !== 'all')
        .map(id => ({
            id,
            label: CCR_SECTION_USAGE_LABELS[id],
            used: scope.includes(id)
        }));
}

function scopesOverlapSubstances(a, b) {
    if (a == null || a === 'all' || b == null || b === 'all') return true;
    const aa = Array.isArray(a) ? a.map(String) : [String(a)];
    const bb = Array.isArray(b) ? b.map(String) : [String(b)];
    return aa.some(id => bb.includes(id));
}

function scopesOverlapSections(a, b) {
    const aa = (!a || !a.length || a.includes('all')) ? null : a;
    const bb = (!b || !b.length || b.includes('all')) ? null : b;
    if (!aa || !bb) return true;
    return aa.some(id => bb.includes(id));
}

function ccrNumericRange(rule) {
    const v = getCcrRuleCompareNumber(rule, 'value');
    const v2 = getCcrRuleCompareNumber(rule, 'valueTo');
    switch (rule.operator) {
        case 'eq':
            return v == null ? null : { lo: v, hi: v, loExclusive: false, hiExclusive: false };
        case 'gt':
            return v == null ? null : { lo: v, hi: Infinity, loExclusive: true, hiExclusive: true };
        case 'gte':
            return v == null ? null : { lo: v, hi: Infinity, loExclusive: false, hiExclusive: true };
        case 'lt':
            return v == null ? null : { lo: -Infinity, hi: v, loExclusive: true, hiExclusive: true };
        case 'lte':
            return v == null ? null : { lo: -Infinity, hi: v, loExclusive: true, hiExclusive: false };
        case 'between':
        case 'betweenInclusive': {
            if (v == null || v2 == null) return null;
            const boundary = rule.operator === 'betweenInclusive'
                ? 'inclusive'
                : getCcrRuleRangeBoundary(rule);
            return {
                lo: Math.min(v, v2),
                hi: Math.max(v, v2),
                loExclusive: boundary === 'exclusive' || boundary === 'exclusiveInclusive',
                hiExclusive: boundary === 'exclusive' || boundary === 'inclusiveExclusive'
            };
        }
        case 'betweenExclusive': {
            if (v == null || v2 == null) return null;
            return {
                lo: Math.min(v, v2),
                hi: Math.max(v, v2),
                loExclusive: true,
                hiExclusive: true
            };
        }
        case 'pctAboveTarget':
        case 'pctBelowTarget':
        case 'daysSince':
            return v == null ? null : { lo: v, hi: Infinity, loExclusive: false, hiExclusive: true };
        default:
            return null;
    }
}

/** True only when two numeric ranges share at least one matching value. Adjacent non-overlapping bounds are not conflicts. */
function ccrRangesOverlap(a, b) {
    if (!a || !b) return false;
    if (a.hi < b.lo || b.hi < a.lo) return false;
    if (a.hi === b.lo) {
        if (!Number.isFinite(a.hi)) return true;
        return !a.hiExclusive && !b.loExclusive;
    }
    if (b.hi === a.lo) {
        if (!Number.isFinite(a.lo)) return true;
        return !b.hiExclusive && !a.loExclusive;
    }
    return true;
}

function ccrRangeOverlapPoint(a, b) {
    if (!ccrRangesOverlap(a, b)) return null;
    if (a.hi === b.lo && Number.isFinite(a.hi)) return a.hi;
    if (b.hi === a.lo && Number.isFinite(b.hi)) return b.hi;
    const lo = Math.max(a.lo, b.lo);
    const hi = Math.min(a.hi, b.hi);
    if (Number.isFinite(lo)) return lo;
    if (Number.isFinite(hi)) return hi;
    return null;
}

function ccrRangesTouchBoundary(a, b) {
    if (!a || !b || ccrRangesOverlap(a, b)) return false;
    if (a.hi === b.lo && Number.isFinite(a.hi)) return true;
    if (b.hi === a.lo && Number.isFinite(b.hi)) return true;
    return false;
}

function ccrRangeTouchPoint(a, b) {
    if (!ccrRangesTouchBoundary(a, b)) return null;
    if (a.hi === b.lo && Number.isFinite(a.hi)) return a.hi;
    if (b.hi === a.lo && Number.isFinite(b.hi)) return b.hi;
    return null;
}

function getCcrRangeRelationship(a, b) {
    if (ccrRangesOverlap(a, b)) {
        return { state: 'overlap', label: 'Overlaps', level: 'red', value: ccrRangeOverlapPoint(a, b) };
    }
    if (ccrRangesTouchBoundary(a, b)) {
        return { state: 'touch', label: 'Touches boundary', level: 'yellow', value: ccrRangeTouchPoint(a, b) };
    }
    return { state: 'none', label: 'No overlap', level: 'green', value: null };
}

function buildCcrConflictEntry(otherRule, overlapValue = null, state = 'overlap') {
    const valueText = overlapValue == null ? 'an overlapping range' : `value ${formatAmount(overlapValue)}`;
    const isTouch = state === 'touch';
    return {
        ...otherRule,
        relationship: isTouch ? 'touch' : 'overlap',
        severity: isTouch ? 'warning' : 'error',
        conflictAt: overlapValue,
        message: isTouch
            ? `Touches boundary with '${otherRule.name}' at ${valueText}.`
            : `Overlaps with '${otherRule.name}' at ${valueText}.`
    };
}

function summarizeCcrRuleRelationship(rule, rules = null, data = appData) {
    const list = (rules || getConditionalColorRules(data)).filter(r => r && r.id !== rule?.id && r.enabled && rule?.enabled);
    let hasTouch = null;
    for (const other of list) {
        if (rule.metric !== other.metric) continue;
        if (normalizeCcrVisualTarget(rule.visualTarget) !== normalizeCcrVisualTarget(other.visualTarget)) continue;
        if (!scopesOverlapSubstances(rule.substanceScope, other.substanceScope)) continue;
        if (!scopesOverlapSections(rule.sectionScope, other.sectionScope)) continue;
        const rangeA = ccrNumericRange(rule);
        const rangeB = ccrNumericRange(other);
        if (!rangeA || !rangeB) continue;
        const relationship = getCcrRangeRelationship(rangeA, rangeB);
        if (relationship.state === 'overlap') return { ...relationship, other };
        if (relationship.state === 'touch' && !hasTouch) hasTouch = { ...relationship, other };
    }
    return hasTouch || { state: 'none', label: 'No overlap', level: 'green', value: null, other: null };
}

/**
 * Detect rules that share metric + substance + section with overlapping conditions.
 */
function detectConditionalColorRuleConflicts(rules = null, data = appData) {
    const list = (rules || getConditionalColorRules(data)).slice();
    const byId = Object.create(null);
    list.forEach(rule => { byId[rule.id] = []; });
    const meta = list.map(rule => ({
        rule,
        enabled: !!rule?.enabled,
        metric: rule?.metric,
        target: normalizeCcrVisualTarget(rule?.visualTarget),
        range: ccrNumericRange(rule)
    }));

    for (let i = 0; i < meta.length; i++) {
        const ma = meta[i];
        if (!ma.enabled) continue;
        for (let j = i + 1; j < meta.length; j++) {
            const mb = meta[j];
            if (!mb.enabled) continue;
            const a = ma.rule;
            const b = mb.rule;
            if (!a || !b) continue;
            if (ma.metric !== mb.metric) continue;
            if (ma.target !== mb.target) continue;
            if (!scopesOverlapSubstances(a.substanceScope, b.substanceScope)) continue;
            if (!scopesOverlapSections(a.sectionScope, b.sectionScope)) continue;
            if (a.operator === 'contains' || b.operator === 'contains'
                || a.operator === 'empty' || b.operator === 'empty'
                || a.operator === 'notEmpty' || b.operator === 'notEmpty'
                || a.operator === 'true' || b.operator === 'true'
                || a.operator === 'false' || b.operator === 'false') {
                if (a.operator === b.operator) {
                    byId[a.id].push(buildCcrConflictEntry(b));
                    byId[b.id].push(buildCcrConflictEntry(a));
                }
                continue;
            }
            if (ccrRangesOverlap(ma.range, mb.range)) {
                const overlap = ccrRangeOverlapPoint(ma.range, mb.range);
                byId[a.id].push(buildCcrConflictEntry(b, overlap));
                byId[b.id].push(buildCcrConflictEntry(a, overlap));
            }
        }
    }
    return byId;
}

function buildConditionalColorRuleMatchContexts(data = appData, { maxSamples = 200 } = {}) {
    const contexts = [];
    const push = (ctx) => {
        if (contexts.length < maxSamples) contexts.push(ctx);
    };
    (data.logs || []).slice(-80).forEach(log => {
        const amount = parseFloat(log.amount);
        if (Number.isFinite(amount)) {
            push({
                substanceId: log.substanceId,
                section: 'useHistory',
                metric: 'useAmount',
                value: amount
            });
        }
        const durationMinutes = typeof getNormalizedSessionDurationMinutes === 'function'
            ? getNormalizedSessionDurationMinutes(log)
            : null;
        if (durationMinutes != null) {
            push({
                substanceId: log.substanceId,
                section: 'useHistory',
                metric: 'sessionDuration',
                value: durationMinutes,
                log
            });
        }
        const gph = typeof getNormalizedGramsPerHour === 'function'
            ? getNormalizedGramsPerHour(log)
            : null;
        if (gph != null && Number.isFinite(gph)) {
            push({
                substanceId: log.substanceId,
                section: 'useHistory',
                metric: 'gramsPerHour',
                value: gph,
                log
            });
        }
        const breakHours = typeof computeBreakSincePreviousUseHours === 'function'
            ? computeBreakSincePreviousUseHours(log, data)
            : null;
        if (breakHours != null && Number.isFinite(breakHours)) {
            push({
                substanceId: log.substanceId,
                section: 'useHistory',
                metric: 'useGapPrevious',
                value: breakHours,
                log
            });
        }
        if (log.transactionType) {
            push({
                substanceId: log.substanceId,
                section: 'useHistory',
                metric: 'transactionType',
                value: log.transactionType,
                textValue: String(log.transactionType)
            });
        }
    });
    (data.purchases || []).slice(-80).forEach(p => {
        const spend = typeof getPurchaseSpendAmount === 'function' ? getPurchaseSpendAmount(p) : parseFloat(p.totalCost);
        if (Number.isFinite(spend)) {
            push({
                substanceId: getPurchaseSubstanceId(p),
                section: 'spending',
                metric: 'spend',
                value: spend
            });
        }
        const pct = typeof getPurchasePercentRemaining === 'function'
            ? getPurchasePercentRemaining(p)
            : null;
        if (pct != null && Number.isFinite(Number(pct))) {
            push({
                substanceId: getPurchaseSubstanceId(p),
                section: 'inventory',
                metric: 'inventoryPercent',
                value: Number(pct)
            });
        }
    });
    // Lightweight synthetic contexts so presets still produce match stats when data is sparse
    push({ substanceId: 'all', section: 'dashboard', metric: 'useVsTarget', value: 0.5, target: 1 });
    push({ substanceId: 'all', section: 'dashboard', metric: 'useVsTarget', value: 0.85, target: 1 });
    push({ substanceId: 'all', section: 'dashboard', metric: 'useVsTarget', value: 1.2, target: 1 });
    push({ substanceId: 'all', section: 'taper', metric: 'taperPlannedVsActual', value: 0.8, target: 1 });
    push({ substanceId: 'all', section: 'taper', metric: 'taperPlannedVsActual', value: 1.3, target: 1 });
    (data.substances || []).forEach(sub => {
        const gap = computeCurrentUseGapHours(sub.id, data);
        if (gap != null) {
            push({ substanceId: sub.id, section: 'dashboard', metric: 'useGapCurrent', value: gap });
        }
    });
    push({ substanceId: 'all', section: 'dashboard', metric: 'useGapCurrent', value: 48 });
    return contexts;
}

function getCcrMatchCountCacheKey(data = appData) {
    const state = data?.settings?.[ccrStorageKey()] || {};
    return [
        (data.logs || []).length,
        (data.purchases || []).length,
        (state.rules || []).length,
        state.enabled === false ? 0 : 1,
        (state.rules || []).map(r => `${r.id}:${r.enabled}:${r.priority}:${r.metric}:${r.operator}:${r.value}`).join('|')
    ].join('::');
}

/**
 * Count how many sampled records currently match each rule.
 * Reuses compareConditionalColorRule — does not re-implement condition logic.
 */
function computeConditionalColorRuleMatchCounts(data = appData, options = {}) {
    const key = getCcrMatchCountCacheKey(data);
    if (!options.force && ccrMatchCountCache.key === key) {
        return { ...ccrMatchCountCache.counts };
    }
    const rules = getConditionalColorRules(data);
    const counts = Object.create(null);
    rules.forEach(r => { counts[r.id] = 0; });
    const contexts = buildConditionalColorRuleMatchContexts(data, options);
    contexts.forEach(ctx => {
        rules.forEach(rule => {
            if (!rule.enabled) return;
            if (!ruleMatchesSubstanceScope(rule, ctx.substanceId)) return;
            if (!ruleMatchesSectionScope(rule, ctx.section)) return;
            if (!ruleMatchesMetric(rule, ctx.metric)) return;
            if (compareConditionalColorRule(rule, ctx)) counts[rule.id] += 1;
        });
    });
    ccrMatchCountCache = { key, counts: { ...counts } };
    return counts;
}

function getConditionalColorRuleMatchCount(ruleId, data = appData) {
    const counts = computeConditionalColorRuleMatchCounts(data);
    return counts[ruleId] || 0;
}

function filterAndSortConditionalColorRules(rules, filters = getCcrManagerUiState(), data = appData) {
    const search = String(filters.search || '').trim().toLowerCase();
    let list = (rules || []).slice();

    if (search) {
        list = list.filter(rule => {
            const hay = [
                rule.name,
                rule.metric,
                rule.operator,
                formatCcrConditionSummary(rule),
                formatCcrSubstanceScopeLabel(rule, data),
                formatCcrSectionScopeLabel(rule),
                rule.statusLabel || ''
            ].join(' ').toLowerCase();
            return hay.includes(search);
        });
    }
    if (filters.substance && filters.substance !== 'all') {
        list = list.filter(rule => ruleMatchesSubstanceScope(rule, filters.substance));
    }
    if (filters.section && filters.section !== 'all') {
        list = list.filter(rule => ruleMatchesSectionScope(rule, filters.section));
    }
    if (filters.metric && filters.metric !== 'all') {
        list = list.filter(rule => rule.metric === filters.metric);
    }
    if (filters.enabled === 'enabled') list = list.filter(r => r.enabled);
    if (filters.enabled === 'disabled') list = list.filter(r => !r.enabled);

    const dir = filters.sortDir === 'asc' ? 1 : -1;
    const sortKey = filters.sort || 'priority';
    list.sort((a, b) => {
        let av;
        let bv;
        if (sortKey === 'name') {
            av = String(a.name || '').toLowerCase();
            bv = String(b.name || '').toLowerCase();
            return av < bv ? -dir : av > bv ? dir : 0;
        }
        if (sortKey === 'metric') {
            av = String(a.metric || '');
            bv = String(b.metric || '');
            return av < bv ? -dir : av > bv ? dir : 0;
        }
        if (sortKey === 'substance') {
            av = formatCcrSubstanceScopeLabel(a, data).toLowerCase();
            bv = formatCcrSubstanceScopeLabel(b, data).toLowerCase();
            return av < bv ? -dir : av > bv ? dir : 0;
        }
        if (sortKey === 'lastModified') {
            av = a.lastModified || '';
            bv = b.lastModified || '';
            return av < bv ? -dir : av > bv ? dir : 0;
        }
        if (sortKey === 'rangeLower') {
            const ar = ccrNumericRange(a);
            const br = ccrNumericRange(b);
            av = ar ? ar.lo : Number.POSITIVE_INFINITY;
            bv = br ? br.lo : Number.POSITIVE_INFINITY;
            if (av !== bv) return (av - bv) * dir;
            const aHi = ar ? ar.hi : Number.POSITIVE_INFINITY;
            const bHi = br ? br.hi : Number.POSITIVE_INFINITY;
            return (aHi - bHi) * dir;
        }
        // priority (default)
        return filters.sortDir === 'asc'
            ? -compareCcrRulePrecedence(a, b)
            : compareCcrRulePrecedence(a, b);
    });
    return list;
}

function bulkSetConditionalColorRulesEnabled(ruleIds, enabled, data = appData) {
    const ids = new Set((ruleIds || []).map(String));
    if (!ids.size) return [];
    const state = ensureConditionalColorRules(data);
    state.rules.forEach(rule => {
        if (ids.has(rule.id)) {
            rule.enabled = !!enabled;
            rule.lastModified = new Date().toISOString();
        }
    });
    persistConditionalColorRulesState({ rules: state.rules }, data);
    invalidateConditionalColorRuleMatchCache();
    return state.rules.filter(r => ids.has(r.id));
}

function bulkDeleteConditionalColorRules(ruleIds, data = appData) {
    const ids = new Set((ruleIds || []).map(String));
    if (!ids.size) return [];
    const state = ensureConditionalColorRules(data);
    const removed = state.rules.filter(r => ids.has(r.id));
    state.rules = state.rules.filter(r => !ids.has(r.id));
    persistConditionalColorRulesState({ rules: state.rules }, data);
    invalidateConditionalColorRuleMatchCache();
    const ui = getCcrManagerUiState();
    ui.selectedIds = ui.selectedIds.filter(id => !ids.has(id));
    return removed;
}

function exportConditionalColorRulesSelectionJson(ruleIds, data = appData) {
    const ids = new Set((ruleIds || []).map(String));
    const state = ensureConditionalColorRules(data);
    const rules = state.rules.filter(r => ids.has(r.id));
    return JSON.stringify({
        app: 'recovery-tracker-conditional-color-rules',
        version: state.version || 1,
        exportedAt: new Date().toISOString(),
        enabled: state.enabled,
        metricSettings: state.metricSettings || {},
        rules
    }, null, 2);
}

function formatCcrRuleRangeLabel(rule) {
    if (!rule) return '';
    const unit = '';
    const lo = isCcrDurationMetric(rule.metric)
        ? formatCcrDurationThresholdLabel(getCcrRuleCompareMinutes(rule, 'value'))
        : (isCcrTimeGapMetric(rule.metric)
            ? formatCcrUseGapThresholdLabel(getCcrRuleCompareHours(rule, 'value'))
            : String(rule.value ?? '').trim());
    const hi = isCcrDurationMetric(rule.metric)
        ? formatCcrDurationThresholdLabel(getCcrRuleCompareMinutes(rule, 'valueTo'))
        : (isCcrTimeGapMetric(rule.metric)
            ? formatCcrUseGapThresholdLabel(getCcrRuleCompareHours(rule, 'valueTo'))
            : String(rule.valueTo ?? '').trim());
    if (rule.operator === 'between' || rule.operator === 'betweenInclusive' || rule.operator === 'betweenExclusive') {
        return `${lo || '—'}-${hi || '—'}${unit}`;
    }
    if (rule.operator === 'gt') return `over ${lo}`;
    if (rule.operator === 'gte') return `${lo}+`;
    if (rule.operator === 'lt') return `under ${lo}`;
    if (rule.operator === 'lte') return `up to ${lo}`;
    if (rule.operator === 'eq') return String(lo || '—');
    return formatCcrConditionSummary(rule);
}

function generateCcrRuleNameFromCondition(rule, data = appData) {
    const substance = formatCcrSubstanceScopeLabel(rule, data).replace(/^All substances$/, 'All');
    const metric = getCcrMetricUiDef(rule?.metric, data)?.label || getCcrMetricDef(rule?.metric)?.label || rule?.metric || 'Metric';
    const range = formatCcrRuleRangeLabel(rule) || formatCcrConditionSummary(rule);
    return `${substance} · ${metric} · ${range}`.slice(0, 80);
}

function formatCcrRuleManagerSummary(rule, data = appData) {
    const substance = formatCcrSubstanceScopeLabel(rule, data);
    const metric = getCcrMetricUiDef(rule?.metric, data)?.label || getCcrMetricDef(rule?.metric)?.label || rule?.metric || 'Metric';
    const condition = formatCcrConditionSummary(rule);
    if (isCcrTimeGapMetric(rule?.metric)) {
        return `${substance} · ${condition}`;
    }
    return `${substance} · ${metric} · ${condition}`;
}

function getCcrRulePrimaryColorName(rule) {
    const raw = rule?.colors?.background || rule?.colors?.border || rule?.colors?.text || '';
    const parsed = parseCssColor(raw);
    if (!parsed) return 'theme color';
    const { r, g, b } = parsed;
    if (g >= r && g >= b && r < 180) return 'green';
    if (r > 200 && g > 170 && b < 120) return 'yellow';
    if (r > 200 && g > 100 && g < 190 && b < 120) return 'orange';
    if (r > 180 && g < 120 && b < 140) return 'red';
    if (r > 120 && b > 140) return 'purple';
    if (b > r && b > g) return 'blue';
    if (Math.max(r, g, b) - Math.min(r, g, b) < 32) return 'gray';
    return 'selected color';
}

function formatCcrRuleExplanation(rule, data = appData) {
    const metric = getCcrMetricUiDef(rule?.metric, data)?.label || getCcrMetricDef(rule?.metric)?.label || rule?.metric || 'Metric';
    const metricPattern = String(metric).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const condition = formatCcrConditionSummary(rule)
        .replace(new RegExp(`^${metricPattern}\\s*·?\\s*`, 'i'), '')
        .replace(/^Duration\s+/i, '')
        .trim();
    const target = getCcrVisualTargetLabel(rule?.visualTarget).toLowerCase();
    const color = getCcrRulePrimaryColorName(rule);
    return `If ${metric} is ${condition || 'matched'} → Color ${target} ${color}.`;
}

function applyCcrBulkNameChange(rule, changes = {}, index = 0, data = appData) {
    const current = String(rule.name || '');
    if (changes.autoNameFromCondition) return generateCcrRuleNameFromCondition(rule, data);
    if (changes.nameMode === 'replace' || Object.prototype.hasOwnProperty.call(changes, 'name')) {
        return String(changes.name ?? changes.ruleName ?? current).slice(0, 80);
    }
    if (changes.nameMode === 'prefix' || Object.prototype.hasOwnProperty.call(changes, 'namePrefix')) {
        return `${changes.namePrefix ?? ''}${current}`.slice(0, 80);
    }
    if (changes.nameMode === 'suffix' || Object.prototype.hasOwnProperty.call(changes, 'nameSuffix')) {
        return `${current}${changes.nameSuffix ?? ''}`.slice(0, 80);
    }
    if (changes.nameMode === 'findReplace' || Object.prototype.hasOwnProperty.call(changes, 'findText')) {
        const find = String(changes.findText ?? '');
        if (!find) return current;
        return current.split(find).join(String(changes.replaceText ?? '')).slice(0, 80);
    }
    if (changes.nameMode === 'autoNumber' || changes.autoNumber) {
        const start = Number(changes.numberStart ?? changes.autoNumberStart ?? 1);
        const step = Number(changes.numberStep ?? changes.autoNumberStep ?? 1);
        const n = (Number.isFinite(start) ? start : 1) + index * (Number.isFinite(step) ? step : 1);
        const template = String(changes.numberTemplate || changes.autoNumberTemplate || '{name} {n}');
        return template
            .replace(/\{name\}/g, current)
            .replace(/\{n\}/g, String(n))
            .replace(/\{range\}/g, formatCcrRuleRangeLabel(rule))
            .slice(0, 80);
    }
    return current;
}

function buildCcrBulkEditPreview(ruleIds, changes = {}, data = appData) {
    const ids = new Set((ruleIds || []).map(String));
    const state = ensureConditionalColorRules(data);
    const selected = state.rules.filter(rule => ids.has(rule.id));
    const now = new Date().toISOString();
    return selected.map((rule, index) => {
        const next = {
            ...rule,
            colors: { ...(rule.colors || {}) }
        };
        const has = (key) => Object.prototype.hasOwnProperty.call(changes, key);
        const shouldChangeName = ['replace', 'prefix', 'suffix', 'findReplace', 'autoNumber'].includes(changes.nameMode)
            || changes.autoNameFromCondition
            || has('name') || has('ruleName') || has('namePrefix') || has('nameSuffix') || has('findText') || changes.autoNumber;
        if (shouldChangeName) next.name = applyCcrBulkNameChange(next, changes, index, data);
        if (has('substanceScope')) next.substanceScope = changes.substanceScope;
        if (has('sectionScope')) next.sectionScope = changes.sectionScope;
        if (has('metric')) next.metric = changes.metric;
        if (has('priority')) next.priority = Number(changes.priority);
        if (has('enabled')) next.enabled = !!changes.enabled;
        if (has('stopProcessing')) next.stopProcessing = !!changes.stopProcessing;
        if (has('backgroundColor')) next.colors.background = String(changes.backgroundColor ?? '');
        if (has('textColor')) next.colors.text = String(changes.textColor ?? '');
        if (has('borderColor')) next.colors.border = String(changes.borderColor ?? '');
        if (has('statusLabel')) next.statusLabel = String(changes.statusLabel ?? '').slice(0, 40);
        if (has('operator')) next.operator = changes.operator;
        if (has('value')) next.value = changes.value;
        if (has('valueTo') && ['between', 'betweenInclusive', 'betweenExclusive'].includes(next.operator)) next.valueTo = changes.valueTo;
        if (has('targetValue')) next.targetValue = changes.targetValue;
        if (has('customGroupId')) next.customGroupId = changes.customGroupId;
        next.lastModified = now;
        const normalized = normalizeConditionalColorRule(next);
        return {
            id: rule.id,
            before: rule,
            after: normalized,
            changedFields: Object.keys(normalized).filter(key => JSON.stringify(rule[key]) !== JSON.stringify(normalized[key]))
        };
    });
}

function applyCcrBulkEdit(ruleIds, changes = {}, data = appData) {
    const preview = buildCcrBulkEditPreview(ruleIds, changes, data);
    if (!preview.length) return [];
    const byId = new Map(preview.map(item => [item.id, item.after]));
    const state = ensureConditionalColorRules(data);
    state.rules = state.rules.map(rule => byId.get(rule.id) || rule);
    persistConditionalColorRulesState({ rules: state.rules }, data);
    invalidateConditionalColorRuleMatchCache();
    return preview;
}

function getCcrCustomGroups(data = appData) {
    return ensureConditionalColorRules(data).customGroups.slice();
}

function createCcrCustomGroup(name, data = appData) {
    const state = ensureConditionalColorRules(data);
    const group = normalizeCcrCustomGroup({ id: ccrNewId('group'), name: name || 'New group' }, state.customGroups.length);
    state.customGroups.push(group);
    persistConditionalColorRulesState({ customGroups: state.customGroups }, data);
    return group;
}

function renameCcrCustomGroup(groupId, name, data = appData) {
    const state = ensureConditionalColorRules(data);
    const group = state.customGroups.find(g => g.id === groupId);
    if (!group) return null;
    group.name = String(name || group.name).slice(0, 80);
    group.lastModified = new Date().toISOString();
    persistConditionalColorRulesState({ customGroups: state.customGroups }, data);
    return group;
}

function deleteCcrCustomGroup(groupId, data = appData) {
    const state = ensureConditionalColorRules(data);
    const id = String(groupId || '');
    state.customGroups = state.customGroups.filter(g => g.id !== id);
    state.rules.forEach(rule => {
        if (rule.customGroupId === id) {
            rule.customGroupId = '';
            rule.lastModified = new Date().toISOString();
        }
    });
    persistConditionalColorRulesState({ customGroups: state.customGroups, rules: state.rules }, data);
    return state;
}

function duplicateCcrCustomGroup(groupId, data = appData) {
    const state = ensureConditionalColorRules(data);
    const src = state.customGroups.find(g => g.id === groupId);
    if (!src) return null;
    const copy = normalizeCcrCustomGroup({
        ...src,
        id: ccrNewId('group'),
        name: `${src.name} copy`,
        createdAt: new Date().toISOString(),
        lastModified: new Date().toISOString()
    }, state.customGroups.length);
    state.customGroups.push(copy);
    persistConditionalColorRulesState({ customGroups: state.customGroups }, data);
    return copy;
}

function moveCcrRulesToCustomGroup(ruleIds, groupId, data = appData) {
    const id = String(groupId || '');
    const ids = new Set((ruleIds || []).map(String));
    const state = ensureConditionalColorRules(data);
    state.rules.forEach(rule => {
        if (ids.has(rule.id)) {
            rule.customGroupId = id;
            rule.lastModified = new Date().toISOString();
        }
    });
    persistConditionalColorRulesState({ rules: state.rules }, data);
    return state.rules.filter(r => ids.has(r.id));
}

function setCcrCustomGroupEnabled(groupId, enabled, data = appData) {
    const state = ensureConditionalColorRules(data);
    const group = state.customGroups.find(g => g.id === groupId);
    if (group) {
        group.enabled = !!enabled;
        group.lastModified = new Date().toISOString();
    }
    state.rules.forEach(rule => {
        if (rule.customGroupId === groupId) {
            rule.enabled = !!enabled;
            rule.lastModified = new Date().toISOString();
        }
    });
    persistConditionalColorRulesState({ customGroups: state.customGroups, rules: state.rules }, data);
    invalidateConditionalColorRuleMatchCache();
    return group || null;
}

function exportCcrCustomGroupJson(groupId, data = appData) {
    const state = ensureConditionalColorRules(data);
    const group = state.customGroups.find(g => g.id === groupId) || { id: groupId, name: 'Ungrouped' };
    const rules = state.rules.filter(r => r.customGroupId === groupId);
    return JSON.stringify({
        app: 'recovery-tracker-conditional-color-rule-group',
        version: state.version || 1,
        exportedAt: new Date().toISOString(),
        group,
        metricSettings: state.metricSettings || {},
        rules
    }, null, 2);
}

function getCcrGroupCollapseMap(data = appData) {
    return { ...(ensureConditionalColorRules(data).ui?.collapsedGroups || {}) };
}

function setCcrRuleGroupCollapsed(groupId, collapsed, data = appData) {
    const state = ensureConditionalColorRules(data);
    const collapsedGroups = { ...(state.ui?.collapsedGroups || {}) };
    collapsedGroups[groupId] = !!collapsed;
    persistConditionalColorRulesState({ ui: { ...(state.ui || {}), collapsedGroups } }, data);
    return collapsedGroups;
}

function setCcrAllRuleGroupsCollapsed(groupIds, collapsed, data = appData) {
    const state = ensureConditionalColorRules(data);
    const collapsedGroups = { ...(state.ui?.collapsedGroups || {}) };
    (groupIds || []).forEach(id => { collapsedGroups[id] = !!collapsed; });
    persistConditionalColorRulesState({ ui: { ...(state.ui || {}), collapsedGroups } }, data);
    return collapsedGroups;
}

function setCcrManagerGroupBy(groupBy, data = appData) {
    const state = ensureConditionalColorRules(data);
    const allowed = ['substance', 'metric', 'section', 'enabled', 'custom'];
    const next = allowed.includes(groupBy) ? groupBy : 'substance';
    getCcrManagerUiState().groupBy = next;
    persistConditionalColorRulesState({ ui: { ...(state.ui || {}), groupBy: next } }, data);
    return next;
}

function getCcrRuleGroupKey(rule, groupBy = 'substance', data = appData) {
    if (groupBy === 'metric') return `metric:${rule.metric || 'none'}`;
    if (groupBy === 'section') {
        const section = (!rule.sectionScope?.length || rule.sectionScope.includes('all')) ? 'all' : rule.sectionScope[0];
        return `section:${section}`;
    }
    if (groupBy === 'enabled') return `enabled:${rule.enabled ? 'enabled' : 'disabled'}`;
    if (groupBy === 'custom') return `custom:${rule.customGroupId || 'ungrouped'}`;
    const scope = rule.substanceScope;
    const substance = scope === 'all' || scope == null ? 'all' : (Array.isArray(scope) ? (scope[0] || 'all') : String(scope));
    return `substance:${substance}`;
}

function getCcrRuleGroupName(groupKey, groupBy = 'substance', data = appData) {
    const value = String(groupKey).split(':').slice(1).join(':') || 'all';
    if (groupBy === 'metric') return getCcrMetricUiDef(value, data)?.label || getCcrMetricDef(value)?.label || value;
    if (groupBy === 'section') return CCR_SECTION_USAGE_LABELS[value] || CCR_SECTIONS.find(s => s.id === value)?.label || value;
    if (groupBy === 'enabled') return value === 'enabled' ? 'Enabled' : 'Disabled';
    if (groupBy === 'custom') {
        if (value === 'ungrouped') return 'Ungrouped';
        return ensureConditionalColorRules(data).customGroups.find(g => g.id === value)?.name || 'Missing group';
    }
    if (value === 'all') return 'All substances';
    return (data.substances || []).find(s => s.id === value)?.name || value;
}

function buildCcrRuleGroups(rules, { groupBy = null, conflicts = null, matchCounts = null, data = appData } = {}) {
    const state = ensureConditionalColorRules(data);
    const actualGroupBy = groupBy || state.ui?.groupBy || getCcrManagerUiState().groupBy || 'substance';
    const collapsed = state.ui?.collapsedGroups || {};
    const conflictMap = conflicts || detectConditionalColorRuleConflicts(state.rules, data);
    const counts = matchCounts || computeConditionalColorRuleMatchCounts(data);
    const groups = new Map();
    (rules || []).forEach(rule => {
        const id = getCcrRuleGroupKey(rule, actualGroupBy, data);
        if (!groups.has(id)) {
            groups.set(id, {
                id,
                groupBy: actualGroupBy,
                name: getCcrRuleGroupName(id, actualGroupBy, data),
                rules: [],
                count: 0,
                enabledCount: 0,
                conflictCount: 0,
                totalMatchCount: 0,
                collapsed: !!collapsed[id]
            });
        }
        const group = groups.get(id);
        group.rules.push(rule);
        group.count += 1;
        if (rule.enabled) group.enabledCount += 1;
        if ((conflictMap[rule.id] || []).length) group.conflictCount += 1;
        group.totalMatchCount += counts[rule.id] || 0;
    });
    groups.forEach(group => {
        if (group.groupBy === 'metric') {
            group.rules.sort((a, b) => {
                const sa = formatCcrSubstanceScopeLabel(a, data).localeCompare(formatCcrSubstanceScopeLabel(b, data));
                return sa || compareCcrRulePrecedence(a, b);
            });
        }
    });
    return [...groups.values()];
}

function selectCcrRuleGroup(groupId, checked, rules = null, data = appData) {
    const ui = getCcrManagerUiState();
    const state = ensureConditionalColorRules(data);
    const visible = rules || filterAndSortConditionalColorRules(state.rules, ui, data);
    const group = buildCcrRuleGroups(visible, { groupBy: ui.groupBy || state.ui?.groupBy, data })
        .find(g => g.id === groupId);
    if (!group) return [];
    const ids = group.rules.map(r => r.id);
    if (checked) ui.selectedIds = [...new Set([...ui.selectedIds, ...ids])];
    else {
        const drop = new Set(ids);
        ui.selectedIds = ui.selectedIds.filter(id => !drop.has(id));
    }
    return ids;
}

function getCcrManagerGroup(groupId, data = appData) {
    const ui = getCcrManagerUiState();
    const state = ensureConditionalColorRules(data);
    const visible = filterAndSortConditionalColorRules(state.rules, ui, data);
    return buildCcrRuleGroups(visible, { groupBy: ui.groupBy || state.ui?.groupBy, data })
        .find(g => g.id === groupId) || null;
}

function setCcrRuleGroupEnabled(groupId, enabled, data = appData) {
    const group = getCcrManagerGroup(groupId, data);
    if (!group) return [];
    const ids = group.rules.map(r => r.id);
    bulkSetConditionalColorRulesEnabled(ids, enabled, data);
    return ids;
}

function duplicateCcrRuleManagerGroup(groupId, data = appData) {
    const group = getCcrManagerGroup(groupId, data);
    if (!group) return [];
    const state = ensureConditionalColorRules(data);
    const now = new Date().toISOString();
    const copies = group.rules.map(rule => normalizeConditionalColorRule({
        ...rule,
        id: ccrNewId(),
        name: `${rule.name} (copy)`,
        isPreset: false,
        presetId: null,
        createdAt: now,
        lastModified: now
    }));
    state.rules.push(...copies);
    persistConditionalColorRulesState({ rules: state.rules }, data);
    invalidateConditionalColorRuleMatchCache();
    return copies;
}

function deleteCcrRuleManagerGroup(groupId, data = appData) {
    const group = getCcrManagerGroup(groupId, data);
    if (!group) return [];
    const ids = new Set(group.rules.map(r => String(r.id)));
    const state = ensureConditionalColorRules(data);
    state.rules = state.rules.filter(rule => !ids.has(String(rule.id)));
    persistConditionalColorRulesState({ rules: state.rules }, data);
    invalidateConditionalColorRuleMatchCache();
    return [...ids];
}

function exportCcrRuleManagerGroupJson(groupId, data = appData) {
    const group = getCcrManagerGroup(groupId, data);
    if (!group) return '';
    return exportConditionalColorRulesSelectionJson(group.rules.map(r => r.id), data);
}

/**
 * Install recovery presets without overwriting existing rules unless replace=true.
 */
function loadRecoveryColorRulePresets(data = appData, { replace = false, theme = null } = {}) {
    const resolved = theme
        || (typeof resolvedTheme !== 'undefined' ? resolvedTheme : 'dark')
        || 'dark';
    const presets = getConditionalColorPresetRules(resolved).map((r, i) => normalizeConditionalColorRule({
        ...r,
        createdByUser: true,
        lastModified: new Date().toISOString()
    }, i));
    const state = ensureConditionalColorRules(data);
    if (replace) {
        state.rules = presets;
    } else {
        const byPresetId = new Set(state.rules.map(r => r.presetId).filter(Boolean));
        const byName = new Set(state.rules.map(r => String(r.name || '').toLowerCase()));
        presets.forEach(preset => {
            if (preset.presetId && byPresetId.has(preset.presetId)) return;
            if (byName.has(String(preset.name || '').toLowerCase())) return;
            preset.id = ccrNewId('preset');
            state.rules.push(preset);
        });
    }
    persistConditionalColorRulesState({ rules: state.rules }, data);
    invalidateConditionalColorRuleMatchCache();
    return state;
}

function setConditionalColorRulePriorityOrder(orderedIds, data = appData) {
    const state = ensureConditionalColorRules(data);
    const byId = new Map(state.rules.map(r => [r.id, r]));
    const ordered = [];
    (orderedIds || []).forEach(id => {
        if (byId.has(id)) {
            ordered.push(byId.get(id));
            byId.delete(id);
        }
    });
    // Append any leftover rules
    byId.forEach(rule => ordered.push(rule));
    // Highest priority at top of list
    const base = 1000;
    ordered.forEach((rule, index) => {
        rule.priority = base - index;
        rule.lastModified = new Date().toISOString();
    });
    persistConditionalColorRulesState({ rules: ordered }, data);
    invalidateConditionalColorRuleMatchCache();
    return ordered;
}

function formatCcrLastModifiedLabel(iso) {
    if (!iso) return '—';
    try {
        const d = new Date(iso);
        if (Number.isNaN(d.getTime())) return '—';
        return d.toLocaleString();
    } catch (_) {
        return '—';
    }
}

function renderCcrColorPreview(rule) {
    const c = rule?.colors || {};
    const bg = c.background || 'transparent';
    const text = c.text || 'var(--text-primary)';
    const border = c.border || 'var(--border)';
    const accent = c.accent || border;
    return `<div class="ccr-color-preview" role="img" aria-label="Background ${escapeAttr(bg)}, text ${escapeAttr(text)}, border ${escapeAttr(border)}, accent ${escapeAttr(accent)}">
        <span class="ccr-swatch-bg" style="background:${escapeAttr(bg)};border-color:${escapeAttr(border)}" title="Background"></span>
        <span class="ccr-swatch-text" style="color:${escapeAttr(text)}" title="Text">Aa</span>
        <span class="ccr-swatch-border" style="border-color:${escapeAttr(border)}" title="Border"></span>
        <span class="ccr-swatch-accent" style="background:${escapeAttr(accent)}" title="Accent"></span>
        <span class="ccr-swatch-sr">${escapeHtml(`BG ${bg} · Text ${text} · Border ${border} · Accent ${accent}`)}</span>
    </div>`;
}

// ——— Conditional Color Rules UI ———

let ccrEditingRuleId = null;

function getCcrEditorDraftFromForm() {
    const get = (id) => document.getElementById(id);
    const sections = [...(get('ccr-rule-sections')?.selectedOptions || [])].map(o => o.value);
    const substance = get('ccr-rule-substance')?.value || 'all';
    const backgroundRaw = get('ccr-rule-bg')?.value ?? '';
    const metric = get('ccr-rule-metric')?.value || 'useAmount';
    const draft = {
        id: ccrEditingRuleId || ccrNewId(),
        name: get('ccr-rule-name')?.value || 'Untitled rule',
        enabled: get('ccr-rule-enabled')?.checked !== false,
        substanceScope: substance,
        sectionScope: sections.length ? sections : ['all'],
        metric,
        operator: get('ccr-rule-operator')?.value || 'gt',
        rangeBoundary: get('ccr-rule-boundary')?.value || 'inclusiveExclusive',
        visualTarget: get('ccr-rule-visual-target')?.value || 'value',
        value: get('ccr-rule-value')?.value ?? '',
        valueTo: get('ccr-rule-value-to')?.value ?? '',
        targetValue: get('ccr-rule-target')?.value ?? '',
        priority: parseFloat(get('ccr-rule-priority')?.value) || 100,
        stopProcessing: !!get('ccr-rule-stop')?.checked,
        statusLabel: get('ccr-rule-status-label')?.value || '',
        colors: {
            background: backgroundRaw,
            text: get('ccr-rule-text') ? get('ccr-rule-text').value : '#81c784',
            border: get('ccr-rule-border') ? get('ccr-rule-border').value : '#4caf50'
        }
    };
    if (isCcrDurationMetric(metric)) {
        draft.valueUnit = 'hours';
        draft.durationValueVersion = 2;
    } else if (isCcrTimeGapMetric(metric)) {
        draft.valueUnit = getCcrMetricSettings(metric)?.inputUnit || 'hours';
    }
    return normalizeConditionalColorRule(draft);
}

function setCcrBackgroundOpacityUi(percent) {
    const pct = Math.max(0, Math.min(100, Math.round(Number(percent))));
    const opacity = document.getElementById('ccr-rule-bg-opacity');
    const label = document.getElementById('ccr-rule-bg-opacity-label');
    if (opacity) {
        opacity.value = String(Number.isFinite(pct) ? pct : 100);
        opacity.setAttribute('aria-valuenow', opacity.value);
    }
    if (label) label.textContent = `${Number.isFinite(pct) ? pct : 100}%`;
}

function setCcrBackgroundColorError(message) {
    const error = document.getElementById('ccr-rule-bg-error');
    if (error) error.textContent = message || '';
}

function applyCcrBackgroundControlsFromValue(backgroundValue) {
    const text = document.getElementById('ccr-rule-bg');
    const picker = document.getElementById('ccr-rule-bg-picker');
    const raw = String(backgroundValue ?? '');
    if (text) text.value = raw;
    const trimmed = raw.trim();
    if (!trimmed) {
        setCcrBackgroundColorError('');
        if (picker && !picker.value) picker.value = '#4caf50';
        setCcrBackgroundOpacityUi(Number(document.getElementById('ccr-rule-bg-opacity')?.value) || 100);
        return;
    }
    const parsed = parseCssColor(trimmed);
    if (!parsed) {
        setCcrBackgroundColorError('Invalid background color. Use #RGB, #RRGGBB, #RRGGBBAA, rgb(), or rgba().');
        return;
    }
    setCcrBackgroundColorError('');
    if (picker) picker.value = rgbToHexColor(parsed.r, parsed.g, parsed.b);
    setCcrBackgroundOpacityUi(Math.round(parsed.a * 100));
}

function fillCcrEditorForm(rule) {
    const r = normalizeConditionalColorRule(rule || {
        name: 'New rule',
        metric: 'useAmount',
        operator: 'gt',
        visualTarget: 'value',
        value: 0,
        priority: 100,
        colors: { background: 'rgba(76, 175, 80, 0.22)', text: '#81c784', border: '#4caf50' },
        statusLabel: ''
    });
    ccrEditingRuleId = r.id;
    const set = (id, value, prop = 'value') => {
        const el = document.getElementById(id);
        if (!el) return;
        if (prop === 'checked') el.checked = !!value;
        else el[prop] = value ?? '';
    };
    set('ccr-rule-name', r.name);
    set('ccr-rule-enabled', r.enabled, 'checked');
    set('ccr-rule-substance', Array.isArray(r.substanceScope) ? (r.substanceScope[0] || 'all') : r.substanceScope);
    const sectionsEl = document.getElementById('ccr-rule-sections');
    if (sectionsEl) {
        const selected = new Set(r.sectionScope || ['all']);
        [...sectionsEl.options].forEach(opt => {
            opt.selected = selected.has(opt.value);
        });
    }
    populateCcrMetricSelect(r.metric);
    const opEl = document.getElementById('ccr-rule-operator');
    if (opEl) opEl.value = r.operator;
    populateCcrOperatorSelectForMetric(r.metric);
    set('ccr-rule-operator', r.operator);
    set('ccr-rule-boundary', r.rangeBoundary || normalizeCcrRangeBoundary(null, r.operator));
    if (isCcrDurationMetric(r.metric)) {
        const editorVals = getCcrDurationEditorValues(r);
        set('ccr-rule-value', editorVals.value);
        set('ccr-rule-value-to', editorVals.valueTo);
    } else if (isCcrTimeGapMetric(r.metric)) {
        const editorVals = getCcrTimeGapEditorValues(r);
        set('ccr-rule-value', editorVals.value);
        set('ccr-rule-value-to', editorVals.valueTo);
    } else {
        set('ccr-rule-value', r.value);
        set('ccr-rule-value-to', r.valueTo);
    }
    set('ccr-rule-target', r.targetValue);
    set('ccr-rule-priority', r.priority);
    set('ccr-rule-stop', r.stopProcessing, 'checked');
    set('ccr-rule-status-label', r.statusLabel);
    set('ccr-rule-visual-target', normalizeCcrVisualTarget(r.visualTarget));
    applyCcrBackgroundControlsFromValue(r.colors.background);
    set('ccr-rule-text', r.colors.text);
    set('ccr-rule-text-hex', r.colors.text.startsWith('#') ? r.colors.text.slice(0, 7) : '#81c784');
    set('ccr-rule-text-picker', r.colors.text.startsWith('#') ? r.colors.text.slice(0, 7) : '#81c784');
    set('ccr-rule-border', r.colors.border);
    set('ccr-rule-border-hex', r.colors.border.startsWith('#') ? r.colors.border.slice(0, 7) : '#4caf50');
    set('ccr-rule-border-picker', r.colors.border.startsWith('#') ? r.colors.border.slice(0, 7) : '#4caf50');

    const textHex = document.getElementById('ccr-rule-text-hex');
    const borderHex = document.getElementById('ccr-rule-border-hex');
    if (textHex) syncCcrColorInputs(textHex);
    if (borderHex) syncCcrColorInputs(borderHex);
    updateCcrOperatorFieldsVisibility();
    refreshCcrColorPalettes();
    updateCcrLivePreview();
    updateCcrRangeVisualizer();
}

function updateCcrDurationValueLabels() {
    const metric = document.getElementById('ccr-rule-metric')?.value;
    const op = document.getElementById('ccr-rule-operator')?.value;
    const isDur = isCcrDurationMetric(metric);
    const isGap = isCcrTimeGapMetric(metric);
    const isBetween = op === 'between' || op === 'betweenInclusive' || op === 'betweenExclusive';
    const valueLabel = document.getElementById('ccr-rule-value-label')
        || document.querySelector('label[for="ccr-rule-value"]');
    const valueToLabel = document.getElementById('ccr-rule-value-to-label')
        || document.querySelector('label[for="ccr-rule-value-to"]');
    const hint = document.getElementById('ccr-duration-value-hint');
    if (valueLabel) {
        if (isDur && isBetween) valueLabel.textContent = 'Minimum hours';
        else if (isDur) valueLabel.textContent = 'Comparison value (hours)';
        else if (isGap && isBetween) valueLabel.textContent = 'Minimum hours';
        else if (isGap) valueLabel.textContent = 'Comparison value (hours)';
        else valueLabel.textContent = 'Comparison value';
    }
    if (valueToLabel) {
        valueToLabel.textContent = (isDur || isGap) ? 'Maximum hours' : 'Range end';
    }
    if (hint) {
        hint.textContent = isGap
            ? 'Enter duration in hours. Decimals are allowed. Examples: 0.5 = 30 minutes, 2 = 2 hours, 26 = 1 day 2 hours.'
            : 'Enter duration in hours. Decimals are allowed.';
        hint.classList.toggle('hidden', !(isDur || isGap));
    }
}

function populateCcrOperatorSelectForMetric(metric = null) {
    const opEl = document.getElementById('ccr-rule-operator');
    if (!opEl) return;
    const current = opEl.value;
    const settings = getCcrMetricSettings(metric || document.getElementById('ccr-rule-metric')?.value || 'useAmount');
    const allowed = new Set(settings?.allowedOperators || CCR_OPERATORS.map(o => o.id));
    const optionIds = CCR_OPERATORS
        .map(o => o.id)
        .filter(id => id !== 'betweenInclusive' && allowed.has(id));
    if (current && !optionIds.includes(current) && CCR_OPERATORS.some(o => o.id === current)) {
        optionIds.push(current);
    }
    opEl.innerHTML = optionIds
        .map(id => {
            const o = CCR_OPERATORS.find(item => item.id === id);
            const legacy = allowed.has(id) ? '' : ' (legacy)';
            return `<option value="${id}">${escapeHtml((o?.label || id) + legacy)}</option>`;
        }).join('');
    if ([...opEl.options].some(o => o.value === current)) opEl.value = current;
    else if (settings?.defaultOperator && [...opEl.options].some(o => o.value === settings.defaultOperator)) opEl.value = settings.defaultOperator;
}

function onCcrMetricChanged() {
    populateCcrMetricSettingsEditor();
    const metric = document.getElementById('ccr-rule-metric')?.value;
    populateCcrOperatorSelectForMetric(metric);
    const settings = getCcrMetricSettings(metric);
    const opEl = document.getElementById('ccr-rule-operator');
    if (opEl && settings?.defaultOperator && [...opEl.options].some(o => o.value === settings.defaultOperator)) {
        opEl.value = settings.defaultOperator;
    }
    updateCcrDurationValueLabels();
    updateCcrOperatorFieldsVisibility();
    updateCcrLivePreview();
}

function updateCcrOperatorFieldsVisibility() {
    const op = document.getElementById('ccr-rule-operator')?.value;
    const valueRow = document.getElementById('ccr-value-row');
    const valueToRow = document.getElementById('ccr-value-to-row');
    const boundaryRow = document.getElementById('ccr-boundary-row');
    const targetRow = document.getElementById('ccr-target-row');
    const needsValue = !['empty', 'notEmpty', 'true', 'false'].includes(op);
    const needsTo = op === 'between' || op === 'betweenInclusive' || op === 'betweenExclusive';
    const needsTarget = op === 'pctAboveTarget' || op === 'pctBelowTarget';
    valueRow?.classList.toggle('hidden', !needsValue);
    valueToRow?.classList.toggle('hidden', !needsTo);
    boundaryRow?.classList.toggle('hidden', !needsTo);
    targetRow?.classList.toggle('hidden', !needsTarget);
    updateCcrDurationValueLabels();
    updateCcrRangeVisualizer();
}

const CCR_RULE_EXAMPLE_VALUES = Object.freeze([0.5, 1, 1.5, 2, 2.5, 3, 4, 5]);

function renderCcrExampleValuePreview(rule) {
    const canCompare = getCcrMetricSettings(rule.metric)?.valueType !== 'string'
        && getCcrMetricSettings(rule.metric)?.valueType !== 'boolean';
    if (!canCompare) return '<p class="settings-hint">Example values are shown for numeric rules.</p>';
    return `<div class="ccr-example-values" aria-label="Example values">
        ${CCR_RULE_EXAMPLE_VALUES.map(value => {
            const matches = compareConditionalColorRule(rule, { value, textValue: String(value) });
            return `<span class="ccr-example-value${matches ? ' is-match' : ''}" title="${matches ? 'Matches this rule' : 'Does not match this rule'}">${escapeHtml(String(value))}</span>`;
        }).join('')}
    </div>`;
}

function buildCcrPreviewStyleForTarget(colors, target) {
    const normalized = normalizeCcrVisualTarget(target);
    const background = normalized === 'border' ? '' : colors.background;
    const text = normalized === 'border' ? '' : colors.text;
    return buildConditionalColorInlineStyle({
        matched: [{}],
        style: {
            background,
            text,
            border: colors.border || colors.accent,
            accent: colors.accent || colors.border
        }
    });
}

function updateCcrLivePreview() {
    const draft = getCcrEditorDraftFromForm();
    const preview = document.getElementById('ccr-live-preview');
    const warn = document.getElementById('ccr-contrast-warning');
    const bgInput = document.getElementById('ccr-rule-bg');
    const bgValidation = validateCcrBackgroundColor(bgInput?.value ?? draft.colors.background);
    if (bgInput && String(bgInput.value || '').trim()) {
        setCcrBackgroundColorError(bgValidation.ok ? '' : bgValidation.message);
    } else {
        setCcrBackgroundColorError('');
    }
    if (preview) {
        const previewColors = {
            ...draft.colors,
            background: bgValidation.ok ? draft.colors.background : ''
        };
        const style = buildCcrPreviewStyleForTarget(previewColors, draft.visualTarget);
        const label = (draft.statusLabel || '').trim();
        const badge = label
            ? `<span class="ccr-preview-badge"${style ? ` style="${escapeAttr(style)}"` : ''}>${escapeHtml(label)}</span>`
            : `<span class="ccr-preview-badge"${style ? ` style="${escapeAttr(style)}"` : ''}>Badge</span>`;
        preview.innerHTML = `
            <div class="ccr-live-preview-grid">
                <div class="ccr-preview-neutral"><span>Neutral</span><strong>12.5</strong></div>
                <div class="ccr-preview-value"><span>Colored Value</span><strong${style ? ` style="${escapeAttr(style)}"` : ''}>12.5</strong></div>
                <div class="ccr-preview-row"${normalizeCcrVisualTarget(draft.visualTarget) === 'row' && style ? ` style="${escapeAttr(style)}"` : ''}><span>Colored Row</span><strong>12.5</strong></div>
                <div class="ccr-preview-card"${normalizeCcrVisualTarget(draft.visualTarget) === 'card' && style ? ` style="${escapeAttr(style)}"` : ''}><span>Colored Card</span><strong>12.5</strong>${badge}</div>
            </div>
            <div class="ccr-rule-explanation">${escapeHtml(formatCcrRuleExplanation(draft))}</div>
            ${renderCcrExampleValuePreview(draft)}
        `;
    }
    if (warn) {
        const bgParsed = bgValidation.parsed || parseCssColor(draft.colors.background);
        const bg = bgParsed
            ? `rgb(${clampCssByte(bgParsed.r)},${clampCssByte(bgParsed.g)},${clampCssByte(bgParsed.b)})`
            : (typeof resolvedTheme !== 'undefined' && resolvedTheme === 'light' ? '#ffffff' : '#1e1e1e');
        const info = getContrastWarning(draft.colors.text, bg);
        warn.textContent = info.message || '';
        warn.classList.toggle('ccr-contrast-bad', !info.ok);
        warn.classList.toggle('ccr-contrast-ok', !!info.ok);
    }
    updateCcrRangeVisualizer();
}

function populateCcrSubstanceSelect() {
    const el = document.getElementById('ccr-rule-substance');
    if (!el) return;
    const current = el.value || 'all';
    const substances = typeof getActiveSubstances === 'function' ? getActiveSubstances() : (appData.substances || []);
    el.innerHTML = `<option value="all">All substances</option>` + substances.map(s =>
        `<option value="${escapeAttr(s.id)}">${escapeHtml(s.icon || '')} ${escapeHtml(s.name)}</option>`
    ).join('');
    el.value = [...el.options].some(o => o.value === current) ? current : 'all';
}

function isCcrRuleCardExpanded(ruleId, data = appData) {
    return (ensureConditionalColorRules(data).ui?.expandedRuleIds || []).includes(String(ruleId));
}

function setCcrRuleCardExpanded(ruleId, expanded, data = appData) {
    const state = ensureConditionalColorRules(data);
    const id = String(ruleId || '');
    const set = new Set(state.ui?.expandedRuleIds || []);
    if (expanded) set.add(id);
    else set.delete(id);
    persistConditionalColorRulesState({ ui: { ...(state.ui || {}), expandedRuleIds: [...set] } }, data);
    return [...set];
}

function toggleCcrRuleCardExpanded(ruleId) {
    setCcrRuleCardExpanded(ruleId, !isCcrRuleCardExpanded(ruleId));
    renderConditionalColorRulesList();
}

function toggleCcrRuleGroupCollapsed(groupId) {
    const collapsed = !!getCcrGroupCollapseMap()[groupId];
    setCcrRuleGroupCollapsed(groupId, !collapsed);
    renderConditionalColorRulesList();
}

function expandAllCcrRuleGroups() {
    const ui = getCcrManagerUiState();
    const groups = buildCcrRuleGroups(filterAndSortConditionalColorRules(getConditionalColorRules(), ui), { groupBy: ui.groupBy });
    setCcrAllRuleGroupsCollapsed(groups.map(g => g.id), false);
    renderConditionalColorRulesList();
}

function collapseAllCcrRuleGroups() {
    const ui = getCcrManagerUiState();
    const groups = buildCcrRuleGroups(filterAndSortConditionalColorRules(getConditionalColorRules(), ui), { groupBy: ui.groupBy });
    setCcrAllRuleGroupsCollapsed(groups.map(g => g.id), true);
    renderConditionalColorRulesList();
}

function onCcrManagerGroupByChanged(value) {
    setCcrManagerGroupBy(value);
    renderConditionalColorRulesSettings();
}

function selectCcrRuleGroupFromUi(groupId, checked) {
    selectCcrRuleGroup(groupId, checked);
    renderConditionalColorRulesList();
}

function bulkSetCcrRuleGroupEnabledFromUi(groupId, enabled) {
    const ids = setCcrRuleGroupEnabled(groupId, enabled);
    renderConditionalColorRulesSettings();
    if (typeof showToast === 'function') showToast(`${enabled ? 'Enabled' : 'Disabled'} ${ids.length} rules`);
}

function duplicateCcrRuleGroupFromUi(groupId) {
    const copies = duplicateCcrRuleManagerGroup(groupId);
    renderConditionalColorRulesSettings();
    if (typeof showToast === 'function') showToast(`Duplicated ${copies.length} rules`);
}

function deleteCcrRuleGroupFromUi(groupId) {
    const group = getCcrManagerGroup(groupId);
    if (!group) return;
    if (!confirm(`Delete ${group.rules.length} rules in "${group.name}"?`)) return;
    const deleted = deleteCcrRuleManagerGroup(groupId);
    renderConditionalColorRulesSettings();
    if (typeof showToast === 'function') showToast(`Deleted ${deleted.length} rules`);
}

function exportCcrRuleGroupFromUi(groupId) {
    const group = getCcrManagerGroup(groupId);
    if (!group) return;
    const json = exportCcrRuleManagerGroupJson(groupId);
    if (!json) return;
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `recovery-tracker-color-rules-${String(group.name || 'group').replace(/[^a-z0-9]+/gi, '-').toLowerCase()}-${getLocalDateString?.() || 'export'}.json`;
    a.click();
    URL.revokeObjectURL(url);
}

function importCcrRuleGroupFromUi() {
    document.getElementById('ccr-import-file')?.click();
}

function moveSelectedColorRulesToGroupFromUi() {
    const ids = getSelectedCcrManagerRuleIds();
    if (!ids.length) {
        if (typeof showToast === 'function') showToast('Select rules first');
        return;
    }
    const groups = getCcrCustomGroups();
    let group = groups[0];
    if (!group) group = createCcrCustomGroup('New group');
    moveCcrRulesToCustomGroup(ids, group.id);
    setCcrManagerGroupBy('custom');
    renderConditionalColorRulesSettings();
    if (typeof showToast === 'function') showToast(`Moved ${ids.length} rule${ids.length === 1 ? '' : 's'} to ${group.name}`);
}

function openCcrBulkEditDialog() {
    const ids = getSelectedCcrManagerRuleIds();
    if (ids.length < 2) {
        if (typeof showToast === 'function') showToast('Select multiple rules first');
        return;
    }
    const findText = prompt('Bulk Edit preview\n\nEnter text to find in selected rule names. Leave blank to auto-name from condition.');
    const changes = findText
        ? { nameMode: 'findReplace', findText, replaceText: prompt('Replace with:', '') || '' }
        : { autoNameFromCondition: true };
    const preview = buildCcrBulkEditPreview(ids, changes);
    const previewText = preview.slice(0, 8).map(item => `${item.before.name} -> ${item.after.name}`).join('\n');
    if (!confirm(`Preview ${preview.length} changes:\n\n${previewText}${preview.length > 8 ? '\n...' : ''}\n\nSave these changes?`)) return;
    applyCcrBulkEdit(ids, changes);
    renderConditionalColorRulesSettings();
    if (typeof showToast === 'function') showToast(`Bulk edited ${preview.length} rules`);
}

function renderCcrRuleManagerCard(rule, { conflicts, matchCounts, selected } = {}) {
    const metricLabel = (id) => getCcrMetricUiDef(id)?.label || getCcrMetricDef(id)?.label || id;
    const conflictList = conflicts[rule.id] || [];
    const relationship = summarizeCcrRuleRelationship(rule);
    const expanded = isCcrRuleCardExpanded(rule.id);
    const conflictHtml = conflictList.length
        ? `<span class="ccr-conflict-group"><button type="button" class="ccr-overlap-pill ccr-overlap-red" title="${escapeAttr(conflictList.map(c => c.message || c.name).join(' '))}" aria-label="${escapeAttr(conflictList[0].message || `Overlaps with ${conflictList[0].name}`)}" onclick="jumpToConflictingColorRule('${escapeAttr(conflictList[0].id)}')">🔴 Overlaps${conflictList.length > 1 ? ` +${conflictList.length - 1}` : ''}</button><button type="button" class="secondary-btn btn-sm" onclick="fixCcrRangeBoundariesForRule('${escapeAttr(rule.id)}')">Fix range boundaries</button></span>`
        : `<span class="ccr-overlap-pill ccr-overlap-${relationship.level}" title="${escapeAttr(relationship.other ? `${relationship.label} ${relationship.other.name}` : relationship.label)}">${relationship.level === 'yellow' ? '🟡' : '🟢'} ${escapeHtml(relationship.label)}</span>`;
    const reviewHtml = rule.needsReview
        ? `<span class="ccr-conflict-btn" title="${escapeAttr(rule.reviewReason || 'Needs review')}">Needs review</span>`
        : '';
    const usage = getConditionalColorRuleUsage(rule)
        .filter(u => u.used)
        .map(u => `<span class="ccr-usage-chip">${escapeHtml(u.label)}</span>`)
        .join(' ');
    const matchCount = matchCounts[rule.id] || 0;
    const checked = selected.has(rule.id) ? 'checked' : '';
    const expandedClass = expanded ? ' is-expanded' : '';
    return `<article class="ccr-rule-card ccr-manager-row${!rule.enabled ? ' is-disabled' : ''}${expandedClass}" data-rule-id="${escapeAttr(rule.id)}" draggable="true" ondragstart="onCcrRuleDragStart(event, '${escapeAttr(rule.id)}')" ondragover="onCcrRuleDragOver(event)" ondrop="onCcrRuleDrop(event, '${escapeAttr(rule.id)}')" ondragend="onCcrRuleDragEnd()" tabindex="0" role="listitem" aria-label="${escapeAttr(rule.name)}">
        <div class="ccr-rule-card-select">
            <label class="ccr-select-mini">
                <input type="checkbox" ${checked} aria-label="Select ${escapeAttr(rule.name)}" onchange="toggleCcrManagerRuleSelection('${escapeAttr(rule.id)}', this.checked); renderConditionalColorRulesList();">
                <span class="ccr-drag-handle" title="Drag within this group" aria-hidden="true">⋮⋮</span>
            </label>
        </div>
        <div class="ccr-rule-card-main">
            <label class="ccr-enable-mini">
                <input type="checkbox" ${rule.enabled ? 'checked' : ''} aria-label="Enable ${escapeAttr(rule.name)}" onchange="setConditionalColorRuleEnabled('${escapeAttr(rule.id)}', this.checked); renderConditionalColorRulesSettings();">
                <span>On</span>
            </label>
            ${renderCcrColorPreview(rule)}
            <div class="ccr-rule-card-body">
                <div class="ccr-rule-compact-line">
                    <strong class="ccr-rule-name">${escapeHtml(rule.name)}</strong>
                    <span class="ccr-rule-condition">${escapeHtml(formatCcrRuleExplanation(rule))}</span>
                    <span class="ccr-target-pill">${escapeHtml(getCcrVisualTargetLabel(rule.visualTarget))}</span>
                    <span class="ccr-priority-pill">Priority ${escapeHtml(String(rule.priority))}</span>
                    ${reviewHtml}
                    ${conflictHtml}
                </div>
                ${expanded ? `<div class="ccr-rule-expanded-details">
                    <p class="ccr-rule-meta"><span>${escapeHtml(formatCcrSubstanceScopeLabel(rule))}</span> · <span>${escapeHtml(formatCcrSectionScopeLabel(rule))}</span></p>
                    <p class="ccr-rule-meta">${escapeHtml(formatCcrPrecedenceLabel(rule))}</p>
                    <p class="ccr-rule-meta ccr-rule-usage">${usage || '<span class="ccr-usage-chip">All sections</span>'}</p>
                    <p class="ccr-rule-meta">Matches: <strong>${escapeHtml(String(matchCount))}</strong> record${matchCount === 1 ? '' : 's'} · Updated ${escapeHtml(formatCcrLastModifiedLabel(rule.lastModified))}</p>
                </div>` : ''}
            </div>
        </div>
        <button type="button" class="secondary-btn btn-sm ccr-card-expand-btn" aria-expanded="${expanded ? 'true' : 'false'}" onclick="toggleCcrRuleCardExpanded('${escapeAttr(rule.id)}')">${expanded ? 'Hide' : 'Show'}</button>
        ${expanded ? `<div class="ccr-rule-card-actions">
            <button type="button" class="secondary-btn btn-sm" onclick="openConditionalColorRuleEditor('${escapeAttr(rule.id)}')">Edit</button>
            <button type="button" class="secondary-btn btn-sm" onclick="duplicateConditionalColorRule('${escapeAttr(rule.id)}'); renderConditionalColorRulesSettings();">Duplicate</button>
            <button type="button" class="secondary-btn btn-sm" onclick="addNextCcrRangeFromRule('${escapeAttr(rule.id)}')">Add next range</button>
            <button type="button" class="danger-btn btn-sm" onclick="confirmDeleteConditionalColorRule('${escapeAttr(rule.id)}')">Delete</button>
        </div>` : ''}
        ${expanded ? (() => {
            const siblings = getCcrSiblingRangeRules(rule);
            if (!siblings.length || siblings[0].id !== rule.id) return '';
            return `<div class="ccr-rule-range-map">${renderCcrRangeVisualizer(siblings, rule.id)}</div>`;
        })() : ''}
    </article>`;
}

function renderConditionalColorRulesList() {
    const root = document.getElementById('ccr-rules-list');
    if (!root) return;
    const state = ensureConditionalColorRules();
    const enabledToggle = document.getElementById('ccr-rules-enabled');
    if (enabledToggle) enabledToggle.checked = state.enabled !== false;

    const filters = getCcrManagerUiState();
    filters.groupBy = state.ui?.groupBy || filters.groupBy || 'metric';
    const rules = filterAndSortConditionalColorRules(state.rules, filters);
    const conflicts = detectConditionalColorRuleConflicts(state.rules);
    const matchCounts = computeConditionalColorRuleMatchCounts();
    const selected = new Set(filters.selectedIds || []);

    const countEl = document.getElementById('ccr-manager-result-count');
    if (countEl) {
        countEl.textContent = `${rules.length} rule${rules.length === 1 ? '' : 's'} shown · ${state.rules.length} total · ${selected.size} selected`;
    }
    document.getElementById('ccr-manager-bulk-edit')?.classList.toggle('hidden', selected.size < 2);

    if (!state.rules.length) {
        root.innerHTML = '<p class="empty-hint">No rules yet. Add a rule or load example rules.</p>';
        return;
    }
    if (!rules.length) {
        root.innerHTML = '<p class="empty-hint">No rules match the current search/filters.</p>';
        return;
    }

    const groups = buildCcrRuleGroups(rules, { groupBy: filters.groupBy, conflicts, matchCounts });
    root.innerHTML = groups.map(group => {
        const groupSelected = group.rules.every(rule => selected.has(rule.id));
        return `<section class="ccr-rule-group" data-group-id="${escapeAttr(group.id)}">
            <header class="ccr-rule-group-header">
                <button type="button" class="secondary-btn btn-sm ccr-group-toggle" aria-expanded="${group.collapsed ? 'false' : 'true'}" onclick="toggleCcrRuleGroupCollapsed('${escapeAttr(group.id)}')">${group.collapsed ? '▶' : '▼'}</button>
                <label class="ccr-select-mini">
                    <input type="checkbox" ${groupSelected ? 'checked' : ''} onchange="selectCcrRuleGroupFromUi('${escapeAttr(group.id)}', this.checked)" aria-label="Select all in ${escapeAttr(group.name)}">
                </label>
                <strong>${escapeHtml(group.name)}</strong>
                <span class="ccr-group-stat">${group.count} rules</span>
                <span class="ccr-group-stat">${group.enabledCount} enabled</span>
                <span class="ccr-group-stat">${group.conflictCount} overlaps</span>
                <span class="ccr-group-stat">${group.totalMatchCount} matches</span>
                <div class="ccr-group-actions">
                    <button type="button" class="secondary-btn btn-sm" onclick="bulkSetCcrRuleGroupEnabledFromUi('${escapeAttr(group.id)}', true)">Enable all</button>
                    <button type="button" class="secondary-btn btn-sm" onclick="bulkSetCcrRuleGroupEnabledFromUi('${escapeAttr(group.id)}', false)">Disable all</button>
                    <button type="button" class="secondary-btn btn-sm" onclick="duplicateCcrRuleGroupFromUi('${escapeAttr(group.id)}')">Duplicate group</button>
                    <button type="button" class="secondary-btn btn-sm" onclick="exportCcrRuleGroupFromUi('${escapeAttr(group.id)}')">Export group</button>
                    <button type="button" class="secondary-btn btn-sm" onclick="importCcrRuleGroupFromUi('${escapeAttr(group.id)}')">Import group</button>
                    <button type="button" class="danger-btn btn-sm" onclick="deleteCcrRuleGroupFromUi('${escapeAttr(group.id)}')">Delete group</button>
                </div>
            </header>
            ${group.collapsed ? '' : `<div class="ccr-rule-group-body">${(() => {
                if (group.groupBy !== 'metric') {
                    return group.rules.map(rule => renderCcrRuleManagerCard(rule, { conflicts, matchCounts, selected })).join('');
                }
                let currentSubstance = null;
                return group.rules.map(rule => {
                    const label = formatCcrSubstanceScopeLabel(rule);
                    const header = label !== currentSubstance
                        ? `<h4 class="ccr-rule-subgroup-heading">${escapeHtml(label)}</h4>`
                        : '';
                    currentSubstance = label;
                    return header + renderCcrRuleManagerCard(rule, { conflicts, matchCounts, selected });
                }).join('');
            })()}</div>`}
        </section>`;
    }).join('');
}

function populateCcrManagerFilterSelects() {
    const substanceEl = document.getElementById('ccr-manager-filter-substance');
    if (substanceEl) {
        const current = substanceEl.value || getCcrManagerUiState().substance || 'all';
        const substances = typeof getActiveSubstances === 'function' ? getActiveSubstances() : (appData.substances || []);
        substanceEl.innerHTML = `<option value="all">All substances</option>` + substances.map(s =>
            `<option value="${escapeAttr(s.id)}">${escapeHtml(s.icon || '')} ${escapeHtml(s.name)}</option>`
        ).join('');
        substanceEl.value = [...substanceEl.options].some(o => o.value === current) ? current : 'all';
    }
    const sectionEl = document.getElementById('ccr-manager-filter-section');
    if (sectionEl && !sectionEl.dataset.ready) {
        sectionEl.innerHTML = `<option value="all">All sections</option>` + CCR_SECTIONS.map(s =>
            `<option value="${escapeAttr(s.id)}">${escapeHtml(s.label)}</option>`
        ).join('');
        sectionEl.dataset.ready = '1';
    }
    const metricEl = document.getElementById('ccr-manager-filter-metric');
    if (metricEl && !metricEl.dataset.ready) {
        const active = CCR_METRICS.filter(m => !m.deleted && getCcrMetricSettings(m.key)?.visible !== false);
        const byGroup = new Map();
        active.forEach(m => {
            const gid = m.group || 'use';
            if (!byGroup.has(gid)) byGroup.set(gid, []);
            byGroup.get(gid).push(getCcrMetricUiDef(m.key) || m);
        });
        let metricHtml = `<option value="all">All metrics</option>`;
        CCR_METRIC_GROUP_ORDER.forEach(group => {
            const list = byGroup.get(group.id);
            if (!list?.length) return;
            const customGroup = list.find(item => item.settings?.groupName
                && item.settings.groupName !== getDefaultCcrMetricSettings(item.key)?.groupName);
            metricHtml += `<optgroup label="${escapeAttr(customGroup?.settings?.groupName || group.label)}">`;
            list.forEach(m => {
                metricHtml += `<option value="${escapeAttr(m.key)}">${escapeHtml(m.label)}</option>`;
            });
            metricHtml += '</optgroup>';
        });
        metricEl.innerHTML = metricHtml;
        metricEl.dataset.ready = '1';
    }
    const sortEl = document.getElementById('ccr-manager-sort');
    if (sortEl) {
        const current = sortEl.value || getCcrManagerUiState().sort || 'priority';
        sortEl.innerHTML = CCR_MANAGER_SORT_OPTIONS.map(o =>
            `<option value="${escapeAttr(o.id)}">${escapeHtml(o.label)}</option>`
        ).join('');
        sortEl.value = [...sortEl.options].some(o => o.value === current) ? current : 'priority';
        sortEl.dataset.ready = '1';
    }
    syncCcrManagerFilterControls();
}

function syncCcrManagerFilterControls() {
    const f = getCcrManagerUiState();
    const setVal = (id, value) => {
        const el = document.getElementById(id);
        if (el) el.value = value;
    };
    setVal('ccr-manager-search', f.search || '');
    setVal('ccr-manager-filter-substance', f.substance || 'all');
    setVal('ccr-manager-filter-section', f.section || 'all');
    setVal('ccr-manager-filter-metric', f.metric || 'all');
    setVal('ccr-manager-filter-enabled', f.enabled || 'all');
    setVal('ccr-manager-sort', f.sort || 'priority');
    setVal('ccr-manager-sort-dir', f.sortDir || 'desc');
    setVal('ccr-manager-group-by', f.groupBy || ensureConditionalColorRules().ui?.groupBy || 'substance');
}

function onCcrManagerFiltersChanged() {
    setCcrManagerFilters({
        search: document.getElementById('ccr-manager-search')?.value || '',
        substance: document.getElementById('ccr-manager-filter-substance')?.value || 'all',
        section: document.getElementById('ccr-manager-filter-section')?.value || 'all',
        metric: document.getElementById('ccr-manager-filter-metric')?.value || 'all',
        enabled: document.getElementById('ccr-manager-filter-enabled')?.value || 'all',
        sort: document.getElementById('ccr-manager-sort')?.value || 'priority',
        sortDir: document.getElementById('ccr-manager-sort-dir')?.value || 'desc',
        groupBy: document.getElementById('ccr-manager-group-by')?.value || 'substance'
    });
    renderConditionalColorRulesList();
}

function toggleCcrManagerRuleSelection(ruleId, checked) {
    const ui = getCcrManagerUiState();
    const id = String(ruleId);
    if (checked) {
        if (!ui.selectedIds.includes(id)) ui.selectedIds.push(id);
    } else {
        ui.selectedIds = ui.selectedIds.filter(x => x !== id);
    }
}

function selectAllVisibleCcrManagerRules(checked) {
    const ui = getCcrManagerUiState();
    const visible = filterAndSortConditionalColorRules(getConditionalColorRules(), ui).map(r => r.id);
    if (checked) {
        const set = new Set([...ui.selectedIds, ...visible]);
        ui.selectedIds = [...set];
    } else {
        const drop = new Set(visible);
        ui.selectedIds = ui.selectedIds.filter(id => !drop.has(id));
    }
    renderConditionalColorRulesList();
}

function getSelectedCcrManagerRuleIds() {
    return getCcrManagerUiState().selectedIds.slice();
}

function bulkEnableSelectedColorRules() {
    const ids = getSelectedCcrManagerRuleIds();
    if (!ids.length) {
        if (typeof showToast === 'function') showToast('Select rules first');
        return;
    }
    bulkSetConditionalColorRulesEnabled(ids, true);
    renderConditionalColorRulesSettings();
    if (typeof showToast === 'function') showToast(`Enabled ${ids.length} rule${ids.length === 1 ? '' : 's'}`);
}

function bulkDisableSelectedColorRules() {
    const ids = getSelectedCcrManagerRuleIds();
    if (!ids.length) {
        if (typeof showToast === 'function') showToast('Select rules first');
        return;
    }
    bulkSetConditionalColorRulesEnabled(ids, false);
    renderConditionalColorRulesSettings();
    if (typeof showToast === 'function') showToast(`Disabled ${ids.length} rule${ids.length === 1 ? '' : 's'}`);
}

function bulkDeleteSelectedColorRules() {
    const ids = getSelectedCcrManagerRuleIds();
    if (!ids.length) {
        if (typeof showToast === 'function') showToast('Select rules first');
        return;
    }
    if (!confirm(`Delete ${ids.length} selected color rule${ids.length === 1 ? '' : 's'}? This does not change tracked data.`)) return;
    bulkDeleteConditionalColorRules(ids);
    renderConditionalColorRulesSettings();
    if (typeof showToast === 'function') showToast('Selected rules deleted');
}

function downloadSelectedColorRulesExport() {
    const ids = getSelectedCcrManagerRuleIds();
    if (!ids.length) {
        if (typeof showToast === 'function') showToast('Select rules first');
        return;
    }
    const json = exportConditionalColorRulesSelectionJson(ids);
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `recovery-tracker-color-rules-selected-${getLocalDateString?.() || 'export'}.json`;
    a.click();
    URL.revokeObjectURL(url);
}

function loadRecoveryColorPresetsFromUi() {
    const state = ensureConditionalColorRules();
    let replace = true;
    if (state.rules.length) {
        replace = confirm('Load Example Rules.\n\nOK = replace existing rules\nCancel = keep existing and only add missing examples');
    }
    loadRecoveryColorRulePresets(appData, { replace });
    renderConditionalColorRulesSettings();
    if (typeof showToast === 'function') {
        showToast(replace ? 'Example rules loaded (replaced)' : 'Missing example rules added');
    }
}

function confirmResetColorRulesToPresets() {
    if (!confirm('Replace all color rules with Example Rules? Existing custom rules will be removed.')) return;
    resetConditionalColorRulesToPresets();
    renderConditionalColorRulesSettings();
    if (typeof showToast === 'function') showToast('Example rules loaded');
}

function jumpToConflictingColorRule(ruleId) {
    const safeId = String(ruleId || '').replace(/\\/g, '\\\\').replace(/"/g, '\\"');
    const el = document.querySelector(`.ccr-rule-card[data-rule-id="${safeId}"]`);
    if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        el.classList.add('ccr-rule-flash');
        el.focus?.();
        setTimeout(() => el.classList.remove('ccr-rule-flash'), 1600);
    }
    openConditionalColorRuleEditor(ruleId);
}

function onCcrRuleDragStart(event, ruleId) {
    ccrDragRuleId = ruleId;
    try {
        event.dataTransfer.setData('text/plain', ruleId);
        event.dataTransfer.effectAllowed = 'move';
    } catch (_) { /* ignore */ }
    event.currentTarget?.classList.add('is-dragging');
}

function onCcrRuleDragOver(event) {
    event.preventDefault();
    try { event.dataTransfer.dropEffect = 'move'; } catch (_) { /* ignore */ }
}

function onCcrRuleDrop(event, targetRuleId) {
    event.preventDefault();
    const fromId = ccrDragRuleId || (() => {
        try { return event.dataTransfer.getData('text/plain'); } catch (_) { return null; }
    })();
    if (!fromId || fromId === targetRuleId) return;
    const ui = getCcrManagerUiState();
    const visible = filterAndSortConditionalColorRules(getConditionalColorRules(), ui).map(r => r.id);
    const fromIdx = visible.indexOf(fromId);
    const toIdx = visible.indexOf(targetRuleId);
    if (fromIdx < 0 || toIdx < 0) return;
    visible.splice(fromIdx, 1);
    visible.splice(toIdx, 0, fromId);
    // Keep non-visible rules after visible ones
    const allIds = getConditionalColorRules().map(r => r.id);
    const rest = allIds.filter(id => !visible.includes(id));
    setConditionalColorRulePriorityOrder([...visible, ...rest]);
    renderConditionalColorRulesSettings();
}

function onCcrRuleDragEnd() {
    ccrDragRuleId = null;
    document.querySelectorAll('.ccr-rule-card.is-dragging').forEach(el => el.classList.remove('is-dragging'));
}

function renderConditionalColorRulesSettings() {
    populateCcrSubstanceSelect();
    populateCcrManagerFilterSelects();
    populateCcrMetricSelect();
    populateCcrOperatorSelectForMetric(document.getElementById('ccr-rule-metric')?.value || 'useAmount');
    const sectionsEl = document.getElementById('ccr-rule-sections');
    if (sectionsEl && !sectionsEl.options.length) {
        sectionsEl.innerHTML = CCR_SECTIONS.map(s => `<option value="${s.id}">${escapeHtml(s.label)}</option>`).join('');
    }
    renderConditionalColorRulesList();
    updateCcrOperatorFieldsVisibility();
    updateCcrLivePreview();
}

function openConditionalColorRuleEditor(ruleId = null) {
    const state = ensureConditionalColorRules();
    const rule = ruleId ? state.rules.find(r => r.id === ruleId) : null;
    const editor = document.getElementById('ccr-rule-editor');
    editor?.classList.remove('hidden');
    populateCcrSubstanceSelect();
    fillCcrEditorForm(rule || {
        id: ccrNewId(),
        name: 'New rule',
        enabled: true,
        metric: 'useAmount',
        operator: 'gt',
        value: 0,
        priority: 100,
        sectionScope: ['all'],
        substanceScope: 'all',
        colors: { background: 'rgba(76, 175, 80, 0.22)', text: '#81c784', border: '#4caf50' },
        statusLabel: ''
    });
    refreshCcrColorPalettes();
    updateCcrRangeVisualizer();
}

function closeConditionalColorRuleEditor() {
    document.getElementById('ccr-rule-editor')?.classList.add('hidden');
    ccrEditingRuleId = null;
}

function saveConditionalColorRuleFromForm() {
    const draft = getCcrEditorDraftFromForm();
    if (!draft.name.trim()) {
        if (typeof showToast === 'function') showToast('Rule name is required');
        return;
    }
    const bgValidation = validateCcrBackgroundColor(draft.colors.background);
    if (!bgValidation.ok) {
        setCcrBackgroundColorError(bgValidation.message);
        if (typeof showToast === 'function') showToast(bgValidation.message);
        document.getElementById('ccr-rule-bg')?.focus();
        return;
    }
    draft.colors.background = bgValidation.value;
    saveConditionalColorRule(draft);
    closeConditionalColorRuleEditor();
    renderConditionalColorRulesSettings();
    if (typeof showToast === 'function') showToast('Color rule saved');
    if (typeof refreshAppAfterDataChange === 'function') {
        try { refreshAppAfterDataChange({ skipSave: true }); } catch (_) { /* ignore */ }
    }
}

function confirmDeleteConditionalColorRule(ruleId) {
    if (!confirm('Delete this color rule? This does not change any tracked data.')) return;
    deleteConditionalColorRule(ruleId);
    renderConditionalColorRulesSettings();
}

function onConditionalColorRulesEnabledToggle(checked) {
    setConditionalColorRulesEnabled(!!checked);
    renderConditionalColorRulesSettings();
}

function downloadConditionalColorRulesExport() {
    const json = exportConditionalColorRulesJson();
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `recovery-tracker-color-rules-${getLocalDateString?.() || 'export'}.json`;
    a.click();
    URL.revokeObjectURL(url);
}

function onConditionalColorRulesImportFile(event) {
    const file = event?.target?.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
        try {
            const replace = confirm('Replace existing rules with imported rules?\n\nOK = replace\nCancel = merge');
            importConditionalColorRulesJson(String(reader.result || ''), appData, { replace });
            renderConditionalColorRulesSettings();
            if (typeof showToast === 'function') showToast('Color rules imported');
        } catch (err) {
            alert(err?.message || 'Failed to import color rules');
        }
        event.target.value = '';
    };
    reader.readAsText(file);
}

function hslToHexColor(h, s = 1, l = 0.5) {
    const hue = ((Number(h) % 360) + 360) % 360;
    const sat = Math.max(0, Math.min(1, s));
    const light = Math.max(0, Math.min(1, l));
    const c = (1 - Math.abs(2 * light - 1)) * sat;
    const x = c * (1 - Math.abs(((hue / 60) % 2) - 1));
    const m = light - c / 2;
    let r = 0;
    let g = 0;
    let b = 0;
    if (hue < 60) { r = c; g = x; }
    else if (hue < 120) { r = x; g = c; }
    else if (hue < 180) { g = c; b = x; }
    else if (hue < 240) { g = x; b = c; }
    else if (hue < 300) { r = x; b = c; }
    else { r = c; b = x; }
    return rgbToHexColor((r + m) * 255, (g + m) * 255, (b + m) * 255);
}

function getCcrChannelSelectedHex(channel) {
    if (channel === 'background') {
        const raw = document.getElementById('ccr-rule-bg')?.value || '';
        const parsed = parseCssColor(raw);
        return parsed ? rgbToHexColor(parsed.r, parsed.g, parsed.b) : '';
    }
    if (channel === 'text') {
        return normalizeHexColor(document.getElementById('ccr-rule-text')?.value || '', '').slice(0, 7);
    }
    if (channel === 'border') {
        return normalizeHexColor(document.getElementById('ccr-rule-border')?.value || '', '').slice(0, 7);
    }
    return '';
}

function renderCcrColorPalette(channel) {
    const selected = (getCcrChannelSelectedHex(channel) || '').toLowerCase();
    const rangeButtons = channel === 'background'
        ? `<div class="ccr-range-scheme-actions">${Object.entries(CCR_RANGE_COLOR_SCHEMES).map(([id, scheme]) =>
            `<button type="button" class="secondary-btn btn-sm" onclick="generateCcrRangeRulesFromEditor('${escapeAttr(id)}')">${id === 'rainbow' ? '🌈 ' : ''}${escapeHtml(scheme.label)}</button>`
        ).join('')}</div>`
        : '';
    const swatches = CCR_QUICK_COLOR_PRESETS.map(preset => {
        const isSelected = selected === preset.hex.toLowerCase();
        return `<button type="button" class="ccr-swatch-btn${isSelected ? ' is-selected' : ''}"
            style="--ccr-swatch:${escapeAttr(preset.hex)}"
            data-ccr-channel="${escapeAttr(channel)}"
            data-ccr-hex="${escapeAttr(preset.hex)}"
            aria-label="${escapeAttr(preset.label)}"
            aria-pressed="${isSelected ? 'true' : 'false'}"
            title="${escapeAttr(preset.label)}"
            onclick="applyCcrQuickColor('${escapeAttr(channel)}', '${escapeAttr(preset.hex)}')"></button>`;
    }).join('');
    return `
        <div class="ccr-color-palette" data-ccr-palette="${escapeAttr(channel)}" role="group" aria-label="${escapeAttr(channel)} color presets">
            <div class="ccr-swatch-row">${swatches}</div>
            <div class="ccr-rainbow-strip"
                role="slider"
                tabindex="0"
                aria-label="${escapeAttr(channel)} rainbow hue picker"
                aria-valuemin="0"
                aria-valuemax="360"
                aria-valuenow="0"
                data-ccr-channel="${escapeAttr(channel)}"
                onmousedown="onCcrRainbowPointerDown(event, '${escapeAttr(channel)}')"
                onkeydown="onCcrRainbowKeyDown(event, '${escapeAttr(channel)}')"></div>
            <div class="ccr-color-palette-actions">
                <button type="button" class="secondary-btn btn-sm" onclick="clearCcrColorChannel('${escapeAttr(channel)}')">Clear color</button>
                <button type="button" class="secondary-btn btn-sm" onclick="resetCcrColorChannel('${escapeAttr(channel)}')">Reset</button>
            </div>
            ${rangeButtons}
        </div>`;
}

function refreshCcrColorPalettes() {
    ['background', 'text', 'border'].forEach(channel => {
        const host = document.getElementById(`ccr-palette-${channel}`);
        if (host) host.innerHTML = renderCcrColorPalette(channel);
    });
}

function applyCcrQuickColor(channel, hex) {
    const normalized = normalizeHexColor(hex, '#4caf50').slice(0, 7);
    if (channel === 'background') {
        const opacity = Number(document.getElementById('ccr-rule-bg-opacity')?.value);
        const pct = Number.isFinite(opacity) ? opacity : 100;
        const picker = document.getElementById('ccr-rule-bg-picker');
        const text = document.getElementById('ccr-rule-bg');
        if (picker) picker.value = normalized;
        if (text) text.value = composeCcrBackgroundFromPicker(normalized, pct);
        setCcrBackgroundOpacityUi(pct);
        setCcrBackgroundColorError('');
    } else if (channel === 'text' || channel === 'border') {
        const picker = document.getElementById(`ccr-rule-${channel}-picker`);
        const hexEl = document.getElementById(`ccr-rule-${channel}-hex`);
        const value = document.getElementById(`ccr-rule-${channel}`);
        if (picker) picker.value = normalized;
        if (hexEl) hexEl.value = normalized;
        if (value) value.value = normalized;
    }
    refreshCcrColorPalettes();
    updateCcrLivePreview();
}

function clearCcrColorChannel(channel) {
    if (channel === 'background') {
        const text = document.getElementById('ccr-rule-bg');
        if (text) text.value = '';
        setCcrBackgroundColorError('');
        setCcrBackgroundOpacityUi(100);
    } else if (channel === 'text' || channel === 'border') {
        const picker = document.getElementById(`ccr-rule-${channel}-picker`);
        const hexEl = document.getElementById(`ccr-rule-${channel}-hex`);
        const value = document.getElementById(`ccr-rule-${channel}`);
        // Clear means no color override in preview; keep picker at a neutral so UI stays usable
        if (value) value.value = '';
        if (hexEl) hexEl.value = '';
        if (picker) picker.value = channel === 'text' ? '#ffffff' : '#000000';
    }
    refreshCcrColorPalettes();
    updateCcrLivePreview();
}

function resetCcrColorChannel(channel) {
    const defaults = CCR_COLOR_CHANNEL_DEFAULTS;
    if (channel === 'background') {
        applyCcrBackgroundControlsFromValue(defaults.background);
    } else {
        applyCcrQuickColor(channel, defaults[channel]);
        return;
    }
    refreshCcrColorPalettes();
    updateCcrLivePreview();
}

function ccrRainbowHexFromClientX(el, clientX) {
    if (!el) return '#4caf50';
    const rect = el.getBoundingClientRect();
    const ratio = rect.width > 0 ? Math.max(0, Math.min(1, (clientX - rect.left) / rect.width)) : 0;
    const hue = ratio * 360;
    el.setAttribute('aria-valuenow', String(Math.round(hue)));
    return hslToHexColor(hue);
}

function onCcrRainbowPointerDown(event, channel) {
    event.preventDefault();
    const el = event.currentTarget;
    const apply = (clientX) => applyCcrQuickColor(channel, ccrRainbowHexFromClientX(el, clientX));
    apply(event.clientX);
    const onMove = (ev) => apply(ev.clientX);
    const onUp = () => {
        document.removeEventListener('mousemove', onMove);
        document.removeEventListener('mouseup', onUp);
    };
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
}

function onCcrRainbowKeyDown(event, channel) {
    const el = event.currentTarget;
    let hue = Number(el?.getAttribute('aria-valuenow')) || 0;
    if (event.key === 'ArrowRight' || event.key === 'ArrowUp') hue = Math.min(360, hue + 5);
    else if (event.key === 'ArrowLeft' || event.key === 'ArrowDown') hue = Math.max(0, hue - 5);
    else if (event.key === 'Home') hue = 0;
    else if (event.key === 'End') hue = 360;
    else return;
    event.preventDefault();
    el.setAttribute('aria-valuenow', String(hue));
    applyCcrQuickColor(channel, hslToHexColor(hue));
}

function getCcrSiblingRangeRules(seedRule = null, data = appData) {
    const draft = seedRule || getCcrEditorDraftFromForm();
    if (!draft) return [];
    return getConditionalColorRules(data)
        .filter(rule => rule.metric === draft.metric
            && normalizeCcrVisualTarget(rule.visualTarget) === normalizeCcrVisualTarget(draft.visualTarget)
            && scopesOverlapSubstances(rule.substanceScope, draft.substanceScope)
            && scopesOverlapSections(rule.sectionScope, draft.sectionScope)
            && ccrNumericRange(rule))
        .slice()
        .sort((a, b) => {
            const ar = ccrNumericRange(a);
            const br = ccrNumericRange(b);
            return (ar.lo - br.lo) || (ar.hi - br.hi);
        });
}

function fixCcrRangeBoundariesForRule(ruleId, data = appData) {
    const state = ensureConditionalColorRules(data);
    const source = state.rules.find(r => String(r.id) === String(ruleId));
    if (!source) return [];
    const siblings = getCcrSiblingRangeRules(source, data)
        .filter(r => ['between', 'betweenInclusive', 'betweenExclusive'].includes(r.operator));
    const ids = new Set(siblings.map(r => String(r.id)));
    state.rules = state.rules.map(rule => {
        if (!ids.has(String(rule.id))) return rule;
        return normalizeConditionalColorRule({
            ...rule,
            operator: 'between',
            rangeBoundary: 'inclusiveExclusive',
            lastModified: new Date().toISOString()
        });
    }).filter(Boolean);
    persistConditionalColorRulesState({ rules: state.rules }, data);
    invalidateConditionalColorRuleMatchCache();
    if (typeof renderConditionalColorRulesSettings === 'function') renderConditionalColorRulesSettings();
    if (typeof showToast === 'function') showToast('Range boundaries set to inclusive lower, exclusive upper');
    return state.rules.filter(r => ids.has(String(r.id)));
}

function formatCcrRangeTick(n, rule = null) {
    if (!Number.isFinite(n)) return n > 0 ? '∞' : '−∞';
    if (rule && isCcrDurationMetric(rule.metric)) {
        return formatCcrDurationThresholdLabel(n);
    }
    if (rule && isCcrTimeGapMetric(rule.metric)) {
        return formatCcrUseGapThresholdLabel(n);
    }
    if (Math.abs(n - Math.round(n)) < 1e-9) return String(Math.round(n));
    return String(Math.round(n * 100) / 100);
}

function ccrRangeSwatchEmoji(rule) {
    const parsed = parseCssColor(rule?.colors?.background || rule?.colors?.border || rule?.colors?.text || '');
    if (!parsed) return '⚪';
    const { r, g, b } = parsed;
    const max = Math.max(r, g, b);
    const min = Math.min(r, g, b);
    if (max < 40) return '⚫';
    if (min > 220) return '⚪';
    if (g > r && g > b) return '🟢';
    if (r > g && r > b && g > 80) return '🟠';
    if (r > g && r > b) return '🔴';
    if (b > r && b > g) return '🔵';
    if (r > 180 && g > 180 && b < 120) return '🟡';
    if (r > 150 && b > 150) return '🟣';
    return '🔘';
}

function renderCcrRangeVisualizer(rules = null, highlightId = null) {
    const list = (rules || getCcrSiblingRangeRules()).slice();
    if (!list.length) {
        return '<p class="settings-hint">Add Between / comparison rules for this metric to see the range map.</p>';
    }
    const ticks = [];
    list.forEach(rule => {
        const range = ccrNumericRange(rule);
        if (!range) return;
        if (Number.isFinite(range.lo)) ticks.push(range.lo);
        if (Number.isFinite(range.hi)) ticks.push(range.hi);
    });
    const uniqueTicks = [...new Set(ticks.map(t => Math.round(t * 1000) / 1000))].sort((a, b) => a - b);
    if (!uniqueTicks.length) uniqueTicks.push(0);
    const durationSample = list.find(r => isCcrDurationMetric(r.metric)) || null;
    const axis = uniqueTicks.map(t => formatCcrRangeTick(t, durationSample)).join('────') + '────+';
    const markers = list.map(rule => {
        const range = ccrNumericRange(rule);
        const mark = ccrRangeSwatchEmoji(rule);
        const active = highlightId && rule.id === highlightId ? ' is-active' : '';
        return `<span class="ccr-range-marker${active}" title="${escapeAttr(rule.name + ': ' + formatCcrConditionSummary(rule))}">${mark}<span class="ccr-range-marker-label">${escapeHtml(formatCcrRangeTick(range.lo, rule))}–${escapeHtml(formatCcrRangeTick(range.hi, rule))}</span></span>`;
    }).join('');
    return `
        <div class="ccr-range-visualizer" role="img" aria-label="Range map for related color rules">
            <div class="ccr-range-axis" aria-hidden="true">${escapeHtml(axis)}</div>
            <div class="ccr-range-markers">${markers}</div>
            <ul class="ccr-range-legend">
                ${list.map(rule => `<li${highlightId && rule.id === highlightId ? ' class="is-active"' : ''}>${escapeHtml(rule.name)} · ${escapeHtml(formatCcrConditionSummary(rule))}</li>`).join('')}
            </ul>
        </div>`;
}

function updateCcrRangeVisualizer() {
    const host = document.getElementById('ccr-range-visualizer');
    if (!host) return;
    const draft = getCcrEditorDraftFromForm();
    const siblings = getCcrSiblingRangeRules(draft);
    // Include unsaved draft range when editing
    const draftRange = ccrNumericRange(draft);
    const combined = siblings.filter(r => r.id !== draft.id);
    if (draftRange) combined.push(draft);
    combined.sort((a, b) => {
        const ar = ccrNumericRange(a);
        const br = ccrNumericRange(b);
        return (ar.lo - br.lo) || (ar.hi - br.hi);
    });
    host.innerHTML = renderCcrRangeVisualizer(combined, draft.id);
}

function buildNextCcrRangeDraft(src) {
    const source = normalizeConditionalColorRule(src);
    const range = ccrNumericRange(source);
    let nextValue = 0;
    let nextValueTo = 1;
    let operator = 'between';
    let rangeBoundary = 'inclusiveExclusive';
    if (range && Number.isFinite(range.hi)) {
        nextValue = range.hi;
        nextValueTo = Number.isFinite(range.hi) ? range.hi + Math.max(1, Math.abs(range.hi - range.lo) || 1) : range.hi + 1;
    } else if (range && range.hi === Infinity && Number.isFinite(range.lo)) {
        operator = 'gt';
        rangeBoundary = 'inclusiveExclusive';
        nextValue = range.lo;
        nextValueTo = '';
    }
    // Duration ranges are computed in minutes; persist next draft in hours.
    let valueUnit = source.valueUnit;
    let durationValueVersion = source.durationValueVersion;
    if (isCcrDurationMetric(source.metric)) {
        valueUnit = 'hours';
        durationValueVersion = 2;
        nextValue = ccrDurationMinutesToHours(nextValue);
        if (nextValueTo !== '' && nextValueTo != null) {
            nextValueTo = ccrDurationMinutesToHours(nextValueTo);
        }
    }
    return normalizeConditionalColorRule({
        ...source,
        id: ccrNewId(),
        name: `${source.name.replace(/\s*\(copy\)\s*$/i, '').replace(/\s*range\s*\d*$/i, '').trim()} range`,
        operator,
        rangeBoundary,
        value: nextValue,
        valueTo: operator.startsWith('between') ? nextValueTo : '',
        valueUnit,
        durationValueVersion,
        priority: (Number(source.priority) || 0) - 1,
        statusLabel: '',
        isPreset: false,
        presetId: null,
        createdAt: new Date().toISOString(),
        lastModified: new Date().toISOString()
    });
}

function ccrRangeSchemeColorSet(hex) {
    const normalized = normalizeHexColor(hex, '#4caf50').slice(0, 7);
    return {
        background: composeCcrBackgroundFromPicker(normalized, 22),
        text: normalized,
        border: normalized
    };
}

function buildCcrGeneratedRangeRulesFromDraft(draft, schemeId = 'rainbow') {
    const base = normalizeConditionalColorRule(draft || getCcrEditorDraftFromForm());
    const scheme = CCR_RANGE_COLOR_SCHEMES[schemeId] || CCR_RANGE_COLOR_SCHEMES.rainbow;
    const ranges = [
        { label: '0-1', operator: 'between', value: 0, valueTo: 1, rangeBoundary: 'inclusiveExclusive' },
        { label: '1-2', operator: 'between', value: 1, valueTo: 2, rangeBoundary: 'inclusiveExclusive' },
        { label: '2-3', operator: 'between', value: 2, valueTo: 3, rangeBoundary: 'inclusiveExclusive' },
        { label: '3-4', operator: 'between', value: 3, valueTo: 4, rangeBoundary: 'inclusiveExclusive' },
        { label: '>4', operator: 'gte', value: 4, valueTo: '', rangeBoundary: 'inclusiveExclusive' }
    ];
    const now = new Date().toISOString();
    const metric = getCcrMetricUiDef(base.metric)?.label || getCcrMetricDef(base.metric)?.label || base.metric || 'Metric';
    return ranges.map((range, index) => normalizeConditionalColorRule({
        ...base,
        id: ccrNewId('range'),
        name: `${metric} ${range.label}`,
        operator: range.operator,
        rangeBoundary: range.rangeBoundary,
        value: range.value,
        valueTo: range.valueTo,
        priority: (Number(base.priority) || 100) - index,
        colors: ccrRangeSchemeColorSet(scheme.colors[index]),
        statusLabel: '',
        isPreset: false,
        presetId: null,
        createdAt: now,
        lastModified: now
    }, index));
}

function generateCcrRangeRulesFromEditor(schemeId = 'rainbow', data = appData) {
    const rules = buildCcrGeneratedRangeRulesFromDraft(getCcrEditorDraftFromForm(), schemeId);
    const state = ensureConditionalColorRules(data);
    state.rules.push(...rules);
    persistConditionalColorRulesState({ rules: state.rules }, data);
    invalidateConditionalColorRuleMatchCache();
    renderConditionalColorRulesSettings();
    closeConditionalColorRuleEditor();
    if (typeof showToast === 'function') showToast(`Generated ${rules.length} range rules`);
    return rules;
}

function duplicateConditionalColorRuleChangeRange(ruleId, data = appData) {
    const state = ensureConditionalColorRules(data);
    const src = state.rules.find(r => r.id === ruleId);
    if (!src) return null;
    const copy = normalizeConditionalColorRule({
        ...src,
        id: ccrNewId(),
        name: `${src.name.replace(/\s*\(copy\)\s*$/i, '').trim()} (range)`,
        isPreset: false,
        presetId: null,
        createdAt: new Date().toISOString(),
        priority: (Number(src.priority) || 0) + 1,
        statusLabel: '',
        lastModified: new Date().toISOString()
    });
    state.rules.push(copy);
    persistConditionalColorRulesState({ rules: state.rules }, data);
    invalidateConditionalColorRuleMatchCache();
    openConditionalColorRuleEditor(copy.id);
    if (typeof showToast === 'function') showToast('Duplicated — adjust the range');
    return copy;
}

function addNextCcrRangeFromRule(ruleId = null, data = appData) {
    const state = ensureConditionalColorRules(data);
    const src = ruleId
        ? state.rules.find(r => r.id === ruleId)
        : (ccrEditingRuleId ? state.rules.find(r => r.id === ccrEditingRuleId) : getCcrEditorDraftFromForm());
    if (!src) {
        if (typeof showToast === 'function') showToast('Save or select a rule first');
        return null;
    }
    const draft = buildNextCcrRangeDraft(src);
    const editor = document.getElementById('ccr-rule-editor');
    editor?.classList.remove('hidden');
    fillCcrEditorForm(draft);
    populateCcrSubstanceSelect();
    refreshCcrColorPalettes();
    updateCcrRangeVisualizer();
    document.getElementById('ccr-rule-value')?.focus();
    if (typeof showToast === 'function') showToast('Add next range — set boundaries and save');
    return draft;
}

function syncCcrBackgroundColorInputs(source) {
    const picker = document.getElementById('ccr-rule-bg-picker');
    const text = document.getElementById('ccr-rule-bg');
    const opacity = document.getElementById('ccr-rule-bg-opacity');
    if (!picker || !text || !opacity) {
        updateCcrLivePreview();
        return;
    }

    if (source === picker || source === opacity) {
        const pct = Math.max(0, Math.min(100, Number(opacity.value)));
        setCcrBackgroundOpacityUi(Number.isFinite(pct) ? pct : 100);
        text.value = composeCcrBackgroundFromPicker(picker.value, Number.isFinite(pct) ? pct : 100);
        setCcrBackgroundColorError('');
    } else if (source === text) {
        const raw = String(text.value || '').trim();
        if (!raw) {
            setCcrBackgroundColorError('');
            updateCcrLivePreview();
            return;
        }
        const validation = validateCcrBackgroundColor(raw);
        if (!validation.ok) {
            setCcrBackgroundColorError(validation.message);
            updateCcrLivePreview();
            return;
        }
        setCcrBackgroundColorError('');
        const parsed = validation.parsed;
        picker.value = rgbToHexColor(parsed.r, parsed.g, parsed.b);
        setCcrBackgroundOpacityUi(Math.round(parsed.a * 100));
    }
    refreshCcrColorPalettes();
    updateCcrLivePreview();
}

function syncCcrColorInputs(source) {
    const pairs = [
        ['ccr-rule-text-picker', 'ccr-rule-text', 'ccr-rule-text-hex'],
        ['ccr-rule-border-picker', 'ccr-rule-border', 'ccr-rule-border-hex']
    ];
    pairs.forEach(([pickerId, valueId, hexId]) => {
        const picker = document.getElementById(pickerId);
        const value = document.getElementById(valueId);
        const hex = document.getElementById(hexId);
        if (!picker || !value || !hex) return;
        if (source === picker) {
            value.value = picker.value;
            hex.value = picker.value;
        } else if (source === hex) {
            const normalized = normalizeHexColor(hex.value, picker.value);
            hex.value = normalized.length === 9 ? normalized.slice(0, 7) : normalized;
            if (normalized.startsWith('#') && (normalized.length === 7 || normalized.length === 9)) {
                picker.value = normalized.slice(0, 7);
                value.value = normalized.length === 7 ? normalized : normalized.slice(0, 7);
            }
        } else if (source === value) {
            if (String(value.value).startsWith('#')) {
                const normalized = normalizeHexColor(value.value, picker.value);
                hex.value = normalized.slice(0, 7);
                if (normalized.length === 7 || normalized.length === 9) picker.value = normalized.slice(0, 7);
            }
        }
    });
    refreshCcrColorPalettes();
    updateCcrLivePreview();
}

function initConditionalColorRulesUi() {
    ensureConditionalColorRules();
    renderConditionalColorRulesSettings();
}


function initAppearanceZoom() {
    if (!appData.settings) appData.settings = {};
    appData.settings.appearanceZoom = getAppearanceZoom();
    if (appData.settings.phoneViewZoom == null) {
        appData.settings.phoneViewZoom = appData.settings.appearanceZoom;
    } else {
        appData.settings.phoneViewZoom = normalizeAppearanceZoom(appData.settings.phoneViewZoom);
    }
    if (appData.settings.laptopViewZoom == null) {
        appData.settings.laptopViewZoom = appData.settings.appearanceZoom;
    } else {
        appData.settings.laptopViewZoom = normalizeAppearanceZoom(appData.settings.laptopViewZoom);
    }
    appData.settings.appearanceSpacing = getAppearanceSpacing();
    applyAppearanceSpacing(appData.settings.appearanceSpacing);
    applyAppearanceZoom(getActiveAppearanceZoom());
    if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
        window.addEventListener('resize', updateAppearanceZoomLayoutMetrics, { passive: true });
    }
}

