    '/insights-calendar': { tab: 'insights-calendar-tab', view: null },
    '/home': { tab: 'dashboard-tab', view: null },
    '/log': { tab: 'use-log-tab', view: null },
    '/inventory': { tab: 'buy-tracker-tab', view: null },
