function getTapersEmptyMessage(view, substanceId, data = appData) {
    const name = goalSubstanceLabel(substanceId, data) || 'selected';
    if (view === 'history') return `No completed or archived ${name} tapers.`;
    return `No active ${name} tapers.`;
}

function getCompatibleTaperTemplates(substanceId, data = appData) {
    const allowed = new Set(
        typeof getTaperReductionTypesForSubstance === 'function'
            ? getTaperReductionTypesForSubstance(substanceId)
            : []
    );
    const sub = typeof getSubstance === 'function' ? getSubstance(substanceId, data) : null;
    if (sub?.costTrackingEnabled && typeof isNicotineVapeTaperEligible === 'function'
        && !isNicotineVapeTaperEligible(substanceId, data)) {
        allowed.add('reduce-buying');
    }
    if (typeof isNicotineVapeTaperEligible === 'function' && isNicotineVapeTaperEligible(substanceId, data)) {
        allowed.add('reduce-puffs');
        allowed.add('manual-weekly');
        allowed.add('nicotine-vape-purchase');
        allowed.add('reduce-buying');
    }
    return TAPER_TEMPLATES.filter(t => allowed.has(t.reductionType));
}

function refreshTapersCombinedViews() {
    if (typeof document === 'undefined') return;
    const prefs = typeof ensureCombinedNavPrefs === 'function' ? ensureCombinedNavPrefs() : {};
    const view = prefs.goalsPlansView || 'overview';
    if (view === 'overview') {
        const root = document.getElementById('gp-overview-root');
        if (root) root.innerHTML = renderGoalsPlansOverviewHtml(buildGoalsPlansOverview());
    } else if (typeof renderGoalsPlansRecordsView === 'function') {
        renderGoalsPlansRecordsView(view);
    }
}

function getUnifiedTaperCurrentStep(plan, data = appData) {
    if (!plan?.substanceId) return null;
    try {
        const byWeek = typeof buildTaperByWeekData === 'function'
            ? buildTaperByWeekData(plan.substanceId, plan)
            : null;
        return byWeek?.rows?.find(row => row.isCurrent) || byWeek?.rows?.[0] || null;
    } catch (_) {
        const today = typeof getLocalDateString === 'function' ? getLocalDateString() : '';
        return (plan.weeklyTargets || []).find(w => (w.weekStart || '') <= today && (w.weekEnd || '9999-12-31') >= today)
            || (plan.weeklyTargets || [])[0]
            || null;
    }
}

function normalizeUnifiedGoalPlanRecord(record, { kind, data = appData } = {}) {
    if (kind === 'goal') return null;
    const plan = record || {};
    const currentStep = getUnifiedTaperCurrentStep(plan, data);
    const status = typeof getTaperPlanStatus === 'function' ? getTaperPlanStatus(plan) : (plan.status || 'active');
    const plannedAmount = currentStep?.planned
        ?? currentStep?.targetAmount
        ?? currentStep?.weeklyMax
        ?? currentStep?.puffTarget
        ?? null;
    let progressPct = null;
    try {
        if (typeof getTaperPlanProgressSummary === 'function') {
            const summary = getTaperPlanProgressSummary(plan, data);
            if (summary?.progressPct != null) progressPct = summary.progressPct;
            else if (summary?.percentComplete != null) progressPct = summary.percentComplete;
        }
    } catch (_) { /* soft */ }
    return {
        type: 'taper',
        id: plan.id,
        name: plan.name || 'Untitled taper',
        description: plan.description || plan.notes || '',
        substanceId: plan.substanceId || DASHBOARD_ALL,
        substanceLabel: goalSubstanceLabel(plan.substanceId, data),
        category: plan.category || 'taper',
        metric: plan.metric || (TAPER_REDUCTION_LABELS[plan.reductionType] || plan.reductionType || 'Taper target'),
        startDate: plan.startDate || '',
        endDate: plan.endDate || '',
        status,
        priority: plan.priority || (plan.isPrimary ? 'high' : 'normal'),
        notes: plan.notes || '',
        repeatSetting: plan.repeatSetting || 'weekly',
        scheduledSteps: plan.weeklyTargets || [],
        plannedAmountPerStep: plannedAmount,
        spendingTarget: plan.monthlySpendTarget ?? plan.purchaseWeeklySpendTarget ?? null,
        purchaseTarget: plan.monthlyMax ?? plan.purchaseWeeklyAmountTarget ?? null,
        currentStep: currentStep?.weekNum || currentStep?.week || '—',
        stepStatus: currentStep?.statusLabel || currentStep?.status || '—',
        progressPct,
        linkedGoalIds: [],
        source: plan
    };
}

function getUnifiedGoalsPlansRecords(data = appData) {
    if (typeof ensureTaperPlansV2 === 'function') ensureTaperPlansV2(data);
    return (data.taperPlansV2 || [])
        .filter(Boolean)
        .map(plan => normalizeUnifiedGoalPlanRecord(plan, { kind: 'taper', data }))
        .filter(Boolean);
}

function unifiedGoalPlanIsActive(record) {
    return record.status === 'active' || record.status === 'paused' || record.status === 'draft' || record.status === 'upcoming';
}

function unifiedGoalPlanIsHistory(record) {
    return ['completed', 'archived', 'missed', 'cancelled', 'met'].includes(record.status);
}

function filterUnifiedGoalsPlansRecords(records, view, data = appData) {
    const pageSubstanceId = getTapersPageSubstanceId(data);
    if (view === 'history') {
        const filter = goalsPlansUiState.historyFilter || 'all';
        const status = goalsPlansUiState.historyStatus || 'all';
        return records.filter(record => {
            if (record.type !== 'taper') return false;
            if (!unifiedGoalPlanIsHistory(record)) return false;
            if (!taperPlanMatchesSubstance({ substanceId: record.substanceId }, pageSubstanceId, data)) return false;
            if (filter === 'completed-tapers' && record.status !== 'completed') return false;
            if (filter === 'archived' && record.status !== 'archived') return false;
            if (filter === 'missed' && record.status !== 'missed') return false;
            if (status !== 'all' && record.status !== status) return false;
            return true;
        });
    }

    const status = goalsPlansUiState.activeStatus || 'all';
    return records.filter(record => {
        if (record.type !== 'taper') return false;
        if (!unifiedGoalPlanIsActive(record)) return false;
        if (!taperPlanMatchesSubstance({ substanceId: record.substanceId }, pageSubstanceId, data)) return false;
        if (status !== 'all' && record.status !== status) return false;
        return true;
    });
}

function unifiedGoalPlanStatusLabel(record) {
    return typeof getTaperPlanStatusLabel === 'function' ? getTaperPlanProgressLabelSafe(record.status) : record.status;
}

function getTaperPlanProgressLabelSafe(status) {
    return typeof getTaperPlanStatusLabel === 'function' ? getTaperPlanStatusLabel(status) : String(status || '');
}

function renderUnifiedGoalPlanCard(record, data = appData) {
    const title = escapeHtml(record.name || 'Taper');
    const status = escapeHtml(getTaperPlanProgressLabelSafe(record.status));
    const dateRange = [record.startDate, record.endDate].filter(Boolean).join(' - ') || 'No dates set';
    const primaryMetric = `Current step: ${escapeHtml(String(record.currentStep))} · ${escapeHtml(String(record.stepStatus))}`;
    const progress = record.progressPct != null
        ? `<span>Progress: <strong>${escapeHtml(String(Math.round(Number(record.progressPct))))}%</strong></span>`
        : '';
    const secondary = `${escapeHtml(record.metric)} · ${record.scheduledSteps.length} scheduled step${record.scheduledSteps.length === 1 ? '' : 's'}`;
    const openAction = `openUnifiedTaperRecord('${escapeHtml(record.id)}')`;
    const editAction = `editUnifiedTaperRecord('${escapeHtml(record.id)}')`;
    const duplicateAction = `duplicateUnifiedTaperRecord('${escapeHtml(record.id)}')`;
    const pauseAction = `pauseUnifiedTaperRecord('${escapeHtml(record.id)}')`;
    const completeAction = `completeUnifiedTaperRecord('${escapeHtml(record.id)}')`;
    const archiveAction = `archiveUnifiedTaperRecord('${escapeHtml(record.id)}')`;
    return `
        <article class="goal-card unified-goal-plan-card" data-record-type="taper" data-record-id="${escapeAttr(record.id)}">
            <header class="goal-card-head">
                <div>
                    <div class="goal-chip-row"><span class="goal-chip">Taper</span></div>
                    <h3 class="goal-card-title">${title}</h3>
                    <p class="goal-card-period">${escapeHtml(record.substanceLabel)} · ${escapeHtml(dateRange)}</p>
                </div>
                <span class="goal-status-pill goal-tone-neutral">${status}</span>
            </header>
            ${record.description ? `<p class="goal-card-desc">${escapeHtml(record.description)}</p>` : ''}
            <div class="goal-card-foot">
                <span>${secondary}</span>
                <span>${primaryMetric}</span>
                ${progress}
                <span>Priority: <strong>${escapeHtml(record.priority || 'normal')}</strong></span>
            </div>
            <div class="goal-card-actions">
                <button type="button" class="btn-small" onclick="${openAction}">Open</button>
                <button type="button" class="btn-small" onclick="${editAction}">Edit</button>
                <button type="button" class="btn-small" onclick="${duplicateAction}">Duplicate</button>
                ${record.status === 'paused' ? '' : `<button type="button" class="btn-small" onclick="${pauseAction}">Pause</button>`}
                ${record.status === 'completed' ? '' : `<button type="button" class="btn-small" onclick="${completeAction}">Complete</button>`}
                ${record.status === 'archived' ? '' : `<button type="button" class="btn-small" onclick="${archiveAction}">Archive</button>`}
            </div>
        </article>`;
}

function renderUnifiedGoalsPlansFilters(view, data = appData) {
    const statusStateKey = view === 'history' ? 'historyStatus' : 'activeStatus';
    const statusValue = goalsPlansUiState[statusStateKey] || 'all';
    const statusOptions = ['all', 'active', 'paused', 'draft', 'completed', 'archived']
        .map(s => `<option value="${s}"${statusValue === s ? ' selected' : ''}>${escapeHtml(s === 'all' ? 'All statuses' : s.replace(/_/g, ' '))}</option>`)
        .join('');

    if (view === 'history') {
        const filter = goalsPlansUiState.historyFilter || 'all';
        return `
            <section class="goal-filters">
                <label class="goal-filter"><span>History</span><select onchange="setGoalsPlansHistoryFilter(this.value)">
                    ${['all', 'completed-tapers', 'archived'].map(v => `<option value="${v}"${filter === v ? ' selected' : ''}>${escapeHtml(v === 'all' ? 'All' : v.replace(/-/g, ' '))}</option>`).join('')}
                </select></label>
                <label class="goal-filter"><span>Status</span><select onchange="setGoalsPlansFilter('historyStatus', this.value, 'history')">${statusOptions}</select></label>
            </section>`;
    }

    return `
        <section class="goal-filters">
            <label class="goal-filter"><span>Status</span><select onchange="setGoalsPlansFilter('activeStatus', this.value, 'active')">${statusOptions}</select></label>
        </section>`;
}

function renderTaperTemplatesView(data = appData) {
    const root = tapersRootEl();
    if (!root) return;
    const substanceId = getTapersPageSubstanceId(data);
    const templates = getCompatibleTaperTemplates(substanceId, data);
    const cards = templates.length
        ? templates.map(t => `
        <article class="goal-card unified-goal-plan-card" data-template-id="${escapeAttr(t.id)}">
            <header class="goal-card-head">
                <div>
                    <div class="goal-chip-row"><span class="goal-chip">Template</span></div>
                    <h3 class="goal-card-title">${escapeHtml(t.name)}</h3>
                </div>
            </header>
            <p class="goal-card-desc">${escapeHtml(t.description)}</p>
            <div class="goal-card-actions">
                <button type="button" class="btn-primary btn-small" onclick="applyTaperTemplate('${escapeHtml(t.id)}')">Use template</button>
            </div>
        </article>`).join('')
        : `<div class="goal-empty"><p>${escapeHtml(`No templates compatible with ${goalSubstanceLabel(substanceId, data)}.`)}</p></div>`;
    root.innerHTML = `
        <div class="goal-view unified-goals-plans-view">
            <header class="goal-view-head">
                <div>
                    <h2 class="goal-view-title">Templates</h2>
                    <p class="goal-view-sub">Start from a common taper pattern for ${escapeHtml(goalSubstanceLabel(substanceId, data))}</p>
                </div>
                <div class="goal-view-actions">
                    <button type="button" class="btn-primary" onclick="openUnifiedNewTaper()">New Taper</button>
                </div>
            </header>
            <section class="goal-list" id="taper-template-list">
                ${cards}
            </section>
        </div>`;
}

function applyTaperTemplate(templateId) {
    const substanceId = typeof getTaperSubstanceId === 'function' ? getTaperSubstanceId() : null;
    const compatible = getCompatibleTaperTemplates(substanceId);
    const template = compatible.find(t => t.id === templateId)
        || TAPER_TEMPLATES.find(t => t.id === templateId);
    openUnifiedNewTaper();
    if (!template) return;
    if (!compatible.some(t => t.id === template.id)) return;
    const nameEl = typeof document !== 'undefined' ? document.getElementById('taper-plan-name') : null;
    if (nameEl) nameEl.value = template.name;
    const typeEl = typeof document !== 'undefined' ? document.getElementById('reduction-type') : null;
    if (typeEl && template.reductionType) {
        if (typeof populateTaperReductionTypeSelect === 'function') {
            populateTaperReductionTypeSelect(substanceId, template.reductionType);
        }
        typeEl.value = template.reductionType;
        if (typeof toggleTaperPlanTypeFields === 'function') {
            toggleTaperPlanTypeFields({ selectedType: template.reductionType, skipPrefill: false });
        }
    }
}

function renderGoalsPlansRecordsView(view = null) {
    const root = tapersRootEl();
    if (!root) return;
    const activeView = view || ensureCombinedNavPrefs().goalsPlansView || 'active';
    if (activeView === 'templates') {
        renderTaperTemplatesView();
        return;
    }
    const data = appData;
    if (typeof ensureTaperPlansV2 === 'function') ensureTaperPlansV2(data);
    const substanceId = getTapersPageSubstanceId(data);
    syncGoalsPlansSubstanceFilters(substanceId);

    const filteredPlans = getFilteredTapers({
        substance: substanceId,
        includeArchived: true,
        data
    });
    const allRecords = filteredPlans
        .map(plan => normalizeUnifiedGoalPlanRecord(plan, { kind: 'taper', data }))
        .filter(Boolean);
    const records = filterUnifiedGoalsPlansRecords(allRecords, activeView, data);
    const activeTapers = allRecords.filter(r => unifiedGoalPlanIsActive(r)).length;
    const emptyCopy = getTapersEmptyMessage(activeView, substanceId, data);
    const substanceLabel = goalSubstanceLabel(substanceId, data);
    root.innerHTML = `
        <div class="goal-view unified-goals-plans-view">
            <header class="goal-view-head">
                <div>
                    <h2 class="goal-view-title">${activeView === 'history' ? 'History' : 'Active'}</h2>
                    <p class="goal-view-sub">${activeTapers} active ${escapeHtml(substanceLabel)} taper${activeTapers === 1 ? '' : 's'}</p>
                </div>
                <div class="goal-view-actions">
                    <button type="button" class="btn-primary" onclick="openUnifiedNewTaper()">New Taper</button>
                </div>
            </header>
            ${renderUnifiedGoalsPlansFilters(activeView, data)}
            <section class="goal-list" id="taper-list">
                ${records.length ? records.map(record => renderUnifiedGoalPlanCard(record, data)).join('') : `<div class="goal-empty"><p>${escapeHtml(emptyCopy)}</p></div>`}
            </section>
        </div>`;
}

function setGoalsPlansFilter(key, value, view = 'active') {
    if (Object.prototype.hasOwnProperty.call(goalsPlansUiState, key)) goalsPlansUiState[key] = value;
    renderGoalsPlansRecordsView(view);
}

function setGoalsPlansHistoryFilter(value) {
    goalsPlansUiState.historyFilter = value || 'all';
    renderGoalsPlansRecordsView('history');
}

function attachUnifiedTaperSurface(..._ids) {
    showTaperWorkspace();
}

function openUnifiedNewTaper() {
    const prefs = ensureCombinedNavPrefs();
    const current = prefs.goalsPlansView || 'overview';
    const stay = current === 'overview' || current === 'active' || current === 'templates' ? current : 'active';
    // Keep the editor mount alive while syncing the subnav — hideTaperWorkspace would blank the page.
    setGoalsPlansView(stay, { persist: true, skipRoute: false, keepTaperEditor: true });
    showTaperWorkspace();
    const opened = typeof showNewTaperPlan === 'function' ? showNewTaperPlan() : false;
    if (opened === false) {
        hideTaperWorkspace();
        setGoalsPlansView(stay, { persist: true, skipRoute: true });
        return;
    }
    ensureTaperSetupVisible();
}

function openUnifiedTaperRecord(planId) {
    setGoalsPlansView('active', { persist: true, keepTaperEditor: true });
    showTaperWorkspace();
    if (typeof openTaperPlanFromManage === 'function') openTaperPlanFromManage(planId);
}

function editUnifiedTaperRecord(planId) {
    setGoalsPlansView('active', { persist: true, keepTaperEditor: true });
    showTaperWorkspace();
    const opened = typeof editTaperPlanById === 'function' ? editTaperPlanById(planId) : false;
    if (opened === false) {
        hideTaperWorkspace();
        setGoalsPlansView('active', { persist: true, skipRoute: true });
        return;
    }
    ensureTaperSetupVisible();
}

function duplicateUnifiedTaperRecord(planId) {
    if (typeof duplicateTaperPlanById === 'function') duplicateTaperPlanById(planId);
    hideTaperWorkspace();
    setGoalsPlansView('active', { persist: true });
    renderGoalsPlansRecordsView('active');
}

function pauseUnifiedTaperRecord(planId) {
    if (typeof pauseTaperPlanById === 'function') pauseTaperPlanById(planId);
    renderGoalsPlansRecordsView('active');
}

function completeUnifiedTaperRecord(planId) {
    if (typeof completeTaperPlanById === 'function') completeTaperPlanById(planId);
    setGoalsPlansView('history', { persist: true });
    renderGoalsPlansRecordsView('history');
}

function archiveUnifiedTaperRecord(planId) {
    if (typeof archiveTaperPlanById === 'function') archiveTaperPlanById(planId);
    setGoalsPlansView('history', { persist: true });
    renderGoalsPlansRecordsView('history');
}

function buildGoalsPlansOverview(data = appData, options = {}) {
    if (typeof ensureTaperPlansV2 === 'function') ensureTaperPlansV2(data);
    ensureGoals(data);
    const substanceId = options.substance !== undefined
        ? options.substance
        : getTapersPageSubstanceId(data);
    syncGoalsPlansSubstanceFilters(substanceId);

    const plans = getFilteredTapers({
        substance: substanceId,
        status: ['active', 'paused', 'draft', 'upcoming'],
        includeArchived: false,
        data
    });
    const archivedPlans = getFilteredTapers({
        substance: substanceId,
        status: ['archived', 'completed', 'missed', 'cancelled', 'met'],
        includeArchived: true,
        data
    });
    let plansOnTrack = 0;
    let plansAbove = 0;
    let currentPlanWeek = '—';

    // Prefer primary / selected plan for "current taper step", still scoped to substance.
    const primaryPlan = (typeof getPrimaryTaperPlan === 'function' && substanceId && !goalIsAllSubstances(substanceId))
        ? getPrimaryTaperPlan(substanceId, data)
        : null;
    const stepSourcePlan = (primaryPlan && taperPlanMatchesSubstance(primaryPlan, substanceId, data))
        ? primaryPlan
        : (plans.find(p => p.isPrimary && p.status === 'active') || plans.find(p => p.status === 'active') || plans[0] || null);

    if (stepSourcePlan) {
        try {
            if (typeof getTaperPlanProgressSummary === 'function') {
                const summary = getTaperPlanProgressSummary(stepSourcePlan, data);
                if (summary?.currentWeekLabel) currentPlanWeek = summary.currentWeekLabel;
            }
            if (currentPlanWeek === '—' && Array.isArray(stepSourcePlan.weeklyTargets) && stepSourcePlan.weeklyTargets.length) {
                const today = typeof getLocalDateString === 'function' ? getLocalDateString() : '';
                const week = stepSourcePlan.weeklyTargets.find(w => (w.weekStart || '') <= today && (w.weekEnd || '9999') >= today)
                    || stepSourcePlan.weeklyTargets[0];
                if (week) currentPlanWeek = week.label || week.weekStart || String(week.weekNum || week.week || '—');
            }
            if (currentPlanWeek === '—') {
                const step = typeof getUnifiedTaperCurrentStep === 'function'
                    ? getUnifiedTaperCurrentStep(stepSourcePlan, data)
                    : null;
                if (step?.weekNum != null || step?.week != null) {
                    currentPlanWeek = String(step.weekNum ?? step.week);
                } else if (step?.label) {
                    currentPlanWeek = step.label;
                }
            }
        } catch (_) { /* soft */ }
    }

    plans.forEach(plan => {
        try {
            if (typeof getTaperPlanProgressSummary === 'function') {
                const summary = getTaperPlanProgressSummary(plan, data);
                if (summary?.aboveTarget || summary?.status === 'above') plansAbove += 1;
                else plansOnTrack += 1;
            } else if (Array.isArray(plan.weeklyTargets) && plan.weeklyTargets.length) {
                const today = typeof getLocalDateString === 'function' ? getLocalDateString() : '';
                const week = plan.weeklyTargets.find(w => (w.weekStart || '') <= today && (w.weekEnd || '9999') >= today);
                if (week) {
                    const actual = Number(week.actualAmount ?? week.actual ?? 0);
                    const target = Number(week.targetAmount ?? week.target ?? 0);
                    if (target > 0 && actual > target) plansAbove += 1;
                    else plansOnTrack += 1;
                } else {
                    plansOnTrack += 1;
                }
            } else {
                plansOnTrack += 1;
            }
        } catch (_) {
            plansOnTrack += 1;
        }
    });

    const unifiedRecords = plans
        .map(plan => normalizeUnifiedGoalPlanRecord(plan, { kind: 'taper', data }))
        .filter(Boolean)
        .filter(unifiedGoalPlanIsActive)
        .sort((a, b) => String(a.endDate || '9999-12-31').localeCompare(String(b.endDate || '9999-12-31')))
        .slice(0, 8);

    const closestDeadline = unifiedRecords
        .filter(r => r.endDate)
        .slice()
        .sort((a, b) => String(a.endDate).localeCompare(String(b.endDate)))[0];

    return {
        substanceId,
        substanceLabel: goalSubstanceLabel(substanceId, data),
        activeTotal: plans.length,
        activeGoalCount: 0,
        activePlanCount: plans.length,
        activeTaperCount: plans.length,
        goalsOnTrack: 0,
        goalsNearLimit: 0,
        plansOnTrack,
        plansAboveTarget: plansAbove,
        closestGoalDeadline: closestDeadline ? { id: closestDeadline.id, name: closestDeadline.name, endDate: closestDeadline.endDate, substanceId: closestDeadline.substanceId } : null,
        currentPlanWeek,
        activeRecords: unifiedRecords,
        recentlyCompletedGoals: [],
        recentlyCompletedPlans: archivedPlans.slice(0, 5),
        evaluations: [],
        plans
    };
}

function renderGoalsPlansOverviewHtml(overview) {
    const substanceLabel = overview.substanceLabel || 'selected';
    const deadline = overview.closestGoalDeadline
        ? `${escapeHtml(overview.closestGoalDeadline.name || 'Taper')} · ${escapeHtml(overview.closestGoalDeadline.endDate)}`
        : 'None set';
    const emptyActive = getTapersEmptyMessage('active', overview.substanceId, appData);
    const activeList = overview.activeRecords?.length
        ? `<div class="goal-list combined-overview-list">${overview.activeRecords.map(record => renderUnifiedGoalPlanCard(record)).join('')}</div>`
        : `<p class="settings-hint">${escapeHtml(emptyActive)}</p>`;

    return `
        <div class="combined-overview">
            <div class="combined-overview-grid">
                <article class="combined-stat-card"><span class="combined-stat-label">Active tapers</span><strong>${overview.activeTaperCount || 0}</strong></article>
                <article class="combined-stat-card"><span class="combined-stat-label">On track</span><strong>${overview.plansOnTrack || 0}</strong></article>
                <article class="combined-stat-card"><span class="combined-stat-label">Above target</span><strong>${overview.plansAboveTarget || 0}</strong></article>
                <article class="combined-stat-card"><span class="combined-stat-label">Closest end date</span><strong class="combined-stat-text">${deadline}</strong></article>
                <article class="combined-stat-card"><span class="combined-stat-label">Current taper step</span><strong class="combined-stat-text">${escapeHtml(String(overview.currentPlanWeek))}</strong></article>
            </div>
            <section class="combined-overview-block">
                <h3>Active ${escapeHtml(substanceLabel)} tapers</h3>
                ${activeList}
            </section>
            <div class="combined-overview-actions">
                <button type="button" class="secondary-btn" onclick="openUnifiedNewTaper();">New Taper</button>
                <button type="button" class="secondary-btn" onclick="setGoalsPlansView('templates')">Browse templates</button>
            </div>
        </div>`;
}

function renderGoalsPlansCombinedView() {
    const loading = typeof document !== 'undefined' ? document.getElementById('gp-loading') : null;
    const error = typeof document !== 'undefined' ? document.getElementById('gp-error') : null;
    loading?.classList.add('hidden');
    error?.classList.add('hidden');
    try {
        const prefs = ensureCombinedNavPrefs();
        setGoalsPlansView(prefs.goalsPlansView, { persist: false, skipRoute: true, force: true });
    } catch (err) {
        console.error('[tapers] render failed', err);
        loading?.classList.add('hidden');
        error?.classList.remove('hidden');
        const msg = document.getElementById('gp-error-message');
        if (msg) msg.textContent = err?.message || 'Could not load Tapers.';
    }
}

function setGoalsPlansView(view, options = {}) {
    const prefs = ensureCombinedNavPrefs();
    const next = normalizeCombinedView(view, GOALS_PLANS_VIEWS, prefs.goalsPlansView || 'overview');
    prefs.goalsPlansView = next;
    if (options.persist !== false) persistCombinedNavPrefs();
    syncGoalsPlansSubstanceFilters(getTapersPageSubstanceId());

    syncCombinedSubnav('gp-subnav', 'gp-subnav-select', 'data-gp-view', next);
    setCombinedSubviewVisibility('#goals-plans-tab', 'data-gp-view', next);
    if (!options.keepTaperEditor) hideTaperWorkspace();

    if (next === 'overview') {
        const root = document.getElementById('gp-overview-root');
        if (root) root.innerHTML = renderGoalsPlansOverviewHtml(buildGoalsPlansOverview());
    } else if (next === 'active' || next === 'history' || next === 'templates') {
        if (typeof renderGoalsPlansRecordsView === 'function') renderGoalsPlansRecordsView(next);
    }

    if (!options.skipRoute) syncLocationToCombinedRoute('goals-plans-tab', next);
    if (typeof applyCollapsedSections === 'function') applyCollapsedSections();
}

function buildInsightsCalendarOverview(data = appData) {
    const substanceId = (typeof document !== 'undefined' && document.getElementById('stats-substance')?.value)
        || (typeof selectedSubstanceId !== 'undefined' ? selectedSubstanceId : 'all');
    const rangeLabel = (typeof document !== 'undefined' && document.getElementById('stats-date-range')?.selectedOptions?.[0]?.textContent)
        || 'Selected range';

    let useSummary = '—';
    let spendSummary = '—';
    let purchaseSummary = '—';
    let goalPerf = '—';
    let planPerf = '—';
    let warnings = [];

    try {
        if (typeof buildDashboardFinancialSummary === 'function') {
            const fin = buildDashboardFinancialSummary(data, substanceId === 'all' ? 'all' : substanceId);
            spendSummary = fin?.spentThisMonth != null ? `$${Number(fin.spentThisMonth).toFixed(2)} this month` : '—';
            purchaseSummary = fin?.purchaseCount != null ? `${fin.purchaseCount} purchases in range` : '—';
        }
    } catch (_) { /* overview soft-fail */ }

    try {
        const gp = buildGoalsPlansOverview(data, { substance: substanceId });
        planPerf = `${gp.plansOnTrack} tapers on track · ${gp.plansAboveTarget} above target`;
        useSummary = `${gp.activeTaperCount} active taper${gp.activeTaperCount === 1 ? '' : 's'}`;
        goalPerf = '—';
    } catch (_) { /* overview soft-fail */ }

    try {
        if (typeof buildFinancialDataQualityIssues === 'function') {
            warnings = (buildFinancialDataQualityIssues(data) || []).slice(0, 5);
        }
    } catch (_) { /* overview soft-fail */ }

    return {
        rangeLabel,
        substanceId,
        useSummary,
        spendSummary,
        purchaseSummary,
        goalPerf,
        planPerf,
        warnings,
        importantEvents: []
    };
}

function renderInsightsCalendarOverviewHtml(overview) {
    const warnings = overview.warnings?.length
        ? `<ul class="combined-mini-list">${overview.warnings.map(w => `<li>${escapeHtml(w.message || w.title || 'Data warning')}</li>`).join('')}</ul>`
        : '<p class="settings-hint">No data warnings right now.</p>';
    return `
        <div class="combined-overview">
            <p class="settings-hint">Date range: <strong>${escapeHtml(overview.rangeLabel)}</strong></p>
            <div class="combined-overview-grid">
                <article class="combined-stat-card"><span class="combined-stat-label">Use summary</span><strong class="combined-stat-text">${escapeHtml(String(overview.useSummary))}</strong></article>
                <article class="combined-stat-card"><span class="combined-stat-label">Spending summary</span><strong class="combined-stat-text">${escapeHtml(String(overview.spendSummary))}</strong></article>
                <article class="combined-stat-card"><span class="combined-stat-label">Purchase summary</span><strong class="combined-stat-text">${escapeHtml(String(overview.purchaseSummary))}</strong></article>
                <article class="combined-stat-card"><span class="combined-stat-label">Taper performance</span><strong class="combined-stat-text">${escapeHtml(String(overview.planPerf))}</strong></article>
            </div>
            <div class="combined-overview-columns">
                <section class="combined-overview-block">
                    <h3>Calendar preview</h3>
                    <p class="settings-hint">Open the full calendar for month, week, day, and agenda views.</p>
                    <button type="button" class="secondary-btn btn-sm" onclick="setInsightsCalendarView('calendar')">Open calendar</button>
                </section>
                <section class="combined-overview-block">
                    <h3>Data warnings</h3>
                    ${warnings}
                </section>
            </div>
            <div class="combined-overview-actions">
                <button type="button" class="secondary-btn" onclick="setInsightsCalendarView('use')">Use</button>
                <button type="button" class="secondary-btn" onclick="setInsightsCalendarView('money')">Money</button>
                <button type="button" class="secondary-btn" onclick="setInsightsCalendarView('more')">More</button>
            </div>
        </div>`;
}

function applyInsightsCalendarSectionFilter(view) {
    const stats = typeof document !== 'undefined' ? document.getElementById('stats-tab') : null;
    if (!stats) return;
    // Overview now shares the Insights shell (filter bar + summary + charts).
    // Calendar keeps its dedicated full-page view.
    if (view === 'calendar') {
        stats.hidden = true;
        return;
    }
    stats.hidden = false;
    stats.classList.add('active');
    stats.querySelectorAll('.collapsible-section[data-ic-panels]').forEach(section => {
        const panels = String(section.getAttribute('data-ic-panels') || '').split(/\s+/).filter(Boolean);
        const match = panels.includes(view);
        section.classList.toggle('ic-section-hidden', !match);
        section.hidden = !match;
    });
}

function renderPlanAnalyticsPanel(data = appData) {
    const panel = typeof document !== 'undefined' ? document.getElementById('plan-analytics-panel') : null;
    if (!panel) return;
    try {
        if (typeof ensureTaperPlansV2 === 'function') ensureTaperPlansV2(data);
        const plans = (data.taperPlansV2 || []).filter(Boolean);
        if (!plans.length) {
            panel.innerHTML = '<p class="settings-hint">No tapers yet. Create a taper from the Tapers page.</p>';
            return;
        }
        const rows = plans.slice(0, 20).map(plan => {
            const status = plan.archived ? 'Archived' : 'Active';
            return `<tr>
                <td>${escapeHtml(plan.name || 'Taper')}</td>
                <td>${escapeHtml(status)}</td>
                <td><button type="button" class="btn-small" onclick="setInsightsCalendarView('calendar')">Calendar</button>
                    <button type="button" class="btn-small" onclick="switchTab('goals-plans-tab'); setGoalsPlansView('active'); openTaperPlanFromManage('${escapeHtml(plan.id)}');">Open</button></td>
            </tr>`;
        }).join('');
        panel.innerHTML = `
            <div class="table-scroll">
                <table class="sheet-table">
                    <thead><tr><th>Taper</th><th>Status</th><th></th></tr></thead>
                    <tbody>${rows}</tbody>
                </table>
            </div>`;
    } catch (err) {
        panel.innerHTML = `<p class="rd-error">Could not render plan analytics: ${escapeHtml(err?.message || String(err))}</p>`;
    }
}

function renderInsightsCalendarCombinedView() {
    const loading = document.getElementById('ic-loading');
    const error = document.getElementById('ic-error');
    loading?.classList.add('hidden');
    error?.classList.add('hidden');
    try {
        const prefs = ensureCombinedNavPrefs();
        setInsightsCalendarView(prefs.insightsCalendarView, { persist: false, skipRoute: true, force: true });
    } catch (err) {
        console.error('[insights-calendar] render failed', err);
        error?.classList.remove('hidden');
        const msg = document.getElementById('ic-error-message');
        if (msg) msg.textContent = err?.message || 'Could not load Insights & Calendar.';
    }
}

function setInsightsCalendarView(view, options = {}) {
    const prefs = ensureCombinedNavPrefs();
    const next = normalizeCombinedView(view, INSIGHTS_CALENDAR_VIEWS, prefs.insightsCalendarView || 'overview');
    prefs.insightsCalendarView = next;
    if (options.persist !== false) persistCombinedNavPrefs();

    syncCombinedSubnav('ic-subnav', 'ic-subnav-select', 'data-ic-view', next);
    setCombinedSubviewVisibility('#insights-calendar-tab', 'data-ic-view', next);
    applyInsightsCalendarSectionFilter(next);

    if (next === 'overview') {
        const root = document.getElementById('ic-overview-root');
        if (root) root.innerHTML = renderInsightsCalendarOverviewHtml(buildInsightsCalendarOverview());
        if (typeof applyMainSubstanceToViewSelectors === 'function') applyMainSubstanceToViewSelectors();
        if (typeof updateStats === 'function') updateStats();
    } else if (next === 'calendar') {
        if (typeof renderCalendarView === 'function') renderCalendarView();
    } else {
        if (typeof applyMainSubstanceToViewSelectors === 'function') applyMainSubstanceToViewSelectors();
        if (typeof updateStats === 'function') updateStats();
        if (next === 'money') {
            if (typeof renderFinancialAnalyticsView === 'function') renderFinancialAnalyticsView();
            if (typeof renderPurchaseAnalyticsView === 'function') renderPurchaseAnalyticsView();
        }
        if (next === 'use') {
            if (typeof renderChartDashboardView === 'function') renderChartDashboardView();
            if (typeof renderRunningTotalsView === 'function') renderRunningTotalsView();
        }
        if (next === 'more') {
            if (typeof renderPlanAnalyticsPanel === 'function') renderPlanAnalyticsPanel();
            if (typeof renderInsightsContactAnalytics === 'function') renderInsightsContactAnalytics();
            if (typeof renderChartDashboardView === 'function') renderChartDashboardView();
            const customRoot = document.getElementById('custom-metrics-root');
            if (customRoot && !customRoot.dataset.ready) {
                customRoot.innerHTML = '<p class="settings-hint">Custom metric formulas will appear here when the builder is enabled. Use Money and Use for built-in metrics today.</p>';
                customRoot.dataset.ready = '1';
            }
        }
    }

    if (!options.skipRoute) syncLocationToCombinedRoute('insights-calendar-tab', next);
    if (typeof applyCollapsedSections === 'function') applyCollapsedSections();
}

function handleCombinedNavHashChange() {
    if (combinedNavRouteSyncing) return;
    const parsed = applyRouteRedirectIfNeeded() || parseAppRouteFromLocation();
    if (!parsed?.tab) return;
    combinedNavRouteSyncing = true;
    try {
        if (parsed.tab === 'goals-plans-tab' && parsed.view) {
            ensureCombinedNavPrefs().goalsPlansView = normalizeCombinedView(parsed.view, GOALS_PLANS_VIEWS, 'overview');
        }
        if (parsed.tab === 'insights-calendar-tab' && parsed.view) {
            ensureCombinedNavPrefs().insightsCalendarView = normalizeCombinedView(parsed.view, INSIGHTS_CALENDAR_VIEWS, 'overview');
        }
        switchTab(parsed.tab);
    } finally {
        combinedNavRouteSyncing = false;
    }
}

function initCombinedNavigation() {
    ensureCombinedNavPrefs();
    migrateCombinedNavActiveTab();
    if (typeof window !== 'undefined') {
        window.addEventListener('hashchange', handleCombinedNavHashChange);
    }
    applyRouteRedirectIfNeeded();
}


// ——— Purchase Analytics ———
// Purchase habits, pricing, suppliers, stores, and inventory turnover.
// Local-only: mutations persist through saveData(appData).
// Spliced into app.js ahead of `const defaultData`.
//
// Rules:
//   • Purchased + Purchased as Gift count toward spending.
//   • Gift Received never counts as spending.
//   • Purchased as Gift is not usable inventory.
//   • Never double-count the same purchase id.
//   • Weighted cost/unit = total spend ÷ total qualifying quantity.

const PURCHASE_ANALYTICS_WEEKDAYS = Object.freeze([
    'Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'
]);

const PURCHASE_ANALYTICS_ALERT_TYPES = Object.freeze([
    'aboveAveragePrice',
    'duplicatePurchase',
    'shortInterval',
    'missingSupplier',
    'missingStore',
    'missingCost',
    'missingQuantity',
    'inventoryExpiring',
    'overstocked'
]);

const PURCHASE_ANALYTICS_ALERT_LABELS = Object.freeze({
    aboveAveragePrice: 'Paid above average',
    duplicatePurchase: 'Possible duplicate purchase',
    shortInterval: 'Very short purchase interval',
    missingSupplier: 'Missing supplier',
    missingStore: 'Missing store',
    missingCost: 'Missing cost',
    missingQuantity: 'Missing quantity',
    inventoryExpiring: 'Inventory may be expiring',
    overstocked: 'Overstocked inventory'
});

let purchaseAnalyticsCache = null;
let purchaseAnalyticsCacheKey = '';

function paToNumber(value, fallback = 0) {
    return toFiniteNumber(value, fallback);
}

function paRound(value, decimals = 2) {
    return roundToOrNull(value, decimals);
}

function paTrim(value) {
    return trimToString(value);
}

function paKey(value) {
    return lowerKey(value);
}

function paToday() {
    return todayLocalDate();
}

function paAllSubstancesId() {
    return allSubstancesId();
}

function paMoney(value, decimals = 2) {
    return formatMoneyOrDash(value, decimals);
}

function paNumberOrDash(value, decimals = 2) {
    return formatNumberOrDash(value, decimals);
}

function paDateLabel(dateStr) {
    return formatLongDateLabel(dateStr);
}

function paDaysBetween(a, b) {
    return daysBetweenDates(a, b);
}

function paMedian(values) {
    return medianOfNumbers((values || []).map(v => toFiniteNumber(v, NaN)).filter(Number.isFinite));
}

function paMean(values) {
    return meanOrNull(values);
}

function invalidatePurchaseAnalyticsCache() {
    purchaseAnalyticsCache = null;
    purchaseAnalyticsCacheKey = '';
}

function getDefaultPurchaseAnalyticsFilters() {
    return {
        substanceId: paAllSubstancesId(),
        productType: '',
        store: '',
        supplier: '',
        paymentMethod: '',
        acquisitionType: '',
        giftStatus: '',
        minCost: '',
        maxCost: '',
        minQuantity: '',
        maxQuantity: '',
        dateRangePreset: 'last-30',
        customStart: '',
        customEnd: ''
    };
}

function getDefaultPurchaseAnalyticsPrefs() {
    return {
        alertsEnabled: true,
        alertTypes: PURCHASE_ANALYTICS_ALERT_TYPES.reduce((acc, id) => { acc[id] = true; return acc; }, {}),
        chartGrain: 'monthly',
        filtersCollapsed: false,
        aboveAverageMultiplier: 1.35,
        shortIntervalDays: 2,
        overstockDaysSupply: 60,
        favoriteStores: [],
        storeDistances: {},
        filters: getDefaultPurchaseAnalyticsFilters()
    };
}

function ensurePurchaseAnalyticsPrefs(data = appData) {
    if (!data || typeof data !== 'object') return getDefaultPurchaseAnalyticsPrefs();
    if (!data.settings || typeof data.settings !== 'object') data.settings = {};
    const defaults = getDefaultPurchaseAnalyticsPrefs();
    if (!data.settings.purchaseAnalytics || typeof data.settings.purchaseAnalytics !== 'object') {
        data.settings.purchaseAnalytics = {
            ...defaults,
            alertTypes: { ...defaults.alertTypes },
            filters: { ...defaults.filters },
            favoriteStores: [],
            storeDistances: {}
        };
    }
    const prefs = data.settings.purchaseAnalytics;
    Object.keys(defaults).forEach(key => {
        if (prefs[key] === undefined) {
            prefs[key] = (key === 'alertTypes' || key === 'filters' || key === 'storeDistances')
                ? { ...defaults[key] }
                : Array.isArray(defaults[key]) ? [...defaults[key]] : defaults[key];
        }
    });
    if (!prefs.alertTypes || typeof prefs.alertTypes !== 'object') prefs.alertTypes = { ...defaults.alertTypes };
    PURCHASE_ANALYTICS_ALERT_TYPES.forEach(id => {
        if (prefs.alertTypes[id] === undefined) prefs.alertTypes[id] = true;
    });
    if (!prefs.filters || typeof prefs.filters !== 'object') prefs.filters = { ...defaults.filters };
    Object.keys(defaults.filters).forEach(key => {
        if (prefs.filters[key] === undefined) prefs.filters[key] = defaults.filters[key];
    });
    if (!Array.isArray(prefs.favoriteStores)) prefs.favoriteStores = [];
    if (!prefs.storeDistances || typeof prefs.storeDistances !== 'object') prefs.storeDistances = {};
    prefs.aboveAverageMultiplier = Math.max(1.05, paToNumber(prefs.aboveAverageMultiplier, defaults.aboveAverageMultiplier));
    prefs.shortIntervalDays = Math.max(1, Math.round(paToNumber(prefs.shortIntervalDays, defaults.shortIntervalDays)));
    prefs.overstockDaysSupply = Math.max(7, Math.round(paToNumber(prefs.overstockDaysSupply, defaults.overstockDaysSupply)));
    return prefs;
}

function getPurchaseAnalyticsPrefs(data = appData) {
    return ensurePurchaseAnalyticsPrefs(data);
}

function persistPurchaseAnalyticsPrefs(patch = {}, data = appData) {
    const prefs = ensurePurchaseAnalyticsPrefs(data);
    const { alertTypes, filters, favoriteStores, storeDistances, ...rest } = patch || {};
    Object.assign(prefs, rest);
    if (alertTypes) prefs.alertTypes = { ...prefs.alertTypes, ...alertTypes };
    if (filters) prefs.filters = { ...prefs.filters, ...filters };
    if (favoriteStores) prefs.favoriteStores = [...favoriteStores];
    if (storeDistances) prefs.storeDistances = { ...prefs.storeDistances, ...storeDistances };
    ensurePurchaseAnalyticsPrefs(data);
    invalidatePurchaseAnalyticsCache();
    if (typeof saveData === 'function') saveData(data);
    return prefs;
}

function migratePurchaseAnalytics(data = appData) {
    ensurePurchaseAnalyticsPrefs(data);
    return data;
}

function purchaseAnalyticsAcquisitionType(purchase) {
    if (typeof getPurchaseAcquisitionType === 'function') return getPurchaseAcquisitionType(purchase);
    return paTrim(purchase?.acquisitionType || purchase?.type || 'purchased') || 'purchased';
}

function purchaseAnalyticsCountsTowardSpend(purchase) {
    if (typeof purchaseCountsTowardSpend === 'function') return purchaseCountsTowardSpend(purchase);
    if (typeof financialCountsTowardSpend === 'function') return financialCountsTowardSpend(purchase);
    const t = purchaseAnalyticsAcquisitionType(purchase);
    return t === 'purchased' || t === 'purchased_as_gift';
}

function purchaseAnalyticsSpendAmount(purchase) {
    if (!purchaseAnalyticsCountsTowardSpend(purchase)) return 0;
    if (typeof getPurchaseSpendAmount === 'function') return paToNumber(getPurchaseSpendAmount(purchase), 0);
    return paToNumber(purchase?.totalCost ?? purchase?.cost ?? purchase?.price, 0);
}

function purchaseAnalyticsIsPurchasedAsGift(purchase) {
    if (typeof purchaseIsPurchasedAsGift === 'function') return purchaseIsPurchasedAsGift(purchase);
    return purchaseAnalyticsAcquisitionType(purchase) === 'purchased_as_gift';
}

function purchaseAnalyticsIsGiftReceived(purchase) {
    return purchaseAnalyticsAcquisitionType(purchase) === 'gift_received';
}

function purchaseAnalyticsIsUsableInventory(purchase) {
    if (purchaseAnalyticsIsPurchasedAsGift(purchase)) return false;
    if (typeof purchaseIsPersonalUseInventory === 'function') return purchaseIsPersonalUseInventory(purchase);
    const t = purchaseAnalyticsAcquisitionType(purchase);
    return t === 'purchased' || t === 'gift_received';
}

function purchaseAnalyticsSupplier(purchase) {
    if (typeof financialPurchaseSupplier === 'function') {
        const s = financialPurchaseSupplier(purchase);
        if (s) return s;
    }
    return paTrim(
        purchase?.supplier
        || purchase?.store
        || purchase?.giftSource
        || purchase?.giverName
        || purchase?.dealer
        || purchase?.contact
        || ''
    );
}

function purchaseAnalyticsStore(purchase) {
    if (typeof financialPurchaseStore === 'function') {
        const s = financialPurchaseStore(purchase);
        if (s) return paTrim(s);
    }
    // Prefer business Source; ignore person sources for store analytics
    if (typeof getPurchaseSourceKind === 'function' && typeof getPurchaseSourceName === 'function') {
        const kind = getPurchaseSourceKind(purchase);
        if (kind === 'business' || kind === 'online' || kind === 'event' || kind === 'other') {
            return paTrim(getPurchaseSourceName(purchase) || purchase?.store || '');
        }
        return '';
    }
    return paTrim(purchase?.store || '');
}

function purchaseAnalyticsProductType(purchase) {
    if (typeof normalizeWeedProductType === 'function') {
        const pt = normalizeWeedProductType(purchase?.weedProductType || purchase?.productType || purchase?.flavor);
        if (pt) return pt;
    }
    return paTrim(purchase?.weedProductType || purchase?.productType || purchase?.flavor || '');
}

function purchaseAnalyticsQuantity(purchase) {
    if (typeof getPurchaseQuantityBought === 'function') return paToNumber(getPurchaseQuantityBought(purchase), 0);
    return paToNumber(purchase?.quantityBought ?? purchase?.quantity ?? purchase?.amount, 0);
}

function purchaseAnalyticsRemaining(purchase) {
    if (typeof getPurchaseRemainingAmount === 'function') return paToNumber(getPurchaseRemainingAmount(purchase), 0);
    return paToNumber(purchase?.remainingAmount ?? purchase?.remaining, 0);
}

function purchaseAnalyticsUnit(purchase, data = appData) {
    return paTrim(purchase?.unit || '')
        || (typeof getSubstancePrimaryUnit === 'function'
            ? getSubstancePrimaryUnit(purchase?.substanceId, data)
            : '')
        || 'unit';
}

function purchaseAnalyticsCostPerUnit(purchase) {
    const qty = purchaseAnalyticsQuantity(purchase);
    const spend = purchaseAnalyticsSpendAmount(purchase);
    if (!(qty > 0) || !(spend >= 0) || !purchaseAnalyticsCountsTowardSpend(purchase)) return null;
    return spend / qty;
}

function purchaseAnalyticsPriceMetricKey(purchase, data = appData) {
    const substance = typeof getSubstance === 'function' ? getSubstance(purchase?.substanceId, data) : null;
    const mode = substance?.trackingMode || '';
    const productType = purchaseAnalyticsProductType(purchase);
    const unit = purchaseAnalyticsUnit(purchase, data).toLowerCase();

    if (mode === 'weed' || purchase?.substanceId === 'weed-thc') {
        if (productType === 'edibles' || productType === 'edible') {
            const thc = paToNumber(purchase?.totalThcMg ?? purchase?.thcMg, 0);
            if (thc > 0) return 'cost_per_thc_mg';
            return 'cost_per_edible';
        }
        if (productType === 'cart') return 'cost_per_cart';
        if (productType === 'pre-roll' || productType === 'preroll') return 'cost_per_gram';
        return 'cost_per_gram';
    }
    if (mode === 'nicotine' || productType === 'vape') return 'cost_per_vape';
    if (mode === 'powder' || unit === 'g' || unit === 'gram' || unit === 'grams') return 'cost_per_gram';
    if (mode === 'xanax' || unit === 'pill' || unit === 'pills') return 'cost_per_pill';
    if (mode === 'lsd' || unit === 'tab' || unit === 'tabs') return 'cost_per_tab';
    return `cost_per_${unit || 'unit'}`;
}

function purchaseAnalyticsPriceQuantity(purchase, metricKey) {
    if (metricKey === 'cost_per_thc_mg') return paToNumber(purchase?.totalThcMg ?? purchase?.thcMg, 0);
    if (metricKey === 'cost_per_edible') {
        return paToNumber(purchase?.edibleCount ?? purchase?.quantityBought ?? purchase?.quantity, 0);
    }
    if (metricKey === 'cost_per_cart' || metricKey === 'cost_per_vape') {
        return Math.max(1, paToNumber(purchase?.quantityBought ?? purchase?.quantity ?? 1, 1));
    }
    return purchaseAnalyticsQuantity(purchase);
}

function normalizePurchaseAnalyticsFilters(filters = null, data = appData) {
    const prefs = ensurePurchaseAnalyticsPrefs(data);
    const base = { ...prefs.filters, ...(filters || {}) };
    if (!base.substanceId) base.substanceId = paAllSubstancesId();
    if (!base.dateRangePreset) base.dateRangePreset = 'last-30';
    return base;
}

function resolvePurchaseAnalyticsBounds(filters = null, data = appData) {
    const f = normalizePurchaseAnalyticsFilters(filters, data);
    if (typeof resolveFinancialBounds === 'function') {
        return resolveFinancialBounds({
            dateRangePreset: f.dateRangePreset,
            customStart: f.customStart,
            customEnd: f.customEnd
        }, data);
    }
    const today = paToday();
    return {
        startDate: f.customStart || today,
        endDate: f.customEnd || today,
        preset: f.dateRangePreset,
        label: f.dateRangePreset,
        incomplete: false
    };
}

function purchaseAnalyticsMatchesFilters(purchase, filters, data = appData) {
    if (!purchase) return false;
    const f = normalizePurchaseAnalyticsFilters(filters, data);
    const substanceId = purchase.substanceId;
    if (f.substanceId && f.substanceId !== paAllSubstancesId()) {
        if (typeof financialMatchesSubstance === 'function') {
            if (!financialMatchesSubstance(substanceId, f.substanceId, data)) return false;
        } else if (String(substanceId) !== String(f.substanceId)) return false;
    }
    if (f.productType && paKey(purchaseAnalyticsProductType(purchase)) !== paKey(f.productType)) return false;
    if (f.store && paKey(purchaseAnalyticsStore(purchase)) !== paKey(f.store)) return false;
    if (f.supplier && paKey(purchaseAnalyticsSupplier(purchase)) !== paKey(f.supplier)) return false;
    if (f.paymentMethod && paKey(purchase.paymentMethod || '') !== paKey(f.paymentMethod)) return false;
    if (f.acquisitionType && purchaseAnalyticsAcquisitionType(purchase) !== f.acquisitionType) return false;
    if (f.giftStatus === 'purchased_as_gift' && !purchaseAnalyticsIsPurchasedAsGift(purchase)) return false;
    if (f.giftStatus === 'gift_received' && !purchaseAnalyticsIsGiftReceived(purchase)) return false;
    if (f.giftStatus === 'not_gift' && (purchaseAnalyticsIsPurchasedAsGift(purchase) || purchaseAnalyticsIsGiftReceived(purchase))) return false;

    const spend = purchaseAnalyticsSpendAmount(purchase);
    const qty = purchaseAnalyticsQuantity(purchase);
    if (f.minCost !== '' && spend < paToNumber(f.minCost, 0)) return false;
    if (f.maxCost !== '' && spend > paToNumber(f.maxCost, Infinity)) return false;
    if (f.minQuantity !== '' && qty < paToNumber(f.minQuantity, 0)) return false;
    if (f.maxQuantity !== '' && qty > paToNumber(f.maxQuantity, Infinity)) return false;
    return true;
}

function getPurchaseAnalyticsPurchases(filters = null, data = appData) {
    const f = normalizePurchaseAnalyticsFilters(filters, data);
    const bounds = resolvePurchaseAnalyticsBounds(f, data);
    const seen = new Set();
    const list = [];
    (data.purchases || []).forEach(p => {
        if (!p || !p.id || seen.has(p.id)) return;
        const date = paTrim(p.date);
        if (!date) return;
        if (bounds.startDate && date < bounds.startDate) return;
        if (bounds.endDate && date > bounds.endDate) return;
        if (!purchaseAnalyticsMatchesFilters(p, f, data)) return;
        seen.add(p.id);
        list.push(p);
    });
    list.sort((a, b) => {
        const d = String(a.date).localeCompare(String(b.date));
        if (d !== 0) return d;
        return String(a.time || '').localeCompare(String(b.time || ''));
    });
    return list;
}

function getPurchaseAnalyticsSpendPurchases(filters = null, data = appData) {
    return getPurchaseAnalyticsPurchases(filters, data).filter(purchaseAnalyticsCountsTowardSpend);
}

function buildPurchaseFrequencyMetrics(purchases = []) {
    const dates = [...new Set(purchases.map(p => p.date).filter(Boolean))].sort();
    const gaps = [];
    for (let i = 1; i < dates.length; i += 1) {
        const gap = paDaysBetween(dates[i - 1], dates[i]);
        if (gap != null && gap >= 0) gaps.push(gap);
    }
    const byDay = {};
    const byWeek = {};
    const byMonth = {};
    const byYear = {};
    purchases.forEach(p => {
        const d = p.date;
        if (!d) return;
        byDay[d] = (byDay[d] || 0) + 1;
        const weekKey = typeof getIsoWeekKey === 'function'
            ? getIsoWeekKey(d)
            : d.slice(0, 7);
        byWeek[weekKey] = (byWeek[weekKey] || 0) + 1;
        const monthKey = d.slice(0, 7);
        byMonth[monthKey] = (byMonth[monthKey] || 0) + 1;
        const yearKey = d.slice(0, 4);
        byYear[yearKey] = (byYear[yearKey] || 0) + 1;
    });

    let longestNoPurchase = 0;
    if (dates.length) {
        for (let i = 1; i < dates.length; i += 1) {
            const gap = paDaysBetween(dates[i - 1], dates[i]);
            if (gap != null) longestNoPurchase = Math.max(longestNoPurchase, Math.max(0, gap - 1));
        }
        const sinceLast = paDaysBetween(dates[dates.length - 1], paToday());
        if (sinceLast != null) longestNoPurchase = Math.max(longestNoPurchase, Math.max(0, sinceLast));
    }

    const weekCount = Object.keys(byWeek).length || 1;
    const monthCount = Object.keys(byMonth).length || 1;

    return {
        byDay,
        byWeek,
        byMonth,
        byYear,
        averagePurchasesPerWeek: paRound(purchases.length / weekCount, 2),
        averagePurchasesPerMonth: paRound(purchases.length / monthCount, 2),
        averageDaysBetweenPurchases: paRound(paMean(gaps), 2),
        longestNoPurchaseStreak: longestNoPurchase,
        shortestIntervalDays: gaps.length ? Math.min(...gaps) : null,
        purchaseCount: purchases.length,
        uniquePurchaseDays: dates.length
    };
}

function buildPurchaseDashboardMetrics(purchases = [], data = appData, bounds = null) {
    const spendPurchases = purchases.filter(purchaseAnalyticsCountsTowardSpend);
    const spends = spendPurchases.map(purchaseAnalyticsSpendAmount);
    const qtys = spendPurchases.map(purchaseAnalyticsQuantity).filter(q => q > 0);
    const totalSpent = spends.reduce((s, n) => s + n, 0);
    const totalQty = qtys.reduce((s, n) => s + n, 0);
    const freq = buildPurchaseFrequencyMetrics(spendPurchases);
    const suppliers = new Set(purchases.map(purchaseAnalyticsSupplier).filter(Boolean));
    const stores = new Set(purchases.map(purchaseAnalyticsStore).filter(Boolean));

    let activeInventoryValue = 0;
    (data.purchases || []).forEach(p => {
        if (!purchaseAnalyticsIsUsableInventory(p)) return;
        const rem = purchaseAnalyticsRemaining(p);
        const qty = purchaseAnalyticsQuantity(p);
        const spend = purchaseAnalyticsSpendAmount(p);
        if (rem > 0 && qty > 0 && spend > 0) activeInventoryValue += spend * (rem / qty);
        else if (rem > 0 && typeof p.costPerUnit === 'number') activeInventoryValue += rem * p.costPerUnit;
    });

    const turnover = buildInventoryTurnoverMetrics(purchases, data, bounds);

    return {
        totalPurchases: purchases.length,
        spendPurchaseCount: spendPurchases.length,
        totalSpent: paRound(totalSpent, 2),
        averagePurchaseSize: paRound(paMean(spends), 2),
        medianPurchaseSize: paRound(paMedian(spends), 2),
        averageCostPerUnit: totalQty > 0 ? paRound(totalSpent / totalQty, 4) : null,
        averageDaysBetweenPurchases: freq.averageDaysBetweenPurchases,
        largestPurchase: spends.length ? paRound(Math.max(...spends), 2) : null,
        smallestPurchase: spends.length ? paRound(Math.min(...spends), 2) : null,
        activeSuppliers: suppliers.size,
        activeStores: stores.size,
        activeInventoryValue: paRound(activeInventoryValue, 2),
        inventoryTurnoverRate: turnover.turnoverRate
    };
}

function buildSupplierAnalytics(purchases = [], data = appData) {
    const map = new Map();
    purchases.forEach(p => {
        const name = purchaseAnalyticsSupplier(p) || 'Unknown';
        const key = paKey(name);
        if (!map.has(key)) {
            map.set(key, {
                id: key,
                name,
                purchases: [],
                totalSpent: 0,
                totalQty: 0,
                substances: {},
                productTypes: {},
                notes: ''
            });
        }
        const row = map.get(key);
        row.purchases.push(p);
        if (purchaseAnalyticsCountsTowardSpend(p)) {
            const spend = purchaseAnalyticsSpendAmount(p);
            const qty = purchaseAnalyticsQuantity(p);
            row.totalSpent += spend;
            if (qty > 0) row.totalQty += qty;
        }
        const sid = p.substanceId || 'unknown';
        row.substances[sid] = (row.substances[sid] || 0) + 1;
        const pt = purchaseAnalyticsProductType(p) || 'n/a';
        row.productTypes[pt] = (row.productTypes[pt] || 0) + 1;
    });

    const today = paToday();
    return [...map.values()].map(row => {
        const dates = row.purchases.map(p => p.date).filter(Boolean).sort();
        const freq = buildPurchaseFrequencyMetrics(row.purchases.filter(purchaseAnalyticsCountsTowardSpend));
        const topSubstance = Object.entries(row.substances).sort((a, b) => b[1] - a[1])[0]?.[0] || '';
        const topProduct = Object.entries(row.productTypes).sort((a, b) => b[1] - a[1])[0]?.[0] || '';
        const last = dates[dates.length - 1] || '';
        const daysSince = last ? paDaysBetween(last, today) : null;
        const completeness = row.purchases.filter(p => purchaseAnalyticsStore(p) && purchaseAnalyticsSpendAmount(p) > 0).length / Math.max(1, row.purchases.length);
        const reliabilityScore = paRound(Math.min(100, (
            (freq.averageDaysBetweenPurchases != null ? 40 : 20)
            + completeness * 40
            + Math.min(20, row.purchases.length * 2)
            - Math.min(30, (daysSince || 0) > 90 ? 20 : 0)
        )), 0);
        return {
            id: row.id,
            name: row.name,
            totalPurchases: row.purchases.length,
            totalSpent: paRound(row.totalSpent, 2),
            averagePurchase: row.purchases.length ? paRound(row.totalSpent / row.purchases.filter(purchaseAnalyticsCountsTowardSpend).length || 1, 2) : null,
            averageCostPerUnit: row.totalQty > 0 ? paRound(row.totalSpent / row.totalQty, 4) : null,
            mostPurchasedSubstance: topSubstance
                ? (typeof getSubstanceDisplayName === 'function' ? getSubstanceDisplayName(topSubstance, data) : topSubstance)
                : '—',
            mostPurchasedProductType: topProduct,
            firstPurchase: dates[0] || '',
            lastPurchase: last,
            purchaseFrequencyDays: freq.averageDaysBetweenPurchases,
            reliabilityScore,
            notes: row.notes,
            status: daysSince != null && daysSince > 90 ? 'inactive' : 'active'
        };
    }).sort((a, b) => b.totalSpent - a.totalSpent);
}

function buildStoreAnalytics(purchases = [], data = appData) {
    const prefs = ensurePurchaseAnalyticsPrefs(data);
    const map = new Map();
    purchases.forEach(p => {
        const name = purchaseAnalyticsStore(p) || 'Unknown';
        const key = paKey(name);
        if (!map.has(key)) {
            map.set(key, {
                id: key,
                name,
                purchases: [],
                totalSpent: 0,
                totalQty: 0,
                products: {}
            });
        }
        const row = map.get(key);
        row.purchases.push(p);
        if (purchaseAnalyticsCountsTowardSpend(p)) {
            row.totalSpent += purchaseAnalyticsSpendAmount(p);
            const qty = purchaseAnalyticsQuantity(p);
            if (qty > 0) row.totalQty += qty;
        }
        const product = purchaseAnalyticsProductType(p)
            || (typeof getSubstanceDisplayName === 'function' ? getSubstanceDisplayName(p.substanceId, data) : p.substanceId)
            || 'n/a';
        row.products[product] = (row.products[product] || 0) + 1;
    });

    return [...map.values()].map(row => {
        const dates = row.purchases.map(p => p.date).filter(Boolean).sort();
        const topProduct = Object.entries(row.products).sort((a, b) => b[1] - a[1])[0]?.[0] || '—';
        const spendCount = row.purchases.filter(purchaseAnalyticsCountsTowardSpend).length || 1;
        return {
            id: row.id,
            name: row.name,
            totalSpent: paRound(row.totalSpent, 2),
            purchaseCount: row.purchases.length,
            averageCost: paRound(row.totalSpent / spendCount, 2),
            mostCommonProduct: topProduct,
            averageCostPerUnit: row.totalQty > 0 ? paRound(row.totalSpent / row.totalQty, 4) : null,
            lastVisit: dates[dates.length - 1] || '',
            distance: prefs.storeDistances[row.id] ?? prefs.storeDistances[row.name] ?? null,
            favorite: prefs.favoriteStores.some(s => paKey(s) === row.id || paKey(s) === paKey(row.name))
        };
    }).sort((a, b) => b.totalSpent - a.totalSpent);
}

function buildPriceTrackingMetrics(purchases = [], data = appData) {
    const points = [];
    purchases.filter(purchaseAnalyticsCountsTowardSpend).forEach(p => {
        const metricKey = purchaseAnalyticsPriceMetricKey(p, data);
        const qty = purchaseAnalyticsPriceQuantity(p, metricKey);
        const spend = purchaseAnalyticsSpendAmount(p);
        if (!(qty > 0) || !(spend >= 0)) return;
        points.push({
            id: p.id,
            date: p.date,
            substanceId: p.substanceId,
            productType: purchaseAnalyticsProductType(p),
            store: purchaseAnalyticsStore(p),
            supplier: purchaseAnalyticsSupplier(p),
            metricKey,
            unitPrice: spend / qty,
            quantity: qty,
            spend
        });
    });

    const byMetric = {};
    points.forEach(pt => {
        if (!byMetric[pt.metricKey]) byMetric[pt.metricKey] = [];
        byMetric[pt.metricKey].push(pt);
    });

    const series = Object.entries(byMetric).map(([metricKey, list]) => {
        const sorted = list.slice().sort((a, b) => String(a.date).localeCompare(String(b.date)));
        const monthly = {};
        sorted.forEach(pt => {
            const m = String(pt.date).slice(0, 7);
            if (!monthly[m]) monthly[m] = { spend: 0, qty: 0 };
            monthly[m].spend += pt.spend;
            monthly[m].qty += pt.quantity;
        });
        const monthlyAvg = Object.entries(monthly)
            .sort((a, b) => a[0].localeCompare(b[0]))
            .map(([month, v]) => ({ month, average: v.qty > 0 ? v.spend / v.qty : null }));

        let inflation = null;
        if (monthlyAvg.length >= 2) {
            const first = monthlyAvg[0].average;
            const last = monthlyAvg[monthlyAvg.length - 1].average;
            if (first > 0 && last != null) inflation = (last - first) / first;
        }

        const bySupplier = {};
        const byStore = {};
        sorted.forEach(pt => {
            if (pt.supplier) {
                if (!bySupplier[pt.supplier]) bySupplier[pt.supplier] = { spend: 0, qty: 0 };
                bySupplier[pt.supplier].spend += pt.spend;
                bySupplier[pt.supplier].qty += pt.quantity;
            }
            if (pt.store) {
                if (!byStore[pt.store]) byStore[pt.store] = { spend: 0, qty: 0 };
                byStore[pt.store].spend += pt.spend;
                byStore[pt.store].qty += pt.quantity;
            }
        });
        const cheapestSupplier = Object.entries(bySupplier)
            .map(([name, v]) => ({ name, unitPrice: v.qty > 0 ? v.spend / v.qty : null }))
            .filter(x => x.unitPrice != null)
            .sort((a, b) => a.unitPrice - b.unitPrice)[0] || null;
        const cheapestStore = Object.entries(byStore)
            .map(([name, v]) => ({ name, unitPrice: v.qty > 0 ? v.spend / v.qty : null }))
            .filter(x => x.unitPrice != null)
            .sort((a, b) => a.unitPrice - b.unitPrice)[0] || null;
        const highest = sorted.slice().sort((a, b) => b.unitPrice - a.unitPrice)[0] || null;

        return {
            metricKey,
            label: metricKey.replace(/_/g, ' '),
            points: sorted.map(pt => ({ date: pt.date, unitPrice: paRound(pt.unitPrice, 4), store: pt.store, supplier: pt.supplier })),
            monthlyAverage: monthlyAvg.map(m => ({ ...m, average: paRound(m.average, 4) })),
            cheapestSupplier: cheapestSupplier ? { ...cheapestSupplier, unitPrice: paRound(cheapestSupplier.unitPrice, 4) } : null,
            cheapestStore: cheapestStore ? { ...cheapestStore, unitPrice: paRound(cheapestStore.unitPrice, 4) } : null,
            highestPrice: highest ? { date: highest.date, unitPrice: paRound(highest.unitPrice, 4), store: highest.store, supplier: highest.supplier } : null,
            inflationRate: inflation != null ? paRound(inflation, 4) : null
        };
    });

    return { points, series };
}

function buildPurchasePatternMetrics(purchases = []) {
    const spendPurchases = purchases.filter(purchaseAnalyticsCountsTowardSpend);
    const weekdayCounts = Array(7).fill(0);
    const hourBuckets = { morning: 0, afternoon: 0, evening: 0, night: 0 };
    const amounts = [];
    const spends = [];

    spendPurchases.forEach(p => {
        const d = typeof parseLocalDate === 'function' ? parseLocalDate(p.date) : null;
        if (d) weekdayCounts[d.getDay()] += 1;
        const time = paTrim(p.time || '12:00');
        const hour = paToNumber(time.split(':')[0], 12);
        if (hour >= 5 && hour < 12) hourBuckets.morning += 1;
        else if (hour >= 12 && hour < 17) hourBuckets.afternoon += 1;
        else if (hour >= 17 && hour < 22) hourBuckets.evening += 1;
        else hourBuckets.night += 1;
        amounts.push(purchaseAnalyticsQuantity(p));
        spends.push(purchaseAnalyticsSpendAmount(p));
    });

    const preferredDayIdx = weekdayCounts.indexOf(Math.max(...weekdayCounts));
    const preferredTime = Object.entries(hourBuckets).sort((a, b) => b[1] - a[1])[0]?.[0] || '—';
    const avgSpend = paMean(spends) || 0;
    const avgAmount = paMean(amounts) || 0;
    const spikes = spendPurchases.filter(p => purchaseAnalyticsSpendAmount(p) >= avgSpend * 2);
    const bulk = spendPurchases.filter(p => purchaseAnalyticsQuantity(p) >= avgAmount * 1.75 && avgAmount > 0);
    const freq = buildPurchaseFrequencyMetrics(spendPurchases);
    const emergency = spendPurchases.filter((p, i, arr) => {
        if (i === 0) return false;
        const gap = paDaysBetween(arr[i - 1].date, p.date);
        return gap != null && gap <= 1 && purchaseAnalyticsSpendAmount(p) > avgSpend;
    });

    return {
        preferredPurchaseDays: weekdayCounts
            .map((count, idx) => ({ day: PURCHASE_ANALYTICS_WEEKDAYS[idx], count }))
            .filter(x => x.count > 0)
            .sort((a, b) => b.count - a.count),
        preferredPurchaseDay: weekdayCounts.some(c => c > 0) ? PURCHASE_ANALYTICS_WEEKDAYS[preferredDayIdx] : '—',
        preferredPurchaseTimes: hourBuckets,
        preferredPurchaseTime: preferredTime,
        typicalPurchaseAmount: paRound(avgAmount, 3),
        typicalSpending: paRound(avgSpend, 2),
        purchaseCycleDays: freq.averageDaysBetweenPurchases,
        purchaseSpikes: spikes.map(p => ({ id: p.id, date: p.date, spend: purchaseAnalyticsSpendAmount(p) })),
        bulkBuying: bulk.map(p => ({ id: p.id, date: p.date, quantity: purchaseAnalyticsQuantity(p) })),
        emergencyPurchases: emergency.map(p => ({ id: p.id, date: p.date, spend: purchaseAnalyticsSpendAmount(p) }))
    };
}

function buildInventoryTurnoverMetrics(purchases = [], data = appData, bounds = null) {
    const usable = (data.purchases || []).filter(purchaseAnalyticsIsUsableInventory);
    let purchasedQty = 0;
    let remainingQty = 0;
    let consumed = 0;
    let gifted = 0;
    let adjusted = 0;
    let waste = 0;

    usable.forEach(p => {
        const bought = purchaseAnalyticsQuantity(p);
        const rem = purchaseAnalyticsRemaining(p);
        purchasedQty += bought;
        remainingQty += Math.max(0, rem);
        const used = Math.max(0, bought - Math.max(0, rem));
        consumed += used;
    });

    (data.logs || []).forEach(log => {
        if (bounds?.startDate && log.date < bounds.startDate) return;
        if (bounds?.endDate && log.date > bounds.endDate) return;
        const amount = paToNumber(log.amount ?? log.quantity, 0);
        if (typeof isGiftGivenLog === 'function' && isGiftGivenLog(log)) gifted += Math.abs(amount);
        else if (typeof isInventoryAdjustmentLog === 'function' && isInventoryAdjustmentLog(log)) {
            if (typeof inventoryAdjustmentRemoves === 'function' && inventoryAdjustmentRemoves(log)) adjusted += Math.abs(amount);
            else adjusted += Math.abs(amount);
        }
    });

    // Approximate waste as adjustments that remove stock beyond normal use tracking
    waste = Math.max(0, adjusted);

    const daysInRange = bounds?.startDate && bounds?.endDate
        ? Math.max(1, (paDaysBetween(bounds.startDate, bounds.endDate) || 0) + 1)
        : 30;
    const depletionRate = consumed / daysInRange;
    const daysInventoryLasts = depletionRate > 0 ? remainingQty / depletionRate : null;
    const purchaseInterval = buildPurchaseFrequencyMetrics(
        purchases.filter(purchaseAnalyticsCountsTowardSpend)
    ).averageDaysBetweenPurchases;
    const turnoverRate = purchasedQty > 0 ? paRound(consumed / purchasedQty, 4) : null;

    return {
        daysInventoryLasts: daysInventoryLasts != null ? paRound(daysInventoryLasts, 1) : null,
        averageDepletionRate: paRound(depletionRate, 4),
        averagePurchaseInterval: purchaseInterval,
        inventoryWaste: paRound(waste, 3),
        inventoryGifted: paRound(gifted, 3),
        inventoryAdjusted: paRound(adjusted, 3),
        inventoryConsumed: paRound(consumed, 3),
        inventoryRemaining: paRound(remainingQty, 3),
        turnoverRate
    };
}

function buildProductAnalytics(purchases = [], data = appData) {
    const map = new Map();
    purchases.forEach(p => {
        const productType = purchaseAnalyticsProductType(p) || 'unspecified';
        const key = paKey(productType);
        if (!map.has(key)) {
            map.set(key, {
                productType,
                purchases: [],
                spent: 0,
                qty: 0,
                durations: []
            });
        }
        const row = map.get(key);
        row.purchases.push(p);
        if (purchaseAnalyticsCountsTowardSpend(p)) {
            row.spent += purchaseAnalyticsSpendAmount(p);
            const q = purchaseAnalyticsQuantity(p);
            if (q > 0) row.qty += q;
        }
    });

    return [...map.values()].map(row => {
        const freq = buildPurchaseFrequencyMetrics(row.purchases.filter(purchaseAnalyticsCountsTowardSpend));
        const spendCount = row.purchases.filter(purchaseAnalyticsCountsTowardSpend).length || 1;
        return {
            productType: row.productType,
            purchaseFrequency: freq.averagePurchasesPerMonth,
            spending: paRound(row.spent, 2),
            averagePrice: paRound(row.spent / spendCount, 2),
            averageAmount: row.qty > 0 ? paRound(row.qty / spendCount, 3) : null,
            averageDurationDays: freq.averageDaysBetweenPurchases,
            inventoryLifespanDays: freq.averageDaysBetweenPurchases
        };
    }).sort((a, b) => b.spending - a.spending);
}

function buildPurchaseAnalyticsWarnings(purchases = [], data = appData, prefs = null) {
    const p = prefs || ensurePurchaseAnalyticsPrefs(data);
    const enabled = type => p.alertsEnabled !== false && p.alertTypes?.[type] !== false;
    const alerts = [];
    const spendPurchases = purchases.filter(purchaseAnalyticsCountsTowardSpend);
    const avgSpend = paMean(spendPurchases.map(purchaseAnalyticsSpendAmount)) || 0;
    const avgCpu = (() => {
        let spend = 0;
        let qty = 0;
        spendPurchases.forEach(x => {
            const q = purchaseAnalyticsQuantity(x);
            if (q > 0) {
                spend += purchaseAnalyticsSpendAmount(x);
                qty += q;
            }
        });
        return qty > 0 ? spend / qty : null;
    })();

    const sorted = spendPurchases.slice().sort((a, b) => String(a.date).localeCompare(String(b.date)));
    sorted.forEach((purchase, idx) => {
        if (enabled('aboveAveragePrice') && avgCpu != null) {
            const cpu = purchaseAnalyticsCostPerUnit(purchase);
            if (cpu != null && cpu > avgCpu * p.aboveAverageMultiplier) {
                alerts.push({
                    type: 'aboveAveragePrice',
                    severity: 'warn',
                    purchaseId: purchase.id,
                    message: `Purchase on ${purchase.date} is above average unit price.`
                });
            }
        }
        if (enabled('missingSupplier') && !purchaseAnalyticsSupplier(purchase)) {
            alerts.push({ type: 'missingSupplier', severity: 'info', purchaseId: purchase.id, message: `Missing supplier on ${purchase.date}.` });
        }
        if (enabled('missingStore') && !purchaseAnalyticsStore(purchase)) {
            alerts.push({ type: 'missingStore', severity: 'info', purchaseId: purchase.id, message: `Missing store on ${purchase.date}.` });
        }
        if (enabled('missingCost') && !(purchaseAnalyticsSpendAmount(purchase) > 0) && purchaseAnalyticsCountsTowardSpend(purchase)) {
            const rawCost = paToNumber(purchase.totalCost ?? purchase.cost, NaN);
            if (!Number.isFinite(rawCost) || rawCost <= 0) {
                alerts.push({ type: 'missingCost', severity: 'warn', purchaseId: purchase.id, message: `Missing cost on ${purchase.date}.` });
            }
        }
        if (enabled('missingQuantity') && !(purchaseAnalyticsQuantity(purchase) > 0)) {
            alerts.push({ type: 'missingQuantity', severity: 'warn', purchaseId: purchase.id, message: `Missing quantity on ${purchase.date}.` });
        }
        if (enabled('shortInterval') && idx > 0) {
            const gap = paDaysBetween(sorted[idx - 1].date, purchase.date);
            if (gap != null && gap <= p.shortIntervalDays) {
                alerts.push({
                    type: 'shortInterval',
                    severity: 'warn',
                    purchaseId: purchase.id,
                    message: `Only ${gap} day(s) between purchases (${sorted[idx - 1].date} → ${purchase.date}).`
                });
            }
        }
    });

    if (enabled('duplicatePurchase')) {
        const seen = new Map();
        spendPurchases.forEach(purchase => {
            const key = [
                purchase.date,
                purchase.substanceId,
                paRound(purchaseAnalyticsSpendAmount(purchase), 2),
                paRound(purchaseAnalyticsQuantity(purchase), 3),
                paKey(purchaseAnalyticsStore(purchase))
            ].join('|');
            if (seen.has(key)) {
                alerts.push({
                    type: 'duplicatePurchase',
                    severity: 'warn',
                    purchaseId: purchase.id,
                    message: `Possible duplicate purchase on ${purchase.date}.`
                });
            } else seen.set(key, purchase.id);
        });
    }

    const turnover = buildInventoryTurnoverMetrics(purchases, data);
    if (enabled('overstocked') && turnover.daysInventoryLasts != null && turnover.daysInventoryLasts > p.overstockDaysSupply) {
        alerts.push({
            type: 'overstocked',
            severity: 'info',
            message: `Inventory may last ~${turnover.daysInventoryLasts} days (overstock threshold ${p.overstockDaysSupply}).`
        });
    }
    if (enabled('inventoryExpiring') && turnover.daysInventoryLasts != null && turnover.daysInventoryLasts < 3 && turnover.inventoryRemaining > 0) {
        alerts.push({
            type: 'inventoryExpiring',
            severity: 'warn',
            message: 'Remaining inventory may run out within a few days based on recent depletion.'
        });
    }

    return alerts.slice(0, 50);
}

function buildPurchaseAnalyticsCharts(purchases = [], suppliers = [], stores = [], products = [], price = null, frequency = null) {
    const supplierSpend = suppliers.slice(0, 8).map(s => ({ label: s.name, value: s.totalSpent }));
    const storeSpend = stores.slice(0, 8).map(s => ({ label: s.name, value: s.totalSpent }));
    const productSpend = products.slice(0, 8).map(p => ({ label: p.productType, value: p.spending }));
    const timeline = Object.entries(frequency?.byDay || {}).map(([date, count]) => ({ label: date, value: count }));
    const monthlyHeat = Object.entries(frequency?.byMonth || {}).map(([month, count]) => ({ label: month, value: count }));
    const priceTrend = (price?.series?.[0]?.points || []).map(pt => ({ label: pt.date, value: pt.unitPrice }));
    const avgSizeSeries = Object.entries(frequency?.byMonth || {}).map(([month]) => {
        const monthPurchases = purchases.filter(p => String(p.date).startsWith(month) && purchaseAnalyticsCountsTowardSpend(p));
        const avg = paMean(monthPurchases.map(purchaseAnalyticsSpendAmount));
        return { label: month, value: avg == null ? 0 : avg };
    });

    return {
        spendingBySupplier: supplierSpend,
        spendingByStore: storeSpend,
        spendingByProduct: productSpend,
        purchaseTimeline: timeline,
        monthlyPurchaseHeatmap: monthlyHeat,
        priceTrend,
        averagePurchaseSize: avgSizeSeries
    };
}

function buildPurchaseAnalyticsDataset(data = appData, options = {}) {
    const prefs = ensurePurchaseAnalyticsPrefs(data);
    const filters = normalizePurchaseAnalyticsFilters(options.filters || prefs.filters, data);
    const bounds = resolvePurchaseAnalyticsBounds(filters, data);
    const cacheKey = JSON.stringify({
        filters,
        bounds,
        purchaseCount: (data.purchases || []).length,
        logCount: (data.logs || []).length,
        fav: prefs.favoriteStores,
        dist: prefs.storeDistances
    });
    if (!options.bypassCache && purchaseAnalyticsCache && purchaseAnalyticsCacheKey === cacheKey) {
        return purchaseAnalyticsCache;
    }

    const purchases = getPurchaseAnalyticsPurchases(filters, data);
    const dashboard = buildPurchaseDashboardMetrics(purchases, data, bounds);
    const frequency = buildPurchaseFrequencyMetrics(purchases.filter(purchaseAnalyticsCountsTowardSpend));
    const suppliers = buildSupplierAnalytics(purchases, data);
    const stores = buildStoreAnalytics(purchases, data);
    const price = buildPriceTrackingMetrics(purchases, data);
    const patterns = buildPurchasePatternMetrics(purchases);
    const turnover = buildInventoryTurnoverMetrics(purchases, data, bounds);
    const products = buildProductAnalytics(purchases, data);
    const warnings = buildPurchaseAnalyticsWarnings(purchases, data, prefs);
    const charts = buildPurchaseAnalyticsCharts(purchases, suppliers, stores, products, price, frequency);

    const dataset = {
        generatedAt: new Date().toISOString(),
        filters,
        bounds,
        prefs,
        purchases,
        dashboard,
        frequency,
        suppliers,
        stores,
        price,
        patterns,
        turnover,
        products,
        warnings,
        charts
    };
    purchaseAnalyticsCache = dataset;
    purchaseAnalyticsCacheKey = cacheKey;
    return dataset;
}

function buildPurchaseAnalyticsCsvRows(dataset) {
    const rows = [];
    rows.push(['Section', 'Field', 'Value']);
    const d = dataset.dashboard || {};
    Object.entries(d).forEach(([k, v]) => rows.push(['Dashboard', k, v == null ? '' : v]));
    (dataset.suppliers || []).forEach(s => {
        rows.push(['Supplier', s.name, `spent=${s.totalSpent};count=${s.totalPurchases};cpu=${s.averageCostPerUnit ?? ''};status=${s.status}`]);
    });
    (dataset.stores || []).forEach(s => {
        rows.push(['Store', s.name, `spent=${s.totalSpent};count=${s.purchaseCount};favorite=${s.favorite ? 1 : 0}`]);
    });
    (dataset.price?.series || []).forEach(series => {
        series.points.forEach(pt => rows.push(['Price', series.metricKey, `${pt.date}:${pt.unitPrice}`]));
    });
    (dataset.products || []).forEach(p => {
        rows.push(['Product', p.productType, `spent=${p.spending};avgPrice=${p.averagePrice ?? ''}`]);
    });
    const t = dataset.turnover || {};
    Object.entries(t).forEach(([k, v]) => rows.push(['Turnover', k, v == null ? '' : v]));
    (dataset.warnings || []).forEach(w => rows.push(['Warning', w.type, w.message]));
    return rows;
}

function exportPurchaseAnalyticsCsv(data = appData) {
    const dataset = buildPurchaseAnalyticsDataset(data, { bypassCache: true });
    const rows = buildPurchaseAnalyticsCsvRows(dataset);
    const csv = rows.map(r => r.map(cell => {
        const s = String(cell ?? '');
        return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
    }).join(',')).join('\n');
    if (typeof downloadTextFile === 'function') {
        downloadTextFile(`purchase-analytics-${paToday()}.csv`, csv, 'text/csv');
    }
    return csv;
}

function paBarChartHtml(items, maxHint = null) {
    const list = (items || []).filter(i => i && (i.value != null));
    if (!list.length) return '<p class="pa-empty">No chart data for this range.</p>';
    const max = maxHint || Math.max(...list.map(i => paToNumber(i.value, 0)), 0.0001);
    return `<div class="pa-bar-chart">${list.slice(0, 12).map(item => {
        const v = paToNumber(item.value, 0);
        const pct = Math.max(2, Math.round((v / max) * 100));
        return `<div class="pa-bar-row"><span>${escapeHtml(item.label)}</span><div class="pa-bar-track"><span class="pa-bar-fill" style="width:${pct}%"></span></div><span>${escapeHtml(String(paRound(v, 2) ?? v))}</span></div>`;
    }).join('')}</div>`;
}

function paTableHtml(headers, rows) {
    if (!rows.length) return '<p class="pa-empty">No rows for this range.</p>';
    return `<div class="table-scroll"><table class="pa-table sheet-table"><thead><tr>${headers.map(h => `<th>${escapeHtml(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${r.map(c => `<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}

