function formatGoalLinkedContactsHtml(goal, data = appData) {
    if (!goal) return '';
    const parts = [];
    const add = (label, id, name) => {
        if (id) parts.push(`${label}: <button type="button" class="link-btn" onclick="openContactDetailPanel('${ctEscAttr(id)}')">${escapeHtml(getContactDisplayName(id, data) || name || 'Contact')}</button>`);
        else if (name) parts.push(`${label}: ${escapeHtml(name)}`);
    };
    add('Accountability', goal.accountabilityPartnerContactId, goal.accountabilityPartnerName);
    add('Support', goal.supportContactId, goal.supportContactName);
    add('Check-in', goal.checkInContactId, goal.checkInContactName);
    return parts.length ? `<p class="settings-hint ct-linked-line">${parts.join(' · ')}</p>` : '';
}

function initContactsIntegrationUi() {
    mountLogContactPickers();
    mountBuyContactPickers();
    if (typeof document !== 'undefined') {
        document.addEventListener('click', (event) => {
            const t = event.target;
            if (!(t instanceof Element)) return;
            if (t.closest('.ct-picker')) return;
            document.querySelectorAll('.ct-picker-menu').forEach(el => el.classList.add('hidden'));
        });
    }
}


// ——— Shared Insights filter state (source of truth) ———
// Every Insights section must consume these filters. Display settings
// (columns, chart widgets, reset mode) stay separate.

const INSIGHTS_FILTERS_KEY = 'insightsFilters';

function getDefaultInsightsFilters() {
    return {
        substanceId: typeof DASHBOARD_ALL !== 'undefined' ? DASHBOARD_ALL : 'all',
        productType: '',
        dateRangePreset: 'last-7',
        customStart: '',
        customEnd: '',
        transactionType: ''
    };
}

function ensureInsightsFilters(data = appData) {
    if (!data || typeof data !== 'object') return getDefaultInsightsFilters();
    if (!data.settings || typeof data.settings !== 'object') data.settings = {};
    const defaults = getDefaultInsightsFilters();
    if (!data.settings[INSIGHTS_FILTERS_KEY] || typeof data.settings[INSIGHTS_FILTERS_KEY] !== 'object') {
        // Seed from existing globals / dashboard substance when available
        const seeded = { ...defaults };
        try {
            const dash = data.settings.dashboardSubstanceId
                || data.settings.recoveryDashboard?.selectedDashboardSubstance;
            if (dash) seeded.substanceId = dash;
            if (typeof statsDateRangePreset === 'string' && statsDateRangePreset) {
                seeded.dateRangePreset = statsDateRangePreset;
            }
            if (typeof statsCustomStartDate === 'string') seeded.customStart = statsCustomStartDate;
            if (typeof statsCustomEndDate === 'string') seeded.customEnd = statsCustomEndDate;
        } catch (_) { /* optional */ }
        data.settings[INSIGHTS_FILTERS_KEY] = seeded;
    }
    const prefs = data.settings[INSIGHTS_FILTERS_KEY];
    Object.keys(defaults).forEach(key => {
        if (prefs[key] === undefined) prefs[key] = defaults[key];
    });
    if (!prefs.substanceId) prefs.substanceId = defaults.substanceId;
    if (!prefs.dateRangePreset) prefs.dateRangePreset = defaults.dateRangePreset;
    // Non-weed substances cannot keep a weed product-type filter
    if (prefs.productType && !insightsFiltersIsWeedSubstance(prefs.substanceId, data)) {
        prefs.productType = '';
    }
    return prefs;
}

function getInsightsFilters(data = appData) {
    return ensureInsightsFilters(data);
}

/** Named accessors matching product requirements */
function getSelectedInsightsSubstance(data = appData) {
    return getInsightsFilters(data).substanceId;
}
function getSelectedInsightsProductType(data = appData) {
    return getInsightsFilters(data).productType || '';
}
function getSelectedInsightsDateRange(data = appData) {
    const f = getInsightsFilters(data);
    return {
        preset: f.dateRangePreset,
        customStart: f.customStart || '',
        customEnd: f.customEnd || ''
    };
}
function getSelectedInsightsTransactionType(data = appData) {
    return getInsightsFilters(data).transactionType || '';
}

function insightsFiltersIsAll(substanceId) {
    const id = String(substanceId ?? '').trim();
    return !id || id === 'all' || (typeof DASHBOARD_ALL !== 'undefined' && id === DASHBOARD_ALL);
}

function insightsFiltersIsWeedSubstance(substanceId, data = appData) {
    if (insightsFiltersIsAll(substanceId)) return false;
    if (typeof isWeedTrackingMode === 'function') return !!isWeedTrackingMode(substanceId, data);
    const sub = (data?.substances || []).find(s => String(s.id) === String(substanceId));
    return String(sub?.trackingMode || '').toLowerCase() === 'weed';
}

function loadInsightsFiltersIntoState(data = appData) {
    const f = ensureInsightsFilters(data);
    // Keep in-memory Insights globals aligned with persisted shared filters.
    // These lets are declared later in app.js — assignment throws in TDZ and is ignored.
    try {
        currentSubstanceId = f.substanceId;
        selectedDashboardSubstance = f.substanceId;
        statsDateRangePreset = f.dateRangePreset || 'last-7';
        statsCustomStartDate = f.customStart || '';
        statsCustomEndDate = f.customEnd || '';
    } catch (_) { /* Temporal Dead Zone / early init */ }
    return f;
}

function syncInsightsFilterUi(data = appData) {
    const f = ensureInsightsFilters(data);
    const setVal = (id, value) => {
        const el = typeof document !== 'undefined' ? document.getElementById(id) : null;
        if (el && value != null) el.value = value;
    };
    setVal('stats-substance', f.substanceId);
    setVal('stats-date-range', f.dateRangePreset);
    setVal('stats-custom-start', f.customStart || '');
    setVal('stats-custom-end', f.customEnd || '');
    setVal('stats-product-type', f.productType || '');
    setVal('stats-transaction-type', f.transactionType || '');
    const customWrap = typeof document !== 'undefined' ? document.getElementById('stats-custom-range-wrap') : null;
    if (customWrap) customWrap.classList.toggle('hidden', f.dateRangePreset !== 'custom');
    const productWrap = typeof document !== 'undefined' ? document.getElementById('stats-product-type-wrap') : null;
    if (productWrap) {
        const show = insightsFiltersIsWeedSubstance(f.substanceId, data);
        productWrap.classList.toggle('hidden', !show);
        if (!show) {
            const sel = document.getElementById('stats-product-type');
            if (sel) sel.value = '';
        }
    }
}

/**
 * Push shared Insights filters into section-specific prefs (without saveData loops).
 * Section-local display prefs (reset mode, chart interval, etc.) are preserved.
 */
function syncSectionFiltersFromInsights(data = appData) {
    const f = ensureInsightsFilters(data);
    const substanceId = f.substanceId || 'all';
    const datePatch = {
        substanceId,
        productType: f.productType || '',
        dateRangePreset: f.dateRangePreset || 'last-7',
        customStart: f.customStart || '',
        customEnd: f.customEnd || '',
        transactionType: f.transactionType || ''
    };

    // Materialize Insights date range into concrete custom bounds so every
    // section resolver (financial, charts, running totals) sees the same window.
    if (typeof getStatsDateRange === 'function') {
        try {
            const bounds = getStatsDateRange();
            if (bounds?.startDate && bounds?.endDate) {
                datePatch.customStart = bounds.startDate;
                datePatch.customEnd = bounds.endDate;
                datePatch.dateRangePreset = 'custom';
            }
        } catch (_) { /* optional */ }
    }

    if (typeof ensureRunningTotalsPrefs === 'function') {
        const rt = ensureRunningTotalsPrefs(data);
        rt.filters = { ...rt.filters, ...datePatch };
    }
    if (typeof ensureChartSystemPrefs === 'function') {
        const ch = ensureChartSystemPrefs(data);
        ch.filters = { ...ch.filters, ...datePatch };
    }
    if (typeof ensureFinancialAnalyticsPrefs === 'function') {
        const fin = ensureFinancialAnalyticsPrefs(data);
        fin.filters = { ...(fin.filters || {}), ...datePatch };
    }
    if (typeof ensurePurchaseAnalyticsPrefs === 'function') {
        const pa = ensurePurchaseAnalyticsPrefs(data);
        pa.filters = { ...(pa.filters || {}), ...datePatch };
    }
    return f;
}

function invalidateInsightsSectionCaches() {
    if (typeof invalidateInsightsDatasetCache === 'function') invalidateInsightsDatasetCache();
    if (typeof invalidateChartSystemCache === 'function') invalidateChartSystemCache();
    if (typeof invalidateFinancialAnalyticsCache === 'function') invalidateFinancialAnalyticsCache();
    if (typeof invalidatePurchaseAnalyticsCache === 'function') invalidatePurchaseAnalyticsCache();
}

/**
 * Persist shared Insights filters, sync globals + section prefs, optionally re-render.
 */
function persistInsightsFilters(patch = {}, options = {}) {
    const {
        data = appData,
        render = false,
        save = true,
        syncSections = true
    } = options;
    const prefs = ensureInsightsFilters(data);
    Object.assign(prefs, patch || {});

    if (prefs.productType && !insightsFiltersIsWeedSubstance(prefs.substanceId, data)) {
        prefs.productType = '';
    }

    // Keep in-memory globals in sync (core Insights dataset uses these)
    try {
        currentSubstanceId = prefs.substanceId;
        selectedDashboardSubstance = prefs.substanceId;
        statsDateRangePreset = prefs.dateRangePreset || 'last-7';
        statsCustomStartDate = prefs.customStart || '';
        statsCustomEndDate = prefs.customEnd || '';
    } catch (_) { /* ignore */ }

    if (typeof saveDashboardViewSubstanceId === 'function') {
        try { saveDashboardViewSubstanceId(prefs.substanceId); } catch (_) { /* ignore */ }
    }
    if (typeof persistRecoveryDashboardPrefs === 'function') {
        try {
            persistRecoveryDashboardPrefs({ selectedDashboardSubstance: prefs.substanceId }, data);
        } catch (_) { /* ignore */ }
    }

    if (syncSections) syncSectionFiltersFromInsights(data);
    invalidateInsightsSectionCaches();
    syncInsightsFilterUi(data);

    if (save && typeof saveData === 'function') saveData(data);
    if (render && typeof updateStats === 'function') updateStats();
    return prefs;
}

function setSelectedInsightsSubstance(substanceId, options = {}) {
    let next = substanceId || (typeof DASHBOARD_ALL !== 'undefined' ? DASHBOARD_ALL : 'all');
    if (!insightsFiltersIsAll(next) && typeof normalizeSubstanceRef === 'function') {
        next = normalizeSubstanceRef(next, options.data || appData) || next;
    }
    const patch = { substanceId: next };
    // Clear weed product type when leaving Weed
    if (!insightsFiltersIsWeedSubstance(next, options.data || appData)) {
        patch.productType = '';
    }
    return persistInsightsFilters(patch, { render: true, ...options });
}

function setSelectedInsightsProductType(productType, options = {}) {
    const data = options.data || appData;
    const f = ensureInsightsFilters(data);
    if (!insightsFiltersIsWeedSubstance(f.substanceId, data)) {
        return persistInsightsFilters({ productType: '' }, { render: true, ...options, data });
    }
    return persistInsightsFilters({ productType: productType || '' }, { render: true, ...options, data });
}

function setSelectedInsightsDateRange(preset, customStart = '', customEnd = '', options = {}) {
    return persistInsightsFilters({
        dateRangePreset: preset || 'last-7',
        customStart: customStart || '',
        customEnd: customEnd || ''
    }, { render: true, ...options });
}

function setSelectedInsightsTransactionType(transactionType, options = {}) {
    return persistInsightsFilters({ transactionType: transactionType || '' }, { render: true, ...options });
}

/** Clear visible section roots so stale substance data never flashes under a new label. */
function clearInsightsSectionOutputs() {
    if (typeof document === 'undefined') return;
    const ids = [
        'running-totals-root',
        'chart-dashboard-root',
        'financial-analytics-root',
        'purchase-analytics-root',
        'insights-contacts-root',
        'goal-insights-panel',
        'stats-weekly-summary',
        'stats-monthly-summary',
        'average-use-analytics-root'
    ];
    ids.forEach(id => {
        const el = document.getElementById(id);
        if (el) el.innerHTML = '<div class="settings-hint" role="status">Updating filters…</div>';
    });
}

/**
 * Render Insights module sections that must always follow shared filters,
 * including when All Substances is selected.
 */
function renderInsightsFilteredSections() {
    syncSectionFiltersFromInsights(appData);
    try {
        if (typeof renderFinancialAnalyticsView === 'function') renderFinancialAnalyticsView();
    } catch (err) { console.error('Financial analytics render failed', err); }
    try {
        if (typeof renderPurchaseAnalyticsView === 'function') renderPurchaseAnalyticsView();
    } catch (err) { console.error('Purchase analytics render failed', err); }
    try {
        if (typeof renderChartDashboardView === 'function') renderChartDashboardView();
    } catch (err) { console.error('Chart dashboard render failed', err); }
    try {
        if (typeof renderInsightsContactAnalytics === 'function') renderInsightsContactAnalytics();
    } catch (err) { console.error('Contact insights render failed', err); }
    try {
        if (typeof renderRunningTotalsView === 'function') renderRunningTotalsView();
    } catch (err) { console.error('Running totals render failed', err); }
    try {
        if (typeof renderAverageUseAnalyticsView === 'function') renderAverageUseAnalyticsView();
    } catch (err) { console.error('Average use analytics render failed', err); }
    try {
        if (typeof renderPlanAnalyticsPanel === 'function') renderPlanAnalyticsPanel();
    } catch (err) { console.error('Plan analytics render failed', err); }
}

function onInsightsProductTypeChange() {
    const value = typeof document !== 'undefined'
        ? (document.getElementById('stats-product-type')?.value || '')
        : '';
    setSelectedInsightsProductType(value);
}

function onInsightsTransactionTypeChange() {
    const value = typeof document !== 'undefined'
        ? (document.getElementById('stats-transaction-type')?.value || '')
        : '';
    setSelectedInsightsTransactionType(value);
}


// ——— Running Totals (Insights → Use Analytics) ———
// Cumulative personal-use sessions with product-specific units.
// Spliced into app.js ahead of `const defaultData`. Never mutates source records.

const RUNNING_TOTALS_RESET_MODES = Object.freeze([
    'daily', 'weekly', 'monthly', 'yearly', 'selected-range', 'inventory', 'lifetime'
]);

const RUNNING_TOTALS_GROUP_BY = Object.freeze([
    'session', 'day', 'week', 'month', 'inventory'
]);

function rtNum(value, fallback = 0) {
    return toFiniteNumber(value, fallback);
}

function rtRound(value, digits = 4) {
    return roundToOrNull(value, digits);
}

function rtTrim(value) {
    return trimToString(value);
}

function rtEsc(value) {
    return escapeHtmlSafe(value);
}

function rtToday() {
    return todayLocalDate();
}

function rtIsAll(substanceId) {
    const id = rtTrim(substanceId);
    return !id || id === 'all' || (typeof DASHBOARD_ALL !== 'undefined' && id === DASHBOARD_ALL);
}

function getDefaultRunningTotalsPrefs() {
    return {
        filters: {
            // Shared Insights filters are applied at dataset build time.
            // These fields remain for backward compatibility / tests.
            substanceId: 'all',
            productType: '',
            dateRangePreset: 'last-30',
            customStart: '',
            customEnd: '',
            transactionType: '',
            personalUseOnly: true,
            groupBy: 'session',
            resetMode: 'daily',
            newestFirst: true,
            showTargetLine: true,
            showCbdRunning: true
        }
    };
}

/** Merge shared Insights filters over Running Totals local display prefs. */
function resolveRunningTotalsFilters(options = {}, data = appData) {
    const prefs = ensureRunningTotalsPrefs(data);
    const local = { ...prefs.filters, ...(options.filters || {}) };
    if (typeof getInsightsFilters === 'function') {
        const inf = getInsightsFilters(data);
        local.substanceId = inf.substanceId;
        local.productType = inf.productType || '';
        local.dateRangePreset = inf.dateRangePreset || local.dateRangePreset;
        local.customStart = inf.customStart || '';
        local.customEnd = inf.customEnd || '';
        local.transactionType = inf.transactionType || '';
    }
    return local;
}

function ensureRunningTotalsPrefs(data = appData) {
    if (!data || typeof data !== 'object') return getDefaultRunningTotalsPrefs();
    if (!data.settings || typeof data.settings !== 'object') data.settings = {};
    const defaults = getDefaultRunningTotalsPrefs();
    if (!data.settings.runningTotals || typeof data.settings.runningTotals !== 'object') {
        data.settings.runningTotals = {
            filters: { ...defaults.filters }
        };
    }
    const prefs = data.settings.runningTotals;
    prefs.filters = { ...defaults.filters, ...(prefs.filters || {}) };
    if (!RUNNING_TOTALS_RESET_MODES.includes(prefs.filters.resetMode)) prefs.filters.resetMode = 'daily';
    if (!RUNNING_TOTALS_GROUP_BY.includes(prefs.filters.groupBy)) prefs.filters.groupBy = 'session';
    return prefs;
}

function getRunningTotalsPrefs(data = appData) {
    return ensureRunningTotalsPrefs(data);
}

function persistRunningTotalsPrefs(patch = {}, data = appData) {
    const prefs = ensureRunningTotalsPrefs(data);
    if (patch.filters) prefs.filters = { ...prefs.filters, ...patch.filters };
    if (typeof saveData === 'function') saveData(data);
    return prefs;
}

function resolveRunningTotalsBounds(filters, data = appData) {
    const f = { ...getDefaultRunningTotalsPrefs().filters, ...(filters || {}) };
    return resolveFilterDateBounds(f, '', data);
}

function runningTotalsWeekStartPref(data = appData) {
    try {
        if (typeof getCalendarViewPrefs === 'function') {
            const ws = getCalendarViewPrefs(data)?.weekStarts;
            if (ws === 'monday' || ws === 'sunday') return ws;
        }
    } catch (_) { /* optional */ }
    return data?.settings?.calendarView?.weekStarts === 'monday' ? 'monday' : 'sunday';
}

function runningTotalsWeekKey(dateStr, data = appData) {
    const weekStarts = runningTotalsWeekStartPref(data);
    if (typeof resolveCalendarPeriodBounds === 'function') {
        const bounds = resolveCalendarPeriodBounds('week', dateStr, weekStarts);
        if (bounds?.startDate) return bounds.startDate;
    }
    if (typeof parseLocalDate === 'function' && typeof getLocalDateString === 'function') {
        const d = parseLocalDate(dateStr);
        if (d) {
            const dow = d.getDay();
            const offset = weekStarts === 'monday' ? ((dow + 6) % 7) : dow;
            d.setDate(d.getDate() - offset);
            return getLocalDateString(d);
        }
    }
    if (typeof getWeekStartDateStr === 'function') return getWeekStartDateStr(dateStr);
    return String(dateStr || '').slice(0, 10);
}

function runningTotalsMonthKey(dateStr) {
    return String(dateStr || '').slice(0, 7);
}

function runningTotalsYearKey(dateStr) {
    return String(dateStr || '').slice(0, 4);
}

function isRunningTotalsEligibleLog(log, filters = {}, data = appData) {
    if (!log) return false;
    if (log.isDistributedChild) return false;
    if (typeof isAlcoholMultiDayChildLog === 'function' && isAlcoholMultiDayChildLog(log)) return false;
    if (log.parentPercentLogId != null && log.isEstimatedDailyUse) return false;

    const tx = typeof getLogTransactionType === 'function' ? getLogTransactionType(log) : (log.transactionType || 'use');
    if (tx === 'gift_given' || tx === 'gift_received' || tx === 'inventory_adjustment' || tx === 'shared_use') return false;
    if (filters.transactionType && tx !== filters.transactionType) return false;
    return tx === 'use';
}

function getRunningTotalsProductType(log, data = appData) {
    if (typeof normalizeWeedProductType === 'function' && typeof isWeedTrackingMode === 'function') {
        const sid = typeof getUseSubstanceId === 'function' ? getUseSubstanceId(log, data) : log.substanceId;
        if (isWeedTrackingMode(sid, data)) {
            return normalizeWeedProductType(log.weedProductType || '', { allowEmpty: true }) || '';
        }
    }
    if (typeof getNicotineProductType === 'function' && typeof isNicotineTrackingMode === 'function') {
        const sid = typeof getUseSubstanceId === 'function' ? getUseSubstanceId(log, data) : log.substanceId;
        if (isNicotineTrackingMode(sid, data)) return getNicotineProductType(log, data) || '';
    }
    return rtTrim(log.weedProductType || log.productType || log.nicotineProductType || '');
}

/**
 * Returns session display measure + accumulate measure for running totals.
 * accumulateAmount is what increments running totals (may differ from session, e.g. THC mg).
 */
function getRunningTotalsSessionMeasure(log, data = appData) {
    const sid = typeof getUseSubstanceId === 'function' ? getUseSubstanceId(log, data) : log.substanceId;
    const personal = typeof getLogStatsAmount === 'function' ? rtNum(getLogStatsAmount(log), 0) : rtNum(log.amount, 0);
    const productType = getRunningTotalsProductType(log, data);

    if (typeof isWeedTrackingMode === 'function' && isWeedTrackingMode(sid, data)) {
        if (productType === 'cart' || (typeof isWeedCartPercentLog === 'function' && isWeedCartPercentLog(log, data))) {
            const pct = rtNum(log.estimatedPercentUsed ?? personal, 0);
            return {
                sessionAmount: pct,
                sessionUnit: '%',
                accumulateAmount: pct,
                accumulateUnit: '%',
                productType: 'cart',
                unitFamily: 'percent'
            };
        }
        if (productType === 'edibles' || (typeof isWeedEdiblesLog === 'function' && isWeedEdiblesLog(log, data))) {
            const thc = typeof getWeedEdibleLogThcUsed === 'function' ? getWeedEdibleLogThcUsed(log) : null;
            const cbd = typeof getWeedEdibleLogCbdUsed === 'function' ? getWeedEdibleLogCbdUsed(log) : null;
            return {
                sessionAmount: personal,
                sessionUnit: 'edible',
                accumulateAmount: thc != null ? thc : personal,
                accumulateUnit: thc != null ? 'mg THC' : 'edible',
                secondaryAccumulate: cbd != null ? cbd : null,
                secondaryUnit: 'mg CBD',
                productType: 'edibles',
                unitFamily: thc != null ? 'thc_mg' : 'count'
            };
        }
        if (productType === 'pre-rolls') {
            const grams = rtNum(log.normalizedGrams, null);
            return {
                sessionAmount: personal,
                sessionUnit: 'pre-roll',
                accumulateAmount: personal,
                accumulateUnit: 'pre-roll',
                secondaryAccumulate: grams,
                secondaryUnit: 'g',
                productType: 'pre-rolls',
                unitFamily: 'count'
            };
        }
        // Bud / default weed
        const grams = rtNum(log.normalizedGrams ?? (log.unit === 'grams' || log.unit === 'g' ? log.amount : personal), personal);
        return {
            sessionAmount: grams,
            sessionUnit: 'g',
            accumulateAmount: grams,
            accumulateUnit: 'g',
            productType: productType || 'bud',
            unitFamily: 'mass_g'
        };
    }

    if (typeof isNicotineTrackingMode === 'function' && isNicotineTrackingMode(sid, data)) {
        return {
            sessionAmount: personal,
            sessionUnit: 'puffs',
            accumulateAmount: personal,
            accumulateUnit: 'puffs',
            productType: productType || 'vape',
            unitFamily: 'puffs'
        };
    }

    const trackingMode = (() => {
        const sub = (data?.substances || []).find(s => String(s.id) === String(sid));
        return String(sub?.trackingMode || '').toLowerCase();
    })();

    if ((typeof isLsdSubstanceId === 'function' && isLsdSubstanceId(sid, data)) || trackingMode === 'lsd') {
        const ug = rtNum(log.ugUsed ?? log.amount, personal);
        const tabs = rtNum(log.tabsUsed, null);
        return {
            sessionAmount: tabs != null ? tabs : ug,
            sessionUnit: tabs != null ? 'tabs' : 'µg',
            accumulateAmount: ug,
            accumulateUnit: 'µg',
            productType: '',
            unitFamily: 'ug'
        };
    }

    if ((typeof isXanaxSubstanceId === 'function' && isXanaxSubstanceId(sid, data)) || trackingMode === 'xanax') {
        const mg = rtNum(log.mgUsed, null);
        const pills = rtNum(log.pillsUsed ?? log.amount, personal);
        return {
            sessionAmount: pills,
            sessionUnit: 'pills',
            accumulateAmount: mg != null ? mg : pills,
            accumulateUnit: mg != null ? 'mg' : 'pills',
            productType: '',
            unitFamily: 'mg'
        };
    }

    const unit = log.unit || (typeof getSubstancePrimaryUnit === 'function' ? getSubstancePrimaryUnit(sid, data) : 'g') || 'g';
    return {
        sessionAmount: personal,
        sessionUnit: unit,
        accumulateAmount: personal,
        accumulateUnit: unit,
        productType: productType || '',
        unitFamily: 'auto'
    };
}

function getRunningTotalsResetKey(dateStr, resetMode, inventoryId, data = appData) {
    if (resetMode === 'lifetime' || resetMode === 'selected-range') return 'all';
    if (resetMode === 'inventory') return inventoryId ? String(inventoryId) : 'unlinked';
    if (resetMode === 'yearly') return runningTotalsYearKey(dateStr);
    if (resetMode === 'monthly') return runningTotalsMonthKey(dateStr);
    if (resetMode === 'weekly') return runningTotalsWeekKey(dateStr, data);
    return dateStr; // daily — local calendar date, resets at midnight
}

function getRunningTotalsTarget(substanceId, data = appData) {
    try {
        if (typeof getActiveTaperPlan === 'function') {
            const plan = getActiveTaperPlan(substanceId, data);
            const today = rtToday();
            const week = plan?.weeklyTargets?.find(w => (w.weekStart || '') <= today && (w.weekEnd || '9999') >= today);
            if (week?.targetAmount != null) return { value: rtNum(week.targetAmount, null), label: 'Weekly taper target' };
            if (plan?.currentWeeklyTarget != null) return { value: rtNum(plan.currentWeeklyTarget, null), label: 'Plan target' };
        }
    } catch (_) { /* optional */ }
    return null;
}

function collectRunningTotalsLogs(filters, data = appData) {
    const bounds = resolveRunningTotalsBounds(filters, data);
    const f = { ...getDefaultRunningTotalsPrefs().filters, ...filters };
    const logs = (data.logs || []).filter(log => {
        if (!isRunningTotalsEligibleLog(log, f, data)) return false;
        if (!log.date) return false;
        if (bounds.startDate && log.date < bounds.startDate) return false;
        if (bounds.endDate && log.date > bounds.endDate) return false;
        if (!rtIsAll(f.substanceId)) {
            if (typeof logMatchesSubstance === 'function') {
                if (!logMatchesSubstance(log, f.substanceId, data)) return false;
            } else {
                const sid = typeof getUseSubstanceId === 'function' ? getUseSubstanceId(log, data) : log.substanceId;
                if (String(sid) !== String(f.substanceId)) return false;
            }
        }
        if (f.productType) {
            if (getRunningTotalsProductType(log, data) !== f.productType) return false;
        }
        return true;
    });

    // Chronological for calculation
    logs.sort((a, b) => {
        const da = typeof getLogDatetimeMs === 'function' ? getLogDatetimeMs(a) : 0;
        const db = typeof getLogDatetimeMs === 'function' ? getLogDatetimeMs(b) : 0;
        if (da !== db) return da - db;
        return String(a.id).localeCompare(String(b.id));
    });
    return { logs, bounds };
}

function buildRunningTotalsRows(filters, data = appData) {
    const f = { ...getDefaultRunningTotalsPrefs().filters, ...filters };
    const { logs, bounds } = collectRunningTotalsLogs(f, data);
    const dayRun = new Map();
    const weekRun = new Map();
    const monthRun = new Map();
    const rangeRun = new Map(); // key: substanceId::unitFamily
    const invRun = new Map();
    const resetRun = new Map(); // for chart primary running series per reset mode

    const rows = [];
    logs.forEach(log => {
        const sid = typeof getUseSubstanceId === 'function' ? getUseSubstanceId(log, data) : log.substanceId;
        const measure = getRunningTotalsSessionMeasure(log, data);
        const seriesKey = `${sid}::${measure.unitFamily}::${measure.accumulateUnit}`;
        const invId = typeof getLogPurchaseId === 'function'
            ? getLogPurchaseId(log)
            : (log.purchaseId || log.linkedPurchaseId || log.inventoryId || '');
        const dateStr = log.date;
        const dayKey = `${seriesKey}::${dateStr}`;
        const weekKey = `${seriesKey}::${runningTotalsWeekKey(dateStr, data)}`;
        const monthKey = `${seriesKey}::${runningTotalsMonthKey(dateStr)}`;
        const amt = rtNum(measure.accumulateAmount, 0);
        const secondary = measure.secondaryAccumulate != null ? rtNum(measure.secondaryAccumulate, 0) : null;

        dayRun.set(dayKey, (dayRun.get(dayKey) || 0) + amt);
        weekRun.set(weekKey, (weekRun.get(weekKey) || 0) + amt);
        monthRun.set(monthKey, (monthRun.get(monthKey) || 0) + amt);
        rangeRun.set(seriesKey, (rangeRun.get(seriesKey) || 0) + amt);
        if (invId) {
            const ik = `${seriesKey}::${invId}`;
            invRun.set(ik, (invRun.get(ik) || 0) + amt);
        }

        const resetKey = `${seriesKey}::${getRunningTotalsResetKey(dateStr, f.resetMode, invId, data)}`;
        resetRun.set(resetKey, (resetRun.get(resetKey) || 0) + amt);

        let secondaryDay = null;
        let secondaryWeek = null;
        let secondaryMonth = null;
        let secondaryRange = null;
        if (secondary != null && measure.secondaryUnit) {
            const sKey = `${seriesKey}::sec`;
            const sd = `${sKey}::${dateStr}`;
            const sw = `${sKey}::${runningTotalsWeekKey(dateStr, data)}`;
            const sm = `${sKey}::${runningTotalsMonthKey(dateStr)}`;
            dayRun.set(sd, (dayRun.get(sd) || 0) + secondary);
            weekRun.set(sw, (weekRun.get(sw) || 0) + secondary);
            monthRun.set(sm, (monthRun.get(sm) || 0) + secondary);
            rangeRun.set(sKey, (rangeRun.get(sKey) || 0) + secondary);
            secondaryDay = dayRun.get(sd);
            secondaryWeek = weekRun.get(sw);
            secondaryMonth = monthRun.get(sm);
            secondaryRange = rangeRun.get(sKey);
        }

        const purchase = invId && typeof findPurchase === 'function' ? findPurchase(invId, data) : null;
        const invLabel = purchase
            ? (typeof formatWeedPurchaseDisplayLine === 'function' && typeof isWeedPurchase === 'function' && isWeedPurchase(purchase, data)
                ? formatWeedPurchaseDisplayLine(purchase)
                : `${purchase.date || ''} · ${rtNum(purchase.remainingAmount, 0)} left`)
            : (invId ? String(invId) : '—');

        rows.push({
            id: log.id,
            substanceId: sid,
            substanceName: typeof getSubstanceDisplayName === 'function' ? getSubstanceDisplayName(sid, data) : sid,
            date: dateStr,
            time: log.startTime || log.time || '',
            datetimeMs: typeof getLogDatetimeMs === 'function' ? getLogDatetimeMs(log) : 0,
            sessionAmount: rtRound(measure.sessionAmount, 4),
            sessionUnit: measure.sessionUnit,
            productType: measure.productType,
            productTypeLabel: measure.productType
                ? (typeof getWeedProductTypeLabel === 'function' ? getWeedProductTypeLabel(measure.productType) : measure.productType)
                : '—',
            accumulateAmount: rtRound(amt, 4),
            accumulateUnit: measure.accumulateUnit,
            unitFamily: measure.unitFamily,
            runningDaily: rtRound(dayRun.get(dayKey), 4),
            runningWeekly: rtRound(weekRun.get(weekKey), 4),
            runningMonthly: rtRound(monthRun.get(monthKey), 4),
            runningRange: rtRound(rangeRun.get(seriesKey), 4),
            runningInventory: invId ? rtRound(invRun.get(`${seriesKey}::${invId}`), 4) : null,
            runningReset: rtRound(resetRun.get(resetKey), 4),
            secondaryUnit: measure.secondaryUnit || '',
            secondarySession: secondary != null ? rtRound(secondary, 4) : null,
            secondaryDaily: secondaryDay != null ? rtRound(secondaryDay, 4) : null,
            secondaryWeekly: secondaryWeek != null ? rtRound(secondaryWeek, 4) : null,
            secondaryMonthly: secondaryMonth != null ? rtRound(secondaryMonth, 4) : null,
            secondaryRange: secondaryRange != null ? rtRound(secondaryRange, 4) : null,
            inventoryId: invId || '',
            inventoryLabel: invLabel,
            notes: log.notes || '',
            transactionType: typeof getLogTransactionType === 'function' ? getLogTransactionType(log) : log.transactionType,
            seriesKey
        });
    });

    return { rows, bounds, filters: f };
}

function groupRunningTotalsRows(rows, groupBy) {
    if (!groupBy || groupBy === 'session') return rows;
    const map = new Map();
    rows.forEach(row => {
        let key;
        if (groupBy === 'day') key = `${row.seriesKey}::${row.date}`;
        else if (groupBy === 'week') key = `${row.seriesKey}::${runningTotalsWeekKey(row.date)}`; // week key uses default appData week-start
        else if (groupBy === 'month') key = `${row.seriesKey}::${runningTotalsMonthKey(row.date)}`;
        else if (groupBy === 'inventory') key = `${row.seriesKey}::${row.inventoryId || 'unlinked'}`;
        else key = row.id;
        if (!map.has(key)) {
            map.set(key, {
                ...row,
                id: key,
                time: groupBy === 'session' ? row.time : '',
                sessionAmount: 0,
                accumulateAmount: 0,
                secondarySession: row.secondarySession != null ? 0 : null,
                notes: '',
                grouped: true,
                groupCount: 0
            });
        }
        const g = map.get(key);
        g.sessionAmount = rtRound((g.sessionAmount || 0) + (row.sessionAmount || 0), 4);
        g.accumulateAmount = rtRound((g.accumulateAmount || 0) + (row.accumulateAmount || 0), 4);
        if (g.secondarySession != null && row.secondarySession != null) {
            g.secondarySession = rtRound(g.secondarySession + row.secondarySession, 4);
        }
        g.runningDaily = row.runningDaily;
        g.runningWeekly = row.runningWeekly;
        g.runningMonthly = row.runningMonthly;
        g.runningRange = row.runningRange;
        g.runningInventory = row.runningInventory;
        g.runningReset = row.runningReset;
        g.secondaryDaily = row.secondaryDaily;
        g.secondaryWeekly = row.secondaryWeekly;
        g.secondaryMonthly = row.secondaryMonthly;
        g.secondaryRange = row.secondaryRange;
        g.groupCount += 1;
        g.datetimeMs = Math.max(g.datetimeMs || 0, row.datetimeMs || 0);
        if (row.date > g.date) g.date = row.date;
    });
    return [...map.values()].sort((a, b) => (a.datetimeMs || 0) - (b.datetimeMs || 0));
}

function buildRunningTotalsDataset(data = appData, options = {}) {
    const filters = resolveRunningTotalsFilters(options, data);
    // Allow explicit test overrides to win over Insights shared state
    if (options.filters) {
        Object.assign(filters, options.filters);
    }
    const built = buildRunningTotalsRows(filters, data);
    let rows = groupRunningTotalsRows(built.rows, filters.groupBy);
    const bySubstance = new Map();
    rows.forEach(row => {
        if (!bySubstance.has(row.substanceId)) bySubstance.set(row.substanceId, []);
        bySubstance.get(row.substanceId).push(row);
    });

    // Display order
    const displayRows = filters.newestFirst === false
        ? rows
        : [...rows].sort((a, b) => (b.datetimeMs || 0) - (a.datetimeMs || 0));

    const series = [...bySubstance.entries()].map(([sid, substanceRows]) => {
        const chrono = [...substanceRows].sort((a, b) => (a.datetimeMs || 0) - (b.datetimeMs || 0));
        const target = getRunningTotalsTarget(sid, data);
        return {
            substanceId: sid,
            label: substanceRows[0]?.substanceName || sid,
            unit: substanceRows[0]?.accumulateUnit || '',
            unitFamily: substanceRows[0]?.unitFamily || 'auto',
            points: chrono.map(r => ({
                key: r.date + (r.time ? ` ${r.time}` : ''),
                date: r.date,
                session: r.sessionAmount,
                running: r.runningReset,
                unit: r.accumulateUnit
            })),
            target
        };
    });

    const incompatible = series.length > 1 && new Set(series.map(s => s.unitFamily)).size > 1;

    return {
        generatedAt: new Date().toISOString(),
        filters,
        bounds: built.bounds,
        rows: displayRows,
        calcRows: rows,
        series,
        incompatible,
        partial: !!built.bounds?.incomplete,
        empty: displayRows.length === 0,
        state: displayRows.length ? 'ok' : 'empty'
    };
}

function formatRunningTotalsAmount(value, unit) {
    if (value == null || !Number.isFinite(value)) return '—';
    const formatted = typeof formatAmount === 'function' ? formatAmount(value) : String(value);
    return unit ? `${formatted} ${unit}` : formatted;
}

function renderRunningTotalsChartSvg(seriesList, options = {}) {
    const series = seriesList?.[0];
    if (!series?.points?.length) return '<p class="rt-empty">No chart data.</p>';
    const width = options.width || 640;
    const height = options.height || 220;
    const pad = { t: 16, r: 12, b: 36, l: 44 };
    const points = series.points;
    const yMax = Math.max(
        ...points.map(p => p.session || 0),
        ...points.map(p => p.running || 0),
        series.target?.value || 0,
        1
    );
    const xScale = i => pad.l + (points.length <= 1 ? (width - pad.l - pad.r) / 2 : (i / (points.length - 1)) * (width - pad.l - pad.r));
    const yScale = v => height - pad.b - (v / yMax) * (height - pad.t - pad.b);
    const barW = Math.max(4, Math.min(18, (width - pad.l - pad.r) / Math.max(points.length, 1) * 0.55));
    const bars = points.map((p, i) => {
        const x = xScale(i) - barW / 2;
        const y = yScale(p.session || 0);
        const h = Math.max(0, height - pad.b - y);
        return `<rect class="rt-bar" x="${x}" y="${y}" width="${barW}" height="${h}" rx="2"><title>${rtEsc(p.key)}: ${rtEsc(p.session)} ${rtEsc(series.unit)}</title></rect>`;
    }).join('');
    const line = points.map((p, i) => `${i === 0 ? 'M' : 'L'} ${xScale(i)} ${yScale(p.running || 0)}`).join(' ');
    const targetLine = options.showTarget && series.target?.value != null
        ? `<line class="rt-target" x1="${pad.l}" y1="${yScale(series.target.value)}" x2="${width - pad.r}" y2="${yScale(series.target.value)}" />
           <text class="rt-axis-label" x="${width - pad.r}" y="${yScale(series.target.value) - 4}" text-anchor="end">${rtEsc(series.target.label || 'Target')}</text>`
        : '';
    return `<svg class="rt-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="Running totals chart">
        <line class="rt-axis" x1="${pad.l}" y1="${height - pad.b}" x2="${width - pad.r}" y2="${height - pad.b}" />
        <line class="rt-axis" x1="${pad.l}" y1="${pad.t}" x2="${pad.l}" y2="${height - pad.b}" />
        ${bars}
        <path class="rt-line" d="${line}" fill="none" />
        ${targetLine}
        <text class="rt-axis-label" x="${pad.l}" y="${pad.t + 4}">${rtEsc(yMax)} ${rtEsc(series.unit)}</text>
    </svg>
    <p class="settings-hint">Bars = session amount · Line = running total (${rtEsc(options.resetMode || 'daily')} reset)${series.target ? ' · Dashed = target' : ''}</p>`;
}

function renderRunningTotalsTableHtml(dataset) {
    if (dataset.empty) {
        return '<div class="rt-empty" role="status">No personal-use sessions in this range.</div>';
    }
    const showCbd = dataset.filters.showCbdRunning !== false;
    const rows = dataset.rows.map(row => {
        const cbdCell = showCbd && row.secondaryUnit === 'mg CBD' && row.secondaryRange != null
            ? `<td>${formatRunningTotalsAmount(row.secondaryRange, 'mg CBD')}</td>`
            : (showCbd ? '<td>—</td>' : '');
        const gramsCell = row.secondaryUnit === 'g' && row.secondarySession != null
            ? `<td>${formatRunningTotalsAmount(row.secondarySession, 'g')}</td>`
            : '<td>—</td>';
        return `<tr>
            <td>${rtEsc(typeof formatDate === 'function' ? formatDate(row.date) : row.date)}</td>
            <td>${rtEsc(row.time || '—')}</td>
            <td>${formatRunningTotalsAmount(row.sessionAmount, row.sessionUnit)}</td>
            <td>${rtEsc(row.productTypeLabel || '—')}</td>
            <td>${formatRunningTotalsAmount(row.runningDaily, row.accumulateUnit)}</td>
            <td>${formatRunningTotalsAmount(row.runningWeekly, row.accumulateUnit)}</td>
            <td>${formatRunningTotalsAmount(row.runningMonthly, row.accumulateUnit)}</td>
            <td>${formatRunningTotalsAmount(row.runningRange, row.accumulateUnit)}</td>
            <td>${row.runningInventory != null ? formatRunningTotalsAmount(row.runningInventory, row.accumulateUnit) : '—'}</td>
            <td>${rtEsc(row.inventoryLabel || '—')}</td>
            <td>${rtEsc(row.notes || '')}</td>
            ${showCbd ? cbdCell : ''}
            ${gramsCell}
        </tr>`;
    }).join('');

    return `<div class="table-scroll rt-table-wrap"><table class="sheet-table rt-table">
        <thead><tr>
            <th>Date</th><th>Time</th><th>Session amount</th><th>Product type</th>
            <th>Running daily</th><th>Running weekly</th><th>Running monthly</th>
            <th>Running selected range</th><th>Running inventory</th>
            <th>Linked inventory</th><th>Notes</th>
            ${showCbd ? '<th>Running CBD</th>' : ''}
            <th>Session grams</th>
        </tr></thead>
        <tbody>${rows}</tbody>
    </table></div>`;
}

function renderRunningTotalsView() {
    const root = typeof document !== 'undefined' ? document.getElementById('running-totals-root') : null;
    if (!root) return;
    root.innerHTML = '<div class="rt-loading" role="status">Loading running totals…</div>';
    try {
        if (typeof syncSectionFiltersFromInsights === 'function') syncSectionFiltersFromInsights(appData);
        const prefs = ensureRunningTotalsPrefs(appData);
        const dataset = buildRunningTotalsDataset(appData);
        const f = dataset.filters;
        const resetOptions = RUNNING_TOTALS_RESET_MODES.map(m =>
            `<option value="${m}"${f.resetMode === m ? ' selected' : ''}>${m.replace(/-/g, ' ')}</option>`
        ).join('');
        const groupOptions = RUNNING_TOTALS_GROUP_BY.map(m =>
            `<option value="${m}"${f.groupBy === m ? ' selected' : ''}>${m}</option>`
        ).join('');
        const substanceLabel = rtIsAll(f.substanceId)
            ? 'All Substances (separate series)'
            : (typeof getSubstanceDisplayName === 'function'
                ? getSubstanceDisplayName(f.substanceId, appData)
                : f.substanceId);
        const productLabel = f.productType
            ? (typeof getWeedProductTypeLabel === 'function' ? getWeedProductTypeLabel(f.productType) : f.productType)
            : 'All product types';

        const charts = dataset.incompatible
            ? dataset.series.map(s => `<section class="rt-chart-block"><h4>${rtEsc(s.label)} (${rtEsc(s.unit)})</h4>${renderRunningTotalsChartSvg([s], { showTarget: f.showTargetLine, resetMode: f.resetMode })}</section>`).join('')
            : renderRunningTotalsChartSvg(dataset.series, { showTarget: f.showTargetLine, resetMode: f.resetMode });

        const tables = dataset.incompatible
            ? dataset.series.map(s => {
                const subset = { ...dataset, rows: dataset.rows.filter(r => r.substanceId === s.substanceId), empty: !dataset.rows.some(r => r.substanceId === s.substanceId) };
                return `<section class="rt-table-block"><h4>${rtEsc(s.label)}</h4>${renderRunningTotalsTableHtml(subset)}</section>`;
            }).join('')
            : renderRunningTotalsTableHtml(dataset);

        root.innerHTML = `
            <div class="rt-dashboard">
                <p class="settings-hint rt-inherits">
                    Using Insights filters: <strong>${rtEsc(substanceLabel)}</strong>
                    · ${rtEsc(productLabel)}
                    · ${rtEsc(f.dateRangePreset || 'range')}
                    ${f.transactionType ? ` · ${rtEsc(f.transactionType)}` : ''}
                </p>
                <div class="rt-filters">
                    <label>Reset mode
                        <select id="rt-filter-reset" onchange="onRunningTotalsFilterChange()">${resetOptions}</select>
                    </label>
                    <label>Group by
                        <select id="rt-filter-group" onchange="onRunningTotalsFilterChange()">${groupOptions}</select>
                    </label>
                    <label class="rt-check"><input type="checkbox" id="rt-filter-personal" ${f.personalUseOnly ? 'checked' : ''} onchange="onRunningTotalsFilterChange()"> Personal use only</label>
                    <label class="rt-check"><input type="checkbox" id="rt-filter-newest" ${f.newestFirst !== false ? 'checked' : ''} onchange="onRunningTotalsFilterChange()"> Newest first</label>
                    <label class="rt-check"><input type="checkbox" id="rt-filter-target" ${f.showTargetLine ? 'checked' : ''} onchange="onRunningTotalsFilterChange()"> Show target / taper line</label>
                </div>
                <p class="settings-hint">
                    ${dataset.bounds?.startDate || '…'} → ${dataset.bounds?.endDate || '…'}
                    ${dataset.partial ? ' · Partial period' : ''}
                    ${dataset.incompatible ? ' · All Substances: separate series (units not combined)' : ''}
                    · Calculated chronologically · Daily resets at local midnight · Weekly uses app week-start
                </p>
                <div class="rt-actions">
                    <button type="button" class="secondary-btn btn-sm" onclick="exportRunningTotalsCsv()">Export CSV</button>
                </div>
                <div class="rt-chart">${charts}</div>
                ${tables}
            </div>`;
    } catch (err) {
        console.error('[running-totals] render failed', err);
        root.innerHTML = `<div class="rt-error" role="alert"><p>Could not load running totals.</p><p class="settings-hint">${rtEsc(err?.message || String(err))}</p><button type="button" class="secondary-btn btn-sm" onclick="renderRunningTotalsView()">Retry</button></div>`;
    }
}

function onRunningTotalsFilterChange() {
    const g = id => (typeof document !== 'undefined' ? document.getElementById(id) : null);
    // Only local display prefs — substance/date/product/tx come from shared Insights filters
    persistRunningTotalsPrefs({
        filters: {
            resetMode: g('rt-filter-reset')?.value || 'daily',
            groupBy: g('rt-filter-group')?.value || 'session',
            personalUseOnly: !!g('rt-filter-personal')?.checked,
            newestFirst: !!g('rt-filter-newest')?.checked,
            showTargetLine: !!g('rt-filter-target')?.checked
        }
    });
    renderRunningTotalsView();
}

function exportRunningTotalsCsv() {
    if (typeof syncSectionFiltersFromInsights === 'function') syncSectionFiltersFromInsights(appData);
    const dataset = buildRunningTotalsDataset(appData);
    const headers = [
        'date', 'time', 'substance', 'productType', 'sessionAmount', 'sessionUnit',
        'runningDaily', 'runningWeekly', 'runningMonthly', 'runningRange', 'runningInventory',
        'accumulateUnit', 'inventory', 'notes', 'secondarySession', 'secondaryUnit'
    ];
    const lines = [headers.join(',')];
    dataset.rows.forEach(row => {
        const vals = [
            row.date, row.time, row.substanceName, row.productType,
            row.sessionAmount, row.sessionUnit,
            row.runningDaily, row.runningWeekly, row.runningMonthly, row.runningRange,
            row.runningInventory ?? '',
            row.accumulateUnit, row.inventoryLabel, row.notes,
            row.secondarySession ?? '', row.secondaryUnit || ''
        ].map(v => {
            const s = String(v ?? '');
            return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
        });
        lines.push(vals.join(','));
    });
    const csv = lines.join('\n');
    if (typeof downloadTextFile === 'function') {
        downloadTextFile(`running-totals-${rtToday()}.csv`, csv, 'text/csv');
    }
    return csv;
}


// ——— Average Use Analytics (Insights → Use Analytics) ———

const AVERAGE_USE_SETTINGS_KEY = 'averageUseAnalytics';
const AVERAGE_USE_MONTH_DAYS = 365.25 / 12;

function getDefaultAverageUseAnalyticsPrefs() {
    return {
        denominatorMode: 'active'
    };
}

function ensureAverageUseAnalyticsPrefs(data = appData) {
    if (!data || typeof data !== 'object') return getDefaultAverageUseAnalyticsPrefs();
    if (!data.settings || typeof data.settings !== 'object') data.settings = {};
    if (!data.settings[AVERAGE_USE_SETTINGS_KEY] || typeof data.settings[AVERAGE_USE_SETTINGS_KEY] !== 'object') {
        data.settings[AVERAGE_USE_SETTINGS_KEY] = getDefaultAverageUseAnalyticsPrefs();
    }
    const prefs = data.settings[AVERAGE_USE_SETTINGS_KEY];
    if (prefs.denominatorMode !== 'full' && prefs.denominatorMode !== 'active') prefs.denominatorMode = 'active';
    return prefs;
}

function persistAverageUseAnalyticsPrefs(patch = {}, data = appData) {
    const prefs = ensureAverageUseAnalyticsPrefs(data);
    Object.assign(prefs, patch || {});
    if (prefs.denominatorMode !== 'full' && prefs.denominatorMode !== 'active') prefs.denominatorMode = 'active';
    if (typeof saveData === 'function') saveData(data);
    return prefs;
}

function resolveAverageUseFilters(options = {}, data = appData) {
    const inf = typeof getInsightsFilters === 'function' ? getInsightsFilters(data) : {};
    const prefs = ensureAverageUseAnalyticsPrefs(data);
    return {
        substanceId: inf.substanceId || 'all',
        productType: inf.productType || '',
        dateRangePreset: inf.dateRangePreset || 'last-7',
        customStart: inf.customStart || '',
        customEnd: inf.customEnd || '',
        transactionType: inf.transactionType || '',
        denominatorMode: prefs.denominatorMode || 'active',
        ...(options.filters || {})
    };
}

function averageUseQualifiesLog(log, filters = {}, data = appData) {
    if (!log) return false;
    if (log.isDistributedChild) return false;
    if (typeof isAlcoholMultiDayChildLog === 'function' && isAlcoholMultiDayChildLog(log)) return false;
    if (log.parentPercentLogId != null && log.isEstimatedDailyUse) return false;
    if (typeof isGiftGivenLog === 'function' && isGiftGivenLog(log)) return false;
    if (typeof isGiftReceivedLog === 'function' && isGiftReceivedLog(log)) return false;
    if (typeof isInventoryAdjustmentLog === 'function' && isInventoryAdjustmentLog(log)) return false;

    const tx = typeof getLogTransactionType === 'function' ? getLogTransactionType(log) : (log.transactionType || 'use');
    if (filters.transactionType && tx !== filters.transactionType) return false;
    if (tx === 'shared_use') {
        const personal = typeof getLogPersonalAmount === 'function' ? getLogPersonalAmount(log) : parseFloat(log.personalAmount);
        return Number.isFinite(personal) && personal > 0;
    }
    return tx === 'use';
}

function getAverageUseBounds(filters = {}, data = appData) {
    const range = {
        preset: filters.dateRangePreset || 'last-7',
        startDate: filters.customStart || null,
        endDate: filters.customEnd || null
    };
    if (range.preset !== 'custom') {
        const previousPreset = statsDateRangePreset;
        const previousStart = statsCustomStartDate;
        const previousEnd = statsCustomEndDate;
        try {
            statsDateRangePreset = range.preset;
            statsCustomStartDate = filters.customStart || '';
            statsCustomEndDate = filters.customEnd || '';
            const resolved = getStatsDateRange();
            range.startDate = resolved.startDate;
            range.endDate = resolved.endDate;
            range.preset = resolved.preset || range.preset;
        } finally {
            statsDateRangePreset = previousPreset;
            statsCustomStartDate = previousStart;
            statsCustomEndDate = previousEnd;
        }
    } else if (filters.customStart || filters.customEnd) {
        const today = toDateStr(getStatsReferenceDate());
        const a = filters.customStart || filters.customEnd || today;
        const b = filters.customEnd || filters.customStart || today;
        range.startDate = a <= b ? a : b;
        range.endDate = a <= b ? b : a;
    }

    const candidateLogs = (data.logs || []).filter(log => averageUseQualifiesLog(log, { ...filters, transactionType: '' }, data));
    const activeLogs = rtIsAll(filters.substanceId)
        ? candidateLogs
        : candidateLogs.filter(log => logMatchesSubstance(log, filters.substanceId, data));
    const bounds = resolveStatsRangeBounds(range.startDate, range.endDate, activeLogs);
    return { ...bounds, preset: range.preset || filters.dateRangePreset || 'last-7' };
}

function cloneAverageUseLogForMeasure(log, data = appData) {
    const personal = typeof getLogPersonalAmount === 'function' ? getLogPersonalAmount(log) : (parseFloat(log.amount) || 0);
    return {
        ...log,
        amount: personal,
        personalAmount: personal,
        totalAmount: personal,
        sharedAmount: 0,
        transactionType: 'use'
    };
}

function getAverageUseMeasure(log, data = appData) {
    const normalized = cloneAverageUseLogForMeasure(log, data);
    const measure = getRunningTotalsSessionMeasure(normalized, data);
    const amount = rtNum(measure.accumulateAmount, 0);
    return {
        amount,
        unit: measure.accumulateUnit || measure.sessionUnit || '',
        unitFamily: measure.unitFamily || 'auto',
        productType: measure.productType || ''
    };
}

function averageUseMonthKey(dateStr) {
    return String(dateStr || '').slice(0, 7);
}

function averageUseSafeDivide(total, denominator) {
    return denominator > 0 ? total / denominator : null;
}

function buildAverageUseAnalyticsRows(data = appData, options = {}) {
    const filters = resolveAverageUseFilters(options, data);
    const bounds = options.bounds || getAverageUseBounds(filters, data);
    const dayCount = countDaysInRange(bounds.startDate, bounds.endDate);
    const fullWeeks = dayCount / 7;
    const fullMonths = dayCount / AVERAGE_USE_MONTH_DAYS;
    const rowsByKey = new Map();

    (data.logs || []).forEach(log => {
        if (!averageUseQualifiesLog(log, filters, data)) return;
        const date = log.date || '';
        if (!date) return;
        if (bounds.startDate && date < bounds.startDate) return;
        if (bounds.endDate && date > bounds.endDate) return;
        if (!rtIsAll(filters.substanceId) && !logMatchesSubstance(log, filters.substanceId, data)) return;
        if (filters.productType && getRunningTotalsProductType(log, data) !== filters.productType) return;

        const substanceId = typeof getUseSubstanceId === 'function' ? getUseSubstanceId(log, data) : log.substanceId;
        const measure = getAverageUseMeasure(log, data);
        if (!(measure.amount > 0)) return;
        const key = `${substanceId}::${measure.unitFamily}::${measure.unit}`;
        if (!rowsByKey.has(key)) {
            rowsByKey.set(key, {
                key,
                substanceId,
                substanceName: typeof getSubstanceDisplayName === 'function' ? getSubstanceDisplayName(substanceId, data) : substanceId,
                unit: measure.unit,
                unitFamily: measure.unitFamily,
                totalUse: 0,
                useDaySet: new Set(),
                weekSet: new Set(),
                monthSet: new Set(),
                sessions: 0
            });
        }
        const row = rowsByKey.get(key);
        row.totalUse += measure.amount;
        row.useDaySet.add(date);
        row.weekSet.add(runningTotalsWeekKey(date, data));
        row.monthSet.add(averageUseMonthKey(date));
        row.sessions += 1;
    });

    const sameSubstanceCounts = new Map();
    rowsByKey.forEach(row => {
        sameSubstanceCounts.set(row.substanceId, (sameSubstanceCounts.get(row.substanceId) || 0) + 1);
    });

    return [...rowsByKey.values()]
        .map(row => {
            const useDays = row.useDaySet.size;
            const activeWeeks = row.weekSet.size;
            const activeMonths = row.monthSet.size;
            const weekDenominator = filters.denominatorMode === 'full' ? fullWeeks : activeWeeks;
            const monthDenominator = filters.denominatorMode === 'full' ? fullMonths : activeMonths;
            const period = `${formatDate(bounds.startDate)} – ${formatDate(bounds.endDate)}`;
            const hasSplitUnits = (sameSubstanceCounts.get(row.substanceId) || 0) > 1;
            return {
                key: row.key,
                substanceId: row.substanceId,
                substanceName: row.substanceName,
                period,
                periodLabel: rtIsAll(filters.substanceId) || hasSplitUnits
                    ? `${row.substanceName}${hasSplitUnits ? ` (${row.unit})` : ''} · ${period}`
                    : period,
                unit: row.unit,
                unitFamily: row.unitFamily,
                totalUse: rtRound(row.totalUse, 6),
                useDays,
                calendarDays: dayCount,
                sessions: row.sessions,
                avgActiveDay: averageUseSafeDivide(row.totalUse, useDays),
                avgCalendarDay: averageUseSafeDivide(row.totalUse, dayCount),
                avgWeek: averageUseSafeDivide(row.totalUse, weekDenominator),
                avgMonth: averageUseSafeDivide(row.totalUse, monthDenominator),
                denominators: {
                    activeDay: useDays,
                    calendarDay: dayCount,
                    week: weekDenominator,
                    month: monthDenominator,
                    weekMode: filters.denominatorMode,
                    monthMode: filters.denominatorMode,
                    fullWeeks,
                    fullMonths,
                    activeWeeks,
                    activeMonths
                }
            };
        })
        .sort((a, b) => a.substanceName.localeCompare(b.substanceName) || a.unit.localeCompare(b.unit));
}

function buildAverageUseAnalyticsDataset(data = appData, options = {}) {
    const filters = resolveAverageUseFilters(options, data);
    if (options.filters) Object.assign(filters, options.filters);
    const bounds = getAverageUseBounds(filters, data);
    const rows = buildAverageUseAnalyticsRows(data, { filters, bounds });
    return {
        generatedAt: new Date().toISOString(),
        filters,
        bounds,
        rows,
        empty: rows.length === 0
    };
}

function formatAverageUseAmount(value, unit) {
    if (value == null || !Number.isFinite(value)) return '—';
    const formatted = typeof formatAmount === 'function' ? formatAmount(value) : String(rtRound(value, 3));
    return unit ? `${formatted} ${unit}` : formatted;
}

function formatAverageUseDenominator(value, label) {
    if (value == null || !Number.isFinite(value)) return `${label}: —`;
    const formatted = Number.isInteger(value) ? String(value) : formatAmount(value, 2);
    return `${label}: ${formatted}`;
}

function evaluateAverageUseCcr(row, metricValue) {
    if (typeof evaluateConditionalColorRules !== 'function') return null;
    return evaluateConditionalColorRules({
        substanceId: row.substanceId,
        section: 'insights',
        metric: 'useAmount',
        visualTarget: 'value',
        value: metricValue
    });
}

function renderAverageUseValue(row, metricKey) {
    const unit = metricKey === 'sessions' || metricKey === 'useDays' ? '' : row.unit;
    const raw = row[metricKey];
    const text = metricKey === 'sessions' || metricKey === 'useDays'
        ? String(raw ?? 0)
        : formatAverageUseAmount(raw, unit);
    const denom = row.denominators || {};
    let title = text;
    if (metricKey === 'avgActiveDay') title = formatAverageUseDenominator(denom.activeDay, 'Denominator active days');
    if (metricKey === 'avgCalendarDay') title = formatAverageUseDenominator(denom.calendarDay, 'Denominator calendar days');
    if (metricKey === 'avgWeek') title = `${formatAverageUseDenominator(denom.week, 'Denominator weeks')} (${denom.weekMode === 'full' ? 'full selected range' : 'active periods only'})`;
    if (metricKey === 'avgMonth') title = `${formatAverageUseDenominator(denom.month, 'Denominator months')} (${denom.monthMode === 'full' ? 'full selected range' : 'active periods only'})`;
    const ccr = metricKey === 'sessions' || metricKey === 'useDays' ? null : evaluateAverageUseCcr(row, raw);
    const html = ccr?.matched?.length
        ? wrapWithConditionalColor(escapeHtml(text), ccr, { keepLabel: false })
        : escapeHtml(text);
    return { html, title };
}

function renderAverageUsePreviousComparison(dataset, row, metricKey) {
    if (typeof isPreviousPeriodCompareEnabled !== 'function' || !isPreviousPeriodCompareEnabled(appData)) return '';
    if (!dataset.bounds?.startDate || !dataset.bounds?.endDate) return '';
    const prevBounds = resolvePreviousPeriodBounds(dataset.bounds, getPreviousPeriodCompareMode(appData));
    if (!prevBounds?.valid) return '';
    const previous = buildAverageUseAnalyticsDataset(appData, {
        filters: {
            ...dataset.filters,
            substanceId: row.substanceId,
            dateRangePreset: 'custom',
            customStart: prevBounds.startDate,
            customEnd: prevBounds.endDate
        }
    });
    const prevRow = previous.rows.find(r => r.unitFamily === row.unitFamily && r.unit === row.unit);
    const currentValue = row[metricKey];
    const previousValue = prevRow
        ? (metricKey === 'avgSessionAmount' ? averageUseSafeDivide(prevRow.totalUse, prevRow.sessions) : prevRow[metricKey])
        : null;
    const cmp = buildMetricPeriodComparison({
        current: currentValue,
        previous: previousValue,
        metricKind: 'use',
        unit: row.unit,
        currentLabel: formatAverageUseAmount(currentValue, row.unit),
        previousLabel: previousValue == null ? '—' : formatAverageUseAmount(previousValue, row.unit),
        currentPeriodLabel: 'Current',
        previousPeriodLabel: prevBounds.label || 'Previous',
        currentBounds: dataset.bounds,
        previousBounds: prevBounds
    });
    return renderMetricPeriodComparison(cmp, { data: appData, compact: true });
}

function renderAverageUseCards(dataset) {
    if (!dataset.rows.length) return '<p class="empty-hint">No qualifying personal use in this range.</p>';
    return dataset.rows.map(row => {
        const title = rtIsAll(dataset.filters.substanceId) ? `<h4>${escapeHtml(row.substanceName)}</h4>` : '';
        const cards = [
            ['Average per active day', 'avgActiveDay'],
            ['Average per calendar day', 'avgCalendarDay'],
            ['Average per week', 'avgWeek'],
            ['Average per month', 'avgMonth'],
            ['Average session amount', 'avgSessionAmount'],
            ['Total use', 'totalUse'],
            ['Number of use days', 'useDays'],
            ['Number of sessions', 'sessions']
        ].map(([label, key]) => {
            const metricKey = key === 'avgSessionAmount' ? 'avgSessionAmount' : key;
            const value = key === 'avgSessionAmount'
                ? averageUseSafeDivide(row.totalUse, row.sessions)
                : row[metricKey];
            const display = key === 'useDays' || key === 'sessions'
                ? String(value ?? 0)
                : formatAverageUseAmount(value, row.unit);
            const footerMetric = key === 'useDays' || key === 'sessions' ? null : (key === 'avgSessionAmount' ? 'avgSessionAmount' : key);
            const comparisonRow = footerMetric === 'avgSessionAmount' ? { ...row, avgSessionAmount: value } : row;
            const footer = footerMetric ? renderAverageUsePreviousComparison(dataset, comparisonRow, footerMetric) : '';
            const ccr = key === 'useDays' || key === 'sessions' ? null : evaluateAverageUseCcr(row, value);
            const denom = row.denominators || {};
            const title = key === 'avgActiveDay'
                ? formatAverageUseDenominator(denom.activeDay, 'Denominator active days')
                : key === 'avgCalendarDay'
                    ? formatAverageUseDenominator(denom.calendarDay, 'Denominator calendar days')
                    : key === 'avgWeek'
                        ? `${formatAverageUseDenominator(denom.week, 'Denominator weeks')} (${denom.weekMode === 'full' ? 'full selected range' : 'active periods only'})`
                        : key === 'avgMonth'
                            ? `${formatAverageUseDenominator(denom.month, 'Denominator months')} (${denom.monthMode === 'full' ? 'full selected range' : 'active periods only'})`
                            : key === 'avgSessionAmount'
                                ? formatAverageUseDenominator(row.sessions, 'Denominator sessions')
                                : '';
            return renderSheetMetricCard(label, display, null, {
                substanceId: row.substanceId,
                section: 'insights',
                ccrResult: ccr,
                footerHtml: footer,
                title
            });
        }).join('');
        return `<section class="average-use-card-group">${title}<div class="sheet-summary-grid">${cards}</div></section>`;
    }).join('');
}

function renderAverageUseSummaryTable(dataset) {
    const rows = dataset.rows.map(row => ({
        ...row,
        avgSessionAmount: averageUseSafeDivide(row.totalUse, row.sessions)
    }));
    return renderConfigurableSheetTable('averageUse', rows, (colId, row) => {
        switch (colId) {
            case 'period': return row.periodLabel || row.period;
            case 'totalUse': return renderAverageUseValue(row, 'totalUse');
            case 'useDays': return renderAverageUseValue(row, 'useDays');
            case 'sessions': return renderAverageUseValue(row, 'sessions');
            case 'avgActiveDay': return renderAverageUseValue(row, 'avgActiveDay');
            case 'avgCalendarDay': return renderAverageUseValue(row, 'avgCalendarDay');
            case 'avgWeek': return renderAverageUseValue(row, 'avgWeek');
            case 'avgMonth': return renderAverageUseValue(row, 'avgMonth');
            default: return '—';
        }
    });
}

function renderAverageUseAnalyticsView() {
    const root = typeof document !== 'undefined' ? document.getElementById('average-use-analytics-root') : null;
    if (!root) return;
    const mode = ensureAverageUseAnalyticsPrefs(appData).denominatorMode;
    const modeSelect = document.getElementById('average-use-denominator-mode');
    if (modeSelect) modeSelect.value = mode;
    const dataset = buildAverageUseAnalyticsDataset(appData);
    const rangeLabel = getStatsRangeLabel(dataset.bounds.preset || dataset.filters.dateRangePreset, dataset.bounds.startDate, dataset.bounds.endDate);
    root.innerHTML = `
        <p class="settings-hint">Using shared Insights filters · ${escapeHtml(rangeLabel)} · ${dataset.filters.denominatorMode === 'full' ? 'Full selected range' : 'Active periods only'} for weekly and monthly averages.</p>
        ${renderAverageUseCards(dataset)}
        <h4>Summary table</h4>
        ${renderAverageUseSummaryTable(dataset)}
    `;
}

function onAverageUseDenominatorModeChange() {
    const value = typeof document !== 'undefined'
        ? (document.getElementById('average-use-denominator-mode')?.value || 'active')
        : 'active';
    persistAverageUseAnalyticsPrefs({ denominatorMode: value === 'full' ? 'full' : 'active' });
    renderAverageUseAnalyticsView();
}

function buildAverageUseAnalyticsCsvRows(dataset = buildAverageUseAnalyticsDataset(appData)) {
    const columns = getEffectiveColumnOrder('averageUse');
    const headers = columns.map(colId => resolveColumnDisplayLabel('averageUse', colId, { forCsv: true }));
    const rows = [headers];
    dataset.rows.forEach(baseRow => {
        const row = {
            ...baseRow,
            avgSessionAmount: averageUseSafeDivide(baseRow.totalUse, baseRow.sessions)
        };
        rows.push(columns.map(colId => {
            switch (colId) {
                case 'period': return row.periodLabel || row.period;
                case 'totalUse': return row.totalUse;
                case 'useDays': return row.useDays;
                case 'sessions': return row.sessions;
                case 'avgActiveDay': return row.avgActiveDay ?? '';
                case 'avgCalendarDay': return row.avgCalendarDay ?? '';
                case 'avgWeek': return row.avgWeek ?? '';
                case 'avgMonth': return row.avgMonth ?? '';
                default: return '';
            }
        }));
    });
    return rows;
}

function exportAverageUseAnalyticsCsv(data = appData) {
    const dataset = buildAverageUseAnalyticsDataset(data);
    const rows = buildAverageUseAnalyticsCsvRows(dataset);
    const csv = rows.map(r => r.map(cell => {
        const s = String(cell ?? '');
        return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
    }).join(',')).join('\n');
    if (typeof downloadTextFile === 'function') {
        downloadTextFile(`average-use-analytics-${rtToday()}.csv`, csv, 'text/csv');
    }
    return csv;
}


// ——— Insights & Calendar UI simplification ———
// Reorganizes views into Overview / Calendar / Use / Money / More.
// Adds Simple/Advanced mode and section expand/collapse controls.
// Does not remove features or data — only reorganizes the interface.

const INSIGHTS_SIMPLIFY_PRIMARY_VIEWS = Object.freeze([
    'overview', 'calendar', 'use', 'money', 'more'
]);

const INSIGHTS_LEGACY_VIEW_MAP = Object.freeze({
    trends: 'use',
    comparisons: 'more',
    compare: 'more',
    comparison: 'more',
    financial: 'money',
    finances: 'money',
    purchase: 'money',
    'purchase-analytics': 'money',
    'use-analytics': 'use',
    'goal-analytics': 'more',
    'plan-analytics': 'more',
    charts: 'use',
    custom: 'more',
    'custom-metrics': 'more'
});

const INSIGHTS_SIMPLE_HIDDEN_SECTIONS = Object.freeze([
    'statsMonthlySummary',
    'statsWeeklySummary',
    'statsRunningTotals',
    'statsContactAnalytics',
    'statsCustomMetrics',
    'statsBuyPurchaseDetails',
    'statsBuyStoreBreakdown',
    'statsBuyAdvanced',
    'statsGiftAnalytics',
    'chartBuilder',
    'chartFilters',
    'statsMoreMetrics',
    'statsPlanAnalytics',
    'purchaseAnalyticsFilters'
]);

function getDefaultInsightsLayoutPrefs() {
    return {
        viewMode: 'simple', // simple | advanced
        compactRows: true
    };
}

function ensureInsightsLayoutPrefs(data = appData) {
    if (!data || typeof data !== 'object') return getDefaultInsightsLayoutPrefs();
    if (!data.settings || typeof data.settings !== 'object') data.settings = {};
    const defaults = getDefaultInsightsLayoutPrefs();
    if (!data.settings.insightsLayout || typeof data.settings.insightsLayout !== 'object') {
        data.settings.insightsLayout = { ...defaults };
    }
    const prefs = data.settings.insightsLayout;
    if (prefs.viewMode !== 'simple' && prefs.viewMode !== 'advanced') prefs.viewMode = 'simple';
    if (prefs.compactRows === undefined) prefs.compactRows = true;
    return prefs;
}

function getInsightsLayoutPrefs(data = appData) {
    return ensureInsightsLayoutPrefs(data);
}

function persistInsightsLayoutPrefs(patch = {}, data = appData) {
    const prefs = ensureInsightsLayoutPrefs(data);
    Object.assign(prefs, patch || {});
    if (typeof saveData === 'function') saveData(data);
    applyInsightsLayoutMode();
    return prefs;
}

function normalizeInsightsSimplifyView(view) {
    const raw = String(view || '').trim().toLowerCase();
    const mapped = INSIGHTS_LEGACY_VIEW_MAP[raw] || raw;
    return INSIGHTS_SIMPLIFY_PRIMARY_VIEWS.includes(mapped) ? mapped : 'overview';
}

/** Migrate persisted nav prefs + mutate allowed views list in place. */
function applyInsightsSimplifyNavMigration(data = appData) {
    try {
        if (typeof INSIGHTS_CALENDAR_VIEWS !== 'undefined' && Array.isArray(INSIGHTS_CALENDAR_VIEWS)) {
            const next = INSIGHTS_SIMPLIFY_PRIMARY_VIEWS.slice();
            if (INSIGHTS_CALENDAR_VIEWS.join('|') !== next.join('|')) {
                INSIGHTS_CALENDAR_VIEWS.splice(0, INSIGHTS_CALENDAR_VIEWS.length, ...next);
            }
        }
    } catch (_) { /* ignore */ }

    if (!data?.settings) return;
    const prefs = typeof ensureCombinedNavPrefs === 'function'
        ? ensureCombinedNavPrefs(data)
        : data.settings.combinedNav;
    if (prefs && prefs.insightsCalendarView) {
        prefs.insightsCalendarView = normalizeInsightsSimplifyView(prefs.insightsCalendarView);
    }
    ensureInsightsLayoutPrefs(data);
}

function isInsightsSimpleMode(data = appData) {
    return getInsightsLayoutPrefs(data).viewMode !== 'advanced';
}

function applyInsightsLayoutMode(data = appData) {
    const prefs = ensureInsightsLayoutPrefs(data);
    const root = typeof document !== 'undefined'
        ? document.getElementById('insights-calendar-tab')
        : null;
    if (!root) return;
    root.classList.toggle('insights-simple-mode', prefs.viewMode === 'simple');
    root.classList.toggle('insights-advanced-mode', prefs.viewMode === 'advanced');
    root.classList.toggle('insights-compact-rows', !!prefs.compactRows);

    const modeSelect = document.getElementById('ic-view-mode');
    if (modeSelect) modeSelect.value = prefs.viewMode;

    // Hide advanced-only sections in Simple mode (still in DOM / preserved)
    root.querySelectorAll('[data-ic-advanced="true"], .collapsible-section').forEach(section => {
        const key = section.dataset?.section || '';
        const markedAdvanced = section.getAttribute('data-ic-advanced') === 'true'
            || INSIGHTS_SIMPLE_HIDDEN_SECTIONS.includes(key);
        if (!markedAdvanced) return;
        const hide = prefs.viewMode === 'simple';
        section.classList.toggle('ic-simple-hidden', hide);
        if (hide) {
            // Don't permanently set hidden attribute used by panel filter — use class only
        }
    });
}

function onInsightsViewModeChange() {
    const value = typeof document !== 'undefined'
        ? (document.getElementById('ic-view-mode')?.value || 'simple')
        : 'simple';
    persistInsightsLayoutPrefs({ viewMode: value === 'advanced' ? 'advanced' : 'simple' });
    if (typeof applyCollapsedSections === 'function') applyCollapsedSections();
    if (typeof updateStats === 'function') updateStats();
}

function expandAllInsightsSections() {
    ensureCollapsedSections(appData);
    const page = document.getElementById('insights-calendar-tab');
    if (!page) return;
    page.querySelectorAll('.collapsible-section[data-section]').forEach(section => {
        if (section.classList.contains('ic-section-hidden') || section.classList.contains('ic-simple-hidden')) return;
        const key = section.dataset.section;
        if (!key) return;
        appData.settings.collapsedSections[key] = false;
    });
    if (typeof saveData === 'function') saveData(appData);
    applyCollapsedSections();
}

function collapseAllInsightsSections() {
    ensureCollapsedSections(appData);
    const page = document.getElementById('insights-calendar-tab');
    if (!page) return;
    page.querySelectorAll('.collapsible-section[data-section]').forEach(section => {
        if (section.classList.contains('ic-section-hidden')) return;
        const key = section.dataset.section;
        if (!key || key === 'statsDateRange') return; // keep shared filter bar open
        appData.settings.collapsedSections[key] = true;
    });
    if (typeof saveData === 'function') saveData(appData);
    applyCollapsedSections();
}

function resetInsightsLayout() {
    ensureCollapsedSections(appData);
    // Restore defaults for Insights-related section keys only
    const defaults = typeof DEFAULT_COLLAPSED_SECTIONS === 'object' ? DEFAULT_COLLAPSED_SECTIONS : {};
    Object.keys(defaults).forEach(key => {
        if (key.startsWith('stats') || key.startsWith('chart') || key.startsWith('calendar') || key.startsWith('purchase')) {
            appData.settings.collapsedSections[key] = defaults[key];
        }
    });
    persistInsightsLayoutPrefs({ viewMode: 'simple', compactRows: true });
    if (typeof saveData === 'function') saveData(appData);
    applyInsightsLayoutMode();
    applyCollapsedSections();
    if (typeof syncInsightsFilterUi === 'function') syncInsightsFilterUi(appData);
}

function renderInsightsSectionToolbarHtml() {
    const prefs = getInsightsLayoutPrefs();
    return `
        <div class="ic-layout-toolbar" id="ic-layout-toolbar">
            <div class="ic-layout-toolbar-row">
                <label class="ic-view-mode-label">View Mode
                    <select id="ic-view-mode" aria-label="Insights view mode" onchange="onInsightsViewModeChange()">
                        <option value="simple"${prefs.viewMode === 'simple' ? ' selected' : ''}>Simple</option>
                        <option value="advanced"${prefs.viewMode === 'advanced' ? ' selected' : ''}>Advanced</option>
                    </select>
                </label>
                <div class="ic-layout-actions">
                    <button type="button" class="secondary-btn btn-sm" onclick="expandAllInsightsSections()">Expand all</button>
                    <button type="button" class="secondary-btn btn-sm" onclick="collapseAllInsightsSections()">Collapse all</button>
                    <button type="button" class="secondary-btn btn-sm" onclick="resetInsightsLayout()">Reset layout</button>
                </div>
            </div>
            <p class="settings-hint ic-layout-hint">Simple mode shows summary cards, key charts, and alerts. Advanced unlocks Running Totals, detailed tables, custom metrics, and exports.</p>
        </div>`;
}

function ensureInsightsSectionToolbarMounted() {
    if (typeof document === 'undefined') return;
    const wrap = document.querySelector('#insights-calendar-tab .combined-subnav-wrap');
    if (!wrap) return;
    let bar = document.getElementById('ic-layout-toolbar');
    if (!bar) {
        wrap.insertAdjacentHTML('afterend', renderInsightsSectionToolbarHtml());
    } else {
        // Refresh selected mode
        const sel = document.getElementById('ic-view-mode');
        if (sel) sel.value = getInsightsLayoutPrefs().viewMode;
    }
}

/**
 * Compact primary summary: Today, This week, This month, Range total, Spending, Use days.
 * Secondary metrics go into #stats-more-metrics-body when present.
 */
function renderCompactInsightsSummaryCards(substanceId, useStats, bounds, unit, cur) {
    const container = document.getElementById('stats-summary-dashboard');
    if (!container) return false;
    const today = typeof getLocalDateString === 'function' ? getLocalDateString() : '';
    const weekStart = typeof getWeekStartDateStr === 'function' ? getWeekStartDateStr(today) : today;
    const monthStart = String(today || '').slice(0, 7) + '-01';
    const isVape = typeof isVapeNicotineSubstanceId === 'function' && isVapeNicotineSubstanceId(substanceId);
    const displayUnit = typeof getStatsDisplayUnit === 'function'
        ? getStatsDisplayUnit(substanceId, unit)
        : (unit || '');
    const weekUsed = isVape
        ? (typeof getStatsUsageInRange === 'function' ? getStatsUsageInRange(substanceId, weekStart, today) : 0)
        : (typeof getWeeklyUsed === 'function' ? getWeeklyUsed(substanceId, today) : 0);
    const monthUsed = typeof getStatsUsageInRange === 'function'
        ? getStatsUsageInRange(substanceId, monthStart, today)
        : (useStats?.totalAmount ?? 0);
    const todayUsed = isVape
        ? (typeof getStatsUsageOnDate === 'function' ? getStatsUsageOnDate(substanceId, today) : 0)
        : (typeof getTodayUseStats === 'function' ? getTodayUseStats(substanceId).totalAmount : 0);
    const weekGoal = typeof getWeeklyLimit === 'function' ? getWeeklyLimit(substanceId, weekStart) : null;
    const weeklyBadge = typeof getUsageVsTargetBadge === 'function'
        ? getUsageVsTargetBadge(weekUsed, weekGoal)
        : null;

    let spend = useStats?.totalSpend ?? useStats?.spendTotal ?? useStats?.totalCost ?? null;
    try {
        if (spend == null && typeof buildInsightsDataset === 'function') {
            const ds = buildInsightsDataset(substanceId);
            const purchases = ds?.purchases || [];
            spend = purchases.reduce((s, p) => s + (parseFloat(p.totalCost) || 0), 0);
        }
    } catch (_) { /* optional */ }

    const fmtAmt = (n) => (typeof formatAmount === 'function' ? formatAmount(n) : String(n ?? 0));
    const fmtPuffs = (n) => (typeof formatStatsPuffs === 'function' ? formatStatsPuffs(n) : fmtAmt(n));
    const money = (n) => {
        if (n == null || !Number.isFinite(n)) return '—';
        const sym = cur || (typeof getCurrencySymbol === 'function' ? getCurrencySymbol() : '$');
        return `${sym}${fmtAmt(n)}`;
    };
    const card = typeof renderSheetMetricCard === 'function'
        ? renderSheetMetricCard
        : (label, value) => `<div class="sheet-metric-card"><span>${label}</span><strong>${value}</strong></div>`;

    const primary = isVape
        ? [
            card('Today', `${fmtPuffs(todayUsed)} puffs`, null),
            card('This week', `${fmtPuffs(weekUsed)} puffs`, weeklyBadge),
            card('This month', `${fmtPuffs(monthUsed)} puffs`, null),
            card('Range total', `${fmtPuffs(useStats?.totalAmount || 0)} puffs`, null),
            card('Spending', money(spend), null),
            card('Use days', String(useStats?.useDays ?? 0), null)
        ]
        : [
            card('Today', `${fmtAmt(todayUsed)} ${displayUnit}`, null),
            card('This week', `${fmtAmt(weekUsed)} ${displayUnit}`, weeklyBadge),
            card('This month', `${fmtAmt(monthUsed)} ${displayUnit}`, null),
            card('Range total', `${fmtAmt(useStats?.totalAmount || 0)} ${displayUnit}`, null),
            card('Spending', money(spend), null),
            card('Use days', String(useStats?.useDays ?? 0), null)
        ];

    container.innerHTML = primary.join('');
    container.classList.add('ic-primary-summary');

    const more = document.getElementById('stats-more-metrics-body');
    if (more) {
        const remaining = typeof getTotalRemainingSupply === 'function'
            ? getTotalRemainingSupply(substanceId)
            : null;
        const entriesLabel = (typeof isWeedTrackingMode === 'function' && isWeedTrackingMode(substanceId))
            ? 'Entries'
            : 'Sessions';
        const secondary = isVape
            ? [
                card('Weekly target', weekGoal != null ? `${fmtPuffs(weekGoal)} puffs` : '—', weeklyBadge),
                card('Vape count', String(useStats?.vapeCount ?? 0), null),
                card('Avg cost/vape', typeof formatCostPerVape === 'function'
                    ? formatCostPerVape(useStats?.avgCostPerVape, cur)
                    : '—', null),
                card('Remaining puffs', remaining != null ? `${fmtPuffs(remaining)} puffs` : '—', null),
                card('Range', `${bounds?.startDate || '…'} – ${bounds?.endDate || '…'}`, null)
            ]
            : [
                card('Weekly target', weekGoal != null ? `${fmtAmt(weekGoal)} ${displayUnit}` : '—', weeklyBadge),
                card(entriesLabel, String(useStats?.sessionCount ?? 0), null),
                card('Use day %', `${fmtAmt(useStats?.useDayPct ?? 0, 1)}%`, null),
                card('Remaining supply', remaining != null ? `${fmtAmt(remaining)} ${displayUnit}` : '—', null),
                card('Range', `${bounds?.startDate || '…'} – ${bounds?.endDate || '…'}`, null)
            ];
        more.innerHTML = `<div class="sheet-summary-grid">${secondary.join('')}</div>`;
    }
    return true;
}

function patchInsightsSimplifySummaryDashboard() {
    if (typeof renderStatsSummaryDashboard !== 'function') return;
    if (renderStatsSummaryDashboard.__insightsSimplifyPatched) return;
    const original = renderStatsSummaryDashboard;
    function wrapped(substanceId, useStats, bounds, unit, cur) {
        try {
            if (renderCompactInsightsSummaryCards(substanceId, useStats, bounds, unit, cur)) {
                return;
            }
        } catch (err) {
            console.warn('[insights-simplify] compact cards failed', err);
        }
        return original(substanceId, useStats, bounds, unit, cur);
    }
    wrapped.__insightsSimplifyPatched = true;
    wrapped.__original = original;
    renderStatsSummaryDashboard = wrapped;
}

function patchInsightsSimplifySectionFilter() {
    if (typeof applyInsightsCalendarSectionFilter !== 'function') return;
    if (applyInsightsCalendarSectionFilter.__insightsSimplifyPatched) return;
    const original = applyInsightsCalendarSectionFilter;
    function wrapped(view) {
        const normalized = normalizeInsightsSimplifyView(view);
        const stats = typeof document !== 'undefined' ? document.getElementById('stats-tab') : null;
        if (!stats) return original(view);

        if (normalized === 'calendar') {
            stats.hidden = true;
            applyInsightsLayoutMode();
            return;
        }

        stats.hidden = false;
        stats.classList.add('active');
        stats.querySelectorAll('.collapsible-section[data-ic-panels]').forEach(section => {
            const panels = String(section.getAttribute('data-ic-panels') || '').split(/\s+/).filter(Boolean);
            // Support legacy panel tags by mapping them
            const match = panels.some(p => normalizeInsightsSimplifyView(p) === normalized || p === normalized);
            section.classList.toggle('ic-section-hidden', !match);
            section.hidden = !match;
        });
        applyInsightsLayoutMode();
    }
    wrapped.__insightsSimplifyPatched = true;
    applyInsightsCalendarSectionFilter = wrapped;
}

function patchInsightsSimplifySetView() {
    if (typeof setInsightsCalendarView !== 'function') return;
    if (setInsightsCalendarView.__insightsSimplifyPatched) return;
    const original = setInsightsCalendarView;
    function wrapped(view, options = {}) {
        const normalized = normalizeInsightsSimplifyView(view);
        ensureInsightsSectionToolbarMounted();
        applyInsightsSimplifyNavMigration(appData);

        // Delegate to original with normalized view (allowed list already migrated)
        const result = original.call(this, normalized, options);

        // Extra renders for consolidated views
        if (normalized === 'overview') {
            const root = document.getElementById('ic-overview-root');
            if (root) root.innerHTML = renderSimplifiedInsightsOverviewHtml();
            if (typeof updateStats === 'function') updateStats();
        } else if (normalized === 'money') {
            if (typeof renderFinancialAnalyticsView === 'function') renderFinancialAnalyticsView();
            if (typeof renderPurchaseAnalyticsView === 'function') renderPurchaseAnalyticsView();
        } else if (normalized === 'more') {
            if (typeof renderRunningTotalsView === 'function') renderRunningTotalsView();
            if (typeof renderPlanAnalyticsPanel === 'function') renderPlanAnalyticsPanel();
            if (typeof renderInsightsContactAnalytics === 'function') renderInsightsContactAnalytics();
            if (typeof renderChartDashboardView === 'function') renderChartDashboardView();
        } else if (normalized === 'use') {
            if (typeof renderChartDashboardView === 'function') renderChartDashboardView();
            if (typeof renderRunningTotalsView === 'function') renderRunningTotalsView();
        }

        applyInsightsLayoutMode();
        if (typeof applyCollapsedSections === 'function') applyCollapsedSections();
        return result;
    }
    wrapped.__insightsSimplifyPatched = true;
    setInsightsCalendarView = wrapped;
}

function renderSimplifiedInsightsOverviewHtml() {
    let overview = null;
    try {
        overview = typeof buildInsightsCalendarOverview === 'function'
            ? buildInsightsCalendarOverview()
            : null;
    } catch (_) { overview = null; }
    const warnings = overview?.warnings?.length
        ? `<ul class="combined-mini-list">${overview.warnings.map(w =>
            `<li>${typeof escapeHtml === 'function' ? escapeHtml(w.message || w.title || 'Data warning') : (w.message || 'Data warning')}</li>`
        ).join('')}</ul>`
        : '<p class="settings-hint">No alerts right now.</p>';
    const range = overview?.rangeLabel || 'Selected range';
    return `
        <div class="combined-overview ic-simplified-overview">
            <p class="settings-hint">Showing Overview for <strong>${typeof escapeHtml === 'function' ? escapeHtml(range) : range}</strong>. Use the shared filters below for substance, product type, and dates.</p>
            <div class="combined-overview-columns">
                <section class="combined-overview-block">
                    <h3>Alerts</h3>
                    ${warnings}
                </section>
                <section class="combined-overview-block">
                    <h3>Quick links</h3>
                    <div class="combined-overview-actions">
                        <button type="button" class="secondary-btn btn-sm" onclick="setInsightsCalendarView('use')">Use</button>
                        <button type="button" class="secondary-btn btn-sm" onclick="setInsightsCalendarView('money')">Money</button>
                        <button type="button" class="secondary-btn btn-sm" onclick="setInsightsCalendarView('calendar')">Calendar</button>
                        <button type="button" class="secondary-btn btn-sm" onclick="setInsightsCalendarView('more')">More</button>
                    </div>
                </section>
            </div>
            <p class="settings-hint">Summary cards, trend charts, and calendar preview appear in the Insights sections below.</p>
        </div>`;
}

function initInsightsSimplify() {
    applyInsightsSimplifyNavMigration(appData);
    patchInsightsSimplifySectionFilter();
    patchInsightsSimplifySetView();
    patchInsightsSimplifySummaryDashboard();
    ensureInsightsSectionToolbarMounted();
    applyInsightsLayoutMode();
}

// Auto-init after DOM if available; also called from ensureAppDataSettings / initializeApp hooks
if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => {
            try { initInsightsSimplify(); } catch (err) { console.error('[insights-simplify] init failed', err); }
        });
    } else {
        try { initInsightsSimplify(); } catch (_) { /* ignore early */ }
    }
}


// ——— Inventory Source (unified Store + Supplier Contact) ———
// One optional Source field for businesses and people. Keeps `store` /
// `supplierContactId` / gift fields in sync for backward-compatible analytics.
// Does not reuse purchase.source (legacy acquisition-type marker).

const INVENTORY_SOURCE_KINDS = Object.freeze([
    'business',
    'individual',
    'dealer',
    'friend',
    'family',
    'online',
    'event',
    'other'
]);

const INVENTORY_SOURCE_KIND_LABELS = Object.freeze({
    business: 'Business/store',
    individual: 'Individual contact',
    dealer: 'Dealer/supplier',
    friend: 'Friend',
    family: 'Family',
    online: 'Online',
    event: 'Event',
    other: 'Other'
});

const INVENTORY_SOURCE_KIND_ICONS = Object.freeze({
    business: '🏪',
    individual: '👤',
    dealer: '👤',
    friend: '👤',
    family: '👤',
    online: '🌐',
    event: '📍',
    other: '•'
});

const BUY_SOURCE_ADD_NEW = '__add_new_source__';

function invSrcTrim(value) {
    return String(value ?? '').trim().replace(/\s+/g, ' ');
}

function invSrcEsc(value) {
    return typeof escapeHtml === 'function' ? escapeHtml(String(value ?? '')) : String(value ?? '');
}

function normalizeInventorySourceKind(kind) {
    const raw = String(kind || '').trim().toLowerCase();
    if (INVENTORY_SOURCE_KINDS.includes(raw)) return raw;
    const aliases = {
        store: 'business',
        location: 'business',
        business_store: 'business',
        person: 'individual',
        contact: 'individual',
        supplier: 'dealer',
        dealer_supplier: 'dealer',
        dispensary: 'business',
        pharmacy: 'business',
        website: 'online',
        web: 'online'
    };
    return aliases[raw] || 'other';
}

function inventorySourceKindLabel(kind) {
    return INVENTORY_SOURCE_KIND_LABELS[normalizeInventorySourceKind(kind)] || 'Other';
}

function inventorySourceIcon(kind) {
    return INVENTORY_SOURCE_KIND_ICONS[normalizeInventorySourceKind(kind)] || '•';
}

function inventorySourceIsPersonKind(kind) {
    const k = normalizeInventorySourceKind(kind);
    return k === 'individual' || k === 'dealer' || k === 'friend' || k === 'family';
}

function inventorySourceIsBusinessKind(kind) {
    const k = normalizeInventorySourceKind(kind);
    return k === 'business' || k === 'online' || k === 'event';
}

function inferInventorySourceKindFromContact(contact) {
    if (!contact) return 'individual';
    const roles = contact.roles || [];
    if (typeof contactHasRole === 'function') {
        if (contactHasRole(contact, 'dealer_supplier')) return 'dealer';
        if (contactHasRole(contact, 'friend')) return 'friend';
        if (contactHasRole(contact, 'family')) return 'family';
        if (contactHasRole(contact, 'dispensary') || contactHasRole(contact, 'pharmacy')) return 'business';
    } else {
        if (roles.includes('dealer_supplier')) return 'dealer';
        if (roles.includes('friend')) return 'friend';
        if (roles.includes('family')) return 'family';
        if (roles.includes('dispensary') || roles.includes('pharmacy')) return 'business';
    }
    return 'individual';
}

function getPurchaseSourceName(purchase) {
    if (!purchase) return '';
    const named = invSrcTrim(purchase.sourceName);
    if (named) return named;
    if (purchase.sourceContactId && typeof getContactDisplayName === 'function') {
        const n = invSrcTrim(getContactDisplayName(purchase.sourceContactId));
        if (n) return n;
    }
    const store = invSrcTrim(purchase.store || purchase.location || '');
    if (store) return store;
    if (purchase.supplierContactId && typeof getContactDisplayName === 'function') {
        const n = invSrcTrim(getContactDisplayName(purchase.supplierContactId));
        if (n) return n;
    }
    const gift = typeof getPurchaseGiftSource === 'function' ? invSrcTrim(getPurchaseGiftSource(purchase)) : '';
    if (gift) return gift;
    if (typeof purchaseIsPurchasedAsGift === 'function' && purchaseIsPurchasedAsGift(purchase)) {
        const recip = typeof getPurchaseGiftRecipient === 'function'
            ? invSrcTrim(getPurchaseGiftRecipient(purchase))
            : invSrcTrim(purchase.giftRecipient || '');
        if (recip) return recip;
    }
    return invSrcTrim(purchase.dealer || purchase.contact || '');
}

function getPurchaseSourceKind(purchase) {
    if (!purchase) return 'other';
    if (purchase.sourceKind) return normalizeInventorySourceKind(purchase.sourceKind);
    if (purchase.sourceContactId || purchase.supplierContactId) {
        const id = purchase.sourceContactId || purchase.supplierContactId;
        const contact = typeof getContactById === 'function' ? getContactById(id) : null;
        return inferInventorySourceKindFromContact(contact);
    }
    const store = invSrcTrim(purchase.store || purchase.location || '');
    if (store) {
        const lower = store.toLowerCase();
        if (/online|amazon|ebay|\.com|website|shipped/.test(lower)) return 'online';
        if (/festival|concert|party|event/.test(lower)) return 'event';
        return 'business';
    }
    if (purchase.dealer || purchase.contact) return 'dealer';
    return 'other';
}

function getPurchaseSourceContactId(purchase) {
    if (!purchase) return '';
    if (purchase.sourceContactId != null && String(purchase.sourceContactId).trim() !== '') {
        return String(purchase.sourceContactId).trim();
    }
    // If Source is already a business/store name, do not fall back to a different supplier contact
    if (purchase.sourceName && inventorySourceIsBusinessKind(purchase.sourceKind)) {
        return '';
    }
    return String(purchase.supplierContactId || purchase.storeContactId || '').trim();
}

function formatPurchaseSourceDisplay(purchase) {
    const name = getPurchaseSourceName(purchase);
    if (!name) return '—';
    const kind = getPurchaseSourceKind(purchase);
    return `${inventorySourceIcon(kind)} ${name}`;
}

function getBuySourceFieldLabel(acquisitionType) {
    const type = typeof normalizePurchaseAcquisitionType === 'function'
        ? normalizePurchaseAcquisitionType(acquisitionType)
        : acquisitionType;
    if (type === 'gift_received') return 'Gift From';
    if (type === 'purchased_as_gift') return 'Gift Recipient';
    if (type === 'other_adjustment') return 'Related Person / Source';
    return 'Source';
}

function getBuySourcePlaceholder(acquisitionType) {
    const type = typeof normalizePurchaseAcquisitionType === 'function'
        ? normalizePurchaseAcquisitionType(acquisitionType)
        : acquisitionType;
    if (type === 'gift_received') return 'Who gave this to you?';
    if (type === 'purchased_as_gift') return 'Who is this gift for?';
    if (type === 'other_adjustment') return 'Related person or source (optional)';
    return 'Search stores and contacts (optional)';
}

/**
 * Sync sourceName/sourceKind/sourceContactId onto legacy store / supplier / gift fields.
 * Never writes acquisition-type values into sourceName.
 */
function syncPurchaseSourceFields(purchase, data = appData) {
    if (!purchase || typeof purchase !== 'object') return purchase;
    const name = getPurchaseSourceName(purchase);
    const kind = getPurchaseSourceKind(purchase);
    const contactId = getPurchaseSourceContactId(purchase);

    if (name) purchase.sourceName = name;
    purchase.sourceKind = kind;
    if (contactId) purchase.sourceContactId = contactId;
    else if (purchase.sourceContactId === undefined) purchase.sourceContactId = '';

    const acq = typeof getPurchaseAcquisitionType === 'function'
        ? getPurchaseAcquisitionType(purchase)
        : (purchase.acquisitionType || 'purchased');

    if (acq === 'gift_received') {
        if (name) {
            purchase.giftSource = name;
            purchase.giverName = name;
            purchase.giftPartyName = name;
        }
        if (contactId) purchase.giftSourceContactId = contactId;
        purchase.store = '';
        purchase.supplierContactId = contactId || '';
    } else if (acq === 'purchased_as_gift') {
        if (name) {
            purchase.giftRecipient = name;
            purchase.recipientName = name;
            purchase.giftPartyName = name;
        }
        if (contactId) purchase.giftRecipientContactId = contactId;
        // Source is the gift recipient. Preserve store when it is a separate purchase location.
        if (inventorySourceIsBusinessKind(kind) && name && !purchase.giftRecipient) {
            purchase.store = name;
            purchase.supplierContactId = '';
        } else if (inventorySourceIsPersonKind(kind) || contactId) {
            purchase.supplierContactId = contactId || purchase.supplierContactId || '';
            // do not clear store — may still hold where the gift was purchased
        }
    } else {
        // purchased / other_adjustment
        if (inventorySourceIsPersonKind(kind) || contactId) {
            purchase.supplierContactId = contactId || purchase.supplierContactId || '';
            // Keep store empty when the Source is a person (avoid duplicate store+supplier)
            if (!inventorySourceIsBusinessKind(kind)) purchase.store = '';
            else if (name) purchase.store = name;
        } else if (name) {
            purchase.store = name;
            if (!contactId) purchase.supplierContactId = purchase.supplierContactId || '';
        }
    }
    return purchase;
}

function migratePurchaseSourceFields(purchase, data = appData) {
    if (!purchase || typeof purchase !== 'object') return { changed: false };
    if (purchase.sourceName) {
        syncPurchaseSourceFields(purchase, data);
        return { changed: false };
    }

    const store = invSrcTrim(purchase.store || purchase.location || '');
    const supplierId = String(purchase.supplierContactId || purchase.storeContactId || '').trim();
    const giftSource = invSrcTrim(purchase.giftSource || purchase.giverName || '');
    const giftRecipient = invSrcTrim(purchase.giftRecipient || purchase.recipientName || '');
    const acq = typeof getPurchaseAcquisitionType === 'function'
        ? getPurchaseAcquisitionType(purchase)
        : (purchase.acquisitionType || 'purchased');

    let name = '';
    let kind = 'other';
    let contactId = '';

    if (acq === 'gift_received' && (giftSource || purchase.giftSourceContactId)) {
        name = giftSource;
        contactId = String(purchase.giftSourceContactId || '').trim();
        kind = contactId ? inferInventorySourceKindFromContact(
            typeof getContactById === 'function' ? getContactById(contactId, data) : null
        ) : 'individual';
    } else if (acq === 'purchased_as_gift' && (giftRecipient || purchase.giftRecipientContactId)) {
        name = giftRecipient;
        contactId = String(purchase.giftRecipientContactId || '').trim();
        kind = contactId ? inferInventorySourceKindFromContact(
            typeof getContactById === 'function' ? getContactById(contactId, data) : null
        ) : 'individual';
    } else if (store) {
        // Prefer store; Supplier Contact only becomes Source when Store is empty
        name = store;
        kind = 'business';
        contactId = '';
        if (supplierId) {
            const c = typeof getContactById === 'function' ? getContactById(supplierId) : null;
            const cName = c ? invSrcTrim(typeof getContactDisplayName === 'function' ? getContactDisplayName(c) : c.name) : '';
            if (cName && cName.toLowerCase() === store.toLowerCase()) {
                contactId = supplierId;
                kind = inferInventorySourceKindFromContact(c);
            }
        }
    } else if (supplierId) {
        contactId = supplierId;
        const c = typeof getContactById === 'function' ? getContactById(supplierId, data) : null;
        name = c
            ? invSrcTrim(typeof getContactDisplayName === 'function' ? getContactDisplayName(c) : c.name)
            : '';
        kind = inferInventorySourceKindFromContact(c);
    } else if (purchase.dealer || purchase.contact) {
        name = invSrcTrim(purchase.dealer || purchase.contact);
        kind = 'dealer';
    }

    if (!name && !contactId) return { changed: false };

    purchase.sourceName = name;
    purchase.sourceKind = kind;
    purchase.sourceContactId = contactId;
    syncPurchaseSourceFields(purchase, data);
    return { changed: true };
}

function migrateInventorySources(data = appData) {
    if (!data || typeof data !== 'object') return { migrated: 0 };
    if (!data.migrations || typeof data.migrations !== 'object') data.migrations = {};
    let migrated = 0;
    (data.purchases || []).forEach(p => {
        const result = migratePurchaseSourceFields(p, data);
        if (result.changed) migrated += 1;
        else syncPurchaseSourceFields(p, data);
    });
    data.migrations.inventorySourceV1 = true;
    data.migrations.inventorySourceReport = { migrated, at: new Date().toISOString() };
    return data.migrations.inventorySourceReport;
}

function ensureInventorySourcesMigrated(data = appData) {
    if (!data || typeof data !== 'object') return null;
    if (!data.migrations || typeof data.migrations !== 'object') data.migrations = {};
    if (data.migrations.inventorySourceV1) {
        (data.purchases || []).forEach(p => syncPurchaseSourceFields(p, data));
        return data.migrations.inventorySourceReport || null;
    }
    return migrateInventorySources(data);
}

function collectInventorySourceOptions(data = appData) {
    const businesses = new Map(); // key -> { name, kind }
    const people = [];

    (data.purchases || []).forEach(p => {
        const name = getPurchaseSourceName(p);
        if (!name) return;
        const kind = getPurchaseSourceKind(p);
        if (inventorySourceIsPersonKind(kind) || p.sourceContactId || p.supplierContactId) return;
        const key = name.toLowerCase();
        if (!businesses.has(key)) businesses.set(key, { name, kind, icon: inventorySourceIcon(kind) });
    });

    // Also include saved store names that may not have sourceName yet
    if (typeof getSavedStoreNames === 'function') {
        getSavedStoreNames(data).forEach(store => {
            const key = store.toLowerCase();
            if (!businesses.has(key)) businesses.set(key, { name: store, kind: 'business', icon: '🏪' });
        });
    }

    const contacts = typeof getContacts === 'function'
        ? getContacts(data, { includeArchived: false, includeHidden: false })
        : [];
    contacts.forEach(c => {
        const name = typeof getContactDisplayName === 'function' ? getContactDisplayName(c) : c.name;
        if (!name) return;
        people.push({
            id: c.id,
            name,
            kind: inferInventorySourceKindFromContact(c),
            icon: inventorySourceIcon(inferInventorySourceKindFromContact(c)),
            favorite: !!c.favorite
        });
    });

    people.sort((a, b) => {
        if (a.favorite !== b.favorite) return a.favorite ? -1 : 1;
        return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
    });

    return {
        businesses: [...businesses.values()].sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' })),
        people
    };
}

function getBuyFormSourceSelection() {
    const contactId = document.getElementById('buy-source-contact-id')?.value || '';
    const name = invSrcTrim(
        document.getElementById('buy-source-search')?.value
        || document.getElementById('buy-source-new')?.value
        || document.getElementById('buy-source')?.value
        || ''
    );
    const kindSelect = document.getElementById('buy-source-kind')?.value;
    let kind = kindSelect ? normalizeInventorySourceKind(kindSelect) : '';
    if (!kind && contactId) {
        const c = typeof getContactById === 'function' ? getContactById(contactId) : null;
        kind = inferInventorySourceKindFromContact(c);
    }
    if (!kind && name) kind = 'business';
    if (!kind) kind = 'other';
    return { name, kind, contactId };
}

function applyInventorySourceToPayload(payload) {
    if (!payload) return payload;
    const sel = getBuyFormSourceSelection();
    const acq = payload.acquisitionType || 'purchased';
    const hasSource = !!(sel.name || sel.contactId);

    // If the Source picker is empty, keep whatever the form already wrote (legacy store / gift fields)
    if (!hasSource) {
        // Still promote gift recipient/source into sourceName when those fields were filled
        if (acq === 'gift_received' && payload.giftSource) {
            payload.sourceName = invSrcTrim(payload.giftSource);
            payload.sourceKind = payload.giftSourceContactId ? 'individual' : 'individual';
            payload.sourceContactId = payload.giftSourceContactId || '';
        } else if (acq === 'purchased_as_gift' && payload.giftRecipient) {
            payload.sourceName = invSrcTrim(payload.giftRecipient);
            payload.sourceKind = payload.giftRecipientContactId ? 'individual' : 'individual';
            payload.sourceContactId = payload.giftRecipientContactId || '';
            // Preserve store (where bought) when Source is the recipient
        } else if (payload.store) {
            payload.sourceName = invSrcTrim(payload.store);
            payload.sourceKind = 'business';
            payload.sourceContactId = '';
        }
        syncPurchaseSourceFields(payload);
        // For purchased_as_gift, sync may clear store when kind is person — restore purchase location
        if (acq === 'purchased_as_gift' && payload._preservedStore == null) {
            /* store already on payload from form */
        }
        return payload;
    }

    // Every source flows through the shared Contacts system: a free-typed name
    // reuses an existing contact when one matches (no duplicates) or creates a
    // new contact from the purchase form.
    if (sel.name && !sel.contactId
        && typeof findContactByName === 'function'
        && typeof saveContactRecord === 'function') {
        let contact = findContactByName(sel.name, appData);
        if (!contact) {
            try {
                contact = saveContactRecord({ name: sel.name }, appData);
            } catch (_) {
                contact = null;
            }
        }
        if (contact && contact.id) sel.contactId = contact.id;
    }

    payload.sourceName = sel.name || '';
    payload.sourceKind = sel.kind || 'other';
    payload.sourceContactId = sel.contactId || '';

    if (acq === 'gift_received') {
        payload.giftSource = sel.name || '';
        payload.giftSourceContactId = sel.contactId || '';
        payload.store = '';
        payload.supplierContactId = sel.contactId || '';
        if (sel.name) {
            payload.giverName = sel.name;
            payload.giftPartyName = sel.name;
        }
    } else if (acq === 'purchased_as_gift') {
        const priorStore = invSrcTrim(payload.store || '');
        payload.giftRecipient = sel.name || '';
        payload.giftRecipientContactId = sel.contactId || '';
        if (sel.name) {
            payload.recipientName = sel.name;
            payload.giftPartyName = sel.name;
        }
        // Source is the recipient; keep any prior store as purchase location when Source is a person
        if (inventorySourceIsBusinessKind(sel.kind) && sel.name) {
            payload.store = sel.name;
            payload.supplierContactId = '';
        } else {
            payload.store = priorStore;
            payload.supplierContactId = sel.contactId || '';
        }
    } else {
        if (inventorySourceIsPersonKind(sel.kind) || sel.contactId) {
            payload.store = inventorySourceIsBusinessKind(sel.kind) ? (sel.name || '') : '';
            payload.supplierContactId = sel.contactId || '';
            if (!sel.contactId && sel.name && inventorySourceIsPersonKind(sel.kind)) {
                payload.dealer = sel.name;
            }
        } else {
            payload.store = sel.name || '';
            payload.supplierContactId = '';
        }
    }

    const preservedStore = acq === 'purchased_as_gift' ? invSrcTrim(payload.store || '') : '';
    syncPurchaseSourceFields(payload);
    if (acq === 'purchased_as_gift' && preservedStore && inventorySourceIsPersonKind(payload.sourceKind)) {
        payload.store = preservedStore;
    }
    return payload;
}

function buildBuySourcePickerHtml(acquisitionType = 'purchased') {
    const label = getBuySourceFieldLabel(acquisitionType);
    const placeholder = getBuySourcePlaceholder(acquisitionType);
    return `
        <div class="form-group buy-source-group" id="buy-source-group" data-buy-source="1">
            <label for="buy-source-search" id="buy-source-label">${invSrcEsc(label)}</label>
            <div class="buy-source-picker" data-buy-source-picker="1">
                <input type="hidden" id="buy-source" value="">
                <input type="hidden" id="buy-source-contact-id" value="">
                <input type="hidden" id="buy-source-kind" value="">
                <input type="search" id="buy-source-search" class="buy-source-search"
                    placeholder="${invSrcEsc(placeholder)}" autocomplete="off"
                    onfocus="openBuySourceMenu()"
                    oninput="onBuySourceSearch(this.value)">
                <div id="buy-source-menu" class="buy-source-menu ct-picker-menu hidden" role="listbox"></div>
            </div>
            <div class="buy-source-meta">
                <button type="button" class="secondary-btn btn-sm" id="buy-source-clear-btn" onclick="clearBuySourceSelection()">Clear</button>
            </div>
            <div class="form-group buy-source-new-group hidden" id="buy-source-new-group">
                <label for="buy-source-new">New source name</label>
                <input type="text" id="buy-source-new" placeholder="Enter business or person name" autocomplete="off"
                    oninput="onBuySourceNewInput(this.value)">
            </div>
            <p class="settings-hint">Search businesses and contacts. Selecting either fills Source — no separate supplier field.</p>
        </div>`;
}

function refreshBuySourceMenu(query = '') {
    const menu = document.getElementById('buy-source-menu');
    if (!menu) return;
    const q = String(query || '').trim().toLowerCase();
    const { businesses, people } = collectInventorySourceOptions(appData);
    const filter = (name) => !q || String(name).toLowerCase().includes(q);
    const biz = businesses.filter(b => filter(b.name)).slice(0, 12);
    const ppl = people.filter(p => filter(p.name)).slice(0, 16);
    const bizHtml = biz.length
        ? `<div class="buy-source-group-label">Businesses</div>${biz.map(b =>
            `<button type="button" class="ct-picker-option buy-source-option" data-src-name="${invSrcEsc(b.name)}" data-src-kind="${b.kind}" onclick="selectBuySourceBusiness(this.getAttribute('data-src-name'), this.getAttribute('data-src-kind'))">${b.icon} ${invSrcEsc(b.name)}</button>`
        ).join('')}`
        : '';
    const pplHtml = ppl.length
        ? `<div class="buy-source-group-label">Contacts</div>${ppl.map(p =>
            `<button type="button" class="ct-picker-option buy-source-option" data-src-id="${invSrcEsc(p.id)}" onclick="selectBuySourceContact(this.getAttribute('data-src-id'))">${p.icon} ${invSrcEsc(p.name)}</button>`
        ).join('')}`
        : '';
    menu.innerHTML = `
        ${bizHtml}
        ${pplHtml}
        ${!biz.length && !ppl.length ? '<p class="settings-hint">No matches.</p>' : ''}
        <button type="button" class="ct-picker-option ct-picker-add" onclick="startBuySourceAddNew()">+ Add new source…</button>`;
}

function openBuySourceMenu() {
    const menu = document.getElementById('buy-source-menu');
    if (!menu) return;
    menu.classList.remove('hidden');
    refreshBuySourceMenu(document.getElementById('buy-source-search')?.value || '');
}

function closeBuySourceMenu() {
    document.getElementById('buy-source-menu')?.classList.add('hidden');
}

function onBuySourceSearch(value) {
    const idEl = document.getElementById('buy-source-contact-id');
    const free = document.getElementById('buy-source');
    if (idEl) idEl.value = '';
    if (free) free.value = value || '';
    document.getElementById('buy-source-new-group')?.classList.add('hidden');
    openBuySourceMenu();
    refreshBuySourceMenu(value);
}

function onBuySourceNewInput(value) {
    const free = document.getElementById('buy-source');
    const search = document.getElementById('buy-source-search');
    if (free) free.value = value || '';
    if (search) search.value = value || '';
    const idEl = document.getElementById('buy-source-contact-id');
    if (idEl) idEl.value = '';
    const kindEl = document.getElementById('buy-source-kind');
    if (kindEl && !kindEl.value) kindEl.value = 'business';
}

function startBuySourceAddNew() {
    document.getElementById('buy-source-new-group')?.classList.remove('hidden');
    closeBuySourceMenu();
    const kind = document.getElementById('buy-source-kind');
    if (kind && !kind.value) kind.value = 'business';
    document.getElementById('buy-source-new')?.focus();
}

function clearBuySourceSelection() {
    ['buy-source', 'buy-source-contact-id', 'buy-source-kind', 'buy-source-search', 'buy-source-new'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = '';
    });
    document.getElementById('buy-source-new-group')?.classList.add('hidden');
    closeBuySourceMenu();
}

function selectBuySourceBusiness(name, kind = 'business') {
    const n = invSrcTrim(name);
    const free = document.getElementById('buy-source');
    const search = document.getElementById('buy-source-search');
    const idEl = document.getElementById('buy-source-contact-id');
    const kindEl = document.getElementById('buy-source-kind');
    if (free) free.value = n;
    if (search) search.value = n;
    if (idEl) idEl.value = '';
    if (kindEl) kindEl.value = normalizeInventorySourceKind(kind);
    document.getElementById('buy-source-new-group')?.classList.add('hidden');
    closeBuySourceMenu();
    // Hide any leftover supplier picker
    document.getElementById('buy-supplier-contact-picker')?.classList.add('hidden');
}

function selectBuySourceContact(contactId) {
    const contact = typeof getContactById === 'function' ? getContactById(contactId) : null;
    const name = contact
        ? (typeof getContactDisplayName === 'function' ? getContactDisplayName(contact) : contact.name)
        : '';
    const kind = inferInventorySourceKindFromContact(contact);
    const free = document.getElementById('buy-source');
    const search = document.getElementById('buy-source-search');
    const idEl = document.getElementById('buy-source-contact-id');
    const kindEl = document.getElementById('buy-source-kind');
    if (free) free.value = name || '';
    if (search) search.value = name || '';
    if (idEl) idEl.value = contactId || '';
    if (kindEl) kindEl.value = kind;
    document.getElementById('buy-source-new-group')?.classList.add('hidden');
    closeBuySourceMenu();
    document.getElementById('buy-supplier-contact-picker')?.classList.add('hidden');
}

function setBuySourceFieldValue(purchaseOrName, maybeKind = '', maybeContactId = '') {
    ensureBuySourcePickerMounted();
    let name = '';
    let kind = '';
    let contactId = '';
    if (purchaseOrName && typeof purchaseOrName === 'object') {
        name = getPurchaseSourceName(purchaseOrName);
        kind = getPurchaseSourceKind(purchaseOrName);
        contactId = getPurchaseSourceContactId(purchaseOrName);
    } else {
        name = invSrcTrim(purchaseOrName);
        kind = normalizeInventorySourceKind(maybeKind || (maybeContactId ? 'individual' : 'business'));
        contactId = String(maybeContactId || '');
    }
    const free = document.getElementById('buy-source');
    const search = document.getElementById('buy-source-search');
    const idEl = document.getElementById('buy-source-contact-id');
    const kindEl = document.getElementById('buy-source-kind');
    if (free) free.value = name;
    if (search) search.value = name;
    if (idEl) idEl.value = contactId;
    if (kindEl) kindEl.value = name || contactId ? kind : '';
    document.getElementById('buy-source-new-group')?.classList.add('hidden');
}

function updateBuySourceFieldLabel() {
    const type = typeof getBuyFormAcquisitionType === 'function'
        ? getBuyFormAcquisitionType()
        : (document.getElementById('buy-acquisition-type')?.value || 'purchased');
    const label = document.getElementById('buy-source-label');
    if (label) label.textContent = getBuySourceFieldLabel(type);
    const search = document.getElementById('buy-source-search');
    if (search) search.placeholder = getBuySourcePlaceholder(type);
}

function ensureBuySourcePickerMounted() {
    if (typeof document === 'undefined') return;
    let group = document.getElementById('buy-source-group');
    if (group) {
        updateBuySourceFieldLabel();
        document.getElementById('buy-store-group')?.classList.add('hidden');
        document.getElementById('buy-supplier-contact-picker')?.classList.add('hidden');
        return;
    }
    const type = typeof getBuyFormAcquisitionType === 'function'
        ? getBuyFormAcquisitionType()
        : 'purchased';
    const html = buildBuySourcePickerHtml(type);
    const mount = document.getElementById('buy-source-mount');
    const storeGroup = document.getElementById('buy-store-group');
    if (mount) {
        mount.innerHTML = html;
    } else if (storeGroup) {
        storeGroup.insertAdjacentHTML('beforebegin', html);
    } else {
        document.getElementById('buy-payment-group')?.insertAdjacentHTML('beforebegin', html);
    }
    storeGroup?.classList.add('hidden');
    // Hide separate supplier + gift source/recipient (Source replaces them)
    document.getElementById('buy-supplier-contact-picker')?.classList.add('hidden');
    document.getElementById('buy-gift-source-group')?.classList.add('hidden');
    document.getElementById('buy-gift-recipient-group')?.classList.add('hidden');
    updateBuySourceFieldLabel();
}

function patchInventorySourceBuyForm() {
    if (typeof updateBuyAcquisitionTypeUI === 'function' && !updateBuyAcquisitionTypeUI.__sourcePatched) {
        const original = updateBuyAcquisitionTypeUI;
        updateBuyAcquisitionTypeUI = function patchedBuyAcquisitionTypeUI() {
            const result = original.apply(this, arguments);
            try {
                ensureBuySourcePickerMounted();
                updateBuySourceFieldLabel();
                // Always hide legacy store + supplier picker
                document.getElementById('buy-store-group')?.classList.add('hidden');
                document.getElementById('buy-supplier-contact-picker')?.classList.add('hidden');
                // Gift From / Recipient groups replaced by Source (keep gift date)
                const type = typeof getBuyFormAcquisitionType === 'function' ? getBuyFormAcquisitionType() : '';
                document.getElementById('buy-gift-source-group')?.classList.add('hidden');
                document.getElementById('buy-gift-recipient-group')?.classList.add('hidden');
                document.getElementById('buy-source-group')?.classList.remove('hidden');
                if (type === 'purchased_as_gift') {
                    document.getElementById('buy-gift-date-group')?.classList.remove('hidden');
                }
            } catch (err) {
                console.warn('[inventory-source] acquisition UI patch failed', err);
            }
            return result;
        };
        updateBuyAcquisitionTypeUI.__sourcePatched = true;
    }

    if (typeof buildPurchaseFromForm === 'function' && !buildPurchaseFromForm.__sourcePatched) {
        const original = buildPurchaseFromForm;
        buildPurchaseFromForm = function patchedBuildPurchaseFromForm() {
            const payload = original.apply(this, arguments);
            try {
                applyInventorySourceToPayload(payload);
                // Restore legacy acquisition marker on `source` after our sourceName write
                const acq = payload.acquisitionType || 'purchased';
                if (acq !== 'purchased') payload.source = acq;
                else if (payload.source === 'purchased') delete payload.source;
            } catch (err) {
                console.warn('[inventory-source] apply to payload failed', err);
            }
            return payload;
        };
        buildPurchaseFromForm.__sourcePatched = true;
    }

    if (typeof fillBuyFormFromPurchase === 'function' && !fillBuyFormFromPurchase.__sourcePatched) {
        const original = fillBuyFormFromPurchase;
        fillBuyFormFromPurchase = function patchedFillBuyFormFromPurchase(purchase) {
            const result = original.apply(this, arguments);
            try {
                ensureBuySourcePickerMounted();
                setBuySourceFieldValue(purchase);
                updateBuySourceFieldLabel();
            } catch (err) {
                console.warn('[inventory-source] fill form failed', err);
            }
            return result;
        };
        fillBuyFormFromPurchase.__sourcePatched = true;
    }

    if (typeof getBuyFormStoreValue === 'function' && !getBuyFormStoreValue.__sourcePatched) {
        const original = getBuyFormStoreValue;
        getBuyFormStoreValue = function patchedGetBuyFormStoreValue() {
            const sel = getBuyFormSourceSelection();
            if (sel.name || sel.contactId) {
                if (inventorySourceIsBusinessKind(sel.kind) || (!sel.contactId && !inventorySourceIsPersonKind(sel.kind))) {
                    return sel.name;
                }
                return '';
            }
            return original.apply(this, arguments);
        };
        getBuyFormStoreValue.__sourcePatched = true;
    }
}

function patchInventorySourceAnalytics() {
    if (typeof financialPurchaseStore === 'function' && !financialPurchaseStore.__sourcePatched) {
        const original = financialPurchaseStore;
        financialPurchaseStore = function patchedFinancialPurchaseStore(purchase) {
            const kind = getPurchaseSourceKind(purchase);
            if (inventorySourceIsBusinessKind(kind) || kind === 'other') {
                const name = getPurchaseSourceName(purchase);
                if (name && !inventorySourceIsPersonKind(kind)) return name;
            }
            // Person sources should not count as stores
            if (inventorySourceIsPersonKind(kind)) return '';
            return original(purchase);
        };
        financialPurchaseStore.__sourcePatched = true;
    }

    if (typeof financialPurchaseSupplier === 'function' && !financialPurchaseSupplier.__sourcePatched) {
        const original = financialPurchaseSupplier;
        financialPurchaseSupplier = function patchedFinancialPurchaseSupplier(purchase) {
            const kind = getPurchaseSourceKind(purchase);
            const name = getPurchaseSourceName(purchase);
            if (inventorySourceIsPersonKind(kind) || kind === 'dealer') return name || original(purchase);
            if (purchase?.sourceContactId || purchase?.supplierContactId) return name || original(purchase);
            return original(purchase);
        };
        financialPurchaseSupplier.__sourcePatched = true;
    }
}

function patchInventorySourceHistoryColumns() {
    try {
        if (typeof TABLE_COLUMN_LABELS !== 'undefined' && TABLE_COLUMN_LABELS.purchaseHistory) {
            TABLE_COLUMN_LABELS.purchaseHistory.store = 'Source';
            TABLE_COLUMN_LABELS.purchaseHistory.supplier = 'Source (legacy)';
        }
    } catch (_) { /* optional */ }

    // Hide supplier by default going forward
    try {
        if (typeof TABLE_COLUMN_DEFAULTS !== 'undefined' && TABLE_COLUMN_DEFAULTS.purchaseHistory) {
            const hidden = TABLE_COLUMN_DEFAULTS.purchaseHistory.hidden || [];
            if (!hidden.includes('supplier')) {
                TABLE_COLUMN_DEFAULTS.purchaseHistory.hidden = [...hidden, 'supplier'];
            }
        }
    } catch (_) { /* optional */ }
}

function initInventorySource() {
    ensureInventorySourcesMigrated(appData);
    patchInventorySourceBuyForm();
    patchInventorySourceAnalytics();
    patchInventorySourceHistoryColumns();
    if (typeof document !== 'undefined') {
        ensureBuySourcePickerMounted();
        document.addEventListener('click', (e) => {
            const menu = document.getElementById('buy-source-menu');
            const picker = document.querySelector('[data-buy-source-picker]');
            if (!menu || menu.classList.contains('hidden')) return;
            if (picker && picker.contains(e.target)) return;
            closeBuySourceMenu();
        });
    }
}

if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => {
            try { initInventorySource(); } catch (err) { console.error('[inventory-source] init failed', err); }
        });
    } else {
        try { initInventorySource(); } catch (_) { /* tests / early */ }
    }
}


// ——— App-wide Experience Mode (Simple / Advanced) ———
// Presentation layer only — reuses canonical calc engine, logs, inventory, tapers.
// Does not remove Advanced features or rewrite existing records.

const EXPERIENCE_MODE_SIMPLE = 'simple';
const EXPERIENCE_MODE_ADVANCED = 'advanced';
const EXPERIENCE_PROGRESS_RANGES = Object.freeze(['7', '30', '90', 'all']);

const SIMPLE_TAPER_STATUS = Object.freeze({
    within: { key: 'within', label: 'Within target', homeLabel: 'Within taper target' },
    near: { key: 'near', label: 'Near target', homeLabel: 'Near taper target' },
    above: { key: 'above', label: 'Above target', homeLabel: 'Above taper target' },
    none: { key: 'none', label: 'No active taper', homeLabel: 'No active taper' }
});

const SIMPLE_PLAN_INTENTS = Object.freeze([
    { id: 'use-less', label: 'Use less', reductionType: 'reduce-amount', hint: 'Lower daily use over time.' },
    { id: 'spend-less', label: 'Spend less', reductionType: 'reduce-buying', hint: 'Reduce how much you spend.' },
    { id: 'buy-less', label: 'Buy less often', reductionType: 'reduce-buying', hint: 'Increase days between purchases.' },
    { id: 'quit-by-date', label: 'Quit by a date', reductionType: 'reduce-amount', hint: 'Reach zero by a chosen end date.' },
    { id: 'track-only', label: 'Track only', reductionType: null, hint: 'No taper — just monitor use.' },
    { id: 'custom', label: 'Custom', reductionType: null, hint: 'Open full plan settings.' }
]);

function getDefaultSimpleModePrefs() {
    return {
        quickLogBySubstance: {},
        recentAmountsBySubstance: {},
        progressRange: '7',
        progressSubstanceId: null,
        progressCalendarMonth: null,
        lastQuickSubstanceId: null,
        planIntent: null
    };
}

function normalizeExperienceMode(value) {
    return value === EXPERIENCE_MODE_ADVANCED ? EXPERIENCE_MODE_ADVANCED : EXPERIENCE_MODE_SIMPLE;
}

function migrateExperienceModeV1(data = appData) {
    if (!data || typeof data !== 'object') return;
    if (!data.migrations || typeof data.migrations !== 'object') data.migrations = {};
    if (data.migrations.experienceModeV1) return;
    if (!data.settings || typeof data.settings !== 'object') data.settings = {};

    const hasExistingWork =
        (Array.isArray(data.logs) && data.logs.length > 0)
        || (Array.isArray(data.purchases) && data.purchases.length > 0)
        || (Array.isArray(data.taperPlansV2) && data.taperPlansV2.length > 0)
        || (data.taperPlans && typeof data.taperPlans === 'object' && Object.keys(data.taperPlans).length > 0);

    if (data.settings.experienceMode == null) {
        // Existing users keep the full UI by default; new installs use Simple.
        data.settings.experienceMode = hasExistingWork
            ? EXPERIENCE_MODE_ADVANCED
            : EXPERIENCE_MODE_SIMPLE;
    } else {
        data.settings.experienceMode = normalizeExperienceMode(data.settings.experienceMode);
    }
    data.migrations.experienceModeV1 = true;
}

function ensureSimpleModePrefs(data = appData) {
    if (!data || typeof data !== 'object') return getDefaultSimpleModePrefs();
    if (!data.settings || typeof data.settings !== 'object') data.settings = {};
    const defaults = getDefaultSimpleModePrefs();
    if (!data.settings.simpleModePrefs || typeof data.settings.simpleModePrefs !== 'object') {
        data.settings.simpleModePrefs = { ...defaults };
    }
    const prefs = data.settings.simpleModePrefs;
    if (!prefs.quickLogBySubstance || typeof prefs.quickLogBySubstance !== 'object') {
        prefs.quickLogBySubstance = {};
    }
    if (!prefs.recentAmountsBySubstance || typeof prefs.recentAmountsBySubstance !== 'object') {
        prefs.recentAmountsBySubstance = {};
    }
    if (!EXPERIENCE_PROGRESS_RANGES.includes(String(prefs.progressRange))) {
        prefs.progressRange = '7';
    }
    return prefs;
}

function ensureExperienceMode(data = appData) {
    if (!data || typeof data !== 'object') return EXPERIENCE_MODE_SIMPLE;
    if (!data.settings || typeof data.settings !== 'object') data.settings = {};
    migrateExperienceModeV1(data);
    data.settings.experienceMode = normalizeExperienceMode(data.settings.experienceMode);
    ensureSimpleModePrefs(data);
    return data.settings.experienceMode;
}

function getExperienceMode(data = appData) {
    return ensureExperienceMode(data);
}

function isSimpleExperienceMode(data = appData) {
    return getExperienceMode(data) === EXPERIENCE_MODE_SIMPLE;
}

function isAdvancedExperienceMode(data = appData) {
    return getExperienceMode(data) === EXPERIENCE_MODE_ADVANCED;
}

function persistExperienceMode(mode, data = appData) {
    ensureExperienceMode(data);
    data.settings.experienceMode = normalizeExperienceMode(mode);
    if (typeof saveData === 'function') saveData(data);
    applyExperienceMode(data);
    return data.settings.experienceMode;
}

function getSimpleModePrefs(data = appData) {
    return ensureSimpleModePrefs(data);
}

function persistSimpleModePrefs(patch = {}, data = appData) {
    const prefs = ensureSimpleModePrefs(data);
    Object.assign(prefs, patch || {});
    if (typeof saveData === 'function') saveData(data);
    return prefs;
}

function getTrackedSubstancesForSimpleHome(data = appData) {
    const active = typeof getActiveSubstances === 'function'
        ? getActiveSubstances(data)
        : (data.substances || []).filter(s => s && s.active !== false);
    const today = typeof getLocalDateString === 'function' ? getLocalDateString() : '';
    return active.filter(sub => {
        if (!sub?.id) return false;
        if (sub.isMain) return true;
        if (!today) return true;
        const used = typeof getCanonicalUsageOnDate === 'function'
            ? getCanonicalUsageOnDate(sub.id, today, data)
            : 0;
        return used > 0;
    });
}

function resolveSimpleTaperStatus(used, target) {
    if (typeof getTaperLimitStatus === 'function') {
        const engine = getTaperLimitStatus(used, target);
        if (engine.status === 'over') return SIMPLE_TAPER_STATUS.above;
        if (engine.status === 'close') return SIMPLE_TAPER_STATUS.near;
        if (engine.status === 'under') return SIMPLE_TAPER_STATUS.within;
        return SIMPLE_TAPER_STATUS.none;
    }
    if (target == null || !(target > 0)) return SIMPLE_TAPER_STATUS.none;
    if (used > target) return SIMPLE_TAPER_STATUS.above;
    if (used >= target * 0.8) return SIMPLE_TAPER_STATUS.near;
    return SIMPLE_TAPER_STATUS.within;
}

function getSimpleTaperDailyTarget(substanceId, dateStr, data = appData) {
    if (!substanceId || typeof getDailyLimitForDate !== 'function') return null;
    const target = getDailyLimitForDate(substanceId, dateStr, null);
    return target != null && Number(target) > 0 ? Number(target) : null;
}

function formatSimpleUsage(substanceId, amount, data = appData) {
    if (typeof formatRecoveryUsageAmount === 'function') {
        return formatRecoveryUsageAmount(substanceId, amount, data);
    }
    const unit = typeof getSubstanceDisplayUnit === 'function'
        ? getSubstanceDisplayUnit(substanceId, data)
        : '';
    const n = Number(amount) || 0;
    if (typeof formatAmountWithUnit === 'function') return formatAmountWithUnit(n, unit);
    return `${n}${unit ? ` ${unit}` : ''}`;
}

function getSimpleSubstanceDisplayName(subOrId, data = appData) {
    if (typeof getSubstanceDisplayName === 'function') {
        return getSubstanceDisplayName(subOrId, data);
    }
    if (subOrId && typeof subOrId === 'object') return subOrId.name || subOrId.id || '';
    return String(subOrId || '');
}

function formatSimpleLastSaved(raw) {
    const text = String(raw || 'Last Saved: —').trim();
    if (/^Last Saved:/i.test(text)) return text.replace(/^Last Saved:\s*/i, 'Last Saved: ');
    return `Last Saved: ${text}`;
}

function formatSimpleSpendPeriodLabel(bounds) {
    if (!bounds) return 'Estimated spending';
    if (bounds.key === 'all') return 'Estimated spending · All time';
    const days = Number(bounds.days) || Number(bounds.key);
    if (Number.isFinite(days) && days > 0) return `Estimated spending · ${days} days`;
    return 'Estimated spending';
}

function formatSimpleAxisDate(dateStr) {
    if (typeof formatShortMonthDay === 'function') return formatShortMonthDay(dateStr);
    return dateStr || '';
}

function getRecentAverageUsage(substanceId, days = 7, data = appData) {
    if (!substanceId || typeof getCanonicalUsageInRange !== 'function') return 0;
    const today = getLocalDateString();
    const endPrev = addDaysYYYYMMDD(today, -1);
    const startPrev = addDaysYYYYMMDD(endPrev, -(Math.max(1, days) - 1));
    const total = getCanonicalUsageInRange(substanceId, startPrev, endPrev, data);
    return total / Math.max(1, days);
}

function buildSimpleTodayCard(substance, data = appData) {
    const today = getLocalDateString();
    const substanceId = substance.id;
    const used = typeof getCanonicalUsageOnDate === 'function'
        ? getCanonicalUsageOnDate(substanceId, today, data)
        : 0;
    const target = getSimpleTaperDailyTarget(substanceId, today, data);
    const remaining = target != null ? Math.max(0, target - used) : null;
    const recentAvg = getRecentAverageUsage(substanceId, 7, data);
    let vsRecent = null;
    if (recentAvg > 0) {
        vsRecent = ((used - recentAvg) / recentAvg) * 100;
    }
    const status = resolveSimpleTaperStatus(used, target);
    const unit = typeof getSubstanceDisplayUnit === 'function'
        ? getSubstanceDisplayUnit(substanceId, data)
        : (substance.defaultUnit || '');
    return {
        substanceId,
        name: getSimpleSubstanceDisplayName(substance, data) || substance.name || substanceId,
        unit,
        used,
        usedLabel: formatSimpleUsage(substanceId, used, data),
        target,
        targetLabel: target != null ? formatSimpleUsage(substanceId, target, data) : null,
        remaining,
        remainingLabel: remaining != null ? formatSimpleUsage(substanceId, remaining, data) : null,
        vsRecent,
        status
    };
}

function buildSimpleHomeDataset(data = appData) {
    const substances = getTrackedSubstancesForSimpleHome(data);
    const cards = substances.map(s => buildSimpleTodayCard(s, data));
    // Also include any substance with use today that wasn't in the filtered list
    const today = getLocalDateString();
    const seen = new Set(cards.map(c => c.substanceId));
    (data.substances || []).forEach(sub => {
        if (!sub?.id || seen.has(sub.id) || sub.active === false) return;
        const used = getCanonicalUsageOnDate(sub.id, today, data);
        if (used > 0) {
            cards.push(buildSimpleTodayCard(sub, data));
            seen.add(sub.id);
        }
    });
    cards.sort((a, b) => {
        if (b.used !== a.used) return b.used - a.used;
        return String(a.name).localeCompare(String(b.name));
    });
    return { today, cards };
}

function renderSimpleHome(data = appData) {
    if (typeof document === 'undefined') return;
    const root = document.getElementById('simple-home');
    if (!root) return;
    const dataset = buildSimpleHomeDataset(data);
    const cardsHtml = dataset.cards.length
        ? dataset.cards.map(card => {
            const vsRow = card.vsRecent == null
                ? ''
                : `<div class="sm-today-row">
                    <dt>vs recent</dt>
                    <dd class="${card.vsRecent <= 0 ? 'sm-vs-down' : 'sm-vs-up'}">${card.vsRecent <= 0 ? '↓' : '↑'} ${Math.abs(Math.round(card.vsRecent))}%</dd>
                   </div>`;
            const meta = card.target != null
                ? `<dl class="sm-today-meta">
                    <div class="sm-today-row"><dt>Taper target</dt><dd>≤ ${escapeHtml(card.targetLabel)}</dd></div>
                    <div class="sm-today-row"><dt>Remaining</dt><dd>${escapeHtml(card.remainingLabel)}</dd></div>
                    ${vsRow}
                   </dl>`
                : `<dl class="sm-today-meta">
                    <div class="sm-today-row"><dt>Taper</dt><dd>${escapeHtml(card.status.homeLabel || card.status.label)}</dd></div>
                    ${vsRow}
                   </dl>`;
            return `
                <article class="sm-today-card status-${escapeHtml(card.status.key)}" data-substance-id="${escapeHtml(card.substanceId)}">
                    <header class="sm-today-card-head">
                        <h3>${escapeHtml(card.name)}</h3>
                        <span class="sm-status-pill">${escapeHtml(card.status.homeLabel || card.status.label)}</span>
                    </header>
                    <p class="sm-today-amount">${escapeHtml(card.usedLabel)} <span class="sm-today-amount-label">today</span></p>
                    ${meta}
                    <button type="button" class="sm-card-quick-btn" onclick="openSimpleQuickLog('${escapeHtml(card.substanceId)}')">Quick Log</button>
                </article>`;
        }).join('')
        : `<div class="sm-empty">
            <p>Nothing logged today yet.</p>
            <p class="settings-hint">Tap Quick Log to record use in a few taps.</p>
           </div>`;

    const lastSaved = formatSimpleLastSaved(
        document.getElementById('dashboard-last-saved')?.textContent
        || document.getElementById('settings-last-saved')?.textContent
        || 'Last Saved: —'
    );

    root.innerHTML = `
        <div class="sm-home-header">
            <div>
                <h2 class="sm-home-title">Today</h2>
                <p class="sm-home-sub">How am I doing today?</p>
            </div>
            <p class="last-saved-status sm-last-saved">${escapeHtml(lastSaved)}</p>
        </div>
        <div class="sm-primary-actions" role="group" aria-label="Primary actions">
            <button type="button" class="sm-action-btn sm-action-primary" onclick="openSimpleQuickLog()">Quick Log</button>
            <button type="button" class="sm-action-btn sm-action-secondary" onclick="openSimpleLogDetails()">Log Details</button>
            <button type="button" class="sm-action-btn sm-action-secondary" onclick="openSimpleProgress()">View Progress</button>
        </div>
        <div class="sm-today-grid" id="sm-today-grid">${cardsHtml}</div>
        <div class="sm-home-footer">
            <button type="button" class="sm-text-btn" onclick="showAdvancedHomeDashboard()">Show full dashboard</button>
        </div>`;
}

function showAdvancedHomeDashboard() {
    if (typeof document === 'undefined') return;
    document.getElementById('dashboard-tab')?.classList.add('sm-show-advanced-home');
    if (typeof updateDashboard === 'function') updateDashboard();
}

function hideAdvancedHomeDashboard() {
    if (typeof document === 'undefined') return;
    document.getElementById('dashboard-tab')?.classList.remove('sm-show-advanced-home');
}

function openSimpleLogDetails() {
    hideAdvancedHomeDashboard();
    if (typeof switchTab === 'function') switchTab('use-log-tab');
}

function openSimpleProgress() {
    hideAdvancedHomeDashboard();
    if (typeof switchTab === 'function') switchTab('insights-calendar-tab');
    renderSimpleProgress();
}

function rememberQuickLogFromForm(data = appData) {
    const substanceId = document.getElementById('use-substance')?.value
        || document.getElementById('use-log-substance')?.value;
    if (!substanceId) return;
    const prefs = ensureSimpleModePrefs(data);
    const amountRaw = document.getElementById('use-amount')?.value
        || document.getElementById('use-vape-puffs-used')?.value
        || document.getElementById('use-cigarettes-smoked')?.value
        || document.getElementById('use-lsd-tabs-used')?.value
        || document.getElementById('use-xanax-pills-used')?.value;
    const amount = parseFloat(amountRaw);
    const unit = document.getElementById('use-unit')?.value || '';
    const productType = document.getElementById('use-nicotine-product-type')?.value
        || document.getElementById('use-weed-product-type')?.value
        || null;
    const purchaseId = document.getElementById('use-purchase-select')?.value
        || document.getElementById('use-vape-purchase-select')?.value
        || null;
    const transactionType = document.getElementById('use-transaction-type')?.value || 'use';
    const vapeMode = document.getElementById('use-vape-log-mode')?.value || null;

    prefs.quickLogBySubstance[substanceId] = {
        substanceId,
        productType,
        amount: Number.isFinite(amount) ? amount : null,
        unit,
        purchaseId: purchaseId || null,
        transactionType,
        vapeMode,
        updatedAt: new Date().toISOString()
    };
    prefs.lastQuickSubstanceId = substanceId;

    if (Number.isFinite(amount) && amount > 0) {
        rememberRecentAmount(substanceId, amount, data);
    } else if (typeof saveData === 'function') {
        saveData(data);
    }
}

function rememberRecentAmount(substanceId, amount, data = appData) {
    if (!substanceId || !(amount > 0)) return;
    const prefs = ensureSimpleModePrefs(data);
    const key = String(substanceId);
    const list = Array.isArray(prefs.recentAmountsBySubstance[key])
        ? prefs.recentAmountsBySubstance[key].slice()
        : [];
    const rounded = Math.round(amount * 1000) / 1000;
    const next = [rounded, ...list.filter(v => Math.abs(v - rounded) > 1e-9)].slice(0, 6);
    prefs.recentAmountsBySubstance[key] = next;
    if (typeof saveData === 'function') saveData(data);
}

function getRecentAmountsForSubstance(substanceId, data = appData) {
    const prefs = ensureSimpleModePrefs(data);
    const remembered = prefs.recentAmountsBySubstance?.[substanceId];
    if (Array.isArray(remembered) && remembered.length) {
        return remembered.filter(n => Number.isFinite(n) && n > 0).slice(0, 5);
    }
    // Derive from recent logs when prefs are empty
    const logs = (data.logs || [])
        .filter(l => l && String(l.substanceId) === String(substanceId) && Number(l.amount) > 0)
        .sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')))
        .slice(0, 40);
    const seen = [];
    logs.forEach(log => {
        const amt = Math.round(Number(log.amount) * 1000) / 1000;
        if (!(amt > 0)) return;
        if (!seen.some(v => Math.abs(v - amt) < 1e-9)) seen.push(amt);
    });
    if (seen.length) return seen.slice(0, 5);

    // Light sensible fallbacks by tracking mode
    if (typeof isNicotineTrackingMode === 'function' && isNicotineTrackingMode(substanceId, data)) {
        return [100, 250, 500];
    }
    if (typeof isPowderTrackingMode === 'function' && isPowderTrackingMode(substanceId, data)) {
        return [0.1, 0.25, 0.5];
    }
    return [1, 2, 5];
}

function applyQuickLogMemoryToForm(substanceId, data = appData) {
    if (!substanceId || typeof document === 'undefined') return;
    const prefs = ensureSimpleModePrefs(data);
    const mem = prefs.quickLogBySubstance?.[substanceId];
    const substanceEl = document.getElementById('use-substance');
    const pageSubstanceEl = document.getElementById('use-log-substance');
    if (substanceEl) substanceEl.value = substanceId;
    if (pageSubstanceEl) pageSubstanceEl.value = substanceId;
    if (typeof onUseLogSubstanceChange === 'function') {
        try { onUseLogSubstanceChange(); } catch (_) { /* ignore */ }
    } else if (typeof syncUseLogFormFromSelectedSubstance === 'function') {
        try { syncUseLogFormFromSelectedSubstance(); } catch (_) { /* ignore */ }
    }

    if (mem?.productType) {
        const nic = document.getElementById('use-nicotine-product-type');
        const weed = document.getElementById('use-weed-product-type');
        if (nic && [...nic.options].some(o => o.value === mem.productType)) {
            nic.value = mem.productType;
            if (typeof onNicotineUseProductTypeChange === 'function') onNicotineUseProductTypeChange();
        }
        if (weed && [...weed.options].some(o => o.value === mem.productType)) {
            weed.value = mem.productType;
            if (typeof onWeedUseProductTypeChange === 'function') onWeedUseProductTypeChange();
        }
    }

    if (mem?.unit) {
        const unitEl = document.getElementById('use-unit');
        if (unitEl && [...unitEl.options].some(o => o.value === mem.unit)) {
            unitEl.value = mem.unit;
        }
    }

    if (mem?.amount != null && Number.isFinite(mem.amount)) {
        const amountEl = document.getElementById('use-amount');
        if (amountEl) amountEl.value = String(mem.amount);
        const puffsEl = document.getElementById('use-vape-puffs-used');
        if (puffsEl && (mem.productType === 'vape' || mem.vapeMode === 'puffs')) {
            puffsEl.value = String(mem.amount);
            if (typeof setVapeLogInputMode === 'function') setVapeLogInputMode('puffs');
        }
    }

    if (mem?.transactionType && typeof setUseTransactionType === 'function') {
        try { setUseTransactionType(mem.transactionType); } catch (_) { /* ignore */ }
    }

    // Inventory is optional in Simple Mode — default none unless memory has a link
    if (typeof setUsePurchaseLinkMode === 'function') {
        if (mem?.purchaseId) {
            setUsePurchaseLinkMode('manual');
            const sel = document.getElementById('use-purchase-select');
            if (sel) sel.value = String(mem.purchaseId);
            const vapeSel = document.getElementById('use-vape-purchase-select');
            if (vapeSel) vapeSel.value = String(mem.purchaseId);
            if (typeof updateUsePurchaseLinkUI === 'function') updateUsePurchaseLinkUI();
        } else if (isSimpleExperienceMode(data)) {
            setUsePurchaseLinkMode('none');
        }
    }

    renderSimpleRecentAmountChips(substanceId, data);
}

function renderSimpleRecentAmountChips(substanceId, data = appData) {
    if (typeof document === 'undefined') return;
    const host = document.getElementById('sm-recent-amounts');
    if (!host) return;
    if (!substanceId) {
        host.innerHTML = '';
        host.classList.add('hidden');
        return;
    }
    const amounts = getRecentAmountsForSubstance(substanceId, data);
    const unit = typeof getSubstanceDisplayUnit === 'function'
        ? getSubstanceDisplayUnit(substanceId, data)
        : '';
    host.classList.remove('hidden');
    host.innerHTML = `
        <span class="sm-recent-label">Recent amounts</span>
        <div class="sm-recent-chips" role="group" aria-label="Recent amounts">
            ${amounts.map(amt => {
                const label = unit ? `${amt} ${unit}` : String(amt);
                return `<button type="button" class="sm-amount-chip" onclick="applySimpleQuickAmount(${amt})">${escapeHtml(label)}</button>`;
            }).join('')}
        </div>`;
}

function applySimpleQuickAmount(amount) {
    const n = Number(amount);
    if (!(n > 0)) return;
    const amountEl = document.getElementById('use-amount');
    if (amountEl) amountEl.value = String(n);
    const puffsEl = document.getElementById('use-vape-puffs-used');
    if (puffsEl && !puffsEl.closest('.hidden')) {
        puffsEl.value = String(n);
        if (typeof setVapeLogInputMode === 'function') setVapeLogInputMode('puffs');
        if (typeof updateVapeUsePreview === 'function') {
            try { updateVapeUsePreview(); } catch (_) { /* ignore */ }
        }
    }
    const cigEl = document.getElementById('use-cigarettes-smoked');
    if (cigEl && !cigEl.closest('.hidden')) cigEl.value = String(n);
}

function openSimpleQuickLog(substanceId) {
    const prefs = ensureSimpleModePrefs(appData);
    const sid = substanceId
        || prefs.lastQuickSubstanceId
        || prefs.progressSubstanceId
        || (typeof resolveDefaultSelectedSubstanceId === 'function' ? resolveDefaultSelectedSubstanceId() : null)
        || getActiveSubstances?.(appData)?.[0]?.id;

    if (typeof switchTab === 'function') switchTab('use-log-tab');
    if (typeof selectUseEntryType === 'function') selectUseEntryType('quick');
    if (typeof setUseTransactionType === 'function') setUseTransactionType('use');
    if (typeof setDefaultUseLogDateTime === 'function') setDefaultUseLogDateTime();

    if (sid) applyQuickLogMemoryToForm(sid, appData);

    // Focus amount for fastest path
    setTimeout(() => {
        const amount = document.getElementById('use-amount');
        const puffs = document.getElementById('use-vape-puffs-used');
        const target = (puffs && !puffs.closest?.('.hidden')) ? puffs : amount;
        target?.focus?.();
        target?.scrollIntoView?.({ block: 'center', behavior: 'smooth' });
    }, 60);

    // Expand form section if collapsed
    const formSection = document.querySelector('#use-log-tab [data-section="useLogForm"]');
    if (formSection?.classList.contains('collapsed') && typeof toggleSection === 'function') {
        try { toggleSection('useLogForm'); } catch (_) { /* ignore */ }
    }
}

function applySimpleLogFormLayout(data = appData) {
    if (typeof document === 'undefined') return;
    const page = document.getElementById('use-log-tab');
    if (!page) return;
    const simple = isSimpleExperienceMode(data);
    page.classList.toggle('sm-log-simple', simple);

    const summary = document.querySelector('#use-advanced-section .use-log-advanced-summary');
    if (summary) summary.textContent = simple ? 'More Options' : 'Advanced options';

    const slot = document.getElementById('sm-more-options-slot');
    const form = document.getElementById('use-log-form');
    if (slot && form) {
        const moreFields = [...form.querySelectorAll('.sm-log-more-field')];
        if (simple) {
            moreFields.forEach(el => {
                if (el.parentElement !== slot) slot.appendChild(el);
            });
        } else {
            // Restore near top of form (before core card) when leaving Simple
            const core = form.querySelector('.use-log-core-card');
            moreFields.forEach(el => {
                if (el.parentElement === slot && core) {
                    form.insertBefore(el, core);
                }
            });
        }
    }

    // Default inventory optional in Simple for new entries (not while editing)
    if (simple && typeof editingUseId !== 'undefined' && !editingUseId && typeof setUsePurchaseLinkMode === 'function') {
        const mode = getUsePurchaseLinkMode();
        if (mode === 'auto') setUsePurchaseLinkMode('none');
    }

    const substanceId = document.getElementById('use-substance')?.value
        || document.getElementById('use-log-substance')?.value;
    if (simple && substanceId) renderSimpleRecentAmountChips(substanceId, data);
    else {
        const host = document.getElementById('sm-recent-amounts');
        if (host) {
            host.innerHTML = '';
            host.classList.add('hidden');
        }
    }
}

function getProgressRangeBounds(rangeKey, data = appData) {
    const today = getLocalDateString();
    const key = EXPERIENCE_PROGRESS_RANGES.includes(String(rangeKey)) ? String(rangeKey) : '7';
    if (key === 'all') {
        const dates = (data.logs || []).map(l => l?.date).filter(Boolean).sort();
        return {
            key,
            label: 'All Time',
            startDate: dates[0] || today,
            endDate: today,
            days: Math.max(1, dates.length ? ((parseLocalDate(today) - parseLocalDate(dates[0])) / 86400000) + 1 : 1)
        };
    }
    const days = Number(key);
    const startDate = addDaysYYYYMMDD(today, -(days - 1));
    return { key, label: `Last ${days} Days`, startDate, endDate: today, days };
}

function buildSimpleProgressDataset(substanceId, rangeKey, data = appData) {
    const bounds = getProgressRangeBounds(rangeKey, data);
    const usedToday = getCanonicalUsageOnDate(substanceId, bounds.endDate, data);
    const rangeTotal = getCanonicalUsageInRange(substanceId, bounds.startDate, bounds.endDate, data);
    const dailyAvg = rangeTotal / Math.max(1, bounds.days);

    const prevEnd = addDaysYYYYMMDD(bounds.startDate, -1);
    const prevStart = addDaysYYYYMMDD(prevEnd, -(bounds.days - 1));
    const prevTotal = getCanonicalUsageInRange(substanceId, prevStart, prevEnd, data);
    const prevAvg = prevTotal / Math.max(1, bounds.days);
    const pctChange = prevAvg > 0 ? ((dailyAvg - prevAvg) / prevAvg) * 100 : null;

    const target = getSimpleTaperDailyTarget(substanceId, bounds.endDate, data);
    const status = resolveSimpleTaperStatus(usedToday, target);
    const streak = typeof computeRecoveryStreakDays === 'function'
        ? computeRecoveryStreakDays(substanceId)
        : { days: 0 };
    // Estimated spending: reuse the canonical use-cost engine for the selected range.
    const spend = typeof getCanonicalCostInRange === 'function'
        ? getCanonicalCostInRange(substanceId, bounds.startDate, bounds.endDate, data)
        : 0;

    const series = [];
    let cursor = bounds.startDate;
    let guard = 0;
    while (cursor <= bounds.endDate && guard < 400) {
        const amt = getCanonicalUsageOnDate(substanceId, cursor, data);
        const dayTarget = getSimpleTaperDailyTarget(substanceId, cursor, data);
        series.push({
            date: cursor,
            amount: amt,
            target: dayTarget,
            status: resolveSimpleTaperStatus(amt, dayTarget)
        });
        cursor = addDaysYYYYMMDD(cursor, 1);
        guard += 1;
    }

    return {
        substanceId,
        bounds,
        usedToday,
        dailyAvg,
        prevAvg,
        pctChange,
        target,
        status,
        streakDays: streak?.days ?? 0,
        spend,
        spendPeriodLabel: formatSimpleSpendPeriodLabel(bounds),
        displayName: getSimpleSubstanceDisplayName(substanceId, data),
        series,
        unit: typeof getSubstanceDisplayUnit === 'function'
            ? getSubstanceDisplayUnit(substanceId, data)
            : ''
    };
}

function renderSimpleProgressChart(series) {
    if (!series?.length) return '<p class="settings-hint">No use in this range.</p>';
    const max = Math.max(...series.map(s => s.amount), 0.0001);
    const bars = series.map(s => {
        const h = Math.max(4, Math.round((s.amount / max) * 100));
        return `<div class="sm-chart-bar-wrap" title="${escapeHtml(s.date)}: ${escapeHtml(String(s.amount))}">
            <div class="sm-chart-bar status-${escapeHtml(s.status.key)}" style="height:${h}%"></div>
        </div>`;
    }).join('');
    const startLabel = formatSimpleAxisDate(series[0].date);
    const endLabel = formatSimpleAxisDate(series[series.length - 1].date);
    return `<div class="sm-trend-card">
        <div class="sm-trend-chart" role="img" aria-label="Use trend">
            ${bars}
        </div>
        <div class="sm-trend-axis">
            <span>${escapeHtml(startLabel)}</span>
            <span>${escapeHtml(endLabel)}</span>
        </div>
    </div>`;
}

function renderSimpleProgressCalendar(dataset, monthStr) {
    const today = getLocalDateString();
    const base = monthStr && /^\d{4}-\d{2}/.test(monthStr)
        ? `${monthStr.slice(0, 7)}-01`
        : `${today.slice(0, 7)}-01`;
    const monthStart = parseLocalDate(base);
    if (!monthStart) return '';
    const year = monthStart.getFullYear();
    const month = monthStart.getMonth();
    const firstDow = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const byDate = new Map((dataset.series || []).map(s => [s.date, s]));
    const maxInMonth = Math.max(0.0001, ...[...byDate.values()].map(s => s.amount));

    const cells = [];
    for (let i = 0; i < firstDow; i++) cells.push('<div class="sm-cal-cell empty"></div>');
    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = formatYYYYMMDD(new Date(year, month, d));
        const point = byDate.get(dateStr);
        const amount = point?.amount ?? (dateStr >= dataset.bounds.startDate && dateStr <= dataset.bounds.endDate
            ? getCanonicalUsageOnDate(dataset.substanceId, dateStr)
            : 0);
        const status = point?.status || resolveSimpleTaperStatus(amount, point?.target ?? dataset.target);
        const intensity = amount > 0 ? Math.min(1, amount / maxInMonth) : 0;
        cells.push(`
            <button type="button" class="sm-cal-cell status-${escapeHtml(status.key)}"
                style="--sm-intensity:${intensity.toFixed(3)}"
                data-date="${escapeHtml(dateStr)}"
                onclick="openSimpleProgressDay('${escapeHtml(dateStr)}')"
                aria-label="${escapeHtml(dateStr)}">
                <span class="sm-cal-day">${d}</span>
            </button>`);
    }

    const label = monthStart.toLocaleString(undefined, { month: 'long', year: 'numeric' });
    const prevMonth = formatYYYYMMDD(new Date(year, month - 1, 1)).slice(0, 7);
    const nextMonth = formatYYYYMMDD(new Date(year, month + 1, 1)).slice(0, 7);
    return `
        <div class="sm-cal-card">
            <div class="sm-cal-header">
                <button type="button" class="sm-cal-nav" onclick="setSimpleProgressCalendarMonth('${prevMonth}')" aria-label="Previous month">‹</button>
                <h4>${escapeHtml(label)}</h4>
                <button type="button" class="sm-cal-nav" onclick="setSimpleProgressCalendarMonth('${nextMonth}')" aria-label="Next month">›</button>
            </div>
            <div class="sm-cal-dow">${['S','M','T','W','T','F','S'].map(d => `<span>${d}</span>`).join('')}</div>
            <div class="sm-cal-grid">${cells.join('')}</div>
        </div>`;
}

function setSimpleProgressCalendarMonth(monthStr) {
    persistSimpleModePrefs({ progressCalendarMonth: monthStr });
    renderSimpleProgress();
}

function openSimpleProgressDay(dateStr) {
    if (!dateStr) return;
    if (typeof setUseLogFilter === 'function') setUseLogFilter('all');
    if (typeof switchTab === 'function') switchTab('use-log-tab');
    // Prefer today filter when applicable
    const today = getLocalDateString();
    if (dateStr === today && typeof setUseLogFilter === 'function') setUseLogFilter('today');
    const list = document.getElementById('use-history-table-wrap') || document.getElementById('recent-use-list');
    list?.scrollIntoView?.({ behavior: 'smooth', block: 'start' });
}

function renderSimpleProgress(data = appData) {
    if (typeof document === 'undefined') return;
    const root = document.getElementById('simple-progress');
    if (!root) return;

    const prefs = ensureSimpleModePrefs(data);
    const substances = typeof getActiveSubstances === 'function'
        ? getActiveSubstances(data)
        : (data.substances || []).filter(s => s?.active !== false);
    let substanceId = prefs.progressSubstanceId
        || substances.find(s => s.isMain)?.id
        || substances[0]?.id;
    if (substanceId && !substances.some(s => s.id === substanceId)) {
        substanceId = substances[0]?.id || null;
    }
    if (!substanceId) {
        root.innerHTML = '<p class="settings-hint">Add a substance in Settings to see progress.</p>';
        return;
    }

    const dataset = buildSimpleProgressDataset(substanceId, prefs.progressRange, data);
    const month = prefs.progressCalendarMonth || dataset.bounds.endDate.slice(0, 7);
    const pctLabel = dataset.pctChange == null
        ? '—'
        : `${dataset.pctChange <= 0 ? '' : '+'}${Math.round(dataset.pctChange)}%`;
    const spendLabel = dataset.spend > 0
        ? (typeof formatMoneyOrDash === 'function'
            ? formatMoneyOrDash(dataset.spend)
            : `$${Number(dataset.spend).toFixed(2)}`)
        : '—';
    const spendPeriodLabel = dataset.spendPeriodLabel || formatSimpleSpendPeriodLabel(dataset.bounds);

    root.innerHTML = `
        <div class="sm-progress-header">
            <h2>Progress</h2>
            <p class="sm-progress-sub">A simple look at how things are going.</p>
        </div>
        <div class="sm-progress-controls">
            <label class="sm-field">
                <span>Substance</span>
                <select id="sm-progress-substance" onchange="onSimpleProgressSubstanceChange(this.value)">
                    ${substances.map(s => `<option value="${escapeHtml(s.id)}"${s.id === substanceId ? ' selected' : ''}>${escapeHtml(getSimpleSubstanceDisplayName(s, data))}</option>`).join('')}
                </select>
            </label>
            <div class="sm-range-pills" role="group" aria-label="Progress range">
                ${EXPERIENCE_PROGRESS_RANGES.map(r => {
                    const label = r === 'all' ? 'All Time' : `${r} Days`;
                    return `<button type="button" class="sm-range-btn${prefs.progressRange === r ? ' active' : ''}" onclick="setSimpleProgressRange('${r}')">${label}</button>`;
                }).join('')}
            </div>
        </div>
        <div class="sm-progress-metrics">
            <div class="sm-metric"><span class="sm-metric-label">Today</span><strong>${escapeHtml(formatSimpleUsage(substanceId, dataset.usedToday, data))}</strong></div>
            <div class="sm-metric"><span class="sm-metric-label">Daily average</span><strong>${escapeHtml(formatSimpleUsage(substanceId, dataset.dailyAvg, data))}</strong></div>
            <div class="sm-metric"><span class="sm-metric-label">Previous period</span><strong>${escapeHtml(formatSimpleUsage(substanceId, dataset.prevAvg, data))}</strong></div>
            <div class="sm-metric"><span class="sm-metric-label">Change</span><strong>${escapeHtml(pctLabel)}</strong></div>
            <div class="sm-metric"><span class="sm-metric-label">Break / streak</span><strong>${dataset.streakDays} day${dataset.streakDays === 1 ? '' : 's'}</strong></div>
            <div class="sm-metric"><span class="sm-metric-label">Taper</span><strong>${escapeHtml(dataset.status.label)}</strong></div>
            <div class="sm-metric"><span class="sm-metric-label">${escapeHtml(spendPeriodLabel)}</span><strong>${escapeHtml(spendLabel)}</strong></div>
        </div>
        <section class="sm-progress-section sm-trend-section">
            <div class="sm-section-head">
                <h3>Trend</h3>
                <p class="sm-section-sub">${escapeHtml(dataset.bounds.label)}</p>
            </div>
            ${renderSimpleProgressChart(dataset.series)}
        </section>
        <section class="sm-progress-section sm-cal-section">
            <div class="sm-section-head">
                <h3>Calendar</h3>
            </div>
            <div id="sm-progress-calendar">${renderSimpleProgressCalendar(dataset, month)}</div>
        </section>
        <div class="sm-progress-footer">
            <button type="button" class="sm-text-btn" onclick="openDetailedAnalyticsFromSimple()">View Detailed Analytics</button>
        </div>`;
}

function onSimpleProgressSubstanceChange(substanceId) {
    persistSimpleModePrefs({ progressSubstanceId: substanceId });
    renderSimpleProgress();
}

function setSimpleProgressRange(rangeKey) {
    persistSimpleModePrefs({ progressRange: String(rangeKey) });
    renderSimpleProgress();
}

function openDetailedAnalyticsFromSimple() {
    // Temporarily reveal advanced insights UI without forcing global Advanced mode
    const tab = document.getElementById('insights-calendar-tab');
    tab?.classList.add('sm-show-detailed-analytics');
    if (typeof setInsightsCalendarView === 'function') setInsightsCalendarView('overview');
    if (typeof updateStats === 'function') updateStats();
    document.getElementById('stats-summary-dashboard')?.scrollIntoView?.({ behavior: 'smooth' });
}

function applySimplePlanIntent(intentId) {
    const intent = SIMPLE_PLAN_INTENTS.find(i => i.id === intentId) || SIMPLE_PLAN_INTENTS[0];
    persistSimpleModePrefs({ planIntent: intent.id });

    if (intent.id === 'track-only') {
        const wizardOnly = document.getElementById('simple-plan-wizard');
        if (wizardOnly) wizardOnly.classList.add('hidden');
        alert('Track only keeps logging without a taper plan. You can create a plan later anytime.');
        return;
    }

    const wizard = document.getElementById('simple-plan-wizard');
    if (wizard) wizard.classList.add('hidden');
    if (typeof globalThis !== 'undefined') globalThis.__smPlanWizardBypass = true;
    try {
        if (typeof showNewTaperPlan === 'function') showNewTaperPlan();
    } finally {
        if (typeof globalThis !== 'undefined') globalThis.__smPlanWizardBypass = false;
    }

    // Prefill relevant fields based on intent
    if (intent.reductionType && typeof populateTaperReductionTypeSelect === 'function') {
        const substanceId = typeof getTaperSubstanceId === 'function' ? getTaperSubstanceId() : null;
        try {
            populateTaperReductionTypeSelect(substanceId, intent.reductionType);
            const typeEl = document.getElementById('taper-reduction-type');
            if (typeEl) typeEl.value = intent.reductionType;
            if (typeof toggleTaperPlanTypeFields === 'function') {
                toggleTaperPlanTypeFields({ selectedType: intent.reductionType, skipPrefill: false });
            }
        } catch (_) { /* ignore */ }
    }

    if (intent.id === 'quit-by-date') {
        const goalEl = document.getElementById('taper-goal-daily')
            || document.getElementById('goal-daily-average')
            || document.getElementById('taper-goal-avg');
        if (goalEl) goalEl.value = '0';
    }

    if (intent.id === 'custom' || intent.id === 'use-less' || intent.id === 'quit-by-date') {
        // Show advanced block for custom; keep simpler fields visible otherwise
    }

    applySimplePlanFormLayout();
    document.getElementById('taper-setup')?.scrollIntoView?.({ behavior: 'smooth', block: 'start' });
}

function openSimplePlanWizard() {
    const wizard = typeof document !== 'undefined'
        ? document.getElementById('simple-plan-wizard')
        : null;
    if (!wizard) {
        // Tests / missing DOM — open the real taper form without looping.
        if (typeof globalThis !== 'undefined') globalThis.__smPlanWizardBypass = true;
        try {
            if (typeof showNewTaperPlan === 'function') showNewTaperPlan();
        } finally {
            if (typeof globalThis !== 'undefined') globalThis.__smPlanWizardBypass = false;
        }
        return;
    }
    wizard.classList.remove('hidden');
    wizard.innerHTML = `
        <div class="sm-plan-wizard-card">
            <h3>What are you trying to do?</h3>
            <p class="settings-hint">We’ll only show the settings that match what you’re trying to do.</p>
            <div class="sm-plan-intent-grid">
                ${SIMPLE_PLAN_INTENTS.map(intent => `
                    <button type="button" class="sm-plan-intent-btn" onclick="applySimplePlanIntent('${intent.id}')">
                        <strong>${escapeHtml(intent.label)}</strong>
                        <span>${escapeHtml(intent.hint)}</span>
                    </button>`).join('')}
            </div>
            <button type="button" class="secondary-btn btn-sm" onclick="closeSimplePlanWizard()">Cancel</button>
        </div>`;
    wizard.scrollIntoView?.({ behavior: 'smooth', block: 'start' });
}

function closeSimplePlanWizard() {
    document.getElementById('simple-plan-wizard')?.classList.add('hidden');
}

function applySimplePlanFormLayout(data = appData) {
    if (typeof document === 'undefined') return;
    const page = document.getElementById('goals-plans-tab');
    if (!page) return;
    const simple = isSimpleExperienceMode(data);
    page.classList.toggle('sm-plan-simple', simple);
    const prefs = ensureSimpleModePrefs(data);
    const intent = prefs.planIntent;
    page.dataset.planIntent = intent || '';

    // Hide purchase-heavy / advanced blocks unless Custom or Advanced Mode
    const advancedBlocks = page.querySelectorAll('[data-sm-plan-advanced="true"]');
    advancedBlocks.forEach(el => {
        el.classList.toggle('sm-hidden-in-simple', simple && intent !== 'custom');
    });
}

function syncExperienceModeSettingsUI(data = appData) {
    if (typeof document === 'undefined') return;
    const mode = getExperienceMode(data);
    const select = document.getElementById('experience-mode');
    if (select) select.value = mode;
    document.querySelectorAll('[data-experience-mode]').forEach(btn => {
        const active = btn.getAttribute('data-experience-mode') === mode;
        btn.classList.toggle('active', active);
        btn.setAttribute('aria-pressed', active ? 'true' : 'false');
    });
}

function onExperienceModeChange(value) {
    const next = normalizeExperienceMode(value);
    const prev = getExperienceMode(appData);
    persistExperienceMode(next);
    syncExperienceModeSettingsUI();
    // Leaving Advanced → Simple while on Inventory: return Home (Inventory stays reachable via Settings → Advanced/More)
    if (prev === EXPERIENCE_MODE_ADVANCED && next === EXPERIENCE_MODE_SIMPLE
        && appData.settings?.activeTab === 'buy-tracker-tab'
        && typeof switchTab === 'function') {
        switchTab('dashboard-tab');
    }
}

function updateBottomNavForExperienceMode(data = appData) {
    if (typeof document === 'undefined' || !document.body?.classList) return;
    const simple = isSimpleExperienceMode(data);
    document.body.classList.toggle('experience-simple', simple);
    document.body.classList.toggle('experience-advanced', !simple);

    const inventoryBtn = document.querySelector('.bottom-nav .nav-btn[data-tab="buy-tracker-tab"]');
    if (inventoryBtn) {
        inventoryBtn.classList.toggle('sm-nav-hidden', simple);
        inventoryBtn.setAttribute('aria-hidden', simple ? 'true' : 'false');
    }

    const insightsBtn = document.querySelector('.bottom-nav .nav-btn[data-tab="insights-calendar-tab"]');
    if (insightsBtn) {
        const full = insightsBtn.querySelector('.nav-btn-label-full');
        const short = insightsBtn.querySelector('.nav-btn-label-short');
        if (full) full.textContent = simple ? 'Progress' : 'Insights & Calendar';
        if (short) short.textContent = simple ? 'Progress' : 'Insights';
    }

    const plansBtn = document.querySelector('.bottom-nav .nav-btn[data-tab="goals-plans-tab"]');
    if (plansBtn) {
        const full = plansBtn.querySelector('.nav-btn-label-full');
        const short = plansBtn.querySelector('.nav-btn-label-short');
        if (full) full.textContent = simple ? 'Plan' : 'Tapers';
        if (short) short.textContent = simple ? 'Plan' : 'Tapers';
    }
}

function applyExperienceMode(data = appData) {
    ensureExperienceMode(data);
    const simple = isSimpleExperienceMode(data);
    if (typeof document === 'undefined' || !document.body?.classList) return;

    document.body.classList.toggle('experience-simple', simple);
    document.body.classList.toggle('experience-advanced', !simple);

    updateBottomNavForExperienceMode(data);
    syncExperienceModeSettingsUI(data);
    applySimpleLogFormLayout(data);
    applySimplePlanFormLayout(data);

    const dash = document.getElementById('dashboard-tab');
    if (dash) {
        dash.classList.toggle('sm-home-active', simple);
        if (!simple) dash.classList.remove('sm-show-advanced-home');
    }

    const insights = document.getElementById('insights-calendar-tab');
    if (insights) {
        insights.classList.toggle('sm-progress-active', simple);
        if (!simple) insights.classList.remove('sm-show-detailed-analytics');
    }

    const gp = document.getElementById('goals-plans-tab');
    if (gp) {
        const title = gp.querySelector('.combined-page-header h2');
        if (title) title.textContent = simple ? 'Plan' : 'Tapers';
        const hint = gp.querySelector('.combined-page-header .settings-hint');
        if (hint) {
            hint.textContent = simple
                ? 'Set a simple plan for how you want use to change.'
                : 'Tapers define a gradual reduction path.';
        }
    }

    if (simple) {
        renderSimpleHome(data);
        renderSimpleProgress(data);
    }
}

function initExperienceMode() {
    ensureExperienceMode(appData);
    applyExperienceMode(appData);

    // Hook new-plan buttons in simple mode toward wizard
    if (typeof document !== 'undefined') {
        document.getElementById('sm-new-plan-btn')?.addEventListener('click', (e) => {
            e.preventDefault();
            openSimplePlanWizard();
        });
    }
}

function onExperienceModeAfterUseLogSave() {
    try {
        rememberQuickLogFromForm(appData);
    } catch (err) {
        console.warn('[experience-mode] quick log memory failed', err);
    }
    if (isSimpleExperienceMode()) {
        renderSimpleHome(appData);
        renderSimpleProgress(appData);
    }
}

function onExperienceModeTabChange(tabId) {
    if (!isSimpleExperienceMode()) return;
    if (tabId === 'dashboard-tab') {
        hideAdvancedHomeDashboard();
        renderSimpleHome(appData);
    } else if (tabId === 'insights-calendar-tab') {
        document.getElementById('insights-calendar-tab')?.classList.remove('sm-show-detailed-analytics');
        renderSimpleProgress(appData);
    } else if (tabId === 'use-log-tab') {
        applySimpleLogFormLayout(appData);
    } else if (tabId === 'goals-plans-tab') {
        applySimplePlanFormLayout(appData);
    } else if (tabId === 'settings-tab') {
        syncExperienceModeSettingsUI(appData);
    }
}


