let editingSubstanceId = null;
let editingPurchaseId = null;
const expandedPurchaseIds = new Set();
let editingUseId = null;
let taperEditingPlan = false;
/** True after Edit/Create form has been fully initialized from plan or defaults. */
let taperFormInitialized = false;
/** Serialized snapshot of form values after last clean init/save. */
let taperFormBaselineSnapshot = null;
let taperFormDirty = false;
let taperFormBeforeUnloadBound = false;

function slugify(name) {
    return name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || `substance-${Date.now()}`;
}

function uniqueSubstanceId(name, excludeId) {
    let base = slugify(name);
    let id = base;
    let n = 1;
    while (appData.substances.some(s => s.id === id && s.id !== excludeId)) {
        id = `${base}-${n++}`;
    }
    return id;
}

function migrateFromV1(v1) {
    const substances = getDefaultSubstances();
    const nameToId = { ...V1_NAME_TO_ID };
    const substanceSettings = { ...getDefaultSubstanceSettings() };

    const ensureSubstance = (name) => {
        if (nameToId[name]) return nameToId[name];
        let id = slugify(name);
        let n = 1;
        while (substances.some(s => s.id === id)) {
            id = `${slugify(name)}-${n++}`;
        }
        substances.push(createSubstance({
            id,
            name,
            icon: '📦',
            color: SUBSTANCE_COLORS[substances.length % SUBSTANCE_COLORS.length],
            units: ['units'],
            defaultUnit: 'units',
            costTrackingEnabled: true,
            taperTrackingEnabled: true
        }));
        nameToId[name] = id;
        if (v1.settings?.substanceSettings?.[name]) {
            substanceSettings[id] = { ...v1.settings.substanceSettings[name] };
        }
        return id;
    };

    Object.keys(v1.settings?.substanceSettings || {}).forEach(name => {
        const id = ensureSubstance(name);
        if (!substanceSettings[id]) substanceSettings[id] = { ...v1.settings.substanceSettings[name] };
    });

    (v1.customSubstances || []).forEach(name => ensureSubstance(name));

    const mapRef = (ref) => {
        if (!ref) return ref;
        if (nameToId[ref]) return nameToId[ref];
        return ensureSubstance(ref);
    };

    const logs = (v1.logs || []).map(log => ({
        ...log,
        substanceId: mapRef(log.substanceId || log.substance)
    }));

    const cravings = (v1.cravings || []).map(c => ({
        ...c,
        substanceId: mapRef(c.substanceId || c.substance)
    }));

    const taperPlans = {};
    Object.entries(v1.taperPlans || {}).forEach(([key, plan]) => {
        taperPlans[mapRef(key)] = plan;
    });

    const recoveryStreaks = {};
    Object.entries(v1.recoveryStreaks || {}).forEach(([key, val]) => {
        recoveryStreaks[mapRef(key)] = val;
    });

    const settingsSubstance = {};
    Object.entries(v1.settings?.substanceSettings || {}).forEach(([name, val]) => {
        settingsSubstance[mapRef(name)] = val;
    });

    const purchases = (v1.packPurchases || []).map(p => {
        const qty = (p.packsBought || 1) * (p.unitsPerPack || 1);
        return {
            id: p.id,
            substanceId: mapRef(p.substanceId || p.substance),
            date: p.date,
            time: '12:00',
            quantityBought: qty,
            quantity: qty,
            unit: 'units',
            totalCost: p.packPrice || 0,
            costPerUnit: qty > 0 ? (p.packPrice || 0) / qty : 0,
            remainingAmount: qty,
            isDepleted: false,
            store: p.store || '',
            paymentMethod: '',
            notes: p.notes || ''
        };
    });

    return {
        substances,
        logs,
        purchases,
        cravings,
        settings: {
            currency: '$',
            substanceSettings: { ...substanceSettings, ...settingsSubstance }
        },
        taperPlans,
        recoveryStreaks,
        privacy: v1.privacy || { ...defaultData.privacy }
    };
}

let appDataLoadedFromStorage = false;

function getDefaultAppData() {
    return typeof structuredClone === 'function'
        ? structuredClone(defaultData)
        : JSON.parse(JSON.stringify(defaultData));
}

function safeParseStoredJson(raw) {
    if (raw == null || raw === '') return null;
    try {
        const parsed = JSON.parse(raw);
        if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
        return parsed;
    } catch (err) {
        console.error('Failed to parse saved recovery data JSON:', err);
        return null;
    }
}

function loadAutoBackupAppData() {
    try {
        const raw = localStorage.getItem(AUTO_BACKUP_KEY);
        if (!raw) return null;
        const parsed = safeParseStoredJson(raw);
        const backupData = parsed?.data;
        const validation = validateBackupData(backupData);
        return validation.ok ? validation.data : null;
    } catch (err) {
        console.error('Failed to read automatic backup:', err);
        return null;
    }
}

function normalizeAppDataSafe(data) {
    try {
        return normalizeAppData(data);
    } catch (err) {
        console.error('Failed to normalize app data:', err);
        ensureAppDataSubstancesReady(data);
        return data;
    }
}

function ensureLoadedDataDefaults(data) {
    ensureAppDataSubstancesReady(data);
    if (!data.privacy) data.privacy = { ...defaultData.privacy };
    if (!data.recoveryStreaks) data.recoveryStreaks = {};
    return data;
}

function loadData() {
    const raw = localStorage.getItem(STORAGE_KEY);
    let data = null;

    if (raw) {
        data = safeParseStoredJson(raw);
        if (!data) {
            console.warn('Saved recovery data is invalid; trying automatic backup');
            data = loadAutoBackupAppData();
        }
        if (!data) {
            throw new Error('Invalid saved recovery data');
        }
        appDataLoadedFromStorage = true;
        console.log('Loaded saved recovery data');
        ensureLoadedDataDefaults(data);
        return normalizeAppDataSafe(data);
    }

    const v1 = localStorage.getItem(STORAGE_KEY_V1);
    if (v1) {
        const v1Data = safeParseStoredJson(v1);
        if (!v1Data) {
            throw new Error('Invalid v1 saved recovery data');
        }
        data = migrateFromV1(v1Data);
        appDataLoadedFromStorage = true;
        console.log('Loaded saved recovery data');
        ensureLoadedDataDefaults(data);
        return normalizeAppDataSafe(data);
    }

    console.log('No saved data found, using defaults');
    return normalizeAppDataSafe(getDefaultAppData());
}

function normalizeLegacyRefs(data) {
    data.logs?.forEach(log => {
        if (!log.substanceId && log.substance) log.substanceId = log.substance;
    });
    data.cravings?.forEach(c => {
        if (!c.substanceId && c.substance) c.substanceId = c.substance;
    });
}

function migrateUseLogsToLogs(data) {
    const legacy = data.useLogs;
    if (!Array.isArray(legacy) || !legacy.length) {
        delete data.useLogs;
        return;
    }
    data.logs = [...(data.logs || [])];
    const seen = new Set(data.logs.map(l => l.id));
    legacy.forEach(l => {
        if (l?.id != null && seen.has(l.id)) {
            const idx = data.logs.findIndex(x => x.id === l.id);
            if (idx >= 0) data.logs[idx] = l;
        } else if (l?.id != null) {
            data.logs.push(l);
            seen.add(l.id);
        } else {
            data.logs.push(l);
        }
    });
    delete data.useLogs;
}

function normalizeAppData(data) {
    normalizeLegacyRefs(data);
    migrateUseLogsToLogs(data);
    data.logs = data.logs || [];
    data.purchases = data.purchases || [];
    data.cravings = data.cravings || [];
    // Legacy Goal records are kept in-memory so old localStorage/imports load,
    // but they are never evaluated or shown. Do not convert them into tapers.
    data.goals = Array.isArray(data.goals) ? data.goals : [];
    data.budgets = Array.isArray(data.budgets) ? data.budgets : [];
    data.contacts = Array.isArray(data.contacts) ? data.contacts : [];

    ensurePurchaseIds(data);

    data.logs.forEach(log => {
        if (!log.type) log.type = log.endTime ? 'session' : 'quick';
        if (!log.startTime && log.time) log.startTime = log.time;
        const fallbackTs = log.timestamp || (log.date && (log.startTime || log.time)
            ? (parseLocalDateTime(log.date, log.startTime || log.time)?.toISOString() || null)
            : null);
        if (!log.createdAt) log.createdAt = fallbackTs || new Date().toISOString();
        if (!log.updatedAt) log.updatedAt = log.createdAt;
        if (!log.timestamp && fallbackTs) log.timestamp = fallbackTs;
        if (log.transactionType === 'session') log.transactionType = 'use';
        if (!log.transactionType) log.transactionType = 'use';
        const resolvedSubstanceId = normalizeSubstanceRef(getUseSubstanceId(log), data);
        if (resolvedSubstanceId) log.substanceId = resolvedSubstanceId;
        if (!Array.isArray(log.linkedPurchases)) log.linkedPurchases = [];
        syncLogPurchaseFields(log);
        syncGiftPartyFields(log);
        if (isLsdSubstanceId(getUseSubstanceId(log), data)) {
            if (!log.logMode) log.logMode = 'lsd_dose';
            if (log.ugUsed == null && log.amount != null) log.ugUsed = parseFloat(log.amount) || 0;
            if ((log.tabsUsed == null || log.tabsUsed === '') && log.ugPerTabAtTimeOfUse) {
                log.tabsUsed = getLsdLogTabsAmount(log);
            }
            if (log.estimatedCost == null) {
                const cost = computeLsdUseLogEstimatedCost(log, data);
                if (cost != null) log.estimatedCost = cost;
            }
        }
        if (isXanaxSubstanceId(getUseSubstanceId(log), data)) {
            if (!log.logMode) log.logMode = 'xanax_dose';
            if (log.pillsUsed == null && log.amount != null) log.pillsUsed = parseFloat(log.amount) || 0;
            if (log.mgUsed == null) log.mgUsed = getXanaxLogMgAmount(log);
            if (log.estimatedCost == null) {
                const cost = computeXanaxUseLogEstimatedCost(log, data);
                if (cost != null) log.estimatedCost = cost;
            }
        }
        normalizeUseLogWellness(log);
        if (hasLinkedSupply(log)) {
            log.inventoryAffects = true;
            log.supplyUnlinked = false;
        } else {
            captureLegacySupplyText(log);
            log.inventoryAffects = false;
            log.purchaseId = null;
            log.linkedPurchaseId = null;
            log.linkedPurchases = [];
            log.supplyUnlinked = true;
        }
    });

    (data.sessions || []).forEach(s => {
        data.logs.push({
            id: s.id,
            type: 'session',
            substanceId: s.substanceId || s.substance,
            date: s.date,
            startTime: s.startTime,
            endTime: s.endTime,
            amount: s.amount,
            unit: s.unit,
            count: s.count || 0,
            notes: s.notes || '',
            timestamp: s.timestamp || new Date().toISOString(),
            createdAt: s.createdAt || s.timestamp || new Date().toISOString(),
            updatedAt: s.updatedAt || s.createdAt || s.timestamp || new Date().toISOString()
        });
    });
    delete data.sessions;

    const legacyPurchases = data.packPurchases || [];
    legacyPurchases.forEach(p => {
        const qty = (p.packsBought || 1) * (p.unitsPerPack || 1);
        data.purchases.push({
            id: p.id,
            substanceId: p.substanceId || p.substance,
            date: p.date,
            time: p.time || '12:00',
            quantityBought: qty,
            quantity: qty,
            unit: 'units',
            totalCost: p.packPrice || 0,
            costPerUnit: qty > 0 ? (p.packPrice || 0) / qty : 0,
            remainingAmount: qty,
            isDepleted: false,
            store: p.store || '',
            paymentMethod: '',
            notes: p.notes || ''
        });
    });
    delete data.packPurchases;
    delete data.currentPack;

    data.purchases.forEach(p => {
        if (!p.substanceId && p.substance) p.substanceId = p.substance;
        if (!p.costPerUnit && p.quantity > 0) p.costPerUnit = p.totalCost / p.quantity;
        syncPurchaseAcquisitionFields(p);
    });

    migrateInventoryLinkedV1(data);
    if (!data.migrations?.purchaseIdLinkV2) {
        createAutoBackupFromData(data, 'migration');
    }
    migratePurchaseIdLinkV2(data);

    data.purchases.forEach(p => {
        migratePurchaseInventory(p, data.logs || [], data);
    });

    ensureAppDataSettings(data);
    ensureAppDataMigrations(data);
    normalizeSubstanceRecords(data);
    ensureDefaultSubstances(data);
    ensureDefaultSubstanceSettings(data);
    migrateSubstanceTrackingModes(data);
    migrateSubstanceNameDedupe(data);
    migrateRemoveCaffeine(data);
    migrateInventorySubstanceFields(data);
    normalizeMainSubstances(data);
    migrateTaperPlansSafely(data);
    migrateTaperPlansToV2IfNeeded(data);
    (data.taperPlansV2 || []).forEach(plan => {
        if (!plan?.substanceId) return;
        try {
            migrateTaperPlan(plan, plan.substanceId, data);
            syncTaperPlanDataForPlan(plan, data);
        } catch (err) {
            console.warn('taperPlansV2 normalize failed for', plan.id, err);
        }
    });
    recalculateAllBreaksForData(data);
    recalculateAllBuyBreaksForData(data);
    delete data.supportContacts;
    delete data.reasons;
    migrateVapeDataV1(data);
    repairVapeInventoryLinks(data);
    migrateLsdInventoryV1(data);
    migrateXanaxInventoryV1(data);
    migrateNicotineUnifyV1(data);
    migrateNicotineSubstanceRecordsV2(data);
    repairNicotineUnifiedData(data);
    migrateVapePercentSpreadV1(data);
    migrateInventoryStatusFields(data);
    repairDataConsistency(data);
    return data;
}

function ensureAppDataMigrations(data) {
    if (!data.migrations) data.migrations = {};
}

const COMPARE_PERIOD_PRESET_LABELS = {
    'past-30': 'Past 30 days vs previous 30 days',
    'past-3m': 'Past 3 months vs previous 3 months',
    'past-6m': 'Past 6 months vs previous 6 months',
    'past-12m': 'Past 12 months vs previous 12 months',
    'this-month': 'This month vs last month',
    'this-quarter': 'This quarter vs last quarter',
    'this-year': 'This year vs last year',
    custom: 'Custom period vs previous equal-length period'
};

function ensureComparePeriodsPrefs(data = appData) {
    if (!data.settings) {
        data.settings = JSON.parse(JSON.stringify(defaultData.settings));
    }
    const defaults = {
        preset: 'past-30',
        chartView: 'monthly',
        customStart: '',
        customEnd: ''
    };
    if (!data.settings.comparePeriods || typeof data.settings.comparePeriods !== 'object') {
        data.settings.comparePeriods = { ...defaults };
    } else {
        data.settings.comparePeriods = {
            ...defaults,
            ...data.settings.comparePeriods
        };
    }
    if (!COMPARE_PERIOD_PRESET_LABELS[data.settings.comparePeriods.preset]) {
        data.settings.comparePeriods.preset = defaults.preset;
    }
    if (!['monthly', 'weekly', 'rolling-30'].includes(data.settings.comparePeriods.chartView)) {
        data.settings.comparePeriods.chartView = defaults.chartView;
    }
    return data.settings.comparePeriods;
}

function loadComparePeriodsPrefsIntoState(data = appData) {
    const prefs = ensureComparePeriodsPrefs(data);
    statsComparePreset = prefs.preset;
    statsCompareChartView = prefs.chartView;
    statsCompareCustomStart = prefs.customStart || '';
    statsCompareCustomEnd = prefs.customEnd || '';
}

function persistComparePeriodsPrefs() {
    const prefs = ensureComparePeriodsPrefs(appData);
    prefs.preset = statsComparePreset;
    prefs.chartView = statsCompareChartView;
    prefs.customStart = statsCompareCustomStart;
    prefs.customEnd = statsCompareCustomEnd;
    saveData(appData);
}

function ensureAppDataSettings(data) {
    if (!data.settings) {
        data.settings = JSON.parse(JSON.stringify(defaultData.settings));
    }
    if (!data.settings.substanceSettings) {
        data.settings.substanceSettings = getDefaultSubstanceSettings();
    }
    data.settings.currency = '$';
    if (!data.settings.vapeTaperCountMode) {
        data.settings.vapeTaperCountMode = 'log-date';
    }
    // Spreading percent-left usage across days is now always enabled.
    // Migrate any existing user who previously turned it off.
    data.settings.spreadPercentLeftUsage = true;
    data.settings.appearanceViewMode = normalizeAppearanceViewMode(data.settings.appearanceViewMode);
    data.settings.appearanceZoom = normalizeAppearanceZoom(data.settings.appearanceZoom);
    data.settings.phoneViewZoom = normalizeAppearanceZoom(
        data.settings.phoneViewZoom ?? data.settings.appearanceZoom
    );
    data.settings.laptopViewZoom = normalizeAppearanceZoom(
        data.settings.laptopViewZoom ?? data.settings.appearanceZoom
    );
    data.settings.appearanceSpacing = normalizeAppearanceSpacing(data.settings.appearanceSpacing);
    if (data.settings.showInCellProgressBars === undefined) {
        data.settings.showInCellProgressBars = true;
    } else {
        data.settings.showInCellProgressBars = !!data.settings.showInCellProgressBars;
    }
    ensureTargetLinePrefs(data);
    ensurePreviousPeriodComparePrefs(data);
    if (data.settings.useCustomNamesInCsvExport === undefined) {
        data.settings.useCustomNamesInCsvExport = false;
    } else {
        data.settings.useCustomNamesInCsvExport = !!data.settings.useCustomNamesInCsvExport;
    }
    ensureConditionalColorRules(data);
    ensureInsightPrefs(data);
    ensureComparePeriodsPrefs(data);
    ensureRecoveryDashboardPrefs(data);
    ensureCalendarViewPrefs(data);
    ensureGoalSystemPrefs(data);
    ensureCombinedNavPrefs(data);
    migrateCombinedNavActiveTab(data);
    ensureFinancialAnalyticsPrefs(data);
    ensureBudgets(data);
    migrateFinancialAnalytics(data);
    ensurePurchaseAnalyticsPrefs(data);
    migratePurchaseAnalytics(data);
    ensureContactsMigrated(data);
    ensureContactsPrefs(data);
    ensureChartSystemPrefs(data);
    ensureWeedCompletePrefs(data);
    ensureRunningTotalsPrefs(data);
    ensureInsightsFilters(data);
    loadInsightsFiltersIntoState(data);
    ensureInsightsLayoutPrefs(data);
    applyInsightsSimplifyNavMigration(data);
    ensureExperienceMode(data);
    ensureInventorySourcesMigrated(data);
    ensureTableColumnSettings(data);
    ensureUseStatsConfig(data);
    ensureCollapsedSections(data);
    ensureTaperSuggestPrefs(data);
    if (data.settings.activeTab === 'history-tab'
        || data.settings.activeTab === 'history') {
        data.settings.activeTab = 'use-log-tab';
    }
    if (data.settings.activeTab === 'contacts-tab'
        || data.settings.activeTab === 'contacts'
        || data.settings.activeTab === 'friends') {
        data.settings.activeTab = 'settings-tab';
    }
}

