function loadColumnSettingsStore() {
    try {
        const raw = localStorage.getItem(COLUMN_SETTINGS_STORAGE_KEY);
        return raw ? JSON.parse(raw) : {};
    } catch {
        return {};
    }
}

function saveColumnSettingsStore(store) {
    localStorage.setItem(COLUMN_SETTINGS_STORAGE_KEY, JSON.stringify(store));
}

function isValidPurchaseHistoryColumnSettings(stored) {
    if (!stored || typeof stored !== 'object' || Array.isArray(stored)) return false;
    if (!Array.isArray(stored.order) || !stored.order.length) return false;
    if (stored.visible != null && (typeof stored.visible !== 'object' || Array.isArray(stored.visible))) {
        return false;
    }
    if (stored.widths != null && (typeof stored.widths !== 'object' || Array.isArray(stored.widths))) {
        return false;
    }
    const allowed = new Set(TABLE_COLUMN_DEFAULTS.purchaseHistory?.order || []);
    return stored.order.some(id => allowed.has(id));
}

function loadPurchaseHistoryColumnSettingsRaw() {
    try {
        const raw = localStorage.getItem(PURCHASE_HISTORY_COLUMNS_STORAGE_KEY);
        if (!raw) return null;
        return JSON.parse(raw);
    } catch {
        return null;
    }
}

function savePurchaseHistoryColumnSettings(config) {
    const normalized = normalizeStoredColumnSettings('purchaseHistory', config);
    try {
        localStorage.setItem(PURCHASE_HISTORY_COLUMNS_STORAGE_KEY, JSON.stringify(normalized));
    } catch (_) { /* ignore quota */ }
    // Keep legacy shared-store mirror for older builds; never treat it as filter state.
    try {
        const store = loadColumnSettingsStore();
        store.purchaseHistory = normalized;
        saveColumnSettingsStore(store);
    } catch (_) { /* ignore */ }
    return normalized;
}

/**
 * Load Purchase History column presentation settings only.
 * Corrupted values fall back to defaults without touching purchases or inventory filters.
 */
function loadPurchaseHistoryColumnSettings() {
    const dedicated = loadPurchaseHistoryColumnSettingsRaw();
    if (isValidPurchaseHistoryColumnSettings(dedicated)) {
        return normalizeStoredColumnSettings('purchaseHistory', dedicated);
    }
    if (dedicated != null) {
        // Corrupt dedicated key — replace with defaults.
        const defaults = getDefaultColumnSettings('purchaseHistory');
        try {
            localStorage.setItem(PURCHASE_HISTORY_COLUMNS_STORAGE_KEY, JSON.stringify(defaults));
        } catch (_) { /* ignore */ }
        return defaults;
    }
    // Migrate once from shared columnSettings store when dedicated key is missing.
    try {
        const store = loadColumnSettingsStore();
        if (isValidPurchaseHistoryColumnSettings(store.purchaseHistory)) {
            return savePurchaseHistoryColumnSettings(store.purchaseHistory);
        }
    } catch (_) { /* ignore */ }
    return savePurchaseHistoryColumnSettings(getDefaultColumnSettings('purchaseHistory'));
}

function migratePurchaseHistoryColumnSettingsIfNeeded() {
    const dedicated = loadPurchaseHistoryColumnSettingsRaw();
    if (isValidPurchaseHistoryColumnSettings(dedicated)) return;
    loadPurchaseHistoryColumnSettings();
}

const COLUMN_CUSTOM_NAME_MAX_LENGTH = 40;

function getDefaultColumnSettings(tableKey) {
    const defaults = TABLE_COLUMN_DEFAULTS[tableKey];
    if (!defaults) return { order: [], visible: {}, widths: {}, customNames: {} };
    const visible = {};
    defaults.order.forEach(id => {
        visible[id] = !(defaults.hidden || []).includes(id);
    });
    return {
        order: [...defaults.order],
        visible,
        widths: { ...(defaults.widths || {}) },
        customNames: {}
    };
}

function sanitizeCustomColumnName(raw) {
    if (raw == null) return '';
    const trimmed = String(raw).trim().replace(/\s+/g, ' ');
    if (!trimmed) return '';
    return trimmed.slice(0, COLUMN_CUSTOM_NAME_MAX_LENGTH);
}

function normalizeCustomNamesMap(tableKey, storedNames, allowedIds = null) {
    const defaults = TABLE_COLUMN_DEFAULTS[tableKey];
    const allowed = new Set(allowedIds || defaults?.order || []);
    const out = {};
    if (!storedNames || typeof storedNames !== 'object' || Array.isArray(storedNames)) return out;
    Object.entries(storedNames).forEach(([id, val]) => {
        const mapped = tableKey === 'useHistory' ? remapUseHistoryColumnId(id) : id;
        if (!allowed.has(mapped)) return;
        const cleaned = sanitizeCustomColumnName(val);
        if (cleaned) out[mapped] = cleaned;
    });
    return out;
}

function getUseCustomNamesInCsvExport(data = appData) {
    ensureAppDataSettings(data);
    return !!data.settings.useCustomNamesInCsvExport;
}

function setUseCustomNamesInCsvExport(enabled) {
    ensureAppDataSettings(appData);
    appData.settings.useCustomNamesInCsvExport = !!enabled;
    saveData(appData);
    const el = document.getElementById('settings-use-custom-names-in-csv');
    if (el) el.checked = !!enabled;
}

function syncUseCustomNamesInCsvToggle() {
    const el = document.getElementById('settings-use-custom-names-in-csv');
    if (el) el.checked = getUseCustomNamesInCsvExport();
}

function remapUseHistoryColumnId(colId) {
    return USE_HISTORY_COLUMN_ALIASES[colId] || colId;
}

function normalizeStoredColumnSettings(tableKey, stored) {
    const defaults = TABLE_COLUMN_DEFAULTS[tableKey];
    if (!defaults) return getDefaultColumnSettings(tableKey);
    const base = getDefaultColumnSettings(tableKey);

    let order = Array.isArray(stored?.order)
        ? stored.order.map(id => tableKey === 'useHistory' ? remapUseHistoryColumnId(id) : id)
            .filter(id => defaults.order.includes(id))
        : [];
    defaults.order.forEach(id => {
        if (!order.includes(id)) order.push(id);
    });

    const visible = { ...base.visible };
    if (stored?.visible && typeof stored.visible === 'object') {
        Object.entries(stored.visible).forEach(([id, val]) => {
            const mapped = tableKey === 'useHistory' ? remapUseHistoryColumnId(id) : id;
            if (defaults.order.includes(mapped)) visible[mapped] = !!val;
        });
    } else if (Array.isArray(stored?.hidden)) {
        stored.hidden.forEach(id => {
            const mapped = tableKey === 'useHistory' ? remapUseHistoryColumnId(id) : id;
            if (visible[mapped] !== undefined) visible[mapped] = false;
        });
    }

    (TABLE_COLUMNS_REQUIRED[tableKey] || []).forEach(id => {
        visible[id] = true;
    });

    const widths = { ...base.widths };
    if (stored?.widths && typeof stored.widths === 'object') {
        defaults.order.forEach(id => {
            if (stored.widths[id] != null) widths[id] = stored.widths[id];
        });
    }

    const customNames = normalizeCustomNamesMap(tableKey, stored?.customNames, defaults.order);
    return { order, visible, widths, customNames };
}

function migrateLegacyTableColumnsToLocalStorageIfNeeded(data = appData) {
    const store = loadColumnSettingsStore();
    if (store.__migratedFromAppData) return;
    const legacy = data?.settings?.tableColumns;
    if (legacy && typeof legacy === 'object') {
        Object.keys(TABLE_COLUMN_DEFAULTS).forEach(tableKey => {
            if (store[tableKey]) return;
            const old = legacy[tableKey];
            if (!old) return;
            store[tableKey] = normalizeStoredColumnSettings(tableKey, {
                order: old.order,
                hidden: old.hidden,
                widths: old.widths
            });
        });
    }
    store.__migratedFromAppData = true;
    saveColumnSettingsStore(store);
}

function ensureTableColumnSettings(data) {
    migrateLegacyTableColumnsToLocalStorageIfNeeded(data);
    migratePurchaseHistoryColumnSettingsIfNeeded();
    const store = loadColumnSettingsStore();
    Object.keys(TABLE_COLUMN_DEFAULTS).forEach(tableKey => {
        if (tableKey === 'purchaseHistory') {
            // Purchase History columns live in a dedicated key; mirror for compatibility only.
            store.purchaseHistory = loadPurchaseHistoryColumnSettings();
            return;
        }
        if (!store[tableKey]) {
            store[tableKey] = getDefaultColumnSettings(tableKey);
        } else {
            store[tableKey] = normalizeStoredColumnSettings(tableKey, store[tableKey]);
        }
    });
    saveColumnSettingsStore(store);
}

function resolveColumnStorageKey(tableKey, variantKey = null) {
    if (variantKey) return `${tableKey}::${variantKey}`;
    return tableKey;
}

/** Universal weekly taper columns shown for every substance. */
const TAPER_BY_WEEK_UNIVERSAL_COLUMNS = [
    'week', 'dates', 'planned', 'used', 'difference', 'status',
    'sessions', 'runningPlanned', 'runningUsed', 'remaining'
];

/**
 * Substance-family optional columns for Plan → Customize Weekly Table Columns.
 * Only columns that exist in TABLE_COLUMN_DEFAULTS.taperByWeek are listed.
 */
const TAPER_BY_WEEK_FAMILY_EXTRA_COLUMNS = {
    cocaine: [
        'bought', 'buyDiff', 'runningAmountBought', 'runningAmountSpent',
        'buyPlanned', 'spendPlanned', 'spent', 'spendDiff', 'runningPlannedSpend',
        'buyInterval', 'weeklyBuyCapStatus', 'weeklySpendCapStatus',
        'monthlyBuyCapStatus', 'monthlySpendCapStatus',
        'purchaseOverallStatus', 'targets',
        'buyAmountStatus', 'spendAmountStatus'
    ],
    nicotine: [
        'bought', 'runningAmountBought', 'buyInterval', 'vapeLifespans', 'lifespanGoal',
        'nicotineStrength', 'estimatedNicotineUsed', 'spendPlanned', 'spent', 'runningAmountSpent',
        'nicotineFreeHours', 'giftedPuffs', 'dailyTarget'
    ],
    alcohol: [
        'avgPerDay', 'spent', 'runningAmountSpent'
    ],
    cannabis: [
        'bought', 'runningAmountBought', 'spent', 'runningAmountSpent',
        'buyInterval', 'avgPerDay'
    ],
    lsd: [
        'avgPerDay'
    ],
    xanax: [
        'avgPerDay'
    ],
    generic: [
        'bought', 'runningAmountBought', 'spent', 'runningAmountSpent',
        'avgPerDay', 'dailyTarget', 'reductionFromPrior'
    ]
};

const TAPER_BY_WEEK_FAMILY_LABELS = {
    cocaine: 'Cocaine Taper',
    nicotine: 'Nicotine Taper',
    alcohol: 'Alcohol Taper',
    cannabis: 'Cannabis Taper',
    lsd: 'LSD Taper',
    xanax: 'Xanax Taper',
    generic: 'Taper'
};

function getTaperByWeekColumnFamily(substanceId, data = appData) {
    if (isNicotineTrackingMode(substanceId, data)) return 'nicotine';
    if (isAlcoholTrackingMode(substanceId, data)) return 'alcohol';
    if (isWeedTrackingMode(substanceId, data)) return 'cannabis';
    if (isLsdSubstanceId(substanceId, data)) return 'lsd';
    if (isXanaxSubstanceId(substanceId, data)) return 'xanax';
    if (isCokeSubstanceId(substanceId) || isPowderTrackingMode(substanceId, data)) return 'cocaine';
    return 'generic';
}

function getTaperByWeekColumnFamilyLabel(familyOrSubstanceId, data = appData) {
    const family = TAPER_BY_WEEK_FAMILY_LABELS[familyOrSubstanceId]
        ? familyOrSubstanceId
        : getTaperByWeekColumnFamily(familyOrSubstanceId, data);
    return TAPER_BY_WEEK_FAMILY_LABELS[family] || TAPER_BY_WEEK_FAMILY_LABELS.generic;
}

/**
 * Weekly Table column preferences are scoped per substance (not family/plan).
 * Family is still used for catalog membership and migration from older keys.
 */
function getTaperByWeekColumnVariantKey(substanceId, plan) {
    return substanceId || plan?.substanceId || getTaperSubstanceId() || null;
}

function getTaperByWeekColumnCatalog(substanceId, plan = null, data = appData) {
    const family = getTaperByWeekColumnFamily(substanceId || plan?.substanceId, data);
    const allowed = new Set([
        ...TAPER_BY_WEEK_UNIVERSAL_COLUMNS,
        ...(TAPER_BY_WEEK_FAMILY_EXTRA_COLUMNS[family] || TAPER_BY_WEEK_FAMILY_EXTRA_COLUMNS.generic)
    ]);
    return TABLE_COLUMN_DEFAULTS.taperByWeek.order.filter(id => allowed.has(id));
}

function filterTaperByWeekColumnSettingsToCatalog(settings, substanceId, plan = null) {
    const catalog = getTaperByWeekColumnCatalog(substanceId, plan);
    const catalogSet = new Set(catalog);
    const order = [];
    (settings?.order || []).forEach(id => {
        if (catalogSet.has(id) && !order.includes(id)) order.push(id);
    });
    catalog.forEach(id => {
        if (!order.includes(id)) order.push(id);
    });
    const visible = {};
    order.forEach(id => {
        visible[id] = settings?.visible?.[id] !== false;
    });
    (TABLE_COLUMNS_REQUIRED.taperByWeek || []).forEach(id => {
        if (catalogSet.has(id)) visible[id] = true;
    });
    const widths = {};
    order.forEach(id => {
        if (settings?.widths?.[id] != null) widths[id] = settings.widths[id];
        else if (TABLE_COLUMN_DEFAULTS.taperByWeek.widths?.[id] != null) {
            widths[id] = TABLE_COLUMN_DEFAULTS.taperByWeek.widths[id];
        }
    });
    const customNames = normalizeCustomNamesMap('taperByWeek', settings?.customNames, order);
    return { order, visible, widths, customNames };
}

function getDefaultTaperByWeekColumnSettings(substanceId, plan) {
    const catalog = getTaperByWeekColumnCatalog(substanceId, plan);
    const base = getDefaultColumnSettings('taperByWeek');
    const visible = {};
    catalog.forEach(id => {
        visible[id] = base.visible[id] !== false;
    });
    // Keep most optional columns hidden by default; reveal purchase-relevant ones by plan type.
    catalog.forEach(id => {
        if ((TABLE_COLUMNS_REQUIRED.taperByWeek || []).includes(id)) {
            visible[id] = true;
            return;
        }
        if (TAPER_BY_WEEK_UNIVERSAL_COLUMNS.includes(id)
            && !['sessions', 'runningPlanned', 'runningUsed', 'remaining'].includes(id)) {
            visible[id] = true;
            return;
        }
        visible[id] = false;
    });
    if (isNicotineVapePurchasePlan(plan)) {
        ['bought', 'runningAmountBought', 'buyInterval', 'vapeLifespans', 'lifespanGoal',
            'spendPlanned', 'spent', 'runningAmountSpent', 'giftedPuffs']
            .forEach(id => { if (id in visible) visible[id] = true; });
    } else if (isReduceBuyingPlan(plan)) {
        ['targets', 'bought', 'spent', 'runningAmountBought', 'runningAmountSpent']
            .forEach(id => { if (id in visible) visible[id] = true; });
    } else if (supportsPurchaseTaper(substanceId) || getSubstance(substanceId)?.costTrackingEnabled) {
        const family = getTaperByWeekColumnFamily(substanceId);
        if (family === 'cocaine' || family === 'cannabis' || family === 'generic') {
            ['bought', 'runningAmountBought', 'runningAmountSpent', 'buyPlanned', 'spendPlanned', 'purchaseOverallStatus']
                .forEach(id => { if (id in visible) visible[id] = true; });
        } else if (family === 'nicotine') {
            ['bought', 'runningAmountBought', 'buyInterval', 'vapeLifespans']
                .forEach(id => { if (id in visible) visible[id] = true; });
        } else if (family === 'alcohol') {
            ['avgPerDay', 'spent', 'runningAmountSpent']
                .forEach(id => { if (id in visible) visible[id] = true; });
        }
    }
    if (isAutoSpendFromCostPerGramEnabled(plan)) {
        ['spendPlanned', 'spent', 'spendDiff', 'runningPlannedSpend', 'runningAmountSpent', 'spendAmountStatus']
            .forEach(id => { if (id in visible) visible[id] = true; });
    }
    return filterTaperByWeekColumnSettingsToCatalog({ order: catalog, visible, widths: base.widths }, substanceId, plan);
}

function findLegacyTaperByWeekColumnSettings(store, family) {
    if (!store || !family) return null;
    const prefix = 'taperByWeek::';
    const matches = Object.keys(store).filter(key => {
        if (!key.startsWith(prefix) || key === `${prefix}${family}`) return false;
        const variant = key.slice(prefix.length);
        // Legacy keys were `${substanceId}__${reductionType}`.
        if (!variant.includes('__')) return false;
        const substanceId = variant.split('__')[0];
        return getTaperByWeekColumnFamily(substanceId) === family;
    });
    if (!matches.length) return null;
    return store[matches[0]] || null;
}

/** Resolve older Weekly Table prefs (family key or substance__planType) for migration. */
function findMigratableTaperByWeekColumnSettings(store, substanceId) {
    if (!store || !substanceId) return null;
    const prefix = 'taperByWeek::';
    const substanceKey = `${prefix}${substanceId}`;
    if (store[substanceKey]) return null;

    const family = getTaperByWeekColumnFamily(substanceId);
    const familyKey = `${prefix}${family}`;
    if (family && store[familyKey]) return store[familyKey];

    const substanceLegacy = Object.keys(store).filter(key => {
        if (!key.startsWith(prefix) || key === substanceKey) return false;
        const variant = key.slice(prefix.length);
        return variant === substanceId || variant.startsWith(`${substanceId}__`);
    });
    if (substanceLegacy.length) return store[substanceLegacy[0]] || null;

    return findLegacyTaperByWeekColumnSettings(store, family);
}

function getTaperByWeekColumnLabel(colId, plan, substanceId) {
    const labels = TABLE_COLUMN_LABELS.taperByWeek;
    const family = getTaperByWeekColumnFamily(substanceId);
    if (colId === 'runningAmountBought') {
        if (family === 'nicotine') return 'Monthly Running Vapes Bought';
        if (family === 'cannabis') return 'Running Grams';
        return labels.runningAmountBought;
    }
    if (colId === 'runningAmountSpent') {
        if (family === 'nicotine') return 'Running Monthly Spending';
        if (family === 'alcohol' || family === 'cannabis') return 'Running Cost';
        return labels.runningAmountSpent;
    }
    if (colId === 'bought') {
        if (family === 'cannabis') return 'Grams';
        if (family === 'nicotine') return 'Vapes Bought';
        return labels.bought;
    }
    if (colId === 'spent') {
        if (family === 'nicotine') return 'Actual Spending';
        if (family === 'alcohol' || family === 'cannabis') return 'Cost';
        return labels.spent;
    }
    if (colId === 'spendPlanned') {
        if (family === 'nicotine') return 'Spending Goal';
        return labels.spendPlanned;
    }
    if (colId === 'buyInterval') {
        if (family === 'nicotine') return 'Days Between Purchases';
        if (family === 'cannabis') return 'Breaks';
        return labels.buyInterval;
    }
    if (colId === 'vapeLifespans') {
        if (family === 'nicotine') return 'Vape Lifespan';
        return labels.vapeLifespans;
    }
    if (colId === 'avgPerDay') {
        if (family === 'nicotine') return 'Avg Puffs/Day';
        if (family === 'alcohol') return 'Avg Drinks/Day';
        if (family === 'xanax') return 'Avg mg/day';
        if (family === 'lsd') return 'Avg ug/session';
        return labels.avgPerDay;
    }
    if (colId === 'planned') {
        if (isNicotineVapePurchasePlan(plan) || family === 'nicotine') return 'Puff Target';
        if (isReduceNicotinePlan(plan)) return 'Target mg/mL';
        if (family === 'alcohol') return 'Drinks Planned';
        if (family === 'lsd') return 'Tabs Planned';
        if (family === 'xanax') return 'Pills Planned';
    }
    if (colId === 'used') {
        if (isNicotineVapePurchasePlan(plan) || family === 'nicotine') return 'Personal Puffs';
        if (isReduceBuyingPlan(plan)) return 'Vapes bought';
        if (isReduceNicotinePlan(plan)) return 'Current mg/mL';
        if (family === 'alcohol') return 'Drinks Used';
        if (family === 'lsd') return 'Tabs Used';
        if (family === 'xanax') return 'Pills Used';
        if (family === 'nicotine') return 'Puffs Used';
        if (family === 'cannabis') return 'Grams';
    }
    if (colId === 'runningUsed') {
        if (family === 'nicotine') return 'Running Puffs';
        if (family === 'alcohol') return 'Running Drinks';
        if (family === 'lsd') return 'Running Tabs';
        if (family === 'xanax') return 'Running Pills';
        if (family === 'cannabis') return 'Running Grams';
    }
    if (colId === 'runningPlanned') {
        if (family === 'alcohol') return 'Running Weekly Drinks';
        if (family === 'lsd') return 'Running Tabs';
        if (family === 'xanax') return 'Running Pills';
    }
    if (colId === 'difference' && isReduceNicotinePlan(plan)) return 'Strength +/-';
    return getTableColumnLabelForSubstance('taperByWeek', colId, substanceId)
        || labels[colId]
        || colId;
}

function getTableColumnConfig(tableKey, variantKey = null) {
    ensureTableColumnSettings(appData);
    if (tableKey === 'purchaseHistory') {
        return loadPurchaseHistoryColumnSettings();
    }
    const store = loadColumnSettingsStore();
    const storageKey = resolveColumnStorageKey(tableKey, variantKey);
    if (store[storageKey]) {
        const normalized = normalizeStoredColumnSettings(tableKey, store[storageKey]);
        if (tableKey === 'taperByWeek' && variantKey) {
            const substanceId = resolveTaperByWeekColumnSubstanceId(variantKey);
            return filterTaperByWeekColumnSettingsToCatalog(
                normalized,
                substanceId,
                getSelectedTaperPlan()
            );
        }
        if (tableKey === 'useHistory' && variantKey) {
            const substanceId = getUseLogViewSubstanceId();
            const family = getUseHistoryColumnFamily(substanceId);
            const sid = family === variantKey
                ? substanceId
                : ((appData.substances || []).find(s => getUseHistoryColumnFamily(s.id) === variantKey)?.id
                    || substanceId);
            return filterUseHistoryColumnSettingsToCatalog(normalized, sid);
        }
        return normalized;
    }
    if (tableKey === 'taperByWeek' && variantKey) {
        const substanceId = resolveTaperByWeekColumnSubstanceId(variantKey);
        const migratable = findMigratableTaperByWeekColumnSettings(store, substanceId);
        if (migratable) {
            const migrated = filterTaperByWeekColumnSettingsToCatalog(
                normalizeStoredColumnSettings(tableKey, migratable),
                substanceId,
                getSelectedTaperPlan()
            );
            // Persist under the substance-scoped key so refresh/restart keep widths.
            saveTableColumnConfig(tableKey, migrated, substanceId);
            return migrated;
        }
        return getDefaultTaperByWeekColumnSettings(substanceId, getSelectedTaperPlan() || {
            substanceId,
            reductionType: 'reduce-amount'
        });
    }
    if (tableKey === 'useHistory' && variantKey) {
        // Fall back to unscoped useHistory settings once, then filter to family catalog.
        if (store.useHistory) {
            const substanceId = getUseLogViewSubstanceId();
            const sid = getUseHistoryColumnFamily(substanceId) === variantKey
                ? substanceId
                : ((appData.substances || []).find(s => getUseHistoryColumnFamily(s.id) === variantKey)?.id
                    || substanceId);
            return filterUseHistoryColumnSettingsToCatalog(
                normalizeStoredColumnSettings(tableKey, store.useHistory),
                sid
            );
        }
        const substanceId = getUseLogViewSubstanceId();
        const sid = getUseHistoryColumnFamily(substanceId) === variantKey
            ? substanceId
            : ((appData.substances || []).find(s => getUseHistoryColumnFamily(s.id) === variantKey)?.id
                || substanceId);
        return getDefaultUseHistoryColumnSettings(sid);
    }
    return store[tableKey] || getDefaultColumnSettings(tableKey);
}

function getTaperSubstanceIdForColumnFamily(family) {
    const currentId = getTaperSubstanceId();
    if (getTaperByWeekColumnFamily(currentId) === family) return currentId;
    const match = (appData.substances || []).find(sub => getTaperByWeekColumnFamily(sub.id) === family);
    return match?.id || currentId || family;
}

/** Variant keys are substance ids; accept legacy family keys for older callers/tests. */
function resolveTaperByWeekColumnSubstanceId(variantKey) {
    if (!variantKey) return getTaperSubstanceId();
    if ((appData.substances || []).some(s => s.id === variantKey)) return variantKey;
    if (TAPER_BY_WEEK_FAMILY_LABELS[variantKey]) {
        return getTaperSubstanceIdForColumnFamily(variantKey);
    }
    return variantKey;
}

function getEffectiveColumnOrder(tableKey, variantKey = null) {
    const defaults = TABLE_COLUMN_DEFAULTS[tableKey];
    const config = getTableColumnConfig(tableKey, variantKey);
    const visible = config.visible || {};
    const required = new Set(TABLE_COLUMNS_REQUIRED[tableKey] || []);
    const order = [...config.order];
    defaults.order.forEach(id => {
        if (!order.includes(id)) order.push(id);
    });
    let allowedIds = defaults.order;
    if (tableKey === 'taperByWeek') {
        const substanceId = variantKey
            ? resolveTaperByWeekColumnSubstanceId(variantKey)
            : getTaperSubstanceId();
        allowedIds = getTaperByWeekColumnCatalog(substanceId, getSelectedTaperPlan());
    }
    const allowed = new Set(allowedIds);
    return order.filter(id => allowed.has(id) && (visible[id] !== false || required.has(id)));
}

function saveTableColumnConfig(tableKey, config, variantKey = null) {
    if (tableKey === 'purchaseHistory') {
        savePurchaseHistoryColumnSettings(config);
        return;
    }
    const store = loadColumnSettingsStore();
    const storageKey = resolveColumnStorageKey(tableKey, variantKey);
    store[storageKey] = normalizeStoredColumnSettings(tableKey, config);
    saveColumnSettingsStore(store);
}

function estimateColumnMinWidthFromLabel(label) {
    const text = String(label || '').trim();
    if (!text) return 72;
    // Approximate 0.82rem tabular header glyphs + cell padding/resize gutter.
    return Math.min(220, Math.max(72, Math.ceil(text.length * 7.2) + 28));
}

function getTableColumnMinWidth(tableKey, colId, variantKey = null) {
    if (colId === 'actions') return 150;
    if (colId === 'select') return 40;
    if (colId === 'notes') return 120;
    // Weekly Table: saved widths control layout. Keep only a small floor so
    // Customize → Width values are not overridden by label-length estimates.
    if (tableKey === 'taperByWeek') return 48;
    return 60;
}

function getCustomizableTableColumnLayout(tableKey, columnIds, variantKey = null) {
    return (columnIds || []).map(colId => {
        const minWidthPx = getTableColumnMinWidth(tableKey, colId, variantKey);
        const savedWidth = getTableColumnWidthPx(tableKey, colId, variantKey);
        // Saved/default width is authoritative (clamped only to the absolute floor).
        const widthPx = Math.max(minWidthPx, savedWidth);
        return { id: colId, widthPx, minWidthPx };
    });
}

function getTableColumnWidthPx(tableKey, colId, variantKey = null) {
    const config = getTableColumnConfig(tableKey, variantKey);
    const defaultWidths = TABLE_COLUMN_DEFAULTS[tableKey]?.widths || {};
    const raw = config.widths?.[colId] ?? defaultWidths[colId];
    if (typeof raw === 'number' && Number.isFinite(raw) && raw > 0) {
        return Math.round(raw);
    }
    if (typeof raw === 'string' && PURCHASE_HISTORY_WIDTH_TIERS.includes(raw)) {
        const map = colId === 'actions' ? PURCHASE_HISTORY_ACTIONS_WIDTH_MAP : PURCHASE_HISTORY_WIDTH_MAP;
        return map[raw] || map.M;
    }
    return defaultWidths[colId] || 100;
}

function saveTableColumnWidth(tableKey, colId, px, variantKey = null) {
    const config = getTableColumnConfig(tableKey, variantKey);
    const widths = { ...(config.widths || {}) };
    widths[colId] = Math.max(getTableColumnMinWidth(tableKey, colId), Math.round(px));
    saveTableColumnConfig(tableKey, { ...config, widths }, variantKey);
}

function buildTableColgroup(tableKey, columnIds, variantKey = null) {
    const layout = getCustomizableTableColumnLayout(tableKey, columnIds, variantKey);
    let html = '<colgroup>';
    layout.forEach(col => {
        html += `<col data-col="${col.id}" style="width:${col.widthPx}px;min-width:${col.minWidthPx}px">`;
    });
    html += '</colgroup>';
    return html;
}

function getTableMinWidth(tableKey, columnIds, variantKey = null) {
    const layout = getCustomizableTableColumnLayout(tableKey, columnIds, variantKey);
    const total = layout.reduce((sum, col) => sum + col.widthPx, 0);
    return Math.max(total, 320);
}

/** Rebuild full order: remove dragged id, then insert at target (before/after). No duplicates. */
function computeReorderedColumnOrder(order, draggedColId, targetColId, placeAfter = false) {
    const next = (order || []).filter(id => id !== draggedColId);
    const targetIdx = next.indexOf(targetColId);
    if (targetIdx < 0) {
        next.push(draggedColId);
        return next;
    }
    next.splice(placeAfter ? targetIdx + 1 : targetIdx, 0, draggedColId);
    return next;
}

function reorderTableColumnOrder(tableKey, draggedColId, targetColId, placeAfter = false, variantKey = null) {
    if (!tableKey || !draggedColId || !targetColId || draggedColId === targetColId) return null;
    const config = getTableColumnConfig(tableKey, variantKey);
    const order = computeReorderedColumnOrder(config.order || [], draggedColId, targetColId, placeAfter);
    const nextConfig = { ...config, order };
    saveTableColumnConfig(tableKey, nextConfig, variantKey);
    return order;
}

function clearCustomizableTableColumnDropIndicators(table) {
    table?.querySelectorAll('thead th.column-drop-before, thead th.column-drop-after').forEach(th => {
        th.classList.remove('column-drop-before', 'column-drop-after');
    });
}

function renderColumnResizeHandle(tableKey, colId, label) {
    return `<span class="column-resize-handle" data-table-key="${tableKey}" data-col-id="${colId}" role="separator" aria-orientation="vertical" aria-label="Resize ${escapeAttr(label)} column"></span>`;
}

function getUseStatsDefaultsForSubstance(substanceId) {
    if (isVapeNicotineSubstanceId(substanceId)) return USE_STATS_VAPE_DEFAULTS;
    if (isWeedTrackingMode(substanceId)) return USE_STATS_WEED_DEFAULTS;
    return USE_STATS_COKE_DEFAULTS;
}

function getExcludedStatIdsForSubstance(substanceId) {
    if (isVapeNicotineSubstanceId(substanceId)) return VAPE_EXCLUDED_USE_STAT_IDS;
    if (isWeedTrackingMode(substanceId)) {
        return new Set([...WEED_EXCLUDED_USE_STAT_IDS, ...VAPE_ONLY_USE_STAT_IDS]);
    }
    return new Set(VAPE_ONLY_USE_STAT_IDS);
}

function loadUseStatsLayoutStore() {
    try {
        const raw = localStorage.getItem(USE_STATS_LAYOUT_STORAGE_KEY);
        return raw ? JSON.parse(raw) : {};
    } catch {
        return {};
    }
}

function saveUseStatsLayoutStore(store) {
    localStorage.setItem(USE_STATS_LAYOUT_STORAGE_KEY, JSON.stringify(store));
}

function layoutFromDefaults(substanceId) {
    const defaults = getUseStatsDefaultsForSubstance(substanceId);
    const catalog = getUseStatsCatalogForSubstance(substanceId);
    const excluded = getExcludedStatIdsForSubstance(substanceId);
    const hidden = new Set(defaults.hidden || []);
    const order = [];
    (defaults.order || []).forEach(id => {
        if (catalog.includes(id) && !order.includes(id)) order.push(id);
    });
    catalog.forEach(id => {
        if (!order.includes(id)) order.push(id);
    });
    const enabled = order.filter(id => !hidden.has(id) && !excluded.has(id));
    return { enabled, order };
}

function normalizeUseStatsLayout(layout, substanceId) {
    const catalog = getUseStatsCatalogForSubstance(substanceId);
    const excluded = getExcludedStatIdsForSubstance(substanceId);
    const defaults = getUseStatsDefaultsForSubstance(substanceId);

    let order = Array.isArray(layout?.order) ? layout.order.filter(id => catalog.includes(id)) : [];
    catalog.forEach(id => {
        if (!order.includes(id)) order.push(id);
    });
    (defaults.order || []).forEach(id => {
        if (catalog.includes(id) && !order.includes(id)) order.push(id);
    });

    let enabled = Array.isArray(layout?.enabled)
        ? layout.enabled.filter(id => catalog.includes(id) && !excluded.has(id))
        : [];
    if (!enabled.length) {
        const hidden = new Set(defaults.hidden || []);
        enabled = order.filter(id => !hidden.has(id) && !excluded.has(id));
    }
    enabled = order.filter(id => enabled.includes(id));

    return { enabled, order };
}

function getUseStatsLayout(substanceId) {
    let sid = substanceId;
    if (!sid || sid === DASHBOARD_ALL) {
        sid = getMainSubstanceId() || getActiveSubstances()[0]?.id;
    }
    if (!sid) return { enabled: [], order: [] };
    const store = loadUseStatsLayoutStore();
    if (store[sid]) return normalizeUseStatsLayout(store[sid], sid);
    return layoutFromDefaults(sid);
}

function saveUseStatsLayout(substanceId, layout) {
    if (!substanceId || substanceId === DASHBOARD_ALL) return;
    const store = loadUseStatsLayoutStore();
    store[substanceId] = normalizeUseStatsLayout(layout, substanceId);
    saveUseStatsLayoutStore(store);
}

function migrateLegacyUseStatsLayoutIfNeeded(data = appData) {
    const store = loadUseStatsLayoutStore();
    if (Object.keys(store).length) return;
    const legacy = data?.settings?.useStatsCards;
    if (!legacy) return;
    const mainId = getMainSubstanceId() || 'coke';
    const hidden = new Set(legacy.hidden || []);
    const order = Array.isArray(legacy.order) ? [...legacy.order] : [];
    const catalog = getUseStatsCatalogForSubstance(mainId);
    const enabled = order.filter(id => catalog.includes(id) && !hidden.has(id));
    if (enabled.length) {
        saveUseStatsLayout(mainId, { enabled, order });
    }
}

function ensureUseStatsConfig(data) {
    if (!data.settings) data.settings = {};
    migrateLegacyUseStatsLayoutIfNeeded(data);
}

function getUseStatsConfig(substanceId = currentSubstanceId) {
    const layout = getUseStatsLayout(substanceId);
    return {
        order: layout.order,
        hidden: layout.order.filter(id => !layout.enabled.includes(id))
    };
}

function getVisibleUseStatsOrder() {
    return getVisibleUseStatsOrderForSubstance(currentSubstanceId);
}

function saveUseStatsConfig(substanceId, layout) {
    saveUseStatsLayout(substanceId, layout);
}

function resetUseStatsConfig(substanceId = currentSubstanceId) {
    const layout = layoutFromDefaults(substanceId);
    saveUseStatsLayout(substanceId, layout);
    return layout;
}

function openUseStatsSettingsModal() {
    const modal = document.getElementById('use-stats-settings-modal');
    renderUseStatsSettingsList();
    modal?.classList.remove('hidden');
}

function closeUseStatsSettingsModal() {
    document.getElementById('use-stats-settings-modal')?.classList.add('hidden');
}

function renderUseStatsSettingsList() {
    const list = document.getElementById('use-stats-settings-list');
    if (!list) return;
    const substanceId = currentSubstanceId;
    const layout = getUseStatsLayout(substanceId);
    const enabledSet = new Set(layout.enabled);
    const excluded = getExcludedStatIdsForSubstance(substanceId);

    list.innerHTML = layout.order
        .filter(statId => !excluded.has(statId))
        .map(statId => {
            const checked = enabledSet.has(statId) ? 'checked' : '';
            const label = getUseStatLabelForSubstance(statId, substanceId, 'puffs');
            return `<li class="column-settings-item" draggable="true" data-stat-id="${statId}">
            <span class="column-drag-handle" draggable="true" aria-hidden="true">☰</span>
            <label class="column-settings-label">
                <input type="checkbox" class="use-stats-settings-visible" data-stat-id="${statId}" ${checked}>
                ${label}
            </label>
        </li>`;
        }).join('');
}

function readUseStatsSettingsFromModal() {
    const list = document.getElementById('use-stats-settings-list');
    const substanceId = currentSubstanceId;
    const catalog = new Set(getUseStatsCatalogForSubstance(substanceId));
    const excluded = getExcludedStatIdsForSubstance(substanceId);
    if (!list) return getUseStatsLayout(substanceId);

    const order = [...list.querySelectorAll('.column-settings-item')]
        .map(li => li.dataset.statId)
        .filter(id => catalog.has(id) && !excluded.has(id));

    const enabled = [];
    list.querySelectorAll('.use-stats-settings-visible').forEach(input => {
        const statId = input.dataset.statId;
        if (!catalog.has(statId) || excluded.has(statId)) return;
        if (input.checked) enabled.push(statId);
    });

    const enabledOrdered = order.filter(id => enabled.includes(id));
    return { enabled: enabledOrdered, order };
}

function applyUseStatsSettingsFromModal() {
    const layout = readUseStatsSettingsFromModal();
    if (!layout.enabled.length) {
        alert('Keep at least one stat visible.');
        return;
    }
    saveUseStatsLayout(currentSubstanceId, layout);
    closeUseStatsSettingsModal();
    updateStats();
}

function resetUseStatsSettingsFromModal() {
    resetUseStatsConfig(currentSubstanceId);
    renderUseStatsSettingsList();
    updateStats();
}

function setupUseStatsSettingsModal() {
    document.getElementById('use-stats-edit-btn')?.addEventListener('click', openUseStatsSettingsModal);
    document.getElementById('use-stats-settings-close')?.addEventListener('click', closeUseStatsSettingsModal);
    document.getElementById('use-stats-settings-apply')?.addEventListener('click', applyUseStatsSettingsFromModal);
    document.getElementById('use-stats-settings-reset')?.addEventListener('click', resetUseStatsSettingsFromModal);

    setupColumnSettingsDragReorder(document.getElementById('use-stats-settings-list'), 'statId');
}

// Drag-to-reorder wiring shared by the column settings and use-stats settings lists.
function setupColumnSettingsDragReorder(list, dragIdKey) {
    if (!list) return;

    let dragItem = null;

    list.addEventListener('dragstart', e => {
        if (!e.target.closest('.column-drag-handle')) {
            e.preventDefault();
            return;
        }
        const item = e.target.closest('.column-settings-item');
        if (!item) return;
        dragItem = item;
        item.classList.add('column-settings-dragging');
        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('text/plain', item.dataset[dragIdKey]);
    });

    list.addEventListener('dragend', () => {
        dragItem?.classList.remove('column-settings-dragging');
        dragItem = null;
        list.querySelectorAll('.column-settings-item').forEach(el => el.classList.remove('column-settings-drop-target'));
    });

    list.addEventListener('dragover', e => {
        e.preventDefault();
        const item = e.target.closest('.column-settings-item');
        if (!item || item === dragItem) return;
        list.querySelectorAll('.column-settings-item').forEach(el => el.classList.remove('column-settings-drop-target'));
        item.classList.add('column-settings-drop-target');
    });

    list.addEventListener('drop', e => {
        e.preventDefault();
        const target = e.target.closest('.column-settings-item');
        if (!target || !dragItem || target === dragItem) return;
        const items = [...list.querySelectorAll('.column-settings-item')];
        const from = items.indexOf(dragItem);
        const to = items.indexOf(target);
        if (from < 0 || to < 0) return;
        if (from < to) target.after(dragItem);
        else target.before(dragItem);
        target.classList.remove('column-settings-drop-target');
    });
}

function resetTableColumnConfig(tableKey, variantKey = null) {
    let config;
    if (tableKey === 'taperByWeek' && variantKey) {
        const substanceId = resolveTaperByWeekColumnSubstanceId(variantKey);
        config = getDefaultTaperByWeekColumnSettings(
            substanceId,
            getSelectedTaperPlan() || {
                substanceId,
                reductionType: 'reduce-amount'
            }
        );
    } else if (tableKey === 'useHistory' && variantKey) {
        config = getDefaultUseHistoryColumnSettings(getUseLogViewSubstanceId());
    } else {
        config = getDefaultColumnSettings(tableKey);
    }
    saveTableColumnConfig(tableKey, config, variantKey);
}

function updateColumnSettingsSubtitle(tableKey, variantKey = null) {
    const subtitle = document.getElementById('column-settings-subtitle');
    if (!subtitle) return;
    if (tableKey === 'taperByWeek' && variantKey) {
        const substanceId = resolveTaperByWeekColumnSubstanceId(variantKey);
        const substanceName = getSubstance(substanceId)?.name || substanceId;
        const familyLabel = getTaperByWeekColumnFamilyLabel(substanceId);
        subtitle.innerHTML = `Showing columns for <strong>${escapeHtml(substanceName)}</strong> (${escapeHtml(familyLabel)})`;
        subtitle.classList.remove('hidden');
        return;
    }
    if (tableKey === 'useHistory' && variantKey) {
        const substanceId = getUseLogViewSubstanceId();
        const name = substanceId && substanceId !== DASHBOARD_ALL
            ? (getSubstance(substanceId)?.name || variantKey)
            : (variantKey === 'cocaine' ? 'Coke' : variantKey);
        subtitle.innerHTML = `Showing columns for <strong>${escapeHtml(name)}</strong>`;
        subtitle.classList.remove('hidden');
        return;
    }
    subtitle.textContent = '';
    subtitle.classList.add('hidden');
}

function openColumnSettingsModal(tableKey, variantKey = null) {
    columnSettingsTableKey = tableKey;
    columnSettingsVariantKey = variantKey;
    const modal = document.getElementById('column-settings-modal');
    const title = document.getElementById('column-settings-title');
    if (title) {
        title.textContent = COLUMN_MODAL_TITLES[tableKey] || 'Customize Columns';
    }
    updateColumnSettingsSubtitle(tableKey, variantKey);
    const runningWrap = document.getElementById('column-settings-buy-month-running-wrap');
    const runningSelect = document.getElementById('column-settings-buy-month-running-mode');
    if (runningWrap) {
        runningWrap.classList.toggle('hidden', tableKey !== 'buyMonthly');
    }
    if (runningSelect && tableKey === 'buyMonthly') {
        runningSelect.value = getBuyMonthRunningMode();
    }
    renderColumnSettingsList(tableKey);
    modal?.classList.remove('hidden');
}

function closeColumnSettingsModal() {
    columnSettingsTableKey = null;
    columnSettingsVariantKey = null;
    document.getElementById('column-settings-modal')?.classList.add('hidden');
}

function renderColumnSettingsList(tableKey) {
    const list = document.getElementById('column-settings-list');
    if (!list) return;
    const variantKey = tableKey === 'taperByWeek' || tableKey === 'useHistory'
        ? columnSettingsVariantKey
        : null;
    const config = getTableColumnConfig(tableKey, variantKey);
    const required = new Set(TABLE_COLUMNS_REQUIRED[tableKey] || []);
    const visible = config.visible || {};
    const order = [...config.order];
    TABLE_COLUMN_DEFAULTS[tableKey].order.forEach(id => {
        if (!order.includes(id)) order.push(id);
    });
    const plan = tableKey === 'taperByWeek' ? getSelectedTaperPlan() : null;
    const substanceId = tableKey === 'taperByWeek'
        ? getTaperSubstanceId()
        : (tableKey === 'useHistory' ? getUseLogViewSubstanceId() : currentSubstanceId);
    let availableOrder = order;
    if (tableKey === 'purchaseHistory') {
        availableOrder = order.filter(colId =>
            colId !== 'flavor' || substanceShowsPurchaseFlavor(getInventorySubstanceFilterId() || substanceId)
        );
    } else if (tableKey === 'taperByWeek') {
        const catalog = new Set(getTaperByWeekColumnCatalog(substanceId, plan));
        availableOrder = order.filter(colId => catalog.has(colId));
        getTaperByWeekColumnCatalog(substanceId, plan).forEach(colId => {
            if (!availableOrder.includes(colId)) availableOrder.push(colId);
        });
    } else if (tableKey === 'useHistory') {
        const catalog = getUseHistoryColumnCatalog(substanceId);
        const catalogSet = new Set(catalog);
        availableOrder = order.filter(colId => catalogSet.has(colId));
        catalog.forEach(colId => {
            if (!availableOrder.includes(colId)) availableOrder.push(colId);
        });
    }

    const customNames = config.customNames || {};
    list.innerHTML = availableOrder.map(colId => {
        const checked = visible[colId] !== false;
        const disabled = required.has(colId) ? 'disabled checked' : (checked ? 'checked' : '');
        const reqNote = required.has(colId) ? ' <span class="column-required-tag">(required)</span>' : '';
        const defaultLabel = getDefaultColumnLabel(tableKey, colId, { substanceId, plan });
        const customName = sanitizeCustomColumnName(customNames[colId]);
        const widthPx = getTableColumnWidthPx(tableKey, colId, variantKey);
        const widthControl = `<div class="column-settings-width">
            <label class="column-settings-width-label" for="column-width-${tableKey}-${colId}">Width</label>
            <input type="number" id="column-width-${tableKey}-${colId}" class="column-settings-width-input" data-col-id="${colId}" min="${getTableColumnMinWidth(tableKey, colId)}" step="1" value="${widthPx}">
            <span class="column-settings-width-hint">px</span>
        </div>`;
        const nameControl = `<div class="column-settings-display-name">
            <label class="column-settings-display-name-label" for="column-name-${tableKey}-${colId}">Display name</label>
            <input type="text" id="column-name-${tableKey}-${colId}" class="column-settings-custom-name" data-col-id="${colId}" maxlength="${COLUMN_CUSTOM_NAME_MAX_LENGTH}" placeholder="${escapeAttr(defaultLabel)}" value="${escapeAttr(customName)}" aria-label="Display name for ${escapeAttr(defaultLabel)}">
            <button type="button" class="secondary-btn btn-sm column-settings-reset-name" data-col-id="${colId}">Reset name</button>
        </div>`;
        return `<li class="column-settings-item column-settings-item-with-width" draggable="true" data-col-id="${colId}">
            <span class="column-drag-handle" draggable="true" aria-hidden="true">☰</span>
            <label class="column-settings-label">
                <input type="checkbox" class="column-settings-visible" data-col-id="${colId}" ${disabled}>
                <span class="column-settings-internal-key" title="Internal key: ${escapeAttr(colId)}">${escapeHtml(defaultLabel)}${reqNote}</span>
            </label>
            ${nameControl}
            ${widthControl}
        </li>`;
    }).join('');
}

function setColumnSettingsVisibilityInModal(tableKey, showAllOptional = true) {
    const list = document.getElementById('column-settings-list');
    if (!list) return;
    const required = new Set(TABLE_COLUMNS_REQUIRED[tableKey] || []);
    list.querySelectorAll('.column-settings-visible').forEach(input => {
        const colId = input.dataset.colId;
        if (!colId || required.has(colId)) return;
        input.checked = showAllOptional;
    });
}

function getPurchaseHistoryColumnWidthSetting(colId) {
    return getTableColumnWidthPx('purchaseHistory', colId);
}

function getPurchaseHistoryColumnWidthPx(colId, widthSetting) {
    if (typeof widthSetting === 'number' && Number.isFinite(widthSetting) && widthSetting > 0) {
        return Math.round(widthSetting);
    }
    return getTableColumnWidthPx('purchaseHistory', colId);
}

function getPurchaseHistoryColumnWidthsMap() {
    const config = getTableColumnConfig('purchaseHistory');
    return { ...(config.widths || TABLE_COLUMN_DEFAULTS.purchaseHistory.widths) };
}

function savePurchaseHistoryColumnWidth(colId, px) {
    saveTableColumnWidth('purchaseHistory', colId, px);
}

function buildPurchaseHistoryColgroup(columnIds) {
    return buildTableColgroup('purchaseHistory', columnIds);
}

function readColumnSettingsFromModal(tableKey) {
    const list = document.getElementById('column-settings-list');
    const variantKey = tableKey === 'taperByWeek' || tableKey === 'useHistory'
        ? columnSettingsVariantKey
        : null;
    if (!list) return getTableColumnConfig(tableKey, variantKey);
    const required = new Set(TABLE_COLUMNS_REQUIRED[tableKey] || []);
    const previous = getTableColumnConfig(tableKey, variantKey);
    const order = [...list.querySelectorAll('.column-settings-item')].map(li => li.dataset.colId);
    // Preserve context-hidden columns (e.g. Flavor while viewing Coke) so they
    // remain available when switching back to flavored product types.
    if (tableKey === 'purchaseHistory' && !order.includes('flavor')
        && (previous.order || []).includes('flavor')) {
        const flavorIndex = previous.order.indexOf('flavor');
        const insertAt = Math.min(Math.max(flavorIndex, 0), order.length);
        order.splice(insertAt, 0, 'flavor');
    }
    const visible = { ...(previous.visible || {}) };
    order.forEach(id => {
        if (!(id in visible)) visible[id] = true;
    });
    list.querySelectorAll('.column-settings-visible').forEach(input => {
        const colId = input.dataset.colId;
        if (!colId) return;
        visible[colId] = required.has(colId) ? true : input.checked;
    });
    const widths = { ...(previous.widths || {}) };
    list.querySelectorAll('.column-settings-width-input').forEach(input => {
        const colId = input.dataset.colId;
        const px = parseInt(input.value, 10);
        if (colId && Number.isFinite(px) && px > 0) {
            widths[colId] = Math.max(getTableColumnMinWidth(tableKey, colId), px);
        }
    });
    const customNames = { ...(previous.customNames || {}) };
    // Drop names for rows currently in the modal, then re-apply from inputs.
    order.forEach(id => { delete customNames[id]; });
    list.querySelectorAll('.column-settings-custom-name').forEach(input => {
        const colId = input.dataset.colId;
        if (!colId) return;
        const cleaned = sanitizeCustomColumnName(input.value);
        if (cleaned) customNames[colId] = cleaned;
        else delete customNames[colId];
    });
    if (tableKey === 'taperByWeek') {
        return filterTaperByWeekColumnSettingsToCatalog(
            { order, visible, widths, customNames },
            getTaperSubstanceId(),
            getSelectedTaperPlan()
        );
    }
    if (tableKey === 'useHistory') {
        return filterUseHistoryColumnSettingsToCatalog(
            { order, visible, widths, customNames },
            getUseLogViewSubstanceId()
        );
    }
    return {
        order,
        visible,
        widths,
        customNames: normalizeCustomNamesMap(tableKey, customNames, order)
    };
}

function refreshTableAfterColumnChange(tableKey) {
    const substanceId = isAllSubstancesView() ? null : currentSubstanceId;
    switch (tableKey) {
        case 'useHistory':
            renderUseHistoryTable();
            break;
        case 'purchaseHistory':
            // Presentation-only: never override inventory filters/search/status/substance.
            renderPurchaseHistory(null);
            break;
        case 'statsWeekly':
            renderStatsWeeklySummary(currentSubstanceId);
            break;
        case 'statsMonthly':
            renderStatsMonthlySummary(currentSubstanceId);
            break;
        case 'taperByWeek':
            renderTaperWeeklyTable(getTaperSubstanceId());
            break;
        case 'statsCalendarYearSummary':
            renderStatsCalendarView();
            break;
        case 'buyWeekly':
        case 'buyMonthly':
        case 'buyPurchaseDetails': {
            if (currentSubstanceId && currentSubstanceId !== DASHBOARD_ALL) {
                const insights = buildInsightsDataset(currentSubstanceId);
                if (tableKey === 'buyWeekly') renderStatsBuyWeekSummary(insights);
                else if (tableKey === 'buyMonthly') renderStatsBuyMonthSummary(insights);
                else renderStatsBuyPurchaseDetails(insights);
            }
            break;
        }
        default:
            break;
    }
}

function setupCustomizableTableColumnResize() {
    if (document.documentElement.dataset.tableColResizeBound === '1') return;
    document.documentElement.dataset.tableColResizeBound = '1';

    let active = null;

    document.addEventListener('mousedown', e => {
        const handle = e.target.closest('.column-resize-handle');
        if (!handle) return;
        e.preventDefault();
        const tableKey = handle.dataset.tableKey;
        const colId = handle.dataset.colId;
        const table = handle.closest('table.customizable-table');
        const col = table?.querySelector(`colgroup col[data-col="${colId}"]`);
        if (!tableKey || !colId || !table || !col) return;
        const startWidth = col.getBoundingClientRect().width || getTableColumnWidthPx(tableKey, colId);
        active = { tableKey, colId, col, table, startX: e.clientX, startWidth };
        document.body.classList.add('table-col-resizing');
    });

    document.addEventListener('mousemove', e => {
        if (!active) return;
        e.preventDefault();
        const minW = getTableColumnMinWidth(active.tableKey, active.colId);
        const newWidth = Math.max(minW, Math.round(active.startWidth + (e.clientX - active.startX)));
        active.col.style.width = `${newWidth}px`;
        active.col.style.minWidth = `${newWidth}px`;
        const total = [...active.table.querySelectorAll('colgroup col')].reduce((sum, c) => {
            return sum + (parseInt(c.style.width, 10) || c.getBoundingClientRect().width || 0);
        }, 0);
        active.table.style.minWidth = `${Math.max(total, 320)}px`;
    });

    document.addEventListener('mouseup', () => {
        if (!active) return;
        const px = parseInt(active.col.style.width, 10) || active.startWidth;
        const table = active.table;
        const variantKey = table?.dataset?.tableVariant || null;
        saveTableColumnWidth(active.tableKey, active.colId, px, variantKey || null);
        document.body.classList.remove('table-col-resizing');
        active = null;
    });
}

function setupCustomizableTableColumnDrag() {
    if (document.documentElement.dataset.tableColDragBound === '1') return;
    document.documentElement.dataset.tableColDragBound = '1';

    let dragState = null;

    document.addEventListener('dragstart', e => {
        if (e.target.closest?.('.column-resize-handle')) {
            e.preventDefault();
            return;
        }
        const th = e.target.closest?.('table.customizable-table.column-reorderable thead th[data-col]');
        if (!th || th.draggable === false) return;
        const table = th.closest('table.customizable-table');
        const tableKey = table?.dataset?.tableKey;
        const colId = th.dataset.col;
        if (!table || !tableKey || !colId) return;
        dragState = {
            table,
            tableKey,
            variantKey: table.dataset.tableVariant || null,
            colId
        };
        th.classList.add('column-dragging');
        table.classList.add('is-column-reordering');
        try {
            e.dataTransfer.effectAllowed = 'move';
            e.dataTransfer.setData('text/plain', colId);
        } catch {
            /* ignore */
        }
    });

    document.addEventListener('dragend', () => {
        if (!dragState) return;
        clearCustomizableTableColumnDropIndicators(dragState.table);
        dragState.table.querySelectorAll('thead th.column-dragging').forEach(th => {
            th.classList.remove('column-dragging');
        });
        dragState.table.classList.remove('is-column-reordering');
        dragState = null;
    });

    document.addEventListener('dragover', e => {
        if (!dragState) return;
        const th = e.target.closest?.('table.customizable-table.column-reorderable thead th[data-col]');
        if (!th || th.closest('table') !== dragState.table) return;
        const targetColId = th.dataset.col;
        if (!targetColId || targetColId === dragState.colId) return;
        e.preventDefault();
        try { e.dataTransfer.dropEffect = 'move'; } catch { /* ignore */ }
        const rect = th.getBoundingClientRect?.();
        const placeAfter = rect ? e.clientX > rect.left + rect.width / 2 : false;
        clearCustomizableTableColumnDropIndicators(dragState.table);
        th.classList.add(placeAfter ? 'column-drop-after' : 'column-drop-before');
        dragState.placeAfter = placeAfter;
        dragState.targetColId = targetColId;
    });

    document.addEventListener('drop', e => {
        if (!dragState) return;
        const th = e.target.closest?.('table.customizable-table.column-reorderable thead th[data-col]');
        const table = dragState.table;
        const tableKey = dragState.tableKey;
        const variantKey = dragState.variantKey;
        const draggedColId = dragState.colId;
        let targetColId = dragState.targetColId;
        let placeAfter = !!dragState.placeAfter;
        if (th && th.closest('table') === table) {
            targetColId = th.dataset.col || targetColId;
            const rect = th.getBoundingClientRect?.();
            if (rect) placeAfter = e.clientX > rect.left + rect.width / 2;
        }
        e.preventDefault();
        clearCustomizableTableColumnDropIndicators(table);
        table.querySelectorAll('thead th.column-dragging').forEach(el => el.classList.remove('column-dragging'));
        table.classList.remove('is-column-reordering');
        dragState = null;
        if (!targetColId || targetColId === draggedColId) return;
        // Persist new order, then fully re-render so old position is gone before new layout paints.
        reorderTableColumnOrder(tableKey, draggedColId, targetColId, placeAfter, variantKey);
        refreshTableAfterColumnChange(tableKey);
    });
}

function applyColumnSettingsFromModal() {
    if (!columnSettingsTableKey) return;
    const tableKey = columnSettingsTableKey;
    const variantKey = columnSettingsVariantKey;
    const config = readColumnSettingsFromModal(tableKey);
    const required = new Set(TABLE_COLUMNS_REQUIRED[tableKey] || []);
    const visibleDataCols = config.order.filter(id => !required.has(id) && config.visible[id] !== false);
    if (!visibleDataCols.length) {
        alert('Keep at least one visible data column.');
        return;
    }
    if (tableKey === 'buyMonthly') {
        const runningMode = document.getElementById('column-settings-buy-month-running-mode')?.value
            || 'within-year';
        setBuyMonthRunningMode(runningMode);
        if (runningMode === 'hide') {
            config.visible.runningPurchased = false;
            config.visible.runningSpent = false;
        }
    }
    // Column settings control presentation only — never mutate inventory filters or purchases.
    saveTableColumnConfig(tableKey, config, variantKey);
    closeColumnSettingsModal();
    refreshTableAfterColumnChange(tableKey);
}

function resetColumnSettingsFromModal() {
    if (!columnSettingsTableKey) return;
    const tableKey = columnSettingsTableKey;
    const variantKey = columnSettingsVariantKey;
    resetTableColumnConfig(tableKey, variantKey);
    renderColumnSettingsList(tableKey);
    refreshTableAfterColumnChange(tableKey);
}

function resetColumnCustomNameInModal(colId) {
    if (!colId || !columnSettingsTableKey) return;
    const input = document.querySelector(
        `#column-settings-list .column-settings-custom-name[data-col-id="${CSS.escape?.(colId) || colId}"]`
    ) || [...document.querySelectorAll('#column-settings-list .column-settings-custom-name')]
        .find(el => el.dataset.colId === colId);
    if (input) input.value = '';
}

function resetAllColumnCustomNamesInModal() {
    if (!columnSettingsTableKey) return;
    document.querySelectorAll('#column-settings-list .column-settings-custom-name').forEach(input => {
        input.value = '';
    });
}

function setupColumnSettingsModal() {
    document.getElementById('use-history-customize-columns')?.addEventListener('click', () => {
        openColumnSettingsModal('useHistory', getUseHistoryColumnVariantKey());
    });
    document.getElementById('purchase-history-customize-columns')?.addEventListener('click', () => {
        openColumnSettingsModal('purchaseHistory');
    });
    document.getElementById('stats-weekly-customize-columns')?.addEventListener('click', () => {
        openColumnSettingsModal('statsWeekly');
    });
    document.getElementById('stats-monthly-customize-columns')?.addEventListener('click', () => {
        openColumnSettingsModal('statsMonthly');
    });
    document.getElementById('average-use-customize-columns')?.addEventListener('click', () => {
        openColumnSettingsModal('averageUse');
    });
    document.getElementById('stats-buy-week-customize-columns')?.addEventListener('click', () => {
        openColumnSettingsModal('buyWeekly');
    });
    document.getElementById('stats-buy-month-customize-columns')?.addEventListener('click', () => {
        openColumnSettingsModal('buyMonthly');
    });
    document.getElementById('stats-buy-purchase-details-customize-columns')?.addEventListener('click', () => {
        openColumnSettingsModal('buyPurchaseDetails');
    });
    document.getElementById('taper-weekly-customize-columns')?.addEventListener('click', () => {
        openColumnSettingsModal('taperByWeek', getTaperByWeekColumnVariantKey(getTaperSubstanceId(), getSelectedTaperPlan()));
    });
    document.getElementById('stats-calendar-year-customize-columns')?.addEventListener('click', () => {
        openColumnSettingsModal('statsCalendarYearSummary');
    });
    document.getElementById('column-settings-close')?.addEventListener('click', closeColumnSettingsModal);
    document.getElementById('column-settings-apply')?.addEventListener('click', applyColumnSettingsFromModal);
    document.getElementById('column-settings-reset')?.addEventListener('click', resetColumnSettingsFromModal);
    document.getElementById('column-settings-reset-all-names')?.addEventListener('click', resetAllColumnCustomNamesInModal);
    document.getElementById('column-settings-show-all')?.addEventListener('click', () => {
        if (columnSettingsTableKey) setColumnSettingsVisibilityInModal(columnSettingsTableKey, true);
    });
    document.getElementById('column-settings-hide-optional')?.addEventListener('click', () => {
        if (columnSettingsTableKey) setColumnSettingsVisibilityInModal(columnSettingsTableKey, false);
    });
    document.getElementById('settings-use-custom-names-in-csv')?.addEventListener('change', (e) => {
        setUseCustomNamesInCsvExport(!!e.target.checked);
    });

    const list = document.getElementById('column-settings-list');
    if (!list) return;

    list.addEventListener('click', e => {
        const btn = e.target.closest?.('.column-settings-reset-name');
        if (!btn) return;
        e.preventDefault();
        resetColumnCustomNameInModal(btn.dataset.colId);
    });

    setupColumnSettingsDragReorder(list, 'colId');

    setupCustomizableTableColumnResize();
    setupCustomizableTableColumnDrag();
}

function formatUseHistoryVapeAmountHtml(entry) {
    if (isSharedUseLog(entry)) {
        const me = formatAmount(getLogPersonalAmount(entry));
        const other = formatAmount(getLogSharedAmount(entry));
        const name = entry.sharedWithName?.trim() || 'Other';
        return `<span class="use-history-amount-compact">Legacy Shared Use · Me ${me} puffs · ${escapeHtml(name)} ${other} puffs</span>`;
    }
    if (isPercentLeftCheckpointLog(entry) && getSpreadPercentLeftUsage()) {
        const beforeRaw = entry.percentBefore;
        const afterRaw = entry.percentLeftAfter ?? entry.percentRemaining;
        const beforeLabel = beforeRaw != null && Number.isFinite(parseFloat(beforeRaw))
            ? (Number.isInteger(parseFloat(beforeRaw)) ? beforeRaw : parseFloat(beforeRaw).toFixed(1))
            : '—';
        const afterLabel = afterRaw != null && Number.isFinite(parseFloat(afterRaw))
            ? (Number.isInteger(parseFloat(afterRaw)) ? afterRaw : parseFloat(afterRaw).toFixed(1))
            : '—';
        const total = entry.originalTotalEstimatedPuffs ?? entry.estimatedPuffsUsed ?? entry.amount;
        const puffsLabel = Number.isFinite(parseFloat(total))
            ? Math.round(parseFloat(total)).toLocaleString('en-US')
            : formatAmount(total);
        return `<span class="use-history-amount-compact">Percent-left checkpoint · ${beforeLabel}% → ${afterLabel}%</span>`
            + `<span class="use-history-amount-sub">Estimated ${puffsLabel} puffs</span>`;
    }
    const puffs = parseFloat(entry.estimatedPuffsUsed ?? entry.amount);
    const puffsLabel = Number.isFinite(puffs)
        ? Math.round(puffs).toLocaleString('en-US')
        : formatAmount(entry.amount);
    const prefix = (entry.isEstimated || entry.estimatedFromPercent) ? 'Estimated ' : '';
    return `<span class="use-history-amount-compact">${prefix}${puffsLabel} puffs</span>`;
}

function formatUseHistoryAmountHtml(entry) {
    if (isLsdDateOnlyUseLog(entry)) return formatLsdUseSummary(entry);
    if (isXanaxDateOnlyUseLog(entry)) return formatXanaxUseSummary(entry);
    if (isVapeUseLog(entry) || (isNicotineSubstanceId(getUseSubstanceId(entry)) && getNicotineProductType(entry) === 'vape')) {
        return formatUseHistoryVapeAmountHtml(entry);
    }
    if (isNicotineSubstanceId(getUseSubstanceId(entry))) {
        return formatNicotineUseLogLabel(entry);
    }
    if (isAlcoholTrackingMode(getUseSubstanceId(entry))) {
        return formatAlcoholUseSummary(entry);
    }
    if (isWeedTrackingMode(getUseSubstanceId(entry))) {
        return formatUseHistoryWeedAmountHtml(entry);
    }
    if (isPercentLeftDistributedChildLog(entry)) {
        return `~${formatAmount(entry.amount)} <span class="use-history-est-label">(est. daily)</span>`;
    }
    return `${formatAmount(entry.amount)}`;
}

let useHistorySortState = {
    col: null,
    dir: 'desc'
};

function getUseHistorySortState() {
    return useHistorySortState;
}

function setUseHistorySort(colId, dir = null) {
    const sortable = new Set(['date', 'start', 'end', 'duration', 'amount', 'gPerHour', 'breakBetweenUses', 'break']);
    if (!sortable.has(colId)) return useHistorySortState;
    if (useHistorySortState.col === colId) {
        useHistorySortState.dir = dir || (useHistorySortState.dir === 'asc' ? 'desc' : 'asc');
    } else {
        useHistorySortState.col = colId;
        useHistorySortState.dir = dir || (colId === 'breakBetweenUses' || colId === 'break' || colId === 'duration' || colId === 'gPerHour' || colId === 'amount'
            ? 'desc'
            : 'desc');
    }
    return useHistorySortState;
}

function onUseHistorySortClick(colId) {
    setUseHistorySort(colId);
    renderUseHistoryTable();
}

function compareUseHistoryBreakSort(aEntry, bEntry, dir, data = appData) {
    const ah = computeBreakSincePreviousUseHours(aEntry, data);
    const bh = computeBreakSincePreviousUseHours(bEntry, data);
    const aNull = ah == null || !Number.isFinite(ah);
    const bNull = bh == null || !Number.isFinite(bh);
    if (aNull && bNull) return getLogDatetimeMs(bEntry) - getLogDatetimeMs(aEntry);
    if (aNull) return 1;
    if (bNull) return -1;
    return dir === 'asc' ? ah - bh : bh - ah;
}

function sortUseHistoryDisplayRows(rows, sortState = useHistorySortState, data = appData) {
    const list = (rows || []).slice();
    const col = sortState?.col;
    const dir = sortState?.dir === 'asc' ? 'asc' : 'desc';
    if (!col) return list;
    list.sort((a, b) => {
        if (col === 'breakBetweenUses' || col === 'break') {
            return compareUseHistoryBreakSort(a.entry, b.entry, dir, data);
        }
        if (col === 'duration') {
            const ah = getNormalizedSessionDurationMinutes(a.entry);
            const bh = getNormalizedSessionDurationMinutes(b.entry);
            const aNull = ah == null;
            const bNull = bh == null;
            if (aNull && bNull) return getLogDatetimeMs(b.entry) - getLogDatetimeMs(a.entry);
            if (aNull) return 1;
            if (bNull) return -1;
            return dir === 'asc' ? ah - bh : bh - ah;
        }
        if (col === 'gPerHour') {
            const ah = getNormalizedGramsPerHour(a.entry);
            const bh = getNormalizedGramsPerHour(b.entry);
            const aNull = ah == null;
            const bNull = bh == null;
            if (aNull && bNull) return getLogDatetimeMs(b.entry) - getLogDatetimeMs(a.entry);
            if (aNull) return 1;
            if (bNull) return -1;
            return dir === 'asc' ? ah - bh : bh - ah;
        }
        if (col === 'amount') {
            const ah = typeof getLogStatsAmount === 'function' ? getLogStatsAmount(a.entry) : (parseFloat(a.entry.amount) || 0);
            const bh = typeof getLogStatsAmount === 'function' ? getLogStatsAmount(b.entry) : (parseFloat(b.entry.amount) || 0);
            return dir === 'asc' ? ah - bh : bh - ah;
        }
        const da = getLogDatetimeMs(a.entry);
        const db = getLogDatetimeMs(b.entry);
        return dir === 'asc' ? da - db : db - da;
    });
    return list;
}

function renderUseHistoryHeaderCell(colId, substanceId = getUseLogViewSubstanceId()) {
    const label = resolveColumnDisplayLabel('useHistory', colId, {
        substanceId,
        variantKey: getUseHistoryColumnVariantKey(substanceId)
    });
    const resize = colId === 'select' ? '' : renderColumnResizeHandle('useHistory', colId, label);
    if (colId === 'select') {
        return `<th class="use-history-cb-col" data-col="${colId}"><span class="sr-only">${escapeHtml(label)}</span></th>`;
    }
    if (colId === 'actions') {
        return `<th class="actions-cell use-history-actions-header" data-col="${colId}" title="${escapeAttr(label)}"><span class="customizable-th-label">${escapeHtml(label)}</span>${resize}</th>`;
    }
    const sortable = ['date', 'start', 'end', 'duration', 'amount', 'gPerHour', 'breakBetweenUses'].includes(colId);
    if (sortable) {
        const active = useHistorySortState.col === colId;
        const ind = active ? (useHistorySortState.dir === 'asc' ? ' ↑' : ' ↓') : '';
        const ariaSort = active
            ? (useHistorySortState.dir === 'asc' ? 'ascending' : 'descending')
            : 'none';
        return `<th data-col="${colId}" class="use-history-sortable" data-sort-col="${escapeAttr(colId)}" role="columnheader" aria-sort="${ariaSort}" tabindex="0" title="${escapeAttr(label)}"><button type="button" class="use-history-sort-btn" onclick="onUseHistorySortClick('${escapeAttr(colId)}')" aria-label="Sort by ${escapeAttr(label)}"><span class="customizable-th-label">${escapeHtml(label)}${ind}</span></button>${resize}</th>`;
    }
    return `<th data-col="${colId}" title="${escapeAttr(label)}"><span class="customizable-th-label">${escapeHtml(label)}</span>${resize}</th>`;
}

function formatUseHistoryTransactionType(log, { withIcon = false } = {}) {
    const tx = getLogTransactionType(log);
    if (tx === 'shared_use') return 'Legacy Shared Use';
    if (tx === 'gift_given') return withIcon ? '🎁 Gift given' : 'Gift given';
    if (tx === 'gift_received') return withIcon ? '📦 Gift received' : 'Gift received';
    if (tx === 'inventory_adjustment') return 'Inventory adj.';
    return 'Use';
}

function renderUseHistoryBodyCell(colId, entry, sub, avgRate) {
    const isWeedSimple = isWeedDateOnlyUseLog(entry);
    const isVapeDateOnly = isVapeDateOnlyUseLog(entry);
    const isLsdDateOnly = isLsdDateOnlyUseLog(entry);
    const hideTimeStats = isWeedSimple || isVapeDateOnly || isLsdDateOnly || isXanaxDateOnlyUseLog(entry);
    const rateStr = (!hideTimeStats && entry.useRate != null) ? `${formatAmount(entry.useRate)}/${sub.defaultUnit}/hr` : '—';
    const checked = useHistorySelectionHas(entry.id) ? 'checked' : '';
    const label = getUseHistoryColumnLabel(colId, getUseSubstanceId(entry) || sub?.id);
    const dataLabel = ` data-label="${escapeAttr(label)}"`;
    switch (colId) {
        case 'select':
            return `<td class="use-history-cb-col" data-col="${colId}"><input type="checkbox" class="use-history-row-cb" data-log-id="${escapeAttr(entry.id)}" aria-label="Select session" ${checked}></td>`;
        case 'date':
            return `<td data-col="${colId}"${dataLabel}>${formatDate(entry.date)}</td>`;
        case 'start':
            return `<td data-col="${colId}"${dataLabel}>${hideTimeStats ? '—' : (entry.startTime || entry.time || '—')}</td>`;
        case 'end':
            return `<td data-col="${colId}"${dataLabel}>${hideTimeStats ? '—' : (entry.endTime || '—')}</td>`;
        case 'duration': {
            if (hideTimeStats) {
                return `<td data-col="${colId}"${dataLabel}>—</td>`;
            }
            const minutes = typeof getNormalizedSessionDurationMinutes === 'function'
                ? getNormalizedSessionDurationMinutes(entry)
                : null;
            let durationHtml = minutes != null
                ? formatNormalizedSessionDuration(minutes)
                : (entry.durationHours != null ? formatDurationHours(entry.durationHours) : '—');
            if (minutes != null) {
                durationHtml = applyConditionalColorToMetricHtml(durationHtml, {
                    substanceId: getUseSubstanceId(entry),
                    section: 'useHistory',
                    metric: 'sessionDuration',
                    value: minutes,
                    log: entry
                });
            }
            return `<td data-col="${colId}"${dataLabel}>${durationHtml}</td>`;
        }
        case 'substance':
            return `<td data-col="${colId}"${dataLabel}>${escapeHtml(sub.icon || '')} ${escapeHtml(sub.name)}</td>`;
        case 'productType':
            if (isWeedTrackingMode(getUseSubstanceId(entry))) {
                return `<td data-col="${colId}"${dataLabel}>${escapeHtml(getWeedLogProductTypeLabel(entry))}</td>`;
            }
            return `<td data-col="${colId}"${dataLabel}>${getNicotineProductTypeLabel(getNicotineProductType(entry))}</td>`;
        case 'transactionType':
            {
                let txHtml = formatUseHistoryTransactionType(entry, { withIcon: true });
                const tx = getLogTransactionType(entry);
                const ccr = evaluateConditionalColorRules({
                    substanceId: getUseSubstanceId(entry),
                    section: 'useHistory',
                    visualTarget: 'value',
                    metric: 'transactionType',
                    value: tx,
                    textValue: tx,
                    log: entry
                });
                if (ccr.matched.length) txHtml = wrapWithConditionalColor(txHtml, ccr, { keepLabel: true });
                return `<td data-col="${colId}"${dataLabel}>${txHtml}</td>`;
            }
        case 'amount': {
            let amountHtml = formatUseHistoryAmountHtml(entry);
            if (typeof evaluateConditionalColorRules === 'function') {
                const amount = typeof getLogStatsAmount === 'function' ? getLogStatsAmount(entry) : (parseFloat(entry.amount) || 0);
                const ccr = evaluateConditionalColorRules({
                    substanceId: getUseSubstanceId(entry),
                    section: 'useHistory',
                    visualTarget: 'value',
                    metric: 'useAmount',
                    value: amount
                });
                if (ccr.matched.length) {
                    amountHtml = wrapWithConditionalColor(amountHtml, ccr, { keepLabel: true });
                }
            }
            return `<td class="use-history-amount-cell" data-col="${colId}"${dataLabel}>${amountHtml}</td>`;
        }
        case 'unit':
            if (isWeedCartPercentLog(entry)) {
                return `<td data-col="${colId}"${dataLabel}>%</td>`;
            }
            if (isWeedEdiblesLog(entry)) {
                return `<td data-col="${colId}"${dataLabel}>edible</td>`;
            }
            return `<td data-col="${colId}"${dataLabel}>${isLsdDateOnlyUseLog(entry) ? 'ug' : (entry.unit || '—')}</td>`;
        case 'tabs':
            return `<td data-col="${colId}"${dataLabel}>${entry.tabsUsed != null ? formatAmount(entry.tabsUsed) : '—'}</td>`;
        case 'ug':
            return `<td data-col="${colId}"${dataLabel}>${entry.ugUsed != null ? formatAmount(entry.ugUsed) : '—'}</td>`;
        case 'pills':
            return `<td data-col="${colId}"${dataLabel}>${entry.pillsUsed != null ? formatAmount(entry.pillsUsed) : '—'}</td>`;
        case 'mg':
            return `<td data-col="${colId}"${dataLabel}>${entry.mgUsed != null ? formatAmount(entry.mgUsed) : '—'}</td>`;
        case 'thcUsed': {
            const thc = getWeedEdibleLogThcUsed(entry);
            return `<td data-col="${colId}"${dataLabel}>${thc != null ? `${formatAmount(thc)} mg` : '—'}</td>`;
        }
        case 'cbdUsed': {
            const cbd = typeof getWeedEdibleLogCbdUsed === 'function' ? getWeedEdibleLogCbdUsed(entry) : null;
            return `<td data-col="${colId}"${dataLabel}>${cbd != null ? `${formatAmount(cbd)} mg` : '—'}</td>`;
        }
        case 'enteredAmount': {
            const entered = entry.enteredAmount ?? entry.originalEnteredAmount;
            const unit = entry.enteredUnit || entry.unit || '';
            return `<td data-col="${colId}"${dataLabel}>${entered != null ? `${formatAmount(entered)}${unit ? ` ${escapeHtml(unit)}` : ''}` : '—'}</td>`;
        }
        case 'normalizedAmount': {
            const grams = entry.normalizedGrams;
            if (grams != null) return `<td data-col="${colId}"${dataLabel}>${formatAmount(grams)} g</td>`;
            return `<td data-col="${colId}"${dataLabel}>—</td>`;
        }
        case 'percentBefore': {
            const v = entry.percentBefore;
            return `<td data-col="${colId}"${dataLabel}>${v != null ? `${formatAmount(v)}%` : '—'}</td>`;
        }
        case 'percentAfter': {
            const v = entry.percentLeftAfter ?? entry.percentAfter ?? entry.percentRemaining;
            return `<td data-col="${colId}"${dataLabel}>${v != null ? `${formatAmount(v)}%` : '—'}</td>`;
        }
        case 'percentUsed': {
            const v = entry.estimatedPercentUsed ?? (isWeedCartPercentLog(entry) ? entry.amount : null);
            return `<td data-col="${colId}"${dataLabel}>${v != null ? `${formatAmount(v)}%` : '—'}</td>`;
        }
        case 'strength': {
            if (isWeedEdiblesLog(entry) || isWeedTrackingMode(getUseSubstanceId(entry))) {
                const edibleStrength = getWeedEdibleLogStrength(entry);
                if (isWeedEdiblesLog(entry)) {
                    return `<td data-col="${colId}"${dataLabel}>${
                        edibleStrength != null ? `${formatAmount(edibleStrength)} mg/edible` : 'Strength missing'
                    }</td>`;
                }
                return `<td data-col="${colId}"${dataLabel}>—</td>`;
            }
            const strength = entry.strengthPerPillAtTimeOfUse ?? entry.mgPerPillAtTimeOfUse;
            const unit = entry.strengthUnitAtTimeOfUse || 'mg';
            return `<td data-col="${colId}"${dataLabel}>${strength != null ? `${formatAmount(strength)} ${unit}` : '—'}</td>`;
        }
        case 'cost': {
            const cost = entry.estimatedCost;
            return `<td data-col="${colId}"${dataLabel}>${cost != null && Number.isFinite(parseFloat(cost)) ? fmtSheetMoney(parseFloat(cost), getCurrencySymbol()) : '—'}</td>`;
        }
        case 'gPerHour': {
            const rate = typeof getNormalizedGramsPerHour === 'function'
                ? getNormalizedGramsPerHour(entry)
                : computeUseHistoryGramsPerHour(entry);
            let rateHtml = rate == null || !Number.isFinite(rate) ? '—' : Number(rate).toFixed(2);
            if (rate != null && Number.isFinite(rate)) {
                rateHtml = applyConditionalColorToMetricHtml(rateHtml, {
                    substanceId: getUseSubstanceId(entry),
                    section: 'useHistory',
                    metric: 'gramsPerHour',
                    value: rate,
                    log: entry
                });
            }
            return `<td data-col="${colId}"${dataLabel}>${rateHtml}</td>`;
        }
        case 'contact': {
            const label = typeof resolveLogContactLabel === 'function' ? resolveLogContactLabel(entry) : (entry.sharedWithName || entry.giftPartyName || '');
            const cid = entry.sharedWithContactId || entry.giftPartyContactId || '';
            if (cid && label) {
                return `<td data-col="${colId}"${dataLabel}><button type="button" class="link-btn" onclick="openContactDetailPanel('${escapeAttr(cid)}')">${escapeHtml(label)}</button></td>`;
            }
            return `<td data-col="${colId}"${dataLabel}>${label ? escapeHtml(label) : '—'}</td>`;
        }
        case 'sharedAmount': {
            if (!isSharedUseLog(entry)) return `<td data-col="${colId}"${dataLabel}>—</td>`;
            return `<td data-col="${colId}"${dataLabel}>Me ${formatAmount(getLogPersonalAmount(entry))} · ${escapeHtml(entry.sharedWithName || 'Other')} ${formatAmount(getLogSharedAmount(entry))}</td>`;
        }
        case 'multiDayRange': {
            if (!isAlcoholMultiDayParentLog(entry)) return `<td data-col="${colId}"${dataLabel}>—</td>`;
            const start = entry.startDate || entry.distributedStartDate || entry.date;
            const end = entry.endDate || entry.distributedEndDate || entry.date;
            return `<td data-col="${colId}"${dataLabel}>${formatDate(start)} – ${formatDate(end)}</td>`;
        }
        case 'dailyBreakdown': {
            if (!isAlcoholMultiDayParentLog(entry)) return `<td class="use-history-amount-cell" data-col="${colId}"${dataLabel}>—</td>`;
            const lines = formatAlcoholMultiDayBreakdownLines(entry);
            return `<td class="use-history-amount-cell" data-col="${colId}"${dataLabel}><span class="use-history-amount-compact">${lines.slice(0, 2).map(escapeHtml).join('<br>')}</span></td>`;
        }
        case 'count':
            return `<td data-col="${colId}"${dataLabel}>${(isVapeUseLog(entry) || isLsdDateOnlyUseLog(entry)) ? '—' : (entry.count || '—')}</td>`;
        case 'rate':
            return `<td data-col="${colId}"${dataLabel}>${rateStr}</td>`;
        case 'break':
        case 'breakBetweenUses':
            return `<td data-col="${colId}"${dataLabel}>${renderBreakSincePreviousCell(entry)}</td>`;
        case 'inventory':
        case 'supply':
            return `<td class="supply-cell session-supply-cell" data-col="inventory"${dataLabel}>${escapeHtml(formatInventoryLinkDisplay(entry))}</td>`;
        case 'notes': {
            const splitNote = formatOvernightSplitNote(entry, sub.id);
            let notesHtml = escapeHtml(entry.notes || '');
            if (isPercentLeftDistributedChildLog(entry)) {
                notesHtml = `${notesHtml ? `${notesHtml}<br>` : ''}<span class="use-history-est-label">Estimated daily use from percent-left log</span>`;
            }
            const splitHtml = splitNote ? `<div class="use-history-split-note cal-muted">${splitNote}</div>` : '';
            return `<td class="notes-cell session-notes-cell" data-col="${colId}"${dataLabel}>${notesHtml}${splitHtml}</td>`;
        }
        case 'actions':
            return `<td class="actions-cell use-history-actions-cell" data-col="${colId}">
                <div class="use-history-actions">
                    <button type="button" class="secondary-btn" onclick="editUseEntry(${entry.id})">Edit</button>
                    <button type="button" class="delete-btn" onclick="deleteUseEntry(${entry.id})" aria-label="Delete entry">×</button>
                </div>
            </td>`;
        default:
            return `<td data-col="${colId}">—</td>`;
    }
}

function getPurchaseHistoryColumnLabel(colId) {
    return TABLE_COLUMN_LABELS.purchaseHistory[colId] || colId;
}

function getPurchaseHistoryTableMinWidth(columns) {
    const widths = getPurchaseHistoryColumnWidthsMap();
    let min = 0;
    columns.forEach(colId => {
        min += getPurchaseHistoryColumnWidthPx(colId, widths[colId]);
    });
    return Math.max(min, 320);
}

function renderPurchaseHistoryHeaderCell(colId) {
    const label = resolveColumnDisplayLabel('purchaseHistory', colId);
    const resize = colId === 'select' ? '' : renderColumnResizeHandle('purchaseHistory', colId, label);
    if (colId === 'select') {
        return `<th class="select-cell" data-col="${colId}"><input type="checkbox" id="inventory-select-all" aria-label="Select all"></th>`;
    }
    if (colId === 'actions') {
        return `<th class="actions-cell" data-col="${colId}" title="${escapeAttr(label)}"><span class="customizable-th-label">${escapeHtml(label)}</span>${resize}</th>`;
    }
    if (colId === 'flavor') {
        const sortInd = purchaseHistorySort.colId === 'flavor'
            ? (purchaseHistorySort.dir === 'asc' ? ' ↑' : ' ↓')
            : '';
        return `<th data-col="${colId}" class="purchase-history-sortable" data-sort-col="flavor" role="button" tabindex="0" aria-label="Sort by ${escapeAttr(label)}" title="${escapeAttr(label)}"><span class="customizable-th-label">${escapeHtml(label)}${sortInd}</span>${resize}</th>`;
    }
    return `<th data-col="${colId}" title="${escapeAttr(label)}"><span class="customizable-th-label">${escapeHtml(label)}</span>${resize}</th>`;
}

function phTd(colId, content, className = '') {
    const label = getPurchaseHistoryColumnLabel(colId);
    const cls = className ? ` class="${className}"` : '';
    return `<td${cls} data-col="${colId}" data-label="${escapeAttr(label)}">${content}</td>`;
}

function renderPurchaseBoughtMetaInner(purchase) {
    if (isAlcoholPurchase(purchase)) {
        const pct = purchase.alcoholPercent;
        const vol = purchase.netVolumeMl;
        const pure = getAlcoholPureAlcoholMl(purchase);
        let meta = '';
        if (pct != null && pct !== '') meta += `<div class="purchase-vape-meta">Alcohol: ${formatAmount(pct)}%</div>`;
        if (vol != null && vol !== '') meta += `<div class="purchase-vape-meta">Net volume: ${formatAmount(vol)} mL</div>`;
        if (pure != null) meta += `<div class="purchase-vape-meta">Pure alcohol: ${formatAmount(pure)} mL</div>`;
        return meta;
    }
    if (isWeedPurchase(purchase)) {
        return `<div class="purchase-vape-meta">${formatWeedPurchaseDisplayLine(purchase)}</div>`;
    }
    if (isLsdPurchase(purchase)) {
        return `<div class="purchase-vape-meta">${formatLsdPurchaseDisplayLine(purchase)}</div>
            <div class="purchase-vape-meta">${formatLsdPurchaseCostLine(purchase)}</div>`;
    }
    if (isXanaxPurchase(purchase)) {
        return `<div class="purchase-vape-meta">${formatXanaxPurchaseDisplayLine(purchase)}</div>
            <div class="purchase-vape-meta">${formatXanaxPurchaseCostLine(purchase)}</div>`;
    }
    if (isCigarettesPurchase(purchase)) {
        return `<div class="purchase-vape-meta">${formatNicotinePurchaseQuantitySummary(purchase)}</div>`;
    }
    if (isNicotinePurchase(purchase)) {
        return `<div class="purchase-vape-meta">${formatNicotinePurchaseQuantitySummary(purchase)}</div>`;
    }
    return '';
}

function getPurchaseHistoryBoughtDisplayHtml(purchase) {
    if (isVapePuffPurchase(purchase)) {
        return formatVapePurchaseQuantitySummary(purchase);
    }
    if (isNicotinePurchase(purchase)) {
        return formatNicotinePurchaseQuantitySummary(purchase);
    }
    if (isWeedPurchase(purchase)) {
        return formatWeedPurchaseDisplayLine(purchase);
    }
    if (isLsdPurchase(purchase)) {
        return `<div>${formatLsdPurchaseDisplayLine(purchase)}</div>
            <div class="purchase-vape-meta">${formatLsdPurchaseCostLine(purchase)}</div>`;
    }
    if (isXanaxPurchase(purchase)) {
        return `<div>${formatXanaxPurchaseDisplayLine(purchase)}</div>
            <div class="purchase-vape-meta">${formatXanaxPurchaseCostLine(purchase)}</div>`;
    }
    const bought = getPurchaseQuantityBought(purchase);
    const unit = purchase.unit || 'units';
    const meta = renderPurchaseBoughtMetaInner(purchase);
    if (meta) {
        return `<div>${formatAmount(bought)}${unit}</div>${meta}`;
    }
    return `${formatAmount(bought)}${unit}`;
}

function renderPurchaseWeedBoughtCell(purchase) {
    return phTd('bought', getPurchaseHistoryBoughtDisplayHtml(purchase), 'purchase-weed-bought-cell');
}

function renderPurchaseLsdBoughtCell(purchase) {
    return phTd('bought', getPurchaseHistoryBoughtDisplayHtml(purchase), 'purchase-lsd-bought-cell');
}

function renderPurchaseXanaxBoughtCell(purchase) {
    return phTd('bought', getPurchaseHistoryBoughtDisplayHtml(purchase), 'purchase-xanax-bought-cell');
}

function renderPurchaseVapeBoughtCell(purchase) {
    return phTd('bought', getPurchaseHistoryBoughtDisplayHtml(purchase), 'purchase-vape-bought-cell purchase-quantity-compact');
}

function renderPurchaseNicotineBoughtCell(purchase) {
    return phTd('bought', getPurchaseHistoryBoughtDisplayHtml(purchase), 'purchase-nicotine-bought-cell purchase-quantity-compact');
}

function renderPurchaseInventoryStatusButtons(purchase) {
    const pid = escapeAttr(normalizePurchaseId(purchase.id));
    const tab = getPurchaseInventoryTab(purchase);
    const remaining = getPurchaseRemainingAmount(purchase);
    const parts = [];
    if (tab === 'hidden') {
        parts.push(`<button type="button" class="secondary-btn btn-sm" data-unhide-purchase="${pid}">Unhide</button>`);
    } else if (tab === 'gifted') {
        parts.push(`<button type="button" class="secondary-btn btn-sm" data-hide-purchase="${pid}">Hide</button>`);
    } else {
        if (tab === 'depleted' && remaining > INVENTORY_EPS) {
            parts.push(`<button type="button" class="secondary-btn btn-sm" data-mark-purchase-active="${pid}">Mark Active</button>`);
        }
        if (tab !== 'depleted') {
            parts.push(`<button type="button" class="secondary-btn btn-sm" data-mark-purchase-depleted="${pid}">Mark Depleted</button>`);
        }
        parts.push(`<button type="button" class="secondary-btn btn-sm" data-hide-purchase="${pid}">Hide</button>`);
    }
    parts.push(`<button type="button" class="secondary-btn btn-sm" data-recalculate-purchase="${pid}">Recalc</button>`);
    return parts.join('');
}

function renderPurchaseHistoryBodyCell(colId, ctx) {
    const {
        purchase, sub, cur, store, bought, remaining, pctUsed, supply, unit,
        breakCell, supplyDurationLabel, supplyDurationTooltip,
        totalNum, cpu, expanded, toggleLabel
    } = ctx;
    switch (colId) {
        case 'date':
            return phTd('date', formatDate(purchase.date || ''));
        case 'substance':
            return phTd(
                'substance',
                `${sub?.icon || ''} ${getSubstanceDisplayName(sub)}${renderPurchaseAcquisitionBadge(purchase)}`
            );
        case 'bought':
            if (isVapePuffPurchase(purchase)) {
                return renderPurchaseVapeBoughtCell(purchase);
            }
            if (isNicotinePurchase(purchase)) {
                return renderPurchaseNicotineBoughtCell(purchase);
            }
            if (isWeedPurchase(purchase)) {
                return renderPurchaseWeedBoughtCell(purchase);
            }
            if (isLsdPurchase(purchase)) {
                return renderPurchaseLsdBoughtCell(purchase);
            }
            if (isXanaxPurchase(purchase)) {
                return renderPurchaseXanaxBoughtCell(purchase);
            }
            return phTd('bought', getPurchaseHistoryBoughtDisplayHtml(purchase));
        case 'remaining': {
            const remDisplay = formatPurchaseRemainingDisplay(purchase);
            const remAmt = getPurchaseRemainingAmount(purchase);
            const boughtAmt = getPurchaseQuantityBought(purchase);
            const remPct = getPurchasePercentRemaining(purchase);
            const ccr = typeof evaluateInventoryColors === 'function'
                ? evaluateInventoryColors(remPct, {
                    substanceId: getPurchaseSubstanceId(purchase),
                    section: 'inventory'
                })
                : null;
            const valueHtml = (boughtAmt > 0 && remAmt != null)
                ? escapeHtml(formatMetricProgressPair(
                    formatAmountWithUnit(remAmt, purchase.unit || unit),
                    formatAmountWithUnit(boughtAmt, purchase.unit || unit)
                ))
                : remDisplay;
            return phTd(
                'remaining',
                renderMetricProgressCell(valueHtml, {
                    current: remAmt,
                    target: boughtAmt > 0 ? boughtAmt : null,
                    percent: remPct,
                    ccrResult: ccr,
                    metricKind: 'inventory',
                    currentLabel: remAmt != null
                        ? formatAmountWithUnit(remAmt, purchase.unit || unit)
                        : null,
                    targetLabel: boughtAmt > 0
                        ? formatAmountWithUnit(boughtAmt, purchase.unit || unit)
                        : null,
                    unit: purchase.unit || unit || ''
                }),
                'purchase-remaining-cell'
            );
        }
        case 'usedPct':
            return phTd(
                'usedPct',
                renderMetricProgressCell(escapeHtml(`${pctUsed}%`), {
                    current: pctUsed,
                    target: 100,
                    percent: pctUsed,
                    metricKind: 'use',
                    currentLabel: `${pctUsed}%`,
                    targetLabel: '100%',
                    unit: '%'
                })
            );
        case 'supplyDuration': {
            const titleAttr = supplyDurationTooltip ? ` title="${supplyDurationTooltip}"` : '';
            return `<td class="purchase-supply-duration-cell" data-col="supplyDuration" data-label="${escapeAttr(getPurchaseHistoryColumnLabel('supplyDuration'))}"${titleAttr}>${supplyDurationLabel}</td>`;
        }
        case 'supply':
            return phTd(
                'supply',
                `<span class="purchase-supply-status ${escapeAttr(supply.className)}"${supply.style ? ` style="${escapeAttr(supply.style)}"` : ''}>${escapeHtml(supply.label)}</span>`,
                'supply-cell'
            );
        case 'cost': {
            const cpu = getPurchaseHistoryCostPerUnit(purchase, totalNum);
            const cpuSuffix = getPurchaseHistoryCostPerUnitSuffix(purchase);
            let costMain = fmtSheetMoney(totalNum, cur);
            if (typeof evaluateSpendColors === 'function') {
                const ccr = evaluateSpendColors(totalNum, {
                    substanceId: getPurchaseSubstanceId(purchase),
                    section: 'purchaseHistory'
                });
                if (ccr.matched.length) {
                    costMain = wrapWithConditionalColor(costMain, ccr, { keepLabel: true });
                }
            }
            return phTd(
                'cost',
                `${costMain} <small>(${fmtSheetMoney(cpu, cur)}/${cpuSuffix})</small>`,
                'purchase-cost-cell'
            );
        }
        case 'store':
            return phTd('store', escapeHtml(typeof formatPurchaseSourceDisplay === 'function'
                ? formatPurchaseSourceDisplay(purchase)
                : (store || '—')));
        case 'payment':
            return phTd('payment', escapeHtml(purchase.paymentMethod || '—'));
        case 'costPerUnit': {
            const unitCpu = getPurchaseHistoryCostPerUnit(purchase, totalNum);
            const unitSuffix = getPurchaseHistoryCostPerUnitSuffix(purchase);
            return phTd('costPerUnit', Number.isFinite(unitCpu) ? (fmtSheetMoney(unitCpu, cur) + '/' + unitSuffix) : '—');
        }
        case 'acquisitionType':
            return phTd('acquisitionType', escapeHtml(getPurchaseAcquisitionType(purchase) || '—'));
        case 'supplier':
            return phTd('supplier', escapeHtml((typeof financialPurchaseSupplier === 'function' ? financialPurchaseSupplier(purchase) : (purchase.store || getPurchaseGiftSource(purchase) || '')) || '—'));
        case 'giftRecipient':
            return phTd('giftRecipient', escapeHtml(getPurchaseGiftRecipient(purchase) || '—'));
        case 'runningMonthlySpend':
            return phTd('runningMonthlySpend', escapeHtml(ctx.runningMonthlySpendLabel || '—'));
        case 'runningYearlySpend':
            return phTd('runningYearlySpend', escapeHtml(ctx.runningYearlySpendLabel || '—'));
        case 'budgetStatus': {
            if (ctx.budgetSpent == null || !(ctx.budgetAmount > 0)) {
                return phTd('budgetStatus', escapeHtml(ctx.budgetStatusLabel || '—'));
            }
            const ccr = typeof evaluateSpendColors === 'function'
                ? evaluateSpendColors(ctx.budgetSpent, {
                    substanceId: getPurchaseSubstanceId(purchase),
                    section: 'spending'
                })
                : null;
            const pair = formatMetricProgressPair(
                `${getCurrencySymbol()}${Number(ctx.budgetSpent).toFixed(2)}`,
                `${getCurrencySymbol()}${Number(ctx.budgetAmount).toFixed(2)}`
            );
            const statusBit = ctx.budgetStatusLabel && ctx.budgetStatusLabel !== '—'
                ? ` <span class="metric-progress-status-text">${escapeHtml(ctx.budgetStatusLabel)}</span>`
                : '';
            return phTd(
                'budgetStatus',
                renderMetricProgressCell(
                    `${escapeHtml(pair)}${statusBit}`,
                    {
                        current: ctx.budgetSpent,
                        target: ctx.budgetAmount,
                        percent: (ctx.budgetSpent / ctx.budgetAmount) * 100,
                        ccrResult: ccr,
                        metricKind: 'spend',
                        currentLabel: `${getCurrencySymbol()}${Number(ctx.budgetSpent).toFixed(2)}`,
                        targetLabel: `${getCurrencySymbol()}${Number(ctx.budgetAmount).toFixed(2)}`,
                        unit: getCurrencySymbol()
                    }
                )
            );
        }
        case 'productType':
            return phTd('productType', escapeHtml((typeof purchaseAnalyticsProductType === 'function' ? purchaseAnalyticsProductType(purchase) : (purchase.weedProductType || purchase.productType || purchase.flavor || '')) || '—'));
        case 'inventoryLifespan':
            return phTd('inventoryLifespan', typeof purchaseHistoryInventoryLifespanLabel === 'function' ? purchaseHistoryInventoryLifespanLabel(purchase) : (supplyDurationLabel || '—'));
        case 'giftStatus':
            return phTd('giftStatus', typeof purchaseHistoryGiftStatusLabel === 'function' ? purchaseHistoryGiftStatusLabel(purchase) : '—');
        case 'linkedUsers':
            return phTd('linkedUsers', escapeHtml(typeof purchaseHistoryLinkedUsersLabel === 'function' ? purchaseHistoryLinkedUsersLabel(purchase) : '—'));
        case 'purchaseQualityRating':
            return phTd('purchaseQualityRating', typeof purchaseHistoryQualityRating === 'function' ? purchaseHistoryQualityRating(purchase) : '—');
        case 'flavor': {
            const flavor = isVapePuffPurchase(purchase) ? getVapePurchaseFlavor(purchase) : '';
            return phTd('flavor', flavor ? escapeHtml(flavor) : '—', 'purchase-flavor-cell');
        }
        case 'notes':
            return phTd('notes', escapeHtml(purchase.notes || '—'), 'notes-cell');
        case 'break':
            return phTd('break', breakCell);
        case 'actions': {
            const pid = normalizePurchaseId(purchase.id);
            const markEmptyBtn = isVapePuffPurchase(purchase) && remaining > INVENTORY_EPS
                ? `<button type="button" class="secondary-btn btn-sm" data-mark-vape-empty="${escapeAttr(pid)}">Mark empty</button>`
                : '';
            const vapeLifecycleBtns = isVapePuffPurchase(purchase) ? `
                <button type="button" class="secondary-btn btn-sm" data-mark-vape-finished="${escapeAttr(pid)}">Mark Finished</button>` : '';
            const statusBtns = renderPurchaseInventoryStatusButtons(purchase);
            const buttons = `
                <button type="button" class="secondary-btn btn-sm purchase-expand-btn" data-purchase-toggle="${escapeAttr(pid)}" data-toggle-purchase-logs="${escapeAttr(pid)}" aria-expanded="${expanded ? 'true' : 'false'}">${toggleLabel}</button>
                <button type="button" class="secondary-btn btn-sm" data-edit-purchase="${escapeAttr(pid)}">Edit</button>
                <button type="button" class="secondary-btn btn-sm" data-duplicate-purchase-now="${escapeAttr(pid)}">Duplicate</button>
                ${markEmptyBtn}
                ${vapeLifecycleBtns}
                ${statusBtns}
                <button type="button" class="delete-btn btn-sm" data-delete-purchase="${escapeAttr(pid)}">Delete</button>`;
            return phTd(
                'actions',
                `<div class="purchase-history-actions-wrap">${buttons}</div>`,
                'actions-cell purchase-history-actions-cell'
            );
        }
        case 'select': {
            const pid = normalizePurchaseId(purchase.id);
            const checked = inventorySelectedIds.has(pid) ? 'checked' : '';
            return phTd('select', `<input type="checkbox" class="inventory-select-cb" data-inventory-select="${escapeAttr(pid)}" ${checked} aria-label="Select purchase">`, 'select-cell');
        }
        default:
            return phTd(colId, '—');
    }
}

function normalizeMainSubstances(data) {
    if (!data.substances?.length) return;
    normalizeSubstanceRecords(data);
    data.substances.forEach(s => {
        if (s.isMain === undefined) s.isMain = false;
    });
    const active = data.substances.filter(s => isSubstanceActive(s) && !isLegacyNicotineSubstanceId(s.id));
    if (!active.length) {
        data.substances.forEach(s => { s.isMain = false; });
        return;
    }
    let main = active.find(s => s.isMain);
    if (main && isLegacyNicotineSubstanceId(main.id)) {
        main = active.find(s => s.id === NICOTINE_ID) || active[0];
    }
    if (!main) {
        main = active.find(s => s.id === DEFAULT_MAIN_SUBSTANCE_ID)
            || active.find(s => s.id === NICOTINE_ID)
            || findSubstanceByNormalizedName(active, 'Nicotine')
            || active[0];
        main.isMain = true;
    }
    data.substances.forEach(s => {
        s.isMain = isSubstanceActive(s) && !isLegacyNicotineSubstanceId(s.id) && s.id === main.id;
    });
}

function saveData(data) {
    try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
        const savedAt = new Date().toISOString();
        localStorage.setItem(LAST_SAVED_KEY, savedAt);
        invalidateInsightsDatasetCache();
        updateLastSavedDisplay(savedAt);
        console.log('Saved recovery data');
        return true;
    } catch (err) {
        console.error('Failed to save recovery data:', err);
        return false;
    }
}

function persistLoadedAppDataIfNeeded() {
    if (appDataLoadedFromStorage) {
        saveData(appData);
    }
}

function getLastSavedTimestamp() {
    return localStorage.getItem(LAST_SAVED_KEY);
}

function formatLastSaved(iso) {
    if (!iso) return 'Never';
    const d = new Date(iso);
    return Number.isNaN(d.getTime()) ? 'Never' : d.toLocaleString();
}

function updateLastSavedDisplay(iso) {
    const label = `Last Saved: ${formatLastSaved(iso || getLastSavedTimestamp())}`;
    ['dashboard-last-saved', 'settings-last-saved'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.textContent = label;
    });
    updateAutoBackupDisplay();
}

function createAutoBackup(reason = 'auto') {
    try {
        const payload = {
            savedAt: new Date().toISOString(),
            reason,
            data: JSON.parse(JSON.stringify(appData))
        };
        localStorage.setItem(AUTO_BACKUP_KEY, JSON.stringify(payload));
        updateAutoBackupDisplay();
        return true;
    } catch (err) {
        console.error('Auto backup failed', err);
        return false;
    }
}

function createAutoBackupFromData(data, reason = 'migration') {
    try {
        const payload = {
            savedAt: new Date().toISOString(),
            reason,
            data: JSON.parse(JSON.stringify(data))
        };
        localStorage.setItem(AUTO_BACKUP_KEY, JSON.stringify(payload));
        return true;
    } catch (err) {
        console.error('Auto backup failed', err);
        return false;
    }
}

function getAutoBackupInfo() {
    try {
        const raw = localStorage.getItem(AUTO_BACKUP_KEY);
        if (!raw) return null;
        const parsed = JSON.parse(raw);
        return parsed?.savedAt ? { savedAt: parsed.savedAt, reason: parsed.reason || 'auto' } : null;
    } catch {
        return null;
    }
}

function updateAutoBackupDisplay() {
    const info = getAutoBackupInfo();
    const label = info ? formatLastSaved(info.savedAt) : 'Never';
    const el = document.getElementById('settings-auto-backup-date');
    if (el) el.textContent = label;
}

function restoreLastAutoBackup() {
    const raw = localStorage.getItem(AUTO_BACKUP_KEY);
    if (!raw) {
        alert('No automatic backup found.');
        return;
    }
    let parsed;
    try {
        parsed = JSON.parse(raw);
    } catch {
        alert('Could not read the automatic backup.');
        return;
    }
    const backupData = parsed?.data;
    const validation = validateBackupData(backupData);
    if (!validation.ok) {
        alert(validation.message || 'Automatic backup is invalid.');
        return;
    }
    if (!confirm('Restore the last automatic backup? Current data will be replaced.')) return;
    createAutoBackup('before-restore');
    appData = validation.data;
    normalizeAppData(appData);
    repairAppDataAfterImport(appData);
    saveData(appData);
    refreshAppAfterDataChange();
    alert('Restored from last automatic backup.');
}

function repairAppData() {
    if (!confirm('Repair data consistency issues?\n\nAn automatic backup will be saved first.')) return;
    pushChangeHistory('before-repair', { summary: 'Before data repair' });
    createAutoBackup('before-repair');
    repairVapeInventoryLinks(appData);
    const stats = repairDataConsistency(appData);
    saveData(appData);
    refreshAppAfterDataChange();
    alert(`Data repair complete.\n\n${formatRepairSummary(stats)}`);
    renderDataHealthPanel();
}

function setText(id, text) {
    const el = document.getElementById(id);
    if (el) el.textContent = text;
}

function setInputValue(id, value) {
    const el = document.getElementById(id);
    if (el != null) el.value = value;
}

// Clears the optional session end date/time inputs on the Use form.
function clearUseEndTimeInputs({ hideDurationPreview = true } = {}) {
    setInputValue('use-end-time', '');
    setInputValue('use-end-date', '');
    if (hideDurationPreview) document.getElementById('use-duration-preview')?.classList.add('hidden');
}

function getMainSubstance() {
    if (!appData?.substances?.length) return null;
    return appData.substances.find(s => isSubstanceActive(s) && s.isMain) || getActiveSubstances()[0] || null;
}

function getMainSubstanceId() {
    if (!appData?.substances?.length) return DEFAULT_MAIN_SUBSTANCE_ID;
    return getMainSubstance()?.id || DEFAULT_MAIN_SUBSTANCE_ID;
}

function resolveStartupSubstanceId() {
    return resolveDashboardViewSubstanceId();
}

function resolveDefaultSelectedSubstanceId() {
    ensureAppDataSubstancesReady(appData);
    if (!appData?.substances?.length) return DASHBOARD_ALL;
    const mainId = resolveSelectedSubstanceId(getMainSubstanceId());
    if (mainId && substanceIsDashboardViewOption(mainId)) return mainId;
    return getActiveSubstances()[0]?.id || appData.substances[0]?.id || DASHBOARD_ALL;
}

function resolveDefaultTaperSubstanceId(data = appData) {
    ensureAppDataSubstancesReady(data);
    const taperSubstances = getTaperSubstances(data);
    if (!taperSubstances.length) {
        return getActiveSubstances(data)[0]?.id || data?.substances?.[0]?.id || DASHBOARD_ALL;
    }
    const storedId = resolveSelectedSubstanceId(data?.settings?.taperSubstanceId, data);
    if (storedId && taperSubstances.some(sub => sub.id === storedId)) return storedId;
    const recentId = resolveSelectedSubstanceId(selectedSubstanceId, data);
    if (recentId && taperSubstances.some(sub => sub.id === recentId)) return recentId;
    return taperSubstances[0]?.id || getActiveSubstances(data)[0]?.id || data?.substances?.[0]?.id || DASHBOARD_ALL;
}

function persistTaperSubstanceId(id, data = appData) {
    if (!data.settings || typeof data.settings !== 'object') data.settings = {};
    const resolved = resolveSelectedSubstanceId(id, data);
    if (!resolved || resolved === DASHBOARD_ALL) delete data.settings.taperSubstanceId;
    else data.settings.taperSubstanceId = resolved;
    if (typeof saveData === 'function') saveData(data);
}

function isSelectedAllSubstances() {
    return selectedSubstanceId === DASHBOARD_ALL;
}

function getSelectedSubstanceFilterId() {
    return isSelectedAllSubstances() ? null : selectedSubstanceId;
}

function sortSubstancesMainFirst(list) {
    return [...list].sort((a, b) => {
        if (a.isMain !== b.isMain) return a.isMain ? -1 : 1;
        if (a.active !== b.active) return a.active ? -1 : 1;
        const catalogDiff = getSubstanceCatalogIndex(a) - getSubstanceCatalogIndex(b);
        if (catalogDiff !== 0) return catalogDiff;
        return a.name.localeCompare(b.name);
    });
}

let appData;
try {
    appData = loadData();
} catch (error) {
    console.error('Failed to load app data:', error);
    const hasStoredData = !!localStorage.getItem(STORAGE_KEY) || !!localStorage.getItem(STORAGE_KEY_V1);
    const backup = loadAutoBackupAppData();
    if (backup) {
        appDataLoadedFromStorage = true;
        appData = normalizeAppDataSafe(backup);
        console.log('Loaded saved recovery data');
    } else if (hasStoredData) {
        console.error('Saved data exists but could not be loaded. Defaults shown in memory only — storage was not overwritten.');
        appData = normalizeAppDataSafe(getDefaultAppData());
    } else {
        appData = normalizeAppDataSafe(getDefaultAppData());
        console.log('No saved data found, using defaults');
    }
}

