// ——— Substance helpers ———
function getSubstance(id, data = appData) {
    if (!id) return null;
    const substances = data?.substances || [];
    const resolvedId = normalizeSubstanceRef(id, data);
    if (isLegacyNicotineSubstanceId(id) || isLegacyNicotineSubstanceId(resolvedId)) {
        return substances.find(s => s.id === NICOTINE_ID)
            || substances.find(s => s.id === id || s.name === id)
            || null;
    }
    return substances.find(s => s.id === id || s.id === resolvedId || s.name === id) || null;
}

function getSubstanceName(id) {
    return getSubstance(id)?.name || 'Unknown';
}

function isSubstanceActive(sub) {
    return !!sub && sub.active !== false && !sub.archived;
}

function normalizeSubstanceRecords(data) {
    if (!Array.isArray(data.substances)) data.substances = [];
    data.substances.forEach(sub => {
        if (sub.active === undefined && !sub.archived) sub.active = true;
        if (sub.isMain === undefined) sub.isMain = false;
    });
}

function ensureAppDataSubstancesReady(data = appData) {
    if (!data || typeof data !== 'object') return;
    if (!Array.isArray(data.substances)) data.substances = [];
    if (!data.substances.length) {
        data.substances = getDefaultSubstances();
    }
    normalizeSubstanceRecords(data);
    ensureDefaultSubstances(data);
    normalizeMainSubstances(data);
}

function substanceIsDashboardViewOption(substanceId, data = appData) {
    if (!substanceId || substanceId === DASHBOARD_ALL) return substanceId === DASHBOARD_ALL;
    const resolved = normalizeSubstanceRef(substanceId, data);
    return getActiveSubstances(data).some(s => s.id === resolved);
}

function resolveDashboardViewSubstanceId(data = appData) {
    ensureAppDataSubstancesReady(data);
    ensureAppDataSettings(data);

    const saved = data.settings?.dashboardSubstanceId;
    if (saved === DASHBOARD_ALL) return DASHBOARD_ALL;
    if (saved && substanceIsDashboardViewOption(saved, data)) {
        return resolveSelectedSubstanceId(saved, data) || saved;
    }

    const active = getActiveSubstances(data);
    const mainId = getMainSubstanceId();
    if (mainId && active.some(s => s.id === mainId)) return mainId;

    if (currentSubstanceId && currentSubstanceId !== DASHBOARD_ALL) {
        const resolved = normalizeSubstanceRef(currentSubstanceId, data);
        if (active.some(s => s.id === resolved)) return resolved;
    }

    if (active[0]?.id) return active[0].id;
    if (data.substances?.[0]?.id) return data.substances[0].id;
    return DASHBOARD_ALL;
}

function saveDashboardViewSubstanceId(substanceId) {
    ensureAppDataSettings(appData);
    appData.settings.dashboardSubstanceId = substanceId || DASHBOARD_ALL;
    saveData(appData);
}

function ensureDashboardSubstanceDropdownReady() {
    ensureAppDataSubstancesReady(appData);
    selectedDashboardSubstance = getSelectedDashboardSubstance(appData);
    currentSubstanceId = selectedDashboardSubstance;
    populateAllSubstanceDropdowns();
    syncSubstanceSelectors();

    const dash = document.getElementById('dashboard-substance');
    const substanceOptionCount = dash
        ? [...dash.options].filter(o => o.value && o.value !== DASHBOARD_ALL).length
        : 0;

    if (!substanceOptionCount) {
        ensureAppDataSubstancesReady(appData);
        if (!appData.substances.length) {
            appData.substances = getDefaultSubstances();
        }
        normalizeSubstanceRecords(appData);
        normalizeMainSubstances(appData);
        currentSubstanceId = resolveDashboardViewSubstanceId();
        populateAllSubstanceDropdowns();
        syncSubstanceSelectors();
    }

    if (dash && [...dash.options].some(o => o.value === selectedDashboardSubstance)) {
        dash.value = selectedDashboardSubstance;
        currentSubstanceId = selectedDashboardSubstance;
    } else if (dash) {
        const fallback = getActiveSubstances()[0]?.id || DASHBOARD_ALL;
        selectedDashboardSubstance = fallback;
        currentSubstanceId = fallback;
        dash.value = fallback;
        persistRecoveryDashboardPrefs({ selectedDashboardSubstance: fallback });
        saveDashboardViewSubstanceId(fallback);
    }
}

function getActiveSubstances(data = appData) {
    return sortSubstancesMainFirst(
        (data.substances || []).filter(s => isSubstanceActive(s) && !isLegacyNicotineSubstanceId(s.id))
    );
}

function setMainSubstance(id) {
    const sub = getSubstance(id);
    if (!sub) return;
    if (!sub.active) return alert('Only active substances can be set as main.');
    appData.substances.forEach(s => { s.isMain = s.id === id; });
    saveData(appData);
    currentSubstanceId = id;
    selectedSubstanceId = id;
    populateAllSubstanceDropdowns();
    populatePageSubstanceDropdowns();
    syncUseLogFormFromSelectedSubstance();
    applyMainSubstanceToViewSelectors();
    syncSubstanceSelectors();
    applyMainSubstanceToForms();
    renderSubstancesList();
    updateDashboardMainDisplay();
    updateDashboard();
    updateQuickActions();
    syncTaperSubstanceToMain();
    refreshTaperDashboard();
}

function applyMainSubstanceToForms() {
    const mainId = getMainSubstanceId();
    syncUseLogFormFromSelectedSubstance();
    syncBuyFormFromSelectedSubstance();
    if (!mainId || !isSelectedAllSubstances()) return;
    const useEl = document.getElementById('use-substance');
    if (useEl && [...useEl.options].some(o => o.value === mainId)) useEl.value = mainId;
    const buyEl = document.getElementById('buy-substance');
    if (buyEl && [...buyEl.options].some(o => o.value === mainId)) buyEl.value = mainId;
    updateUseUnitDropdown();
    updateBuyUnitDropdown();
}

function applyMainSubstanceToViewSelectors() {
    syncSubstanceSelectors();
    const mainId = getMainSubstanceId();
    if (!mainId) return;
    const taperEl = document.getElementById('taper-substance');
    if (taperEl && [...taperEl.options].some(o => o.value === mainId)) taperEl.value = mainId;
}

function getLoggableSubstances() {
    return getActiveSubstances();
}

function getCostTrackedSubstances() {
    return appData.substances.filter(s => s.active && s.costTrackingEnabled);
}

function getTaperSubstances() {
    return sortSubstancesMainFirst(appData.substances.filter(s => s.active && s.taperTrackingEnabled));
}

function getAveragePurchaseCostPerUnit(substanceId, data = appData) {
    const purchases = (data.purchases || []).filter(p =>
        getPurchaseSubstanceId(p) === substanceId && purchaseCountsAsBuySpend(p)
    );
    const withCpu = purchases.filter(p => {
        const cpu = parseFloat(p.costPerUnit);
        return Number.isFinite(cpu) && cpu > 0;
    });
    if (!withCpu.length) return null;
    return withCpu.reduce((s, p) => s + parseFloat(p.costPerUnit), 0) / withCpu.length;
}

function getTaperStartingDailyAverage(substanceId) {
    const plan = getPrimaryTaperPlan(substanceId);
    if (!plan) return null;
    const val = plan.startingDailyAverage ?? plan.currentAvg;
    return val != null && val !== '' ? parseFloat(val) : null;
}

function isAllSubstancesView() {
    return currentSubstanceId === DASHBOARD_ALL;
}

function buildSubstanceOption(sub, { includeIcon = true } = {}) {
    const opt = document.createElement('option');
    opt.value = sub.id;
    const prefix = sub.isMain ? '⭐ ' : '';
    opt.textContent = includeIcon ? `${prefix}${sub.icon} ${sub.name}` : `${prefix}${sub.name}`;
    opt.style.color = sub.color;
    return opt;
}

function populateSelect(selectId, substances, { includeAll = false, currentValue } = {}) {
    const dropdown = document.getElementById(selectId);
    if (!dropdown) return;
    const prev = currentValue ?? dropdown.value;
    dropdown.innerHTML = '';
    if (includeAll) {
        const all = document.createElement('option');
        all.value = DASHBOARD_ALL;
        all.textContent = '📊 All Substances';
        dropdown.appendChild(all);
    }
    substances.forEach(sub => dropdown.appendChild(buildSubstanceOption(sub)));
    const valid = [...dropdown.options].some(o => o.value === prev);
    const fallback = substances[0]?.id || (includeAll ? DASHBOARD_ALL : '');
    dropdown.value = valid ? prev : fallback;
}

function populateAllSubstanceDropdowns() {
    const active = getActiveSubstances();
    const viewDefault = getSelectedDashboardSubstance();
    const mainId = getMainSubstanceId();

    populateSelect('dashboard-substance', active, { includeAll: true, currentValue: viewDefault });
    populateSelect('stats-substance', active, { includeAll: true, currentValue: viewDefault });
    populateSelect('use-substance', getLoggableSubstances(), { currentValue: resolveSelectedSubstanceId(isSelectedAllSubstances() ? getMainSubstanceId() : selectedSubstanceId) });
    populateSelect('buy-substance', active, { currentValue: resolveSelectedSubstanceId(isSelectedAllSubstances() ? mainId : selectedSubstanceId) });
    populatePageSubstanceDropdowns();
    populateTaperReductionTypeSelect(getTaperSubstanceId());
    updateUseUnitDropdown();
    updateBuyUnitDropdown();
}

function syncSubstanceSelectors() {
    ['dashboard-substance', 'stats-substance'].forEach(id => {
        const el = document.getElementById(id);
        if (el && [...el.options].some(o => o.value === currentSubstanceId)) {
            el.value = currentSubstanceId;
        }
    });
    const taperEl = document.getElementById('taper-substance');
    if (taperEl && getTaperSubstances().some(s => s.id === currentSubstanceId)) {
        taperEl.value = currentSubstanceId;
    }
}

function updateUseUnitDropdown() {
    const substanceSelect = document.getElementById('use-substance');
    const unitSelect = document.getElementById('use-unit');
    if (!substanceSelect || !unitSelect) return;
    const sub = getSubstance(substanceSelect.value);
    const units = sub?.units || ['units'];
    unitSelect.innerHTML = '';
    units.forEach(unit => {
        const option = document.createElement('option');
        option.value = unit;
        option.textContent = unit;
        unitSelect.appendChild(option);
    });
    if (sub?.defaultUnit) unitSelect.value = sub.defaultUnit;
    updateSubstanceTrackingFormUI();
    updateVapeUseFormUI();
}

function updateSubstanceTrackingFormUI() {
    const substanceId = document.getElementById('use-substance')?.value;
    if (isWeedTrackingMode(substanceId)) {
        updateWeedUseFormUI();
        return;
    }
    document.getElementById('use-weed-product-type-group')?.classList.add('hidden');
    const amountLabel = document.getElementById('use-amount-label');
    const countLabel = document.querySelector('#use-count-group label');
    const primaryUnit = getSubstancePrimaryUnit(substanceId);
    const countFieldLabel = getSubstanceSecondaryCountLabel(substanceId);
    if (amountLabel) {
        amountLabel.textContent = primaryUnit && primaryUnit !== 'units'
            ? `Amount (${primaryUnit})`
            : 'Amount';
    }
    if (countLabel) {
        countLabel.textContent = countFieldLabel
            ? `${countFieldLabel.charAt(0).toUpperCase()}${countFieldLabel.slice(1)} (optional)`
            : 'Count (optional)';
    }
}

function updateBuyUnitDropdown() {
    const substanceSelect = document.getElementById('buy-substance');
    const unitSelect = document.getElementById('buy-unit');
    if (!substanceSelect || !unitSelect) return;
    const sub = getSubstance(substanceSelect.value);
    const units = sub?.units || ['units'];
    unitSelect.innerHTML = '';
    units.forEach(unit => {
        const option = document.createElement('option');
        option.value = unit;
        option.textContent = unit;
        unitSelect.appendChild(option);
    });
    if (sub?.defaultUnit) unitSelect.value = sub.defaultUnit;
    updateBuyVapeFieldsVisibility();
    updateBuyAcquisitionTypeUI();
}

function updateQuickActions() {
    const logBtn = document.getElementById('quick-log-btn');
    if (!logBtn) return;
    const icon = logBtn.querySelector('.quick-icon');
    const label = logBtn.querySelector('.quick-label');
    if (!icon || !label) return;
    if (isAllSubstancesView()) {
        icon.textContent = '📊';
        label.textContent = 'Quick Use (pick substance)';
        return;
    }
    const sub = getSubstance(currentSubstanceId);
    if (sub) {
        icon.textContent = sub.icon;
        label.textContent = 'Quick Use';
    }
}

function switchSubstance(substanceId) {
    setSelectedDashboardSubstance(substanceId, { persist: true, render: true, syncStats: true });
}

function switchStatsSubstance(substanceId) {
    clearInsightsSectionOutputs();
    if (typeof setSelectedInsightsSubstance === 'function') {
        setSelectedInsightsSubstance(substanceId, { render: false, save: true });
    } else {
        setSelectedDashboardSubstance(substanceId, { persist: true, render: false, syncStats: false });
    }
    const dash = document.getElementById('dashboard-substance');
    if (dash) dash.value = selectedDashboardSubstance;
    const statsSelect = document.getElementById('stats-substance');
    if (statsSelect) statsSelect.value = selectedDashboardSubstance;
    const calSel = document.getElementById('stats-calendar-substance');
    if (calSel && [...calSel.options].some(o => o.value === selectedDashboardSubstance)) {
        calSel.value = selectedDashboardSubstance;
    }
    syncInsightsFilterUi();
    updateStats();
}

function filterLogsBySubstance(logs, substanceId) {
    if (substanceId === DASHBOARD_ALL) return logs;
    return logs.filter(log => logMatchesSubstance(log, substanceId));
}

// ——— Manage Substances ———
function renderSubstancesList() {
    const container = document.getElementById('substances-list');
    if (!container) return;
    container.innerHTML = '';

    const sorted = sortSubstancesMainFirst(
        appData.substances.filter(s => !isLegacyNicotineSubstanceId(s.id))
    );

    if (sorted.length === 0) {
        container.innerHTML = '<p class="empty-hint">No substances yet. Add one below.</p>';
        applyCollapsedSections();
        return;
    }

    sorted.forEach(sub => {
        const item = document.createElement('div');
        item.className = `substance-card ${sub.active ? '' : 'archived'}`;
        item.style.borderLeftColor = sub.color;
        item.innerHTML = `
            <div class="substance-card-main">
                <span class="substance-card-icon">${escapeHtml(sub.icon)}</span>
                <div>
                    <strong>${escapeHtml(sub.name)}</strong>${sub.isMain ? ' <span class="main-badge">⭐ Main</span>' : ''}
                    <div class="substance-card-meta">
                        ${escapeHtml(sub.defaultUnit)} · ${sub.costTrackingEnabled ? '💰 cost' : ''}${sub.costTrackingEnabled && sub.taperTrackingEnabled ? ' · ' : ''}${sub.taperTrackingEnabled ? '📉 taper' : ''}
                        ${!sub.active ? ' · <em>archived</em>' : ''}
                    </div>
                </div>
            </div>
            <div class="substance-card-actions">
                ${sub.active && !sub.isMain ? `<button type="button" class="secondary-btn main-set-btn" onclick="setMainSubstance('${escapeAttr(sub.id)}')">⭐ Set as Main</button>` : ''}
                <button type="button" class="secondary-btn" onclick="openSubstanceEditor('${escapeAttr(sub.id)}')">Edit</button>
                ${sub.active
                    ? `<button type="button" class="secondary-btn" onclick="archiveSubstance('${escapeAttr(sub.id)}')">Archive</button>`
                    : `<button type="button" class="secondary-btn" onclick="restoreSubstance('${escapeAttr(sub.id)}')">Restore</button>`}
                <button type="button" class="delete-btn" onclick="deleteSubstance('${escapeAttr(sub.id)}')">Delete</button>
            </div>
        `;
        container.appendChild(item);
    });
    applyCollapsedSections();
}

function openSubstanceEditor(id) {
    editingSubstanceId = id || null;
    const modal = document.getElementById('substance-modal');
    const title = document.getElementById('substance-editor-title');
    const unitsInput = document.getElementById('substance-units');
    const iconPicker = document.getElementById('substance-icon-picker');
    const colorPicker = document.getElementById('substance-color-picker');
    if (!modal || !title || !unitsInput || !iconPicker || !colorPicker) return;

    title.textContent = id ? 'Edit Substance' : 'Add Substance';
    iconPicker.innerHTML = '';
    SUBSTANCE_ICONS.forEach(icon => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'icon-pick-btn icon-option';
        btn.textContent = icon;
        btn.dataset.icon = icon;
        btn.onclick = () => {
            iconPicker.querySelectorAll('.icon-option').forEach(b => b.classList.remove('selected'));
            btn.classList.add('selected');
            setInputValue('substance-icon', icon);
        };
        iconPicker.appendChild(btn);
    });

    colorPicker.innerHTML = '';
    SUBSTANCE_COLORS.forEach(color => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'color-pick-btn color-option';
        btn.style.background = color;
        btn.dataset.color = color;
        btn.onclick = () => {
            colorPicker.querySelectorAll('.color-option').forEach(b => b.classList.remove('selected'));
            btn.classList.add('selected');
            setInputValue('substance-color', color);
        };
        colorPicker.appendChild(btn);
    });

    const submitBtn = document.getElementById('save-substance-btn');
    if (submitBtn) submitBtn.textContent = id ? 'Save Changes' : 'Save Substance';

    if (id) {
        const sub = getSubstance(id);
        setInputValue('substance-name', sub.name);
        setInputValue('substance-icon', sub.icon);
        setInputValue('substance-color', sub.color);
        setInputValue('substance-default-unit', sub.defaultUnit);
        unitsInput.value = sub.units.join(', ');
        const costEl = document.getElementById('substance-cost-tracking');
        const taperEl = document.getElementById('substance-taper-tracking');
        if (costEl) costEl.checked = sub.costTrackingEnabled;
        if (taperEl) taperEl.checked = sub.taperTrackingEnabled;
        iconPicker.querySelectorAll('.icon-option').forEach(b => {
            if (b.textContent === sub.icon || b.dataset.icon === sub.icon) b.classList.add('selected');
        });
        colorPicker.querySelectorAll('.color-option').forEach(b => {
            if (b.dataset.color === sub.color) b.classList.add('selected');
        });
    } else {
        const form = document.getElementById('substance-form');
        form?.reset();
        setInputValue('substance-icon', '📦');
        setInputValue('substance-color', SUBSTANCE_COLORS[0]);
        const costEl = document.getElementById('substance-cost-tracking');
        const taperEl = document.getElementById('substance-taper-tracking');
        if (costEl) costEl.checked = true;
        if (taperEl) taperEl.checked = true;
        unitsInput.value = 'units';
        setInputValue('substance-default-unit', 'units');
        iconPicker.querySelector('.icon-option')?.classList.add('selected');
        colorPicker.querySelector('.color-option')?.classList.add('selected');
    }

    modal.classList.remove('hidden');
    document.getElementById('substance-name')?.focus();
}

function closeSubstanceEditor() {
    closeSubstanceModal();
}

function closeSubstanceModal() {
    document.getElementById('substance-modal')?.classList.add('hidden');
    document.getElementById('substance-form')?.reset();
    editingSubstanceId = null;
}

function handleSubstanceSubmit(e) {
    if (e) e.preventDefault();

    console.log('[substance] submit started');

    try {
        if (!appData || typeof appData !== 'object') appData = {};
        if (!Array.isArray(appData.substances)) appData.substances = [];
        if (!appData.settings) appData.settings = {};
        if (!appData.settings.substanceSettings) appData.settings.substanceSettings = {};

        const nameEl = document.getElementById('substance-name');
        const unitsEl = document.getElementById('substance-units');
        const defaultUnitEl = document.getElementById('substance-default-unit');

        if (!nameEl) {
            alert('Missing substance-name input.');
            console.error('[substance] missing #substance-name');
            return;
        }

        const name = nameEl.value.trim();

        if (!name) {
            alert('Enter a substance name.');
            return;
        }

        const duplicate = appData.substances.some(s =>
            String(s.name || '').toLowerCase() === name.toLowerCase()
            && s.id !== editingSubstanceId
        );

        if (duplicate) {
            alert('That substance already exists.');
            return;
        }

        const selectedIcon = document.querySelector('#substance-icon-picker .icon-option.selected')
            || document.querySelector('.icon-option.selected');
        const selectedColor = document.querySelector('#substance-color-picker .color-option.selected')
            || document.querySelector('.color-option.selected');

        const icon = selectedIcon?.dataset.icon || selectedIcon?.textContent?.trim() || '📦';
        const color = selectedColor?.dataset.color
            || document.getElementById('substance-color')?.value
            || SUBSTANCE_COLORS[0];

        const unitsText = unitsEl?.value?.trim() || 'units';
        const units = unitsText.split(',').map(u => u.trim()).filter(Boolean);
        if (units.length === 0) units.push('units');

        const defaultUnit = defaultUnitEl?.value?.trim() || units[0] || 'units';
        const costTrackingEnabled = document.getElementById('substance-cost-tracking')?.checked !== false;
        const taperTrackingEnabled = document.getElementById('substance-taper-tracking')?.checked !== false;

        let savedSubstance;

        if (editingSubstanceId) {
            const idx = appData.substances.findIndex(s => s.id === editingSubstanceId);
            if (idx < 0) {
                alert('Substance to edit was not found.');
                return;
            }
            savedSubstance = {
                ...appData.substances[idx],
                name,
                icon,
                color,
                units,
                defaultUnit,
                costTrackingEnabled,
                taperTrackingEnabled,
                active: true,
                archived: false,
                updatedAt: new Date().toISOString()
            };
            appData.substances[idx] = savedSubstance;
        } else {
            const activeCount = appData.substances.filter(s => s.active && !s.archived).length;
            savedSubstance = {
                id: 'sub-' + Date.now(),
                name,
                icon,
                color,
                units,
                defaultUnit,
                active: true,
                archived: false,
                isMain: activeCount === 0,
                costTrackingEnabled,
                taperTrackingEnabled,
                createdAt: new Date().toISOString(),
                updatedAt: new Date().toISOString()
            };

            appData.substances.push(savedSubstance);

            appData.settings.substanceSettings[savedSubstance.id] = {
                defaultUnit,
                units
            };
        }

        normalizeMainSubstances(appData);
        saveData(appData);
        console.log('[substance] saved', savedSubstance);

        const wasEdit = !!editingSubstanceId;
        safeRefreshAfterSubstanceSave();
        alert(wasEdit ? 'Substance updated: ' + name : 'Substance added: ' + name);
    } catch (err) {
        console.error('[substance] save failed', err);
        alert('Save failed. Open Console and send the red error.');
    }
}

function safeRefreshAfterSubstanceSave() {
    try {
        if (typeof updateLastSaved === 'function') updateLastSaved();
        else if (typeof updateLastSavedDisplay === 'function') updateLastSavedDisplay();
    } catch (err) {
        console.error('[substance] updateLastSaved failed', err);
    }
    try {
        if (typeof closeSubstanceModal === 'function') closeSubstanceModal();
    } catch (err) {
        console.error('[substance] closeSubstanceModal failed', err);
    }
    try {
        if (typeof renderSubstances === 'function') renderSubstances();
        else if (typeof renderSubstancesList === 'function') renderSubstancesList();
    } catch (err) {
        console.error('[substance] renderSubstances failed', err);
    }
    try {
        if (typeof populateSubstanceDropdowns === 'function') populateSubstanceDropdowns();
        else if (typeof populateAllSubstanceDropdowns === 'function') populateAllSubstanceDropdowns();
    } catch (err) {
        console.error('[substance] populateSubstanceDropdowns failed', err);
    }
    try {
        if (typeof updateDashboard === 'function') updateDashboard();
    } catch (err) {
        console.error('[substance] updateDashboard failed', err);
    }
    try {
        if (typeof refreshAppAfterDataChange === 'function') refreshAppAfterDataChange();
    } catch (err) {
        console.error('[substance] refreshAppAfterDataChange failed', err);
    }
}

function setupSubstanceForm() {
    const form = document.getElementById('substance-form');
    if (!form) {
        console.warn('[substance] #substance-form not found');
        return;
    }
    if (form.dataset.submitBound !== 'true') {
        form.addEventListener('submit', (ev) => {
            ev.preventDefault();
            console.log('[substance] form submit');
            handleSubstanceSubmit();
        });
        form.dataset.submitBound = 'true';
    }
}

function updateLastSaved() {
    updateLastSavedDisplay();
}

function renderSubstances() {
    renderSubstancesList();
}

function populateSubstanceDropdowns() {
    populateAllSubstanceDropdowns();
}

function archiveSubstance(id) {
    const sub = getSubstance(id);
    if (!sub) return;
    if (confirm(`Archive "${sub.name}"? It will be hidden from logging but data is kept.`)) {
        sub.active = false;
        if (sub.isMain) sub.isMain = false;
        normalizeMainSubstances(appData);
        saveData(appData);
        if (currentSubstanceId === id) currentSubstanceId = getMainSubstanceId() || getActiveSubstances()[0]?.id || DASHBOARD_ALL;
        populateAllSubstanceDropdowns();
        renderSubstancesList();
        updateDashboard();
    }
}

function restoreSubstance(id) {
    const sub = getSubstance(id);
    if (sub) {
        sub.active = true;
        if (!getMainSubstance()) sub.isMain = true;
        normalizeMainSubstances(appData);
        saveData(appData);
        populateAllSubstanceDropdowns();
        renderSubstancesList();
        updateDashboardMainDisplay();
    }
}

function deleteSubstance(id) {
    const sub = getSubstance(id);
    if (!sub) return;
    const logCount = appData.logs.filter(l => l.substanceId === id).length;
    const msg = logCount
        ? `Delete "${sub.name}"? This removes the substance but keeps ${logCount} log(s) in history.`
        : `Delete "${sub.name}"?`;
    if (!confirm(msg)) return;

    appData.substances = appData.substances.filter(s => s.id !== id);
    delete appData.settings.substanceSettings[id];
    delete appData.taperPlans[id];
    if (Array.isArray(appData.taperPlansV2)) {
        appData.taperPlansV2 = appData.taperPlansV2.filter(p => p.substanceId !== id);
    }
    if (selectedTaperPlanId && getTaperPlanById(selectedTaperPlanId)?.substanceId === id) {
        selectedTaperPlanId = null;
    }
    delete appData.recoveryStreaks[id];
    normalizeMainSubstances(appData);
    if (currentSubstanceId === id) currentSubstanceId = getMainSubstanceId() || getActiveSubstances()[0]?.id || DASHBOARD_ALL;
    saveData(appData);
    populateAllSubstanceDropdowns();
    renderSubstancesList();
    updateDashboardMainDisplay();
    updateDashboard();
}

// ——— Tabs & events ———
const REMOVED_TAB_ALIASES = {
    'history-tab': 'use-log-tab',
    history: 'use-log-tab',
    'goals-tab': 'goals-plans-tab',
    goals: 'goals-plans-tab',
    'taper-tab': 'goals-plans-tab',
    taper: 'goals-plans-tab',
    plan: 'goals-plans-tab',
    'plan-tab': 'goals-plans-tab',
    'stats-tab': 'insights-calendar-tab',
    stats: 'insights-calendar-tab',
    insights: 'insights-calendar-tab',
    'insights-tab': 'insights-calendar-tab',
    'calendar-tab': 'insights-calendar-tab',
    calendar: 'insights-calendar-tab'
};

const PRIMARY_TAB_IDS = new Set([
    'dashboard-tab',
    'use-log-tab',
    'buy-tracker-tab',
    'goals-plans-tab',
    'insights-calendar-tab',
    'settings-tab'
]);

function resolveTabNavigation(tabId) {
    if (!tabId) return { tabId: 'dashboard-tab', view: null };
    const raw = String(tabId);
    const legacy = (typeof LEGACY_TAB_TO_COMBINED !== 'undefined' && (LEGACY_TAB_TO_COMBINED[raw] || LEGACY_TAB_TO_COMBINED[raw.replace(/-tab$/, '')])) || null;
    if (legacy) return { tabId: legacy.tab, view: legacy.view || null };
    const alias = REMOVED_TAB_ALIASES[raw] || REMOVED_TAB_ALIASES[raw.replace(/-tab$/, '')];
    const resolved = alias || raw;
    if (PRIMARY_TAB_IDS.has(resolved)) return { tabId: resolved, view: null };
    if (typeof document !== 'undefined' && document.getElementById(resolved)?.classList?.contains('tab')) {
        return { tabId: resolved, view: null };
    }
    if (resolved === 'goals-tab' || resolved === 'taper-tab') {
        return { tabId: 'goals-plans-tab', view: 'active' };
    }
    if (resolved === 'stats-tab' || resolved === 'calendar-tab') {
        return { tabId: 'insights-calendar-tab', view: resolved === 'calendar-tab' ? 'calendar' : 'overview' };
    }
    if (typeof document !== 'undefined' && document.getElementById(resolved)) {
        return { tabId: resolved, view: null };
    }
    return { tabId: 'dashboard-tab', view: null };
}

function normalizeTabId(tabId) {
    return resolveTabNavigation(tabId).tabId;
}

let cachedNavButtons = null;

function getNavButtons() {
    if (!cachedNavButtons?.length) {
        cachedNavButtons = [...document.querySelectorAll('.bottom-nav .nav-btn')];
    }
    return cachedNavButtons;
}

function setActiveNavTab(tabId) {
    getNavButtons().forEach(btn => {
        btn.classList.toggle('active', btn.dataset.tab === tabId);
    });
}

function switchTab(tabId) {
    const nav = resolveTabNavigation(tabId);
    tabId = nav.tabId;
    if (nav.view && tabId === 'goals-plans-tab' && typeof ensureCombinedNavPrefs === 'function') {
        ensureCombinedNavPrefs().goalsPlansView = nav.view;
    }
    if (nav.view && tabId === 'insights-calendar-tab' && typeof ensureCombinedNavPrefs === 'function') {
        ensureCombinedNavPrefs().insightsCalendarView = nav.view;
    }

    document.querySelectorAll('.tab').forEach(tab => tab.classList.remove('active'));
    setActiveNavTab(tabId);
    document.getElementById(tabId)?.classList.add('active');
    if (typeof persistActiveTab === 'function') persistActiveTab(tabId);

    if (tabId === 'dashboard-tab') {
        ensureDashboardSubstanceDropdownReady();
        updateDashboard();
        if (typeof syncLocationToCombinedRoute === 'function') syncLocationToCombinedRoute(tabId);
    } else if (tabId === 'insights-calendar-tab') {
        if (typeof renderInsightsCalendarCombinedView === 'function') renderInsightsCalendarCombinedView();
        else {
            applyMainSubstanceToViewSelectors();
            updateStats();
        }
    } else if (tabId === 'stats-tab') {
        // Legacy alias path — prefer combined tab
        switchTab('insights-calendar-tab');
        return;
    } else if (tabId === 'buy-tracker-tab') {
        syncBuyFormFromSelectedSubstance();
        renderBuyTrackerTab();
        if (typeof syncLocationToCombinedRoute === 'function') syncLocationToCombinedRoute(tabId);
    } else if (tabId === 'use-log-tab') {
        syncUseLogFormFromSelectedSubstance();
        renderUseLogTab();
        if (typeof syncLocationToCombinedRoute === 'function') syncLocationToCombinedRoute(tabId);
    } else if (tabId === 'calendar-tab') {
        switchTab('insights-calendar-tab');
        return;
    } else if (tabId === 'contacts-tab') {
        // Legacy Friends tab removed — open Settings → Manage Contacts.
        if (typeof openManageContactsSettings === 'function') openManageContactsSettings();
        else switchTab('settings-tab');
        return;
    } else if (tabId === 'goals-plans-tab') {
        if (typeof renderGoalsPlansCombinedView === 'function') renderGoalsPlansCombinedView();
        else if (typeof renderGoalsView === 'function') renderGoalsView();
    } else if (tabId === 'goals-tab') {
        switchTab('goals-plans-tab');
        return;
    } else if (tabId === 'taper-tab') {
        switchTab('goals-plans-tab');
        return;
    } else if (tabId === 'settings-tab') {
        applyMainSubstanceToViewSelectors();
        renderSubstancesList();
        syncRecoveryScoreSettingsToggle();
        syncUseCustomNamesInCsvToggle();
        if (typeof syncInCellProgressBarsToggle === 'function') syncInCellProgressBarsToggle();
        if (typeof renderConditionalColorRulesSettings === 'function') renderConditionalColorRulesSettings();
        if (typeof ensureContactsMigrated === 'function') ensureContactsMigrated(appData);
        if (typeof renderContactsView === 'function') renderContactsView();
        if (typeof syncLocationToCombinedRoute === 'function') syncLocationToCombinedRoute(tabId);
        if (typeof syncExperienceModeSettingsUI === 'function') syncExperienceModeSettingsUI(appData);
    }
    applyCollapsedSections();
    if (typeof onExperienceModeTabChange === 'function') {
        try { onExperienceModeTabChange(tabId); } catch (_) { /* ignore */ }
    }
}

// ——— Local date/time (app dates are YYYY-MM-DD in local timezone) ———
function getLocalDateString(date) {
    if (arguments.length === 0 || date == null) {
        if (testReferenceDateStr) {
            const ref = parseLocalDate(testReferenceDateStr);
            if (ref) return formatYYYYMMDD(ref);
        }
        date = new Date();
    }
    return formatYYYYMMDD(date);
}

function formatYYYYMMDD(date) {
    if (typeof date === 'string') {
        const trimmed = date.trim();
        if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) return trimmed;
    }
    const d = date instanceof Date ? date : new Date(date);
    if (Number.isNaN(d.getTime())) return '';
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
}

function addDaysYYYYMMDD(dateStr, days) {
    const d = parseLocalDate(dateStr);
    if (!d) return dateStr;
    d.setDate(d.getDate() + days);
    return formatYYYYMMDD(d);
}

function getLocalTimeString(date = new Date()) {
    const d = date instanceof Date ? date : new Date(date);
    if (Number.isNaN(d.getTime())) return '00:00';
    return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
}

function parseLocalDate(dateString) {
    if (!dateString || typeof dateString !== 'string') return null;
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateString.trim());
    if (!match) return null;
    const y = Number(match[1]);
    const m = Number(match[2]);
    const day = Number(match[3]);
    if (!y || m < 1 || m > 12 || day < 1 || day > 31) return null;
    return new Date(y, m - 1, day, 12, 0, 0, 0);
}

function parseLocalDateTime(dateStr, timeStr = '12:00') {
    const base = parseLocalDate(dateStr);
    if (!base) return null;
    const totalMinutes = timeToMinutes(timeStr);
    const d = new Date(base);
    d.setHours(Math.floor(totalMinutes / 60), totalMinutes % 60, 0, 0);
    return d;
}

function getLocalDayBoundaryMs(dateStr) {
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(dateStr || '').trim());
    if (!match) return null;
    const y = Number(match[1]);
    const m = Number(match[2]) - 1;
    const day = Number(match[3]);
    return {
        startMs: new Date(y, m, day, 0, 0, 0, 0).getTime(),
        endMs: new Date(y, m, day, 23, 59, 59, 999).getTime()
    };
}

function formatStatsPuffs(value, maxDecimals = 1) {
    if (value == null || Number.isNaN(value)) return '0';
    const factor = Math.pow(10, maxDecimals);
    const rounded = Math.round(value * factor) / factor;
    if (Number.isInteger(rounded)) return String(rounded);
    const fixed = rounded.toFixed(maxDecimals);
    return fixed.replace(/(\.\d*?)0+$/, '$1').replace(/\.$/, '');
}

function formatStatsPuffsPerDay(value) {
    if (value == null || Number.isNaN(value)) return '—';
    const rounded = Math.round(value * 10) / 10;
    const formatted = Number.isInteger(rounded)
        ? rounded.toLocaleString('en-US')
        : rounded.toLocaleString('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
    return `${formatted} puffs/day`;
}

function formatCostPerVape(value, cur = getCurrencySymbol()) {
    if (value == null || Number.isNaN(value)) return '—';
    return `${cur}${value.toFixed(2)}/vape`;
}

function getStatsDisplayUnit(substanceId, fallbackUnit = 'units') {
    return isVapeNicotineSubstanceId(substanceId) ? 'puffs' : fallbackUnit;
}

function getTableColumnLabelForSubstance(tableKey, colId, substanceId = currentSubstanceId) {
    if (tableKey === 'useHistory') {
        return getUseHistoryColumnLabel(colId, substanceId === DASHBOARD_ALL ? null : substanceId);
    }
    const labels = TABLE_COLUMN_LABELS[tableKey] || {};
    if (!isVapeNicotineSubstanceId(substanceId)) return labels[colId] || colId;
    const vapeBuyLabels = {
        purchased: 'Puffs purchased',
        costPerUnit: 'Cost/vape',
        gPerDay: 'Puffs/day',
        supplyDuration: 'Days per vape'
    };
    const vapeStatsLabels = {
        gPerSession: 'Puffs/sess',
        gPerHour: 'Puffs/hr',
        gPerUseDay: 'Puffs/use day',
        gPerCalDay: 'Puffs/cal day'
    };
    if (tableKey === 'buyWeekly' || tableKey === 'buyMonthly' || tableKey === 'buyPurchaseDetails') {
        return vapeBuyLabels[colId] || labels[colId] || colId;
    }
    if (tableKey === 'statsWeekly' || tableKey === 'statsMonthly') {
        return vapeStatsLabels[colId] || labels[colId] || colId;
    }
    return labels[colId] || colId;
}

function getDefaultColumnLabel(tableKey, colId, {
    substanceId = currentSubstanceId,
    plan = null
} = {}) {
    if (tableKey === 'taperByWeek') {
        return getTaperByWeekColumnLabel(colId, plan, substanceId);
    }
    if (tableKey === 'useHistory') {
        return getUseHistoryColumnLabel(colId, substanceId === DASHBOARD_ALL ? null : substanceId);
    }
    if (tableKey === 'purchaseHistory') {
        return getPurchaseHistoryColumnLabel(colId);
    }
    return getTableColumnLabelForSubstance(tableKey, colId, substanceId);
}

/** Display label with optional custom name. Internal colId is never changed. */
function resolveColumnDisplayLabel(tableKey, colId, options = {}) {
    const {
        substanceId = currentSubstanceId,
        plan = null,
        variantKey = null,
        forCsv = false,
        config = null
    } = options;
    const defaultLabel = getDefaultColumnLabel(tableKey, colId, { substanceId, plan });
    if (forCsv && !getUseCustomNamesInCsvExport()) return defaultLabel;
    const resolvedVariant = variantKey != null
        ? variantKey
        : (tableKey === 'useHistory'
            ? getUseHistoryColumnVariantKey(substanceId)
            : (tableKey === 'taperByWeek'
                ? getTaperByWeekColumnVariantKey(substanceId, plan)
                : null));
    const cfg = config || getTableColumnConfig(tableKey, resolvedVariant);
    const custom = sanitizeCustomColumnName(cfg?.customNames?.[colId]);
    return custom || defaultLabel;
}

function getLocalDateFromIso(isoString) {
    if (!isoString) return '';
    const d = new Date(isoString);
    if (Number.isNaN(d.getTime())) {
        const match = /^(\d{4}-\d{2}-\d{2})/.exec(String(isoString).trim());
        return match ? match[1] : '';
    }
    return getLocalDateString(d);
}

function formatLocalDate(dateString) {
    const d = parseLocalDate(dateString);
    if (!d) return dateString || '—';
    return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}

// ——— Use Log ———
function parseUseDateTime(dateStr, timeStr) {
    return parseLocalDateTime(dateStr, timeStr);
}

function formatDurationHours(hours) {
    if (hours == null || isNaN(hours)) return '—';
    if (hours < 1 / 60) return '<1m';
    const h = Math.floor(hours);
    const m = Math.round((hours - h) * 60);
    if (h > 0) return m > 0 ? `${h}h ${m}m` : `${h}h`;
    return `${m}m`;
}

function formatUseSessionDurationPreview(hours) {
    if (hours == null || isNaN(hours) || hours < 0) return '—';
    const totalMinutes = Math.round(hours * 60);
    const days = Math.floor(totalMinutes / (24 * 60));
    const remainder = totalMinutes - days * 24 * 60;
    const h = Math.floor(remainder / 60);
    const m = remainder % 60;
    if (days > 0) {
        const parts = [`${days}d`];
        if (h > 0) parts.push(`${h}h`);
        if (m > 0) parts.push(`${m}m`);
        return parts.join(' ');
    }
    return formatDurationHours(hours);
}

function formatDurationHMS(hours) {
    if (hours == null || isNaN(hours) || hours < 0) return '—';
    const totalSeconds = Math.round(hours * 3600);
    const h = Math.floor(totalSeconds / 3600);
    const m = Math.floor((totalSeconds % 3600) / 60);
    const s = totalSeconds % 60;
    return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

function formatTaperMonthlyAmount(value, unit) {
    if (value == null || Number.isNaN(value)) return '—';
    return formatTaperAmount(value, unit);
}

function formatTaperAmount(value, unit) {
    if (value == null || Number.isNaN(value)) return '—';
    return `${formatAmount(value)} ${unit || ''}`.trim();
}

function formatTaperActualAmount(value, unit) {
    if (value == null || Number.isNaN(value)) return '—';
    return `${formatAmount(value, 1)} ${unit || ''}`.trim();
}

function formatTaperPercent(actual, goal) {
    if (goal == null || goal <= 0 || actual == null || Number.isNaN(actual)) return '—';
    return `${Math.round((actual / goal) * 100)}%`;
}

function formatTaperMonthlyRate(value, unit, suffix) {
    if (value == null || Number.isNaN(value)) return '—';
    return `${Number(value.toFixed(2))} ${unit}${suffix}`;
}

function formatBreakText(minutes) {
    if (minutes == null || isNaN(minutes) || minutes < 0) return '—';
    const total = Math.floor(minutes);
    const days = Math.floor(total / 1440);
    const hours = Math.floor((total % 1440) / 60);
    const mins = total % 60;
    if (days > 0) {
        const parts = [`${days}d`];
        if (hours > 0) parts.push(`${hours}h`);
        if (mins > 0) parts.push(`${mins}m`);
        return parts.join(' ');
    }
    if (hours > 0) {
        if (mins > 0) return `${hours}h ${mins}m`;
        return `${hours}h`;
    }
    return `${mins}m`;
}

const USE_BREAK_FIELDS = Object.freeze(['breakMinutes', 'breakHours', 'breakText']);
const BUY_BREAK_FIELDS = Object.freeze(['buyBreakMinutes', 'buyBreakHours', 'buyBreakText']);

function clearUseBreakFields(log) {
    USE_BREAK_FIELDS.forEach(field => delete log[field]);
}

function clearBuyBreakFields(purchase) {
    BUY_BREAK_FIELDS.forEach(field => delete purchase[field]);
}

// Last ten gaps of a chronologically sorted record list, for break trend sparklines.
function buildBreakTrend(records, hoursField, textField) {
    return records
        .filter(r => r[hoursField] != null)
        .slice(-10)
        .map(r => ({
            date: r.date,
            hours: r[hoursField],
            text: r[textField],
            label: formatDate(r.date)
        }));
}

function getBreakColorClass(hours) {
    if (hours == null || isNaN(hours)) return '';
    if (hours < 1) return 'break-red';
    if (hours < 12) return 'break-orange';
    if (hours < 48) return 'break-yellow';
    return 'break-green';
}

function medianBreakHours(values) {
    return medianOfNumbers(values);
}

function recalculateBreaksForData(substanceId, data) {
    const logs = getUseEntries(data)
        .filter(l => logMatchesSubstance(l, substanceId, data) && isPersonalUseLog(l))
        .sort((a, b) => getLogDatetimeMs(a) - getLogDatetimeMs(b));

    logs.forEach((log, index) => {
        if (index === 0) {
            clearUseBreakFields(log);
            return;
        }

        const previous = logs[index - 1];

        if (isWeedTrackingMode(substanceId, data)) {
            const prevDay = parseLocalDate(previous.date);
            const curDay = parseLocalDate(log.date);
            if (!prevDay || !curDay) {
                clearUseBreakFields(log);
                return;
            }
            const dayGap = Math.round((curDay.getTime() - prevDay.getTime()) / 86400000);
            if (dayGap <= 0) {
                clearUseBreakFields(log);
                return;
            }
            const breakMinutes = dayGap * 24 * 60;
            log.breakMinutes = breakMinutes;
            log.breakHours = breakMinutes / 60;
            log.breakText = formatBreakFromHours(log.breakHours);
            return;
        }

        const previousEnd = getUseEndDatetime(previous);
        const currentStartMs = getLogDatetimeMs(log);

        if (!previousEnd || !currentStartMs) {
            clearUseBreakFields(log);
            return;
        }

        const breakMs = currentStartMs - previousEnd.getTime();
        if (breakMs < 0) {
            clearUseBreakFields(log);
            return;
        }

        const breakMinutes = Math.floor(breakMs / 60000);
        log.breakMinutes = breakMinutes;
        log.breakHours = breakMinutes / 60;
        log.breakText = formatBreakText(breakMinutes);
    });
}

function recalculateBreaks(substanceId) {
    recalculateBreaksForData(substanceId, appData);
}

function recalculateAllBreaks() {
    const substanceIds = new Set((appData.logs || []).map(l => getUseSubstanceId(l)).filter(Boolean));
    substanceIds.forEach(id => recalculateBreaks(id));
}

function recalculateAllBreaksForData(data) {
    const substanceIds = new Set(getUseEntries(data).map(l => getUseSubstanceId(l)).filter(Boolean));
    substanceIds.forEach(id => recalculateBreaksForData(id, data));
}

function getBreakMetrics(substanceId) {
    const logs = getUseLogsForSubstance(substanceId, { sortAsc: true, personalUseOnly: true });
    const breakHoursList = logs
        .filter(l => l.breakHours != null && !isNaN(l.breakHours))
        .map(l => l.breakHours);

    const currentLog = logs.length ? logs[logs.length - 1] : null;
    const currentBreak = currentLog?.breakHours != null
        ? { hours: currentLog.breakHours, text: currentLog.breakText || formatBreakText(currentLog.breakMinutes) }
        : null;

    const lastEnd = logs.length ? getUseEndDatetime(logs[logs.length - 1]) : null;
    const streakWithoutUse = lastEnd ? describeElapsedMs(Date.now() - lastEnd.getTime()) : null;

    const thirtyDaysAgo = Date.now() - 30 * 24 * 60 * 60 * 1000;
    const recentBreakHours = logs
        .filter(l => l.breakHours != null && getLogDatetimeMs(l) >= thirtyDaysAgo)
        .map(l => l.breakHours);

    return {
        count: breakHoursList.length,
        current: currentBreak,
        longest: breakHoursList.length ? Math.max(...breakHoursList) : null,
        average: meanOrNull(breakHoursList),
        median: medianBreakHours(breakHoursList),
        shortest: breakHoursList.length ? Math.min(...breakHoursList) : null,
        avg30Days: meanOrNull(recentBreakHours),
        streakWithoutUse,
        trend: buildBreakTrend(logs, 'breakHours', 'breakText')
    };
}

function getBuyBreakColorClass(hours) {
    if (hours == null || isNaN(hours)) return '';
    if (hours < 24) return 'buy-break-red';
    if (hours < 72) return 'buy-break-orange';
    if (hours < 168) return 'buy-break-yellow';
    return 'buy-break-green';
}

function getPurchasesForSubstance(substanceId, data = appData, { sortAsc = true } = {}) {
    let list = (data.purchases || []).filter(p => getPurchaseSubstanceId(p) === substanceId);
    list = [...list].sort((a, b) => {
        const da = getPurchaseDatetimeMs(a);
        const db = getPurchaseDatetimeMs(b);
        return sortAsc ? da - db : db - da;
    });
    return list;
}

function recalculateBuyBreaksForData(substanceId, data) {
    const purchases = getPurchasesForSubstance(substanceId, data, { sortAsc: true });

    purchases.forEach((purchase, index) => {
        const previousMs = index > 0 ? getPurchaseDatetimeMs(purchases[index - 1]) : null;
        const currentMs = getPurchaseDatetimeMs(purchase);
        const buyBreakMs = previousMs && currentMs ? currentMs - previousMs : null;

        if (buyBreakMs == null || buyBreakMs < 0) {
            clearBuyBreakFields(purchase);
            return;
        }

        const buyBreakMinutes = Math.floor(buyBreakMs / 60000);
        purchase.buyBreakMinutes = buyBreakMinutes;
        purchase.buyBreakHours = buyBreakMinutes / 60;
        purchase.buyBreakText = formatBreakText(buyBreakMinutes);
    });
}

function recalculateBuyBreaks(substanceId) {
    recalculateBuyBreaksForData(substanceId, appData);
}

function recalculateAllBuyBreaks() {
    const substanceIds = new Set((appData.purchases || []).map(p => getPurchaseSubstanceId(p)).filter(Boolean));
    substanceIds.forEach(id => recalculateBuyBreaks(id));
}

function recalculateAllBuyBreaksForData(data) {
    const substanceIds = new Set((data.purchases || []).map(p => getPurchaseSubstanceId(p)).filter(Boolean));
    substanceIds.forEach(id => recalculateBuyBreaksForData(id, data));
}

function formatBuyBreakFromHours(hours) {
    if (hours == null || isNaN(hours)) return '—';
    return formatBreakText(Math.floor(hours * 60));
}

function getBuyBreakMetrics(substanceId, bounds = null, data = appData) {
    const purchases = bounds
        ? filterPurchasesByStatsBounds(getPurchasesForInsightMetrics(substanceId, data), bounds)
        : getPurchasesForSubstance(substanceId, data, { sortAsc: true });
    const metrics = getBuyBreakMetricsFromPurchases(substanceId, purchases, data);
    if (bounds) return metrics;

    const thirtyDaysAgo = Date.now() - 30 * 24 * 60 * 60 * 1000;
    const recentBreakHours = purchases
        .filter(p => p.buyBreakHours != null && getPurchaseDatetimeMs(p) >= thirtyDaysAgo)
        .map(p => p.buyBreakHours);
    return { ...metrics, avg30Days: meanOrNull(recentBreakHours) };
}

function renderBuyBreakSincePreviousCell(purchase) {
    const hours = purchase.buyBreakHours;
    const text = purchase.buyBreakText || (hours != null ? formatBuyBreakFromHours(hours) : '—');
    if (text === '—' || hours == null) return '—';
    return `<span class="buy-break-cell ${getBuyBreakColorClass(hours)}">${text}</span>`;
}

function formatHoursAgo(ms) {
    if (ms == null || ms < 0) return '—';
    const hours = ms / 3600000;
    if (hours < 1) return `${Math.round(ms / 60000)}m ago`;
    if (hours < 24) return `${hours.toFixed(1)}h ago`;
    const days = Math.floor(hours / 24);
    return `${days}d ${Math.round(hours % 24)}h ago`;
}

function findUseEntry(id) {
    return getUseEntries().find(l => l.id === id || String(l.id) === String(id));
}

function logIdEquals(a, b) {
    if (a == null || b == null) return false;
    return a === b || String(a) === String(b);
}

function purchaseIdEquals(a, b) {
    if (a == null || b == null) return false;
    return a === b || String(a) === String(b);
}

function normalizePurchaseId(id) {
    return id == null ? '' : String(id);
}

function purchaseIdLiteral(id) {
    return JSON.stringify(normalizePurchaseId(id));
}

function ensureSubstanceInBuyDropdown(substanceId, purchase) {
    const select = document.getElementById('buy-substance');
    if (!select || !substanceId) return;
    if ([...select.options].some(o => o.value === substanceId)) {
        select.value = substanceId;
        return;
    }
    const sub = getSubstance(substanceId);
    if (sub) {
        select.appendChild(buildSubstanceOption(sub));
    } else {
        const opt = document.createElement('option');
        opt.value = substanceId;
        opt.textContent = purchase?.substanceName || substanceId;
        select.appendChild(opt);
    }
    select.value = substanceId;
}

function setupPurchaseHistoryActions() {
    if (document.documentElement.dataset.purchaseHistoryActionsBound === '1') return;
    document.documentElement.dataset.purchaseHistoryActionsBound = '1';
    document.addEventListener('click', (e) => {
        const sortBtn = e.target.closest('[data-sort-col="flavor"]');
        if (sortBtn) {
            e.preventDefault();
            togglePurchaseHistoryFlavorSort();
            return;
        }
        const editBtn = e.target.closest('[data-edit-purchase]');
        if (editBtn) {
            e.preventDefault();
            editPurchase(editBtn.getAttribute('data-edit-purchase'));
            return;
        }
        const duplicateBtn = e.target.closest('[data-duplicate-purchase]');
        if (duplicateBtn) {
            e.preventDefault();
            duplicatePurchase(duplicateBtn.getAttribute('data-duplicate-purchase'));
            return;
        }
        const duplicateNowBtn = e.target.closest('[data-duplicate-purchase-now]');
        if (duplicateNowBtn) {
            e.preventDefault();
            createAutoBackup('before-duplicate-purchase');
            duplicatePurchaseNow(duplicateNowBtn.getAttribute('data-duplicate-purchase-now'));
            return;
        }
        const deleteBtn = e.target.closest('[data-delete-purchase]');
        if (deleteBtn) {
            e.preventDefault();
            deletePurchase(deleteBtn.getAttribute('data-delete-purchase'));
            return;
        }
        const toggleBtn = e.target.closest('[data-toggle-purchase-logs]');
        if (toggleBtn) {
            e.preventDefault();
            togglePurchaseLinkedLogs(toggleBtn.getAttribute('data-toggle-purchase-logs'));
            return;
        }
        const markEmptyBtn = e.target.closest('[data-mark-vape-empty]');
        if (markEmptyBtn) {
            e.preventDefault();
            markVapePurchaseEmpty(markEmptyBtn.getAttribute('data-mark-vape-empty'));
            return;
        }
        const markFinishedBtn = e.target.closest('[data-mark-vape-finished]');
        if (markFinishedBtn) {
            e.preventDefault();
            markVapePurchaseFinishedNow(markFinishedBtn.getAttribute('data-mark-vape-finished'));
            return;
        }
        const activeBtn = e.target.closest('[data-mark-purchase-active]');
        if (activeBtn) {
            e.preventDefault();
            markPurchaseInventoryStatus(activeBtn.getAttribute('data-mark-purchase-active'), 'active');
            return;
        }
        const depletedBtn = e.target.closest('[data-mark-purchase-depleted]');
        if (depletedBtn) {
            e.preventDefault();
            markPurchaseInventoryStatus(depletedBtn.getAttribute('data-mark-purchase-depleted'), 'depleted');
            return;
        }
        const hideBtn = e.target.closest('[data-hide-purchase]');
        if (hideBtn) {
            e.preventDefault();
            setPurchaseHidden(hideBtn.getAttribute('data-hide-purchase'), true);
            return;
        }
        const unhideBtn = e.target.closest('[data-unhide-purchase]');
        if (unhideBtn) {
            e.preventDefault();
            setPurchaseHidden(unhideBtn.getAttribute('data-unhide-purchase'), false);
            return;
        }
        const recalcBtn = e.target.closest('[data-recalculate-purchase]');
        if (recalcBtn) {
            e.preventDefault();
            const result = recalculatePurchaseRemaining(recalcBtn.getAttribute('data-recalculate-purchase'));
            if (result) {
                saveData(appData);
                refreshBuyTrackerRelatedViews();
                alert(`Remaining updated: ${formatAmount(result.oldRemaining)} → ${formatAmount(result.newRemaining)}`);
            }
        }
    });
    document.addEventListener('change', (e) => {
        const cb = e.target.closest('[data-inventory-select]');
        if (!cb) return;
        const id = cb.getAttribute('data-inventory-select');
        if (cb.checked) inventorySelectedIds.add(id);
        else inventorySelectedIds.delete(id);
        updateInventoryBulkBarUI();
    });
}

function isSameTaperWeek(logDate, dateStr) {
    if (!logDate || !dateStr) return false;
    return getWeekStartDateStr(logDate) === getWeekStartDateStr(dateStr);
}

function getTaperWeekBounds(plan, dateStr) {
    if (!plan || !dateStr) return null;
    const week = getWeekRowForDate(plan, dateStr);
    if (week) return { weekStart: week.weekStart, weekEnd: week.weekEnd };
    if (isManualWeeklyPlan(plan) && plan.startDate) {
        const manualWeek = getCurrentManualWeekRow(plan, dateStr);
        if (manualWeek) return { weekStart: manualWeek.weekStart, weekEnd: manualWeek.weekEnd };
    }
    return null;
}

function getTaperPlanWeekNumber(plan, dateStr) {
    if (!plan || !dateStr) return 1;
    const row = getWeekRowForDate(plan, dateStr);
    if (row) {
        if (row.week != null && row.week !== '' && Number.isFinite(Number(row.week))) {
            return Number(row.week);
        }
        const idx = (plan.weeklyTargets || []).findIndex(w =>
            w.weekStart === row.weekStart && w.weekEnd === row.weekEnd
        );
        return idx >= 0 ? idx + 1 : 1;
    }
    const weeks = plan.weeklyTargets || [];
    if (!weeks.length) return 1;
    if (dateStr < weeks[0].weekStart) {
        return weeks[0].week != null && Number.isFinite(Number(weeks[0].week))
            ? Number(weeks[0].week)
            : 1;
    }
    // After the final week / plan end: show the final week number (never negative remaining).
    const last = weeks[weeks.length - 1];
    if (last.week != null && last.week !== '' && Number.isFinite(Number(last.week))) {
        return Number(last.week);
    }
    return weeks.length;
}

function isTaperPlanDateComplete(plan, dateStr = getLocalDateString()) {
    if (!plan || !dateStr) return false;
    if (plan.endDate && dateStr > plan.endDate) return true;
    const weeks = plan.weeklyTargets || [];
    if (!weeks.length) return false;
    const lastEnd = weeks[weeks.length - 1].weekEnd;
    return !!(lastEnd && dateStr > lastEnd && !getWeekRowForDate(plan, dateStr));
}

function getUsedAmountForTaperWeek(substanceId, dateStr, excludeLogId = null, data = appData) {
    return getTaperWeekUsage(substanceId, dateStr, excludeLogId, data);
}

function shortWeeklyTaperStatus(status) {
    return getRecoveryTaperStatusLabel(status);
}

function getUseEntries(data = appData) {
    return Array.isArray(data?.logs) ? data.logs : [];
}

function normalizeSubstanceRef(ref, data = appData) {
    if (ref == null || ref === '') return '';
    const substances = data?.substances || [];
    const refStr = String(ref);
    const byId = substances.find(s => String(s.id) === refStr);
    if (byId) {
        if (byId.id === VAPE_NICOTINE_ID || byId.id === LEGACY_CIGARETTES_ID) return NICOTINE_ID;
        return byId.id;
    }
    const byName = substances.find(s =>
        s.name === ref || String(s.name).toLowerCase() === refStr.toLowerCase()
    );
    if (byName) {
        if (byName.id === VAPE_NICOTINE_ID || byName.id === LEGACY_CIGARETTES_ID) return NICOTINE_ID;
        return byName.id;
    }
    if (refStr === VAPE_NICOTINE_ID || refStr === LEGACY_CIGARETTES_ID) return NICOTINE_ID;
    return refStr;
}

function logMatchesSubstance(log, substanceId, data = appData) {
    if (!substanceId) return true;
    return normalizeSubstanceRef(getUseSubstanceId(log), data)
        === normalizeSubstanceRef(substanceId, data);
}

function getUseSubstanceId(entry) {
    return entry.substanceId || entry.substance || '';
}

function getUseCount(entry) {
    const count = entry.count ?? entry.lines;
    return count != null && count !== '' ? count : '';
}

function getUseLogType(entry) {
    if (entry.type === 'session' || entry.type === 'quick') return entry.type;
    return entry.endTime ? 'session' : 'quick';
}

function getLogTransactionType(log) {
    const t = log?.transactionType;
    if (t === 'gift_given' || t === 'gift_received' || t === 'inventory_adjustment' || t === 'shared_use') return t;
    if (t === 'correction') return 'inventory_adjustment';
    if (t === 'session') return 'use';
    return 'use';
}

function isPersonalUseLog(log) {
    return getLogTransactionType(log) === 'use';
}

function isSharedUseLog(log) {
    return getLogTransactionType(log) === 'shared_use';
}

function getLogTotalAmount(log) {
    if (isSharedUseLog(log)) {
        const total = parseFloat(log.totalAmount);
        if (Number.isFinite(total) && total >= 0) return total;
    }
    return parseFloat(log.amount) || 0;
}

function getLogPersonalAmount(log) {
    if (isSharedUseLog(log)) {
        const personal = parseFloat(log.personalAmount);
        if (Number.isFinite(personal) && personal >= 0) return personal;
    }
    if (isPersonalUseLog(log)) return parseFloat(log.amount) || 0;
    return 0;
}

function getLogSharedAmount(log) {
    if (!isSharedUseLog(log)) return 0;
    const shared = parseFloat(log.sharedAmount);
    if (Number.isFinite(shared) && shared >= 0) return shared;
    return Math.max(0, getLogTotalAmount(log) - getLogPersonalAmount(log));
}

function getLogInventoryDeductionAmount(log) {
    return getLogTotalAmount(log);
}

function logAffectsInventoryDeduction(log) {
    const tx = getLogTransactionType(log);
    if (tx === 'use' || tx === 'shared_use' || tx === 'gift_given') return true;
    if (tx === 'inventory_adjustment' && inventoryAdjustmentRemoves(log)) return true;
    return false;
}

function logCountsTowardPersonalUseStats(log) {
    return isPersonalUseLog(log);
}

function getLogStatsAmount(log) {
    if (isPersonalUseLog(log)) return parseFloat(log.amount) || 0;
    return 0;
}

function isVapeDateOnlyUseForm() {
    const substanceId = document.getElementById('use-substance')?.value;
    if (!substanceId) return false;
    if (isNicotineTrackingMode(substanceId)) {
        return getUseFormNicotineProductType() === 'vape';
    }
    return isVapeTrackingMode(substanceId);
}

function isVapeDateOnlyUseLog(log, data = appData) {
    if (!isVapeUseLog(log, data)) return false;
    return getUseLogType(log) === 'quick' || log.logMode === 'vape_puffs' || !log.endTime;
}

function isVapeSessionFormActive() {
    return isVapeDateOnlyUseForm();
}

function positionUseInventoryFields(inWeedMode) {
    const group = document.getElementById('use-inventory-fields-group');
    const coreAnchor = document.getElementById('use-inventory-core-anchor');
    const advancedBody = document.querySelector('#use-advanced-section .use-log-advanced-body');
    const countGroup = document.getElementById('use-count-group');
    if (!group || !coreAnchor || !advancedBody) return;
    if (inWeedMode) {
        coreAnchor.appendChild(group);
    } else if (countGroup) {
        advancedBody.insertBefore(group, countGroup);
    } else {
        advancedBody.appendChild(group);
    }
}

function getWeedUseProductType({ allowEmpty = false } = {}) {
    const raw = document.getElementById('use-weed-product-type')?.value;
    return normalizeWeedProductType(raw, { allowEmpty });
}

function setWeedUseProductType(value, { defaultIfEmpty = false } = {}) {
    const sel = document.getElementById('use-weed-product-type');
    if (!sel) return normalizeWeedProductType(value, { allowEmpty: !defaultIfEmpty });
    const normalized = normalizeWeedProductType(value, { allowEmpty: true });
    const next = normalized || (defaultIfEmpty ? 'bud' : '');
    if (next && sel.value !== next) sel.value = next;
    return next || getWeedUseProductType({ allowEmpty: true });
}

/** Default to Bud only for new Weed/THC logs when no product type is selected. */
function ensureWeedUseProductTypeDefault() {
    if (!isWeedDateOnlyUseForm()) return '';
    if (editingUseId != null) {
        const entry = findUseEntry(editingUseId);
        if (entry && weedLogNeedsProductTypeReview(entry)) {
            const current = getWeedUseProductType({ allowEmpty: true });
            updateWeedProductTypeReviewHint(!current);
            return current;
        }
    }
    const current = getWeedUseProductType({ allowEmpty: true });
    if (current) {
        setWeedUseProductType(current);
        updateWeedProductTypeReviewHint(false);
        return current;
    }
    const next = setWeedUseProductType('bud', { defaultIfEmpty: true });
    updateWeedProductTypeReviewHint(false);
    return next;
}

function updateWeedProductTypeReviewHint(show) {
    document.getElementById('use-weed-product-type-review')?.classList.toggle('hidden', !show);
}

function onWeedUseProductTypeChange() {
    const raw = document.getElementById('use-weed-product-type')?.value || '';
    const type = setWeedUseProductType(raw || 'bud');
    updateWeedProductTypeReviewHint(false);
    const select = document.getElementById('use-purchase-select');
    if (select?.value) {
        const purchase = findPurchase(parsePurchaseSelectId(select.value));
        if (purchase && !purchaseMatchesWeedProductType(purchase, type)) {
            select.value = '';
        }
    }
    updateWeedUseFormUI();
    updateUsePurchaseLinkUI();
    if (type === 'edibles') syncWeedEdibleStrengthFromInventory({ force: true });
}

function getWeedCartLogInputMode() {
    return document.getElementById('use-weed-cart-log-mode')?.value === 'estimated'
        ? 'estimated'
        : 'checkpoints';
}

function setWeedCartLogInputMode(mode) {
    const val = mode === 'estimated' ? 'estimated' : 'checkpoints';
    setInputValue('use-weed-cart-log-mode', val);
    document.querySelectorAll('.use-weed-cart-mode-btn').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.cartMode === val);
    });
    document.getElementById('use-weed-cart-checkpoints-group')?.classList.toggle('hidden', val === 'estimated');
    document.getElementById('use-weed-cart-estimated-group')?.classList.toggle('hidden', val !== 'estimated');
    updateWeedCartUsePreview();
}

function updateWeedUseUnitOptions(productType) {
    const unitSelect = document.getElementById('use-unit');
    if (!unitSelect) return;
    const type = normalizeWeedProductType(productType, { allowEmpty: true }) || 'bud';
    const current = unitSelect.value;
    unitSelect.innerHTML = '';
    if (type === 'bud') {
        const budUnits = ['grams', 'bowls', 'joints'];
        if (typeof getWeedCompletePrefs === 'function' && getWeedCompletePrefs().enableBudHitsLogging) budUnits.push('hits');
        budUnits.forEach(unit => {
            const option = document.createElement('option');
            option.value = unit;
            option.textContent = unit;
            unitSelect.appendChild(option);
        });
        unitSelect.value = 'grams';
    } else if (type === 'cart') {
        const option = document.createElement('option');
        option.value = 'percent';
        option.textContent = '%';
        unitSelect.appendChild(option);
        unitSelect.value = 'percent';
    } else if (type === 'edibles') {
        const option = document.createElement('option');
        option.value = 'edible';
        option.textContent = 'edible';
        unitSelect.appendChild(option);
        unitSelect.value = 'edible';
    } else if (type === 'pre-rolls') {
        const option = document.createElement('option');
        option.value = 'pre-roll';
        option.textContent = 'pre-roll';
        unitSelect.appendChild(option);
        unitSelect.value = 'pre-roll';
    } else {
        const option = document.createElement('option');
        option.value = 'units';
        option.textContent = 'count';
        unitSelect.appendChild(option);
        unitSelect.value = 'units';
    }
    if ([...unitSelect.options].some(o => o.value === current)) {
        unitSelect.value = current;
    }
}

function updateWeedBudEstimateVisibility() {
    const group = document.getElementById('use-weed-bud-estimate-group');
    if (!group) return;
    const unit = (document.getElementById('use-unit')?.value || '').toLowerCase();
    const show = ['joints', 'joint', 'bowls', 'bowl', 'hits', 'hit'].includes(unit);
    group.classList.toggle('hidden', !show);
    if (show && typeof getWeedCompletePrefs === 'function') {
        const prefs = getWeedCompletePrefs();
        const input = document.getElementById('use-weed-bud-grams-per-unit');
        if (input && (input.value === '' || input.dataset.fromDefault === '1')) {
            const est = (unit === 'bowls' || unit === 'bowl') ? prefs.gramsPerBowl : prefs.gramsPerJoint;
            input.value = String(est);
            input.dataset.fromDefault = '1';
        }
    }
    if (typeof updateWeedBudUsePreview === 'function') updateWeedBudUsePreview();
}

function updateWeedBudUsePreview() {
    const preview = document.getElementById('use-weed-bud-estimate-preview');
    if (!preview) return;
    if (typeof getWeedUseProductType === 'function' && getWeedUseProductType({ allowEmpty: true }) !== 'bud') {
        preview.textContent = '—';
        return;
    }
    const amount = parseFloat(document.getElementById('use-amount')?.value);
    const unit = document.getElementById('use-unit')?.value;
    const estimate = parseFloat(document.getElementById('use-weed-bud-grams-per-unit')?.value);
    if (typeof computeWeedBudNormalizedGrams !== 'function') {
        preview.textContent = '—';
        return;
    }
    const calc = computeWeedBudNormalizedGrams({ enteredAmount: amount, unit, gramsPerUnit: estimate, data: appData });
    if (calc.error || calc.normalizedGrams == null) {
        preview.textContent = calc.error || 'Normalized grams: —';
        return;
    }
    preview.textContent = `Normalized: ${formatAmount(calc.normalizedGrams)} g (${formatAmount(calc.enteredAmount)} ${calc.enteredUnit} × ${formatAmount(calc.gramsPerUnitEstimate)} g)`;
}

function updateWeedUseAmountLabel(productType) {
    const amountLabel = document.getElementById('use-amount-label');
    if (!amountLabel) return;
    const type = normalizeWeedProductType(productType, { allowEmpty: true }) || 'bud';
    if (type === 'bud') {
        amountLabel.textContent = 'Amount';
    } else if (type === 'cart') {
        amountLabel.textContent = 'Estimated percent used';
    } else if (type === 'edibles') {
        amountLabel.textContent = 'Edible amount used';
    } else if (type === 'pre-rolls') {
        amountLabel.textContent = 'Pre-roll amount (count or fraction)';
    } else {
        amountLabel.textContent = 'Quantity (count)';
    }
}

function getLinkedWeedEdiblesPurchaseForForm() {
    const substanceId = document.getElementById('use-substance')?.value;
    if (!isWeedTrackingMode(substanceId)) return null;
    if (getWeedUseProductType({ allowEmpty: true }) !== 'edibles') return null;
    const purchaseId = resolveLinkedPurchaseId(
        substanceId,
        document.getElementById('use-transaction-type')?.value || 'use',
        { weedProductType: 'edibles' }
    );
    const purchase = purchaseId ? findPurchase(purchaseId) : null;
    return purchase && isWeedEdiblesPurchase(purchase) ? purchase : null;
}

function syncWeedEdibleStrengthFromInventory({ force = false } = {}) {
    const mgInput = document.getElementById('use-weed-edible-mg-per');
    const cbdInput = document.getElementById('use-weed-edible-cbd-mg-per');
    if (!mgInput) return;
    const purchase = getLinkedWeedEdiblesPurchaseForForm();
    const mgPer = purchase ? getWeedEdibleMgPerEdible(purchase) : null;
    const cbdPer = purchase && typeof getWeedCbdMgPerEdible === 'function' ? getWeedCbdMgPerEdible(purchase) : null;
    const hint = document.getElementById('use-weed-edible-strength-hint');
    if (mgPer != null) {
        if (force || mgInput.value === '' || mgInput.dataset.fromInventory === '1') {
            mgInput.value = String(mgPer);
            mgInput.dataset.fromInventory = '1';
            mgInput.readOnly = true;
        }
        hint?.classList.add('hidden');
    } else {
        if (force || mgInput.dataset.fromInventory === '1') {
            mgInput.value = '';
            mgInput.dataset.fromInventory = '';
        }
        mgInput.readOnly = false;
        hint?.classList.toggle('hidden', false);
    }
    if (cbdInput) {
        if (cbdPer != null) {
            if (force || cbdInput.value === '' || cbdInput.dataset.fromInventory === '1') {
                cbdInput.value = String(cbdPer);
                cbdInput.dataset.fromInventory = '1';
                cbdInput.readOnly = true;
            }
        } else if (force || cbdInput.dataset.fromInventory === '1') {
            cbdInput.value = '';
            cbdInput.dataset.fromInventory = '';
            cbdInput.readOnly = false;
        }
    }
    updateWeedEdibleUsePreview();
}

function updateWeedEdibleUsePreview() {
    const preview = document.getElementById('use-weed-edible-thc-preview');
    if (!preview) return;
    if (!isWeedDateOnlyUseForm() || getWeedUseProductType({ allowEmpty: true }) !== 'edibles') {
        preview.textContent = 'Estimated THC / CBD mg used: —';
        return;
    }
    const amount = parseFloat(document.getElementById('use-amount')?.value);
    const mgPer = parseFloat(document.getElementById('use-weed-edible-mg-per')?.value);
    const cbdPer = parseFloat(document.getElementById('use-weed-edible-cbd-mg-per')?.value);
    if (Number.isFinite(amount) && amount > 0 && Number.isFinite(mgPer) && mgPer > 0) {
        let text = `Estimated THC mg used: ${formatAmount(amount * mgPer)} mg`
            + ` (${formatAmount(amount)} edible × ${formatAmount(mgPer)} mg)`;
        if (Number.isFinite(cbdPer) && cbdPer >= 0) {
            text += ` · CBD ${formatAmount(amount * cbdPer)} mg`;
        }
        preview.textContent = text;
        return;
    }
    if (Number.isFinite(amount) && amount > 0) {
        preview.textContent = 'Estimated THC mg used: Strength missing — needs review';
        return;
    }
    preview.textContent = 'Estimated THC / CBD mg used: —';
}

/**
 * Keep the user's product-type selection. Inventory is filtered by product type;
 * linked inventory must not overwrite the dropdown.
 */
function syncWeedProductTypeFromPurchase() {
    if (!isWeedDateOnlyUseForm()) return;
    ensureWeedUseProductTypeDefault();
}

function syncWeedCartPercentBeforeFromInventory() {
    if (getWeedCartLogInputMode() !== 'checkpoints') return;
    const beforeEl = document.getElementById('use-weed-cart-percent-before');
    if (!beforeEl || document.activeElement === beforeEl) return;
    if (beforeEl.value !== '' && beforeEl.value != null) return;
    const substanceId = document.getElementById('use-substance')?.value;
    const purchaseId = resolveLinkedPurchaseId(substanceId, document.getElementById('use-transaction-type')?.value || 'use');
    const purchase = purchaseId ? findPurchase(purchaseId) : null;
    if (!purchase || !isWeedCartPurchase(purchase)) return;
    const remaining = getWeedCartPercentRemaining(purchase);
    if (remaining != null) beforeEl.value = String(remaining);
}

function computeWeedCartUseFromForm(options = {}) {
    const substanceId = document.getElementById('use-substance')?.value;
    if (!isWeedTrackingMode(substanceId)) return null;
    if (getWeedUseProductType({ allowEmpty: true }) !== 'cart') return null;

    const mode = getWeedCartLogInputMode();
    const purchaseId = resolveLinkedPurchaseId(
        substanceId,
        document.getElementById('use-transaction-type')?.value || 'use',
        { weedProductType: 'cart' }
    );
    const purchase = purchaseId ? findPurchase(purchaseId) : null;
    if (purchase) ensureWeedCartTracksPercent(purchase);

    let percentBefore = null;
    let percentAfter = null;
    let estimatedPercentUsed = null;

    if (mode === 'estimated') {
        estimatedPercentUsed = clampWeedCartPercent(document.getElementById('use-weed-cart-percent-used')?.value);
        if (estimatedPercentUsed == null) {
            return { error: 'Enter estimated percent used (0–100).' };
        }
        if (purchase) {
            const remaining = getWeedCartPercentRemaining(purchase);
            percentBefore = remaining;
            percentAfter = clampWeedCartPercent((remaining ?? 0) - estimatedPercentUsed);
        }
    } else {
        percentBefore = clampWeedCartPercent(document.getElementById('use-weed-cart-percent-before')?.value);
        percentAfter = clampWeedCartPercent(document.getElementById('use-weed-cart-percent-after')?.value);
        if (percentBefore == null) return { error: 'Enter percent before use (0–100).' };
        if (percentAfter == null) return { error: 'Enter percent after use (0–100).' };
        if (percentBefore < percentAfter) {
            return { error: 'Percent before use must be greater than or equal to percent after use.' };
        }
        estimatedPercentUsed = clampWeedCartPercent(percentBefore - percentAfter) ?? 0;
    }

    const remainingBefore = purchase ? getWeedCartPercentRemaining(purchase) : null;
    let remainingAfter = null;
    if (purchase && estimatedPercentUsed != null) {
        remainingAfter = clampWeedCartPercent((remainingBefore ?? 0) - estimatedPercentUsed) ?? 0;
    }

    return {
        purchase,
        purchaseId: purchase?.id ?? null,
        percentBefore,
        percentAfter: percentAfter ?? remainingAfter,
        estimatedPercentUsed,
        remainingBefore,
        remainingAfter,
        inputMode: mode,
        inventoryAffects: getUsePurchaseLinkMode() !== 'none' && !!purchase?.id
    };
}

function updateWeedCartUsePreview() {
    const preview = document.getElementById('use-weed-cart-estimated-preview');
    if (!preview) return;
    if (!isWeedDateOnlyUseForm() || getWeedUseProductType({ allowEmpty: true }) !== 'cart') {
        preview.textContent = 'Estimated percent used: —';
        return;
    }
    const calc = computeWeedCartUseFromForm({ editingId: editingUseId || null });
    if (!calc || calc.error) {
        preview.textContent = calc?.error || 'Estimated percent used: —';
        return;
    }
    const usedLabel = formatAmount(calc.estimatedPercentUsed);
    if (calc.inputMode === 'checkpoints' && calc.percentBefore != null && calc.percentAfter != null) {
        preview.textContent = `${formatAmount(calc.percentBefore)}% → ${formatAmount(calc.percentAfter)}% · ${usedLabel}% used`;
    } else {
        preview.textContent = `${usedLabel}% estimated use`;
    }
    if (calc.remainingAfter != null && calc.purchase) {
        preview.textContent += ` · inventory → ${formatAmount(calc.remainingAfter)}%`;
    }
}

function formatWeedCartUseSummary(log) {
    if (!log) return '—';
    const used = clampWeedCartPercent(log.estimatedPercentUsed ?? log.amount);
    const before = clampWeedCartPercent(log.percentBefore);
    const after = clampWeedCartPercent(log.percentLeftAfter ?? log.percentAfter ?? log.percentRemaining);
    if (before != null && after != null && used != null) {
        return `${formatAmount(before)}% → ${formatAmount(after)}% · ${formatAmount(used)}% used`;
    }
    if (used != null) return `${formatAmount(used)}% estimated use`;
    return '—';
}

function formatUseHistoryWeedAmountHtml(entry) {
    if (typeof formatWeedNormalizedUseSummary === 'function') {
        return `<span class="use-history-amount-compact">${escapeHtml(formatWeedNormalizedUseSummary(entry))}</span>`;
    }
    if (isWeedCartPercentLog(entry) || normalizeWeedProductType(entry.weedProductType, { allowEmpty: true }) === 'cart') {
        return `<span class="use-history-amount-compact">${escapeHtml(formatWeedCartUseSummary(entry))}</span>`;
    }
    if (isWeedEdiblesLog(entry) || normalizeWeedProductType(entry.weedProductType, { allowEmpty: true }) === 'edibles') {
        return `<span class="use-history-amount-compact">${escapeHtml(formatWeedEdibleUseSummary(entry))}</span>`;
    }
    const unit = entry.unit || '';
    const amount = formatAmount(entry.amount);
    if (normalizeWeedProductType(entry.weedProductType, { allowEmpty: true }) === 'bud') {
        return `<span class="use-history-amount-compact">${amount}${unit ? ` ${escapeHtml(unit)}` : ''} Bud</span>`;
    }
    return `<span class="use-history-amount-compact">${amount}${unit && unit !== 'units' ? ` ${escapeHtml(unit)}` : ''}</span>`;
}

function updateWeedUseFormUI() {
    if (!isWeedDateOnlyUseForm()) return;
    const productType = ensureWeedUseProductTypeDefault();
    const isCart = productType === 'cart';
    const isEdibles = productType === 'edibles';
    const isBud = productType === 'bud';
    const isPreRolls = productType === 'pre-rolls';
    document.getElementById('use-weed-product-type-group')?.classList.remove('hidden');
    document.getElementById('use-weed-cart-fields-group')?.classList.toggle('hidden', !isCart);
    document.getElementById('use-weed-edibles-fields-group')?.classList.toggle('hidden', !isEdibles);
    document.getElementById('use-weed-bud-fields-group')?.classList.toggle('hidden', !isBud);
    document.getElementById('use-weed-preroll-fields-group')?.classList.toggle('hidden', !isPreRolls);
    document.getElementById('use-amount-mode-group')?.classList.toggle('hidden', isCart);
    if (typeof updateWeedBudEstimateVisibility === 'function') updateWeedBudEstimateVisibility();
    const amountInput = document.getElementById('use-amount');
    if (amountInput) {
        amountInput.required = !isCart;
        if (isEdibles) {
            amountInput.step = '0.01';
            amountInput.min = '0';
            amountInput.placeholder = 'e.g. 0.25';
            if (!amountInput.dataset.weedEdibleBound) {
                amountInput.addEventListener('input', updateWeedEdibleUsePreview);
                amountInput.dataset.weedEdibleBound = '1';
            }
        } else {
            amountInput.placeholder = '';
        }
    }
    const unitSelect = document.getElementById('use-unit');
    if (unitSelect) {
        unitSelect.required = !isCart;
        unitSelect.disabled = isCart;
    }
    updateWeedUseAmountLabel(productType || 'bud');
    updateWeedUseUnitOptions(productType || 'bud');
    if (isCart) {
        syncWeedCartPercentBeforeFromInventory();
        updateWeedCartUsePreview();
    }
    if (isEdibles) {
        syncWeedEdibleStrengthFromInventory({ force: editingUseId == null });
        updateWeedEdibleUsePreview();
    }
}

function ensureWeedUseFormDefaults() {
    if (!isWeedDateOnlyUseForm()) return;
    setUseLogType('quick');
    const startEl = document.getElementById('use-start-time');
    if (startEl) {
        startEl.value = '';
        startEl.required = false;
    }
    clearUseEndTimeInputs();
}

function setDefaultWeedUseLogDate() {
    const dateStr = getLocalDateString(new Date());
    const dateEl = document.getElementById('use-date');
    if (dateEl) dateEl.value = dateStr;
    const startEl = document.getElementById('use-start-time');
    if (startEl) {
        startEl.value = '';
        startEl.required = false;
    }
    clearUseEndTimeInputs({ hideDurationPreview: false });
}

function setDefaultVapeUseLogDate() {
    setDefaultWeedUseLogDate();
}

function parseUseSessionEndDateTime(startDate, startTime, endDate, endTime, { allowInferOvernight = true } = {}) {
    const start = getLogStartDateTime({ date: startDate, startTime, time: startTime });
    if (!start) return { start: null, end: null, invalid: false };
    const resolvedEndDate = endDate || inferEndDate(startDate, startTime, endTime);
    let end = endTime ? parseUseDateTime(resolvedEndDate, endTime) : null;
    if (!end) return { start, end: null, invalid: false };
    if (end <= start) {
        if (allowInferOvernight && !endDate && resolvedEndDate === startDate) {
            end = new Date(end);
            end.setDate(end.getDate() + 1);
        } else {
            return { start, end, invalid: true };
        }
    }
    return { start, end, invalid: false };
}

function getLogStartDateTime(log) {
    if (log?.startedAt) {
        const d = new Date(log.startedAt);
        if (!Number.isNaN(d.getTime())) return d;
    }
    const startTime = log?.startTime || log?.time;
    if (!log?.date || !startTime) return null;
    return parseUseDateTime(log.date, startTime);
}

function getLogEndDateTime(log) {
    if (log?.endedAt) {
        const d = new Date(log.endedAt);
        if (!Number.isNaN(d.getTime())) return d;
    }
    if (log?.endDatetime) {
        const d = new Date(log.endDatetime);
        if (!Number.isNaN(d.getTime())) return d;
    }
    if (!log?.endTime) return null;
    const startTime = log.startTime || log.time;
    let endDate = log.endDate || inferEndDate(log.date, startTime, log.endTime);
    let end = parseUseDateTime(endDate, log.endTime);
    const start = getLogStartDateTime(log);
    if (start && end && end <= start) {
        endDate = inferEndDate(log.date, startTime, log.endTime);
        end = parseUseDateTime(endDate, log.endTime);
    }
    return end;
}

function getUseLogStartedAt(log) {
    return getLogStartDateTime(log);
}

function getUseLogEndedAt(log) {
    return getLogEndDateTime(log);
}

function syncCokeSessionEndDateDefault({ fromStartDateChange = false } = {}) {
    if (!shouldShowUseEndDateField()) return;
    const startDate = document.getElementById('use-date')?.value;
    const startTime = document.getElementById('use-start-time')?.value;
    const endTime = document.getElementById('use-end-time')?.value;
    const endDateEl = document.getElementById('use-end-date');
    if (!startDate || !endDateEl) return;

    if (fromStartDateChange) {
        delete endDateEl.dataset.manual;
    }

    const isManual = endDateEl.dataset.manual === '1';
    if (!isManual) {
        endDateEl.value = startDate;
        endDateEl.dataset.syncedStart = startDate;
        if (startTime && endTime && timeToMinutes(endTime) < timeToMinutes(startTime)) {
            endDateEl.value = addDaysToDateStr(startDate, 1);
        }
    }
}

function syncVapeEndDateDefault() {
    syncCokeSessionEndDateDefault();
}

function estimateLogCostWithFallback(log, substanceId, data = appData) {
    const direct = estimateLogCost(log);
    if (direct > 0) return direct;
    const avg = getAveragePurchaseCostPerUnit(substanceId || getUseSubstanceId(log), data);
    if (avg == null) return 0;
    return (parseFloat(log.amount) || 0) * avg;
}

function differenceInMinutes(end, start) {
    return (end - start) / 60000;
}

function startOfNextDay(dt) {
    const dateStr = getLocalDateString(dt);
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr);
    if (!match) return null;
    const y = Number(match[1]);
    const m = Number(match[2]) - 1;
    const day = Number(match[3]);
    return new Date(y, m, day + 1, 0, 0, 0, 0);
}

function splitLogAcrossDays(log) {
    const amount = Number(log.amount) || 0;
    const count = Number(log.count) || 0;
    const startTime = log.startTime || log.time;

    if (!log.date || !startTime || !log.endTime || amount <= 0) {
        return [{
            date: log.date,
            amount,
            count,
            minutes: null,
            sourceLogId: log.id,
            log
        }];
    }

    const start = parseLocalDateTime(log.date, startTime);
    const endDate = log.endDate || inferEndDate(log.date, startTime, log.endTime);
    const end = parseLocalDateTime(endDate, log.endTime);

    if (!start || !end || end <= start) {
        return [{
            date: log.date,
            amount,
            count,
            minutes: null,
            sourceLogId: log.id,
            log,
            needsReview: true
        }];
    }

    const totalMinutes = Math.round((end - start) / 60000);

    if (totalMinutes <= 0) {
        return [{
            date: log.date,
            amount,
            count,
            minutes: null,
            sourceLogId: log.id,
            log,
            needsReview: true
        }];
    }

    const segments = [];
    let cursor = new Date(start);
    const spansDays = formatYYYYMMDD(start) !== formatYYYYMMDD(end);

    while (cursor < end) {
        const dateKey = formatYYYYMMDD(cursor);
        const nextMidnight = new Date(cursor);
        nextMidnight.setHours(24, 0, 0, 0);

        const segmentEnd = nextMidnight < end ? nextMidnight : end;
        const minutes = Math.round((segmentEnd - cursor) / 60000);
        const ratio = minutes / totalMinutes;

        segments.push({
            date: dateKey,
            amount: amount * ratio,
            count: count * ratio,
            minutes,
            ratio,
            sourceLogId: log.id,
            log,
            isSplitSegment: spansDays
        });

        cursor = segmentEnd;
    }

    return segments;
}

function getUsageSegments(logs, options = {}) {
    const {
        substanceId = 'all',
        transactionTypes = ['use'],
        startDate = null,
        endDate = null,
        excludeLogId = null,
        data = appData
    } = options;

    const source = logs ?? getUseEntries(data);

    return source
        .filter(log => {
            if (excludeLogId && logIdEquals(log.id, excludeLogId)) return false;
            if (!transactionTypes.includes(getLogTransactionType(log))) return false;
            if (substanceId !== 'all' && !logMatchesSubstance(log, substanceId, data)) return false;
            return true;
        })
        .flatMap(log => {
            if (log.excludeFromStats && isAlcoholMultiDayParentLog(log)) {
                return [];
            }
            if (isAlcoholMultiDayChildLog(log)) {
                const statsLog = isSharedUseLog(log)
                    ? { ...log, amount: getLogStatsAmount(log) }
                    : log;
                const logSubstanceId = getUseSubstanceId(log);
                const segAmount = getLogStatsAmount(statsLog);
                return [{
                    date: log.date,
                    amount: segAmount,
                    count: 0,
                    minutes: null,
                    sourceLogId: log.id,
                    log: statsLog,
                    originalLog: log,
                    cost: estimateSegmentCostFromLog(statsLog, segAmount, logSubstanceId, data)
                }];
            }
            const statsLog = isSharedUseLog(log)
                ? { ...log, amount: getLogStatsAmount(log) }
                : log;
            if (isVapeUseLog(log, data)) {
                return splitTimedLogByDay(statsLog, data);
            }
            const logSubstanceId = getUseSubstanceId(log);
            return splitLogAcrossDays(statsLog).map(seg => ({
                ...seg,
                originalLog: seg.log || log,
                isOvernightPart: !!seg.isSplitSegment,
                cost: estimateSegmentCostFromLog(statsLog, seg.amount, logSubstanceId, data)
            }));
        })
        .filter(seg => {
            if (startDate && seg.date < startDate) return false;
            if (endDate && seg.date > endDate) return false;
            return true;
        });
}

function sumUsageSegments(segments) {
    return segments.reduce((total, seg) => {
        total.amount += Number(seg.amount) || 0;
        total.count += Number(seg.count) || 0;
        total.minutes += Number(seg.minutes) || 0;
        total.cost += Number(seg.cost) || 0;
        return total;
    }, {
        amount: 0,
        count: 0,
        minutes: 0,
        cost: 0
    });
}

function sumUsageForDate(logs, date, substanceId = 'all', options = {}) {
    const { excludeLogId = null, data = appData } = options;
    return sumUsageSegments(
        getUsageSegments(logs, {
            substanceId,
            startDate: date,
            endDate: date,
            excludeLogId,
            data
        })
    );
}

function sumUsageForRange(logs, startDate, endDate, substanceId = 'all', options = {}) {
    const { excludeLogId = null, data = appData } = options;
    return sumUsageSegments(
        getUsageSegments(logs, {
            substanceId,
            startDate,
            endDate,
            excludeLogId,
            data
        })
    );
}

function sumSegmentsForDate(substanceId, dateStr, excludeLogId = null, data = appData) {
    return sumUseAmountForDate(substanceId, dateStr, excludeLogId, data);
}

function sumSegmentsForRange(substanceId, startDate, endDate, excludeLogId = null, data = appData) {
    return sumUseAmountForRange(substanceId, startDate, endDate, excludeLogId, data);
}

function logOverlapsDateRange(log, startDate, endDate, data = appData) {
    if (!log?.date) return false;
    if (!isPersonalUseLog(log)) {
        if (startDate && log.date < startDate) return false;
        if (endDate && log.date > endDate) return false;
        return true;
    }
    return splitLogAcrossDays(log).some(seg => {
        if (startDate && seg.date < startDate) return false;
        if (endDate && seg.date > endDate) return false;
        return seg.amount > INVENTORY_EPS;
    });
}

function splitTimedLogByDay(log, data = appData) {
    if (!isPersonalUseLog(log)) return [];

    const substanceId = getUseSubstanceId(log);

    if (isVapeUseLog(log, data)) {
        return getVapeLogStatsAllocations(log, data).map(alloc => ({
            date: alloc.date,
            minutes: null,
            amount: alloc.amount,
            count: 0,
            cost: estimateSegmentCostFromLog(log, alloc.amount, substanceId, data),
            sourceLogId: log.id,
            originalLog: log,
            log,
            isOvernightPart: false,
            isSplitSegment: false
        }));
    }

    return splitLogAcrossDays(log).map(seg => ({
        ...seg,
        originalLog: seg.log || log,
        isOvernightPart: !!seg.isSplitSegment,
        cost: estimateSegmentCostFromLog(log, seg.amount, substanceId, data)
    }));
}

function getSegmentCostPerUnit(log, substanceId, data = appData) {
    const sid = substanceId || getUseSubstanceId(log);
    const pid = getLogPurchaseId(log);
    if (pid) {
        const purchase = findPurchase(pid, data);
        if (purchase) {
            const qty = parseFloat(getPurchaseQuantity(purchase)) || 0;
            const totalCost = parseFloat(getPurchaseTotalCost(purchase)) || 0;
            if (qty > 0 && totalCost > 0) return totalCost / qty;
            const cpu = parseFloat(purchase.costPerUnit);
            if (Number.isFinite(cpu) && cpu > 0) return cpu;
        }
    }
    return getAveragePurchaseCostPerUnit(sid, data);
}

function estimateSegmentCostFromLog(log, segmentAmount, substanceId, data = appData) {
    const amount = Number(segmentAmount) || 0;
    if (amount <= INVENTORY_EPS) return 0;
    const costPerUnit = getSegmentCostPerUnit(log, substanceId, data);
    if (costPerUnit == null) return 0;
    return amount * costPerUnit;
}

function getDailyUseSegments(logs, substanceId, { excludeLogId = null, data = appData, startDate = null, endDate = null } = {}) {
    return getUsageSegments(logs, {
        substanceId: substanceId || 'all',
        excludeLogId,
        data,
        startDate,
        endDate
    });
}

function sumUseAmountForDate(substanceId, dateStr, excludeLogId = null, data = appData) {
    if (isVapeNicotineSubstanceId(substanceId, data)) {
        return getVapeDistributedUsageMap(substanceId, data).get(dateStr) || 0;
    }
    return sumUsageForDate(null, dateStr, substanceId, { excludeLogId, data }).amount;
}

function sumUseAmountForRange(substanceId, startDate, endDate, excludeLogId = null, data = appData) {
    if (isVapeNicotineSubstanceId(substanceId, data)) {
        return getStatsUsageInRange(substanceId, startDate, endDate, data);
    }
    return sumUsageForRange(null, startDate, endDate, substanceId, { excludeLogId, data }).amount;
}

function sumUseMinutesForDate(substanceId, dateStr, data = appData) {
    return sumUsageForDate(null, dateStr, substanceId, { data }).minutes;
}

function sumUseMinutesForRange(substanceId, startDate, endDate, data = appData) {
    return sumUsageForRange(null, startDate, endDate, substanceId, { data }).minutes;
}

function sumUseCostForDate(substanceId, dateStr, data = appData) {
    return sumUsageForDate(null, dateStr, substanceId, { data }).cost;
}

function sumUseCostForRange(substanceId, startDate, endDate, data = appData) {
    return sumUsageForRange(null, startDate, endDate, substanceId, { data }).cost;
}

function isUseDay(substanceId, dateStr, data = appData) {
    if (isNicotineSubstanceId(substanceId, data)) {
        const logs = getUseLogsForSubstance(substanceId, { personalUseOnly: true, data });
        return logs.some(log => logHasUseSegmentOnDate(log, dateStr, data));
    }
    if (isVapeNicotineSubstanceId(substanceId, data)) {
        return (getStatsUsageOnDate(substanceId, dateStr, data) || 0) > INVENTORY_EPS;
    }
    return sumUsageForDate(null, dateStr, substanceId, { data }).amount > INVENTORY_EPS;
}

function getUseDayCountFromSegments(substanceId, startDate, endDate, data = appData) {
    if (startDate && endDate) {
        let count = 0;
        iterateDatesInRange(startDate, endDate).forEach(dateStr => {
            if (isUseDay(substanceId, dateStr, data)) count++;
        });
        return count;
    }
    const dates = new Set();
    getUsageSegments(null, { substanceId, data, startDate, endDate })
        .filter(seg => seg.amount > INVENTORY_EPS)
        .forEach(seg => dates.add(seg.date));
    return dates.size;
}

function logHasUseSegmentOnDate(log, dateStr, data = appData) {
    return splitTimedLogByDay(log, data).some(seg => seg.date === dateStr && seg.amount > INVENTORY_EPS);
}

function formatShortMonthDay(dateStr) {
    const d = parseLocalDate(dateStr);
    if (!d) return dateStr || '';
    return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}

function formatUseSessionTimeRange(log) {
    const startTime = log.startTime || log.time || '';
    const endTime = log.endTime || '';
    if (!endTime) return startTime || '—';
    return `${startTime || '—'} → ${endTime}`;
}

function formatOvernightSplitNote(log, substanceId, data = appData) {
    const segments = splitTimedLogByDay(log, data);
    if (segments.length <= 1 || !segments.some(s => s.isOvernightPart)) return '';
    const unit = getStatsDisplayUnit(substanceId, getSubstance(substanceId, data)?.defaultUnit || 'units');
    const parts = segments
        .filter(s => s.amount > INVENTORY_EPS)
        .map(s => `${formatShortMonthDay(s.date)} ${formatAmount(s.amount)} ${unit}`);
    return parts.length > 1 ? `Daily split: ${parts.join(' · ')}` : '';
}

function ensureVapeUseFormDefaults() {
    if (!isVapeDateOnlyUseForm()) return;
    setInputValue('use-transaction-type', 'use');
    setUseLogType('quick');
    const startEl = document.getElementById('use-start-time');
    if (startEl) {
        startEl.value = '';
        startEl.required = false;
    }
    clearUseEndTimeInputs();
}

function isGiftGivenLog(log) {
    return getLogTransactionType(log) === 'gift_given';
}

function isGiftReceivedLog(log) {
    return getLogTransactionType(log) === 'gift_received';
}

function isInventoryAdjustmentLog(log) {
    return getLogTransactionType(log) === 'inventory_adjustment';
}

function isNonUseTransactionLog(log) {
    return !isPersonalUseLog(log);
}

function logInventoryAffects(log) {
    if (log?.inventoryAffects === false) return false;
    if (log?.linkedPurchases?.length) return true;
    if (getLogPurchaseId(log)) return true;
    return log?.inventoryAffects === true;
}

function hasLinkedSupply(log) {
    if (getLogPurchaseId(log)) return true;
    return Array.isArray(log?.linkedPurchases) && log.linkedPurchases.length > 0;
}

function getLinkedSupplyLabel(log) {
    const purchases = appData.purchases || [];
    const purchaseId = getLogPurchaseId(log);

    if (purchaseId) {
        const purchase = purchases.find(p => String(p.id) === String(purchaseId));
        if (purchase) {
            if (isVapePuffPurchase(purchase)) {
                const label = formatVapePurchaseTitleLine(purchase);
                return `Linked: ${formatDate(purchase.date)} · ${label}`;
            }
            const store = purchase.store || purchase.location || purchase.substanceName || '';
            return `Linked: ${formatDate(purchase.date)} purchase${store ? ` · ${store}` : ''}`;
        }
        return 'Linked: unknown purchase';
    }

    if (Array.isArray(log.linkedPurchases) && log.linkedPurchases.length) {
        return log.linkedPurchases.map(lp => {
            const purchase = purchases.find(p => String(p.id) === String(lp.purchaseId));
            const amt = formatAmount(lp.amountUsed ?? lp.amount ?? 0);
            const unit = log.unit || purchase?.unit || '';
            if (!purchase) return `${amt}${unit} from unknown supply`;
            const store = purchase.store || purchase.location || '';
            return `${amt}${unit} from ${formatDate(purchase.date)}${store ? ` · ${store}` : ''}`;
        }).join(', ');
    }

    if (log.legacySupplyText) {
        return `Legacy: ${log.legacySupplyText}`;
    }

    const tx = getLogTransactionType(log);
    if (tx === 'gift_received') return 'Gift received · no purchase';
    if (log.inventoryAffects === false) return 'No linked purchase';

    return 'No linked purchase';
}

function formatInventoryLinkDisplay(log) {
    return getLinkedSupplyLabel(log);
}

function getAdjustmentDirection(log) {
    return log?.adjustmentDirection === 'remove' ? 'remove' : 'add';
}

function inventoryAdjustmentAdds(log) {
    return isInventoryAdjustmentLog(log) && getAdjustmentDirection(log) === 'add';
}

function inventoryAdjustmentRemoves(log) {
    return isInventoryAdjustmentLog(log) && getAdjustmentDirection(log) === 'remove';
}

function getTransactionTypeLabel(tx) {
    if (tx === 'shared_use') return 'Legacy Shared Use';
    if (tx === 'gift_given') return 'Gift Given';
    if (tx === 'gift_received') return 'Gift Received';
    if (tx === 'inventory_adjustment') return 'Inventory Adjustment';
    return 'Personal Use';
}

function formatLogHistoryLabel(entry, sub) {
    const tx = getLogTransactionType(entry);
    const unit = entry.unit || sub?.defaultUnit || 'units';
    const amount = entry.amount ?? '—';
    if (tx === 'gift_given') {
        if (isLsdDateOnlyUseLog(entry)) return `🎁 ${formatLsdUseSummary(entry)}`;
        const who = entry.giftPartyName ? ` — ${entry.giftPartyName}` : '';
        return `🎁 Gift Given${who} — ${amount}${unit}`;
    }
    if (tx === 'gift_received') {
        if (isLsdDateOnlyUseLog(entry)) return `🎁 ${formatLsdUseSummary(entry)}`;
        const who = entry.giftPartyName ? ` — ${entry.giftPartyName}` : '';
        return `🎁 Gift Received${who} — ${amount}${unit}`;
    }
    if (tx === 'inventory_adjustment') {
        if (isLsdDateOnlyUseLog(entry)) return `📦 ${formatLsdUseSummary(entry)}`;
        const dir = getAdjustmentDirection(entry) === 'remove' ? '−' : '+';
        return `📦 Inventory ${dir}${amount}${unit}`;
    }
    if (isVapeUseLog(entry)) {
        return formatVapeUseSummary(entry, sub);
    }
    if (isLsdDateOnlyUseLog(entry)) {
        return formatLsdUseSummary(entry);
    }
    if (isXanaxDateOnlyUseLog(entry)) {
        return formatXanaxUseSummary(entry);
    }
    if (isWeedDateOnlyUseLog(entry)) {
        return `${sub?.icon || ''} ${amount} ${unit}`;
    }
    const typeLabel = getUseLogType(entry) === 'session' ? '⏱️ Session' : '⚡ Quick Use';
    return `${typeLabel} ${sub?.icon || ''} ${amount} ${unit} ${sub?.name || 'Unknown'}`;
}

function setLegacySharedUseFormTransactionType() {
    const hidden = document.getElementById('use-transaction-type');
    if (hidden) hidden.value = 'shared_use';
    document.querySelectorAll('#use-transaction-type-block .use-tx-pill').forEach(btn => {
        btn.classList.remove('active');
    });
    document.getElementById('use-legacy-shared-banner')?.classList.remove('hidden');
    document.getElementById('use-adjustment-direction-group')?.classList.add('hidden');
    document.getElementById('use-gift-party-group')?.classList.add('hidden');
    document.querySelector('.use-log-core-card')?.classList.remove('gift-adjustment-mode');
    updateUseEndTimeVisibility();
    updateVapeUseFormUI();
    updateUseTransactionTypePillsVisibility();
    updateUsePurchaseLinkUI();
}

function setUseTransactionType(tx) {
    if (tx === 'shared_use') return;

    const hidden = document.getElementById('use-transaction-type');
    if (hidden) hidden.value = tx;
    document.querySelectorAll('#use-transaction-type-block .use-tx-pill').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.tx === tx);
    });
    document.getElementById('use-legacy-shared-banner')?.classList.add('hidden');

    const isGiftGiven = tx === 'gift_given';
    const isGiftReceived = tx === 'gift_received';
    const isGift = isGiftGiven || isGiftReceived;
    const isAdjustment = tx === 'inventory_adjustment';
    const isNonUse = isGift || isAdjustment;

    document.getElementById('use-adjustment-direction-group')?.classList.toggle('hidden', !isAdjustment);
    document.getElementById('use-gift-party-group')?.classList.toggle('hidden', !isGift);

    const partyLabel = document.getElementById('use-gift-party-label');
    if (partyLabel) partyLabel.textContent = isGiftReceived ? 'From' : 'Recipient Name';

    const amountLabel = document.getElementById('use-amount-label');
    if (amountLabel) {
        if (isAdjustment) amountLabel.textContent = 'Amount';
        else if (isGiftReceived) amountLabel.textContent = 'Amount Received';
        else if (isGiftGiven) amountLabel.textContent = 'Amount Given';
        else if (isWeedDateOnlyUseForm()) updateWeedUseAmountLabel(getWeedUseProductType());
        else amountLabel.textContent = 'Amount';
    }

    const linkLabel = document.getElementById('use-purchase-link-label');
    if (linkLabel) {
        if (isGiftReceived || (isAdjustment && getUseAdjustmentDirection() === 'add')) {
            linkLabel.textContent = 'Add to Inventory';
        } else if (isAdjustment) {
            linkLabel.textContent = 'Remove from Inventory';
        } else {
            linkLabel.textContent = 'Use From Inventory';
        }
    }

    document.querySelector('.use-log-core-card')?.classList.toggle('gift-adjustment-mode', isNonUse);

    if (isNonUse) {
        const typeHidden = document.getElementById('use-type');
        if (typeHidden) typeHidden.value = 'quick';
    }
    updateUseEndTimeVisibility();
    updateVapeUseFormUI();
    updateUseTransactionTypePillsVisibility();
    updateUsePurchaseLinkUI();
}

function getUseAdjustmentDirection() {
    const active = document.querySelector('.use-adj-pill.active');
    return active?.dataset.dir === 'remove' ? 'remove' : 'add';
}

function setUseAdjustmentDirection(dir) {
    document.querySelectorAll('.use-adj-pill').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.dir === dir);
    });
    updateUsePurchaseLinkUI();
    updateLsdUsePreview();
    updateXanaxUsePreview();
}

function setUseFormSubmitLabel(text) {
    const btn = document.getElementById('use-submit-btn');
    if (btn) btn.textContent = text;
}

function getUseEventTimestamp(date, startTime) {
    if (!startTime) {
        const day = parseLocalDate(date);
        if (day && !Number.isNaN(day.getTime())) {
            return new Date(day.getTime() + 12 * 3600000).toISOString();
        }
    }
    const startDt = parseUseDateTime(date, startTime);
    return startDt && !Number.isNaN(startDt.getTime())
        ? startDt.toISOString()
        : new Date().toISOString();
}

function getUseCreatedAt(entry) {
    return entry.createdAt || entry.timestamp || new Date().toISOString();
}

function buildUseEntryFromForm(vapeCalc = null, lsdCalc = null, nicotineCalc = null, xanaxCalc = null, alcoholCalc = null, weedCartCalc = null) {
    const rawSubstanceId = document.getElementById('use-substance')?.value;
    const substanceId = isNicotineTrackingMode(rawSubstanceId) ? NICOTINE_ID : rawSubstanceId;
    const isNicotine = isNicotineTrackingMode(substanceId);
    const isAlcohol = isAlcoholTrackingMode(substanceId);
    const isAlcoholMultiDay = isAlcohol && (alcoholCalc?.isMultiDay || getAlcoholUseEntryMode() === 'multi_day');
    const nicotineProductType = isNicotine ? getUseFormNicotineProductType() : null;
    const isVapeDateOnly = isNicotine ? nicotineProductType === 'vape' : isVapeTrackingMode(substanceId);
    const isNicotineSimple = isNicotine && nicotineProductType !== 'vape' && nicotineProductType !== 'other';
    const isWeedSimple = isWeedTrackingMode(substanceId);
    const weedProductType = isWeedSimple ? getWeedUseProductType({ allowEmpty: true }) : '';
    const isWeedCart = isWeedSimple && weedProductType === 'cart';
    const isLsdQuick = isLsdSubstanceId(substanceId);
    const isXanaxSimple = isXanaxSubstanceId(substanceId);
    const transactionType = document.getElementById('use-transaction-type')?.value || 'use';
    const isGiftGiven = transactionType === 'gift_given';
    const isGiftReceived = transactionType === 'gift_received';
    const isGift = isGiftGiven || isGiftReceived;
    const isAdjustment = transactionType === 'inventory_adjustment';
    let type = (isGift || isAdjustment || isWeedSimple || isVapeDateOnly || isLsdQuick || isXanaxSimple || isNicotineSimple || isAlcohol) ? 'quick' : (document.getElementById('use-type')?.value || 'quick');
    const date = isAlcoholMultiDay && alcoholCalc?.startDate
        ? alcoholCalc.startDate
        : document.getElementById('use-date')?.value;
    const xanaxOmitsStartTime = isXanaxSimple && !isGift && !isAdjustment;
    const startTime = (isWeedSimple || isVapeDateOnly || isNicotineSimple || xanaxOmitsStartTime)
        ? ''
        : (document.getElementById('use-start-time')?.value || '12:00');
    const endDate = isAlcoholMultiDay
        ? (alcoholCalc?.endDate || document.getElementById('use-end-date')?.value || date)
        : ((isWeedSimple || isVapeDateOnly || isLsdQuick || isXanaxSimple || isNicotineSimple) ? null : (document.getElementById('use-end-date')?.value || date));
    const endTime = isAlcoholMultiDay
        ? (alcoholCalc?.endTime || document.getElementById('use-end-time')?.value || '')
        : ((isWeedSimple || isVapeDateOnly || isLsdQuick || isXanaxSimple || isNicotineSimple) ? '' : (document.getElementById('use-end-time')?.value || ''));
    const isVapeUse = isVapeDateOnly;
    const isCokeSession = isCokeSubstanceId(substanceId) && type === 'session';

    let amount;
    let unit;
    let linkedPurchaseId;
    let inventoryAffects;
    let logMode = isWeedSimple ? 'amount' : 'amount';
    let percentRemaining;
    let previousRemainingBeforeLog;

    if (isVapeUse && vapeCalc && !vapeCalc.error) {
        amount = vapeCalc.estimatedPuffsUsed ?? vapeCalc.puffsUsed;
        unit = 'puffs';
        linkedPurchaseId = vapeCalc.purchaseId;
        inventoryAffects = getUsePurchaseLinkMode() !== 'none' && !!linkedPurchaseId;
        logMode = 'vape_puffs';
        percentRemaining = vapeCalc.percentAfter;
        previousRemainingBeforeLog = vapeCalc.previousRemaining;
    } else if (isWeedCart && weedCartCalc && !weedCartCalc.error) {
        amount = weedCartCalc.estimatedPercentUsed;
        unit = 'percent';
        linkedPurchaseId = weedCartCalc.purchaseId;
        inventoryAffects = !!weedCartCalc.inventoryAffects && linkedPurchaseId != null;
        logMode = 'weed_cart_percent';
        percentRemaining = weedCartCalc.percentAfter;
        previousRemainingBeforeLog = weedCartCalc.remainingBefore;
    } else if (isNicotineSimple && nicotineCalc && !nicotineCalc.error) {
        amount = nicotineCalc.amount;
        unit = nicotineCalc.unit;
        linkedPurchaseId = nicotineCalc.purchaseId;
        inventoryAffects = nicotineCalc.inventoryAffects;
        logMode = nicotineCalc.logMode || 'amount';
    } else if (isLsdQuick && lsdCalc && !lsdCalc.error) {
        amount = lsdCalc.ugUsed;
        unit = 'ug';
        linkedPurchaseId = lsdCalc.purchaseId;
        inventoryAffects = getUsePurchaseLinkMode() !== 'none' && !!linkedPurchaseId;
        logMode = 'lsd_dose';
    } else if (isXanaxSimple && xanaxCalc && !xanaxCalc.error) {
        amount = xanaxCalc.pillsUsed;
        unit = 'pills';
        linkedPurchaseId = xanaxCalc.purchaseId;
        inventoryAffects = getUsePurchaseLinkMode() !== 'none' && !!linkedPurchaseId;
        logMode = 'xanax_dose';
    } else if (isAlcohol && alcoholCalc && !alcoholCalc.error) {
        amount = alcoholCalc.totalAmount ?? alcoholCalc.amount;
        unit = alcoholCalc.unit;
        linkedPurchaseId = resolveLinkedPurchaseId(substanceId, transactionType);
        inventoryAffects = getUsePurchaseLinkMode() !== 'none' && linkedPurchaseId != null;
        logMode = alcoholCalc.isMultiDay ? 'alcohol_multiday' : 'alcohol_quick';
    } else {
        amount = parseFloat(document.getElementById('use-amount')?.value);
        unit = isAlcohol ? getAlcoholFormUnit() : document.getElementById('use-unit')?.value;
        const linkMode = getUsePurchaseLinkMode();
        linkedPurchaseId = resolveLinkedPurchaseId(substanceId, transactionType);
        inventoryAffects = linkMode !== 'none' && linkedPurchaseId != null;
    }

    const giftParty = (isGiftGiven || isGiftReceived)
        ? ((typeof getContactPickerSelection === 'function' ? getContactPickerSelection('use-gift-party').name : '')
            || document.getElementById('use-gift-party')?.value?.trim()
            || '')
        : '';

    const base = {
        type,
        transactionType,
        substanceId,
        amount: Number.isFinite(amount) ? amount : 0,
        unit: unit || 'units',
        logMode,
        percentRemaining: percentRemaining != null ? percentRemaining : undefined,
        previousRemainingBeforeLog: previousRemainingBeforeLog != null ? previousRemainingBeforeLog : undefined,
        date,
        endDate: (isWeedSimple || isVapeDateOnly || isLsdQuick || isXanaxSimple) ? undefined : ((isGift || isAdjustment || type === 'session' || isAlcoholMultiDay) ? (endDate || date) : undefined),
        startTime,
        time: startTime,
        endTime: (isWeedSimple || isVapeDateOnly || isLsdQuick || isXanaxSimple) ? '' : ((isGift || isAdjustment || type === 'session' || isAlcoholMultiDay) ? (endTime || '') : ''),
        count: (isGift || isAdjustment || isWeedSimple || isLsdQuick || isXanaxSimple) ? 0 : (parseFloat(document.getElementById('use-count')?.value) || 0),
        giftPartyName: (typeof getContactPickerSelection === 'function' ? getContactPickerSelection('use-gift-party').name : '') || giftParty,
        recipientName: isGiftGiven ? giftParty : '',
        giverName: isGiftReceived ? giftParty : '',
        sharedWithName: '',
        adjustmentDirection: isAdjustment ? getUseAdjustmentDirection() : undefined,
        notes: document.getElementById('use-notes')?.value || '',
        purchaseId: inventoryAffects ? linkedPurchaseId : null,
        linkedPurchaseId: inventoryAffects ? linkedPurchaseId : null,
        inventoryId: inventoryAffects ? linkedPurchaseId : null,
        linkedPurchases: [],
        supplyUnlinked: !inventoryAffects,
        inventoryAffects
    };

    base.trackingMode = isNicotineTrackingMode(substanceId) ? 'nicotine' : getSubstanceTrackingMode(substanceId);
    if (typeof applyLogContactIdsToEntry === 'function') applyLogContactIdsToEntry(base);

    if (isAlcohol && alcoholCalc && !alcoholCalc.error) {
        base.isMultiDay = !!alcoholCalc.isMultiDay;
        if (alcoholCalc.isMultiDay) {
            base.startDate = alcoholCalc.startDate;
            base.endDate = alcoholCalc.endDate;
            base.totalAmount = alcoholCalc.totalAmount;
            base.splitEvenlyAcrossDays = alcoholCalc.splitEvenlyAcrossDays;
            base.dailyBreakdown = alcoholCalc.dailyBreakdown;
            base.startedAt = alcoholCalc.startedAt;
            base.endedAt = alcoholCalc.endedAt;
            base.durationMs = alcoholCalc.durationMs;
        }
    }

    if (isWeedSimple) {
        if (weedProductType) {
            base.weedProductType = weedProductType;
            base.needsReview = false;
        } else {
            delete base.weedProductType;
            base.needsReview = true;
        }
    }

    if (isWeedCart && weedCartCalc && !weedCartCalc.error) {
        base.weedProductType = 'cart';
        base.logMode = 'weed_cart_percent';
        base.unit = 'percent';
        base.amount = weedCartCalc.estimatedPercentUsed;
        base.estimatedPercentUsed = weedCartCalc.estimatedPercentUsed;
        if (weedCartCalc.percentBefore != null) base.percentBefore = weedCartCalc.percentBefore;
        if (weedCartCalc.percentAfter != null) {
            base.percentLeftAfter = weedCartCalc.percentAfter;
            base.percentAfter = weedCartCalc.percentAfter;
            base.percentRemaining = weedCartCalc.percentAfter;
        }
        base.estimatedFromPercent = weedCartCalc.inputMode === 'checkpoints';
        base.needsReview = false;
    }

    if (isWeedSimple && weedProductType === 'edibles') {
        base.weedProductType = 'edibles';
        base.unit = 'edible';
        base.logMode = 'weed_edible';
        let mgPer = parseFloat(document.getElementById('use-weed-edible-mg-per')?.value);
        if (!(Number.isFinite(mgPer) && mgPer > 0) && linkedPurchaseId) {
            const linked = findPurchase(linkedPurchaseId);
            mgPer = getWeedEdibleMgPerEdible(linked);
        }
        if (Number.isFinite(mgPer) && mgPer > 0) {
            base.mgPerEdibleAtTimeOfUse = mgPer;
            const thcUsed = (Number.isFinite(amount) ? amount : 0) * mgPer;
            base.thcMgUsed = thcUsed;
            base.mgUsed = thcUsed;
        } else {
            delete base.mgPerEdibleAtTimeOfUse;
            delete base.thcMgUsed;
            delete base.mgUsed;
        }
        base.needsReview = false;
    }

    if (isNicotine) {
        base.nicotineProductType = nicotineProductType;
    }

    if (isNicotineSimple && nicotineCalc && !nicotineCalc.error) {
        base.nicotineProductType = nicotineCalc.nicotineProductType || nicotineProductType;
        if (nicotineCalc.cigarettesUsed != null) base.cigarettesUsed = nicotineCalc.cigarettesUsed;
        if (nicotineCalc.packsUsed != null) base.packsUsed = nicotineCalc.packsUsed;
        if (nicotineCalc.pouchesUsed != null) base.pouchesUsed = nicotineCalc.pouchesUsed;
        if (nicotineCalc.piecesUsed != null) base.piecesUsed = nicotineCalc.piecesUsed;
        if (nicotineCalc.patchesUsed != null) base.patchesUsed = nicotineCalc.patchesUsed;
        if (nicotineCalc.patchHoursWorn != null) base.patchHoursWorn = nicotineCalc.patchHoursWorn;
        if (nicotineCalc.nicotineMgUsed != null) base.nicotineMgUsed = nicotineCalc.nicotineMgUsed;
    }

    if (isVapeUse && vapeCalc && !vapeCalc.error) {
        base.nicotineProductType = 'vape';
        base.isEstimated = !!vapeCalc.isEstimated;
        base.estimatedFromPercent = !!vapeCalc.estimatedFromPercent;
        base.percentLeftAfter = vapeCalc.percentAfter;
        base.remainingPuffsAfter = vapeCalc.currentRemaining;
        base.estimatedPuffsUsed = vapeCalc.estimatedPuffsUsed ?? vapeCalc.puffsUsed;
    }

    if (isLsdQuick && lsdCalc && !lsdCalc.error) {
        base.tabsUsed = lsdCalc.tabsUsed;
        base.ugUsed = lsdCalc.ugUsed;
        base.ugPerTabAtTimeOfUse = lsdCalc.ugPerTabAtTimeOfUse;
    }

    if (isXanaxSimple && xanaxCalc && !xanaxCalc.error) {
        base.pillsUsed = xanaxCalc.pillsUsed;
        base.mgUsed = xanaxCalc.mgUsed;
        base.strengthPerPillAtTimeOfUse = xanaxCalc.strengthPerPillAtTimeOfUse;
        base.strengthUnitAtTimeOfUse = xanaxCalc.strengthUnitAtTimeOfUse;
        base.mgPerPillAtTimeOfUse = xanaxCalc.mgPerPillAtTimeOfUse;
    }

    if (isCokeSession && endTime) {
        const { start, end, invalid } = parseUseSessionEndDateTime(date, startTime, endDate || date, endTime, {
            allowInferOvernight: false
        });
        if (!invalid && start && end) {
            base.startedAt = start.toISOString();
            base.endedAt = end.toISOString();
            base.durationMs = end - start;
            base.endDate = endDate || date;
        }
    }

    return base;
}

function normalizeUseLogWellness(log) {
    if (!log) return;
    const parseLevel = val => {
        if (val == null || val === '') return null;
        const n = parseInt(val, 10);
        return Number.isFinite(n) ? Math.min(10, Math.max(1, n)) : null;
    };
    log.cravingLevel = parseLevel(log.cravingLevel ?? log.craving);
    log.stressLevel = parseLevel(log.stressLevel);
    if (log.mood != null && typeof log.mood !== 'string') log.mood = String(log.mood);
    if (log.trigger != null && typeof log.trigger !== 'string') log.trigger = String(log.trigger);
    if (log.mood == null) log.mood = '';
    if (log.trigger == null) log.trigger = '';
    delete log.craving;
}

function stripLegacyUseLogFields(entry) {
    if (!entry) return;
    delete entry.cost;
    delete entry.location;
    normalizeUseLogWellness(entry);
}

function resetUseFormAfterSave() {
    if (typeof onExperienceModeAfterUseLogSave === 'function') {
        try { onExperienceModeAfterUseLogSave(); } catch (_) { /* ignore */ }
    }
    editingUseId = null;
    document.getElementById('use-log-form')?.reset();
    setDefaultUseLogDateTime();
    setUseLogType('quick');
    setUseFormSubmitLabel('Save Entry');
    document.getElementById('cancel-use-edit-btn')?.classList.add('hidden');
    applyMainSubstanceToForms();
    updateUseUnitDropdown();
    setUsePurchaseLinkMode(
        (typeof isSimpleExperienceMode === 'function' && isSimpleExperienceMode()) ? 'none' : 'auto'
    );
    setUseTransactionType('use');
    setUseAdjustmentDirection('add');
    setAlcoholUseEntryMode('single_day');
    const alcoholSplitEl = document.getElementById('use-alcohol-split-evenly');
    if (alcoholSplitEl) alcoholSplitEl.checked = true;
    updateVapeUseFormUI();
    if (typeof applySimpleLogFormLayout === 'function') {
        try { applySimpleLogFormLayout(appData); } catch (_) { /* ignore */ }
    }
}

function refreshUseLogRelatedViews() {
    recalculateAllBreaks();
    recalculateAllBuyBreaks();
    renderUseLogTab();
    updateDashboard();
    updateStats();
    refreshTaperDashboard();
    refreshBuyTrackerRelatedViews();
    if (typeof isSimpleExperienceMode === 'function' && isSimpleExperienceMode()) {
        try { renderSimpleHome(appData); } catch (_) { /* ignore */ }
        try { renderSimpleProgress(appData); } catch (_) { /* ignore */ }
    }
}

function getLogDatetimeMs(log) {
    if (isWeedDateOnlyUseLog(log) || isVapeDateOnlyUseLog(log)) {
        const day = parseLocalDate(log.date);
        if (day && !Number.isNaN(day.getTime())) {
            return day.getTime() + 12 * 3600000;
        }
    }
    if (log.startedAt) {
        const ms = new Date(log.startedAt).getTime();
        if (!Number.isNaN(ms)) return ms;
    }
    if (log.startDatetime) {
        const ms = new Date(log.startDatetime).getTime();
        if (!Number.isNaN(ms)) return ms;
    }
    if (log.timestamp) {
        const ms = new Date(log.timestamp).getTime();
        if (!Number.isNaN(ms)) return ms;
    }
    const time = log.startTime || log.time || '00:00';
    const dt = parseLocalDateTime(log.date, time);
    const ms = dt ? dt.getTime() : 0;
    return Number.isNaN(ms) ? 0 : ms;
}

function getPurchaseDatetimeMs(purchase) {
    const dt = parseLocalDateTime(purchase.date, purchase.time || '12:00');
    const ms = dt ? dt.getTime() : 0;
    return Number.isNaN(ms) ? 0 : ms;
}

function findPurchaseInData(id, data) {
    if (id == null || id === '') return null;
    return (data?.purchases || []).find(p => p.id === id || String(p.id) === String(id)) || null;
}

function finalizePurchaseRemainingState(purchase) {
    const remaining = getPurchaseRemainingAmount(purchase);
    if (remaining <= INVENTORY_EPS) {
        purchase.remainingAmount = 0;
        purchase.isDepleted = true;
    } else {
        purchase.isDepleted = false;
    }
}

function deductPurchaseRemainingInData(purchase, amount) {
    const amt = parseFloat(amount) || 0;
    if (amt <= 0) return 0;
    if (isWeedCartPurchase(purchase)) ensureWeedCartTracksPercent(purchase);
    const remaining = getPurchaseRemainingAmount(purchase);
    const used = Math.min(amt, remaining);
    purchase.remainingAmount = Math.max(0, remaining - used);
    finalizePurchaseRemainingState(purchase);
    if (isLsdPurchase(purchase)) syncLsdPurchaseRemaining(purchase);
    if (isXanaxPurchase(purchase)) syncXanaxPurchaseRemaining(purchase);
    if (isWeedEdiblesPurchase(purchase)) syncWeedEdiblePurchaseRemaining(purchase);
    return used;
}

function addPurchaseRemainingInData(purchase, amount) {
    const amt = parseFloat(amount) || 0;
    if (amt <= 0) return 0;
    const cap = getPurchaseQuantityBought(purchase);
    const remaining = getPurchaseRemainingAmount(purchase);
    purchase.remainingAmount = Math.min(cap, remaining + amt);
    finalizePurchaseRemainingState(purchase);
    if (isLsdPurchase(purchase)) syncLsdPurchaseRemaining(purchase);
    if (isXanaxPurchase(purchase)) syncXanaxPurchaseRemaining(purchase);
    if (isWeedEdiblesPurchase(purchase)) syncWeedEdiblePurchaseRemaining(purchase);
    return purchase.remainingAmount - remaining;
}

function subtractPurchaseRemainingInData(purchase, amount) {
    const amt = parseFloat(amount) || 0;
    if (amt <= 0) return 0;
    purchase.remainingAmount = Math.max(0, getPurchaseRemainingAmount(purchase) - amt);
    finalizePurchaseRemainingState(purchase);
    if (isLsdPurchase(purchase)) syncLsdPurchaseRemaining(purchase);
    if (isXanaxPurchase(purchase)) syncXanaxPurchaseRemaining(purchase);
    if (isWeedEdiblesPurchase(purchase)) syncWeedEdiblePurchaseRemaining(purchase);
    return amt;
}

function resolveGiftReceivedPurchaseInData(substanceId, purchases) {
    const list = (purchases || [])
        .filter(p => getPurchaseSubstanceId(p) === substanceId)
        .sort((a, b) => getPurchaseDatetimeMs(a) - getPurchaseDatetimeMs(b));
    const active = list.find(p => !p.isDepleted && getPurchaseRemainingAmount(p) > INVENTORY_EPS);
    if (active) return active;
    return list.length ? list[list.length - 1] : null;
}

function resolveGiftReceivedPurchaseId(substanceId) {
    const purchase = resolveGiftReceivedPurchaseInData(substanceId, appData.purchases || []);
    return purchase?.id || null;
}

function addPurchaseAmount(purchaseId, amount, data = appData) {
    if (!purchaseId) return { ok: true };
    const purchase = findPurchaseInData(purchaseId, data);
    if (!purchase) return { ok: false, error: 'Linked purchase not found.' };
    addPurchaseRemainingInData(purchase, amount);
    purchase.updatedAt = new Date().toISOString();
    return { ok: true };
}

function applyLogInventoryEffect(log, data = appData) {
    if (!logInventoryAffects(log)) return { ok: true };

    const amount = getLogInventoryDeductionAmount(log);
    if (amount <= INVENTORY_EPS) return { ok: true };

    if (isGiftReceivedLog(log) || inventoryAdjustmentAdds(log)) {
        if (log.linkedPurchases?.length) {
            for (const alloc of log.linkedPurchases) {
                const result = addPurchaseAmount(alloc.purchaseId, alloc.amountUsed ?? alloc.amount, data);
                if (!result.ok) return result;
            }
            return { ok: true };
        }
        const pid = getLogPurchaseId(log);
        return pid ? addPurchaseAmount(pid, amount, data) : { ok: true };
    }

    if (log.linkedPurchases?.length) {
        for (const alloc of log.linkedPurchases) {
            const result = deductPurchaseAmount(alloc.purchaseId, alloc.amountUsed ?? alloc.amount, data);
            if (!result.ok) return result;
        }
        return { ok: true };
    }

    const deductId = getLogPurchaseId(log);
    if (inventoryAdjustmentRemoves(log) || deductId) {
        return deductPurchaseAmount(deductId, amount, data);
    }

    return { ok: true };
}

function resetAllPurchaseInventory(purchases) {
    purchases.forEach(purchase => {
        const qty = getPurchaseQuantityBought(purchase);
        if (!purchase.quantityBought && qty) purchase.quantityBought = qty;
        if (!purchase.quantity && qty) purchase.quantity = qty;
        purchase.remainingAmount = qty;
        purchase.isDepleted = false;
    });
}

function logIsUnlinked(log) {
    if (log.linkedPurchases?.length) return false;
    return !getLogPurchaseId(log);
}

function applyExistingLogLinks(log, purchases) {
    const purchaseIds = [];
    if (!logInventoryAffects(log)) return purchaseIds;

    const amount = getLogInventoryDeductionAmount(log);
    if (amount <= INVENTORY_EPS) return purchaseIds;

    const addsInventory = isGiftReceivedLog(log) || inventoryAdjustmentAdds(log);
    const applyChange = addsInventory ? addPurchaseRemainingInData : deductPurchaseRemainingInData;

    if (log.linkedPurchases?.length) {
        log.linkedPurchases.forEach(alloc => {
            const purchase = findPurchaseInData(alloc.purchaseId, { purchases });
            if (purchase) {
                applyChange(purchase, alloc.amountUsed);
                purchaseIds.push(purchase.id);
            }
        });
        log.supplyUnlinked = false;
        return purchaseIds;
    }
    const pid = getLogPurchaseId(log);
    if (pid) {
        const purchase = findPurchaseInData(pid, { purchases });
        if (purchase) {
            applyChange(purchase, amount);
            purchaseIds.push(purchase.id);
        }
        log.supplyUnlinked = false;
    }
    return purchaseIds;
}

function fifoLinkLogToPurchases(log, purchases) {
    const amount = parseFloat(log.amount) || 0;
    if (amount <= INVENTORY_EPS) {
        return { linked: false, unmatched: false, purchaseIds: [] };
    }

    if (isGiftReceivedLog(log) || inventoryAdjustmentAdds(log)) {
        if (!logInventoryAffects(log)) {
            return { linked: false, unmatched: true, purchaseIds: [] };
        }
        const purchaseIds = applyExistingLogLinks(log, purchases);
        return {
            linked: purchaseIds.length > 0,
            unmatched: purchaseIds.length === 0,
            purchaseIds
        };
    }

    const substanceId = getUseSubstanceId(log);
    const logMs = getLogDatetimeMs(log);
    let amountLeft = amount;
    const allocations = [];
    const purchaseIds = [];

    const eligible = purchases
        .filter(p => getPurchaseSubstanceId(p) === substanceId)
        .filter(p => getPurchaseDatetimeMs(p) <= logMs)
        .sort((a, b) => getPurchaseDatetimeMs(a) - getPurchaseDatetimeMs(b));

    for (const purchase of eligible) {
        if (amountLeft <= INVENTORY_EPS) break;
        const remaining = getPurchaseRemainingAmount(purchase);
        if (remaining <= INVENTORY_EPS) continue;
        const used = deductPurchaseRemainingInData(purchase, amountLeft);
        if (used > 0) {
            allocations.push({ purchaseId: purchase.id, amountUsed: used });
            purchaseIds.push(purchase.id);
            amountLeft -= used;
        }
    }

    if (allocations.length === 1) {
        setLogPurchaseId(log, allocations[0].purchaseId);
    } else if (allocations.length > 1) {
        log.linkedPurchases = allocations;
        log.purchaseId = null;
        log.linkedPurchaseId = null;
        log.inventoryAffects = true;
        log.supplyUnlinked = false;
    } else {
        setLogPurchaseId(log, null);
    }

    return {
        linked: allocations.length > 0,
        unmatched: allocations.length === 0 || amountLeft > INVENTORY_EPS,
        purchaseIds
    };
}

function migrateInventoryLinkedV1(data) {
    ensureAppDataMigrations(data);
    if (data.migrations.inventoryLinkedV1) return;

    const purchases = data.purchases || [];
    const logs = data.logs || [];
    resetAllPurchaseInventory(purchases);

    const sortedLogs = [...logs].sort((a, b) => getLogDatetimeMs(a) - getLogDatetimeMs(b));

    sortedLogs.forEach(log => {
        const amount = parseFloat(log.amount) || 0;
        if (amount <= INVENTORY_EPS) return;

        if (log.linkedPurchases?.length) {
            applyExistingLogLinks(log, purchases);
            return;
        }

        if (log.linkedPurchaseId != null && log.linkedPurchaseId !== '') {
            applyExistingLogLinks(log, purchases);
            return;
        }

    });

    purchases.forEach(finalizePurchaseRemainingState);
    data.migrations.inventoryLinkedV1 = true;
}

function migratePurchaseIdLinkV2(data) {
    ensureAppDataMigrations(data);
    if (data.migrations.purchaseIdLinkV2) return;

    ensurePurchaseIds(data);
    (data.logs || []).forEach(log => {
        syncLogPurchaseFields(log);
        if (hasLinkedSupply(log)) {
            log.inventoryAffects = true;
            log.supplyUnlinked = false;
            return;
        }
        captureLegacySupplyText(log);
        log.purchaseId = null;
        log.linkedPurchaseId = null;
        log.linkedPurchases = [];
        log.inventoryAffects = false;
        log.supplyUnlinked = true;
    });

    data.migrations.purchaseIdLinkV2 = true;
}

function recalculateAllInventory(data = appData) {
    const purchases = data.purchases || [];
    const logs = data.logs || [];
    const nonVapePurchases = purchases.filter(p => !isVapePuffPurchase(p));
    resetAllPurchaseInventory(nonVapePurchases);

    const sortedLogs = [...logs].sort((a, b) => getLogDatetimeMs(a) - getLogDatetimeMs(b));

    sortedLogs.forEach(log => {
        if (isVapeUseLog(log, data)) return;
        const amount = parseFloat(log.amount) || 0;
        if (amount <= INVENTORY_EPS) return;

        if (log.linkedPurchases?.length) {
            applyExistingLogLinks(log, nonVapePurchases);
            return;
        }

        if (getLogPurchaseId(log)) {
            applyExistingLogLinks(log, nonVapePurchases);
        }
    });

    nonVapePurchases.forEach(finalizePurchaseRemainingState);
    purchases.filter(isVapePuffPurchase).forEach(p => recalculateVapePurchaseInventory(p.id, data));
}

function refreshAfterLogLinkChange(substanceId) {
    saveData(appData);
    recalculateAllInventory();
    if (substanceId) recalculateBreaks(substanceId);
    else recalculateAllBreaks();
    renderUseHistoryTable();
    renderRecentUseList();
    refreshBuyTrackerRelatedViews();
    updateDashboard();
    updateStats();
    updateCurrentSupplyDashboard();
    refreshTaperDashboard();
}

function getPurchaseQuantityBought(purchase) {
    const q = purchase.quantityBought ?? purchase.quantity;
    return parseFloat(q) || 0;
}

function getPurchaseRemainingAmount(purchase) {
    if (purchase.remainingAmount != null && purchase.remainingAmount !== '') {
        return Math.max(0, parseFloat(purchase.remainingAmount) || 0);
    }
    if (purchase.isDepleted) return 0;
    if (isVapePuffPurchase(purchase)) {
        if (purchase?.acquisitionType === 'gift_received' && getVapeFullPuffCount(purchase) <= 0) {
            const pct = getVapePercentBoughtAt(purchase);
            return pct > 0 ? null : 0;
        }
        return getVapeStartingPuffsLeft(purchase);
    }
    return getPurchaseQuantityBought(purchase);
}

function isGiftReceivedVapeWithoutKnownPuffCount(purchase) {
    return !!purchase
        && purchase.acquisitionType === 'gift_received'
        && isVapePuffPurchase(purchase)
        && getVapeFullPuffCount(purchase) <= 0;
}

function isPurchaseEffectivelyDepleted(purchase) {
    if (!purchase) return false;
    if (purchase.isDepleted || purchase.inventoryStatus === 'depleted') return true;
    if (isGiftReceivedVapeWithoutKnownPuffCount(purchase)) {
        return (getVapePercentBoughtAt(purchase) || 0) <= 0;
    }
    const remaining = getPurchaseRemainingAmount(purchase);
    if (remaining == null) return false;
    if (remaining <= INVENTORY_EPS) return true;
    if (isVapePuffPurchase(purchase)) {
        const full = getVapeFullPuffCount(purchase);
        if (full > 0) {
            const remPuffs = purchase.remainingPuffs != null && purchase.remainingPuffs !== ''
                ? parseFloat(purchase.remainingPuffs)
                : remaining;
            return Number.isFinite(remPuffs) && remPuffs <= INVENTORY_EPS;
        }
    }
    return false;
}

function repairGiftReceivedVapeInventory(purchase) {
    if (!purchase || purchase.acquisitionType !== 'gift_received' || !isVapePuffPurchase(purchase)) return false;
    const pct = getVapePercentBoughtAt(purchase);
    if (!(pct > 0)) return false;
    const full = getVapeFullPuffCount(purchase);
    const remaining = full > 0 ? Math.round(full * (pct / 100)) : null;
    purchase.percentBoughtAt = pct;
    purchase.startingPercent = pct;
    purchase.remainingPercent = pct;
    purchase.fullPuffCount = full > 0 ? full : null;
    purchase.quantityBought = full > 0 ? (purchase.quantityBought > 0 ? purchase.quantityBought : full) : null;
    purchase.quantity = full > 0 ? (purchase.quantity > 0 ? purchase.quantity : full) : null;
    purchase.startingPuffsLeft = remaining;
    purchase.remainingPuffs = remaining;
    purchase.remainingAmount = remaining;
    purchase.isDepleted = false;
    purchase.inventoryStatus = 'active';
    purchase.depletedAt = null;
    return true;
}

function getLinkedUseAmountForPurchase(purchaseId, logs = []) {
    let total = 0;
    (logs || []).forEach(log => {
        if (!logInventoryAffects(log)) return;
        const applyAmount = (amt) => {
            const amount = parseFloat(amt) || 0;
            if (amount <= INVENTORY_EPS) return;
            const tx = getLogTransactionType(log);
            if (tx === 'gift_received' || inventoryAdjustmentAdds(log)) total -= amount;
            else if (tx === 'use' || tx === 'shared_use' || tx === 'gift_given' || inventoryAdjustmentRemoves(log)) total += amount;
        };
        if (log.linkedPurchases?.length) {
            log.linkedPurchases.forEach(alloc => {
                if (alloc.purchaseId === purchaseId || String(alloc.purchaseId) === String(purchaseId)) {
                    applyAmount(alloc.amountUsed ?? alloc.amount);
                }
            });
            return;
        }
        const pid = getLogPurchaseId(log);
        if (pid === purchaseId || String(pid) === String(purchaseId)) {
            applyAmount(getLogInventoryDeductionAmount(log));
        }
    });
    return total;
}

function migratePurchaseInventory(purchase, logs, data) {
    if (isVapePuffPurchase(purchase)) {
        normalizeVapePurchaseFields(purchase);
        if (purchase.remainingAmount == null || purchase.remainingAmount === '') {
            purchase.remainingAmount = getVapeStartingPuffsLeft(purchase);
        }
        finalizePurchaseRemainingState(purchase);
    } else {
        const qty = getPurchaseQuantityBought(purchase);
        if (!purchase.quantityBought && qty) purchase.quantityBought = qty;
        if (!purchase.quantity && qty) purchase.quantity = qty;
        if (purchase.remainingAmount == null || purchase.remainingAmount === '') {
            const used = getLinkedUseAmountForPurchase(purchase.id, logs);
            purchase.remainingAmount = Math.max(0, qty - used);
        }
        finalizePurchaseRemainingState(purchase);
    }
    if (!purchase.substanceName) {
        const substanceRef = getPurchaseSubstanceId(purchase);
        const sub = getSubstance(substanceRef, data);
        purchase.substanceName = sub?.name || '';
    }
    if (!purchase.createdAt) purchase.createdAt = new Date().toISOString();
    if (!purchase.updatedAt) purchase.updatedAt = purchase.createdAt;
}

function findPurchase(id, data = appData) {
    return findPurchaseInData(id, data);
}

function getActivePurchasesForSubstance(substanceId) {
    const resolved = normalizeNicotineSubstanceRef(substanceId);
    return (appData.purchases || [])
        .filter(p => {
            const pid = getPurchaseSubstanceId(p);
            return (pid === substanceId || normalizeNicotineSubstanceRef(pid) === resolved)
                && purchaseIsPersonalUseInventory(p)
                && !p.isDepleted
                && getPurchaseRemainingAmount(p) > 0;
        })
        .sort((a, b) => getPurchaseDatetimeMs(b) - getPurchaseDatetimeMs(a));
}

function getActivePurchasesForNicotineProductType(substanceId, productType, data = appData) {
    return getActivePurchasesForSubstance(substanceId)
        .filter(p => getNicotineProductType(p, data) === productType);
}

function getActivePurchasesForWeedProductType(substanceId, productType) {
    return getActivePurchasesForSubstance(substanceId)
        .filter(p => purchaseMatchesWeedProductType(p, productType));
}

function getOldestActivePurchase(substanceId, productType = null, options = {}) {
    const weedProductType = options.weedProductType || null;
    if (weedProductType && isWeedTrackingMode(substanceId)) {
        return getActivePurchasesForWeedProductType(substanceId, weedProductType)[0] || null;
    }
    const active = productType
        ? getActivePurchasesForNicotineProductType(substanceId, productType)
        : getActivePurchasesForSubstance(substanceId);
    return active[0] || null;
}

function getPurchasePercentUsed(purchase) {
    if (isVapePuffPurchase(purchase)) {
        const starting = getVapeStartingPuffsLeft(purchase);
        if (starting <= 0) return 0;
        const remaining = getPurchaseRemainingAmount(purchase);
        return Math.round(((starting - remaining) / starting) * 100);
    }
    const bought = getPurchaseQuantityBought(purchase);
    if (bought <= 0) return 0;
    const remaining = getPurchaseRemainingAmount(purchase);
    return Math.round(((bought - remaining) / bought) * 100);
}

function getPurchaseSupplyStatus(purchase) {
    let result;
    if (purchaseIsPurchasedAsGift(purchase) || purchase?.inventoryStatus === 'gifted') {
        result = { key: 'gifted', label: '🎁 Gifted', className: 'supply-gifted' };
    } else if (isVapePuffPurchase(purchase)) {
        const pctLeft = getPurchasePercentRemaining(purchase);
        const remaining = getPurchaseRemainingAmount(purchase);
        const starting = getVapeStartingPuffsLeft(purchase);
        if (isPurchaseEffectivelyDepleted(purchase)) {
            result = { key: 'depleted', label: '❌ Depleted', className: 'supply-depleted' };
        } else if (starting > 0 && remaining != null && remaining / starting <= SUPPLY_LOW_REMAINING_PCT) {
            result = { key: 'low', label: '⚠️ Low supply', className: 'supply-low' };
        } else if (isGiftReceivedVapeWithoutKnownPuffCount(purchase) && pctLeft > 0) {
            result = { key: 'ok', label: '✅ In supply', className: 'supply-ok' };
        } else {
            result = { key: 'ok', label: '✅ In supply', className: 'supply-ok' };
        }
    } else {
        const bought = getPurchaseQuantityBought(purchase);
        const remaining = getPurchaseRemainingAmount(purchase);
        if (isPurchaseEffectivelyDepleted(purchase)) {
            result = { key: 'depleted', label: '❌ Depleted', className: 'supply-depleted' };
        } else if (bought > 0 && remaining / bought <= SUPPLY_LOW_REMAINING_PCT) {
            result = { key: 'low', label: '⚠️ Low supply', className: 'supply-low' };
        } else {
            result = { key: 'ok', label: '✅ In supply', className: 'supply-ok' };
        }
    }
    if (typeof evaluateInventoryColors === 'function' && typeof getPurchasePercentRemaining === 'function') {
        const pct = getPurchasePercentRemaining(purchase);
        const ccr = evaluateInventoryColors(pct, {
            substanceId: getPurchaseSubstanceId(purchase),
            section: 'inventory'
        });
        if (ccr.matched.length) {
            result.ccrResult = ccr;
            result.className = `${result.className} ccr-applied`.trim();
            if (ccr.labels[0]) result.label = ccr.labels[0];
            result.style = buildConditionalColorInlineStyle(ccr);
        }
    }
    return result;
}

function isPercentRemainingUnit(unit) {
    return PERCENT_REMAINING_UNITS.has((unit || '').toLowerCase());
}

function getPurchasePercentRemaining(purchase) {
    if (isVapePuffPurchase(purchase)) {
        const full = getVapeFullPuffCount(purchase);
        if (full <= 0) {
            if (purchase?.acquisitionType === 'gift_received') {
                const pct = getVapePercentBoughtAt(purchase);
                return Number.isFinite(pct) ? Math.max(0, Math.min(100, pct)) : 0;
            }
            return 0;
        }
        const remaining = getPurchaseRemainingAmount(purchase);
        if (remaining == null) {
            const pct = getVapePercentBoughtAt(purchase);
            return Number.isFinite(pct) ? Math.max(0, Math.min(100, pct)) : 0;
        }
        return Math.round((remaining / full) * 1000) / 10;
    }
    const bought = getPurchaseQuantityBought(purchase);
    if (bought <= 0) return 0;
    const remaining = getPurchaseRemainingAmount(purchase);
    return Math.round((remaining / bought) * 1000) / 10;
}

function formatPercentRemainingLabel(remaining, bought) {
    if (bought <= 0) return '';
    const pct = Math.round((remaining / bought) * 1000) / 10;
    const label = Number.isInteger(pct) ? String(pct) : pct.toFixed(1);
    return `${label}% left`;
}

function isVapeNicotineSubstanceId(substanceId, data = appData) {
    return isNicotineSubstanceId(substanceId, data);
}

function isVapeNicotineSubstance(sub, data = appData) {
    return sub?.id ? isVapeTrackingMode(sub.id, data) : false;
}

function isVapePuffUnit(unit) {
    return isPercentRemainingUnit(unit);
}

function isVapePuffPurchase(purchase, data = appData) {
    const substanceId = getPurchaseSubstanceId(purchase);
    if (isNicotineTrackingMode(substanceId, data)) {
        return getNicotineProductType(purchase, data) === 'vape' && isVapePuffUnit(purchase?.unit);
    }
    return isVapeTrackingMode(substanceId, data) && isVapePuffUnit(purchase?.unit);
}

function getVapeFullPuffCount(purchase) {
    if (!purchase) return 0;
    const full = purchase.fullPuffCount ?? purchase.quantityBought ?? purchase.quantity;
    return parseFloat(full) || 0;
}

function getVapePurchaseFlavor(purchase) {
    if (!purchase?.flavor) return '';
    return String(purchase.flavor).trim();
}

function purchaseSupportsFlavor(purchase, data = appData) {
    if (!purchase) return false;
    return isVapePuffPurchase(purchase, data) || isNicotineVapeProduct(purchase, data);
}

function substanceShowsPurchaseFlavor(substanceId, data = appData) {
    if (!substanceId || substanceId === DASHBOARD_ALL) return true;
    if (isCokeSubstanceId(substanceId)) return false;
    if (isNicotineSubstanceId(substanceId, data) || isVapeNicotineSubstanceId(substanceId, data)) return true;
    if (isVapeTrackingMode(substanceId, data)) return true;
    return false;
}

function getInventorySearchPlaceholder(substanceId = getInventorySubstanceFilterId()) {
    return substanceShowsPurchaseFlavor(substanceId)
        ? 'Search store, notes, flavor…'
        : 'Search store, notes…';
}

function syncInventorySearchPlaceholder(substanceId = getInventorySubstanceFilterId()) {
    const el = document.getElementById('inventory-search');
    if (el) el.placeholder = getInventorySearchPlaceholder(substanceId);
}

function getPurchaseHistoryVisibleColumns(substanceId = getInventorySubstanceFilterId()) {
    const columns = getEffectiveColumnOrder('purchaseHistory');
    if (substanceShowsPurchaseFlavor(substanceId)) return columns;
    return columns.filter(colId => colId !== 'flavor');
}

/** Substance-family catalogs for Log → Use History columns. */
const USE_HISTORY_FAMILY_COLUMNS = {
    all: [
        'select', 'date', 'start', 'end', 'duration', 'substance', 'transactionType',
        'amount', 'unit', 'contact', 'breakBetweenUses', 'inventory', 'notes', 'actions'
    ],
    nicotine: [
        'select', 'date', 'start', 'end', 'duration', 'productType', 'transactionType',
        'amount', 'unit', 'contact', 'sharedAmount', 'breakBetweenUses', 'inventory', 'notes', 'actions'
    ],
    cocaine: [
        'select', 'date', 'start', 'end', 'duration', 'transactionType',
        'amount', 'unit', 'gPerHour', 'breakBetweenUses', 'inventory', 'notes', 'actions'
    ],
    cannabis: [
        'select', 'date', 'productType', 'transactionType', 'amount', 'unit',
        'thcUsed', 'cbdUsed', 'strength', 'cost', 'contact', 'sharedAmount', 'breakBetweenUses', 'inventory', 'notes', 'actions'
    ],
    ketamine: [
        'select', 'date', 'start', 'end', 'duration', 'transactionType',
        'amount', 'unit', 'cost', 'breakBetweenUses', 'inventory', 'notes', 'actions'
    ],
    lsd: [
        'select', 'date', 'transactionType', 'tabs', 'ug', 'amount', 'breakBetweenUses', 'inventory', 'notes', 'actions'
    ],
    xanax: [
        'select', 'date', 'transactionType', 'pills', 'mg', 'strength', 'amount', 'breakBetweenUses', 'inventory', 'notes', 'actions'
    ],
    alcohol: [
        'select', 'date', 'transactionType', 'amount', 'unit',
        'multiDayRange', 'dailyBreakdown', 'breakBetweenUses', 'inventory', 'notes', 'actions'
    ],
    generic: [
        'select', 'date', 'start', 'end', 'duration', 'transactionType',
        'amount', 'unit', 'breakBetweenUses', 'inventory', 'notes', 'actions'
    ]
};

function getUseHistoryColumnFamily(substanceId, data = appData) {
    if (!substanceId || substanceId === DASHBOARD_ALL) return 'all';
    if (isNicotineTrackingMode(substanceId, data)) return 'nicotine';
    if (isAlcoholTrackingMode(substanceId, data)) return 'alcohol';
    if (isWeedTrackingMode(substanceId, data)) return 'cannabis';
    if (isLsdSubstanceId(substanceId, data)) return 'lsd';
    if (isXanaxSubstanceId(substanceId, data)) return 'xanax';
    const id = normalizeSubstanceRef(substanceId, data);
    if (id === 'ketamine') return 'ketamine';
    if (isCokeSubstanceId(substanceId) || isPowderTrackingMode(substanceId, data)) return 'cocaine';
    return 'generic';
}

function getUseHistoryColumnVariantKey(substanceId = getUseLogViewSubstanceId(), data = appData) {
    return getUseHistoryColumnFamily(substanceId, data);
}

function getUseHistoryColumnCatalog(substanceId = getUseLogViewSubstanceId(), data = appData) {
    const family = getUseHistoryColumnFamily(substanceId, data);
    const allowed = new Set(USE_HISTORY_FAMILY_COLUMNS[family] || USE_HISTORY_FAMILY_COLUMNS.generic);
    return TABLE_COLUMN_DEFAULTS.useHistory.order.filter(id => allowed.has(id));
}

function getDefaultUseHistoryColumnSettings(substanceId = getUseLogViewSubstanceId()) {
    const catalog = getUseHistoryColumnCatalog(substanceId);
    const family = getUseHistoryColumnFamily(substanceId);
    const base = getDefaultColumnSettings('useHistory');
    const visible = {};
    const required = new Set(TABLE_COLUMNS_REQUIRED.useHistory || []);
    let defaultVisible;
    if (family === 'cocaine') {
        defaultVisible = new Set(['select', 'date', 'start', 'end', 'amount', 'gPerHour', 'actions']);
    } else {
        defaultVisible = null;
    }
    catalog.forEach(id => {
        if (required.has(id)) {
            visible[id] = true;
            return;
        }
        if (defaultVisible) {
            visible[id] = defaultVisible.has(id);
            return;
        }
        visible[id] = base.visible[id] !== false;
    });
    if (family === 'cocaine') visible.cost = false;
    const order = [];
    (base.order || []).forEach(id => {
        if (catalog.includes(id) && !order.includes(id)) order.push(id);
    });
    catalog.forEach(id => {
        if (!order.includes(id)) order.push(id);
    });
    const widths = {};
    order.forEach(id => {
        widths[id] = base.widths?.[id] ?? TABLE_COLUMN_DEFAULTS.useHistory.widths?.[id];
    });
    return { order, visible, widths, customNames: {} };
}

function filterUseHistoryColumnSettingsToCatalog(settings, substanceId = getUseLogViewSubstanceId()) {
    const catalog = getUseHistoryColumnCatalog(substanceId);
    const catalogSet = new Set(catalog);
    const order = [];
    (settings?.order || []).forEach(id => {
        if (catalogSet.has(id) && !order.includes(id)) order.push(id);
    });
    catalog.forEach(id => {
        if (!order.includes(id)) order.push(id);
    });
    const visible = {};
    order.forEach(id => {
        visible[id] = settings?.visible?.[id] !== false;
    });
    (TABLE_COLUMNS_REQUIRED.useHistory || []).forEach(id => {
        if (catalogSet.has(id)) visible[id] = true;
    });
    if (getUseHistoryColumnFamily(substanceId) === 'cocaine') {
        visible.cost = false;
    }
    const widths = {};
    order.forEach(id => {
        if (settings?.widths?.[id] != null) widths[id] = settings.widths[id];
        else if (TABLE_COLUMN_DEFAULTS.useHistory.widths?.[id] != null) {
            widths[id] = TABLE_COLUMN_DEFAULTS.useHistory.widths?.[id];
        }
    });
    const customNames = normalizeCustomNamesMap('useHistory', settings?.customNames, order);
    return { order, visible, widths, customNames };
}

function getUseHistoryVisibleColumns(substanceId = getUseLogViewSubstanceId()) {
    const catalog = getUseHistoryColumnCatalog(substanceId);
    const variantKey = getUseHistoryColumnVariantKey(substanceId);
    const config = getTableColumnConfig('useHistory', variantKey);
    const required = new Set(TABLE_COLUMNS_REQUIRED.useHistory || []);
    const userVisible = config.visible || {};
    const family = getUseHistoryColumnFamily(substanceId);
    return catalog.filter(id => {
        if (family === 'cocaine' && id === 'cost') return false;
        return required.has(id) || userVisible[id] !== false;
    });
}

function getUseHistoryColumnLabel(colId, substanceId = getUseLogViewSubstanceId()) {
    const labels = TABLE_COLUMN_LABELS.useHistory;
    const family = getUseHistoryColumnFamily(substanceId);
    if (colId === 'inventory') {
        if (family === 'nicotine') return 'Linked Vape';
        if (family === 'lsd') return 'Linked Purchase';
        return 'Linked Inventory';
    }
    if (colId === 'amount') {
        if (family === 'nicotine') return 'Puffs / Percent Left';
        if (family === 'alcohol') return 'Drinks';
        return labels.amount || colId;
    }
    if (colId === 'unit' && family === 'alcohol') return 'Unit';
    if (colId === 'thcUsed') return 'THC Used';
    if (colId === 'strength') {
        if (family === 'cannabis') return 'Strength';
        return labels.strength || 'Strength';
    }
    if (colId === 'gPerHour') return 'g/hr';
    return labels[colId] || colId;
}

function getUseHistorySessionDurationHours(entry) {
    if (!entry) return null;
    const durationMs = parseFloat(entry.durationMs);
    if (Number.isFinite(durationMs) && durationMs > 0) return durationMs / 3600000;
    const durationHours = parseFloat(entry.durationHours);
    if (Number.isFinite(durationHours) && durationHours > 0) return durationHours;
    const start = getUseLogStartedAt(entry);
    const end = getUseLogEndedAt(entry);
    if (start && end) {
        const hours = (end.getTime() - start.getTime()) / 3600000;
        if (Number.isFinite(hours) && hours > 0) return hours;
    }
    return null;
}

function getUseLogAmountInGramsForRate(entry) {
    if (!entry) return null;
    if (isGiftGivenLog(entry) || isGiftReceivedLog(entry) || isInventoryAdjustmentLog(entry)) {
        return null;
    }
    let amount;
    if (isSharedUseLog(entry)) {
        amount = getLogPersonalAmount(entry);
    } else if (isPersonalUseLog(entry) || logCountsTowardPersonalUseStats(entry)) {
        amount = getLogPersonalAmount(entry);
        if (!(amount > 0) && amount !== 0) amount = parseFloat(entry.amount);
    } else {
        return null;
    }
    if (!Number.isFinite(amount) || amount < 0) return null;
    const unit = String(entry.unit || 'g').trim().toLowerCase();
    if (unit === 'mg' || unit === 'milligram' || unit === 'milligrams') {
        return amount / 1000;
    }
    if (unit === 'g' || unit === 'gram' || unit === 'grams' || unit === '') {
        return amount;
    }
    // Powder tracking defaults to grams when unit is unrecognized but numeric.
    return amount;
}

/**
 * Coke Use History g/hr = personal grams ÷ exact session hours.
 * Returns null when duration/amount is missing or the transaction is excluded.
 */
function computeUseHistoryGramsPerHour(entry) {
    if (!entry) return null;
    if (isGiftGivenLog(entry) || isGiftReceivedLog(entry) || isInventoryAdjustmentLog(entry)) {
        return null;
    }
    const hours = getUseHistorySessionDurationHours(entry);
    if (hours == null || !(hours > 0)) return null;
    const grams = getUseLogAmountInGramsForRate(entry);
    if (grams == null || !Number.isFinite(grams)) return null;
    return grams / hours;
}

function formatUseHistoryGramsPerHour(entry) {
    const rate = computeUseHistoryGramsPerHour(entry);
    if (rate == null || !Number.isFinite(rate)) return '—';
    return rate.toFixed(2);
}

/** Normalized session duration in minutes. Null when missing or zero. */
function getNormalizedSessionDurationMinutes(entry) {
    const hours = getUseHistorySessionDurationHours(entry);
    if (hours == null || !(hours > 0) || !Number.isFinite(hours)) return null;
    return hours * 60;
}

function formatNormalizedSessionDuration(minutes) {
    if (minutes == null || !Number.isFinite(minutes) || !(minutes > 0)) return '—';
    return formatDurationHours(minutes / 60);
}

/** Shared Coke-style g/hr (personal grams ÷ session hours). */
function getNormalizedGramsPerHour(entry) {
    return computeUseHistoryGramsPerHour(entry);
}

function isQualifyingBreakUseLog(log, data = appData) {
    if (!log) return false;
    if (log.isDistributedChild) return false;
    if (typeof isAlcoholMultiDayChildLog === 'function' && isAlcoholMultiDayChildLog(log)) return false;
    if (log.parentPercentLogId != null && log.isEstimatedDailyUse) return false;
    if (isGiftGivenLog(log) || isGiftReceivedLog(log) || isInventoryAdjustmentLog(log)) return false;
    if (isSharedUseLog(log)) {
        const personal = getLogPersonalAmount(log);
        return Number.isFinite(personal) && personal > 0;
    }
    return isPersonalUseLog(log);
}

/**
 * Break between this qualifying personal-use entry and the previous one
 * for the same substance (previous end → current start).
 * Returns null hours for first use / non-qualifying rows.
 */
function getBreakBetweenUsesDetails(entry, data = appData) {
    if (!isQualifyingBreakUseLog(entry, data)) {
        return { hours: null, minutes: null, text: '—', previous: null, previousEndedAt: null };
    }
    const substanceId = getUseSubstanceId(entry, data);
    const currentStart = typeof getUseLogStartedAt === 'function'
        ? getUseLogStartedAt(entry)
        : null;
    const currentMs = currentStart
        ? currentStart.getTime()
        : getLogDatetimeMs(entry);
    if (!currentMs) {
        return { hours: null, minutes: null, text: '—', previous: null, previousEndedAt: null };
    }

    let previous = null;
    let previousEndedAt = null;
    (typeof getUseEntries === 'function' ? getUseEntries(data) : (data.logs || [])).forEach(log => {
        if (!log || log === entry) return;
        if (entry.id != null && log.id != null && String(log.id) === String(entry.id)) return;
        if (!logMatchesSubstance(log, substanceId, data)) return;
        if (!isQualifyingBreakUseLog(log, data)) return;
        const end = typeof getUseEndDatetime === 'function'
            ? getUseEndDatetime(log)
            : (typeof getUseLogEndedAt === 'function' ? getUseLogEndedAt(log) : null);
        if (!end) return;
        const endMs = end.getTime();
        if (!(endMs < currentMs)) return;
        if (!previousEndedAt || endMs > previousEndedAt.getTime()) {
            previous = log;
            previousEndedAt = end;
        }
    });
    if (!previous || !previousEndedAt) {
        return { hours: null, minutes: null, text: '—', previous: null, previousEndedAt: null };
    }
    const breakMs = currentMs - previousEndedAt.getTime();
    if (!(breakMs >= 0)) {
        return { hours: null, minutes: null, text: '—', previous: null, previousEndedAt: null };
    }
    const hours = breakMs / 3600000;
    const minutes = Math.floor(breakMs / 60000);
    return {
        hours,
        minutes,
        text: formatBreakSincePreviousUse(hours),
        previous,
        previousEndedAt
    };
}

function computeBreakSincePreviousUseHours(entry, data = appData) {
    const details = getBreakBetweenUsesDetails(entry, data);
    return details.hours;
}

function getQualifyingUseGapTimestampMs(log) {
    if (!log) return null;
    const end = typeof getUseEndDatetime === 'function'
        ? getUseEndDatetime(log)
        : (typeof getUseLogEndedAt === 'function' ? getUseLogEndedAt(log) : null);
    if (end?.getTime && Number.isFinite(end.getTime())) return end.getTime();
    const start = typeof getUseLogStartedAt === 'function' ? getUseLogStartedAt(log) : null;
    if (start?.getTime && Number.isFinite(start.getTime())) return start.getTime();
    const ms = typeof getLogDatetimeMs === 'function' ? getLogDatetimeMs(log) : null;
    return Number.isFinite(ms) ? ms : null;
}

function computeCurrentUseGapHours(substanceId, data = appData, asOf = new Date()) {
    const asOfMs = asOf instanceof Date ? asOf.getTime() : new Date(asOf).getTime();
    if (!Number.isFinite(asOfMs)) return null;
    let latestMs = null;
    (typeof getUseEntries === 'function' ? getUseEntries(data) : (data.logs || [])).forEach(log => {
        if (!logMatchesSubstance(log, substanceId, data)) return;
        if (!isQualifyingBreakUseLog(log, data)) return;
        const ts = getQualifyingUseGapTimestampMs(log);
        if (ts == null || ts > asOfMs) return;
        if (latestMs == null || ts > latestMs) latestMs = ts;
    });
    if (latestMs == null) return null;
    const hours = (asOfMs - latestMs) / 3600000;
    return Number.isFinite(hours) && hours >= 0 ? hours : null;
}

function formatBreakSincePreviousUse(hours) {
    if (hours == null || !Number.isFinite(hours) || hours < 0) return '—';
    return formatBreakFromHours(hours);
}

function formatBreakBetweenUsesTooltip(details) {
    if (!details || details.hours == null || !details.previousEndedAt) return '';
    const prevLabel = typeof formatDatetimeLong === 'function'
        ? formatDatetimeLong(details.previousEndedAt)
        : String(details.previousEndedAt);
    const breakLabel = details.text || formatBreakSincePreviousUse(details.hours);
    return `Previous use:\n${prevLabel}\n\nBreak:\n${breakLabel}`;
}

/**
 * Shared resolver for log-level normalized metrics used by CCR and tables.
 * Duration → minutes; g/hr → grams/hour; use gaps → hours.
 */
function resolveNormalizedLogMetric(metricId, log, data = appData) {
    if (!log || !metricId) return null;
    switch (migrateCcrMetricKey(metricId)) {
        case 'sessionDuration':
        case 'duration':
            return getNormalizedSessionDurationMinutes(log);
        case 'gramsPerHour':
        case 'gPerHour':
            return getNormalizedGramsPerHour(log);
        case 'useGapPrevious':
            return computeBreakSincePreviousUseHours(log, data);
        default:
            return null;
    }
}

function applyConditionalColorToMetricHtml(html, context = {}, data = appData) {
    if (html == null) return html;
    const value = context.value;
    if (value == null || !Number.isFinite(Number(value))) return html;
    if (typeof evaluateConditionalColorRules !== 'function') return html;
    const ccr = evaluateConditionalColorRules({
        substanceId: context.substanceId,
        section: context.section || 'useHistory',
        visualTarget: context.visualTarget || 'value',
        metric: context.metric,
        value,
        log: context.log
    }, data);
    if (!ccr.matched.length) return html;
    return wrapWithConditionalColor(html, ccr, { keepLabel: true });
}

function renderNormalizedDurationDetailHtml(entry, { section = 'useHistory' } = {}) {
    const minutes = getNormalizedSessionDurationMinutes(entry);
    if (minutes == null) return '';
    const text = formatNormalizedSessionDuration(minutes);
    const colored = applyConditionalColorToMetricHtml(text, {
        substanceId: getUseSubstanceId(entry),
        section,
        metric: 'sessionDuration',
        value: minutes,
        log: entry
    });
    return `<div class="use-recent-detail">${colored}</div>`;
}

function getVapePurchaseProductName(purchase) {
    return (purchase?.notes || purchase?.store || purchase?.location || '').trim();
}

function formatVapePurchaseTitleLine(purchase) {
    const product = getVapePurchaseProductName(purchase);
    const flavor = getVapePurchaseFlavor(purchase);
    const parts = [];
    if (product) parts.push(product);
    if (flavor) parts.push(flavor);
    return parts.join(' · ') || 'Vape';
}

function formatVapePurchaseDetailLine(purchase) {
    const flavor = getVapePurchaseFlavor(purchase);
    const full = getVapeFullPuffCount(purchase);
    const nic = getVapeNicotineMgPerMl(purchase);
    const parts = [];
    if (flavor) parts.push(flavor);
    if (full > 0) parts.push(`${formatAmount(full)} puffs`);
    if (nic != null) parts.push(`${formatAmount(nic)} mg/mL`);
    return parts.join(' · ');
}

function getVapePurchaseDeviceCount(purchase, data = appData) {
    const raw = purchase?.vapeDeviceCount ?? purchase?.productCount ?? purchase?.deviceCount;
    const count = parseFloat(raw);
    if (Number.isFinite(count) && count > 0) return count;
    if (isVapePuffPurchase(purchase, data) || isNicotineVapeProduct(purchase, data)) return 1;
    return null;
}

function formatVapePurchaseQuantitySummary(purchase, data = appData) {
    const full = getVapeFullPuffCount(purchase);
    const puffPart = full > 0 ? formatAmountWithUnit(full, 'puffs') : '';
    const deviceCount = getVapePurchaseDeviceCount(purchase, data);
    if (deviceCount != null && deviceCount > 0 && puffPart) {
        const deviceLabel = deviceCount === 1 ? 'vape' : 'vapes';
        return `${formatAmount(deviceCount)} ${deviceLabel} · ${puffPart}`;
    }
    if (puffPart) return puffPart;
    if (deviceCount != null && deviceCount > 0) {
        return deviceCount === 1 ? '1 vape' : `${formatAmount(deviceCount)} vapes`;
    }
    return '—';
}

function formatNicotinePurchaseQuantitySummary(purchase, data = appData) {
    const type = getNicotineProductType(purchase, data);
    if (type === 'vape') return formatVapePurchaseQuantitySummary(purchase, data);
    if (type === 'cigarettes') {
        const total = purchase.totalCigarettes ?? getPurchaseQuantityBought(purchase);
        return `${formatAmount(total)} cigarettes`;
    }
    if (type === 'pouches') {
        return `${formatAmount(purchase.totalPouches ?? getPurchaseQuantityBought(purchase))} pouches`;
    }
    if (type === 'gum') {
        return `${formatAmount(purchase.pieceCount ?? getPurchaseQuantityBought(purchase))} pieces`;
    }
    if (type === 'patches') {
        return `${formatAmount(purchase.patchCount ?? getPurchaseQuantityBought(purchase))} patches`;
    }
    const qty = getPurchaseQuantityBought(purchase);
    const unit = purchase.unit || 'units';
    return `${formatAmount(qty)} ${unit}`;
}

function getPurchaseHistoryCostPerUnit(purchase, totalNum) {
    const total = Number.isFinite(totalNum) ? totalNum : (parseFloat(getPurchaseTotalCost(purchase)) || 0);
    if (isVapePuffPurchase(purchase)) {
        const devices = getVapePurchaseDeviceCount(purchase) || 1;
        return devices > 0 ? total / devices : total;
    }
    const stored = parseFloat(purchase?.costPerUnit);
    if (Number.isFinite(stored) && stored > 0) return stored;
    const qtyNum = parseFloat(getPurchaseQuantity(purchase)) || 0;
    return qtyNum > 0 ? total / qtyNum : 0;
}

function getPurchaseHistoryCostPerUnitSuffix(purchase) {
    if (isVapePuffPurchase(purchase)) return 'vape';
    if (isNicotinePurchase(purchase)) {
        const type = getNicotineProductType(purchase);
        if (type === 'cigarettes') return 'cigarette';
        if (type === 'pouches') return 'pouch';
        if (type === 'gum') return 'piece';
        if (type === 'patches') return 'patch';
    }
    return 'u';
}

function syncVapePurchaseCostPerUnit(purchase) {
    if (!isVapePuffPurchase(purchase)) return;
    const total = parseFloat(getPurchaseTotalCost(purchase)) || 0;
    const devices = getVapePurchaseDeviceCount(purchase) || 1;
    purchase.costPerUnit = devices > 0 ? total / devices : total;
}

function parseVapeFlavorFromForm() {
    return document.getElementById('buy-vape-flavor')?.value?.trim() || '';
}

function getVapePercentBoughtAt(purchase) {
    if (!purchase) return 100;
    const pct = parseFloat(purchase.startingPercent ?? purchase.remainingPercent ?? purchase.percentBoughtAt);
    return Number.isFinite(pct) ? Math.max(0, Math.min(100, pct)) : 100;
}

function computeVapeStartingPuffsFromForm(fullCount, percentBoughtAt) {
    const full = Math.max(0, parseFloat(fullCount) || 0);
    const pct = Math.max(0, Math.min(100, parseFloat(percentBoughtAt) || 100));
    return Math.max(0, full * (pct / 100));
}

function getVapeStartingPuffsLeft(purchase) {
    if (!purchase) return 0;
    if (purchase.startingPuffsLeft != null && purchase.startingPuffsLeft !== '') {
        return Math.max(0, parseFloat(purchase.startingPuffsLeft) || 0);
    }
    return computeVapeStartingPuffsFromForm(getVapeFullPuffCount(purchase), getVapePercentBoughtAt(purchase));
}

function normalizeVapePurchaseFields(purchase) {
    if (!isVapePuffPurchase(purchase)) return;
    const full = getVapeFullPuffCount(purchase);
    const giftReceivedUnknownFullCount = purchase.acquisitionType === 'gift_received' && full <= 0;
    if (full > 0) {
        purchase.fullPuffCount = full;
        purchase.quantityBought = full;
        purchase.quantity = full;
    }
    if (purchase.percentBoughtAt == null || purchase.percentBoughtAt === '') {
        purchase.percentBoughtAt = purchase.startingPercent ?? purchase.remainingPercent ?? 100;
    }
    if (purchase.startingPercent == null) purchase.startingPercent = purchase.percentBoughtAt;
    if (purchase.remainingPercent == null) purchase.remainingPercent = purchase.percentBoughtAt;
    if (giftReceivedUnknownFullCount) {
        purchase.fullPuffCount = null;
        purchase.quantityBought = purchase.quantityBought > 0 ? purchase.quantityBought : null;
        purchase.quantity = purchase.quantity > 0 ? purchase.quantity : null;
        purchase.startingPuffsLeft = null;
        purchase.remainingPuffs = null;
        purchase.remainingAmount = null;
    } else {
        purchase.startingPuffsLeft = getVapeStartingPuffsLeft(purchase);
        if (purchase.remainingPuffs == null || purchase.remainingPuffs === '') {
            purchase.remainingPuffs = getPurchaseRemainingAmount(purchase);
        }
    }
    syncVapeNicotineFields(purchase);
    syncVapePurchaseCostPerUnit(purchase);
}

function getVapeELiquidCapacityMl(purchase) {
    const ml = parseFloat(purchase?.eLiquidCapacityMl);
    return Number.isFinite(ml) && ml > 0 ? ml : null;
}

function getVapeNicotineMgPerMl(purchase) {
    const mg = parseFloat(purchase?.nicotineMgPerMl);
    return Number.isFinite(mg) && mg > 0 ? mg : null;
}

function computeVapeTotalNicotineMg(capacityMl, nicotineMgPerMl) {
    const cap = parseFloat(capacityMl);
    const strength = parseFloat(nicotineMgPerMl);
    if (!Number.isFinite(cap) || !Number.isFinite(strength) || cap <= 0 || strength <= 0) return null;
    return cap * strength;
}

function getVapeTotalNicotineMg(purchase) {
    if (!purchase) return null;
    if (purchase.totalNicotineMg != null && purchase.totalNicotineMg !== '') {
        const stored = parseFloat(purchase.totalNicotineMg);
        if (Number.isFinite(stored) && stored > 0) return stored;
    }
    return computeVapeTotalNicotineMg(getVapeELiquidCapacityMl(purchase), getVapeNicotineMgPerMl(purchase));
}

function syncVapeNicotineFields(purchase) {
    if (!isVapePuffPurchase(purchase)) return;
    const cap = getVapeELiquidCapacityMl(purchase);
    const strength = getVapeNicotineMgPerMl(purchase);
    const total = computeVapeTotalNicotineMg(cap, strength);
    if (total != null) {
        purchase.totalNicotineMg = total;
    } else {
        delete purchase.totalNicotineMg;
    }
}

function getVapeNicotineUsedMg(purchase) {
    const total = getVapeTotalNicotineMg(purchase);
    const full = getVapeFullPuffCount(purchase);
    if (!total || full <= 0) return null;
    const starting = getVapeStartingPuffsLeft(purchase);
    const remaining = getPurchaseRemainingAmount(purchase);
    const puffsUsed = Math.max(0, starting - remaining);
    return total * (puffsUsed / full);
}

function getVapeNicotineLeftMg(purchase) {
    const total = getVapeTotalNicotineMg(purchase);
    const full = getVapeFullPuffCount(purchase);
    if (!total || full <= 0) return null;
    const remaining = getPurchaseRemainingAmount(purchase);
    return total * (remaining / full);
}

function getVapeNicotineMetrics(purchase, asOfMs = Date.now()) {
    const totalNicotineMg = getVapeTotalNicotineMg(purchase);
    if (totalNicotineMg == null) return null;
    const nicotineUsedMg = getVapeNicotineUsedMg(purchase);
    const nicotineLeftMg = getVapeNicotineLeftMg(purchase);
    const durationMs = getVapePurchaseSupplyDurationMs(purchase, asOfMs);
    const durationDays = durationMs != null ? durationMs / 86400000 : null;
    return {
        eLiquidCapacityMl: getVapeELiquidCapacityMl(purchase),
        nicotineMgPerMl: getVapeNicotineMgPerMl(purchase),
        totalNicotineMg,
        nicotineUsedMg,
        nicotineLeftMg,
        avgNicotineMgPerDay: durationDays != null && durationDays >= 1 && nicotineUsedMg != null
            ? nicotineUsedMg / durationDays
            : null
    };
}

function parseVapeNicotineFieldsFromForm() {
    const capRaw = parseFloat(document.getElementById('buy-eliquid-capacity')?.value);
    const nicRaw = parseFloat(document.getElementById('buy-nicotine-strength')?.value);
    const eLiquidCapacityMl = Number.isFinite(capRaw) && capRaw > 0 ? capRaw : null;
    const nicotineMgPerMl = Number.isFinite(nicRaw) && nicRaw > 0 ? nicRaw : null;
    const totalNicotineMg = computeVapeTotalNicotineMg(eLiquidCapacityMl, nicotineMgPerMl);
    return { eLiquidCapacityMl, nicotineMgPerMl, totalNicotineMg };
}

function isVapeUseLog(log, data = appData) {
    const tx = getLogTransactionType(log);
    if (tx !== 'use' && tx !== 'shared_use' && tx !== 'gift_given' && tx !== 'inventory_adjustment') return false;
    const substanceId = getUseSubstanceId(log);
    if (isNicotineTrackingMode(substanceId, data) && getNicotineProductType(log, data) !== 'vape') return false;
    if (!isVapeTrackingMode(substanceId, data, log)) return false;
    return log.logMode === 'vape_puffs'
        || log.logMode === 'percent_remaining'
        || log.trackingMode === 'vape'
        || isVapePuffUnit(log.unit)
        || log.percentLeftAfter != null
        || log.percentRemaining != null;
}

function shouldShowUseCountForSubstance(substanceId, data = appData) {
    return Boolean(getSubstanceSecondaryCountLabel(substanceId, data));
}

function getPurchaseDatetimeIso(purchase) {
    const dt = parseLocalDateTime(purchase?.date, purchase?.time || '12:00');
    return dt && !Number.isNaN(dt.getTime()) ? dt.toISOString() : new Date().toISOString();
}

function getVapeLogUseDate(log) {
    if (!log?.date) return null;
    const day = parseLocalDate(log.date);
    return day && !Number.isNaN(day.getTime()) ? day : null;
}

function getVapePurchaseUseLogs(purchase, data = appData) {
    return getLogsForPurchase(purchase.id, data)
        .filter(l => isPersonalUseLog(l) && isVapeUseLog(l, data))
        .filter(l => !isPercentLeftDistributedChildLog(l))
        .sort((a, b) => getVapeLogSortMs(a) - getVapeLogSortMs(b));
}

function formatVapeDuration(ms) {
    if (ms == null || ms < 0 || Number.isNaN(ms)) return '—';
    const days = Math.floor(ms / 86400000);
    const hours = Math.floor((ms % 86400000) / 3600000);
    const minutes = Math.floor((ms % 3600000) / 60000);
    if (days >= 1) return `${days} day${days === 1 ? '' : 's'} ${hours} hr${hours === 1 ? '' : 's'}`;
    return `${hours} hr${hours === 1 ? '' : 's'} ${minutes} min${minutes === 1 ? '' : 's'}`;
}

function countInclusiveCalendarDays(startDate, endDate) {
    const start = typeof startDate === 'string' ? parseLocalDate(startDate) : startDate;
    const end = typeof endDate === 'string' ? parseLocalDate(endDate) : endDate;
    if (!start || !end || Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) return null;
    const ms = end.getTime() - start.getTime();
    if (ms < 0) return null;
    return Math.max(1, Math.round(ms / 86400000) + 1);
}

function parsePurchaseStartedAt(purchase, data = appData) {
    if (isVapePuffPurchase(purchase, data)) {
        return getVapePurchaseSupplyStartAt(purchase, data);
    }
    if (purchase?.startedAt) {
        const d = new Date(purchase.startedAt);
        if (!Number.isNaN(d.getTime())) return d;
    }
    if (purchase?.supplyStartedAt) {
        const d = new Date(purchase.supplyStartedAt);
        if (!Number.isNaN(d.getTime())) return d;
    }
    return parseLocalDateTime(purchase?.date, purchase?.time || '12:00');
}

function getVapePurchaseExplicitStartAt(purchase) {
    for (const raw of [purchase?.startedAt, purchase?.supplyStartedAt]) {
        if (!raw) continue;
        const d = new Date(raw);
        if (!Number.isNaN(d.getTime())) return d;
    }
    return null;
}

function getVapeLogActivityTimestamp(log) {
    const ended = getUseLogEndedAt(log);
    if (ended && !Number.isNaN(ended.getTime())) return ended;
    const started = getUseLogStartedAt(log);
    if (started && !Number.isNaN(started.getTime())) return started;
    return getVapeLogUseDate(log);
}

function getVapePurchaseSupplyStartAt(purchase, data = appData) {
    const explicit = getVapePurchaseExplicitStartAt(purchase);
    if (explicit) return explicit;

    const purchaseDt = parseLocalDateTime(purchase?.date, purchase?.time || '12:00');
    if (purchaseDt && !Number.isNaN(purchaseDt.getTime())) return purchaseDt;

    const logs = getVapePurchaseUseLogs(purchase, data);
    if (!logs.length) return null;
    const firstTs = getVapeLogActivityTimestamp(logs[0]);
    return firstTs && !Number.isNaN(firstTs.getTime()) ? firstTs : null;
}

function getVapeDepletionTimestampFromLogs(purchase, data = appData) {
    const logs = getVapePurchaseUseLogs(purchase, data);
    if (!logs.length) return null;
    let remaining = getVapeStartingPuffsLeft(purchase);
    for (const log of logs) {
        const before = remaining;
        remaining = applyVapeLogToRemaining(purchase, remaining, log);
        if (before > INVENTORY_EPS && remaining <= INVENTORY_EPS) {
            const ts = getVapeLogActivityTimestamp(log);
            if (ts && !Number.isNaN(ts.getTime())) return ts;
        }
    }
    return null;
}

function getVapePurchaseSupplyEndAt(purchase, asOfMs = Date.now(), data = appData) {
    const depleted = purchase.isDepleted || getPurchaseRemainingAmount(purchase) <= INVENTORY_EPS;
    if (!depleted) return new Date(asOfMs);

    for (const raw of [purchase?.depletedAt, purchase?.finishedAt]) {
        if (!raw) continue;
        const d = new Date(raw);
        if (!Number.isNaN(d.getTime())) return d;
    }

    const depletionTs = getVapeDepletionTimestampFromLogs(purchase, data);
    if (depletionTs) return depletionTs;

    const logs = getVapePurchaseUseLogs(purchase, data);
    if (logs.length) {
        const lastTs = getVapeLogActivityTimestamp(logs[logs.length - 1]);
        if (lastTs && !Number.isNaN(lastTs.getTime())) return lastTs;
    }

    return new Date(asOfMs);
}

function formatVapeSupplyDurationSpan(ms, { depleted = false } = {}) {
    if (ms == null || ms < 0 || Number.isNaN(ms)) return 'Not started';
    const days = Math.floor(ms / 86400000);
    const hours = Math.floor((ms % 86400000) / 3600000);
    const prefix = depleted ? 'Lasted' : 'Used for';
    const suffix = depleted ? '' : ' so far';
    if (days >= 1) {
        if (hours > 0) {
            return `${prefix} ${days} day${days === 1 ? '' : 's'} ${hours} hour${hours === 1 ? '' : 's'}${suffix}`;
        }
        return `${prefix} ${days} day${days === 1 ? '' : 's'}${suffix}`;
    }
    if (hours >= 1) {
        return `${prefix} ${hours} hour${hours === 1 ? '' : 's'}${suffix}`;
    }
    const minutes = Math.floor((ms % 3600000) / 60000);
    if (minutes >= 1) {
        return `${prefix} ${minutes} minute${minutes === 1 ? '' : 's'}${suffix}`;
    }
    return `${prefix} less than 1 minute${suffix}`;
}

function getVapeDerivedFinishedAt(purchase, data = appData) {
    if (!isVapePuffPurchase(purchase, data)) return null;
    const depleted = purchase.isDepleted || getPurchaseRemainingAmount(purchase) <= INVENTORY_EPS;
    if (!depleted) return null;
    return getVapePurchaseSupplyEndAt(purchase, Date.now(), data);
}

function formatVapeSupplyDurationLabel(purchase, durationMs, data = appData) {
    const depleted = purchase.isDepleted || getPurchaseRemainingAmount(purchase) <= INVENTORY_EPS;
    return formatVapeSupplyDurationSpan(durationMs, { depleted });
}

function ensureVapePurchaseStartedAt(purchase, logEntry = null) {
    // Vape supply start is derived from explicit start, purchase date, or earliest linked log.
}

function getVapePurchaseLifecycleMetrics(purchase, asOfMs = Date.now(), data = appData) {
    if (!isVapePuffPurchase(purchase, data)) return null;
    const starting = getVapeStartingPuffsLeft(purchase);
    const remaining = getPurchaseRemainingAmount(purchase);
    const totalUsed = Math.max(0, starting - remaining);
    const logs = getVapePurchaseUseLogs(purchase, data);
    const firstLog = logs[0] || null;
    const lastLog = logs[logs.length - 1] || null;
    const firstUseAt = firstLog ? getVapeLogActivityTimestamp(firstLog) : null;
    const lastUseAt = lastLog ? getVapeLogActivityTimestamp(lastLog) : null;
    const started = getVapePurchaseSupplyStartAt(purchase, data);
    const depleted = purchase.isDepleted || remaining <= INVENTORY_EPS;
    const finished = depleted ? getVapePurchaseSupplyEndAt(purchase, asOfMs, data) : null;
    const durationMs = getVapePurchaseSupplyDurationMs(purchase, asOfMs, data);
    const durationDays = durationMs != null ? durationMs / 86400000 : null;
    const durationLabel = started
        ? formatVapeSupplyDurationLabel(purchase, durationMs, data)
        : 'Not started';
    return {
        started,
        firstUseAt,
        lastUseAt,
        finished: depleted ? finished : null,
        durationMs,
        durationLabel,
        totalUsed,
        isFinished: depleted,
        avgPuffsPerDay: durationDays != null && durationDays >= 1 ? totalUsed / durationDays : null,
        avgPuffsPerHour: durationMs != null && durationDays != null && durationDays < 2 && durationMs > 0
            ? totalUsed / (durationMs / 3600000)
            : null,
        nicotine: getVapeNicotineMetrics(purchase, asOfMs)
    };
}

function getPurchaseStartedAtMs(purchase, data = appData) {
    if (isVapePuffPurchase(purchase, data)) {
        const started = getVapePurchaseSupplyStartAt(purchase, data);
        return started && !Number.isNaN(started.getTime()) ? started.getTime() : null;
    }
    const started = parsePurchaseStartedAt(purchase, data);
    if (started && !Number.isNaN(started.getTime())) return started.getTime();
    return getPurchaseDatetimeMs(purchase);
}

function getVapePurchaseSupplyDurationMs(purchase, asOfMs = Date.now(), data = appData) {
    const start = getVapePurchaseSupplyStartAt(purchase, data);
    if (!start || Number.isNaN(start.getTime())) return null;
    const end = getVapePurchaseSupplyEndAt(purchase, asOfMs, data);
    if (!end || Number.isNaN(end.getTime())) return null;
    const ms = end.getTime() - start.getTime();
    return ms >= 0 ? ms : null;
}

function shouldDistributeVapeLogForStats(log, data = appData) {
    if (!isVapeUseLog(log, data) || !isPersonalUseLog(log) || log.needsReview) return false;
    return getVapeTaperCountMode(data) === 'spread-across-days';
}

function distributeAmountOverTimeInterval(amount, startDt, endDt) {
    if (!Number.isFinite(amount) || amount <= 0) return [];
    const startMs = startDt?.getTime();
    const endMs = endDt?.getTime();
    if (startMs == null || endMs == null || Number.isNaN(startMs) || Number.isNaN(endMs)) {
        const fallbackDt = endDt && !Number.isNaN(endDt.getTime())
            ? endDt
            : (startDt && !Number.isNaN(startDt.getTime()) ? startDt : null);
        return fallbackDt ? [{ date: getLocalDateString(fallbackDt), amount }] : [];
    }
    if (endMs <= startMs) {
        return [{ date: getLocalDateString(startDt), amount }];
    }
    const totalMs = endMs - startMs;
    const allocations = new Map();
    let cursor = parseLocalDate(getLocalDateString(startDt));
    const endDate = parseLocalDate(getLocalDateString(endDt));
    while (cursor && endDate && cursor <= endDate) {
        const dateStr = getLocalDateString(cursor);
        const bounds = getLocalDayBoundaryMs(dateStr);
        if (bounds) {
            const overlapStart = Math.max(startMs, bounds.startMs);
            const overlapEnd = Math.min(endMs, bounds.endMs);
            if (overlapEnd > overlapStart) {
                const portion = amount * ((overlapEnd - overlapStart) / totalMs);
                if (portion > 0) allocations.set(dateStr, (allocations.get(dateStr) || 0) + portion);
            }
        }
        cursor.setDate(cursor.getDate() + 1);
    }
    const entries = [...allocations.entries()].map(([date, amt]) => ({ date, amount: amt }));
    const sum = entries.reduce((s, e) => s + e.amount, 0);
    if (entries.length && Math.abs(sum - amount) > 0.001) {
        entries[entries.length - 1].amount += amount - sum;
    }
    return entries;
}

function getVapeLogPuffAmount(log) {
    if (isSharedUseLog(log)) return getLogPersonalAmount(log);
    return parseFloat(log.estimatedPuffsUsed ?? log.amount) || 0;
}

function getVapeLogStatsAllocations(log, data = appData) {
    const amount = getVapeLogPuffAmount(log);
    if (amount <= INVENTORY_EPS) return [];

    if (isPercentLeftDistributedChildLog(log)) {
        return log.date ? [{ date: log.date, amount }] : [];
    }

    if (isPercentLeftCheckpointLog(log) && log.excludeFromStats && getSpreadPercentLeftUsage(data)) {
        const children = getDistributedChildrenForPercentLog(log.id, data);
        if (children.length) return [];
    }

    if (isVapeDateOnlyUseLog(log, data)) {
        return log.date ? [{ date: log.date, amount }] : [];
    }
    if (!shouldDistributeVapeLogForStats(log)) {
        return log.date ? [{ date: log.date, amount }] : [];
    }

    const startedAt = getUseLogStartedAt(log);
    const endedAt = getUseLogEndedAt(log);
    const durationMs = getVapeLogDurationMs(log);

    if (startedAt && endedAt && endedAt > startedAt) {
        return distributeAmountOverTimeInterval(amount, startedAt, endedAt);
    }
    if (startedAt && durationMs != null && durationMs <= 0) {
        return [{ date: getLocalDateString(startedAt), amount }];
    }
    if (startedAt && !endedAt) {
        return [{ date: getLocalDateString(startedAt), amount }];
    }

    const purchase = findPurchaseInData(getLogPurchaseId(log), data);
    if (purchase) {
        const supplyStart = parsePurchaseStartedAt(purchase, data);
        const logEnd = endedAt || parseUseDateTime(log.date, log.endTime || log.startTime || log.time);
        if (supplyStart && logEnd && logEnd > supplyStart) {
            return distributeAmountOverTimeInterval(amount, supplyStart, logEnd);
        }
    }
    if (log.date) return [{ date: log.date, amount }];
    if (startedAt) return [{ date: getLocalDateString(startedAt), amount }];
    return [];
}

function getVapeDistributedUsageMap(substanceId, data = appData) {
    const map = new Map();
    getUseLogsForSubstance(substanceId, { data }).forEach(log => {
        if (!isVapeUseLog(log)) return;
        if (!logCountsTowardPersonalUseStats(log)) return;
        getVapeLogStatsAllocations(log, data).forEach(({ date, amount }) => {
            map.set(date, (map.get(date) || 0) + amount);
        });
    });
    return map;
}

function getStatsUsageInRange(substanceId, startDate, endDate, data = appData) {
    if (!isVapeNicotineSubstanceId(substanceId, data)) {
        return sumUseAmountForRange(substanceId, startDate, endDate, null, data);
    }
    let total = 0;
    getVapeDistributedUsageMap(substanceId, data).forEach((amount, date) => {
        if (startDate && date < startDate) return;
        if (endDate && date > endDate) return;
        total += amount;
    });
    getUseLogsForSubstance(substanceId, { data }).forEach(log => {
        if (!logCountsTowardPersonalUseStats(log)) return;
        if (isVapeUseLog(log, data)) return;
        const logDate = log.date || '';
        if (startDate && logDate < startDate) return;
        if (endDate && logDate > endDate) return;
        total += getLogStatsAmount(log);
    });
    return total;
}

function getStatsUsageOnDate(substanceId, dateStr, data = appData) {
    if (!isVapeNicotineSubstanceId(substanceId, data)) {
        return getUsedAmount(substanceId, dateStr, null, data);
    }
    let total = getVapeDistributedUsageMap(substanceId, data).get(dateStr) || 0;
    getUseLogsForSubstance(substanceId, { data }).forEach(log => {
        if (!logCountsTowardPersonalUseStats(log)) return;
        if (isVapeUseLog(log, data)) return;
        if ((log.date || '') === dateStr) total += getLogStatsAmount(log);
    });
    return total;
}

function getStatsMonthUsageTotal(substanceId, dateStr = getLocalDateString(), data = appData) {
    const monthStart = getMonthStartDateStr(dateStr);
    return getStatsUsageInRange(substanceId, monthStart, dateStr, data);
}

function getVapePurchaseBreakHoursList(substanceId, startDate = null, endDate = null, data = appData) {
    const purchases = getPurchasesForSubstance(substanceId, data).filter(isVapePuffPurchase);
    const gaps = [];
    for (let i = 1; i < purchases.length; i++) {
        const prevMs = getPurchaseStartedAtMs(purchases[i - 1]);
        const curMs = getPurchaseStartedAtMs(purchases[i]);
        const curDate = purchases[i].date;
        if (!prevMs || !curMs || curMs <= prevMs) continue;
        if (startDate && curDate < startDate) continue;
        if (endDate && curDate > endDate) continue;
        gaps.push((curMs - prevMs) / 3600000);
    }
    return gaps;
}

function getVapeFinishedSupplyDurationsInRange(substanceId, startDate, endDate, data = appData) {
    return getPurchasesForSubstance(substanceId, data)
        .filter(p => isVapePuffPurchase(p) && (p.isDepleted || getPurchaseRemainingAmount(p) <= INVENTORY_EPS))
        .filter(p => {
            const finished = getVapeDerivedFinishedAt(p, data);
            if (!finished) return false;
            const finishDate = getLocalDateString(finished);
            return finishDate >= startDate && finishDate <= endDate;
        })
        .map(p => getVapePurchaseSupplyDurationMs(p, Date.now(), data))
        .filter(ms => ms != null && ms >= 0);
}

function getVapeCurrentSupplyDurationMs(substanceId) {
    const active = getActivePurchasesForSubstance(substanceId).filter(isVapePuffPurchase);
    if (!active.length) return null;
    const latest = active.sort((a, b) => getPurchaseStartedAtMs(b) - getPurchaseStartedAtMs(a))[0];
    return getVapePurchaseSupplyDurationMs(latest);
}

function formatStatsBreakValue(hours, substanceId) {
    if (hours == null || Number.isNaN(hours)) return '—';
    if (isVapeNicotineSubstanceId(substanceId)) return formatBreakFromHours(hours);
    return formatDurationHMS(hours);
}

function applyCcrToInsightsMetricCell(displayHtml, {
    substanceId,
    metric,
    value,
    section = 'insights'
} = {}) {
    if (value == null || !Number.isFinite(Number(value))) return displayHtml;
    return applyConditionalColorToMetricHtml(displayHtml, {
        substanceId,
        section,
        metric,
        value
    });
}

function formatInsightsDurationCell(hours, substanceId, section = 'insights') {
    const display = formatStatsDurationValue(hours, substanceId);
    if (hours == null || !Number.isFinite(hours) || !(hours > 0)) return display;
    return applyCcrToInsightsMetricCell(display, {
        substanceId,
        metric: 'sessionDuration',
        value: hours * 60,
        section
    });
}

function formatInsightsGramsPerHourCell(rate, unit, substanceId, section = 'insights') {
    const display = fmtSheetRate(rate, unit, '/hr');
    if (rate == null || !Number.isFinite(rate)) return display;
    return applyCcrToInsightsMetricCell(display, {
        substanceId,
        metric: 'gramsPerHour',
        value: rate,
        section
    });
}

function formatInsightsBreakCell(hours, substanceId, section = 'insights') {
    const display = formatStatsBreakValue(hours, substanceId);
    if (hours == null || !Number.isFinite(hours)) return display;
    return applyCcrToInsightsMetricCell(display, {
        substanceId,
        metric: 'useGapPrevious',
        value: hours,
        section
    });
}

function formatStatsDurationValue(hours, substanceId, { soFar = false } = {}) {
    if (hours == null || Number.isNaN(hours)) return '—';
    if (isWeedTrackingMode(substanceId)) return '—';
    if (isVapeNicotineSubstanceId(substanceId)) {
        const label = formatVapeDuration(hours * 3600000);
        return soFar ? `${label} so far` : label;
    }
    return formatDurationHMS(hours);
}

function getUseStatsCatalogForSubstance(substanceId) {
    if (isVapeNicotineSubstanceId(substanceId)) {
        return [...USE_STATS_VAPE_DEFAULTS.order];
    }
    if (isWeedTrackingMode(substanceId)) {
        return USE_STATS_DEFAULTS.order.filter(id =>
            !VAPE_ONLY_USE_STAT_IDS.includes(id) && !WEED_EXCLUDED_USE_STAT_IDS.has(id)
        );
    }
    return USE_STATS_DEFAULTS.order.filter(id => !VAPE_ONLY_USE_STAT_IDS.includes(id));
}

function getUseStatLabelForSubstance(statId, substanceId, unit) {
    if (isVapeNicotineSubstanceId(substanceId)) {
        if (statId === 'totalUsage') return 'Total puffs';
        if (statId === 'sessionCount') return 'Entries';
        if (statId === 'avgPuffsPerSession') return 'Avg puffs/log';
        return USE_STATS_LABELS[statId] || statId;
    }
    if (isWeedTrackingMode(substanceId) && statId === 'sessionCount') return 'Entries';
    if (statId === 'avgPerUseDay') return `Avg ${unit} / Use Day`;
    if (statId === 'avgPerCalendarDay') return `Avg ${unit} / Calendar Day`;
    return USE_STATS_LABELS[statId] || statId;
}

function getVisibleUseStatsOrderForSubstance(substanceId) {
    const layout = getUseStatsLayout(substanceId);
    const excluded = getExcludedStatIdsForSubstance(substanceId);
    const visible = layout.order.filter(id => layout.enabled.includes(id) && !excluded.has(id));
    if (visible.length) return visible;
    return layoutFromDefaults(substanceId).enabled.filter(id => !excluded.has(id));
}

function reconcileVapePurchaseLifecycle(purchase, data = appData) {
    if (!isVapePuffPurchase(purchase)) return;
    recalculateVapePurchaseInventory(purchase.id, data);
}

function isPercentBasedVapeLog(log) {
    if (!log || log.needsReview) return false;
    if (log.estimatedFromPercent || log.isEstimated) return true;
    return log.logMode === 'percent_remaining';
}

function applyVapeLogToRemaining(purchase, previousRemaining, log) {
    const fullPuffs = getVapeFullPuffCount(purchase);
    if (log.needsReview) return previousRemaining;
    if (isPercentBasedVapeLog(log)) {
        const pct = log.percentLeftAfter ?? log.percentRemaining;
        if (pct != null && Number.isFinite(parseFloat(pct))) {
            return Math.round(Math.max(0, Math.min(fullPuffs, fullPuffs * (parseFloat(pct) / 100))));
        }
    }
    const used = getVapeLogInventoryPuffAmount(log);
    return Math.max(0, Math.min(fullPuffs, previousRemaining - used));
}

function getVapeLogInventoryPuffAmount(log) {
    if (isSharedUseLog(log)) return getLogTotalAmount(log);
    return parseFloat(log.estimatedPuffsUsed ?? log.amount) || 0;
}

function getVapeLogEndMs(log) {
    if (isVapeDateOnlyUseLog(log)) {
        const day = getVapeLogUseDate(log);
        if (day) return day.getTime() + 86400000 - 1;
    }
    const ended = getUseLogEndedAt(log);
    if (ended) return ended.getTime();
    return getLogDatetimeMs(log);
}

function getVapeLogSortMs(log) {
    const day = getVapeLogUseDate(log);
    if (day) return day.getTime() + 12 * 3600000;
    const started = getUseLogStartedAt(log);
    if (started && !Number.isNaN(started.getTime())) return started.getTime();
    return getLogDatetimeMs(log);
}

function getVapeLogDurationMs(log) {
    if (log?.durationMs != null && log.durationMs > 0) return log.durationMs;
    const started = getUseLogStartedAt(log);
    const ended = getUseLogEndedAt(log);
    if (started && ended && ended > started) return ended.getTime() - started.getTime();
    return null;
}

function getVapePurchasesForSubstance(substanceId, data = appData, { sortAsc = true } = {}) {
    return getPurchasesForSubstance(substanceId, data, { sortAsc })
        .filter(p => isVapePuffPurchase(p, data));
}

function findVapePurchaseForLogDatetime(substanceId, logMs, data = appData) {
    const purchases = getVapePurchasesForSubstance(substanceId, data);
    if (!purchases.length || logMs == null || Number.isNaN(logMs)) return null;
    for (let i = 0; i < purchases.length; i++) {
        const purchaseMs = getPurchaseDatetimeMs(purchases[i]);
        const nextMs = purchases[i + 1] ? getPurchaseDatetimeMs(purchases[i + 1]) : null;
        if (logMs >= purchaseMs && (nextMs == null || logMs < nextMs)) {
            return purchases[i];
        }
    }
    return null;
}

function findVapePurchaseForLogDate(substanceId, logDateStr, data = appData) {
    if (!logDateStr) return null;
    const logDay = parseLocalDate(logDateStr);
    if (!logDay) return null;
    return findVapePurchaseForLogDatetime(substanceId, logDay.getTime(), data);
}

function inferVapeInventoryIdForLog(log, data = appData) {
    if (getLogPurchaseId(log)) return getLogPurchaseId(log);
    if (!isVapeUseLog(log, data)) return null;
    const substanceId = getUseSubstanceId(log);
    if (isVapeDateOnlyUseLog(log, data) && log.date) {
        const purchase = findVapePurchaseForLogDate(substanceId, log.date, data);
        return purchase?.id ?? null;
    }
    const started = getUseLogStartedAt(log);
    const logMs = started && !Number.isNaN(started.getTime())
        ? started.getTime()
        : (parseLocalDate(log.date)?.getTime() ?? null);
    const purchase = findVapePurchaseForLogDatetime(substanceId, logMs, data);
    return purchase?.id ?? null;
}

function syncVapePurchaseSupplyStartedAt(purchase, logs, data = appData) {
    // Vape supply start/end are derived from linked use logs at display time.
}

function getVapeRemainingBeforeLog(purchase, logDate, data = appData, excludeLogId = null) {
    let remaining = getVapeStartingPuffsLeft(purchase);
    const logs = getLogsForPurchase(purchase.id, data)
        .filter(l => logAffectsInventoryDeduction(l) && isVapeUseLog(l, data) && !l.needsReview)
        .filter(l => !isPercentLeftDistributedChildLog(l))
        .filter(l => excludeLogId == null || String(l.id) !== String(excludeLogId))
        .filter(l => (l.date || '') <= (logDate || ''))
        .sort((a, b) => {
            const dateCmp = (a.date || '').localeCompare(b.date || '');
            if (dateCmp !== 0) return dateCmp;
            return String(a.id).localeCompare(String(b.id));
        });
    logs.forEach(log => {
        remaining = applyVapeLogToRemaining(purchase, remaining, log);
    });
    return remaining;
}

function recalculateVapePurchaseInventory(purchaseId, data = appData, options = {}) {
    const purchase = findPurchaseInData(purchaseId, data);
    if (!purchase || !isVapePuffPurchase(purchase)) return;
    normalizeVapePurchaseFields(purchase);
    if (isGiftReceivedVapeWithoutKnownPuffCount(purchase)) {
        const pct = getVapePercentBoughtAt(purchase);
        purchase.remainingAmount = null;
        purchase.remainingPuffs = null;
        purchase.isDepleted = pct <= 0;
        purchase.inventoryStatus = purchase.isDepleted ? 'depleted' : 'active';
        purchase.depletedAt = purchase.isDepleted ? (purchase.depletedAt || new Date().toISOString()) : null;
        purchase.updatedAt = new Date().toISOString();
        return;
    }
    const { excludeLogId = null, skipPercentSpread = false } = options;
    const fullPuffs = getVapeFullPuffCount(purchase);
    const startingPuffs = getVapeStartingPuffsLeft(purchase);
    const logs = getLogsForPurchase(purchaseId, data)
        .filter(l => logAffectsInventoryDeduction(l) && isVapeUseLog(l, data) && !l.needsReview)
        .filter(l => !isPercentLeftDistributedChildLog(l))
        .filter(l => excludeLogId == null || String(l.id) !== String(excludeLogId))
        .sort((a, b) => getVapeLogSortMs(a) - getVapeLogSortMs(b));

    let remaining = startingPuffs;
    let lastFinishLog = null;

    logs.forEach(log => {
        const previousRemaining = remaining;
        log.previousRemainingBeforeLog = previousRemaining;
        syncLogInventoryId(log);
        log.inventoryId = purchaseId;
        log.purchaseId = purchaseId;
        log.linkedPurchaseId = purchaseId;

        if (isPercentBasedVapeLog(log)) {
            const pct = log.percentLeftAfter ?? log.percentRemaining;
            remaining = Math.round(Math.max(0, Math.min(fullPuffs, fullPuffs * (parseFloat(pct) / 100))));
            const estimatedUsed = Math.max(0, previousRemaining - remaining);
            log.amount = estimatedUsed;
            log.estimatedPuffsUsed = estimatedUsed;
            if (isSharedUseLog(log)) {
                log.totalAmount = estimatedUsed;
            }
            log.isEstimated = true;
            log.estimatedFromPercent = true;
            log.remainingPuffsAfter = remaining;
            log.percentLeftAfter = parseFloat(pct);
            log.percentRemaining = parseFloat(pct);
        } else {
            const used = parseFloat(log.amount) || 0;
            remaining = Math.max(0, Math.min(fullPuffs, previousRemaining - used));
            log.isEstimated = false;
            log.estimatedFromPercent = false;
            log.remainingPuffsAfter = remaining;
            if (fullPuffs > 0) {
                log.percentRemaining = Math.round((remaining / fullPuffs) * 1000) / 10;
                log.percentLeftAfter = log.percentRemaining;
            }
        }

        if (remaining <= INVENTORY_EPS) {
            remaining = 0;
            lastFinishLog = log;
        }
    });

    purchase.remainingAmount = remaining;
    purchase.remainingPuffs = remaining;
    purchase.isDepleted = remaining <= INVENTORY_EPS;
    if (purchase.isDepleted) {
        purchase.inventoryStatus = 'depleted';
    } else {
        purchase.inventoryStatus = 'active';
    }
    syncVapePurchaseSupplyStartedAt(purchase, logs, data);
    purchase.updatedAt = new Date().toISOString();

    if (!skipPercentSpread) {
        if (getSpreadPercentLeftUsage(data)) {
            logs.filter(l => isPercentBasedVapeLog(l)).forEach(log => {
                syncDistributedPercentLeftEntries(log, purchase, data);
            });
        } else {
            logs.filter(l => isPercentLeftCheckpointLog(l)).forEach(log => {
                removeDistributedPercentLeftEntries(log.id, data);
                clearPercentLeftCheckpointFlags(log);
            });
        }
    }
}

function getVapeUsageRatePreview(purchase, newRemaining, useDate, useTime) {
    const starting = getVapeStartingPuffsLeft(purchase);
    const started = parsePurchaseStartedAt(purchase);
    const useDt = parseUseDateTime(useDate, useTime);
    if (!started || !useDt || Number.isNaN(started.getTime()) || Number.isNaN(useDt.getTime())) return null;
    const ms = useDt.getTime() - started.getTime();
    if (ms <= 0) return null;
    const days = ms / 86400000;
    const totalUsedSoFar = Math.max(0, starting - newRemaining);
    return {
        days,
        ms,
        totalUsedSoFar,
        puffsPerDay: totalUsedSoFar / days,
        puffsPerHour: days < 1 ? totalUsedSoFar / (ms / 3600000) : null,
        started,
        useDt
    };
}

function formatPreviewMonthDay(date) {
    if (!date || Number.isNaN(date.getTime())) return '—';
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}

function getSelectedVapePurchaseId() {
    const vapeVal = document.getElementById('use-vape-purchase-select')?.value;
    if (vapeVal) return parsePurchaseSelectId(vapeVal);
    const val = document.getElementById('use-purchase-select')?.value;
    return val ? parsePurchaseSelectId(val) : null;
}

function formatVapePurchaseSelectOptionLabel(purchase) {
    if (!purchase) return 'Vape purchase';
    const title = formatVapePurchaseTitleLine(purchase);
    const full = getVapeFullPuffCount(purchase);
    const rem = getPurchaseRemainingAmount(purchase);
    const pct = getPurchasePercentRemaining(purchase);
    return `${title} · ${formatDate(purchase.date)} · ${formatAmount(full)} puffs · ${formatAmount(rem)} left (${pct}%)`;
}

function getVapeEditPurchaseWarning(purchaseId, data = appData) {
    if (purchaseId == null || purchaseId === '') {
        return 'No linked vape purchase. Select a purchase to link inventory, or save without a link.';
    }
    const purchase = findPurchaseInData(purchaseId, data);
    if (!purchase) {
        return 'Linked vape purchase was not found. Choose another purchase or save without inventory link.';
    }
    if (!isVapePuffPurchase(purchase, data)) {
        return 'Linked purchase is not a vape inventory item.';
    }
    if (purchase.isDepleted || getPurchaseRemainingAmount(purchase) <= INVENTORY_EPS) {
        return 'Linked vape purchase is depleted. You can still edit this log; inventory will recalculate from all linked logs.';
    }
    return null;
}

function showVapeEditPurchaseWarning(purchaseId) {
    const detail = document.getElementById('use-vape-purchase-detail');
    if (!detail) return;
    const purchase = purchaseId ? findPurchase(purchaseId) : null;
    const warning = getVapeEditPurchaseWarning(purchaseId);
    if (warning) {
        detail.textContent = warning;
        detail.classList.add('use-vape-purchase-warning');
        return;
    }
    detail.classList.remove('use-vape-purchase-warning');
    if (!purchase) {
        detail.textContent = 'Select an active vape purchase.';
        return;
    }
    const cur = getCurrencySymbol();
    const cost = parseFloat(getPurchaseTotalCost(purchase)) || 0;
    const pct = getPurchasePercentRemaining(purchase);
    const rem = getPurchaseRemainingAmount(purchase);
    const nic = getVapeNicotineMgPerMl(purchase);
    const detailParts = [formatVapePurchaseSelectOptionLabel(purchase)];
    if (nic != null) detailParts.push(`${formatAmount(nic)} mg/mL`);
    else detailParts.push('nicotine n/a');
    detailParts.push(fmtSheetMoney(cost, cur));
    detail.textContent = detailParts.filter(Boolean).join(' · ');
}

function buildVapePurchaseSelectList(substanceId, linkedPurchaseId = null, data = appData) {
    const active = (data.purchases || [])
        .filter(p => getPurchaseSubstanceId(p) === substanceId && isVapePuffPurchase(p, data))
        .filter(p => purchaseIsPersonalUseInventory(p))
        .filter(p => getPurchaseInventoryTab(p) === 'active' && getPurchaseRemainingAmount(p) > INVENTORY_EPS)
        .sort((a, b) => getPurchaseDatetimeMs(b) - getPurchaseDatetimeMs(a));
    const fallback = (data.purchases || [])
        .filter(p => getPurchaseSubstanceId(p) === substanceId && isVapePuffPurchase(p, data))
        .filter(p => purchaseIsPersonalUseInventory(p))
        .sort((a, b) => getPurchaseDatetimeMs(b) - getPurchaseDatetimeMs(a));
    let list = active.length ? active : fallback;
    if (linkedPurchaseId != null && linkedPurchaseId !== '') {
        const linked = findPurchaseInData(linkedPurchaseId, data);
        if (linked && isVapePuffPurchase(linked, data)
            && !list.some(p => String(p.id) === String(linkedPurchaseId))) {
            list = [linked, ...list];
        }
    }
    return list;
}

function resolveVapeLogEditInputMode(entry) {
    if (!entry) return 'percent';
    if (isPercentBasedVapeLog(entry) || entry.estimatedFromPercent) return 'percent';
    if (entry.logMode === 'vape_puffs' && entry.amount != null) return 'puffs';
    if (entry.amount != null && entry.percentLeftAfter == null && entry.percentRemaining == null) return 'puffs';
    return 'percent';
}

function populateVapeActivePurchaseSelect(substanceId, options = {}) {
    const select = document.getElementById('use-vape-purchase-select');
    if (!select) return;
    const linkedPurchaseId = options.linkedPurchaseId ?? null;
    const list = buildVapePurchaseSelectList(substanceId, linkedPurchaseId);
    const prev = options.preferredPurchaseId ?? select.value;
    select.innerHTML = '';
    if (linkedPurchaseId != null && linkedPurchaseId !== ''
        && !list.some(p => String(p.id) === String(linkedPurchaseId))) {
        const missing = findPurchase(linkedPurchaseId);
        const opt = document.createElement('option');
        opt.value = String(linkedPurchaseId);
        opt.textContent = missing
            ? formatVapePurchaseSelectOptionLabel(missing)
            : `Missing purchase (${linkedPurchaseId})`;
        select.appendChild(opt);
    }
    list.forEach(p => {
        const opt = document.createElement('option');
        opt.value = String(p.id);
        opt.textContent = formatVapePurchaseSelectOptionLabel(p);
        select.appendChild(opt);
    });
    const preferred = linkedPurchaseId ?? prev;
    if (preferred && [...select.options].some(o => String(o.value) === String(preferred))) {
        select.value = String(preferred);
    } else if (list.length) {
        select.value = String(list[0].id);
    }
    const manualSelect = document.getElementById('use-purchase-select');
    if (manualSelect && select.value) manualSelect.value = select.value;
    showVapeEditPurchaseWarning(getSelectedVapePurchaseId());
}

function updateVapePurchaseSelectDetails() {
    showVapeEditPurchaseWarning(getSelectedVapePurchaseId());
}

function populateUseFormFromVapeLog(entry) {
    if (!entry) return;
    const substanceId = getUseSubstanceId(entry);
    const formSubstanceId = isNicotineSubstanceId(substanceId) ? NICOTINE_ID : substanceId;

    const substanceSelect = document.getElementById('use-substance');
    if (substanceSelect && formSubstanceId && [...substanceSelect.options].some(o => o.value === formSubstanceId)) {
        substanceSelect.value = formSubstanceId;
    } else if (substanceSelect && substanceId && [...substanceSelect.options].some(o => o.value === substanceId)) {
        substanceSelect.value = substanceId;
    }

    if (isNicotineTrackingMode(formSubstanceId)) {
        setInputValue('use-nicotine-product-type', getNicotineProductType(entry) || 'vape');
    }

    if (isSharedUseLog(entry)) {
        setLegacySharedUseFormTransactionType();
    } else {
        setUseTransactionType(getLogTransactionType(entry));
    }
    setUseLogType(getUseLogType(entry));

    updateUseUnitDropdown();

    const unit = entry.unit || 'puffs';
    const unitSelect = document.getElementById('use-unit');
    if (unitSelect) {
        if (unit && ![...unitSelect.options].some(o => o.value === unit)) {
            const option = document.createElement('option');
            option.value = unit;
            option.textContent = unit;
            unitSelect.appendChild(option);
        }
        unitSelect.value = unit;
    }

    setInputValue('use-date', entry.date || '');
    setInputValue('use-notes', entry.notes || '');
    setInputValue('use-gift-party', entry.giftPartyName || entry.recipientName || entry.giverName || '');
    setInputValue('use-amount', entry.totalAmount ?? entry.amount ?? '');

    const isDateOnly = isVapeDateOnlyUseLog(entry);
    if (!isDateOnly && (entry.startedAt || entry.startTime || entry.time || entry.endTime || entry.endedAt)) {
        if (entry.startedAt) {
            const started = new Date(entry.startedAt);
            if (!Number.isNaN(started.getTime())) {
                setInputValue('use-date', getLocalDateString(started));
                setInputValue('use-start-time', getLocalTimeString(started));
            }
        } else {
            setInputValue('use-start-time', entry.startTime || entry.time || '');
        }
        if (entry.endedAt) {
            const ended = new Date(entry.endedAt);
            if (!Number.isNaN(ended.getTime())) {
                setInputValue('use-end-date', getLocalDateString(ended));
                setInputValue('use-end-time', getLocalTimeString(ended));
            }
        } else if (entry.endTime) {
            setInputValue('use-end-date', entry.endDate || entry.date || '');
            setInputValue('use-end-time', entry.endTime);
        } else {
            setInputValue('use-end-date', '');
            setInputValue('use-end-time', '');
        }
    } else {
        setInputValue('use-start-time', '');
        setInputValue('use-end-date', '');
        setInputValue('use-end-time', '');
    }

    updateVapeUseFormUI();

    const linkedId = getLogPurchaseId(entry);
    const inputMode = resolveVapeLogEditInputMode(entry);
    if (inputMode === 'puffs') {
        setVapeLogInputMode('puffs');
        setInputValue('use-vape-puffs-used', entry.amount ?? entry.estimatedPuffsUsed ?? '');
        setInputValue('use-percent-after', entry.percentLeftAfter ?? entry.percentRemaining ?? '');
    } else {
        setVapeLogInputMode('percent');
        setInputValue('use-percent-after', entry.percentLeftAfter ?? entry.percentRemaining ?? '');
        setInputValue('use-vape-puffs-used', entry.estimatedPuffsUsed ?? entry.amount ?? '');
    }

    setUsePurchaseLinkMode(hasLinkedSupply(entry) ? 'manual' : 'none');
    populateVapeActivePurchaseSelect(formSubstanceId, { linkedPurchaseId: linkedId, preferredPurchaseId: linkedId });
    updateUsePurchaseLinkUI();
    updateVapeUsePreview();
}

function applyVapeUseLogEdit(existing, payload, vapeCalc, data = appData) {
    const idx = getUseEntries(data).findIndex(l => l.id === existing.id || String(l.id) === String(existing.id));
    if (idx < 0) return { ok: false, error: 'Could not find the entry to update.' };

    const oldPid = getLogPurchaseId(existing);
    if (isPercentLeftCheckpointLog(existing)) {
        removeDistributedPercentLeftEntries(existing.id, data);
    }

    const now = new Date().toISOString();
    const eventTimestamp = getUseEventTimestamp(payload.date, payload.startTime);
    const updated = {
        ...existing,
        ...payload,
        id: existing.id,
        substanceId: payload.substanceId,
        purchaseId: payload.inventoryAffects ? (payload.purchaseId ?? payload.linkedPurchaseId) : null,
        linkedPurchaseId: payload.inventoryAffects ? payload.linkedPurchaseId : null,
        inventoryId: payload.inventoryAffects ? (payload.inventoryId ?? payload.linkedPurchaseId) : null,
        linkedPurchases: payload.inventoryAffects ? (payload.linkedPurchases || []) : [],
        inventoryAffects: payload.inventoryAffects,
        supplyUnlinked: !payload.inventoryAffects,
        createdAt: getUseCreatedAt(existing),
        updatedAt: now,
        timestamp: eventTimestamp
    };
    stripLegacyUseLogFields(updated);
    delete updated.substance;
    delete updated.lines;

    if (isNicotineVapeFormContext(payload.substanceId, updated)) {
        updated.type = 'quick';
        updated.logMode = 'vape_puffs';
        updated.startTime = '';
        updated.time = '';
        updated.endTime = '';
        delete updated.endDate;
        delete updated.startedAt;
        delete updated.endedAt;
        delete updated.durationMs;
        delete updated.estimatedPuffsPerHour;
        delete updated.estimatedPuffsPerMinute;
        if (vapeCalc && !vapeCalc.error) {
            updated.nicotineProductType = 'vape';
            updated.isEstimated = !!vapeCalc.isEstimated;
            updated.estimatedFromPercent = !!vapeCalc.estimatedFromPercent;
            updated.percentLeftAfter = vapeCalc.percentAfter;
            updated.percentRemaining = vapeCalc.percentAfter;
            updated.remainingPuffsAfter = vapeCalc.currentRemaining;
            updated.estimatedPuffsUsed = vapeCalc.estimatedPuffsUsed ?? vapeCalc.puffsUsed;
            updated.amount = updated.estimatedPuffsUsed;
            updated.previousRemainingBeforeLog = vapeCalc.previousRemaining;
            updated.unit = 'puffs';
        }
    }

    if (isNicotineTrackingMode(getUseSubstanceId(updated))) {
        finalizeNicotineUseLogForSave(updated, { vapeCalc });
    }

    setLogPurchaseId(updated, getLogPurchaseId(updated));
    data.logs[idx] = updated;

    const recalcIds = new Set();
    if (oldPid != null) recalcIds.add(oldPid);
    const newPid = getLogPurchaseId(updated);
    if (newPid != null) recalcIds.add(newPid);
    recalcIds.forEach(pid => recalculateVapePurchaseInventory(pid, data));

    return { ok: true, updated, idx };
}

function getVapeLogInputMode() {
    return document.getElementById('use-vape-log-mode')?.value === 'puffs' ? 'puffs' : 'percent';
}

function setVapeLogInputMode(mode) {
    const val = mode === 'puffs' ? 'puffs' : 'percent';
    setInputValue('use-vape-log-mode', val);
    document.querySelectorAll('.use-vape-mode-btn').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.vapeMode === val);
    });
    document.getElementById('use-vape-percent-group')?.classList.toggle('hidden', val === 'puffs');
    document.getElementById('use-vape-puffs-group')?.classList.toggle('hidden', val !== 'puffs');
    updateVapeUsePreview();
}

function computeVapeUseFromForm(options = {}) {
    const substanceId = document.getElementById('use-substance')?.value;
    const isNicotineVape = isNicotineTrackingMode(substanceId) && getUseFormNicotineProductType() === 'vape';
    if (!isNicotineVape && !isVapeTrackingMode(substanceId)) return null;

    const logDate = document.getElementById('use-date')?.value || getLocalDateString();
    if (!logDate) return { error: 'Enter a date.' };

    const purchaseId = getSelectedVapePurchaseId();
    const purchase = purchaseId ? findPurchase(purchaseId) : null;
    const fullPuffCount = purchase ? getVapeFullPuffCount(purchase) : null;
    if (!purchase || !fullPuffCount) {
        const warning = getVapeEditPurchaseWarning(purchaseId);
        return { error: warning || 'Select an active vape purchase.' };
    }

    const previousRemaining = getVapeRemainingBeforeLog(
        purchase,
        logDate,
        appData,
        options.editingId || null
    );
    const inputMode = getVapeLogInputMode();
    let percentAfter;
    let currentRemaining;
    let puffsUsed;
    let isEstimated = true;
    let estimatedFromPercent = true;
    let warning = null;

    if (inputMode === 'puffs') {
        const puffsRaw = parseFloat(document.getElementById('use-vape-puffs-used')?.value);
        if (!Number.isFinite(puffsRaw) || puffsRaw < 0) {
            return { error: 'Enter puffs used.' };
        }
        puffsUsed = puffsRaw;
        currentRemaining = Math.max(0, previousRemaining - puffsUsed);
        percentAfter = fullPuffCount > 0
            ? Math.round((currentRemaining / fullPuffCount) * 100)
            : 0;
        isEstimated = false;
        estimatedFromPercent = false;
    } else {
        const percentRaw = document.getElementById('use-percent-after')?.value;
        const hasPercent = percentRaw !== '' && percentRaw != null && Number.isFinite(parseFloat(percentRaw));
        if (!hasPercent) return { error: 'Enter current % left after this use.' };
        percentAfter = Math.max(0, Math.min(100, parseFloat(percentRaw)));
        currentRemaining = Math.round(Math.max(0, Math.min(fullPuffCount, fullPuffCount * (percentAfter / 100))));
        puffsUsed = previousRemaining - currentRemaining;
        if (puffsUsed < 0) {
            warning = 'Percent left is higher than current inventory. This will be treated as an adjustment unless you choose a different vape.';
        }
    }

    return {
        purchase,
        purchaseId: purchase.id,
        puffsUsed,
        estimatedPuffsUsed: puffsUsed,
        currentRemaining,
        percentAfter,
        previousRemaining,
        totalPuffs: fullPuffCount,
        isEstimated,
        estimatedFromPercent,
        warning
    };
}

function updateVapeUsePreview() {
    const preview = document.getElementById('use-vape-preview');
    if (!preview) return;
    if (!isVapeSessionFormActive()) {
        preview.textContent = '—';
        return;
    }

    const calc = computeVapeUseFromForm({ editingId: editingUseId || null });
    if (!calc || calc.error) {
        preview.textContent = calc?.error || 'Enter current % left after this use.';
        return;
    }

    const pctLabel = Number.isInteger(calc.percentAfter)
        ? calc.percentAfter
        : parseFloat(calc.percentAfter).toFixed(1);
    const lines = [
        `${formatAmount(calc.puffsUsed)} puffs used → ${formatAmount(calc.currentRemaining)} puffs remaining (${pctLabel}% left).`
    ];
    if (calc.warning) lines.push(calc.warning);
    if (calc.estimatedFromPercent && getSpreadPercentLeftUsage() && calc.puffsUsed > 0) {
        const checkpoint = getPreviousPercentCheckpointInfo(
            calc.purchase,
            document.getElementById('use-date')?.value || getLocalDateString(),
            editingUseId || null
        );
        const start = checkpoint.startDate;
        const end = document.getElementById('use-date')?.value || getLocalDateString();
        if (start && end && end >= start) {
            const dayCount = iterateDatesInRange(start, end).length;
            lines.push(`Will spread ~${formatAmount(calc.puffsUsed)} puffs evenly across ${dayCount} day(s) (${formatDate(start)}–${formatDate(end)}).`);
        }
    }

    preview.textContent = lines.join('\n');
}

function onNicotineUseProductTypeChange() {
    const substanceId = document.getElementById('use-substance')?.value;
    const productType = isNicotineTrackingMode(substanceId) ? getUseFormNicotineProductType() : null;
    const select = document.getElementById('use-purchase-select');
    if (select?.value && productType) {
        const purchase = findPurchase(parsePurchaseSelectId(select.value));
        if (purchase && getNicotineProductType(purchase) !== productType) {
            select.value = '';
        }
    }
    const vapeSelect = document.getElementById('use-vape-purchase-select');
    if (vapeSelect?.value && productType && productType !== 'vape') {
        vapeSelect.value = '';
    }
    // Full form refresh clears required flags on hidden vape/amount fields so submit is not blocked.
    updateVapeUseFormUI();
    updateUsePurchaseLinkUI();
}

function updateUseNicotineProductTypeUI() {
    const substanceId = document.getElementById('use-substance')?.value;
    if (!isNicotineTrackingMode(substanceId)) return;
    const productType = getUseFormNicotineProductType();
    const isVape = productType === 'vape';
    const isCigarettes = productType === 'cigarettes';
    const isPouches = productType === 'pouches';
    const isGum = productType === 'gum';
    const isPatches = productType === 'patches';

    document.getElementById('use-vape-fields-group')?.classList.toggle('hidden', !isVape);
    document.getElementById('use-cigarettes-fields-group')?.classList.toggle('hidden', !isCigarettes);
    document.getElementById('use-pouches-fields-group')?.classList.toggle('hidden', !isPouches);
    document.getElementById('use-gum-fields-group')?.classList.toggle('hidden', !isGum);
    document.getElementById('use-patches-fields-group')?.classList.toggle('hidden', !isPatches);
    document.getElementById('use-amount-mode-group')?.classList.toggle('hidden', isVape || isCigarettes || isPouches || isGum || isPatches);
    document.getElementById('use-nicotine-product-type-group')?.classList.remove('hidden');

    if (isVape) {
        populateVapeActivePurchaseSelect(substanceId);
        updateVapeUsePreview();
    }
    if (isCigarettes) updateUseCigarettesPreview();
    if (isPouches) updateUsePouchesPreview();
    if (isGum) updateUseGumPreview();
    if (isPatches) updateUsePatchesPreview();
}

function updateUseCigarettesPreview() {
    const preview = document.getElementById('use-cigarettes-preview');
    if (!preview) return;
    const smoked = parseFloat(document.getElementById('use-cigarettes-smoked')?.value);
    if (!Number.isFinite(smoked) || smoked <= 0) {
        preview.textContent = '—';
        return;
    }
    const perPack = 20;
    const packs = smoked / perPack;
    preview.textContent = `${formatAmount(smoked)} cigarettes${packs >= 0.05 ? ` (~${formatAmount(packs)} packs)` : ''}`;
}

function updateUsePouchesPreview() {
    const preview = document.getElementById('use-pouches-preview');
    if (!preview) return;
    const used = parseFloat(document.getElementById('use-pouches-used')?.value);
    const purchaseId = resolveLinkedPurchaseId(document.getElementById('use-substance')?.value, 'use');
    const purchase = purchaseId ? findPurchase(purchaseId) : null;
    const mgPer = parseFloat(purchase?.mgPerPouch);
    if (!Number.isFinite(used) || used <= 0) {
        preview.textContent = '—';
        return;
    }
    preview.textContent = Number.isFinite(mgPer) && mgPer > 0
        ? `${formatAmount(used)} pouches · ~${formatAmount(used * mgPer)} mg nicotine`
        : `${formatAmount(used)} pouches`;
}

function updateUseGumPreview() {
    const preview = document.getElementById('use-gum-preview');
    if (!preview) return;
    const used = parseFloat(document.getElementById('use-gum-pieces-used')?.value);
    const purchaseId = resolveLinkedPurchaseId(document.getElementById('use-substance')?.value, 'use');
    const purchase = purchaseId ? findPurchase(purchaseId) : null;
    const mgPer = parseFloat(purchase?.mgPerPiece);
    if (!Number.isFinite(used) || used <= 0) {
        preview.textContent = '—';
        return;
    }
    preview.textContent = Number.isFinite(mgPer) && mgPer > 0
        ? `${formatAmount(used)} pieces · ~${formatAmount(used * mgPer)} mg nicotine`
        : `${formatAmount(used)} pieces`;
}

function updateUsePatchesPreview() {
    const preview = document.getElementById('use-patches-preview');
    if (!preview) return;
    const used = parseFloat(document.getElementById('use-patches-used')?.value);
    const hours = parseFloat(document.getElementById('use-patch-hours-worn')?.value);
    const purchaseId = resolveLinkedPurchaseId(document.getElementById('use-substance')?.value, 'use');
    const purchase = purchaseId ? findPurchase(purchaseId) : null;
    const mgPer = parseFloat(purchase?.mgPerPatch);
    const duration = parseFloat(purchase?.patchDurationHours) || 24;
    if (!Number.isFinite(used) || used <= 0) {
        preview.textContent = '—';
        return;
    }
    let mgEstimate = null;
    if (Number.isFinite(mgPer) && mgPer > 0) {
        const worn = Number.isFinite(hours) && hours > 0 ? hours : duration;
        mgEstimate = used * mgPer * Math.min(1, worn / duration);
    }
    preview.textContent = mgEstimate != null
        ? `${formatAmount(used)} patch(es) · ~${formatAmount(mgEstimate)} mg nicotine est.`
        : `${formatAmount(used)} patch(es)`;
}

function getNicotineUseUnitLabel(productType, unit) {
    if (productType === 'vape') return 'puffs';
    if (productType === 'cigarettes') return 'cigarettes';
    if (productType === 'pouches') return 'pouches';
    if (productType === 'gum') return 'pieces';
    if (productType === 'patches') return 'patches';
    return unit || 'units';
}

function finalizeNicotineUseLogForSave(log, { nicotineCalc = null, vapeCalc = null } = {}) {
    if (!isNicotineTrackingMode(getUseSubstanceId(log))) return;
    const tx = getLogTransactionType(log);
    if (tx === 'gift_given') {
        log.recipientName = log.recipientName || log.giftPartyName || '';
        log.giftPartyName = log.recipientName;
    }
    if (tx === 'gift_received') {
        log.giverName = log.giverName || log.giftPartyName || '';
        log.giftPartyName = log.giverName;
    }
    if (nicotineCalc && !nicotineCalc.error) {
        log.nicotineProductType = nicotineCalc.nicotineProductType || log.nicotineProductType;
        if (nicotineCalc.cigarettesUsed != null) log.cigarettesUsed = nicotineCalc.cigarettesUsed;
        if (nicotineCalc.pouchesUsed != null) log.pouchesUsed = nicotineCalc.pouchesUsed;
        if (nicotineCalc.piecesUsed != null) log.piecesUsed = nicotineCalc.piecesUsed;
        if (nicotineCalc.patchesUsed != null) log.patchesUsed = nicotineCalc.patchesUsed;
        if (nicotineCalc.nicotineMgUsed != null) log.nicotineMgUsed = nicotineCalc.nicotineMgUsed;
        if (nicotineCalc.purchaseId && log.inventoryAffects !== false) {
            setLogPurchaseId(log, nicotineCalc.purchaseId);
        }
    }
    if (vapeCalc && !vapeCalc.error) {
        log.nicotineProductType = 'vape';
        log.isEstimated = !!vapeCalc.isEstimated;
        log.estimatedFromPercent = !!vapeCalc.estimatedFromPercent;
        log.percentLeftAfter = vapeCalc.percentAfter;
        log.remainingPuffsAfter = vapeCalc.currentRemaining;
        log.estimatedPuffsUsed = vapeCalc.estimatedPuffsUsed ?? vapeCalc.puffsUsed;
        log.amount = vapeCalc.estimatedPuffsUsed ?? vapeCalc.puffsUsed;
        log.unit = 'puffs';
        if (vapeCalc.purchaseId && log.inventoryAffects !== false) {
            setLogPurchaseId(log, vapeCalc.purchaseId);
        }
    }
    syncLogPurchaseFields(log);
    return log;
}

function computeNicotineNonVapeUseFromForm() {
    const substanceId = document.getElementById('use-substance')?.value;
    if (!isNicotineTrackingMode(substanceId)) return null;
    const productType = getUseFormNicotineProductType();
    if (productType === 'vape') return null;
    const transactionType = document.getElementById('use-transaction-type')?.value || 'use';

    const linkedPurchaseId = resolveLinkedPurchaseId(substanceId, transactionType, { nicotineProductType: productType });
    const purchase = linkedPurchaseId ? findPurchase(linkedPurchaseId) : null;
    const inventoryAffects = getUsePurchaseLinkMode() !== 'none' && !!linkedPurchaseId;

    const resolveProductAmount = (productAmount, errorLabel) => {
        if (!Number.isFinite(productAmount) || productAmount <= 0) {
            return { error: errorLabel };
        }
        return { amount: productAmount };
    };

    if (productType === 'cigarettes') {
        const resolved = resolveProductAmount(
            parseFloat(document.getElementById('use-cigarettes-smoked')?.value),
            'Enter cigarettes smoked.'
        );
        if (resolved.error) return resolved;
        const smoked = resolved.amount;
        const perPack = parseFloat(purchase?.cigarettesPerPack) || 20;
        return {
            amount: smoked,
            unit: 'cigarettes',
            nicotineProductType: 'cigarettes',
            cigarettesUsed: smoked,
            packsUsed: smoked / perPack,
            purchaseId: linkedPurchaseId,
            inventoryAffects,
            logMode: 'nicotine_cigarettes'
        };
    }
    if (productType === 'pouches') {
        const resolved = resolveProductAmount(
            parseFloat(document.getElementById('use-pouches-used')?.value),
            'Enter pouches used.'
        );
        if (resolved.error) return resolved;
        const used = resolved.amount;
        const mgPer = parseFloat(purchase?.mgPerPouch);
        return {
            amount: used,
            unit: 'pouches',
            nicotineProductType: 'pouches',
            pouchesUsed: used,
            nicotineMgUsed: Number.isFinite(mgPer) ? used * mgPer : null,
            purchaseId: linkedPurchaseId,
            inventoryAffects,
            logMode: 'nicotine_pouches'
        };
    }
    if (productType === 'gum') {
        const resolved = resolveProductAmount(
            parseFloat(document.getElementById('use-gum-pieces-used')?.value),
            'Enter pieces used.'
        );
        if (resolved.error) return resolved;
        const used = resolved.amount;
        const mgPer = parseFloat(purchase?.mgPerPiece);
        return {
            amount: used,
            unit: 'pieces',
            nicotineProductType: 'gum',
            piecesUsed: used,
            nicotineMgUsed: Number.isFinite(mgPer) ? used * mgPer : null,
            purchaseId: linkedPurchaseId,
            inventoryAffects,
            logMode: 'nicotine_gum'
        };
    }
    if (productType === 'patches') {
        const resolved = resolveProductAmount(
            parseFloat(document.getElementById('use-patches-used')?.value),
            'Enter patches used.'
        );
        if (resolved.error) return resolved;
        const used = resolved.amount;
        const hours = parseFloat(document.getElementById('use-patch-hours-worn')?.value);
        const mgPer = parseFloat(purchase?.mgPerPatch);
        const duration = parseFloat(purchase?.patchDurationHours) || 24;
        const worn = Number.isFinite(hours) && hours > 0 ? hours : duration;
        const mgUsed = Number.isFinite(mgPer) ? used * mgPer * Math.min(1, worn / duration) : null;
        return {
            amount: used,
            unit: 'patches',
            nicotineProductType: 'patches',
            patchesUsed: used,
            patchHoursWorn: worn,
            nicotineMgUsed: mgUsed,
            purchaseId: linkedPurchaseId,
            inventoryAffects,
            logMode: 'nicotine_patches'
        };
    }

    const amountRaw = parseFloat(document.getElementById('use-amount')?.value);
    const unit = document.getElementById('use-unit')?.value || 'units';
    if (!Number.isFinite(amountRaw) || amountRaw <= 0) {
        return { error: 'Enter amount used.' };
    }
    return {
        amount: amountRaw,
        unit,
        nicotineProductType: productType,
        purchaseId: linkedPurchaseId,
        inventoryAffects,
        logMode: 'amount'
    };
}

function updateVapeUseFormUI() {
    const substanceId = document.getElementById('use-substance')?.value;
    const isNicotine = isNicotineTrackingMode(substanceId);
    const nicotineProductType = isNicotine ? getUseFormNicotineProductType() : null;
    const isVape = isNicotine ? nicotineProductType === 'vape' : isVapeTrackingMode(substanceId);
    const isNicotineSimple = isNicotine && nicotineProductType !== 'vape' && nicotineProductType !== 'other';
    const isWeed = isWeedTrackingMode(substanceId);
    const isLsd = isLsdSubstanceId(substanceId);
    const isXanax = isXanaxSubstanceId(substanceId);
    const isAlcohol = isAlcoholTrackingMode(substanceId);
    const isVapeUse = isVape;
    const vapeGroup = document.getElementById('use-vape-fields-group');
    const amountGroup = document.getElementById('use-amount-mode-group');
    const amountInput = document.getElementById('use-amount');
    const percentInput = document.getElementById('use-percent-after');
    const unitSelect = document.getElementById('use-unit');
    const countGroup = document.getElementById('use-count-group');
    const tx = document.getElementById('use-transaction-type')?.value || 'use';
    const isNonUse = isNonUseTransactionType(tx);

    document.getElementById('use-log-form')?.classList.toggle('is-weed-simple', isWeed);
    document.getElementById('use-log-form')?.classList.toggle('is-vape-simple', isVape || isNicotineSimple);
    document.getElementById('use-log-form')?.classList.toggle('is-lsd-simple', isLsd);
    document.getElementById('use-log-form')?.classList.toggle('is-xanax-simple', isXanax);
    updateUseTransactionTypePillsVisibility();
    document.getElementById('use-start-time-group')?.classList.toggle('hidden', isWeed || isVape || isNicotineSimple || (isNicotine && !isNonUse));

    const dateLabel = document.getElementById('use-date-label');
    if (dateLabel) dateLabel.textContent = 'Date';
    const startTimeInput = document.getElementById('use-start-time');
    if (startTimeInput) {
        startTimeInput.required = !isWeed && !isVape && !isNicotineSimple && !(isXanax && isNonUse) && !(isNicotine && !isNonUse);
    }
    if (isLsd) {
        syncLsdUseDatetimeUI();
    }

    if (isNicotine) {
        document.getElementById('use-nicotine-product-type-group')?.classList.remove('hidden');
        updateUseNicotineProductTypeUI();
        positionUseInventoryFields(isNicotineSimple);
        document.getElementById('use-duration-preview')?.classList.add('hidden');
        document.getElementById('use-weed-product-type-group')?.classList.add('hidden');
        document.getElementById('use-weed-cart-fields-group')?.classList.add('hidden');
    } else if (isWeed) {
        ensureWeedUseFormDefaults();
        updateWeedUseFormUI();
        positionUseInventoryFields(true);
        document.getElementById('use-duration-preview')?.classList.add('hidden');
    } else if (isLsd) {
        updateLsdUseFormUI();
        positionUseInventoryFields(true);
        document.getElementById('use-duration-preview')?.classList.add('hidden');
        document.getElementById('use-weed-product-type-group')?.classList.add('hidden');
        document.getElementById('use-weed-cart-fields-group')?.classList.add('hidden');
    } else if (isXanax) {
        ensureXanaxUseFormDefaults();
        updateXanaxUseFormUI();
        positionUseInventoryFields(true);
        document.getElementById('use-duration-preview')?.classList.add('hidden');
        document.getElementById('use-weed-product-type-group')?.classList.add('hidden');
        document.getElementById('use-weed-cart-fields-group')?.classList.add('hidden');
    } else if (isAlcohol) {
        document.getElementById('use-nicotine-product-type-group')?.classList.add('hidden');
        document.getElementById('use-cigarettes-fields-group')?.classList.add('hidden');
        document.getElementById('use-pouches-fields-group')?.classList.add('hidden');
        document.getElementById('use-gum-fields-group')?.classList.add('hidden');
        document.getElementById('use-patches-fields-group')?.classList.add('hidden');
        document.getElementById('use-weed-product-type-group')?.classList.add('hidden');
        document.getElementById('use-weed-cart-fields-group')?.classList.add('hidden');
        document.getElementById('use-lsd-fields-group')?.classList.add('hidden');
        document.getElementById('use-xanax-fields-group')?.classList.add('hidden');
        positionUseInventoryFields(false);
        updateAlcoholUseFormUI();
    } else if (isVape) {
        ensureVapeUseFormDefaults();
        positionUseInventoryFields(false);
        document.getElementById('use-duration-preview')?.classList.add('hidden');
        document.getElementById('use-weed-product-type-group')?.classList.add('hidden');
        document.getElementById('use-weed-cart-fields-group')?.classList.add('hidden');
    } else {
        document.getElementById('use-nicotine-product-type-group')?.classList.add('hidden');
        document.getElementById('use-cigarettes-fields-group')?.classList.add('hidden');
        document.getElementById('use-pouches-fields-group')?.classList.add('hidden');
        document.getElementById('use-gum-fields-group')?.classList.add('hidden');
        document.getElementById('use-patches-fields-group')?.classList.add('hidden');
        document.getElementById('use-weed-product-type-group')?.classList.add('hidden');
        document.getElementById('use-weed-cart-fields-group')?.classList.add('hidden');
        document.getElementById('use-lsd-fields-group')?.classList.add('hidden');
        document.getElementById('use-xanax-fields-group')?.classList.add('hidden');
        positionUseInventoryFields(false);
    }

    if (isVape && !isNicotine) {
        setUsePurchaseLinkMode('manual');
        populateVapeActivePurchaseSelect(substanceId);
        setVapeLogInputMode(getVapeLogInputMode());
    }

    const isWeedCart = isWeed && getWeedUseProductType({ allowEmpty: true }) === 'cart';
    if (!isWeed) {
        document.getElementById('use-weed-cart-fields-group')?.classList.add('hidden');
    }
    amountGroup?.classList.toggle('hidden', isVapeUse || isLsd || isXanax || isNicotineSimple || isWeedCart);
    if (!isNicotine) {
        vapeGroup?.classList.toggle('hidden', !isVapeUse);
    }
    document.getElementById('use-vape-purchase-block')?.classList.toggle('hidden', !isVapeUse);
    if (amountInput) {
        amountInput.required = !isVapeUse && !isLsd && !isXanax && !isNicotineSimple && !isWeedCart;
    }
    if (percentInput) {
        if (isVapeUse) {
            percentInput.required = getVapeLogInputMode() === 'percent';
            const purchaseId = getSelectedVapePurchaseId();
            percentInput.disabled = !purchaseId;
        } else {
            percentInput.required = false;
            percentInput.disabled = false;
        }
    }
    if (unitSelect) {
        unitSelect.disabled = isVapeUse || isLsd || isXanax || isNicotineSimple;
        unitSelect.required = !isVapeUse && !isLsd && !isXanax && !isNicotineSimple;
    }
    countGroup?.classList.toggle('hidden', !shouldShowUseCountForSubstance(substanceId) || isVapeUse || isWeed || isLsd || isNicotineSimple);
    if (isVapeUse) {
        updateVapeUsePreview();
    }

    if (!isWeed && !isVape && !isLsd && !isNicotineSimple && !isAlcohol) {
        updateUseEndTimeVisibility();
    }
}

function applyVapeUseInventory(calc, logEntry) {
    const purchase = calc.purchase;
    if (!purchase) return { ok: false, error: 'Purchase not found.' };
    setLogPurchaseId(logEntry, purchase.id);
    recalculateVapePurchaseInventory(purchase.id);
    return { ok: true };
}

function formatVapeUseSummary(log, sub) {
    if (isNicotineSubstanceId(getUseSubstanceId(log)) && getLogTransactionType(log) !== 'use') {
        return formatNicotineUseSummary(log);
    }
    return formatVapeRecentUseDetailLines(log).join(' · ') || `${sub?.name || 'Vape'} use`;
}

function formatLsdTabCountLabel(tabs) {
    const n = parseFloat(tabs);
    if (!Number.isFinite(n)) return '— tabs';
    const rounded = Math.abs(n - 1) < 0.001;
    return `${formatAmount(n)} tab${rounded ? '' : 's'}`;
}

function formatLsdUseSummary(log) {
    const tabs = getLsdLogTabsAmount(log);
    const ug = getLsdLogUgAmount(log);
    const detail = `${formatLsdTabCountLabel(tabs)} · ${formatAmount(ug)} ug`;
    const tx = getLogTransactionType(log);
    if (tx === 'gift_given') return `Gift Given · ${detail}`;
    if (tx === 'gift_received') return `Gift Received · ${detail}`;
    if (tx === 'inventory_adjustment') {
        const dir = getAdjustmentDirection(log) === 'remove' ? '−' : '+';
        return `Adjustment · ${dir}${detail}`;
    }
    return `${formatLsdTabCountLabel(tabs)} · ${formatAmount(ug)} ug`;
}

function formatVapeRecentUseDetailLines(log) {
    const lines = [];
    if (log.needsReview) {
        lines.push('Needs review');
        return lines;
    }
    if (isPercentLeftDistributedChildLog(log)) {
        lines.push(`~${formatAmount(log.amount)} puffs`);
        lines.push('Estimated daily use from percent-left log');
        return lines;
    }
    if (isPercentLeftCheckpointLog(log) && getSpreadPercentLeftUsage()) {
        lines.push(formatPercentLeftCheckpointSummary(log));
        return lines;
    }
    const amount = parseFloat(log.estimatedPuffsUsed ?? log.amount);
    if (Number.isFinite(amount)) {
        lines.push(`~${formatAmount(amount)} puffs used`);
    }
    const pct = log.percentLeftAfter ?? log.percentRemaining;
    if (pct != null) {
        const pctLabel = Number.isInteger(pct) ? pct : parseFloat(pct).toFixed(1);
        lines.push(`${pctLabel}% left after`);
    }
    const started = getUseLogStartedAt(log);
    const ended = getUseLogEndedAt(log);
    if (!isVapeDateOnlyUseLog(log)) {
        if (started) lines.push(`Start: ${formatDatetimeShort(started)}`);
        if (ended && (log.endTime || log.endedAt)) lines.push(`End: ${formatDatetimeShort(ended)}`);
        const durationMs = log.durationMs ?? (started && ended ? ended.getTime() - started.getTime() : null);
        if (durationMs != null && durationMs > 0) {
            lines.push(`Duration: ${formatVapeDuration(durationMs)}`);
        }
    }
    if (log.isEstimated || log.estimatedFromPercent) {
        lines.push('Estimated from percent left');
    }
    return lines;
}

function formatVapeLinkedPurchaseLine(log) {
    const pid = getLogPurchaseId(log);
    if (!pid) return '';
    const purchase = findPurchase(pid);
    if (!purchase) return '';
    const label = formatVapePurchaseTitleLine(purchase);
    return `Linked: ${formatDate(purchase.date)} · ${label}`;
}

function repairVapeInventoryLinks(data) {
    ensureAppDataMigrations(data);
    (data.logs || []).forEach(log => {
        syncLogInventoryId(log);
        if (!data.migrations.vapeInventoryLinkV2 && !getLogPurchaseId(log) && isVapeUseLog(log, data)) {
            const inferred = inferVapeInventoryIdForLog(log, data);
            if (inferred) setLogPurchaseId(log, inferred);
        }
    });
    if (!data.migrations.vapeInventoryLinkV2) {
        (data.purchases || []).filter(isVapePuffPurchase).forEach(purchase => {
            delete purchase.startedAt;
        });
        data.migrations.vapeInventoryLinkV2 = true;
    }
    (data.purchases || []).filter(isVapePuffPurchase).forEach(purchase => {
        recalculateVapePurchaseInventory(purchase.id, data);
    });
}

function migrateVapeDataV1(data) {
    if (data.migrations?.vapePuffsV1) return;
    (data.purchases || []).forEach(purchase => {
        if (!isVapePuffPurchase(purchase)) return;
        normalizeVapePurchaseFields(purchase);
        if (!purchase.time) purchase.time = '12:00';
        if (purchase.remainingPuffs == null) purchase.remainingPuffs = getPurchaseRemainingAmount(purchase);
    });
    (data.logs || []).forEach(log => {
        if (!isVapeNicotineSubstanceId(getUseSubstanceId(log)) || !isPersonalUseLog(log)) return;
        if (log.logMode === 'percent_remaining' || log.amountUnit === '%') {
            log.logMode = 'vape_puffs';
            log.unit = 'puffs';
            delete log.amountUnit;
            const pid = getLogPurchaseId(log);
            const purchase = pid ? findPurchaseInData(pid, data) : null;
            const bought = purchase ? getVapeFullPuffCount(purchase) : null;
            const amount = parseFloat(log.amount) || 0;
            if (amount <= INVENTORY_EPS && log.previousRemainingBeforeLog != null && log.percentRemaining != null && bought > 0) {
                const afterRemaining = bought * (parseFloat(log.percentRemaining) / 100);
                const inferred = log.previousRemainingBeforeLog - afterRemaining;
                if (inferred > INVENTORY_EPS) log.amount = inferred;
                else log.needsReview = true;
            } else if (amount <= INVENTORY_EPS) {
                log.needsReview = true;
            }
            if (bought > 0 && amount >= bought * 0.95 && parseFloat(log.percentRemaining) === 0) {
                log.needsReview = true;
            }
            if (!log.needsReview) {
                log.estimatedFromPercent = true;
                log.isEstimated = true;
                log.percentLeftAfter = log.percentRemaining;
            }
        }
        if (isVapeUseLog(log) && log.unit !== 'puffs') log.unit = 'puffs';
    });
    (data.purchases || []).forEach(purchase => {
        if (isVapePuffPurchase(purchase)) recalculateVapePurchaseInventory(purchase.id, data);
    });
    if (!data.migrations) data.migrations = {};
    data.migrations.vapePuffsV1 = true;
}

function migrateVapePercentSpreadV1(data) {
    if (data.migrations?.vapePercentSpreadV1) return;
    ensureAppDataSettings(data);
    data.logs = getUseEntries(data).filter(l => !isPercentLeftDistributedChildLog(l));
    getUseEntries(data).forEach(l => clearPercentLeftCheckpointFlags(l));
    (data.purchases || []).filter(isVapePuffPurchase).forEach(purchase => {
        recalculateVapePurchaseInventory(purchase.id, data);
    });
    if (!data.migrations) data.migrations = {};
    data.migrations.vapePercentSpreadV1 = true;
}

function markVapePurchaseEmpty(purchaseId) {
    const purchase = findPurchase(purchaseId);
    if (!purchase || !isVapePuffPurchase(purchase)) return;
    const remaining = getPurchaseRemainingAmount(purchase);
    if (remaining <= INVENTORY_EPS) return alert('This vape is already empty.');

    const dateStr = prompt('Finish date (YYYY-MM-DD):', getLocalDateString());
    if (dateStr == null) return;
    const timeStr = prompt('Finish time (HH:MM):', getLocalTimeString()) || '12:00';
    const finishIso = getUseEventTimestamp(dateStr, timeStr);

    const logRemaining = confirm(
        `Mark this vape empty on ${formatDate(dateStr)} at ${timeStr}?\n\nOK = also log ${formatAmount(remaining)} puffs used\nCancel = mark empty without a use log`
    );

    if (logRemaining) {
        const log = {
            id: Date.now(),
            type: 'quick',
            transactionType: 'use',
            substanceId: getPurchaseSubstanceId(purchase),
            amount: remaining,
            unit: 'puffs',
            logMode: 'vape_puffs',
            isEstimated: true,
            estimatedFromPercent: true,
            percentRemaining: 0,
            percentLeftAfter: 0,
            remainingPuffsAfter: 0,
            previousRemainingBeforeLog: remaining,
            date: dateStr,
            startTime: timeStr,
            time: timeStr,
            notes: 'Marked empty',
            purchaseId: purchase.id,
            linkedPurchaseId: purchase.id,
            linkedPurchases: [],
            inventoryAffects: true,
            supplyUnlinked: false,
            timestamp: finishIso,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString()
        };
        stripLegacyUseLogFields(log);
        if (!Array.isArray(appData.logs)) appData.logs = [];
        appData.logs.push(log);
        recalculateVapePurchaseInventory(purchase.id);
    } else {
        purchase.remainingAmount = 0;
        purchase.isDepleted = true;
        purchase.updatedAt = new Date().toISOString();
    }

    saveData(appData);
    refreshUseLogRelatedViews();
    refreshBuyTrackerRelatedViews();
    alert(logRemaining ? 'Vape marked empty and use logged.' : 'Vape marked empty.');
}

function formatPurchaseRemainingDisplay(purchase) {
    if (isVapePuffPurchase(purchase)) {
        const pct = getPurchasePercentRemaining(purchase);
        return `${formatAmountWithUnit(getPurchaseRemainingDisplayAmount(purchase), 'puffs')} / ${pct}%`;
    }
    if (isLsdPurchase(purchase)) {
        return formatLsdRemainingDisplay(purchase);
    }
    if (isXanaxPurchase(purchase)) {
        return formatXanaxRemainingDisplay(purchase);
    }
    if (isWeedEdiblesPurchase(purchase)) {
        const rem = getPurchaseRemainingAmount(purchase);
        const thc = getWeedEdibleRemainingThcMg(purchase);
        const countPart = `${formatAmount(rem)} edible`;
        if (thc != null) return `${countPart} · ${formatAmount(thc)} mg THC`;
        if (weedEdiblePurchaseNeedsStrengthInfo(purchase)) {
            return `${countPart} · Strength missing`;
        }
        return countPart;
    }
    const remaining = getPurchaseRemainingDisplayAmount(purchase);
    const unit = getPurchaseRemainingDisplayUnit(purchase);
    const base = formatAmountWithUnit(remaining, unit);
    const bought = getPurchaseQuantityBought(purchase);
    if (!isPercentRemainingUnit(purchase.unit || unit) || bought <= 0) return base;
    return `${base} (${formatPercentRemainingLabel(remaining, bought)})`;
}

function formatPurchaseOptionLabel(purchase) {
    const remaining = getPurchaseRemainingDisplayAmount(purchase);
    const store = purchase.store || purchase.location || '';
    const storePart = store ? ` — ${store}` : '';
    if (isVapePuffPurchase(purchase)) {
        const full = getVapeFullPuffCount(purchase);
        const starting = getVapeStartingPuffsLeft(purchase);
        const pct = getPurchasePercentRemaining(purchase);
        const pctBought = getVapePercentBoughtAt(purchase);
        const title = formatVapePurchaseTitleLine(purchase);
        const boughtPart = isGiftReceivedVapeWithoutKnownPuffCount(purchase)
            ? `${pctBought}% on receipt`
            : (pctBought < 100
                ? `${formatAmount(full)} @100% · bought at ${pctBought}% · ${formatAmount(starting)} started`
                : (formatVapePurchaseDetailLine(purchase) || `${formatAmount(full)} puffs`));
        return `${formatDate(purchase.date)} — ${title} — ${boughtPart} — ${formatAmountWithUnit(remaining, 'puffs')} left (${pct}%)${storePart}`;
    }
    if (isLsdPurchase(purchase)) {
        return `${formatDate(purchase.date)} — ${formatLsdPurchaseDisplayLine(purchase)} — ${formatLsdRemainingDisplay(purchase)} left${storePart}`;
    }
    if (isXanaxPurchase(purchase)) {
        return `${formatDate(purchase.date)} — ${formatXanaxPurchaseDisplayLine(purchase)} — ${formatXanaxRemainingDisplay(purchase)}${storePart}`;
    }
    const bought = getPurchaseQuantityBought(purchase);
    const unit = getPurchaseRemainingDisplayUnit(purchase);
    const pctPart = isPercentRemainingUnit(purchase.unit || unit) && bought > 0
        ? ` (${formatPercentRemainingLabel(remaining, bought)})`
        : '';
    return `${formatDate(purchase.date)} — ${formatAmountWithUnit(bought, unit)} bought — ${formatAmountWithUnit(remaining, unit)} left${pctPart}${storePart}`;
}

function updateUseLogModeUI() {
    updateVapeUseFormUI();
}

function getUseFormEffectiveAmount() {
    if (isVapeSessionFormActive()) {
        const calc = computeVapeUseFromForm({ editingId: editingUseId || null });
        if (calc && !calc.error) return calc.estimatedPuffsUsed ?? calc.puffsUsed;
    }
    return parseFloat(document.getElementById('use-amount')?.value) || 0;
}

function formatLinkedPurchaseDisplay(log) {
    return getLinkedSupplyLabel(log);
}

function getUsePurchaseLinkMode() {
    return document.getElementById('use-purchase-link-mode')?.value || 'auto';
}

function setUsePurchaseLinkMode(mode) {
    const el = document.getElementById('use-purchase-link-mode');
    if (el) el.value = mode;
    updateUsePurchaseLinkUI();
}

function parsePurchaseSelectId(val) {
    if (val == null || val === '') return null;
    const parsed = parseInt(val, 10);
    return Number.isNaN(parsed) ? val : parsed;
}

function resolveLinkedPurchaseId(substanceId, transactionType = 'use', options = {}) {
    const mode = getUsePurchaseLinkMode();
    if (mode === 'none') return null;

    const nicotineProductType = options.nicotineProductType || null;
    const weedProductType = options.weedProductType
        || (isWeedTrackingMode(substanceId) ? getWeedUseProductType() : null);
    const pickPurchase = () => {
        if (nicotineProductType && isNicotineTrackingMode(substanceId)) {
            return getOldestActivePurchase(substanceId, nicotineProductType);
        }
        if (weedProductType && isWeedTrackingMode(substanceId)) {
            return getOldestActivePurchase(substanceId, null, { weedProductType });
        }
        return getOldestActivePurchase(substanceId);
    };

    const addsInventory = transactionType === 'gift_received'
        || (transactionType === 'inventory_adjustment' && getUseAdjustmentDirection() === 'add');

    if (addsInventory) {
        if (mode === 'manual') {
            const val = document.getElementById('use-purchase-select')?.value;
            return val ? parsePurchaseSelectId(val) : null;
        }
        if (nicotineProductType && isNicotineTrackingMode(substanceId)) {
            const purchase = pickPurchase();
            return purchase?.id ?? resolveGiftReceivedPurchaseId(substanceId);
        }
        return resolveGiftReceivedPurchaseId(substanceId);
    }

    if (mode === 'manual') {
        const val = document.getElementById('use-purchase-select')?.value;
        return val ? parsePurchaseSelectId(val) : null;
    }

    if (isNicotineVapeFormContext(substanceId)) {
        const selected = getSelectedVapePurchaseId();
        if (selected) return selected;
        const logDate = document.getElementById('use-date')?.value || getLocalDateString();
        const purchase = findVapePurchaseForLogDate(substanceId, logDate);
        return purchase?.id ?? null;
    }

    const oldest = pickPurchase();
    return oldest ? oldest.id : null;
}

function restorePurchaseAmount(purchaseId, amount) {
    if (!purchaseId) return;
    const purchase = findPurchase(purchaseId);
    if (!purchase) return;
    const amt = parseFloat(amount) || 0;
    if (amt <= 0) return;
    const cap = getPurchaseQuantityBought(purchase);
    purchase.remainingAmount = Math.min(cap, getPurchaseRemainingAmount(purchase) + amt);
    finalizePurchaseRemainingState(purchase);
    purchase.updatedAt = new Date().toISOString();
}

function restoreLogInventoryEffect(log, data = appData) {
    if (!hasLinkedSupply(log)) return;

    const purchases = data.purchases || [];
    if (log.logMode === 'vape_puffs' || log.logMode === 'percent_remaining') {
        const pid = getLogPurchaseId(log);
        if (pid) recalculateVapePurchaseInventory(pid, data, { excludeLogId: log.id });
        return;
    }
    const applyRestore = (purchase, amt) => {
        if (!purchase || amt <= 0) return;
        if (isGiftReceivedLog(log) || inventoryAdjustmentAdds(log)) {
            subtractPurchaseRemainingInData(purchase, amt);
        } else {
            const cap = getPurchaseQuantityBought(purchase);
            purchase.remainingAmount = Math.min(cap, getPurchaseRemainingAmount(purchase) + amt);
            finalizePurchaseRemainingState(purchase);
            if (isLsdPurchase(purchase)) syncLsdPurchaseRemaining(purchase);
            if (isXanaxPurchase(purchase)) syncXanaxPurchaseRemaining(purchase);
            if (isWeedEdiblesPurchase(purchase)) syncWeedEdiblePurchaseRemaining(purchase);
        }
    };

    if (log.linkedPurchases?.length) {
        log.linkedPurchases.forEach(alloc => {
            const purchase = findPurchaseInData(alloc.purchaseId, { purchases });
            applyRestore(purchase, parseFloat(alloc.amountUsed ?? alloc.amount) || 0);
        });
    } else {
        const pid = getLogPurchaseId(log);
        if (pid) {
            const purchase = findPurchaseInData(pid, { purchases });
            applyRestore(purchase, parseFloat(log.amount) || 0);
        }
    }
}

function restoreLogSupplyLinks(log, data = appData) {
    restoreLogInventoryEffect(log, data);
    setLogPurchaseId(log, null);
}

function getPurchasesForManualLink(substanceId) {
    return (appData.purchases || [])
        .filter(p => getPurchaseSubstanceId(p) === substanceId && purchaseIsPersonalUseInventory(p))
        .sort((a, b) => getPurchaseDatetimeMs(b) - getPurchaseDatetimeMs(a));
}

function applyLogLinkAllocations(log, allocations, { forceSplitArray = false } = {}) {
    if (allocations.length === 1 && !forceSplitArray) {
        setLogPurchaseId(log, allocations[0].purchaseId);
    } else if (allocations.length >= 1) {
        log.linkedPurchases = allocations;
        log.purchaseId = null;
        log.linkedPurchaseId = null;
        log.inventoryAffects = true;
        log.supplyUnlinked = false;
    } else {
        setLogPurchaseId(log, null);
    }
}

function setLogPurchaseLink(log, purchaseId, amount, { split = false } = {}) {
    const amt = parseFloat(amount) || 0;
    log.updatedAt = new Date().toISOString();
    if (split) {
        log.purchaseId = null;
        log.linkedPurchaseId = null;
        log.linkedPurchases = [{ purchaseId, amountUsed: amt }];
        log.inventoryAffects = true;
        log.supplyUnlinked = false;
    } else {
        setLogPurchaseId(log, purchaseId);
    }
}

function manualFifoLinkFromPurchase(log, purchases, startPurchaseId, { allowOverdraw } = {}) {
    const amount = parseFloat(log.amount) || 0;
    if (amount <= INVENTORY_EPS) {
        applyLogLinkAllocations(log, []);
        return { allocations: [], overdraw: 0 };
    }

    const substanceId = getUseSubstanceId(log);
    const sorted = purchases
        .filter(p => getPurchaseSubstanceId(p) === substanceId)
        .sort((a, b) => getPurchaseDatetimeMs(a) - getPurchaseDatetimeMs(b));
    const startIdx = sorted.findIndex(p => p.id === startPurchaseId || String(p.id) === String(startPurchaseId));
    const eligible = startIdx >= 0 ? sorted.slice(startIdx) : sorted;

    let amountLeft = amount;
    const allocations = [];
    let overdraw = 0;

    for (let i = 0; i < eligible.length && amountLeft > INVENTORY_EPS; i++) {
        const purchase = eligible[i];
        const remaining = getPurchaseRemainingAmount(purchase);
        let used = 0;

        if (allowOverdraw && i === 0) {
            used = amountLeft;
            purchase.remainingAmount = remaining - used;
            if (purchase.remainingAmount < -INVENTORY_EPS) {
                overdraw += Math.abs(purchase.remainingAmount);
            }
            finalizePurchaseRemainingState(purchase);
            allocations.push({ purchaseId: purchase.id, amountUsed: used });
            amountLeft = 0;
            break;
        }

        if (remaining <= INVENTORY_EPS) continue;
        used = Math.min(amountLeft, remaining);
        if (used <= INVENTORY_EPS) continue;
        purchase.remainingAmount = Math.max(0, remaining - used);
        finalizePurchaseRemainingState(purchase);
        allocations.push({ purchaseId: purchase.id, amountUsed: used });
        amountLeft -= used;
    }

    if (amountLeft > INVENTORY_EPS) {
        overdraw += amountLeft;
    }

    applyLogLinkAllocations(log, allocations);
    return { allocations, overdraw };
}

function getManualBulkLinkOptionsFromUI() {
    return {
        resetOldLinksFirst: !!document.getElementById('manual-link-reset')?.checked,
        allowOverdraw: !!document.getElementById('manual-link-overdraw')?.checked,
        splitIntoNext: !!document.getElementById('manual-link-split')?.checked
    };
}

function getManualBulkLinkSubstanceId() {
    const val = document.getElementById('manual-link-substance')?.value;
    return val || null;
}

function getManualBulkLinkPurchaseId() {
    const val = document.getElementById('manual-link-purchase')?.value;
    if (!val) return null;
    const parsed = parseInt(val, 10);
    return Number.isNaN(parsed) ? val : parsed;
}

function getSelectedLogsForManualLink(substanceId, data = appData) {
    const ids = [...useHistorySelection];
    return ids
        .map(id => (data.logs || []).find(l => l.id === id || String(l.id) === String(id)))
        .filter(Boolean)
        .filter(l => !substanceId || getUseSubstanceId(l) === substanceId)
        .sort((a, b) => getLogDatetimeMs(a) - getLogDatetimeMs(b));
}

function runManualBulkLinkOnData(data, selectedIds, purchaseId, options) {
    const purchases = data.purchases || [];
    const primary = findPurchaseInData(purchaseId, data);
    if (!primary) return 'Selected purchase not found.';

    const substanceId = getPurchaseSubstanceId(primary);
    const selectedLogs = (data.logs || [])
        .filter(l => selectedIds.some(id => l.id === id || String(l.id) === String(id)))
        .filter(l => getUseSubstanceId(l) === substanceId)
        .sort((a, b) => getLogDatetimeMs(a) - getLogDatetimeMs(b));

    if (!selectedLogs.length) {
        return 'No selected sessions match this substance.';
    }

    const totalAmount = selectedLogs.reduce((s, l) => s + (parseFloat(l.amount) || 0), 0);
    const unit = selectedLogs[0]?.unit || getSubstance(substanceId, data)?.defaultUnit || 'units';

    if (options.resetOldLinksFirst) {
        selectedLogs.forEach(log => restoreLogSupplyLinks(log, data));
    }

    const remainingBefore = getPurchaseRemainingAmount(primary);

    let totalOverdraw = 0;

    if (options.splitIntoNext) {
        selectedLogs.forEach(log => {
            const result = manualFifoLinkFromPurchase(log, purchases, purchaseId, {
                allowOverdraw: options.allowOverdraw
            });
            log.inventoryAffects = true;
            log.updatedAt = new Date().toISOString();
            if (result.allocations.length === 1) {
                applyLogLinkAllocations(log, result.allocations, { forceSplitArray: true });
            }
            totalOverdraw += result.overdraw;
        });
        purchases.forEach(finalizePurchaseRemainingState);
    } else {
        selectedLogs.forEach(log => {
            setLogPurchaseLink(log, primary.id, parseFloat(log.amount) || 0, { split: false });
        });

        if (options.allowOverdraw) {
            primary.remainingAmount = remainingBefore - totalAmount;
            totalOverdraw = Math.max(0, totalAmount - remainingBefore);
        } else {
            const used = Math.min(totalAmount, remainingBefore);
            primary.remainingAmount = Math.max(0, remainingBefore - used);
            totalOverdraw = Math.max(0, totalAmount - used);
        }
        finalizePurchaseRemainingState(primary);
    }

    const remainingAfter = getPurchaseRemainingAmount(primary);

    return {
        ok: true,
        stats: {
            sessionCount: selectedLogs.length,
            totalAmount,
            unit,
            purchaseLabel: formatPurchaseOptionLabel(primary),
            remainingBefore,
            remainingAfter,
            overdraw: totalOverdraw
        }
    };
}

function buildManualBulkLinkPreviewStats(data, selectedIds, purchaseId, options) {
    const working = JSON.parse(JSON.stringify(data));
    const result = runManualBulkLinkOnData(working, selectedIds, purchaseId, options);
    if (typeof result === 'string') return { error: result };
    return result.stats;
}

function formatManualBulkLinkPreview(stats) {
    if (!stats) {
        return '<p class="empty-hint">Choose a purchase to preview.</p>';
    }
    if (stats.error) {
        return `<p class="empty-hint">${stats.error}</p>`;
    }
    const unit = stats.unit || 'units';
    const overdrawLine = stats.overdraw > INVENTORY_EPS
        ? `<li><strong>Overdraw:</strong> ${stats.overdraw.toFixed(2)} ${unit}</li>`
        : '';
    return `
        <ul class="bulk-link-summary-list">
            <li><strong>Selected sessions:</strong> ${stats.sessionCount}</li>
            <li><strong>Total amount:</strong> ${stats.totalAmount.toFixed(2)} ${unit}</li>
            <li><strong>Supply selected:</strong> ${stats.purchaseLabel}</li>
            <li><strong>Remaining before:</strong> ${stats.remainingBefore.toFixed(2)} ${unit}</li>
            <li><strong>Remaining after:</strong> ${stats.remainingAfter.toFixed(2)} ${unit}</li>
            ${overdrawLine}
        </ul>
    `;
}

function deductPurchaseAmount(purchaseId, amount, data = appData) {
    if (!purchaseId) return { ok: true };
    const purchase = findPurchaseInData(purchaseId, data);
    if (!purchase) return { ok: false, error: 'Linked purchase not found.' };
    const amt = parseFloat(amount) || 0;
    if (isWeedCartPurchase(purchase, data)) {
        // Cart percent inventory clamps at 0% instead of rejecting overdrafts.
        deductPurchaseRemainingInData(purchase, amt);
        purchase.updatedAt = new Date().toISOString();
        return { ok: true };
    }
    const remaining = getPurchaseRemainingAmount(purchase);
    if (amt > remaining + 0.0001) {
        return {
            ok: false,
            error: `Only ${formatAmount(remaining)} ${purchase.unit || 'units'} left in that inventory item.`
        };
    }
    purchase.remainingAmount = Math.max(0, remaining - amt);
    finalizePurchaseRemainingState(purchase);
    if (isLsdPurchase(purchase)) syncLsdPurchaseRemaining(purchase);
    if (isXanaxPurchase(purchase)) syncXanaxPurchaseRemaining(purchase);
    if (isWeedEdiblesPurchase(purchase)) syncWeedEdiblePurchaseRemaining(purchase);
    purchase.updatedAt = new Date().toISOString();
    return { ok: true };
}

function getTotalRemainingSupply(substanceId) {
    return (appData.purchases || [])
        .filter(p => getPurchaseSubstanceId(p) === substanceId
            && purchaseIsPersonalUseInventory(p)
            && !p.isDepleted)
        .reduce((s, p) => s + getPurchaseRemainingAmount(p), 0);
}

function getGiftMetrics(substanceId, bounds = null, data = appData) {
    let logs = getUseEntries(data).filter(l => logMatchesSubstance(l, substanceId, data));
    if (bounds?.startDate || bounds?.endDate) {
        logs = filterLogsByDateRange(logs, bounds.startDate, bounds.endDate);
    }
    const metrics = getGiftMetricsFromLogs(logs);
    let giftPurchases = (data.purchases || []).filter(p =>
        purchaseMatchesSubstance(p, substanceId, data) && purchaseIsPurchasedAsGift(p)
    );
    if (bounds?.startDate || bounds?.endDate) {
        giftPurchases = giftPurchases.filter(p => purchaseInDateRange(p, bounds.startDate, bounds.endDate));
    }
    giftPurchases.forEach(p => {
        const amt = getPurchaseQuantityBought(p);
        if (!(amt > 0)) return;
        metrics.given += amt;
        const name = getPurchaseGiftRecipient(p) || 'Unknown';
        metrics.recipients[name] = (metrics.recipients[name] || 0) + amt;
    });
    metrics.net = metrics.received - metrics.given;
    return metrics;
}

function getGiftMetricsFromLogs(logs) {
    let given = 0;
    let received = 0;
    let shared = 0;
    const recipients = {};
    const senders = {};
    const sharedWith = {};
    (logs || []).forEach(l => {
        const amt = getLogInventoryDeductionAmount(l);
        if (isGiftGivenLog(l)) {
            given += amt;
            const name = l.recipientName?.trim() || l.giftPartyName?.trim() || 'Unknown';
            recipients[name] = (recipients[name] || 0) + amt;
        } else if (isGiftReceivedLog(l)) {
            received += amt;
            const name = l.giverName?.trim() || l.giftPartyName?.trim() || 'Unknown';
            senders[name] = (senders[name] || 0) + amt;
        } else if (isSharedUseLog(l)) {
            const sharedAmt = getLogSharedAmount(l);
            shared += sharedAmt;
            const name = l.sharedWithName?.trim() || 'Unknown';
            sharedWith[name] = (sharedWith[name] || 0) + sharedAmt;
        }
    });
    return { given, received, shared, net: received - given, recipients, senders, sharedWith };
}

function getInventoryBreakdown(substanceId) {
    const purchases = (appData.purchases || []).filter(p => getPurchaseSubstanceId(p) === substanceId);
    const purchased = purchases.reduce((s, p) => s + getPurchaseQuantityBought(p), 0);
    const logs = getUseEntries().filter(l => logMatchesSubstance(l, substanceId));
    let used = 0;
    let gifted = 0;
    let received = 0;
    let shared = 0;
    logs.forEach(l => {
        if (isPersonalUseLog(l)) used += getLogStatsAmount(l);
        else if (isSharedUseLog(l)) {
            used += getLogPersonalAmount(l);
            shared += getLogSharedAmount(l);
        }
        else if (isGiftGivenLog(l)) gifted += getLogInventoryDeductionAmount(l);
        else if (isGiftReceivedLog(l)) received += getLogInventoryDeductionAmount(l);
    });
    return {
        purchased,
        used,
        gifted,
        received,
        shared,
        remaining: getTotalRemainingSupply(substanceId)
    };
}

function getCurrentBagPurchase(substanceId) {
    return getOldestActivePurchase(substanceId);
}

function getAverageDailyUse(substanceId, days = 7) {
    const today = new Date();
    let total = 0;
    let dayCount = 0;
    for (let i = 0; i < days; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() - i);
        const dateStr = getLocalDateString(d);
        total += isVapeNicotineSubstanceId(substanceId)
            ? getStatsUsageOnDate(substanceId, dateStr)
            : getUsedAmount(substanceId, dateStr);
        dayCount++;
    }
    return dayCount ? total / dayCount : 0;
}

function getCostPerUnitFromPurchase(purchaseId) {
    const p = findPurchase(purchaseId);
    if (!p) return null;
    const cpu = parseFloat(p.costPerUnit);
    if (Number.isFinite(cpu) && cpu > 0) return cpu;
    const qty = getPurchaseQuantityBought(p);
    const total = parseFloat(getPurchaseTotalCost(p)) || 0;
    return qty > 0 ? total / qty : null;
}

function updateUsePurchaseLinkUI() {
    const mode = getUsePurchaseLinkMode();
    const manualWrap = document.getElementById('use-purchase-manual-wrap');
    const select = document.getElementById('use-purchase-select');
    const preview = document.getElementById('use-purchase-preview');
    const substanceId = document.getElementById('use-substance')?.value;
    const transactionType = document.getElementById('use-transaction-type')?.value || 'use';
    const isReceived = transactionType === 'gift_received';
    const isGiven = transactionType === 'gift_given';
    const isAdjustment = transactionType === 'inventory_adjustment';
    const adjustmentAdds = isAdjustment && getUseAdjustmentDirection() === 'add';
    const addsInventory = isReceived || adjustmentAdds;

    const linkLabel = document.getElementById('use-purchase-link-label');
    if (linkLabel) {
        if (addsInventory) linkLabel.textContent = 'Add to Inventory';
        else if (isAdjustment) linkLabel.textContent = 'Remove from Inventory';
        else linkLabel.textContent = 'Use From Inventory';
    }

    const isVapeUse = isVapeSessionFormActive();
    const nicotineProductType = isNicotineTrackingMode(substanceId) ? getUseFormNicotineProductType() : null;

    if (manualWrap) manualWrap.classList.toggle('hidden', mode !== 'manual' && !isVapeUse);

    const weedProductType = isWeedTrackingMode(substanceId) ? getWeedUseProductType() : null;

    if ((mode === 'manual' || isVapeUse) && select && substanceId) {
        let active = addsInventory
            ? getPurchasesForManualLink(substanceId)
            : getActivePurchasesForSubstance(substanceId);
        if (weedProductType) {
            active = active.filter(p => purchaseMatchesWeedProductType(p, weedProductType));
        }
        if (nicotineProductType && isNicotineTrackingMode(substanceId)) {
            active = active.filter(p => getNicotineProductType(p) === nicotineProductType);
        }
        if (editingUseId) {
            const entry = findUseEntry(editingUseId);
            const linkedIds = new Set();
            const entryPid = getLogPurchaseId(entry);
            if (entryPid) linkedIds.add(String(entryPid));
            if (entry?.linkedPurchases?.length) {
                entry.linkedPurchases.forEach(lp => linkedIds.add(String(lp.purchaseId)));
            }
            linkedIds.forEach(linkedId => {
                const linked = (appData.purchases || []).find(p => String(p.id) === linkedId);
                if (linked && !active.some(p => String(p.id) === linkedId)) {
                    active = [linked, ...active];
                }
            });
        }
        const currentVal = select.value;
        select.innerHTML = '<option value="">No linked purchase</option>';
        active.forEach(p => {
            const opt = document.createElement('option');
            opt.value = String(p.id);
            opt.textContent = formatPurchaseOptionLabel(p);
            select.appendChild(opt);
        });
        if (currentVal && [...select.options].some(o => o.value === currentVal || String(o.value) === String(currentVal))) {
            select.value = [...select.options].find(o => o.value === currentVal || String(o.value) === String(currentVal)).value;
        } else if (currentVal) {
            select.value = '';
        }
    }

    if (preview) {
        if (mode === 'none') {
            preview.textContent = 'This entry will save without changing inventory.';
            preview.classList.remove('hidden');
        } else if (!substanceId) {
            preview.classList.add('hidden');
        } else if (addsInventory) {
            if (mode === 'auto') {
                const target = resolveGiftReceivedPurchaseInData(substanceId, appData.purchases || []);
                preview.textContent = target
                    ? `Auto add to: ${formatPurchaseOptionLabel(target)}`
                    : 'No purchase found — will save without changing inventory.';
            } else {
                const id = select?.value;
                const bag = id ? findPurchase(parsePurchaseSelectId(id)) : null;
                preview.textContent = bag
                    ? `Add to: ${formatPurchaseOptionLabel(bag)}`
                    : 'Choose a purchase to add to, or select No linked purchase.';
            }
            preview.classList.remove('hidden');
        } else if (mode === 'auto') {
            if (isVapeUse) {
                const id = select?.value;
                const bag = id ? findPurchase(parsePurchaseSelectId(id)) : null;
                preview.textContent = bag
                    ? `Using: ${formatPurchaseOptionLabel(bag)}`
                    : 'Select a vape inventory item for this log.';
                preview.classList.remove('hidden');
            } else {
                const bag = weedProductType
                    ? getOldestActivePurchase(substanceId, null, { weedProductType })
                    : (nicotineProductType
                        ? getOldestActivePurchase(substanceId, nicotineProductType)
                        : getOldestActivePurchase(substanceId));
                if (bag) {
                    preview.textContent = isGiven
                        ? `Auto deduct (gift): ${formatPurchaseOptionLabel(bag)}`
                        : `Auto: ${formatPurchaseOptionLabel(bag)}`;
                    preview.classList.remove('hidden');
                } else {
                    preview.textContent = 'No active supply — will save without changing inventory.';
                    preview.classList.remove('hidden');
                }
            }
        } else if (mode === 'manual') {
            const id = select?.value;
            const purchaseId = id ? parsePurchaseSelectId(id) : null;
            const amount = parseFloat(document.getElementById('use-amount')?.value) || 0;
            const unit = document.getElementById('use-unit')?.value || 'units';
            if (purchaseId) {
                const previewLog = {
                    purchaseId,
                    linkedPurchaseId: purchaseId,
                    linkedPurchases: [],
                    unit,
                    inventoryAffects: true
                };
                preview.textContent = getLinkedSupplyLabel(previewLog);
            } else {
                preview.textContent = 'Choose a purchase with remaining supply, or select No linked purchase.';
            }
            preview.classList.remove('hidden');
        }
    }

    syncWeedProductTypeFromPurchase();
    if (isWeedTrackingMode(substanceId) && getWeedUseProductType({ allowEmpty: true }) === 'cart') {
        syncWeedCartPercentBeforeFromInventory();
        updateWeedCartUsePreview();
    }
    if (isWeedTrackingMode(substanceId) && getWeedUseProductType({ allowEmpty: true }) === 'edibles') {
        syncWeedEdibleStrengthFromInventory({ force: editingUseId == null });
        updateWeedEdibleUsePreview();
    }
}

function updateCurrentSupplyDashboard() {
    const set = (id, text) => { const el = document.getElementById(id); if (el) el.textContent = text; };
    const titleEl = document.getElementById('dash-supply-card-title');
    const standardRows = document.getElementById('dash-supply-rows-standard');
    const allContainer = document.getElementById('dash-supply-all-substances');

    if (isAllSubstancesView()) {
        if (titleEl) titleEl.textContent = 'Inventory (all)';
        standardRows?.classList.add('hidden');
        allContainer?.classList.remove('hidden');
        renderAllSubstancesInventoryDashboard(allContainer);
        return;
    }

    if (titleEl) titleEl.textContent = 'Inventory';
    standardRows?.classList.remove('hidden');
    allContainer?.classList.add('hidden');

    const substanceId = currentSubstanceId;
    if (!substanceId || substanceId === DASHBOARD_ALL) {
        set('dash-supply-total', '—');
        set('dash-supply-remaining', '—');
        set('dash-supply-days-left', '—');
        set('dash-supply-last-buy-date', '—');
        set('dash-supply-last-used', '—');
        set('dash-supply-since-last-use', '—');
        return;
    }
    const sub = getSubstance(substanceId);
    const unit = getSubstanceDisplayUnit(substanceId);
    const totalRemaining = getTotalRemainingSupply(substanceId);
    const purchases = (appData.purchases || [])
        .filter(p => purchaseMatchesSubstance(p, substanceId))
        .sort((a, b) => getPurchaseDatetimeMs(b) - getPurchaseDatetimeMs(a));
    const lastPurchase = purchases[0] || null;
    const dailyAvg = getAverageDailyUse(substanceId);

    const remainingLabel = `${totalRemaining.toFixed(1)} ${unit}`;
    set('dash-supply-total', remainingLabel);
    set('dash-supply-remaining', remainingLabel);

    if (dailyAvg > 0 && totalRemaining > 0) {
        set('dash-supply-days-left', `~${Math.round(totalRemaining / dailyAvg)} days`);
    } else {
        set('dash-supply-days-left', '—');
    }

    if (lastPurchase) {
        const summary = isVapePuffPurchase(lastPurchase)
            ? formatVapePurchaseTitleLine(lastPurchase)
            : (lastPurchase.store || lastPurchase.location || '');
        set('dash-supply-last-buy-date', summary
            ? `${formatDate(lastPurchase.date)} · ${summary}`
            : formatDate(lastPurchase.date));
    } else {
        set('dash-supply-last-buy-date', '—');
    }

    const currentBag = getOldestActivePurchase(substanceId);
    if (currentBag) {
        const bagMetrics = getPurchaseSupplyMetrics(currentBag);
        set('dash-supply-last-used', bagMetrics.lastSupplyUseAt
            ? formatDatetimeShort(bagMetrics.lastSupplyUseAt)
            : 'Never');
        set('dash-supply-since-last-use', bagMetrics.timeSinceLastSupplyUse != null
            ? formatTimeSinceMs(bagMetrics.timeSinceLastSupplyUse)
            : '—');
    } else {
        set('dash-supply-last-used', '—');
        set('dash-supply-since-last-use', '—');
    }
}

function updateGiftMetricsDashboard() {
    const set = (id, text) => { const el = document.getElementById(id); if (el) el.textContent = text; };
    const substanceId = isAllSubstancesView() ? getMainSubstanceId() : currentSubstanceId;
    if (!substanceId) {
        set('dash-gift-given', '—');
        set('dash-gift-received', '—');
        set('dash-gift-net', 'Net: —');
        return;
    }
    const sub = getSubstance(substanceId);
    const unit = sub?.defaultUnit || 'units';
    const metrics = getGiftMetrics(substanceId);
    set('dash-gift-given', `${metrics.given.toFixed(1)}${unit}`);
    set('dash-gift-received', `${metrics.received.toFixed(1)}${unit}`);
    const netLabel = metrics.net >= 0 ? `+${metrics.net.toFixed(1)}` : metrics.net.toFixed(1);
    set('dash-gift-net', `Net: ${netLabel}${unit}`);
}

function refreshTaperDashboard() {
    renderTaperPlan();
    checkTaperTarget();
}

function editUseEntry(id) {
    const entry = findUseEntry(id);
    if (!entry) return;

    if (isPercentLeftDistributedChildLog(entry)) {
        editUseEntry(entry.parentPercentLogId);
        return;
    }
    if (isAlcoholMultiDayChildLog(entry)) {
        editUseEntry(entry.parentLogId);
        return;
    }

    editingUseId = id;
    const isVape = isVapeUseLog(entry);
    const isWeed = isWeedTrackingMode(getUseSubstanceId(entry));
    const isLsd = isLsdSubstanceId(getUseSubstanceId(entry));
    const isXanax = isXanaxSubstanceId(getUseSubstanceId(entry));
    const isNicotineNonVape = isNicotineSubstanceId(getUseSubstanceId(entry)) && !isVape;
    const isAlcohol = isAlcoholTrackingMode(getUseSubstanceId(entry));

    if (isVape) {
        populateUseFormFromVapeLog(entry);
        setInputValue('use-count', getUseCount(entry));
        setUseFormSubmitLabel('Update Entry');
        document.getElementById('cancel-use-edit-btn')?.classList.remove('hidden');
        switchTab('use-log-tab');
        document.getElementById('use-log-form')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        return;
    }

    if (isAlcohol) {
        const substanceSelect = document.getElementById('use-substance');
        if (substanceSelect && [...substanceSelect.options].some(o => o.value === 'alcohol')) {
            substanceSelect.value = 'alcohol';
        }
        updateUseUnitDropdown();
        if (isInventoryAdjustmentLog(entry)) {
            setUseAdjustmentDirection(getAdjustmentDirection(entry));
        }
        populateUseFormFromAlcoholLog(entry);
        setInputValue('use-count', getUseCount(entry));
        setUseFormSubmitLabel('Update Entry');
        document.getElementById('cancel-use-edit-btn')?.classList.remove('hidden');
        switchTab('use-log-tab');
        document.getElementById('use-log-form')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        return;
    }

    if (isSharedUseLog(entry)) {
        setLegacySharedUseFormTransactionType();
        setUseLogType(isWeed || isLsd || isXanax ? 'quick' : getUseLogType(entry));
    } else if (isWeed || isLsd || isXanax) {
        setUseTransactionType(getLogTransactionType(entry));
        setUseLogType('quick');
        if (isInventoryAdjustmentLog(entry)) {
            setUseAdjustmentDirection(getAdjustmentDirection(entry));
        }
    } else {
        setUseTransactionType(getLogTransactionType(entry));
        setUseLogType(getUseLogType(entry));
        if (isInventoryAdjustmentLog(entry)) {
            setUseAdjustmentDirection(getAdjustmentDirection(entry));
        }
    }

    const substanceId = getUseSubstanceId(entry);
    const formSubstanceId = isNicotineSubstanceId(substanceId) ? NICOTINE_ID : substanceId;
    const substanceSelect = document.getElementById('use-substance');
    if (substanceSelect && formSubstanceId && [...substanceSelect.options].some(o => o.value === formSubstanceId)) {
        substanceSelect.value = formSubstanceId;
    } else if (substanceSelect && substanceId && [...substanceSelect.options].some(o => o.value === substanceId)) {
        substanceSelect.value = substanceId;
    }
    updateUseUnitDropdown();

    const unit = entry.unit || 'units';
    const unitSelect = document.getElementById('use-unit');
    if (unitSelect) {
        if (unit && ![...unitSelect.options].some(o => o.value === unit)) {
            const option = document.createElement('option');
            option.value = unit;
            option.textContent = unit;
            unitSelect.appendChild(option);
        }
        unitSelect.value = unit;
    }

    setInputValue('use-date', entry.date || '');
    if (isNicotineNonVape) {
        setInputValue('use-nicotine-product-type', getNicotineProductType(entry));
        setInputValue('use-cigarettes-smoked', entry.cigarettesUsed ?? (getNicotineProductType(entry) === 'cigarettes' ? entry.amount : '') ?? '');
        setInputValue('use-pouches-used', entry.pouchesUsed ?? (getNicotineProductType(entry) === 'pouches' ? entry.amount : '') ?? '');
        setInputValue('use-gum-pieces-used', entry.piecesUsed ?? (getNicotineProductType(entry) === 'gum' ? entry.amount : '') ?? '');
        setInputValue('use-patches-used', entry.patchesUsed ?? (getNicotineProductType(entry) === 'patches' ? entry.amount : '') ?? '');
        setInputValue('use-patch-hours-worn', entry.patchHoursWorn ?? '');
        setInputValue('use-start-time', '');
        setInputValue('use-end-date', '');
        setInputValue('use-end-time', '');
        updateUseNicotineProductTypeUI();
    } else if (isWeed || isLsd || isXanax) {
        if (isWeed) {
            const savedType = normalizeWeedProductType(entry.weedProductType, { allowEmpty: true });
            if (savedType) {
                setWeedUseProductType(savedType);
                updateWeedProductTypeReviewHint(false);
            } else {
                const sel = document.getElementById('use-weed-product-type');
                if (sel) sel.value = '';
                updateWeedProductTypeReviewHint(true);
            }
        }
        if (isLsd || (isXanax && !isPersonalUseLog(entry))) {
            setInputValue('use-start-time', entry.startTime || entry.time || getLocalTimeString(new Date()));
        } else {
            setInputValue('use-start-time', '');
        }
        setInputValue('use-end-date', '');
        setInputValue('use-end-time', '');
        updateVapeUseFormUI();
    } else {
        setInputValue('use-start-time', entry.startTime || entry.time || '12:00');
        const inferredEndDate = entry.endDate
            || inferEndDate(entry.date, entry.startTime || entry.time, entry.endTime)
            || entry.date
            || '';
        setInputValue('use-end-date', inferredEndDate);
        setInputValue('use-end-time', entry.endTime || '');
        const endDateEl = document.getElementById('use-end-date');
        if (endDateEl) {
            endDateEl.dataset.syncedStart = entry.date || '';
            if (entry.endDate && entry.endDate !== entry.date) {
                endDateEl.dataset.manual = '1';
            } else {
                delete endDateEl.dataset.manual;
            }
        }
        if (entry.startedAt) {
            const started = new Date(entry.startedAt);
            if (!Number.isNaN(started.getTime())) {
                setInputValue('use-date', getLocalDateString(started));
                setInputValue('use-start-time', getLocalTimeString(started));
            }
        }
        if (entry.endedAt) {
            const ended = new Date(entry.endedAt);
            if (!Number.isNaN(ended.getTime())) {
                setInputValue('use-end-date', getLocalDateString(ended));
                setInputValue('use-end-time', getLocalTimeString(ended));
            }
        }
    }
    if (isLsd) {
        const ugPerTab = entry.ugPerTabAtTimeOfUse ?? getLsdUgPerTab(findPurchase(getLogPurchaseId(entry)));
        if (entry.tabsUsed != null && entry.ugUsed != null && entry.tabsUsed * (ugPerTab || 1) === entry.ugUsed) {
            setLsdLogInputMode('tabs');
            setInputValue('use-lsd-tabs-used', entry.tabsUsed);
        } else if (entry.ugUsed != null) {
            setLsdLogInputMode('ug');
            setInputValue('use-lsd-ug-used', entry.ugUsed);
        } else if (entry.tabsUsed != null) {
            setLsdLogInputMode('tabs');
            setInputValue('use-lsd-tabs-used', entry.tabsUsed);
        } else {
            setLsdLogInputMode('ug');
            setInputValue('use-lsd-ug-used', entry.amount ?? '');
        }
        updateLsdUsePreview();
    } else if (isXanax) {
        const mgPerPill = entry.mgPerPillAtTimeOfUse ?? getXanaxMgPerPill(findPurchase(getLogPurchaseId(entry)));
        if (entry.pillsUsed != null && entry.mgUsed != null && mgPerPill > 0
            && Math.abs(entry.pillsUsed * mgPerPill - entry.mgUsed) < 0.001) {
            setXanaxLogInputMode('pills');
            setInputValue('use-xanax-pills-used', entry.pillsUsed);
        } else if (entry.mgUsed != null) {
            setXanaxLogInputMode('mg');
            setInputValue('use-xanax-mg-used', entry.mgUsed);
        } else if (entry.pillsUsed != null) {
            setXanaxLogInputMode('pills');
            setInputValue('use-xanax-pills-used', entry.pillsUsed);
        } else {
            setXanaxLogInputMode('pills');
            setInputValue('use-xanax-pills-used', entry.amount ?? '');
        }
        updateXanaxUsePreview();
    } else if (isWeed && isWeedCartPercentLog(entry)) {
        setInputValue('use-amount', '');
        setInputValue('use-percent-after', '');
        const hasCheckpoints = entry.percentBefore != null && (entry.percentLeftAfter != null || entry.percentAfter != null);
        setWeedCartLogInputMode(hasCheckpoints ? 'checkpoints' : 'estimated');
        setInputValue('use-weed-cart-percent-before', entry.percentBefore ?? '');
        setInputValue('use-weed-cart-percent-after', entry.percentLeftAfter ?? entry.percentAfter ?? '');
        setInputValue('use-weed-cart-percent-used', entry.estimatedPercentUsed ?? entry.amount ?? '');
        updateWeedCartUsePreview();
    } else if (isWeed && isWeedEdiblesLog(entry)) {
        setInputValue('use-amount', entry.amount != null ? entry.amount : '');
        setInputValue('use-percent-after', '');
        setInputValue('use-weed-cart-percent-before', '');
        setInputValue('use-weed-cart-percent-after', '');
        setInputValue('use-weed-cart-percent-used', '');
        const strength = getWeedEdibleLogStrength(entry);
        const mgInput = document.getElementById('use-weed-edible-mg-per');
        if (mgInput) {
            mgInput.value = strength != null ? String(strength) : '';
            mgInput.dataset.fromInventory = strength != null ? '1' : '';
            mgInput.readOnly = strength != null;
        }
        updateWeedEdibleUsePreview();
    } else {
        setInputValue('use-amount', entry.amount != null ? entry.amount : '');
        setInputValue('use-percent-after', '');
        setInputValue('use-weed-cart-percent-before', '');
        setInputValue('use-weed-cart-percent-after', '');
        setInputValue('use-weed-cart-percent-used', '');
    }
    setInputValue('use-count', getUseCount(entry));
    setInputValue('use-notes', entry.notes || '');
    setInputValue('use-gift-party', entry.giftPartyName || entry.recipientName || entry.giverName || '');
    if (isSharedUseLog(entry)) {
        setInputValue('use-amount', entry.totalAmount ?? entry.amount ?? '');
    }

    if (isWeed || isLsd) {
        updateVapeUseFormUI();
        if (isWeed) updateWeedUseFormUI();
        if (!hasLinkedSupply(entry) && !logInventoryAffects(entry)) {
            setUsePurchaseLinkMode('none');
        } else if (hasLinkedSupply(entry)) {
            setUsePurchaseLinkMode('manual');
            const select = document.getElementById('use-purchase-select');
            updateUsePurchaseLinkUI();
            if (select) {
                const linkedId = getLogPurchaseId(entry) || entry.linkedPurchases?.[0]?.purchaseId;
                if (linkedId != null && linkedId !== '') {
                    const match = [...select.options].find(o => String(o.value) === String(linkedId));
                    if (match) select.value = match.value;
                }
            }
        } else {
            setUsePurchaseLinkMode('auto');
        }
    } else if (!hasLinkedSupply(entry) && !logInventoryAffects(entry)) {
        setUsePurchaseLinkMode('none');
    } else if (hasLinkedSupply(entry)) {
        setUsePurchaseLinkMode('manual');
        const select = document.getElementById('use-purchase-select');
        updateUsePurchaseLinkUI();
        if (select) {
            const linkedId = getLogPurchaseId(entry) || entry.linkedPurchases?.[0]?.purchaseId;
            if (linkedId != null && linkedId !== '') {
                const match = [...select.options].find(o => String(o.value) === String(linkedId));
                if (match) select.value = match.value;
            }
        }
    } else {
        setUsePurchaseLinkMode('auto');
    }
    updateUsePurchaseLinkUI();

    setUseFormSubmitLabel('Update Entry');
    document.getElementById('cancel-use-edit-btn')?.classList.remove('hidden');
    if (!isWeed && !isLsd) {
        updateUseEndTimeVisibility();
    }
    computeUseFormDuration();
    switchTab('use-log-tab');
    document.getElementById('use-log-form')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function cancelUseEdit() {
    editingUseId = null;
    document.getElementById('use-log-form')?.reset();
    setDefaultUseLogDateTime();
    setUseLogType('quick');
    setUseFormSubmitLabel('Save Entry');
    document.getElementById('cancel-use-edit-btn')?.classList.add('hidden');
    applyMainSubstanceToForms();
    updateUseUnitDropdown();
    setUsePurchaseLinkMode('auto');
    setUseTransactionType('use');
    setUseAdjustmentDirection('add');
    updateVapeUseFormUI();
}

function getUseLogsForSubstance(substanceId, { sortAsc = true, personalUseOnly = false, statsUseOnly = false, data = appData } = {}) {
    let list = getUseEntries(data).filter(l => {
        if (!logMatchesSubstance(l, substanceId, data)) return false;
        if (statsUseOnly) {
            if (!logCountsTowardPersonalUseStats(l)) return false;
        } else if (personalUseOnly && !isPersonalUseLog(l)) {
            return false;
        }
        return true;
    });
    list = [...list].sort((a, b) => {
        const da = getLogDatetimeMs(a);
        const db = getLogDatetimeMs(b);
        return sortAsc ? da - db : db - da;
    });
    return list;
}

function getUseEndDatetime(entry) {
    const ended = getUseLogEndedAt(entry);
    if (ended) return ended;
    return getUseLogStartedAt(entry);
}

function enrichUseEntry(entry, previousEntry) {
    const isGift = !isPersonalUseLog(entry);
    const isWeedSimple = isWeedDateOnlyUseLog(entry);
    const isVapeDateOnly = isVapeDateOnlyUseLog(entry);
    const startTime = entry.startTime || entry.time;
    const start = getUseLogStartedAt(entry);
    let end = getUseLogEndedAt(entry);
    let durationHours = null;
    let startDatetime = start ? start.toISOString() : null;
    let endDatetime = end ? end.toISOString() : null;

    if (!isWeedSimple && !isVapeDateOnly) {
        if (entry.durationMs != null && entry.durationMs > 0) {
            durationHours = entry.durationMs / 3600000;
        } else if (end && start) {
            durationHours = (end - start) / 3600000;
        }
    }

    const amount = parseFloat(entry.amount) || 0;
    const useRate = (!isWeedSimple && !isVapeDateOnly && durationHours > 0) ? amount / durationHours : null;

    let timeBetweenHours = null;
    let breakDurationHours = entry.breakHours != null ? entry.breakHours : null;
    if (breakDurationHours == null && entry.breakMinutes != null) {
        breakDurationHours = entry.breakMinutes / 60;
    }
    if (breakDurationHours == null && !isGift && previousEntry && isPersonalUseLog(previousEntry) && start) {
        const prevEnd = getUseEndDatetime(previousEntry);
        if (prevEnd) {
            const gapMs = start - prevEnd;
            if (gapMs >= 0) {
                timeBetweenHours = gapMs / 3600000;
                breakDurationHours = gapMs / 3600000;
            }
        }
    } else if (breakDurationHours != null) {
        timeBetweenHours = breakDurationHours;
    }

    return {
        ...entry,
        type: entry.type || (isGift ? 'quick' : (entry.endTime ? 'session' : 'quick')),
        durationHours,
        useRate,
        timeBetweenHours,
        breakDurationHours,
        breakMinutes: entry.breakMinutes,
        breakText: entry.breakText,
        startDatetime,
        endDatetime
    };
}

function buildEnrichedUseEntries(substanceId) {
    const raw = getUseLogsForSubstance(substanceId, { sortAsc: true });
    const enriched = [];
    for (let i = 0; i < raw.length; i++) {
        enriched.push(enrichUseEntry(raw[i], i > 0 ? enriched[i - 1] : null));
    }
    return enriched;
}

function renderBreakSincePreviousCell(entry, data = appData) {
    const details = typeof getBreakBetweenUsesDetails === 'function'
        ? getBreakBetweenUsesDetails(entry, data)
        : null;
    const hours = details?.hours ?? entry.breakHours ?? entry.breakDurationHours;
    const text = details?.text
        || (hours != null && Number.isFinite(hours)
            ? formatBreakSincePreviousUse(hours)
            : '—');
    const title = details ? formatBreakBetweenUsesTooltip(details) : '';
    let html = (text === '—' || hours == null)
        ? '—'
        : `<span class="break-cell"${title ? ` title="${escapeAttr(title)}"` : ''}>${escapeHtml(text)}</span>`;
    if (hours != null && Number.isFinite(hours)) {
        html = applyConditionalColorToMetricHtml(html, {
            substanceId: getUseSubstanceId(entry, data),
            section: 'useHistory',
            metric: 'useGapPrevious',
            value: hours,
            log: entry
        }, data);
    }
    return html;
}

function getUseRowWarnings(entry, substanceId, avgRate) {
    return [];
}

function isNonUseTransactionType(tx) {
    return tx === 'gift_given' || tx === 'gift_received' || tx === 'inventory_adjustment';
}

function shouldHideUseEntryTypeGroup(substanceId = document.getElementById('use-substance')?.value) {
    const isNicotine = isNicotineTrackingMode(substanceId);
    const nicotineProductType = isNicotine ? getUseFormNicotineProductType() : null;
    const isVape = isNicotine ? nicotineProductType === 'vape' : isVapeTrackingMode(substanceId);
    const isNicotineSimple = isNicotine && nicotineProductType !== 'vape' && nicotineProductType !== 'other';
    return isVape
        || isWeedTrackingMode(substanceId)
        || isLsdSubstanceId(substanceId)
        || isXanaxSubstanceId(substanceId)
        || isNicotineSimple
        || isAlcoholTrackingMode(substanceId);
}

function syncUseEntryTypeToggleActive() {
    const tx = document.getElementById('use-transaction-type')?.value || 'use';
    const activeType = isNonUseTransactionType(tx)
        ? 'gift_adjustment'
        : (document.getElementById('use-type')?.value || 'quick');
    document.querySelectorAll('#use-entry-type-group .use-entry-toggle-btn').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.type === activeType);
    });
}

function updateUseTransactionTypePillsVisibility() {
    const substanceId = document.getElementById('use-substance')?.value;
    const hideEntryType = shouldHideUseEntryTypeGroup(substanceId);
    const tx = document.getElementById('use-transaction-type')?.value || 'use';
    const isGiftMode = isNonUseTransactionType(tx);
    const isLegacyShared = tx === 'shared_use';

    document.getElementById('use-entry-type-group')?.classList.toggle('hidden', hideEntryType);

    const showTxBlock = hideEntryType || isGiftMode || isLegacyShared;
    document.getElementById('use-transaction-type-block')?.classList.toggle('hidden', !showTxBlock);

    document.querySelectorAll('#use-transaction-type-block .use-tx-pill').forEach(btn => {
        const group = btn.dataset.txGroup
            || ((btn.dataset.tx === 'gift_given'
                || btn.dataset.tx === 'gift_received'
                || btn.dataset.tx === 'inventory_adjustment')
                ? 'gift'
                : 'use');
        let show = false;
        if (hideEntryType || isLegacyShared) {
            if (group === 'gift' || btn.dataset.tx === 'use') show = true;
        } else if (isGiftMode) {
            show = group === 'gift';
        }
        btn.classList.toggle('hidden', !show);
    });

    syncUseEntryTypeToggleActive();
}

function isNicotineTrackingUseForm() {
    return isNicotineTrackingMode(document.getElementById('use-substance')?.value);
}

function updateUseEndTimeVisibility() {
    if (isWeedDateOnlyUseForm() || isVapeDateOnlyUseForm() || isLsdDateOnlyUseForm() || isXanaxDateOnlyUseForm()) {
        document.getElementById('use-end-date-group')?.classList.add('hidden');
        document.getElementById('use-end-time-group')?.classList.add('hidden');
        return;
    }
    const tx = document.getElementById('use-transaction-type')?.value || 'use';
    const isNonUse = isNonUseTransactionType(tx);
    const type = document.getElementById('use-type')?.value || 'quick';
    const showEnd = type === 'session' || isNonUse;
    const showEndDate = shouldShowUseEndDateField();
    document.getElementById('use-end-time-group')?.classList.toggle('hidden', !showEnd);
    document.getElementById('use-end-date-group')?.classList.toggle('hidden', !showEndDate);
    document.getElementById('use-datetime-grid')?.classList.toggle('is-coke-session', showEndDate);
    const startLabel = document.getElementById('use-start-time-label');
    if (startLabel) startLabel.textContent = showEndDate ? 'Start time' : 'Start';
    document.querySelectorAll('.use-end-time-field').forEach(el => {
        el.classList.toggle('session-end-span', showEnd && !isNonUse && type === 'session' && !showEndDate);
    });
    if (showEndDate) {
        syncCokeSessionEndDateDefault();
    }
}

function selectUseEntryType(type) {
    if (type === 'gift_adjustment') {
        setUseLogType('gift_adjustment');
        return;
    }
    const tx = document.getElementById('use-transaction-type')?.value || 'use';
    if (isNonUseTransactionType(tx)) {
        const txHidden = document.getElementById('use-transaction-type');
        if (txHidden) txHidden.value = 'use';
        setUseLogType(type);
        setUseTransactionType('use');
        const typeHidden = document.getElementById('use-type');
        if (typeHidden) typeHidden.value = type;
        syncUseEntryTypeToggleActive();
        return;
    }
    setUseLogType(type);
}

function setUseLogType(type) {
    if (type === 'gift_adjustment') {
        const typeHidden = document.getElementById('use-type');
        if (typeHidden) typeHidden.value = 'quick';
        const tx = document.getElementById('use-transaction-type')?.value || 'use';
        if (!isNonUseTransactionType(tx)) {
            setUseTransactionType('gift_given');
        } else {
            updateUseTransactionTypePillsVisibility();
            updateUseEndTimeVisibility();
            computeUseFormDuration();
            syncCokeSessionEndDateDefault();
        }
        return;
    }
    if (isWeedDateOnlyUseForm() || isVapeDateOnlyUseForm()) {
        type = 'quick';
    }
    const hidden = document.getElementById('use-type');
    if (hidden) hidden.value = type;
    syncUseEntryTypeToggleActive();
    const tx = document.getElementById('use-transaction-type')?.value || 'use';
    if (type === 'quick' && !isNonUseTransactionType(tx) && !isVapeSessionFormActive()) {
        const endEl = document.getElementById('use-end-time');
        if (endEl) endEl.value = '';
    }
    updateUseEndTimeVisibility();
    computeUseFormDuration();
    syncCokeSessionEndDateDefault();
}

function setDefaultUseLogDateTime() {
    const now = new Date();
    const dateStr = getLocalDateString(now);
    const timeStr = getLocalTimeString(now);
    const dateEl = document.getElementById('use-date');
    const startEl = document.getElementById('use-start-time');
    const endDateEl = document.getElementById('use-end-date');
    const endTimeEl = document.getElementById('use-end-time');
    if (dateEl) dateEl.value = dateStr;
    if (startEl) startEl.value = timeStr;
    if (endDateEl) {
        endDateEl.value = dateStr;
        endDateEl.dataset.syncedStart = dateStr;
    }
    if (endTimeEl && !isVapeDateOnlyUseForm()) endTimeEl.value = timeStr;
}

function setupUseLogForm() {
    const form = document.getElementById('use-log-form');
    if (!form) return;
    form.addEventListener('submit', handleUseLogSubmit);
    document.getElementById('use-substance')?.addEventListener('change', () => {
        updateUseUnitDropdown();
        updateUsePurchaseLinkUI();
        if (isLsdSubstanceId(document.getElementById('use-substance')?.value)) {
            ensureLsdUseFormDefaults();
        }
        updateVapeUseFormUI();
    });
    document.getElementById('use-unit')?.addEventListener('change', () => {
        updateVapeUseFormUI();
        updateAlcoholUseFormUI();
        if (typeof updateWeedBudEstimateVisibility === 'function') updateWeedBudEstimateVisibility();
    });
    if (typeof initContactsIntegrationUi === 'function') initContactsIntegrationUi();
    if (typeof mountLogContactPickers === 'function') mountLogContactPickers();
    ['use-amount', 'use-date', 'use-end-date', 'use-percent-after', 'use-vape-puffs-used'].forEach(id => {
        document.getElementById(id)?.addEventListener('input', () => {
            if (id === 'use-date') syncCokeSessionEndDateDefault({ fromStartDateChange: true });
            updateUsePurchaseLinkUI();
            updateVapeUsePreview();
            computeUseFormDuration();
            if (isAlcoholTrackingMode(document.getElementById('use-substance')?.value)) {
                updateAlcoholDailyBreakdownUI();
                computeAlcoholMultiDayDurationPreview();
            }
        });
    });
    ['use-start-time', 'use-end-time'].forEach(id => {
        document.getElementById(id)?.addEventListener('input', () => {
            if (isAlcoholTrackingMode(document.getElementById('use-substance')?.value)
                && getAlcoholUseEntryMode() === 'multi_day') {
                computeAlcoholMultiDayDurationPreview();
            }
        });
    });
    document.getElementById('use-alcohol-custom-unit')?.addEventListener('input', updateAlcoholDailyBreakdownUI);
    document.getElementById('use-vape-purchase-select')?.addEventListener('change', () => {
        const manual = document.getElementById('use-purchase-select');
        const vapeSel = document.getElementById('use-vape-purchase-select');
        if (manual && vapeSel?.value) manual.value = vapeSel.value;
        updateVapePurchaseSelectDetails();
        updateVapeUsePreview();
    });
    document.getElementById('use-start-time')?.addEventListener('change', () => {
        syncCokeSessionEndDateDefault();
        computeUseFormDuration();
        updateVapeUsePreview();
    });
    document.getElementById('use-end-time')?.addEventListener('change', () => {
        syncCokeSessionEndDateDefault();
        computeUseFormDuration();
        updateVapeUsePreview();
    });
    document.getElementById('use-end-date')?.addEventListener('change', (e) => {
        if (e.target?.dataset) e.target.dataset.manual = '1';
        computeUseFormDuration();
        updateVapeUsePreview();
    });
    document.getElementById('use-purchase-link-mode')?.addEventListener('change', () => {
        updateUsePurchaseLinkUI();
        updateVapeUsePreview();
    });
    document.getElementById('use-purchase-select')?.addEventListener('change', () => {
        updateUsePurchaseLinkUI();
        updateVapeUsePreview();
        updateLsdUsePreview();
        updateXanaxUsePreview();
        if (getWeedUseProductType({ allowEmpty: true }) === 'edibles') {
            syncWeedEdibleStrengthFromInventory({ force: true });
        }
    });
    ['use-lsd-tabs-used', 'use-lsd-ug-used'].forEach(id => {
        document.getElementById(id)?.addEventListener('input', () => {
            updateLsdUsePreview();
            updateUsePurchaseLinkUI();
        });
    });
    ['use-xanax-pills-used', 'use-xanax-mg-used'].forEach(id => {
        document.getElementById(id)?.addEventListener('input', () => {
            updateXanaxUsePreview();
            updateUsePurchaseLinkUI();
        });
    });
    ['use-cigarettes-smoked', 'use-pouches-used', 'use-gum-pieces-used', 'use-patches-used', 'use-patch-hours-worn']
        .forEach(id => {
            document.getElementById(id)?.addEventListener('input', () => {
                updateUseNicotineProductTypeUI();
                updateUsePurchaseLinkUI();
            });
        });
    setUseLogType(document.getElementById('use-type')?.value || 'quick');
    updateVapeUseFormUI();
    updateUsePurchaseLinkUI();
}

function computeUseFormDuration() {
    if (isWeedDateOnlyUseForm() || isVapeDateOnlyUseForm()) {
        document.getElementById('use-duration-preview')?.classList.add('hidden');
        return;
    }
    const startDate = document.getElementById('use-date')?.value;
    const endDate = document.getElementById('use-end-date')?.value || startDate;
    const start = document.getElementById('use-start-time')?.value;
    const end = document.getElementById('use-end-time')?.value;
    const preview = document.getElementById('use-duration-preview');
    if (!preview) return;
    const showForSession = (document.getElementById('use-type')?.value || 'quick') === 'session';
    if (!startDate || !start || !end || !showForSession) {
        preview.classList.add('hidden');
        preview.classList.remove('use-duration-error');
        return;
    }
    const { start: s, end: e, invalid } = parseUseSessionEndDateTime(
        startDate,
        start,
        endDate,
        end,
        { allowInferOvernight: !shouldShowUseEndDateField() }
    );
    if (!s || !e) {
        preview.classList.add('hidden');
        preview.classList.remove('use-duration-error');
        return;
    }
    if (invalid || e <= s) {
        preview.textContent = 'End date/time is before start date/time.';
        preview.classList.remove('hidden');
        preview.classList.add('use-duration-error');
        return;
    }
    preview.textContent = `Duration: ${formatUseSessionDurationPreview((e - s) / 3600000)}`;
    preview.classList.remove('hidden', 'use-duration-error');
}

function getQuickLogSubstanceId() {
    return pickSubstanceForQuickAction('Quick Use — choose substance');
}

function logOneUse() {
    const substanceId = getQuickLogSubstanceId();
    if (!substanceId) return;
    const sub = getSubstance(substanceId);
    if (!sub) return alert('Add an active substance first.');
    if (isVapeTrackingMode(substanceId)) {
        setSelectedSubstanceId(substanceId, { source: 'use-log-substance', refresh: false });
        switchTab('use-log-tab');
        setDefaultVapeUseLogDate();
        ensureVapeUseFormDefaults();
        updateVapeUseFormUI();
        document.getElementById('use-log-form')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        return;
    }
    if (isWeedTrackingMode(substanceId)) {
        setSelectedSubstanceId(substanceId, { source: 'use-log-substance', refresh: false });
        switchTab('use-log-tab');
        setDefaultWeedUseLogDate();
        ensureWeedUseFormDefaults();
        updateVapeUseFormUI();
        document.getElementById('use-log-form')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        return;
    }
    if (!confirmTaperBeforeLog(substanceId, 1, true)) return;

    const now = new Date();
    const linkedPurchaseId = getOldestActivePurchase(substanceId)?.id || null;
    const log = {
        id: Date.now(),
        type: 'quick',
        transactionType: 'use',
        substanceId,
        amount: 1,
        unit: sub.defaultUnit,
        date: getLocalDateString(now),
        startTime: getLocalTimeString(now),
        time: getLocalTimeString(now),
        notes: '',
        purchaseId: linkedPurchaseId,
        linkedPurchaseId,
        linkedPurchases: [],
        supplyUnlinked: !linkedPurchaseId,
        inventoryAffects: !!linkedPurchaseId,
        timestamp: now.toISOString(),
        createdAt: now.toISOString(),
        updatedAt: now.toISOString()
    };

    if (linkedPurchaseId) {
        const deduct = deductPurchaseAmount(linkedPurchaseId, 1);
        if (!deduct.ok) {
            setLogPurchaseId(log, null);
        }
    }

    snapshotBestStreakBeforeUse(substanceId);
    if (!Array.isArray(appData.logs)) appData.logs = [];
    appData.logs.push(log);
    saveData(appData);
    updateDashboard();
    renderRecentUseList();
    refreshTaperDashboard();
    refreshBuyTrackerRelatedViews();
    alert(`Logged 1 ${sub.defaultUnit} of ${sub.name}`);
}

function openUseLogSession() {
    switchTab('use-log-tab');
    setUseLogType('session');
    const id = pickSubstanceForQuickAction('Session — choose substance');
    if (id) setInputValue('use-substance', id);
    setDefaultUseLogDateTime();
    updateUseUnitDropdown();
    updateUsePurchaseLinkUI();
}

function undoLastUse() {
    const history = loadChangeHistory();
    if (history.some(e => e.snapshot && e.action !== 'before-restore')) {
        undoLastChange();
        return;
    }
    const entries = getUseEntries();
    if (!entries.length) return alert('No use entries to undo');
    if (confirm('Undo last use entry?')) {
        pushChangeHistory('undo-last-use', { summary: 'Before removing last use entry' });
        const last = entries[entries.length - 1];
        if (last) restoreLogSupplyLinks(last);
        if (!Array.isArray(appData.logs)) appData.logs = [];
        appData.logs = getUseEntries().filter(l => l.id !== last.id && String(l.id) !== String(last.id));
        saveData(appData);
        updateDashboard();
        renderRecentUseList();
        renderUseHistoryTable();
        refreshTaperDashboard();
        refreshBuyTrackerRelatedViews();
    }
}

function getUseSaveSuccessMessage(entry) {
    if (isSharedUseLog(entry)) return 'Legacy Shared Use recorded!';
    if (isGiftGivenLog(entry)) return 'Gift given recorded!';
    if (isGiftReceivedLog(entry)) return 'Gift received recorded!';
    if (isInventoryAdjustmentLog(entry)) return 'Inventory adjustment saved!';
    return entry.type === 'session' ? 'Session saved!' : 'Use logged!';
}

function getUseUpdateSuccessMessage(entry) {
    if (isSharedUseLog(entry)) return 'Legacy Shared Use entry updated!';
    if (isGiftGivenLog(entry)) return 'Gift given updated!';
    if (isGiftReceivedLog(entry)) return 'Gift received updated!';
    if (isInventoryAdjustmentLog(entry)) return 'Inventory adjustment updated!';
    return entry.type === 'session' ? 'Session updated!' : 'Entry updated!';
}

function handleUseLogSubmit(e) {
    e.preventDefault();
    if (!reportUseFormValidationErrors()) return;

    const txEarly = document.getElementById('use-transaction-type')?.value || 'use';
    if (txEarly === 'shared_use') {
        return alert('Legacy Shared Use entries must be converted to Personal Use, Gift Given, Gift Received, or Adjustment before saving.');
    }

    const substanceIdPreview = document.getElementById('use-substance')?.value;
    const isNicotine = isNicotineTrackingMode(substanceIdPreview);
    const nicotineProductType = isNicotine ? getUseFormNicotineProductType() : null;
    const isVapeUse = isNicotine ? nicotineProductType === 'vape' : isVapeTrackingMode(substanceIdPreview);
    const isNicotineSimple = isNicotine && nicotineProductType !== 'vape' && nicotineProductType !== 'other';
    const isLsdUse = isLsdSubstanceId(substanceIdPreview);
    const isXanaxUse = isXanaxSubstanceId(substanceIdPreview);
    const isAlcoholUse = isAlcoholTrackingMode(substanceIdPreview);
    const isWeedUse = isWeedTrackingMode(substanceIdPreview);
    const isWeedCartUse = isWeedUse && getWeedUseProductType({ allowEmpty: true }) === 'cart';
    let vapeCalc = null;
    let lsdCalc = null;
    let nicotineCalc = null;
    let xanaxCalc = null;
    let alcoholCalc = null;
    let weedCartCalc = null;

    if (isAlcoholUse) {
        alcoholCalc = computeAlcoholUseFromForm({ editingId: editingUseId || null });
        if (alcoholCalc?.error) return alert(alcoholCalc.error);
    }

    if (isWeedCartUse) {
        weedCartCalc = computeWeedCartUseFromForm({ editingId: editingUseId || null });
        if (weedCartCalc?.error) return alert(weedCartCalc.error);
    } else if (isWeedUse && !getWeedUseProductType({ allowEmpty: true }) && editingUseId != null) {
        return alert('This older Weed entry needs a product type. Choose Bud, Cart, Edibles, or Pre-rolls before saving.');
    }

    if (isVapeUse) {
        vapeCalc = computeVapeUseFromForm({ editingId: editingUseId || null });
        if (vapeCalc?.error) return alert(vapeCalc.error);
        if (vapeCalc.estimatedFromPercent && getSpreadPercentLeftUsage()
            && (!vapeCalc.totalPuffs || vapeCalc.totalPuffs <= 0)) {
            return alert('This vape has no puff capacity set. Cannot estimate usage from percent left.');
        }
        const tx = document.getElementById('use-transaction-type')?.value || 'use';
        if (vapeCalc.puffsUsed < 0 && tx === 'use') {
            return alert(vapeCalc.warning || 'Percent left is higher than current inventory. This will be treated as an adjustment unless you choose a different vape.');
        }
    }

    if (isNicotineSimple) {
        nicotineCalc = computeNicotineNonVapeUseFromForm();
        if (nicotineCalc?.error) return alert(nicotineCalc.error);
    } else if (isNicotine && nicotineProductType === 'other') {
        nicotineCalc = computeNicotineNonVapeUseFromForm();
        if (nicotineCalc?.error) return alert(nicotineCalc.error);
    }

    const tx = document.getElementById('use-transaction-type')?.value || 'use';
    if (isAlcoholUse) {
        if (tx === 'gift_given' || tx === 'gift_received') {
            const party = document.getElementById('use-gift-party')?.value?.trim();
            if (!party) {
                return alert(tx === 'gift_received' ? 'Enter who gave this to you.' : 'Enter recipient name.');
            }
        }
    }
    if (isNicotine) {
        if (tx === 'gift_given' || tx === 'gift_received') {
            const party = document.getElementById('use-gift-party')?.value?.trim();
            if (!party) {
                return alert(tx === 'gift_received' ? 'Enter who gave this to you.' : 'Enter recipient name.');
            }
        }
    }

    if (isLsdUse) {
        lsdCalc = computeLsdUseFromForm({ editingId: editingUseId || null });
        const lsdTx = document.getElementById('use-transaction-type')?.value || 'use';
        const lsdErr = validateLsdUseSubmit(lsdCalc, lsdTx);
        if (lsdErr) return alert(lsdErr);
    }

    if (isXanaxUse) {
        xanaxCalc = computeXanaxUseFromForm({ editingId: editingUseId || null });
        const xanaxTx = document.getElementById('use-transaction-type')?.value || 'use';
        const xanaxErr = validateXanaxUseSubmit(xanaxCalc, xanaxTx);
        if (xanaxErr) return alert(xanaxErr);
    }

    const payload = buildUseEntryFromForm(vapeCalc, lsdCalc, nicotineCalc, xanaxCalc, alcoholCalc, weedCartCalc);
    const { substanceId, amount, type, transactionType } = payload;
    const isPersonalUse = isPersonalUseLog({ transactionType });
    const eventTimestamp = getUseEventTimestamp(payload.date, payload.startTime);
    const now = new Date().toISOString();
    const useVapeInventory = isVapeUse && vapeCalc?.purchase && payload.inventoryAffects;
    const useLsdInventory = isLsdUse && payload.inventoryAffects;
    const useXanaxInventory = isXanaxUse && payload.inventoryAffects;
    const useNicotineInventory = isNicotine && nicotineProductType !== 'vape' && nicotineCalc?.purchaseId && payload.inventoryAffects;

    if (isCokeSubstanceId(substanceId) && type === 'session') {
        if (!payload.endTime) {
            return alert('End time is required for coke sessions.');
        }
        const { start, end, invalid } = parseUseSessionEndDateTime(
            payload.date,
            payload.startTime,
            payload.endDate || payload.date,
            payload.endTime,
            { allowInferOvernight: false }
        );
        if (invalid || !start || !end || end <= start) {
            return alert('End date/time is before start date/time.');
        }
    }

    if (!confirmTaperBeforeLog(substanceId, amount, type === 'quick', editingUseId, transactionType, payload.date)) return;

    if (editingUseId != null) {
        const existing = findUseEntry(editingUseId);
        const idx = getUseEntries().findIndex(l => l.id === editingUseId || String(l.id) === String(editingUseId));
        if (!existing || idx < 0) {
            alert('Could not find the entry to update.');
            cancelUseEdit();
            return;
        }
        const priorState = JSON.parse(JSON.stringify(existing));
        const isVapeEdit = isVapeUseLog(existing) || useVapeInventory;

        if (isVapeEdit) {
            const priorLogs = JSON.parse(JSON.stringify(getUseEntries()));
            const editResult = applyVapeUseLogEdit(existing, payload, vapeCalc, appData);
            if (!editResult.ok) {
                alert(editResult.error || 'Could not update this vape entry.');
                return;
            }
            if (!saveData(appData)) {
                appData.logs = priorLogs;
                recalculateAllInventory();
                return alert('Failed to save data. Your changes were not stored.');
            }
            refreshUseLogRelatedViews();
            resetUseFormAfterSave();
            populateAllSubstanceDropdowns();
            alert(getUseUpdateSuccessMessage(editResult.updated));
            return;
        }

        restoreLogInventoryEffect(existing);

        const updated = {
            ...existing,
            ...payload,
            id: editingUseId,
            substanceId: payload.substanceId,
            purchaseId: payload.inventoryAffects ? (payload.purchaseId ?? payload.linkedPurchaseId) : null,
            linkedPurchaseId: payload.inventoryAffects ? payload.linkedPurchaseId : null,
            inventoryId: payload.inventoryAffects ? (payload.inventoryId ?? payload.linkedPurchaseId) : null,
            linkedPurchases: payload.inventoryAffects ? (payload.linkedPurchases || []) : [],
            inventoryAffects: payload.inventoryAffects,
            supplyUnlinked: !payload.inventoryAffects,
            createdAt: getUseCreatedAt(existing),
            updatedAt: now,
            timestamp: eventTimestamp
        };
        stripLegacyUseLogFields(updated);
        delete updated.substance;
        delete updated.lines;
        if (isWeedTrackingMode(substanceId)) {
            updated.type = 'quick';
            updated.logMode = payload.logMode || 'amount';
            updated.startTime = '';
            updated.time = '';
            updated.endTime = '';
            delete updated.endDate;
            delete updated.startedAt;
            delete updated.endedAt;
            delete updated.durationMs;
            if (payload.weedProductType) {
                updated.weedProductType = payload.weedProductType;
                updated.needsReview = false;
            } else {
                delete updated.weedProductType;
                updated.needsReview = true;
            }
            if (payload.logMode === 'weed_cart_percent') {
                updated.estimatedPercentUsed = payload.estimatedPercentUsed;
                updated.percentBefore = payload.percentBefore;
                updated.percentLeftAfter = payload.percentLeftAfter;
                updated.percentAfter = payload.percentAfter;
                updated.percentRemaining = payload.percentRemaining;
                updated.unit = 'percent';
            } else {
                delete updated.estimatedPercentUsed;
                delete updated.percentBefore;
                delete updated.percentLeftAfter;
                delete updated.percentAfter;
                delete updated.estimatedFromPercent;
            }
        }
        if (isNicotineNonVapeFormContext(substanceId, updated)) {
            updated.type = 'quick';
            updated.startTime = '';
            updated.time = '';
            updated.endTime = '';
            delete updated.endDate;
            delete updated.startedAt;
            delete updated.endedAt;
            delete updated.durationMs;
        }
        if (isNicotineVapeFormContext(substanceId, updated)) {
            updated.type = 'quick';
            updated.logMode = 'vape_puffs';
            updated.startTime = '';
            updated.time = '';
            updated.endTime = '';
            delete updated.endDate;
            delete updated.startedAt;
            delete updated.endedAt;
            delete updated.durationMs;
            delete updated.estimatedPuffsPerHour;
            delete updated.estimatedPuffsPerMinute;
        }
        if (isLsdSubstanceId(substanceId)) {
            finalizeLsdUseLogForSave(updated, lsdCalc);
        }
        if (isXanaxSubstanceId(substanceId)) {
            finalizeXanaxUseLogForSave(updated, xanaxCalc);
        }
        if (isNicotineTrackingMode(substanceId)) {
            finalizeNicotineUseLogForSave(updated, { nicotineCalc, vapeCalc });
        }
        if (isAlcoholTrackingMode(substanceId)) {
            if (isAlcoholMultiDayParentLog(existing)) {
                removeDistributedMultiDayEntries(existing.id);
            }
            if (!alcoholCalc?.isMultiDay) {
                clearAlcoholMultiDayParentFlags(updated);
            }
            finalizeAlcoholUseLogForSave(updated, alcoholCalc);
            if (updated.isMultiDay) {
                syncDistributedAlcoholEntries(updated);
            }
        }

        const inv = applyLogInventoryEffect(updated);
        if (!inv.ok) {
            applyExistingLogLinks(priorState, appData.purchases || []);
            Object.assign(existing, priorState);
            return alert(inv.error);
        }
        appData.logs[idx] = updated;

        if (!saveData(appData)) {
            appData.logs[idx] = priorState;
            applyExistingLogLinks(priorState, appData.purchases || []);
            return alert('Failed to save data. Your changes were not stored.');
        }
        refreshUseLogRelatedViews();
        resetUseFormAfterSave();
        populateAllSubstanceDropdowns();
        alert(getUseUpdateSuccessMessage(updated));
        return;
    }

    if (isPersonalUse) snapshotBestStreakBeforeUse(substanceId);
    const log = {
        ...payload,
        id: Date.now(),
        createdAt: now,
        updatedAt: now,
        timestamp: eventTimestamp
    };
    stripLegacyUseLogFields(log);
    if (isWeedTrackingMode(substanceId)) {
        log.type = 'quick';
        log.logMode = payload.logMode || 'amount';
        log.startTime = '';
        log.time = '';
        log.endTime = '';
        delete log.endDate;
        delete log.startedAt;
        delete log.endedAt;
        delete log.durationMs;
        if (payload.logMode === 'weed_cart_percent') {
            log.estimatedPercentUsed = payload.estimatedPercentUsed;
            log.percentBefore = payload.percentBefore;
            log.percentLeftAfter = payload.percentLeftAfter;
            log.percentAfter = payload.percentAfter;
            log.percentRemaining = payload.percentRemaining;
            log.unit = 'percent';
        }
    }
    if (isNicotineNonVapeFormContext(substanceId, log)) {
        log.type = 'quick';
        log.startTime = '';
        log.time = '';
        log.endTime = '';
        delete log.endDate;
        delete log.startedAt;
        delete log.endedAt;
        delete log.durationMs;
    }
    if (isNicotineVapeFormContext(substanceId, log)) {
        log.type = 'quick';
        log.logMode = 'vape_puffs';
        log.startTime = '';
        log.time = '';
        log.endTime = '';
        delete log.endDate;
        delete log.startedAt;
        delete log.endedAt;
        delete log.durationMs;
        delete log.estimatedPuffsPerHour;
        delete log.estimatedPuffsPerMinute;
    }
    if (isNicotineTrackingMode(substanceId)) {
        finalizeNicotineUseLogForSave(log, { nicotineCalc, vapeCalc });
    }
    if (isAlcoholTrackingMode(substanceId)) {
        finalizeAlcoholUseLogForSave(log, alcoholCalc);
    }
    if (isLsdSubstanceId(substanceId)) {
        log.type = 'quick';
        log.logMode = 'lsd_dose';
        log.startTime = payload.startTime || '';
        log.time = payload.time || payload.startTime || '';
        log.endTime = '';
        delete log.endDate;
        delete log.startedAt;
        delete log.endedAt;
        delete log.durationMs;
    }
    if (isXanaxSubstanceId(substanceId)) {
        finalizeXanaxUseLogForSave(log, xanaxCalc);
        const commitResult = commitUseLogEntry(log, {
            xanaxCalc,
            applyInventory: useXanaxInventory || logInventoryAffects(log)
        });
        if (!commitResult.ok) return alert(commitResult.error || 'Could not save this entry.');
        resetUseFormAfterSave();
        populateAllSubstanceDropdowns();
        refreshUseLogRelatedViews();
        alert(getUseSaveSuccessMessage(log));
        return;
    }

    if (isLsdSubstanceId(substanceId)) {
        finalizeLsdUseLogForSave(log, lsdCalc);
        const commitResult = commitUseLogEntry(log, {
            lsdCalc,
            applyInventory: useLsdInventory || logInventoryAffects(log)
        });
        if (!commitResult.ok) return alert(commitResult.error || 'Could not save this entry.');
        resetUseFormAfterSave();
        populateAllSubstanceDropdowns();
        refreshUseLogRelatedViews();
        alert(getUseSaveSuccessMessage(log));
        return;
    }

    appData.logs.push(log);

    if (isAlcoholTrackingMode(substanceId) && log.isMultiDay) {
        syncDistributedAlcoholEntries(log);
    }

    if (useVapeInventory && vapeCalc.purchaseId) {
        setLogPurchaseId(log, vapeCalc.purchaseId);
        recalculateVapePurchaseInventory(vapeCalc.purchaseId);
    } else if (useNicotineInventory && nicotineCalc.purchaseId) {
        setLogPurchaseId(log, nicotineCalc.purchaseId);
        const purchase = findPurchase(nicotineCalc.purchaseId);
        if (isVapePuffPurchase(purchase)) {
            recalculateVapePurchaseInventory(nicotineCalc.purchaseId);
        } else {
            recalculatePurchaseRemaining(nicotineCalc.purchaseId);
        }
    } else if (!useVapeInventory && !useNicotineInventory) {
        const inv = applyLogInventoryEffect(log);
        if (!inv.ok) {
            appData.logs.pop();
            return alert(inv.error);
        }
    }

    if (!saveData(appData)) {
        restoreLogInventoryEffect(log);
        appData.logs.pop();
        return alert('Failed to save data. Your entry was not stored.');
    }
    resetUseFormAfterSave();
    populateAllSubstanceDropdowns();
    refreshUseLogRelatedViews();
    alert(getUseSaveSuccessMessage(log));
}

function deleteUseEntry(id) {
    const entry = findUseEntry(id);
    if (!entry) {
        return;
    }
    if (isPercentLeftDistributedChildLog(entry)) {
        if (!confirm('Delete the percent-left checkpoint and all distributed daily entries?')) return;
        deleteUseEntry(entry.parentPercentLogId);
        return;
    }
    if (isAlcoholMultiDayChildLog(entry)) {
        if (!confirm('Delete the multi-day entry and all linked daily entries?')) return;
        deleteUseEntry(entry.parentLogId);
        return;
    }
    if (!confirm('Delete this entry?')) return;
    if (editingUseId === id) cancelUseEdit();
    const vapePid = entry && isVapeUseLog(entry) ? getLogPurchaseId(entry) : null;
    if (isPercentLeftCheckpointLog(entry)) {
        removeDistributedPercentLeftEntries(entry.id);
    }
    if (isAlcoholMultiDayParentLog(entry)) {
        removeDistributedMultiDayEntries(entry.id);
    }
    if (entry && !vapePid) restoreLogSupplyLinks(entry);
    appData.logs = getUseEntries().filter(l => l.id !== id && String(l.id) !== String(id));
    if (vapePid) recalculateVapePurchaseInventory(vapePid);
    saveData(appData);
    refreshUseLogRelatedViews();
}

function renderUseLogTab() {
    renderUseLogTotals();
    renderRecentUseList();
    renderUseHistoryTable();
}

let bulkLinkPending = null;
const useHistorySelection = new Set();

function useHistorySelectionHas(id) {
    if (useHistorySelection.has(id)) return true;
    return [...useHistorySelection].some(sid => String(sid) === String(id));
}

/**
 * Single filtered Use Log dataset for summary cards, Recent Use, Use History,
 * Bulk Actions selection, and CSV export.
 */
function getFilteredUseLogsForView(options = {}) {
    const data = options.data || appData;
    const substanceId = options.substanceId !== undefined
        ? options.substanceId
        : getUseLogViewSubstanceId();
    const dateFilter = options.dateFilter !== undefined ? options.dateFilter : useLogDateFilter;
    const productType = options.productType || null;
    const productTypes = options.productTypes
        || (productType ? [productType] : null);
    const transactionTypes = options.transactionTypes || null;

    let logs = getUseEntries(data).filter(l => logMatchesUseLogFilter(l, dateFilter));
    logs = logs.filter(l => !isPercentLeftDistributedChildLog(l));
    logs = logs.filter(l => !isAlcoholMultiDayChildLog(l));
    logs = logs.filter(l => !l.deletedAt && !l.deleted && !l.hidden && !l.inventoryHidden);
    if (substanceId) {
        logs = logs.filter(l => logMatchesSubstance(l, substanceId, data));
    }
    if (productTypes?.length) {
        const allowed = new Set(productTypes);
        logs = logs.filter(l => allowed.has(getNicotineProductType(l, data) || 'other'));
    }
    if (transactionTypes?.length) {
        const allowed = new Set(transactionTypes);
        logs = logs.filter(l => allowed.has(getLogTransactionType(l)));
    }
    return logs;
}

function nicotineProductTypeSortIndex(log, data = appData) {
    const type = getNicotineProductType(log, data) || 'other';
    const idx = NICOTINE_PRODUCT_TYPES.indexOf(type);
    return idx >= 0 ? idx : NICOTINE_PRODUCT_TYPES.length;
}

function buildUseHistoryRows(substanceIdOverride = undefined) {
    const filterId = substanceIdOverride !== undefined
        ? substanceIdOverride
        : getUseLogViewSubstanceId();
    const entries = getFilteredUseLogsForView({ substanceId: filterId });

    const substanceIds = [...new Set(entries.map(l => getUseSubstanceId(l)).filter(Boolean))];
    let substances = substanceIds.map(id => getSubstance(id) || {
        id,
        name: getSubstanceName(id),
        icon: '📦',
        defaultUnit: 'units',
        color: '#888'
    });

    if (!substances.length && filterId) {
        substances = [getSubstance(filterId)].filter(Boolean);
        if (!substances.length) {
            substances = [{
                id: filterId,
                name: getSubstanceName(filterId),
                icon: '📦',
                defaultUnit: 'units',
                color: '#888'
            }];
        }
    }

    let allRows = [];
    substances.forEach(sub => {
        const subEntries = entries.filter(l => logMatchesSubstance(l, sub.id));
        const sorted = [...subEntries].sort((a, b) => getLogDatetimeMs(a) - getLogDatetimeMs(b));
        const enriched = [];
        sorted.forEach((entry, i) => {
            enriched.push(enrichUseEntry(entry, i > 0 ? enriched[i - 1] : null));
        });
        const avgRate = (() => {
            const rates = enriched
                .filter(e => isPersonalUseLog(e))
                .map(e => e.useRate)
                .filter(r => r != null && r > 0);
            return rates.length ? rates.reduce((a, b) => a + b, 0) / rates.length : null;
        })();
        enriched.forEach(entry => allRows.push({ entry, sub, avgRate }));
    });

    const nicotineView = filterId && isNicotineTrackingMode(filterId);
    allRows.sort((a, b) => {
        if (nicotineView) {
            const typeDiff = nicotineProductTypeSortIndex(a.entry) - nicotineProductTypeSortIndex(b.entry);
            if (typeDiff !== 0) return typeDiff;
        }
        const da = getLogDatetimeMs(a.entry);
        const db = getLogDatetimeMs(b.entry);
        return db - da;
    });
    return sortUseHistoryDisplayRows(allRows, useHistorySortState);
}

function getVisibleUseHistoryLogIds() {
    return buildUseHistoryRows().map(({ entry }) => entry.id);
}

function updateUseHistorySelectionUI() {
    const countEl = document.getElementById('use-history-selected-count');
    if (countEl) countEl.textContent = `${useHistorySelection.size} selected`;
    const btn = document.getElementById('manual-link-selected-btn');
    if (btn) btn.disabled = useHistorySelection.size === 0;
}

function syncUseHistorySelectAllCheckbox() {
    const selectAll = document.getElementById('use-history-select-all');
    if (!selectAll) return;
    const visibleIds = getVisibleUseHistoryLogIds();
    if (!visibleIds.length) {
        selectAll.checked = false;
        selectAll.indeterminate = false;
        return;
    }
    const selectedVisible = visibleIds.filter(id => useHistorySelectionHas(id)).length;
    selectAll.checked = selectedVisible === visibleIds.length;
    selectAll.indeterminate = selectedVisible > 0 && selectedVisible < visibleIds.length;
}

function clearUseHistorySelection() {
    useHistorySelection.clear();
    document.querySelectorAll('.use-history-row-cb').forEach(cb => { cb.checked = false; });
    const selectAll = document.getElementById('use-history-select-all');
    if (selectAll) {
        selectAll.checked = false;
        selectAll.indeterminate = false;
    }
    updateUseHistorySelectionUI();
}

function populateManualLinkSubstanceDropdown() {
    const select = document.getElementById('manual-link-substance');
    if (!select) return;
    const subs = getLoggableSubstances();
    const selectedIds = [...useHistorySelection];
    const substanceIdsInSelection = new Set(
        selectedIds
            .map(id => findUseEntry(id))
            .filter(Boolean)
            .map(l => getUseSubstanceId(l))
    );

    select.innerHTML = '';
    subs.forEach(sub => {
        const opt = document.createElement('option');
        opt.value = sub.id;
        opt.textContent = `${sub.icon} ${sub.name}`;
        select.appendChild(opt);
    });

    let defaultId = selectedSubstanceId;
    if (!isSelectedAllSubstances() && subs.some(s => s.id === selectedSubstanceId)) {
        defaultId = selectedSubstanceId;
    } else if (substanceIdsInSelection.size === 1) {
        defaultId = [...substanceIdsInSelection][0];
    } else if (subs.length) {
        defaultId = subs[0].id;
    }
    if (defaultId && [...select.options].some(o => o.value === defaultId)) {
        select.value = defaultId;
    }
}

function populateManualLinkPurchaseDropdown(substanceId) {
    const select = document.getElementById('manual-link-purchase');
    if (!select) return;
    const purchases = getPurchasesForManualLink(substanceId);
    const currentVal = select.value;
    select.innerHTML = '<option value="">Select a purchase…</option>';
    purchases.forEach(p => {
        const opt = document.createElement('option');
        opt.value = p.id;
        opt.textContent = formatPurchaseOptionLabel(p);
        select.appendChild(opt);
    });
    if (currentVal && [...select.options].some(o => String(o.value) === String(currentVal))) {
        select.value = currentVal;
    } else if (purchases.length) {
        select.value = purchases[0].id;
    }
}

function updateManualBulkLinkModalSummary() {
    const substanceId = getManualBulkLinkSubstanceId();
    const selectedLogs = getSelectedLogsForManualLink(substanceId);
    const totalAmount = selectedLogs.reduce((s, l) => s + (parseFloat(l.amount) || 0), 0);
    const unit = selectedLogs[0]?.unit || getSubstance(substanceId)?.defaultUnit || 'units';

    setText('manual-link-session-count', String(selectedLogs.length));
    setText('manual-link-total-amount', selectedLogs.length
        ? `${totalAmount.toFixed(2)} ${unit}`
        : '—');

    const previewEl = document.getElementById('manual-link-preview');
    const purchaseId = getManualBulkLinkPurchaseId();
    if (!previewEl) return;

    if (!purchaseId) {
        previewEl.innerHTML = '<p class="empty-hint">Choose a purchase to preview.</p>';
        return;
    }

    const stats = buildManualBulkLinkPreviewStats(
        appData,
        [...useHistorySelection],
        purchaseId,
        getManualBulkLinkOptionsFromUI()
    );
    previewEl.innerHTML = formatManualBulkLinkPreview(stats);
}

function openManualBulkLinkModal() {
    if (!useHistorySelection.size) {
        alert('Select at least one session in Use History.');
        return;
    }

    populateManualLinkSubstanceDropdown();
    const substanceId = getManualBulkLinkSubstanceId();
    if (substanceId) populateManualLinkPurchaseDropdown(substanceId);
    updateManualBulkLinkModalSummary();

    document.getElementById('manual-bulk-link-modal')?.classList.remove('hidden');
}

function closeManualBulkLinkModal() {
    document.getElementById('manual-bulk-link-modal')?.classList.add('hidden');
}

function applyManualBulkLink() {
    const purchaseId = getManualBulkLinkPurchaseId();
    if (!purchaseId) {
        alert('Select a purchase to link.');
        return;
    }
    if (!useHistorySelection.size) {
        alert('No sessions selected.');
        return;
    }

    const options = getManualBulkLinkOptionsFromUI();
    const selectedLogIds = [...useHistorySelection];
    const substanceId = getManualBulkLinkSubstanceId() || getPurchaseSubstanceId(findPurchase(purchaseId));
    const result = runManualBulkLinkOnData(appData, selectedLogIds, purchaseId, options);
    if (typeof result === 'string') {
        alert(result);
        return;
    }

    console.log('[manual-link] updated logs',
        selectedLogIds.map(id => appData.logs.find(l => String(l.id) === String(id)))
    );

    closeManualBulkLinkModal();
    clearUseHistorySelection();
    refreshAfterLogLinkChange(substanceId);
    updateLastSavedDisplay();

    const { stats } = result;
    const unit = stats.unit || 'units';
    let msg = `Linked ${stats.sessionCount} session(s) (${stats.totalAmount.toFixed(2)} ${unit}).`;
    if (stats.overdraw > INVENTORY_EPS) {
        msg += ` Overdraw: ${stats.overdraw.toFixed(2)} ${unit}.`;
    }
    alert(msg);
}

function setupManualBulkLinkListeners() {
    document.getElementById('use-history-clear-selection')?.addEventListener('click', clearUseHistorySelection);

    document.getElementById('use-history-select-all')?.addEventListener('change', e => {
        const visibleIds = getVisibleUseHistoryLogIds();
        if (e.target.checked) {
            visibleIds.forEach(id => useHistorySelection.add(id));
        } else {
            visibleIds.forEach(id => useHistorySelection.delete(id));
        }
        renderUseHistoryTable();
    });

    document.getElementById('use-history-table-wrap')?.addEventListener('change', e => {
        if (!e.target.classList.contains('use-history-row-cb')) return;
        const idRaw = e.target.dataset.logId;
        const id = parsePurchaseSelectId(idRaw);
        if (id == null) return;
        if (e.target.checked) useHistorySelection.add(id);
        else useHistorySelection.delete(id);
        updateUseHistorySelectionUI();
        syncUseHistorySelectAllCheckbox();
    });

    const modal = document.getElementById('manual-bulk-link-modal');
    if (!modal) return;

    ['manual-link-substance', 'manual-link-purchase', 'manual-link-reset', 'manual-link-overdraw', 'manual-link-split']
        .forEach(id => {
            document.getElementById(id)?.addEventListener('change', () => {
                if (id === 'manual-link-substance') {
                    const substanceId = getManualBulkLinkSubstanceId();
                    if (substanceId) populateManualLinkPurchaseDropdown(substanceId);
                }
                updateManualBulkLinkModalSummary();
            });
        });
}

function runBulkInventoryLink(data, mode) {
    const working = JSON.parse(JSON.stringify(data));
    migrateUseLogsToLogs(working);
    const purchases = working.purchases || [];
    const logs = working.logs || [];
    resetAllPurchaseInventory(purchases);

    const stats = {
        linked: 0,
        purchasesMatched: new Set(),
        unmatched: 0,
        processed: 0,
        cleared: 0
    };

    if (mode === 'clear') {
        logs.forEach(log => {
            setLogPurchaseId(log, null);
        });
        stats.cleared = logs.length;
        purchases.forEach(finalizePurchaseRemainingState);
        return {
            data: working,
            stats: {
                linked: 0,
                purchasesMatched: 0,
                unmatched: 0,
                processed: logs.length,
                cleared: stats.cleared
            }
        };
    }

    const sortedLogs = [...logs].sort((a, b) => getLogDatetimeMs(a) - getLogDatetimeMs(b));

    sortedLogs.forEach(log => {
        const amount = parseFloat(log.amount) || 0;
        if (amount <= INVENTORY_EPS) return;

        stats.processed++;

        if (mode === 'unlinked_only' && !logIsUnlinked(log)) {
            applyExistingLogLinks(log, purchases).forEach(id => stats.purchasesMatched.add(id));
            return;
        }

        if (mode === 'all') {
            delete log.purchaseId;
            delete log.linkedPurchaseId;
            delete log.linkedPurchases;
        }

        const wasUnlinked = logIsUnlinked(log);
        const result = fifoLinkLogToPurchases(log, purchases);

        if (result.purchaseIds.length) {
            result.purchaseIds.forEach(id => stats.purchasesMatched.add(id));
            if (mode === 'all' || wasUnlinked) stats.linked++;
        }
        if (result.unmatched) stats.unmatched++;
    });

    purchases.forEach(finalizePurchaseRemainingState);

    return {
        data: working,
        stats: {
            linked: stats.linked,
            purchasesMatched: stats.purchasesMatched.size,
            unmatched: stats.unmatched,
            processed: stats.processed,
            cleared: 0
        }
    };
}

function formatBulkLinkSummary(stats, mode) {
    if (mode === 'clear') {
        return `
            <p>Cleared links on <strong>${stats.cleared}</strong> session(s).</p>
            <p>Purchase inventory reset to full quantity bought.</p>
        `;
    }
    const label = mode === 'unlinked_only' ? 'session(s)' : 'session(s)';
    return `
        <ul class="bulk-link-summary-list">
            <li>Linked <strong>${stats.linked}</strong> ${label}</li>
            <li>Matched <strong>${stats.purchasesMatched}</strong> purchase(s)</li>
            <li><strong>${stats.unmatched}</strong> session(s) could not be fully matched</li>
        </ul>
        <p class="settings-hint">Inventory will be recalculated from oldest purchases first (FIFO).</p>
    `;
}

function startBulkLinkSessions(mode) {
    const titles = {
        all: 'Auto Link Sessions',
        unlinked_only: 'Link Unlinked Only',
        clear: 'Clear All Links'
    };
    const result = runBulkInventoryLink(appData, mode);
    bulkLinkPending = { mode, result };

    const titleEl = document.getElementById('bulk-link-modal-title');
    const summaryEl = document.getElementById('bulk-link-summary');
    const modal = document.getElementById('bulk-link-modal');
    if (titleEl) titleEl.textContent = titles[mode] || 'Bulk Link Preview';
    if (summaryEl) summaryEl.innerHTML = formatBulkLinkSummary(result.stats, mode);
    modal?.classList.remove('hidden');
}

function closeBulkLinkModal() {
    document.getElementById('bulk-link-modal')?.classList.add('hidden');
    bulkLinkPending = null;
}

function applyBulkLinkPreview() {
    if (!bulkLinkPending) return;
    const { mode, result } = bulkLinkPending;
    appData.logs = result.data.logs;
    appData.purchases = result.data.purchases;
    saveData(appData);
    closeBulkLinkModal();
    refreshUseLogRelatedViews();
    updateCurrentSupplyDashboard();
    const msg = mode === 'clear'
        ? `Cleared links on ${result.stats.cleared} session(s). Inventory reset.`
        : `Linked ${result.stats.linked} session(s). ${result.stats.unmatched} could not be fully matched.`;
    alert(msg);
}

function getUseLogBadgeInfo(log) {
    const tx = getLogTransactionType(log);
    if (tx === 'shared_use') return { label: 'Legacy Shared Use', className: 'badge-shared-use' };
    if (tx === 'gift_given') return { label: 'Gift Given', className: 'badge-gift-given' };
    if (tx === 'gift_received') return { label: 'Gift Received', className: 'badge-gift-received' };
    if (tx === 'inventory_adjustment') return { label: 'Adjustment', className: 'badge-inventory' };
    if (isPercentLeftDistributedChildLog(log)) return { label: 'Est. daily', className: 'badge-estimated' };
    if (isPercentLeftCheckpointLog(log)) return { label: 'Percent-left', className: 'badge-estimated' };
    if (isAlcoholMultiDayParentLog(log)) return { label: 'Multi-day', className: 'badge-session' };
    if (isAlcoholMultiDayChildLog(log)) return { label: 'Daily', className: 'badge-estimated' };
    if (isWeedDateOnlyUseLog(log)) return { label: 'Use', className: 'badge-quick' };
    if (getUseLogType(log) === 'session') return { label: 'Session', className: 'badge-session' };
    return { label: 'Quick Use', className: 'badge-quick' };
}

function renderUseLogBadge(log) {
    const { label, className } = getUseLogBadgeInfo(log);
    return `<span class="use-log-badge ${className}">${label}</span>`;
}

function renderUseHistoryCard(entry, sub, avgRate) {
    const warnings = getUseRowWarnings(entry, sub.id, avgRate);
    const rowCcr = evaluateUseHistoryRowConditionalColor(entry, sub.id);
    const rowColorClasses = getUseHistoryRowColorClassNames(entry, rowCcr);
    const rowStyle = buildUseHistoryRowInlineStyle(rowCcr);
    const isWeedSimple = isWeedDateOnlyUseLog(entry);
    const isVapeDateOnly = isVapeDateOnlyUseLog(entry);
    const isLsdDateOnly = isLsdDateOnlyUseLog(entry);
    const isXanaxDateOnly = isXanaxDateOnlyUseLog(entry);
    const hideTimeStats = isWeedSimple || isVapeDateOnly || isLsdDateOnly || isXanaxDateOnly;
    const rateStr = (!hideTimeStats && entry.useRate != null) ? `${entry.useRate.toFixed(2)}/${sub.defaultUnit}/hr` : '—';
    const checked = useHistorySelectionHas(entry.id) ? 'checked' : '';
    const timeRange = hideTimeStats ? '' : formatUseSessionTimeRange(entry);
    const isVape = isVapeUseLog(entry);
    const isLsd = isLsdDateOnlyUseLog(entry);
    const isXanax = isXanaxDateOnlyUseLog(entry);
    const isNicotineNonVape = isNicotineSubstanceId(getUseSubstanceId(entry)) && !isVape;
    const isAlcohol = isAlcoholTrackingMode(getUseSubstanceId(entry));
    const countStr = (isVape || isLsd || isXanax) ? '—' : (entry.count || '—');
    let amountDisplay = isVape
        ? formatVapeUseSummary(entry, sub)
        : (isLsd ? formatLsdUseSummary(entry)
            : (isXanax ? formatXanaxUseSummary(entry)
                : (isNicotineNonVape ? formatNicotineUseLogLabel(entry)
                    : (isAlcohol ? formatAlcoholUseSummary(entry, sub) : `${entry.amount} ${entry.unit}`))));
    if (isPercentLeftDistributedChildLog(entry)) {
        amountDisplay = `~${formatAmount(entry.amount)} puffs · Estimated daily use from percent-left log`;
    } else if (isPercentLeftCheckpointLog(entry) && getSpreadPercentLeftUsage()) {
        amountDisplay = formatPercentLeftCheckpointSummary(entry);
    } else if (isAlcoholMultiDayParentLog(entry)) {
        amountDisplay = formatAlcoholUseSummary(entry, sub);
    }
    const warningClass = warnings.length ? ` ${warnings.join(' ')}` : '';
    const colorClass = rowColorClasses.length ? ` ${rowColorClasses.join(' ')}` : '';
    const colorStyle = rowStyle ? ` style="${escapeAttr(rowStyle)}"` : '';

    const splitNote = formatOvernightSplitNote(entry, sub.id);
    const splitHtml = splitNote ? `<div class="use-history-split-note cal-muted">${splitNote}</div>` : '';
    const multiDayChildren = isAlcoholMultiDayParentLog(entry) ? getDistributedChildrenForMultiDayLog(entry.id) : [];
    const multiDayHtml = multiDayChildren.length
        ? `<button type="button" class="link-btn percent-dist-toggle" onclick="toggleMultiDayDistDays(${entry.id})">View daily breakdown (${multiDayChildren.length})</button>
           <div id="multiday-dist-${entry.id}" class="percent-dist-days hidden">
               ${formatAlcoholMultiDayBreakdownLines(entry).map(line => `<div class="use-recent-detail percent-dist-day">${line}</div>`).join('')}
           </div>`
        : '';

    return `<article class="use-history-card${warningClass}${colorClass}" data-log-id="${escapeAttr(entry.id)}"${colorStyle}>
        <div class="use-history-card-top">
            <label class="use-history-card-check">
                <input type="checkbox" class="use-history-row-cb" data-log-id="${escapeAttr(entry.id)}" aria-label="Select entry" ${checked}>
            </label>
            <div class="use-history-card-main">
                <div class="use-history-card-title-row">
                    ${renderUseLogBadge(entry)}
                    <span class="use-history-card-amount">${amountDisplay}</span>
                </div>
                <div class="use-history-card-meta">${escapeHtml(sub.icon)} ${escapeHtml(sub.name)} · ${formatDate(entry.date)}${timeRange ? ` · ${escapeHtml(timeRange)}` : ''}</div>
            </div>
        </div>
        <dl class="use-history-card-details">
            ${hideTimeStats ? '' : `<div><dt>Duration</dt><dd>${formatDurationHours(entry.durationHours)}</dd></div>`}
            <div><dt>Count</dt><dd>${countStr}</dd></div>
            ${hideTimeStats ? '' : `<div><dt>Rate</dt><dd>${rateStr}</dd></div>`}
            ${hideTimeStats ? '' : `<div><dt>Break</dt><dd>${entry.breakText || '—'}</dd></div>`}
            <div class="use-history-card-supply"><dt>Supply</dt><dd>${escapeHtml(isVape ? formatVapeLinkedPurchaseLine(entry) || formatInventoryLinkDisplay(entry) : formatInventoryLinkDisplay(entry))}</dd></div>
            ${entry.notes ? `<div class="use-history-card-notes"><dt>Notes</dt><dd>${escapeHtml(entry.notes)}</dd></div>` : ''}
            ${splitHtml}
            ${multiDayHtml}
        </dl>
        <div class="use-history-card-actions">
            <button type="button" class="secondary-btn" onclick="editUseEntry(${entry.id})">Edit</button>
            <button type="button" class="delete-btn" onclick="deleteUseEntry(${entry.id})" aria-label="Delete entry">×</button>
        </div>
    </article>`;
}

function renderRecentUseList() {
    const container = document.getElementById('recent-use-list');
    if (!container) return;
    container.innerHTML = '';
    const filterId = getUseLogViewSubstanceId();
    const list = getFilteredUseLogsForView({ substanceId: filterId });
    const recent = [...list].sort((a, b) => getLogDatetimeMs(b) - getLogDatetimeMs(a)).slice(0, 12);
    if (!recent.length) {
        container.innerHTML = '<p class="empty-hint">No use entries yet</p>';
        applyCollapsedSections();
        return;
    }
    recent.forEach(log => {
        const substanceId = getUseSubstanceId(log);
        const sub = getSubstance(substanceId);
        const enriched = enrichUseEntry(log, null);
        const isVape = isVapeUseLog(log);
        const isNicotineNonVape = isNicotineSubstanceId(getUseSubstanceId(log)) && !isVape;
        const isCheckpoint = isPercentLeftCheckpointLog(log) && getSpreadPercentLeftUsage();
        const distChildren = isCheckpoint ? getDistributedChildrenForPercentLog(log.id) : [];
        const isMultiDayParent = isAlcoholMultiDayParentLog(log);
        const multiDayChildren = isMultiDayParent ? getDistributedChildrenForMultiDayLog(log.id) : [];
        const countStr = getUseCount(log);
        const isWeedSimple = isWeedDateOnlyUseLog(log);
        const isLsdSimple = isLsdDateOnlyUseLog(log);
        const isAlcohol = isAlcoholTrackingMode(getUseSubstanceId(log));
        const isSessionLog = !isVape && !isWeedSimple && !isLsdSimple && !isNicotineNonVape && !isAlcohol && log.endTime;
        const timeRange = formatUseSessionTimeRange(log);
        const amountDisplay = isVape
            ? ''
            : (isLsdSimple
                ? formatLsdUseSummary(log)
                : (isNicotineNonVape
                    ? formatNicotineUseLogLabel(log)
                    : (isAlcohol
                        ? formatAlcoholUseSummary(log)
                        : (isWeedSimple
                            ? (typeof formatWeedNormalizedUseSummary === 'function'
                                ? formatWeedNormalizedUseSummary(log)
                                : (isWeedCartPercentLog(log)
                                    ? formatWeedCartUseSummary(log)
                                    : (isWeedEdiblesLog(log)
                                        ? formatWeedEdibleUseSummary(log)
                                        : `${log.amount != null ? formatAmount(log.amount) : '—'} ${log.unit || ''}`.trim())))
                            : `${log.amount != null ? formatAmount(log.amount) : '—'} ${log.unit || ''}`))));
        const weedProductTypeLabel = isWeedSimple ? getWeedLogProductTypeLabel(log) : '';
        const vapeDetailHtml = isVape
            ? formatVapeRecentUseDetailLines(log).map(line => `<div class="use-recent-detail">${line}</div>`).join('')
            : '';
        const weedDetailHtml = isWeedSimple
            ? `<div class="use-recent-detail">Product type: ${escapeHtml(weedProductTypeLabel)}</div>`
            : '';
        const distDaysHtml = isCheckpoint && distChildren.length
            ? `<button type="button" class="link-btn percent-dist-toggle" onclick="togglePercentDistDays(${log.id})">View distributed days (${distChildren.length})</button>
               <div id="percent-dist-${log.id}" class="percent-dist-days hidden">
                   ${distChildren.map(child => `<div class="use-recent-detail percent-dist-day">${formatDate(child.date)} · ~${formatAmount(child.amount)} puffs · Estimated daily use from percent-left log</div>`).join('')}
               </div>`
            : '';
        const multiDayHtml = isMultiDayParent && multiDayChildren.length
            ? `<button type="button" class="link-btn percent-dist-toggle" onclick="toggleMultiDayDistDays(${log.id})">View daily breakdown (${multiDayChildren.length})</button>
               <div id="multiday-dist-${log.id}" class="percent-dist-days hidden">
                   ${formatAlcoholMultiDayBreakdownLines(log).map(line => `<div class="use-recent-detail percent-dist-day">${line}</div>`).join('')}
               </div>`
            : '';
        const linkedLine = isVape ? formatVapeLinkedPurchaseLine(log) : formatInventoryLinkDisplay(log);
        const splitNote = !isVape ? formatOvernightSplitNote(log, substanceId) : '';
        const sessionBodyHtml = isSessionLog
            ? `<div class="use-recent-sub">${escapeHtml(sub?.icon || '')} ${escapeHtml(sub?.name || 'Unknown')}</div>
                <div class="use-recent-date">${formatDate(log.date || '')}</div>
                <div class="use-recent-time">${timeRange}</div>
                ${amountDisplay ? `<div class="use-recent-amount-line">${amountDisplay}</div>` : ''}
                ${renderNormalizedDurationDetailHtml(log, { section: 'useHistory' })}`
            : `<div class="use-recent-sub">${escapeHtml(sub?.icon || '')} ${escapeHtml(sub?.name || 'Unknown')} · ${formatDate(log.date || '')}${timeRange && timeRange !== '—' ? ` · ${escapeHtml(timeRange)}` : ''}</div>`;
        const item = document.createElement('div');
        item.className = `use-recent-card${isCheckpoint || isMultiDayParent ? ' use-recent-checkpoint' : ''}`;
        item.innerHTML = `
            <div class="use-recent-main">
                <div class="use-recent-top">
                    ${renderUseLogBadge(log)}
                    ${!isSessionLog && amountDisplay ? `<span class="use-recent-amount">${amountDisplay}</span>` : ''}
                </div>
                ${sessionBodyHtml}
                ${vapeDetailHtml}
                ${weedDetailHtml}
                ${distDaysHtml}
                ${multiDayHtml}
                ${!isSessionLog && !isVape ? renderNormalizedDurationDetailHtml(log, { section: 'useHistory' }) : ''}
                ${!isVape && formatSecondaryCountDisplay(substanceId, countStr) ? `<div class="use-recent-detail">${formatSecondaryCountDisplay(substanceId, countStr)}</div>` : ''}
                ${log.notes ? `<div class="use-recent-notes">${escapeHtml(log.notes)}</div>` : ''}
                ${log.mood ? `<div class="use-recent-detail">Mood: ${escapeHtml(log.mood)}</div>` : ''}
                ${log.trigger ? `<div class="use-recent-detail">Trigger: ${escapeHtml(log.trigger)}</div>` : ''}
                ${log.cravingLevel != null ? `<div class="use-recent-detail">Craving: ${log.cravingLevel}/10</div>` : ''}
                ${log.stressLevel != null ? `<div class="use-recent-detail">Stress: ${log.stressLevel}/10</div>` : ''}
                ${splitNote ? `<div class="use-recent-detail use-history-split-note cal-muted">${splitNote}</div>` : ''}
                <div class="use-recent-supply">${escapeHtml(linkedLine)}</div>
            </div>
            <div class="use-recent-actions">
                <button type="button" class="secondary-btn" onclick="editUseEntry(${log.id})">Edit</button>
                <button type="button" class="delete-btn" onclick="deleteUseEntry(${log.id})" aria-label="Delete entry">×</button>
            </div>
        `;
        container.appendChild(item);
    });
    applyCollapsedSections();
}

function renderUseHistoryTable(options = {}) {
    const {
        wrapId = 'use-history-table-wrap',
        // undefined → use current Log substance filter (do NOT default to null/"all")
        substanceId = undefined
    } = typeof options === 'object' ? options : { wrapId: options };
    const wrap = document.getElementById(wrapId);
    if (!wrap) return;

    const filterId = substanceId !== undefined ? substanceId : getUseLogViewSubstanceId();
    const allRows = buildUseHistoryRows(filterId);

    if (!allRows.length) {
        const hasEntries = getUseEntries().length > 0;
        wrap.innerHTML = hasEntries
            ? '<p class="empty-hint">No entries for the selected substance in this view.</p>'
            : '<p class="empty-hint">No entries yet. Log your first use above.</p>';
        pruneUseHistorySelectionToVisible();
        updateUseHistorySelectionUI();
        syncUseHistorySelectAllCheckbox();
        applyCollapsedSections();
        return;
    }

    const useColumns = getUseHistoryVisibleColumns(filterId);
    const variantKey = getUseHistoryColumnVariantKey(filterId);
    const tableMinWidth = getTableMinWidth('useHistory', useColumns, variantKey);
    const colgroup = buildTableColgroup('useHistory', useColumns, variantKey);
    const familyClass = `use-history-family-${getUseHistoryColumnFamily(filterId)}`;
    let tableHtml = `<div class="use-history-table-view table-scroll"><table class="session-table history-table use-history-table customizable-table ${familyClass}" data-table-key="useHistory" data-table-variant="${escapeAttr(variantKey)}" style="min-width:${tableMinWidth}px;table-layout:fixed">${colgroup}<thead><tr>`;
    useColumns.forEach(colId => {
        tableHtml += renderUseHistoryHeaderCell(colId, filterId);
    });
    tableHtml += '</tr></thead><tbody>';

    let cardsHtml = '<div class="use-history-cards">';
    let lastProductType = null;

    allRows.forEach(({ entry, sub, avgRate }) => {
        if (filterId && isNicotineTrackingMode(filterId)) {
            const productType = getNicotineProductType(entry) || 'other';
            if (productType !== lastProductType) {
                lastProductType = productType;
                const label = getNicotineProductTypeLabel(productType);
                tableHtml += `<tr class="use-history-group-row"><td colspan="${useColumns.length}"><span class="use-history-group-label">${escapeHtml(label)}</span></td></tr>`;
            }
        }
        const warnings = getUseRowWarnings(entry, sub.id, avgRate);
        const rowCcr = evaluateUseHistoryRowConditionalColor(entry, sub.id);
        const rowColorClasses = getUseHistoryRowColorClassNames(entry, rowCcr);
        const rowClasses = [...warnings, ...rowColorClasses].filter(Boolean).join(' ');
        const rowStyle = buildUseHistoryRowInlineStyle(rowCcr);
        tableHtml += `<tr class="${escapeAttr(rowClasses)}"${rowStyle ? ` style="${escapeAttr(rowStyle)}"` : ''}>`;
        useColumns.forEach(colId => {
            tableHtml += renderUseHistoryBodyCell(colId, entry, sub, avgRate);
        });
        tableHtml += '</tr>';
        cardsHtml += renderUseHistoryCard(entry, sub, avgRate);
    });

    tableHtml += '</tbody></table></div>';
    cardsHtml += '</div>';

    wrap.innerHTML = tableHtml + cardsHtml;
    pruneUseHistorySelectionToVisible();
    updateUseHistorySelectionUI();
    syncUseHistorySelectAllCheckbox();
    applyCollapsedSections();
}

function pruneUseHistorySelectionToVisible() {
    const visible = new Set(getVisibleUseHistoryLogIds().map(String));
    [...useHistorySelection].forEach(id => {
        if (!visible.has(String(id))) useHistorySelection.delete(id);
    });
}

function getTodayUseStats(substanceId) {
    const today = getLocalDateString();
    if (isVapeNicotineSubstanceId(substanceId)) {
        const logs = filterLogsBySubstance(
            getUseEntries().filter(l => l.date === today && isPersonalUseLog(l)),
            substanceId
        );
        const stats = calculateUseStats(logs);
        return {
            logs,
            totalAmount: getStatsUsageOnDate(substanceId, today),
            sessionCount: stats.sessionCount,
            totalDurationMinutes: stats.totalDurationMinutes,
            totalDurationHours: stats.totalDurationMinutes / 60,
            avgPerSession: stats.avgPerSession,
            sessionDuration: stats.totalDurationMinutes / 60
        };
    }

    const totalAmount = sumUseAmountForDate(substanceId, today);
    const totalDurationMinutes = sumUseMinutesForDate(substanceId, today);
    const sourceLogIds = new Set();
    getDailyUseSegments(null, substanceId)
        .filter(seg => seg.date === today && seg.amount > INVENTORY_EPS)
        .forEach(seg => sourceLogIds.add(seg.sourceLogId));
    const sessionCount = sourceLogIds.size;
    return {
        logs: filterLogsBySubstance(
            getUseEntries().filter(l => logHasUseSegmentOnDate(l, today) && isPersonalUseLog(l)),
            substanceId
        ),
        totalAmount,
        sessionCount,
        totalDurationMinutes,
        totalDurationHours: totalDurationMinutes / 60,
        avgPerSession: sessionCount > 0 ? totalAmount / sessionCount : null,
        sessionDuration: totalDurationMinutes / 60
    };
}

function formatTodayDuration(hours) {
    if (hours == null || isNaN(hours) || hours <= 0) return '0h 0m';
    return formatDurationHours(hours);
}

function aggregateTodayUseStats() {
    let totalAmount = 0;
    let sessionCount = 0;
    let totalDurationMinutes = 0;
    getActiveSubstances().forEach(sub => {
        const stats = getTodayUseStats(sub.id);
        totalAmount += stats.totalAmount;
        sessionCount += stats.sessionCount;
        totalDurationMinutes += stats.totalDurationMinutes;
    });
    return {
        totalAmount,
        sessionCount,
        totalDurationMinutes,
        totalDurationHours: totalDurationMinutes / 60,
        avgPerSession: sessionCount > 0 ? totalAmount / sessionCount : null
    };
}

function getTimeSinceLastUse(substanceId) {
    const logs = filterLogsBySubstance(getUseEntries().filter(isPersonalUseLog), substanceId);
    if (!logs.length) return null;
    const sorted = logs.sort((a, b) => getLogDatetimeMs(b) - getLogDatetimeMs(a));
    const last = sorted[0];
    if (isWeedTrackingMode(substanceId)) {
        const day = parseLocalDate(last.date);
        if (day) {
            const endOfDay = new Date(day);
            endOfDay.setHours(23, 59, 59, 999);
            return Date.now() - endOfDay.getTime();
        }
    }
    const end = getUseEndDatetime(enrichUseEntry(last, null));
    if (!end) return null;
    return Date.now() - end.getTime();
}

// ——— Buy Tracker ———
function getPurchasesFiltered(substanceId) {
    return getInventoryFilteredPurchases(substanceId);
}

function getPurchaseSubstanceId(purchase) {
    return purchase.substanceId || purchase.substance || purchase.item || '';
}

function getPurchaseQuantity(purchase) {
    const q = purchase.quantity ?? purchase.quantityBought;
    return q != null && q !== '' ? q : '';
}

function getPurchaseTotalCost(purchase) {
    const c = purchase.totalCost ?? purchase.cost;
    return c != null && c !== '' ? c : '';
}

const PURCHASE_ACQUISITION_TYPES = ['purchased', 'gift_received', 'purchased_as_gift', 'other_adjustment'];

function normalizePurchaseAcquisitionType(value, purchase = null) {
    const raw = String(value || '').trim().toLowerCase();
    if (raw === 'gift_received' || raw === 'gift-received' || raw === 'gift') return 'gift_received';
    if (
        raw === 'purchased_as_gift'
        || raw === 'purchased-as-gift'
        || raw === 'gift_purchased'
        || raw === 'bought_as_gift'
    ) return 'purchased_as_gift';
    if (
        raw === 'other_adjustment'
        || raw === 'other'
        || raw === 'adjustment'
        || raw === 'inventory_adjustment'
        || raw === 'correction'
    ) return 'other_adjustment';
    if (raw === 'purchased' || raw === 'purchase' || raw === 'bought') return 'purchased';
    if (
        purchase?.isPurchasedAsGift
        || purchase?.source === 'purchased_as_gift'
        || purchase?.inventoryStatus === 'gifted'
    ) {
        return 'purchased_as_gift';
    }
    if (purchase?.isGiftReceived || purchase?.source === 'gift_received' || purchase?.transactionType === 'gift_received') {
        return 'gift_received';
    }
    return 'purchased';
}

function getPurchaseAcquisitionType(purchase) {
    if (!purchase) return 'purchased';
    return normalizePurchaseAcquisitionType(purchase.acquisitionType, purchase);
}

function purchaseIsPurchasedAsGift(purchase) {
    return getPurchaseAcquisitionType(purchase) === 'purchased_as_gift';
}

function purchaseCountsAsBuySpend(purchase) {
    const type = getPurchaseAcquisitionType(purchase);
    return type === 'purchased' || type === 'purchased_as_gift';
}

function purchaseIsNonPurchasedAcquisition(purchase) {
    return !purchaseCountsAsBuySpend(purchase);
}

function purchaseIsPersonalUseInventory(purchase) {
    return !!purchase && !purchaseIsPurchasedAsGift(purchase);
}

function getPurchaseGiftSource(purchase) {
    if (!purchase) return '';
    if (purchaseIsPurchasedAsGift(purchase)) return '';
    return String(purchase.giftSource || purchase.giverName || purchase.giftPartyName || '').trim();
}

function getPurchaseGiftRecipient(purchase) {
    if (!purchase) return '';
    return String(purchase.giftRecipient || purchase.recipientName || '').trim();
}

function getPurchaseGiftDate(purchase) {
    if (!purchase) return '';
    return String(purchase.giftDate || '').trim();
}

function applyPurchasedAsGiftInventoryState(purchase) {
    if (!purchase || !purchaseIsPurchasedAsGift(purchase)) return purchase;
    purchase.remainingAmount = 0;
    if (purchase.remainingPuffs != null) purchase.remainingPuffs = 0;
    if (purchase.remainingTabs != null) purchase.remainingTabs = 0;
    if (purchase.remainingUg != null) purchase.remainingUg = 0;
    if (purchase.remainingPills != null) purchase.remainingPills = 0;
    if (purchase.remainingMg != null) purchase.remainingMg = 0;
    purchase.isDepleted = true;
    purchase.inventoryStatus = 'gifted';
    purchase.inventoryHidden = false;
    if (!purchase.depletedAt) purchase.depletedAt = new Date().toISOString();
    return purchase;
}

function syncPurchaseAcquisitionFields(purchase) {
    if (!purchase || typeof purchase !== 'object') return purchase;
    const acquisitionType = getPurchaseAcquisitionType(purchase);
    purchase.acquisitionType = acquisitionType;
    if (acquisitionType === 'gift_received') {
        purchase.isGiftReceived = true;
        purchase.isPurchasedAsGift = false;
        purchase.source = 'gift_received';
        const giftSource = getPurchaseGiftSource(purchase);
        purchase.giftSource = giftSource;
        if (giftSource) {
            purchase.giverName = giftSource;
            purchase.giftPartyName = giftSource;
        } else {
            delete purchase.giverName;
            delete purchase.giftPartyName;
        }
        purchase.giftRecipient = '';
        purchase.giftDate = '';
        delete purchase.recipientName;
        purchase.totalCost = 0;
        purchase.costPerUnit = 0;
        purchase.paymentMethod = '';
    } else if (acquisitionType === 'purchased_as_gift') {
        purchase.isGiftReceived = false;
        purchase.isPurchasedAsGift = true;
        purchase.source = 'purchased_as_gift';
        purchase.giftSource = '';
        delete purchase.giverName;
        const recipient = getPurchaseGiftRecipient(purchase);
        purchase.giftRecipient = recipient;
        if (recipient) {
            purchase.recipientName = recipient;
            purchase.giftPartyName = recipient;
        } else {
            delete purchase.recipientName;
            delete purchase.giftPartyName;
        }
        const giftDate = getPurchaseGiftDate(purchase);
        if (giftDate) purchase.giftDate = giftDate;
        else delete purchase.giftDate;
        applyPurchasedAsGiftInventoryState(purchase);
    } else if (acquisitionType === 'other_adjustment') {
        purchase.isGiftReceived = false;
        purchase.isPurchasedAsGift = false;
        purchase.source = 'other_adjustment';
        purchase.giftSource = '';
        purchase.giftRecipient = '';
        purchase.giftDate = '';
        delete purchase.giverName;
        delete purchase.recipientName;
        delete purchase.giftPartyName;
        purchase.totalCost = 0;
        purchase.costPerUnit = 0;
        purchase.paymentMethod = '';
    } else {
        purchase.isGiftReceived = false;
        purchase.isPurchasedAsGift = false;
        if (
            purchase.source === 'gift_received'
            || purchase.source === 'other_adjustment'
            || purchase.source === 'purchased_as_gift'
        ) {
            delete purchase.source;
        }
        purchase.giftSource = '';
        purchase.giftRecipient = '';
        purchase.giftDate = '';
        delete purchase.giverName;
        delete purchase.recipientName;
        delete purchase.giftPartyName;
    }
    return purchase;
}

function getPurchaseAcquisitionBadgeInfo(purchase) {
    const type = getPurchaseAcquisitionType(purchase);
    if (type === 'gift_received') return { label: 'Gift Received', className: 'badge-gift-received' };
    if (type === 'purchased_as_gift') return { label: 'Purchased as Gift', className: 'badge-purchased-as-gift' };
    if (type === 'other_adjustment') return { label: 'Adjustment', className: 'badge-inventory' };
    return null;
}

function renderPurchaseAcquisitionBadge(purchase) {
    const info = getPurchaseAcquisitionBadgeInfo(purchase);
    if (!info) return '';
    return ` <span class="use-log-badge ${escapeAttr(info.className)}">${escapeHtml(info.label)}</span>`;
}

function getBuyFormAcquisitionType() {
    return normalizePurchaseAcquisitionType(document.getElementById('buy-acquisition-type')?.value || 'purchased');
}

function setBuyAcquisitionType(type) {
    const normalized = normalizePurchaseAcquisitionType(type);
    const select = document.getElementById('buy-acquisition-type');
    if (select) select.value = normalized;
    document.getElementById('buy-acquisition-type-block')?.classList.remove('hidden');
    updateBuyAcquisitionTypeUI();
}

function updateBuyAcquisitionTypeUI() {
    const type = getBuyFormAcquisitionType();
    const isGiftReceived = type === 'gift_received';
    const isPurchasedAsGift = type === 'purchased_as_gift';
    const isNonPurchase = type === 'gift_received' || type === 'other_adjustment';
    const costInput = document.getElementById('buy-total-cost');
    const acquisitionBlock = document.getElementById('buy-acquisition-type-block');
    const acquisitionSelect = document.getElementById('buy-acquisition-type');
    const giftRecipientInput = document.getElementById('buy-gift-recipient');
    acquisitionBlock?.classList.remove('hidden');
    if (acquisitionSelect) {
        acquisitionSelect.hidden = false;
        acquisitionSelect.disabled = false;
        acquisitionSelect.style.display = '';
        if (!acquisitionSelect.value) acquisitionSelect.value = 'purchased';
    }
    document.getElementById('buy-gift-source-group')?.classList.toggle('hidden', !isGiftReceived);
    document.getElementById('buy-gift-recipient-group')?.classList.toggle('hidden', !isPurchasedAsGift);
    document.getElementById('buy-gift-date-group')?.classList.toggle('hidden', !isPurchasedAsGift);
    document.getElementById('buy-supplier-contact-picker')?.classList.toggle('hidden', isGiftReceived);
    if (typeof mountBuyContactPickers === 'function') mountBuyContactPickers();
    document.getElementById('buy-total-cost-group')?.classList.toggle('hidden', isNonPurchase);
    document.getElementById('buy-cost-per-unit-group')?.classList.toggle('hidden', isNonPurchase);
    document.getElementById('buy-store-group')?.classList.toggle('hidden', isGiftReceived);
    document.getElementById('buy-payment-group')?.classList.toggle('hidden', isNonPurchase);
    if (giftRecipientInput) giftRecipientInput.required = isPurchasedAsGift;
    if (costInput) {
        costInput.required = !isNonPurchase;
        if (isNonPurchase) {
            costInput.value = '0';
            const payment = document.getElementById('buy-payment');
            if (payment) payment.value = '';
        }
    }
    if (isGiftReceived) {
        const storeSelect = document.getElementById('buy-store-select');
        if (storeSelect) storeSelect.value = '';
        const storeNew = document.getElementById('buy-store-new');
        if (storeNew) storeNew.value = '';
        document.getElementById('buy-store-new-group')?.classList.add('hidden');
    }
    if (!isGiftReceived) {
        const giftSource = document.getElementById('buy-gift-source');
        if (giftSource) giftSource.value = '';
    }
    if (!isPurchasedAsGift) {
        const giftRecipient = document.getElementById('buy-gift-recipient');
        if (giftRecipient) giftRecipient.value = '';
        const giftDate = document.getElementById('buy-gift-date');
        if (giftDate) giftDate.value = '';
    }
    updateBuyCostPerUnitPreview();
}

function getPurchaseSpendAmount(purchase) {
    if (!purchase) return 0;
    if (purchaseIsNonPurchasedAcquisition(purchase)) return 0;
    const direct = purchase.totalCost ?? purchase.cost ?? purchase.price;
    if (direct != null && direct !== '') {
        const parsed = parseFloat(direct);
        if (Number.isFinite(parsed)) return Math.max(0, parsed);
    }
    const qty = parseFloat(getPurchaseQuantityBought(purchase) ?? getPurchaseQuantity(purchase)) || 0;
    const cpu = parseFloat(purchase.costPerUnit);
    if (qty > 0 && Number.isFinite(cpu) && cpu > 0) return qty * cpu;
    return 0;
}

function purchaseMatchesSubstance(purchase, substanceId, data = appData) {
    if (!substanceId) return true;
    return normalizeSubstanceRef(getPurchaseSubstanceId(purchase), data)
        === normalizeSubstanceRef(substanceId, data);
}

function getPurchasesForBuyMetrics(substanceId, data = appData) {
    let list = [...(data.purchases || [])];
    if (substanceId) {
        list = list.filter(p => purchaseMatchesSubstance(p, substanceId, data));
    }
    return list.filter(p => !p.archivedAt && !p.inventoryHidden);
}

function getPurchasesForInsightMetrics(substanceId, data = appData) {
    return getPurchasesForBuyMetrics(substanceId, data).filter(purchaseCountsAsBuySpend);
}

function getPurchaseDateStr(purchase) {
    if (!purchase?.date) return '';
    const raw = String(purchase.date).trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
    const isoPrefix = /^(\d{4}-\d{2}-\d{2})/.exec(raw);
    if (isoPrefix) return isoPrefix[1];
    const parsed = parseLocalDate(raw);
    return parsed ? getLocalDateString(parsed) : raw;
}

function purchaseOnDate(purchase, dateStr) {
    return getPurchaseDateStr(purchase) === dateStr;
}

function purchaseInDateRange(purchase, startDate, endDate) {
    const d = purchase?.date;
    if (!d) return false;
    if (startDate && d < startDate) return false;
    if (endDate && d > endDate) return false;
    return true;
}

function getSubstancePurchaseSpend(substanceId, filterFn) {
    return (appData.purchases || [])
        .filter(p => p.substanceId === substanceId && (!filterFn || filterFn(p)))
        .reduce((sum, p) => {
            const c = parseFloat(getPurchaseTotalCost(p));
            return sum + (Number.isFinite(c) ? c : 0);
        }, 0);
}

const BUY_STORE_ADD_NEW = '__add_new_store__';

function normalizeStoreName(name) {
    if (name == null) return '';
    return String(name).trim().replace(/\s+/g, ' ');
}

function getStoreDedupeKey(name) {
    return normalizeStoreName(name).toLowerCase();
}

function getSavedStoreNames(data = appData) {
    const byKey = new Map();
    const purchases = [...(data?.purchases || [])].sort((a, b) => getPurchaseDatetimeMs(b) - getPurchaseDatetimeMs(a));
    purchases.forEach(purchase => {
        const normalized = normalizeStoreName(purchase.store || purchase.location || '');
        if (!normalized) return;
        const key = getStoreDedupeKey(normalized);
        if (!byKey.has(key)) byKey.set(key, normalized);
    });
    return [...byKey.values()].sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' }));
}

function updateBuyStoreNewFieldVisibility() {
    const select = document.getElementById('buy-store-select');
    const group = document.getElementById('buy-store-new-group');
    const isAddNew = select?.value === BUY_STORE_ADD_NEW;
    group?.classList.toggle('hidden', !isAddNew);
    if (!isAddNew) {
        const newInput = document.getElementById('buy-store-new');
        if (newInput) newInput.value = '';
    }
}

function populateBuyStoreDropdown(selectedValue = '') {
    const select = document.getElementById('buy-store-select');
    if (!select) return;

    const normalized = normalizeStoreName(selectedValue);
    let stores = getSavedStoreNames();
    if (normalized && !stores.some(s => getStoreDedupeKey(s) === getStoreDedupeKey(normalized))) {
        stores = [...stores, normalized].sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' }));
    }

    select.innerHTML = '';
    const addOption = (value, label) => {
        const opt = document.createElement('option');
        opt.value = value;
        opt.textContent = label;
        select.appendChild(opt);
    };

    addOption('', '— Select store/location —');
    stores.forEach(store => addOption(store, store));
    addOption(BUY_STORE_ADD_NEW, '+ Add new store/location');

    if (normalized) {
        const match = [...select.options].find(o =>
            o.value && o.value !== BUY_STORE_ADD_NEW && getStoreDedupeKey(o.value) === getStoreDedupeKey(normalized)
        );
        if (match) {
            select.value = match.value;
        } else {
            select.value = BUY_STORE_ADD_NEW;
            const newInput = document.getElementById('buy-store-new');
            if (newInput) newInput.value = normalized;
        }
    } else {
        select.value = '';
    }

    updateBuyStoreNewFieldVisibility();
}

function setBuyStoreFieldValue(value) {
    populateBuyStoreDropdown(value);
}

function getBuyFormStoreValue() {
    const select = document.getElementById('buy-store-select');
    const value = select?.value || '';
    if (value === BUY_STORE_ADD_NEW) {
        return normalizeStoreName(document.getElementById('buy-store-new')?.value);
    }
    return normalizeStoreName(value);
}

function resetBuyStoreField() {
    populateBuyStoreDropdown('');
}

function onBuyStoreSelectChange() {
    updateBuyStoreNewFieldVisibility();
}

function setDefaultBuyDateTime() {
    const now = new Date();
    const dateStr = getLocalDateString(now);
    const timeStr = getLocalTimeString(now);
    const dateEl = document.getElementById('buy-date');
    if (dateEl) dateEl.value = dateStr;
    const timeEl = document.getElementById('buy-time');
    if (timeEl) timeEl.value = timeStr;
}

function updateBuyVapeNicotinePreview() {
    const substanceId = document.getElementById('buy-substance')?.value;
    if (!isVapeNicotineSubstanceId(substanceId)) return;
    const preview = document.getElementById('buy-vape-nicotine-preview');
    if (!preview) return;
    const { eLiquidCapacityMl, nicotineMgPerMl, totalNicotineMg } = parseVapeNicotineFieldsFromForm();
    if (eLiquidCapacityMl != null && nicotineMgPerMl != null && totalNicotineMg != null) {
        preview.textContent = `${formatAmount(eLiquidCapacityMl)} mL × ${formatAmount(nicotineMgPerMl)} mg/mL = ${formatAmount(totalNicotineMg)} mg nicotine total.`;
    } else {
        preview.textContent = '—';
    }
}

function updateBuyVapeFieldsPreview() {
    const substanceId = document.getElementById('buy-substance')?.value;
    if (!isVapeNicotineSubstanceId(substanceId)) return;
    const full = parseFloat(document.getElementById('buy-quantity')?.value) || 0;
    const pctRaw = parseFloat(document.getElementById('buy-percent-bought')?.value);
    const percentBoughtAt = Number.isFinite(pctRaw) ? pctRaw : 100;
    const starting = computeVapeStartingPuffsFromForm(full, percentBoughtAt);
    const preview = document.getElementById('buy-vape-start-preview');
    if (preview) {
        preview.textContent = full > 0
            ? `${formatAmount(full)} puffs at ${percentBoughtAt}% = ${formatAmount(starting)} puffs starting left.`
            : '—';
    }
    updateBuyVapeNicotinePreview();
}

function updateBuyAlcoholPreview() {
    const substanceId = document.getElementById('buy-substance')?.value;
    if (!isAlcoholTrackingMode(substanceId)) return;
    const preview = document.getElementById('buy-alcohol-preview');
    if (!preview) return;
    const { netVolumeMl, alcoholPercent, pureAlcoholMl } = parseAlcoholFieldsFromForm();
    if (netVolumeMl != null && alcoholPercent != null && pureAlcoholMl != null) {
        preview.textContent = `${formatAmount(netVolumeMl)} mL × ${formatAmount(alcoholPercent)}% = ${formatAmount(pureAlcoholMl)} mL pure alcohol.`;
    } else {
        preview.textContent = '—';
    }
}

function updateBuyWeedPreRollPreview() {
    const preview = document.getElementById('buy-preroll-preview');
    if (!preview) return;
    const count = parseFloat(document.getElementById('buy-preroll-count')?.value);
    const grams = parseFloat(document.getElementById('buy-grams-per-preroll')?.value);
    const total = computeWeedTotalPreRollGrams(count, grams);
    if (total != null && count > 0 && grams > 0) {
        preview.textContent = `${formatAmount(count)} pre-rolls × ${formatAmount(grams)} g = ${formatAmount(total)} g total.`;
    } else {
        preview.textContent = '—';
    }
}

function updateBuyNicotineProductTypeUI() {
    const substanceId = document.getElementById('buy-substance')?.value;
    if (!isNicotineTrackingMode(substanceId)) return;
    const productType = getBuyFormNicotineProductType();
    const isVape = productType === 'vape';
    const isCigarettes = productType === 'cigarettes';
    const isPouches = productType === 'pouches';
    const isGum = productType === 'gum';
    const isPatches = productType === 'patches';

    document.getElementById('buy-vape-percent-group')?.classList.toggle('hidden', !isVape);
    document.getElementById('buy-vape-liquid-group')?.classList.toggle('hidden', !isVape);
    document.getElementById('buy-vape-flavor-group')?.classList.toggle('hidden', !isVape);
    document.getElementById('buy-cigarettes-fields-group')?.classList.toggle('hidden', !isCigarettes);
    document.getElementById('buy-pouches-fields-group')?.classList.toggle('hidden', !isPouches);
    document.getElementById('buy-gum-fields-group')?.classList.toggle('hidden', !isGum);
    document.getElementById('buy-patches-fields-group')?.classList.toggle('hidden', !isPatches);
    document.getElementById('buy-time-group')?.classList.toggle('hidden', isVape);

    const hideQty = isVape || isCigarettes || isPouches || isGum || isPatches;
    document.getElementById('buy-quantity-group')?.classList.toggle('hidden', hideQty);
    document.getElementById('buy-unit-group')?.classList.toggle('hidden', isNicotineTrackingMode(substanceId));

    const qtyInput = document.getElementById('buy-quantity');
    if (qtyInput) qtyInput.required = !hideQty;

    const qtyLabel = document.getElementById('buy-quantity-label');
    if (qtyLabel) {
        if (isVape) qtyLabel.textContent = 'Puff count at 100%';
        else if (hideQty) qtyLabel.textContent = 'Quantity';
        else qtyLabel.textContent = 'Quantity Bought';
    }

    if (isVape) updateBuyVapeFieldsPreview();
    if (isCigarettes) updateBuyCigarettesPreview();
    if (isPouches) updateBuyPouchesPreview();
    if (isGum) updateBuyGumPreview();
    if (isPatches) updateBuyPatchesPreview();
    updateBuyCostPerUnitPreview();
}

function updateBuyCigarettesPreview() {
    const preview = document.getElementById('buy-cigarettes-preview');
    if (!preview) return;
    const fields = parseCigaretteFieldsFromForm();
    const totalCost = parseFloat(document.getElementById('buy-total-cost')?.value);
    const lines = [];
    if (fields.totalCigarettes != null) lines.push(`Total cigarettes: ${formatAmount(fields.totalCigarettes)}`);
    if (fields.totalCigarettes != null && Number.isFinite(totalCost) && totalCost > 0) {
        lines.push(`Cost per cigarette: ${fmtSheetMoney(totalCost / fields.totalCigarettes, getCurrencySymbol())}`);
        if (fields.packCount != null && fields.packCount > 0) {
            lines.push(`Cost per pack: ${fmtSheetMoney(totalCost / fields.packCount, getCurrencySymbol())}`);
        }
    }
    preview.textContent = lines.length ? lines.join(' · ') : '—';
}

function updateBuyPouchesPreview() {
    const preview = document.getElementById('buy-pouches-preview');
    if (!preview) return;
    const fields = parseNicotinePouchesFieldsFromForm();
    const lines = [];
    if (fields.totalPouches != null) lines.push(`Total pouches: ${formatAmount(fields.totalPouches)}`);
    if (fields.totalNicotineMg != null) lines.push(`Total nicotine: ${formatAmount(fields.totalNicotineMg)} mg`);
    preview.textContent = lines.length ? lines.join(' · ') : '—';
}

function updateBuyGumPreview() {
    const preview = document.getElementById('buy-gum-preview');
    if (!preview) return;
    const fields = parseNicotineGumFieldsFromForm();
    const lines = [];
    if (fields.pieceCount != null) lines.push(`Pieces: ${formatAmount(fields.pieceCount)}`);
    if (fields.totalNicotineMg != null) lines.push(`Total nicotine: ${formatAmount(fields.totalNicotineMg)} mg`);
    preview.textContent = lines.length ? lines.join(' · ') : '—';
}

function updateBuyPatchesPreview() {
    const preview = document.getElementById('buy-patches-preview');
    if (!preview) return;
    const fields = parseNicotinePatchesFieldsFromForm();
    const lines = [];
    if (fields.patchCount != null) lines.push(`Patches: ${formatAmount(fields.patchCount)}`);
    if (fields.mgPerPatch != null) lines.push(`${formatAmount(fields.mgPerPatch)} mg/patch · ${formatAmount(fields.patchDurationHours)}h duration`);
    preview.textContent = lines.length ? lines.join(' · ') : '—';
}

function getWeedBuyNormalizedUnit(productType) {
    const type = normalizeWeedProductType(productType);
    if (type === 'cart') return 'percent';
    if (type === 'edibles') return 'edible';
    return 'grams';
}

function setBuyUnitSelectNormalizedValue(unit) {
    const unitSelect = document.getElementById('buy-unit');
    if (!unitSelect || !unit) return;
    if (![...unitSelect.options].some(o => o.value === unit)) {
        const option = document.createElement('option');
        option.value = unit;
        option.textContent = unit;
        unitSelect.appendChild(option);
    }
    unitSelect.value = unit;
}

function updateBuyWeedEdiblesPreview() {
    const preview = document.getElementById('buy-edibles-preview');
    if (!preview) return;
    const count = parseFloat(document.getElementById('buy-quantity')?.value);
    const mgPer = parseFloat(document.getElementById('buy-edibles-mg')?.value);
    const cbdPer = parseFloat(document.getElementById('buy-edibles-cbd-mg')?.value);
    if (Number.isFinite(count) && count > 0 && Number.isFinite(mgPer) && mgPer > 0) {
        const total = computeWeedEdibleTotalThcMg(count, mgPer);
        let text = `${formatAmount(count)} edible × ${formatAmount(mgPer)} mg = ${formatAmount(total)} mg THC total`;
        if (Number.isFinite(cbdPer) && cbdPer >= 0 && typeof computeWeedEdibleTotalCbdMg === 'function') {
            const totalCbd = computeWeedEdibleTotalCbdMg(count, cbdPer);
            text += ` · ${formatAmount(totalCbd)} mg CBD`;
        }
        preview.textContent = text;
        return;
    }
    if (Number.isFinite(count) && count > 0) {
        preview.textContent = `${formatAmount(count)} edible · Strength missing — needs review`;
        return;
    }
    preview.textContent = '—';
}

function updateBuyWeedProductTypeUI() {
    if (typeof mountBuyContactPickers === 'function') mountBuyContactPickers();
    const substanceId = document.getElementById('buy-substance')?.value;
    if (!isWeedTrackingMode(substanceId)) return;
    const productType = normalizeWeedProductType(document.getElementById('buy-weed-product-type')?.value || 'bud');
    const typeSelect = document.getElementById('buy-weed-product-type');
    if (typeSelect && typeSelect.value !== productType) typeSelect.value = productType;
    const needsCountQty = productType === 'cart' || productType === 'edibles';
    const hideQty = productType === 'bud' || productType === 'pre-rolls';

    document.getElementById('buy-weed-bud-group')?.classList.toggle('hidden', productType !== 'bud');
    document.getElementById('buy-weed-cart-group')?.classList.toggle('hidden', productType !== 'cart');
    document.getElementById('buy-weed-edibles-group')?.classList.toggle('hidden', productType !== 'edibles');
    document.getElementById('buy-weed-prerolls-group')?.classList.toggle('hidden', productType !== 'pre-rolls');
    document.getElementById('buy-weed-bud-estimates-row')?.classList.toggle('hidden', productType !== 'bud');
    document.getElementById('buy-cart-starting-group')?.classList.toggle('hidden', productType !== 'cart');
    document.getElementById('buy-quantity-group')?.classList.toggle('hidden', hideQty);

    // Product type owns the unit — never show the generic Unit dropdown for Weed/THC.
    const unitGroup = document.getElementById('buy-unit-group');
    unitGroup?.classList.add('hidden');
    const unitSelect = document.getElementById('buy-unit');
    if (unitSelect) {
        unitSelect.required = false;
        setBuyUnitSelectNormalizedValue(getWeedBuyNormalizedUnit(productType));
    }

    const qtyInput = document.getElementById('buy-quantity');
    const qtyLabel = document.getElementById('buy-quantity-label');
    if (qtyInput) {
        qtyInput.required = needsCountQty;
        if (productType === 'edibles' || productType === 'cart') {
            qtyInput.step = productType === 'edibles' ? '0.01' : '1';
            qtyInput.min = '0';
        }
    }
    if (qtyLabel) {
        if (productType === 'edibles') qtyLabel.textContent = 'Total edible count';
        else if (productType === 'cart') qtyLabel.textContent = 'Cart count';
        else if (productType === 'bud') qtyLabel.textContent = 'Bud grams';
        else if (productType === 'pre-rolls') qtyLabel.textContent = 'Pre-roll count';
        else qtyLabel.textContent = 'Quantity Bought';
    }

    updateBuyWeedPreRollPreview();
    updateBuyWeedEdiblesPreview();
    updateBuyCostPerUnitPreview();
}

function updateBuyVapeFieldsVisibility() {
    const substanceId = document.getElementById('buy-substance')?.value;
    const isNicotine = isNicotineTrackingMode(substanceId);
    const isVape = isNicotine ? getBuyFormNicotineProductType() === 'vape' : isVapeTrackingMode(substanceId);
    const isAlcohol = isAlcoholTrackingMode(substanceId);
    const isWeed = isWeedTrackingMode(substanceId);
    const isCigarettes = isNicotine ? getBuyFormNicotineProductType() === 'cigarettes' : isCigarettesTrackingMode(substanceId);
    const isLsd = isLsdSubstanceId(substanceId);
    const isXanax = isXanaxSubstanceId(substanceId);
    document.getElementById('buy-nicotine-fields-group')?.classList.toggle('hidden', !isNicotine);
    document.getElementById('buy-vape-percent-group')?.classList.toggle('hidden', !isVape);
    document.getElementById('buy-vape-liquid-group')?.classList.toggle('hidden', !isVape);
    document.getElementById('buy-vape-flavor-group')?.classList.toggle('hidden', !isVape);
    document.getElementById('buy-alcohol-fields-group')?.classList.toggle('hidden', !isAlcohol);
    document.getElementById('buy-weed-fields-group')?.classList.toggle('hidden', !isWeed);
    document.getElementById('buy-cigarettes-fields-group')?.classList.toggle('hidden', !isCigarettes);
    document.getElementById('buy-pouches-fields-group')?.classList.toggle('hidden', !isNicotine || getBuyFormNicotineProductType() !== 'pouches');
    document.getElementById('buy-gum-fields-group')?.classList.toggle('hidden', !isNicotine || getBuyFormNicotineProductType() !== 'gum');
    document.getElementById('buy-patches-fields-group')?.classList.toggle('hidden', !isNicotine || getBuyFormNicotineProductType() !== 'patches');
    document.getElementById('buy-lsd-fields-group')?.classList.toggle('hidden', !isLsd);
    document.getElementById('buy-xanax-fields-group')?.classList.toggle('hidden', !isXanax);
    document.getElementById('buy-unit-group')?.classList.toggle('hidden', isLsd || isXanax || isNicotine || isWeed);
    const unitSelect = document.getElementById('buy-unit');
    if (unitSelect) {
        unitSelect.required = !(isLsd || isXanax || isNicotine || isWeed);
    }
    document.getElementById('buy-time-group')?.classList.toggle('hidden', isVape);
    if (!isWeed && !isNicotine) {
        document.getElementById('buy-quantity-group')?.classList.remove('hidden');
        const qtyInput = document.getElementById('buy-quantity');
        if (qtyInput) qtyInput.required = true;
    }
    const qtyLabel = document.getElementById('buy-quantity-label');
    const primaryUnit = getSubstancePrimaryUnit(substanceId);
    if (qtyLabel && !isWeed && !isNicotine) {
        qtyLabel.textContent = isVape
            ? 'Puff count at 100%'
            : (isLsd
                ? 'Quantity (tabs)'
                : (isXanax
                    ? 'Quantity of pills'
                    : (primaryUnit && primaryUnit !== 'units'
                        ? `Quantity (${primaryUnit})`
                        : 'Quantity Bought')));
    }
    if (isNicotine) updateBuyNicotineProductTypeUI();
    else if (isVape) updateBuyVapeFieldsPreview();
    if (isAlcohol) updateBuyAlcoholPreview();
    if (isWeed) updateBuyWeedProductTypeUI();
    if (isLsd) updateBuyLsdPreview();
    if (isXanax) updateBuyXanaxPreview();
}

function setBuyFormSubmitLabel(text) {
    const btn = document.getElementById('buy-submit-btn');
    if (btn) btn.textContent = text;
}

function setupBuyTrackerForm() {
    const form = document.getElementById('buy-form');
    if (!form) return;
    form.addEventListener('submit', handleBuySubmit);
    setDefaultBuyDateTime();
    populateBuyStoreDropdown();
    updateBuyVapeFieldsVisibility();
    setBuyAcquisitionType('purchased');
    ['buy-quantity', 'buy-total-cost'].forEach(id => {
        document.getElementById(id)?.addEventListener('input', () => {
            updateBuyCostPerUnitPreview();
            updateBuyVapeFieldsPreview();
        });
    });
    document.getElementById('buy-percent-bought')?.addEventListener('input', updateBuyVapeFieldsPreview);
    ['buy-eliquid-capacity', 'buy-nicotine-strength'].forEach(id => {
        document.getElementById(id)?.addEventListener('input', updateBuyVapeNicotinePreview);
    });
    ['buy-alcohol-percent', 'buy-net-volume-ml'].forEach(id => {
        document.getElementById(id)?.addEventListener('input', updateBuyAlcoholPreview);
    });
    document.getElementById('buy-weed-product-type')?.addEventListener('change', updateBuyWeedProductTypeUI);
    ['buy-quantity', 'buy-edibles-mg'].forEach(id => {
        document.getElementById(id)?.addEventListener('input', () => {
            updateBuyWeedEdiblesPreview();
            updateBuyCostPerUnitPreview();
        });
    });
    document.getElementById('buy-nicotine-product-type')?.addEventListener('change', updateBuyNicotineProductTypeUI);
    ['buy-cigarette-pack-count', 'buy-cigarette-count', 'buy-cigarettes-per-pack', 'buy-cigarette-nicotine-mg',
        'buy-pouch-container-count', 'buy-pouches-per-container', 'buy-pouch-mg-per',
        'buy-gum-piece-count', 'buy-gum-mg-per-piece', 'buy-patch-count', 'buy-patch-mg-per', 'buy-patch-duration-hours']
        .forEach(id => {
            document.getElementById(id)?.addEventListener('input', () => {
                updateBuyNicotineProductTypeUI();
                updateBuyCostPerUnitPreview();
            });
        });
    ['buy-preroll-count', 'buy-grams-per-preroll'].forEach(id => {
        document.getElementById(id)?.addEventListener('input', () => {
            updateBuyWeedPreRollPreview();
            updateBuyCostPerUnitPreview();
        });
    });
    document.getElementById('buy-bud-grams')?.addEventListener('input', updateBuyCostPerUnitPreview);
    ['buy-quantity', 'buy-ug-per-tab', 'buy-total-cost'].forEach(id => {
        document.getElementById(id)?.addEventListener('input', () => {
            updateBuyLsdPreview();
            updateBuyCostPerUnitPreview();
        });
    });
    ['buy-quantity', 'buy-strength-per-pill', 'buy-strength-unit', 'buy-total-cost'].forEach(id => {
        document.getElementById(id)?.addEventListener('input', () => {
            updateBuyXanaxPreview();
            updateBuyCostPerUnitPreview();
        });
    });
    document.getElementById('buy-strength-unit')?.addEventListener('change', () => {
        updateBuyXanaxPreview();
        updateBuyCostPerUnitPreview();
    });
    document.getElementById('buy-substance')?.addEventListener('change', updateBuyUnitDropdown);
    document.getElementById('buy-store-select')?.addEventListener('change', onBuyStoreSelectChange);
}

function buildPurchaseFromForm() {
    const quantity = parseFloat(document.getElementById('buy-quantity')?.value);
    const acquisitionType = getBuyFormAcquisitionType();
    const isNonPurchase = acquisitionType === 'gift_received' || acquisitionType === 'other_adjustment';
    const isPurchasedAsGift = acquisitionType === 'purchased_as_gift';
    const totalCostRaw = parseFloat(document.getElementById('buy-total-cost')?.value);
    const totalCost = isNonPurchase ? 0 : (Number.isFinite(totalCostRaw) ? totalCostRaw : 0);
    const substanceId = document.getElementById('buy-substance')?.value;
    const sub = getSubstance(substanceId);
    const qty = Number.isFinite(quantity) ? quantity : 0;
    const unit = document.getElementById('buy-unit')?.value || 'units';
    const productType = isNicotineTrackingMode(substanceId) ? getBuyFormNicotineProductType() : null;
    const isVape = productType === 'vape'
        || (!isNicotineTrackingMode(substanceId) && isVapeTrackingMode(substanceId) && isVapePuffUnit(unit));
    const giftSourceSel = typeof getContactPickerSelection === 'function'
        ? getContactPickerSelection('buy-gift-source')
        : { contactId: '', name: (document.getElementById('buy-gift-source')?.value || '').trim() };
    const giftRecipientSel = typeof getContactPickerSelection === 'function'
        ? getContactPickerSelection('buy-gift-recipient')
        : { contactId: '', name: (document.getElementById('buy-gift-recipient')?.value || '').trim() };
    const supplierSel = typeof getContactPickerSelection === 'function'
        ? getContactPickerSelection('buy-supplier-contact')
        : { contactId: '', name: '' };
    const giftSource = acquisitionType === 'gift_received' ? (giftSourceSel.name || '').trim() : '';
    const giftRecipient = isPurchasedAsGift ? (giftRecipientSel.name || '').trim() : '';
    const giftDate = isPurchasedAsGift
        ? (document.getElementById('buy-gift-date')?.value || '').trim()
        : '';
    const payload = {
        substanceId,
        substanceName: sub?.name || '',
        trackingMode: isNicotineTrackingMode(substanceId) ? 'nicotine' : getSubstanceTrackingMode(substanceId),
        date: document.getElementById('buy-date')?.value,
        time: isVape ? '12:00' : (document.getElementById('buy-time')?.value || '12:00'),
        quantityBought: qty,
        quantity: qty,
        unit,
        totalCost,
        costPerUnit: qty > 0 ? totalCost / qty : 0,
        store: acquisitionType === 'gift_received' ? '' : getBuyFormStoreValue(),
        paymentMethod: isNonPurchase ? '' : (document.getElementById('buy-payment')?.value || ''),
        notes: document.getElementById('buy-notes')?.value || '',
        acquisitionType,
        giftSource,
        giftRecipient,
        giftDate,
        giftSourceContactId: acquisitionType === 'gift_received' ? (giftSourceSel.contactId || '') : '',
        giftRecipientContactId: isPurchasedAsGift ? (giftRecipientSel.contactId || '') : '',
        supplierContactId: acquisitionType !== 'gift_received' && supplierSel.contactId ? supplierSel.contactId : '',
        isGiftReceived: acquisitionType === 'gift_received',
        isPurchasedAsGift
    };
    if (typeof applyBuyContactIdsToPayload === 'function') applyBuyContactIdsToPayload(payload);
    if (acquisitionType !== 'purchased') payload.source = acquisitionType;
    if (acquisitionType === 'gift_received' && giftSource) {
        payload.giverName = giftSource;
        payload.giftPartyName = giftSource;
    }
    if (isPurchasedAsGift && giftRecipient) {
        payload.recipientName = giftRecipient;
        payload.giftPartyName = giftRecipient;
    }
    if (isVape) {
        const percentRaw = parseFloat(document.getElementById('buy-percent-bought')?.value);
        const percentBoughtAt = Number.isFinite(percentRaw) ? Math.max(0, Math.min(100, percentRaw)) : 100;
        const giftReceivedUnknownFullCount = acquisitionType === 'gift_received' && !(qty > 0);
        const fullPuffCount = giftReceivedUnknownFullCount ? null : qty;
        const startingPuffsLeft = fullPuffCount != null ? computeVapeStartingPuffsFromForm(fullPuffCount, percentBoughtAt) : null;
        if (giftReceivedUnknownFullCount) {
            payload.quantityBought = null;
            payload.quantity = null;
        }
        payload.fullPuffCount = fullPuffCount;
        payload.percentBoughtAt = percentBoughtAt;
        payload.startingPercent = percentBoughtAt;
        payload.remainingPercent = percentBoughtAt;
        payload.startingPuffsLeft = startingPuffsLeft;
        payload.remainingAmount = startingPuffsLeft;
        payload.remainingPuffs = startingPuffsLeft;
        const nicotine = parseVapeNicotineFieldsFromForm();
        payload.eLiquidCapacityMl = nicotine.eLiquidCapacityMl;
        payload.nicotineMgPerMl = nicotine.nicotineMgPerMl;
        payload.totalNicotineMg = nicotine.totalNicotineMg;
        payload.flavor = parseVapeFlavorFromForm();
        payload.supplyStartedAt = null;
        payload.startedAt = null;
        payload.finishedAt = null;
        payload.costPerUnit = totalCost;
    }
    if (isAlcoholTrackingMode(substanceId)) {
        applyAlcoholFieldsToPayload(payload, parseAlcoholFieldsFromForm());
    }
    if (isWeedTrackingMode(substanceId)) {
        const weedFields = parseWeedFieldsFromForm();
        applyWeedFieldsToPayload(payload, weedFields);
        applyWeedQuantityFromFields(payload, weedFields, payload.totalCost);
        if (normalizeWeedProductType(weedFields.weedProductType) === 'edibles') {
            syncWeedEdiblePurchaseFields(payload, payload.totalCost);
        }
    }
    if (isNicotineTrackingMode(substanceId)) {
        const productType = getBuyFormNicotineProductType();
        payload.nicotineProductType = productType;
        if (productType === 'cigarettes') {
            const cigFields = parseCigaretteFieldsFromForm();
            applyCigaretteFieldsToPayload(payload, cigFields);
            if (cigFields.totalCigarettes != null) {
                payload.costPerUnit = cigFields.totalCigarettes > 0 ? payload.totalCost / cigFields.totalCigarettes : 0;
                if (cigFields.packCount != null && cigFields.packCount > 0) {
                    payload.costPerPack = payload.totalCost / cigFields.packCount;
                }
            }
        } else if (productType === 'pouches') {
            const pouchFields = parseNicotinePouchesFieldsFromForm();
            applyNicotinePouchesFieldsToPayload(payload, pouchFields);
            if (pouchFields.totalPouches != null) {
                payload.costPerUnit = pouchFields.totalPouches > 0 ? payload.totalCost / pouchFields.totalPouches : 0;
                payload.costPerPouch = payload.costPerUnit;
            }
        } else if (productType === 'gum') {
            const gumFields = parseNicotineGumFieldsFromForm();
            applyNicotineGumFieldsToPayload(payload, gumFields);
            if (gumFields.pieceCount != null) {
                payload.costPerUnit = gumFields.pieceCount > 0 ? payload.totalCost / gumFields.pieceCount : 0;
                payload.costPerPiece = payload.costPerUnit;
            }
        } else if (productType === 'patches') {
            const patchFields = parseNicotinePatchesFieldsFromForm();
            applyNicotinePatchesFieldsToPayload(payload, patchFields);
            if (patchFields.patchCount != null) {
                payload.costPerUnit = patchFields.patchCount > 0 ? payload.totalCost / patchFields.patchCount : 0;
                payload.costPerPatch = payload.costPerUnit;
            }
        }
    } else if (isCigarettesTrackingMode(substanceId)) {
        applyCigaretteFieldsToPayload(payload, parseCigaretteFieldsFromForm());
    }
    if (isLsdSubstanceId(substanceId)) {
        const lsdFields = parseLsdFieldsFromForm();
        applyLsdFieldsToPayload(payload, lsdFields, payload.totalCost);
    }
    if (isXanaxSubstanceId(substanceId)) {
        const xanaxFields = parseXanaxFieldsFromForm();
        applyXanaxFieldsToPayload(payload, xanaxFields, payload.totalCost);
    }
    if (isVape) {
        payload.nicotineProductType = 'vape';
    }
    syncPurchaseAcquisitionFields(payload);
    stripIrrelevantPurchaseFields(payload);
    return payload;
}

function finalizeNewPurchaseRecord(payload) {
    const now = new Date().toISOString();
    const isVape = isVapeTrackingMode(payload.substanceId) && isVapePuffUnit(payload.unit);
    const isPurchasedAsGift = normalizePurchaseAcquisitionType(payload?.acquisitionType, payload) === 'purchased_as_gift';
    const isGiftReceivedVapeWithoutCount = normalizePurchaseAcquisitionType(payload?.acquisitionType, payload) === 'gift_received'
        && isVape
        && !(parseFloat(payload.fullPuffCount) > 0);
    const giftPercent = Number.isFinite(parseFloat(payload.startingPercent ?? payload.remainingPercent ?? payload.percentBoughtAt))
        ? Math.max(0, Math.min(100, parseFloat(payload.startingPercent ?? payload.remainingPercent ?? payload.percentBoughtAt)))
        : 100;
    const record = {
        ...payload,
        remainingAmount: isPurchasedAsGift
            ? 0
            : (isGiftReceivedVapeWithoutCount
                ? null
                : (isVape
                ? (payload.startingPuffsLeft ?? payload.remainingAmount ?? 0)
                : (payload.quantityBought ?? payload.quantity ?? 0))),
        isDepleted: isPurchasedAsGift || (isGiftReceivedVapeWithoutCount && giftPercent <= 0),
        createdAt: now,
        updatedAt: now
    };
    if (isVape) {
        record.fullPuffCount = payload.fullPuffCount ?? (isGiftReceivedVapeWithoutCount ? null : payload.quantityBought);
        record.percentBoughtAt = payload.percentBoughtAt ?? giftPercent;
        record.startingPercent = payload.startingPercent ?? record.percentBoughtAt;
        record.remainingPercent = payload.remainingPercent ?? record.percentBoughtAt;
        record.startingPuffsLeft = payload.startingPuffsLeft ?? (isPurchasedAsGift || isGiftReceivedVapeWithoutCount ? null : record.remainingAmount);
        record.remainingPuffs = isPurchasedAsGift || isGiftReceivedVapeWithoutCount ? null : (payload.remainingPuffs ?? record.remainingAmount);
        if (payload.eLiquidCapacityMl != null) record.eLiquidCapacityMl = payload.eLiquidCapacityMl;
        if (payload.nicotineMgPerMl != null) record.nicotineMgPerMl = payload.nicotineMgPerMl;
        if (payload.totalNicotineMg != null) record.totalNicotineMg = payload.totalNicotineMg;
        syncVapeNicotineFields(record);
        record.supplyStartedAt = null;
        record.startedAt = null;
        record.finishedAt = null;
    }
    if (isLsdPurchase(record)) {
        syncLsdPurchaseFields(record, parseFloat(getPurchaseTotalCost(record)) || 0);
    }
    if (isXanaxPurchase(record)) {
        syncXanaxPurchaseFields(record, parseFloat(getPurchaseTotalCost(record)) || 0);
    }
    record.inventoryStatus = isPurchasedAsGift ? 'gifted' : 'active';
    record.inventoryHidden = false;
    syncPurchaseAcquisitionFields(record);
    applyPurchasedAsGiftInventoryState(record);
    stripIrrelevantPurchaseFields(record);
    return record;
}

function applyPurchaseQuantityEdit(existing, newQty, options = {}) {
    if (isVapePuffPurchase(existing)) {
        const full = newQty;
        const pct = options.percentBoughtAt ?? getVapePercentBoughtAt(existing);
        const newStarting = computeVapeStartingPuffsFromForm(full, pct);
        existing.fullPuffCount = full;
        existing.quantityBought = full;
        existing.quantity = full;
        existing.percentBoughtAt = pct;
        existing.startingPuffsLeft = newStarting;
        if (options.eLiquidCapacityMl !== undefined) {
            if (options.eLiquidCapacityMl != null) existing.eLiquidCapacityMl = options.eLiquidCapacityMl;
            else delete existing.eLiquidCapacityMl;
        }
        if (options.nicotineMgPerMl !== undefined) {
            if (options.nicotineMgPerMl != null) existing.nicotineMgPerMl = options.nicotineMgPerMl;
            else delete existing.nicotineMgPerMl;
        }
        syncVapeNicotineFields(existing);
        recalculateVapePurchaseInventory(existing.id);
        syncVapePurchaseCostPerUnit(existing);
        existing.updatedAt = new Date().toISOString();
        if (purchaseIsPurchasedAsGift(existing)) applyPurchasedAsGiftInventoryState(existing);
        return;
    }
    if (isLsdPurchase(existing)) {
        const usedUg = Math.max(0, getPurchaseQuantityBought(existing) - getPurchaseRemainingAmount(existing));
        const newTotalUg = newQty;
        existing.totalUg = newTotalUg;
        existing.quantityBought = newTotalUg;
        existing.quantity = newTotalUg;
        existing.unit = 'ug';
        existing.remainingAmount = Math.max(0, newTotalUg - usedUg);
        if (options.quantityTabs != null) existing.quantityTabs = options.quantityTabs;
        if (options.ugPerTab != null) existing.ugPerTab = options.ugPerTab;
        syncLsdPurchaseFields(existing);
        existing.isDepleted = existing.remainingAmount <= INVENTORY_EPS;
        existing.updatedAt = new Date().toISOString();
        if (purchaseIsPurchasedAsGift(existing)) applyPurchasedAsGiftInventoryState(existing);
        return;
    }
    if (isXanaxPurchase(existing)) {
        const usedPills = Math.max(0, getXanaxPillQuantity(existing) - getXanaxRemainingPills(existing));
        const newPillQty = newQty;
        existing.pillQuantity = newPillQty;
        existing.quantityBought = newPillQty;
        existing.quantity = newPillQty;
        existing.unit = 'pills';
        existing.remainingAmount = Math.max(0, newPillQty - usedPills);
        if (options.strengthPerPill != null) existing.strengthPerPill = options.strengthPerPill;
        if (options.strengthUnit != null) existing.strengthUnit = options.strengthUnit;
        existing.needsStrengthInfo = !(existing.strengthPerPill > 0);
        syncXanaxPurchaseFields(existing);
        existing.isDepleted = existing.remainingAmount <= INVENTORY_EPS;
        existing.updatedAt = new Date().toISOString();
        if (purchaseIsPurchasedAsGift(existing)) applyPurchasedAsGiftInventoryState(existing);
        return;
    }
    const used = getPurchaseQuantityBought(existing) - getPurchaseRemainingAmount(existing);
    const remaining = Math.max(0, newQty - used);
    existing.quantityBought = newQty;
    existing.quantity = newQty;
    existing.remainingAmount = remaining;
    existing.isDepleted = remaining <= 0;
    if (newQty > 0) {
        const total = parseFloat(getPurchaseTotalCost(existing)) || 0;
        existing.costPerUnit = total / newQty;
    }
    existing.updatedAt = new Date().toISOString();
    if (purchaseIsPurchasedAsGift(existing)) applyPurchasedAsGiftInventoryState(existing);
}

